window.PACK={"book":{"id":"diwan-maarri","title":"ديوان أبو العلاء المعري","type":"diwan","author":"أبو العلاء المعري (ت ٤٤٩هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"f449606333b9"},"items":[{"id":"diwan-maarri:1","bookId":"diwan-maarri","type":"poem","seq":1,"chapter":"قصائد","title":"إياك والخمر، فهي خالبة،","page":"","text":"إياك والخمر، فهي خالبة، … غالبة، خاب ذلك الغلب\nخابية الراح ناقة حفلت، … ليس لها، غير باطل، حلب\nأشأم من ناقة البسوس على النا … س، وإن ينل عندها الطلب\nيا صال، خف إن حلبت درتها، … أن يترامى بدائها حلب\nأفضل مما تضم أكؤسها، … ما ضمنته العساس والعلب"},{"id":"diwan-maarri:2","bookId":"diwan-maarri","type":"poem","seq":2,"chapter":"قصائد","title":"من لي أن أقيم في بلد،","page":"","text":"من لي أن أقيم في بلد، … أذكر فيه بغير ما يجب\nيظن بي اليسر والديانة والعل … لم، وبيني وبينها حجب\nكل شهوري علي واحدة، … لا صفر يتقى ولا رجب\nأقررت بالجهل، وادعى فهمي … قوم، فأمري وأمرهم عجب\nوالحق أني وأنهم هدر، … لست نجيبا، ولا هم نجب\nوالحال ضاقت عن ضمها جسدي؛ … فكيف لي أن يضمه الشجب؟\nما أوسع الموت، يستريح به الجس … م المعنى، ويخفت اللجب"},{"id":"diwan-maarri:3","bookId":"diwan-maarri","type":"poem","seq":3,"chapter":"قصائد","title":"ما الثريا عنقود كرم ملاح","page":"","text":"ما الثريا عنقود كرم ملاح … ي، ولا الليل يانع غربيب\nونأى عن مدامة، شفق التغ … ريب، فليتق المليك اللبيب\nطال ليل، كأنما قتل العق … رب ساط، فغاب عنها الدبيب\nسلك النجد، في قطار المنايا، … قطري، ونجدة، وشبيب\nشب فكر الحصيف نارا فما يح … سنن، يوما، بعاقل، تشبيب\nأين بقراط، والمقلد جالي … نوس؟ هيهات أن يعيش طبيب\nسبب الرزق للأنام، فما يق … طع، بالعجز، ذلك التسبيب\nوجرى الحتف بالقضاء، فما يس … لم ليث، ولا غزال ربيب\nيطلع الوافد المبغض، والعي … ش، إلى هذه النفوس، حبيب\nخببتها عليه نكد الرزايا، … فنبا، عن قلوبها، التخبيب"},{"id":"diwan-maarri:4","bookId":"diwan-maarri","type":"poem","seq":4,"chapter":"قصائد","title":"أطل صليب الدلو، بين نجومه،","page":"","text":"أطل صليب الدلو، بين نجومه، … يكف رجالا عن عبادتها الصلبا\nفربكم الله الذي خلق السهى، … وأبدى الثريا، والسماكين، والقلبا\nوأنحل بدر التم، بعد كماله، … كأن به الظلماء قاصمة قلبا\nوأدنى رشاء للعراقي، ولم يكن … شريعا، إذا نص البيان، ولا خلبا\nوصور ليث الشب في مستقره، … ولوشاء أمسى، فوق غبرائه، كلبا\nوألقى على الأرض الفراقد، فارتعت … مع الفرقد الوحشي، ترتقب الألبا\nوأهبط منها الثور، يكرب جاهدا، … فتعلق، ظلفيه، الشوابك، والهلبا\nوأضحت نعام الجو، بعد سموها، … سدى في نعام الدو، لا تأمن الغلبا\nوأنزل حوتا في السماء، فضمه … إلى النون في خضراء، فاعترف السلبا\nوأسكن في سك من الترب ضيق، … نجوم دجى في شبوة أبت الثلبا"},{"id":"diwan-maarri:5","bookId":"diwan-maarri","type":"poem","seq":5,"chapter":"قصائد","title":"رأيت قضاء الله أوجب خلقه،","page":"","text":"رأيت قضاء الله أوجب خلقه، … وعاد عليهم في تصرفه سلبا\nوقد غلب الأحياء، في كل وجهة، … هواهم، وإن كانوا غطارفة غلبا\nكلاب تغاوت، أو تعاوت، لجيفة، … وأحسبني أصبحت ألأمها كلبا\nأبينا سوى غش الصدور، وإنما … ينال، ثواب الله، أسلمنا قلبا\nوأي بني الأيام يحمد قائل، … ومن جرب الأقوام أوسعهم ثلبا"},{"id":"diwan-maarri:6","bookId":"diwan-maarri","type":"poem","seq":6,"chapter":"قصائد","title":"إذا كف صل أفعوان، فما له","page":"","text":"إذا كف صل أفعوان، فما له … سوى بيته، يقتات ما عمر التربا\nولو ذهبت عينا هزبر مساور، … لما راع ضأنا، في المراتع، أو سربا\nأو التمعت أنوار عمرو وعامر، … لما حملا رمحا، ولا شهدا حربا\nيقولون: هلا تشهد الجمع، التي … رجونا بها عفوا، من الله، أو قربا\nوهل لي خير في الحضور، وإنما … أزاحم، من أخيارهم، إبلا جربا\nلعمري لقد شاهدت عجما كثيرة، … وعربا، فلا عجما حمدت، ولا عربا\nوللموت كأس تكره النفس شربها، … ولا بد يوما أن نكون لها شربا\nمن السعد، في دنياك، أن يهلك الفتى … بهيجاء، يغشى أهلها الطعن والضربا\nفإن قبيحا، بالمسود، ضجعة … على فرشه، يشكو إلى النفر الكربا\nولي شرق بالحتف، ما هو مغرب، … أيممت شرقا، في المسالك، أم غربا\nتقنص، في الإيوان، أملاك فارس، … وكم جاز بحرا، دون قيصر، أو دربا"},{"id":"diwan-maarri:7","bookId":"diwan-maarri","type":"poem","seq":7,"chapter":"قصائد","title":"إذا كان رعبي يورث الأمن، فهو لي","page":"","text":"إذا كان رعبي يورث الأمن، فهو لي … أسر من الأمن، الذي يورث الرعبا\nألم تر أن الهاشميين بلغوا … عظام المساعي، بعدما سكنوا الشعبا\nوكان الفتى، كعب، تخير للسرى، … أخا النمر، فاستدنى إلى أجل كعبا\nوإني رأيت الصعب يركب دائما … من الناس، من لم يركب الغرض الصعبا"},{"id":"diwan-maarri:8","bookId":"diwan-maarri","type":"poem","seq":8,"chapter":"قصائد","title":"إذا شئت أن يرضى سجاياك ربها،","page":"","text":"إذا شئت أن يرضى سجاياك ربها، … فلا تمس من فعل المقادير مغضبا\nفإن قرون الخيل أولتك ناطحا؛ … وإن الحسام العضب لقاك أعضبا\nخضبت بياضا بالصبيب، صبابة، … ببيضاء عدتك البنان المخضبا\nوما كان حبل العيش إلا معلقا … بعروة أيام الصبا، فتقضبا"},{"id":"diwan-maarri:9","bookId":"diwan-maarri","type":"poem","seq":9,"chapter":"قصائد","title":"لعمرك! ما غادرت مطلع هضبة،","page":"","text":"لعمرك! ما غادرت مطلع هضبة، … من الفكر، إلا وارتقيت هضابها\nأقل الذي تجني الغواني تبرج، … يري العين منها حليها وخضابها\nفإن أنت عاشرت الكعاب فصادها، … وحاول رضاها، واحذرن غضابها\nفكم بكرت تسقي الأمر حليلها … من الغار، إذ تسقي الخليل رضابها\nوإن حبال العيش، ما علقت بها … يد الحي، إلا وهي تخشى انقضابها"},{"id":"diwan-maarri:10","bookId":"diwan-maarri","type":"poem","seq":10,"chapter":"قصائد","title":"إذا ما عراكم حادث، فتحدثوا!","page":"","text":"إذا ما عراكم حادث، فتحدثوا! … فإن حديث القوم ينسي المصائبا\nوحيدوا عن الأشياء خيفة غيها؛ … فلم تجعل اللذات إلا نصائبا\nوما زالت الأيام، وهي غوافل، … تسدد سهما، للمنية، صائبا"},{"id":"diwan-maarri:11","bookId":"diwan-maarri","type":"poem","seq":11,"chapter":"قصائد","title":"الله لا ريب فيه، وهو محتجب،","page":"","text":"الله لا ريب فيه، وهو محتجب، … باد، وكل إلى طبع له جذبا\nأهل الحياة، كإخوان الممات، فأه … ون بالكماة أطالوا السمر والعذبا\nلا يعلم الشري ما ألقى مرارته … إليه، والأري لم يشعر، وقد عذبا\nسألتموني، فأعيتني إجابتكم؛ … من ادعى أنه دار فقد كذبا"},{"id":"diwan-maarri:12","bookId":"diwan-maarri","type":"poem","seq":12,"chapter":"قصائد","title":"إن يصحب الروح عقلي، بعد مظعنها","page":"","text":"إن يصحب الروح عقلي، بعد مظعنها … للموت، عني فأجدر أن ترى عجبا\nوإن مضت في الهواء الرحب هالكة، … هلاك جسمي في تربي، فواشجبا!\nالدين إنصافك الأقوام كلهم، … وأي دين لآبي الحق إن وجبا؟\nوالمرء يعييه قود النفس، مصبحة … للخير، وهو يقود العسكر اللجبا\nوصومه الشهر، ما لم يجن معصيتة، … يغنيه عن صومه شعبان، أو رجبا\nوما اتبعت نجيبا في شمائله، … وفي الحمام تبعت السادة النجبا\nواحذر دعاء ظليم في نعامته؛ … فرب دعوة داع تخرق الحجبا"},{"id":"diwan-maarri:13","bookId":"diwan-maarri","type":"poem","seq":13,"chapter":"قصائد","title":"لا تفرحن بفأل، إن سمعت به؛","page":"","text":"لا تفرحن بفأل، إن سمعت به؛ … ولا تطير، إذا ما ناعب نعبا\nفالخطب أفظع من سراء تأملها؛ … والأمر أيسر من أن تضمر الرعبا\nإذا تفكرت فكرا، لا يمازجه … فساد عقل صحيح، هان ما صعبا\nفاللب إن صح أعطى النفس فترتها، … حتى تموت، وسمى جدها لعبا\nوما الغواني الغوادي، في ملاعبها، … إلا خيالات وقت، أشبهت لعبا\nزيادة الجسم عنت جسم حامله … إلى التراب، وزادت حافرا تعبا"},{"id":"diwan-maarri:14","bookId":"diwan-maarri","type":"poem","seq":14,"chapter":"قصائد","title":"لو كنتم أهل صفو قال ناسبكم:","page":"","text":"لو كنتم أهل صفو قال ناسبكم: … صفوية، فأتى باللفظ ما قلبا\nجند لإبليس في بدليس، آونة؛ … وتارة يحلبون العيش في حلبا\nطلبتم الزاد في الآفاق من طمع، … والله يوجد حقا أينما طلبا\nولست أعنى بهذا غير فاجركم؛ … إن التقي، إذا زاحمته، غلبا\nكالشمس لم يدن من أضوائها دنس، … والبدر قد جل عن ذم، وإن ثلبا\nوما أرى كل قوم، ضل رشدهم، … إلا نظير النصارى أعظموا الصلبا\nيا آل إسرال هل يرجى مسيحكم؛ … هيهات قد ميز الأشياء من خلبا\nقلنا: أتانا، ولم يصلب، وقولكم: … ما جاء بعد، وقالت أمة: صلبا\nجلبتم باطل التوراة، عن شحط؛ … ورب شر بعيد، للفتى، جلبا\nكم يقتل الناس، ماهم الذي عمدت … يداه للقتل، إلا أخذه السلبا\nبالخلف قام عمود الدين، طائفة … تبني الصروح، وأخرى تحفر القلبا"},{"id":"diwan-maarri:15","bookId":"diwan-maarri","type":"poem","seq":15,"chapter":"قصائد","title":"الأمر أيسر مما أنت مضمره؛","page":"","text":"الأمر أيسر مما أنت مضمره؛ … فاطرح أذاك، ويسر كل ما صعبا\nولا يسرك، إن بلغته، أمل؛ … ولا يهمك غربيب، إذا نعبا\nإن جد عالمك الأرضي، في نبأ … يغشاهم، فتصور جدهم لعبا\nما الرأي عندك في ملك تدين له … مصر، أيختار دون الراحة التعبا\nلن تستقيم أمور الناس في عصر؛ … ولا استقامت، فذا أمنا، وذا رعبا\nولا يقوم على حق بنو زمن، … من عهد آدم كانوا في الهوى شعبا"},{"id":"diwan-maarri:16","bookId":"diwan-maarri","type":"poem","seq":16,"chapter":"قصائد","title":"قد يسروا لدفين، حان مصرعه،","page":"","text":"قد يسروا لدفين، حان مصرعه، … بيتا من الخشب، لم يرفع ولا رحبا\nيا هؤلاء اتركوه والثرى، فله … أنس به، وهو أولى صاحب صحبا\nوإنما الجسم ترب، خير حالته … سقيا الغمائم، فاستسقوا له السحبا\nصار البهيج، من الأقوام، خط سفا، … وقد يراع، إذا ما وجهه شحبا\nسيان من لم يضق ذرعا بعيد ردى، … وذارع، في مغاني فتية، سحبا\nفافرق من الضحك واحذر أن تحالفه، … أما ترى الغيم لما استضحك انتحبا؟"},{"id":"diwan-maarri:17","bookId":"diwan-maarri","type":"poem","seq":17,"chapter":"قصائد","title":"من قلة اللب عند النصح أن تابا","page":"","text":"من قلة اللب عند النصح أن تابا … وأن تروم من الأيام إعتابا\nخل الزمان وأهليه لشأنهم، … وعش بدهرك، والأقوام، مرتابا\nسار الشباب، فلم نعرف له خبرا، … ولا رأينا خيالا منه منتابا\nوحق للعيس، لو نالت بنا بلدا، … فيه الصبا، كون عود الهند أقتابا\nألقى الكبير قميص الشرخ رهن بلى، … ثم استجد قميص الشيب، مجتابا\nما زال يمطل دنياه بتوبته، … حتى أتته مناياها، وما تابا\nخط استواء بدا عن نقطة عجب، … أفنت خطوطا، وأقلاما، وكتابا"},{"id":"diwan-maarri:18","bookId":"diwan-maarri","type":"poem","seq":18,"chapter":"قصائد","title":"لو كنت رائد قوم، ظاعنين إلى","page":"","text":"لو كنت رائد قوم، ظاعنين إلى … دنياك هذي، لما ألفيت كذابا\nلقلت: تلك بلاد، نبتها سقم، … وماؤها العذب سم، للفتى، ذابا\nهي العذاب، فجدوا في ترحلكم … إلى سواها، وخلوا الدار إعذابا\nوما تهذب يوم من مكارهها، … أو بعض يوم، فحثوا السير إهذابا\nخبرتكم بيقين غير مؤتشب، … ولم أكن في حبال المين جذابا"},{"id":"diwan-maarri:19","bookId":"diwan-maarri","type":"poem","seq":19,"chapter":"قصائد","title":"أثرى أخوك، فلم يسكب نوافله؛","page":"","text":"أثرى أخوك، فلم يسكب نوافله؛ … وحل رزء، فظل الدمع مسكوبا\nأما تبالي، إذا علتك غانية، … من كوبها، الراح أن أصبحت منكوبا؟\nأين الذين تولوا قبلنا فرطا، … أما تسائل عمن بان أركوبا؟"},{"id":"diwan-maarri:20","bookId":"diwan-maarri","type":"poem","seq":20,"chapter":"قصائد","title":"لو كنت يعقوب طير كنت أرشد، في","page":"","text":"لو كنت يعقوب طير كنت أرشد، في … مسعاك، من أمم تنمى ليعقوبا\nضلوا بعجل مصوغ من شنوفهم، … فاستنكروا مسمعا للشنف مثقوبا\nولن يقوم مسيح يجمعون له، … وخلت واعدهم م الخلف عرقوبا\nوإن دنياك هذا مثل قائبة، … وسوف يقطع منها ربها القوبا\nيغنيك منسوج باري تصان به، … عن بسط محكمة، من نسج قرقوبا\nفاحذر لصوص الأماني فهي سارقة … ردت عن الدين قلب المرء منقوبا"},{"id":"diwan-maarri:21","bookId":"diwan-maarri","type":"poem","seq":21,"chapter":"قصائد","title":"سرحوب! عمن سرى، لله مبتعثا","page":"","text":"سرحوب! عمن سرى، لله مبتعثا … وجناء في الكور، أو في السرح سرحوبا\nفي لاحب، لا يعود السالكون به، … مثل ابن الأبرص لما عاد ملحوبا\nأما الأنام، فقد صاحبتهم زمنا، … فما رضيت، من الخلان، مصحوبا\nلا تغشهم، كولوج الهم يطرقهم، … بالكره، بل مثل وسق الخير، مصحوبا"},{"id":"diwan-maarri:22","bookId":"diwan-maarri","type":"poem","seq":22,"chapter":"قصائد","title":"إن كنت صاحب إخوان ومائدة،","page":"","text":"إن كنت صاحب إخوان ومائدة، … فاحب الطفيلي تأهيلا وترحيبا\nلا تلقينه بتعبيس، لتوحشه، … فالزاد يفنى ولا يبقي الأصاحيبا\nيقفو اللئيم كريم القوم، مكتسبا،؛ … إن السراحين يتبعن السراحيبا"},{"id":"diwan-maarri:23","bookId":"diwan-maarri","type":"poem","seq":23,"chapter":"قصائد","title":"لم يقدر الله تهذيبا لعالمنا،","page":"","text":"لم يقدر الله تهذيبا لعالمنا، … فلا ترومن للأقوام تهذيبا\nولا تصدق بما البرهان يبطله، … فتستفيد من التصديق تكذيبا\nإن عذب الله قوما باجترامهم، … فما يريد لأهل العدل تعذيبا\nيغدو على خله الإنسان يظلمه، … كالذيب يأكل عند الغرة الذيبا"},{"id":"diwan-maarri:24","bookId":"diwan-maarri","type":"poem","seq":24,"chapter":"قصائد","title":"يا راعي المصر! ما سومت في دعة،","page":"","text":"يا راعي المصر! ما سومت في دعة، … وعرسك الشاة، فاحذر جارك الذيبا\nتروم تهذيب هذا الخلق من دنس؛ … والله ما شاء، للأقوام، تهذيبا\nوما رويت بعذب، حل قل قلب، … حتى تكلفت إعناتا وتعذيبا\nفاعرف، لصادقك الأنباء، موضعه؛ … واجز الكذوب على ما قال تكذيبا"},{"id":"diwan-maarri:25","bookId":"diwan-maarri","type":"poem","seq":25,"chapter":"قصائد","title":"يا آل غسان! أقوى منكم وطن،","page":"","text":"يا آل غسان! أقوى منكم وطن، … تغشى العفاة به الشبان والشيبا\nتسقونهم، من حليب الجفن، صافية، … ببارد، كحليب الجفن، ما شيبا"},{"id":"diwan-maarri:26","bookId":"diwan-maarri","type":"poem","seq":26,"chapter":"قصائد","title":"إن كنت يعسوب أقوام فخف قدرا،","page":"","text":"إن كنت يعسوب أقوام فخف قدرا، … ما زال كالطفل يصطاد اليعاسيبا\nوإن تكن بمنا سيب، لمهلكة، … فكم طوى الدهر أقيالا مناسيبا"},{"id":"diwan-maarri:27","bookId":"diwan-maarri","type":"poem","seq":27,"chapter":"قصائد","title":"إذا كانت لك امرأة عجوز،","page":"","text":"إذا كانت لك امرأة عجوز، … فلا تأخذ بها أبدا كعابا\nفإن كانت أقل بهاء وجه، … فأجدر أن تكون أقل عابا\nوحسن الشمس، في الأيام، باق، … وإن مجت، من الكبر، اللعابا"},{"id":"diwan-maarri:28","bookId":"diwan-maarri","type":"poem","seq":28,"chapter":"قصائد","title":"لا تكذبن، فإن فعلت، فلا تقل","page":"","text":"لا تكذبن، فإن فعلت، فلا تقل … كذبا على رب السماء، تكسبا\nفالله فرد قادر، من قبل أن … تدعى لآدم صورة، أو تحسبا\nوإذا انتسبت فقلت إني واحد … من خلقه، فكفى بذاك تنسبا\nأشباح إنس يخضبون صوارما، … تحت العجاج، ويركضون الشسبا\nويمارسون، من الظلام، غياهبا؛ … ويواصلون، فيقطعون السبسبا\nومرادهم عذب، خسيس قدره، … شربوا له مقرا، لكيما يلسبا\nولقد علمت، فما التمضر نافعي، … أني سأتبع نيسبا، لابني سبا\nسبأ المدامة، فاستدام مسرة، … فيما يظن، ولم يرع لما سبى\nروح، إذا رحلت عن الجسم الذي … سكنت به، فمآله أن يرسبا"},{"id":"diwan-maarri:29","bookId":"diwan-maarri","type":"poem","seq":29,"chapter":"قصائد","title":"لو أنني سميت طيفك صادقا،","page":"","text":"لو أنني سميت طيفك صادقا، … لدعوته غضبان، أو عتابا\nقال الخيال: كذبت لست بطارق … ليلا، ولم أك زائرا منتابا\nفأجبته: كم من كتاب زائر؛ … فاهتاج يحلف: ما بعثت كتابا\nلا تثبت الأقلام زلة راقد، … إن كنت بت بحلمه مرتابا\nلم يعف ربك عن مصر، مارد، … لكن تجاوز عن مسيء تابا"},{"id":"diwan-maarri:30","bookId":"diwan-maarri","type":"poem","seq":30,"chapter":"قصائد","title":"أتصح توبة مدرك من كونه،","page":"","text":"أتصح توبة مدرك من كونه، … أو أسود من لونه، فيتوبا\nكتب الشقاء على الفتى، في عيشه، … وليبلغن قضاءه المكتوبا\nوإذا عتبت المرء، ليس بمعتب، … ألفيت، فيما جئته، معتوبا\nيبغي المعاشر في الزمان وصرفه … رتبا، كأن لهم، عليه، رتوبا"},{"id":"diwan-maarri:31","bookId":"diwan-maarri","type":"poem","seq":31,"chapter":"قصائد","title":"عفوك للعالم لا تخلين","page":"","text":"عفوك للعالم لا تخلين … حنظبة، منه، ولا عنظبه\nلا ظبة الصارم باشرتها، … فيك، ولا زرت، لحجي، ظبه"},{"id":"diwan-maarri:32","bookId":"diwan-maarri","type":"poem","seq":32,"chapter":"قصائد","title":"قد صحبنا الزمان بالرغم منا،","page":"","text":"قد صحبنا الزمان بالرغم منا، … وهو يردي، كما علمت، الصحابا\nوحللنا المضيق، ثم أتينا الرحب، … لو دام تركنا والرحابا\nوالجسوم التراب تحيا بسقيا، … فلهذا قلنا: سقيت السحابا\nقد رضينا الشحوب لوكان صرف الده … ر يرضى، للأوجه، الإشحابا\nوضحكنا، وليس ما يوجب الضح … ك، لدينا، بل ما يهيج انتحابا\nكم أمير أمير في عاصفات، … بعدما حاب، في الحياة، وحابا"},{"id":"diwan-maarri:33","bookId":"diwan-maarri","type":"poem","seq":33,"chapter":"قصائد","title":"لا تطيعي هواك، أيتها النف","page":"","text":"لا تطيعي هواك، أيتها النف … س، فنعمى المليك فينا ربيبه\nوابن جحش، لما تنصر، لم تر … كن، إلى ما يقول، أم حبيبه\nوبلال يحكي ابن تمرة في الخفة، … أوفى من عنتر ابن زبيبه\nلا أغادي مفارقي بصبيب، … وأخلي والقفر آل صبيبه\nإن خيرا من اختراش ضباب الأر … ض، للناشىء، اتخاذ ضبيبه\nكيف أضحت شبيبة القلب حمرا … ء، وزالت من السواد الشبيبه\nفالزمي النسك إن علقت، وفري … من ذوي الجهل كي تعدي لبيبه"},{"id":"diwan-maarri:34","bookId":"diwan-maarri","type":"poem","seq":34,"chapter":"قصائد","title":"زاره حتفه، فقطب للمو","page":"","text":"زاره حتفه، فقطب للمو … ت، وألقى من بعدها التقطيبا\nزودوه طيبا، ليلحق بالنا … س، وحسب الدفين بالترب طيبا\nنام في قبره، ووسد يمنا … ه، فخلناه قام فينا خطيبا\nللمنايا حواطب لا تبالي، … أهشيما جرت لها، أم رطيبا\nصرفت كأسها، فلم تسق شربا … مرة، خالصا، وأخرى قطيبا"},{"id":"diwan-maarri:35","bookId":"diwan-maarri","type":"poem","seq":35,"chapter":"قصائد","title":"زعموا أن ما يذكر، إن قا","page":"","text":"زعموا أن ما يذكر، إن قا … رن أنثى، لم يعدم التغليبا\nباطل ذاك، إن لبي، إلى الدن … يا، قرين، وما يزال سليبا\nوالمنايا كالأسد، تفترس الأح … ياء، جمعا ولا تعاف الكليبا\nمثل ماقيل في جرير، أخي القو … ل، يصيد الكركي والعندليبا\nكم سقينا الحمام شارب ماء … ومدام، أو من يسقى حليبا\nتفرع الشامخ المنيف، من الش … م، وتهوي، فتستبيح القليبا\nقدر نازل من الجو، نادى … بالنصارى، حتى أجلوا الصليبا\nوالنجاشي صار ملك أناس، … بعدما هم أن يعد جليبا\nوالفتى كاسمه، المصرف هذا ال … جسم، يلقى التغيير والتقليبا"},{"id":"diwan-maarri:36","bookId":"diwan-maarri","type":"poem","seq":36,"chapter":"قصائد","title":"إن يقرب الموت مني","page":"","text":"إن يقرب الموت مني … فلست أكره قربه\nوذاك أمنع حصن، … يصبر القبر دربه\nمن يلقه لا يراقب … خطبا، ولا يخش كربه\nكأنني رب إبل، … أضحى يمارس جربه\nأو ناشط يتبغى، … في مقفر الأرض، عربه\nوإن رددت لأصلي، … دفنت في شر تربه\nوالوقت مامر، إلا … وحل في العمر أربه\nكل يحاذر حتفا، … وليس يعدم شربه\nويتقي الصارم العض … ب، أن يباشر غربه\nوالنزع، فوق فراش، … أشق من ألف ضربه\nواللب حارب، فينا، … طبعا يكابد حربه\nيا ساكن اللحد! عرف … ني الحمام وإربه\nولا تضن، فإني … ما لي، بذلك، دربه\nيكر في الناس كالأج … دل، المعاود سربه\nأو كالمعير، من العا … سلات، يطرق زربه\nلا ذات سرب يعري الر … دى، ولا ذات سربه\nوما أظن المنايا، … تخطو كواكب جربه\nستأخذ النسر، والغف … ر، والسماك، وتربه\nفتشن عن كل نفس … شرق الفضاء وغربه\nوزرن، عن غير بر، … عجم الأنام، وعربه\nما ومضة من عقيق، … إلا تهيج طربه\nهوى تعبد حرا، … فما يحاول هربه\nمن رامني لم يجدني، … إن المنازل غربه\nكانت مفارق جون، … كأنها ريش غربه\nثم انجلت، فعجبنا … للقار بدل صربه\nإذا خمصت قليلا، … عددت ذلك قربه\nوليس عندي، من آلة … السرى، غير قربه"},{"id":"diwan-maarri:37","bookId":"diwan-maarri","type":"poem","seq":37,"chapter":"قصائد","title":"الله ينقل من شا","page":"","text":"الله ينقل من شا … ء، رتبة بعد رتبه\nأبدى العتاهي نسكا، … وتاب من ذكر عتبه\nوالخوف ألزم سفيا … ن أن يغرق كتبه"},{"id":"diwan-maarri:38","bookId":"diwan-maarri","type":"poem","seq":38,"chapter":"قصائد","title":"كريم أناب، وما أنبا،","page":"","text":"كريم أناب، وما أنبا، … وأنساه طول المدى زينبا\nلإحدى الأرانب، في قومها، … وإن صبحت، بعدنا، أرنبا\nلها والد، بيته شامخ، … مع النسر، أو مثله طنبا\nعهدتك لا تتوقى الهجير، … ولا ترهب الأشيب، الأشنبا\nولكن لقيت صروف الزمان، … وباشرتها مقنبا، مقنبا\nإذا المرء مرت له أربعون، … فليس يعنف، إن حنبا\nوإن يفر خطبا، فأهل له، … وإلا، فكم من حسام نبا\nولا عقل للدهر، فيما أرى، … فكيف يعاتب إن أذنبا؟\nفهلا تراح لأهل الجناب، … إذا الركب، أفراسه، جنبا\nوكنت إلى وصلهم مائلا، … تعاصي العذول، وإن أطنبا"},{"id":"diwan-maarri:39","bookId":"diwan-maarri","type":"poem","seq":39,"chapter":"قصائد","title":"صحبت الحياة، فطال العناء ؛","page":"","text":"صحبت الحياة، فطال العناء ؛ … ولا خير في العيش مستصحبا\nوقد كنت فيما مضى جامحا؛ … ومن راضه دهره أصحبا\nمتى ما شحبت لوجه المليك، … كسيت جمالا بأن تشحبا\nحبا الشيخ، لا طامعا في النهوض، … نقيض الصبي، إذا ما حبا\nولم يحبني أحد نعمة؛ … ولكن مولى الموالي حبا\nنصحتك، فاعمل له دائما؛ … وإن جاء موت، فقل: مرحبا"},{"id":"diwan-maarri:40","bookId":"diwan-maarri","type":"poem","seq":40,"chapter":"قصائد","title":"يؤدبك الدهر بالحادثات،","page":"","text":"يؤدبك الدهر بالحادثات، … إذا كان شيخاك ما أدبا\nبدت فتن مثل سود الغمام، … ألقت على العالم الهيدبا\nومن دونها اختلفت غالب، … وأبعد عثمانها جندبا\nفلا تضحكن ابنة السنبسي، … فأوجب من ذاك أن تندبا\nإذا عامر تبعت صالحا، … وزجت بنو قرة الحردبا\nوأردف حسان في مائح، … متى هبطوا مخصبا أجدبا\nوإن فرعوا جبلا شامخا، … فليس يعنف أن يحدبا\nرأيت نظير الدبا كثرة، … قتيرهم كعيون الدبا"},{"id":"diwan-maarri:41","bookId":"diwan-maarri","type":"poem","seq":41,"chapter":"قصائد","title":"بني آدم بئس المعاشر أنتم،","page":"","text":"بني آدم بئس المعاشر أنتم، … وما فيكم واف لمقت، ولا حب\nوجدتكم لا تقربون إلى العلا، … كما أنكم لا تبعدون عن السب\nولم تكفكم أكباد شاء وجامل، … ووحش إلى أن رمتم كبد الضب\nفإن كان ما بين البهائم قاضيا، … فهذا قضاء جاء من قبل الرب\nركبتم سفين البحر، من فرط رغبة، … فما للمطايا والمطهمة القب\nوكلكم يبدي، لدنياه، نغصة، … على أنه يخفي بها كمد الصب\nإذا جولس الأقوام بالحق أصبحوا، … عداة، فكل الأصفياء على خب\nنشاهد بيضا من رجال، كأنهم … غرابيب طير، ساقطات على حب\nإذا طلبوا، فاقنع لتظفر بالغنى؛ … وإن نطقوا، فاصمت لترجع باللب\nوإن لم تطق هجران رهطك دائما، … فمن أدب النفس الزيارة عن غب\nويدعو الطبيب المرء، وافاه حينه؛ … رويدك! إن الأمر جل عن الطب"},{"id":"diwan-maarri:42","bookId":"diwan-maarri","type":"poem","seq":42,"chapter":"قصائد","title":"أرى اللب مرآة اللبيب، ومن يكن،","page":"","text":"أرى اللب مرآة اللبيب، ومن يكن، … مرائيه، الإخوان يصدق ويكذب\nأأخشى عذاب الله، والله عادل، … وقد عشت عيش المستضام المعذب\nنعم! إنها الأرزاق، والمرء جاهل، … يهذب، من دنياه، ما لم يهذب\nفإن حبال الشمس لسن ثوابتا، … لشد رحال، أو قوابض جذب"},{"id":"diwan-maarri:43","bookId":"diwan-maarri","type":"poem","seq":43,"chapter":"قصائد","title":"لك الملك، إن تنعم، فذاك تفضل","page":"","text":"لك الملك، إن تنعم، فذاك تفضل … علي، وإن عاقبتني، فبواجب\nيقوم الفتى من قبره، إن دعوته، … وما جر مخطوط له في الرواجب\nعصا النسك أحمى، ثم، من رمح عامر … وأشرف عند الفجر من قوس حاجب"},{"id":"diwan-maarri:44","bookId":"diwan-maarri","type":"poem","seq":44,"chapter":"قصائد","title":"عصا في يد الأعمى، يروم بها الهدى،","page":"","text":"عصا في يد الأعمى، يروم بها الهدى، … أبر له من كل خدن وصاحب\nفأوسع بني حواء هجرا، فإنهم … يسيرون في نهج من الغدر لاحب\nوإن غير الإثم الوجوه، فما ترى، … لدى الحشر، إلا كل أسود شاحب\nإذا ما أشار العقل بالرشد، جرهم، … إلى الغي، طبع أخذه أخذ ساحب"},{"id":"diwan-maarri:45","bookId":"diwan-maarri","type":"poem","seq":45,"chapter":"قصائد","title":"نهاني عقلي عن أمور كثيرة،","page":"","text":"نهاني عقلي عن أمور كثيرة، … وطبعي إليها بالغريزة جاذبي\nومما أدام الرزء تكذيب صادق، … على خبرة منا، وتصديق كاذب"},{"id":"diwan-maarri:46","bookId":"diwan-maarri","type":"poem","seq":46,"chapter":"قصائد","title":"لو اتبعوني، ويحهم، لهديتهم","page":"","text":"لو اتبعوني، ويحهم، لهديتهم … إلى الحق، أو نهج لذاك مقارب\nفقد عشت حتى ملني، ومللته، … زماني، وناجتني عيون التجارب\nإذا حان وقتي، فالمثقف طاعني، … بغير معين، والمهند ضاربي\nوإنا، من الغبراء، فوق مطية، … مذللة، ما أمكنت يد خارب\nفمن لي بأرض رحبة، لا يحلها … سواي، تضاهي دارة المتقارب\nفما للفتى إلا انفراد ووحدة، … إذا هو لم يرزق بلوغ المآرب\nفحارب وسالم، إن أردت، فإنما … أخو السلم، في الأيام، مثل محارب"},{"id":"diwan-maarri:47","bookId":"diwan-maarri","type":"poem","seq":47,"chapter":"قصائد","title":"يقولون صنع من كواكب سبعة؛","page":"","text":"يقولون صنع من كواكب سبعة؛ … وما هو إلا من زعيم الكواكب\nإذا رفعت تلك المواكب قسطلا، … فرافعه للعين مجري الكواكب\nأترجع نفس الميت، بعد رحيله، … فيجزي قوما بالدموع السواكب؟\nتبدل أعناق الرجال وأيديا، … تناقله من عسجدي المراكب\nأحب إليه كونه متواطأ … بأقدامهم، لا الحمل فوق المناكب\nهو الموت، مثر عنده مثل مقتر، … وقاصد نهج مثل آخر ناكب\nودرع الفتى، في حكمه، درع غادة، … وأبيات كسرى من بيوت العناكب\nفرجل في غبراء، والخطب فارس، … وما زال، في الأهلين، أشرف راكب\nوما النعش إلا كالسفينة راميا، … بغرقاه، في موج الردى المتراكب"},{"id":"diwan-maarri:48","bookId":"diwan-maarri","type":"poem","seq":48,"chapter":"قصائد","title":"أجل هبات الدهر ترك المواهب،","page":"","text":"أجل هبات الدهر ترك المواهب، … يمد، لما أعطاك، راحة ناهب\nوأفضل من عيش الغنى عيش فاقة، … ومن زي ملك رائق زي راهب\nوما خلته إلا سيبعث حادثا، … يحل الثريا عن جبين الغياهب\nجلا فرقديه، قبل نوح وآدم، … إلى اليوم، لما يدعيا في القراهب\nولي مذهب في هجري الإنس نافع، … إذا القوم خاضوا في اختيار المذاهب\nأرانا على الساعات فرسان غارة، … وهن بنا يجرين جري السلاهب\nومما يزيد العيش إخلاق ملبس، … تأسف نفس، لم تطق رد ذاهب"},{"id":"diwan-maarri:49","bookId":"diwan-maarri","type":"poem","seq":49,"chapter":"قصائد","title":"إذا عبت، عندي، غيري اليوم ظالما،","page":"","text":"إذا عبت، عندي، غيري اليوم ظالما، … فأنت بظلم، عند غيري، عائبي\nعرفتك، فاعلم، إن ذممت خلائقي … ورابك بعضي، أن كلك رائبي\nفأين الذي في الترب يدفن شخصه، … وأسراره مدفونة في الترائب\nيظن نبيه غائبا مثل شاهد؛ … وخامل قوم شاهدا مثل غائب\nوقد يورث، المال البعيد، مضلل، … من الناس، يأبى وضعه في القرائب\nوإن بني حواء زور عن الهدى، … ولو ضربوا بالسيف ضرب الغرائب\nومن حب دنياهم رموا في وغاهم … بغيض المنايا بالنفوس الحبائب\nوكم غوروا، في مورد وتظمىء … عيون ركي، أو عيون ركائب\nوأسروا على الخيل العتاق، وأصمتوا … نواطقها، إلا تحمحم هائب\nوشد لسان الطرف، خوف صهيله، … فقد ألجموا أفواهها بالسبائب\nوغرهم صبح الوجوه، وفوقه … جوامد ليل، سميت بالذوائب\nغرائز في شيب ومرد، بمشرق … وغرب، جرت مجرى الصبا والجنائب\nأرادت لها خضر المضارب والظبى … جلاء، فلم تبيض سود الضرائب\nيقول الفتى: أخلصت غيا ولم أرح، … وشائب فودي بالتورع شائبي"},{"id":"diwan-maarri:50","bookId":"diwan-maarri","type":"poem","seq":50,"chapter":"قصائد","title":"توخ بهجر أم ليلى، فإنها","page":"","text":"توخ بهجر أم ليلى، فإنها … عجوز، أضلت حي طسم ومارب\nدبيب نمال، عن عقار، تخالها … بجسمك، شر من دبيب العقارب\nولو أنها كالماء طلق لأوجبت، … قلاها، أصيلات النهى والتجارب\nتحيي وجوه الشرب، فعل مسالم، … يضاحكه، والكيد كيد محارب\nإذا قتلت، خاف الرشاد جناية، … فكان من الفتيان أول هارب\nعدوة لب، سلت السيف واعتلت … به القوم، إلا أنها لم تضارب\nوما شامت الهندي في الكف عنوة؛ … ولكن ثنته في أنامل ضارب\nفلو كان سرح العقل أذ واد عامر، … رمت كل ذود من سفاه بخارب\nفما أبعدت إلا أجل مقارن؛ … ولا بلغت إلا خسيس المآرب\nتعري الفتى من ثوبه، وهو غافل، … وتوقع حرب الدهر بين الأقارب\nتألى الحجا، واستشهد السكر أنها … ذميمة غب، لا تحل لشارب"},{"id":"diwan-maarri:51","bookId":"diwan-maarri","type":"poem","seq":51,"chapter":"قصائد","title":"تناهبت، العيش، النفوس، بغرة،","page":"","text":"تناهبت، العيش، النفوس، بغرة، … فإن كنت تسطيع النهاب، فناهب\nبقائي في الدنيا، علي، رزية، … وهل أنا إلا غابر مثل ذاهب؟\nإذا خلق الانسان ظل حمامه، … وإن نال يسرا، من أجل المواهب\nتقادم عمر الدهر، حتى كأنما … نجوم الليالي شيب هذي الغياهب\nيهود باغي الحاج، والليل مسلم، … على كفره، والأرض في زي راهب\nتألف غي الناس، شرقا، ومغربا، … تكامل فيهم باختلاف المذاهب\nوإن قطوف الساع، فيما علمته، … أحث مرورا من وساع السلاهب"},{"id":"diwan-maarri:52","bookId":"diwan-maarri","type":"poem","seq":52,"chapter":"قصائد","title":"متى عدد الأقوام لبا وفطنة،","page":"","text":"متى عدد الأقوام لبا وفطنة، … فلا تسأليني عنهما وسليبي\nأرى عالما يرجون عفو مليكهم، … بتقبيل ركن، واتخاذ صليب\nفغفرانك اللهم! هل أنا طارح، … بمكة، في وفد، ثياب سليبي؟\nوهل أرد الغدران، بين صحابة … يمانين، لم يبغوا احتفار قليب\nأفارقهم، ما العرض مني عندهم … ثليبا، ولا عرض لهم بثليب\nولست بلاح من أراح سوامه … إذا لم يجئني، موهنا، بحليب\nوهان على سمعي إذا القبر ضمني … هرير ضباع، حوله، وكليب\nعبيدك جم، ربنا، ولك الغنى، … ولم تك معروفا برق جليب"},{"id":"diwan-maarri:53","bookId":"diwan-maarri","type":"poem","seq":53,"chapter":"قصائد","title":"وجدت عواري الحياة كثيرة،","page":"","text":"وجدت عواري الحياة كثيرة، … كأن بقاء المرء شعر حبيب\nوتلقاه، من فرط الصبابة، جاهلا، … يغير أعلى رأسه بصبيب\nوما كرهت خيل، تخال، وأينق، … بياضا بدا في غرة وسبيب\nفإن طريق الناس في الحتف واحد … أكنت طبيبا أم نقيض طبيب"},{"id":"diwan-maarri:54","bookId":"diwan-maarri","type":"poem","seq":54,"chapter":"قصائد","title":"إذا غيبوني لم أبال متى هفا","page":"","text":"إذا غيبوني لم أبال متى هفا … نسيم شمال، أو نسيم جنوب\nتنوب الرزايا أعظمي، لا أصونها … بمتخذ من عرعر وتنوب\nفهل عاينوا، في مضجعي لجرائمي … كتائب من زنج، تروع، ونوب\nوهل يجعل الأرض التي ابيض لونها، … كلون الحرار الحمس، لون ذنوب\nيقول الثرى: كم رم تحتي للورى … وسائد هام، أو مهود جنوب\nوإني، وإن لم آت خيرا أعده، … لآمل إرواء يخير ذنوب"},{"id":"diwan-maarri:55","bookId":"diwan-maarri","type":"poem","seq":55,"chapter":"قصائد","title":"وجدتك أعطيت الشجاعة حقها،","page":"","text":"وجدتك أعطيت الشجاعة حقها، … غداة لقيت الموت غير هيوب\nإذا قرن الظن المصيب، من الفتى، … بتجربة، جاءا بعلم غيوب\nوإنك، إن أهديت لي عيب واحد، … جدير، إلى غيري، بنقل عيوبي\nوإن جيوب السرد من سبل الردى، … إذا لم يكن، من تحت، نصح جيوب"},{"id":"diwan-maarri:56","bookId":"diwan-maarri","type":"poem","seq":56,"chapter":"قصائد","title":"إذا سكت الإنسان قلت خصومه،","page":"","text":"إذا سكت الإنسان قلت خصومه، … وإن أضجعته الحادثات لجنبه\nحسا طامر، في صمته، من دم الفتى، … فصغر ذاك الصمت معظم ذنبه\nولم يك في حال البعوض، إذا شدا، … له نغم عال، وأنت أذ به\nوإن سل سيفا، من كلام، مسفه، … عليك، فقابله بصبرك تنبه"},{"id":"diwan-maarri:57","bookId":"diwan-maarri","type":"poem","seq":57,"chapter":"قصائد","title":"لقد ترفع، فوق المشتري، زحل،","page":"","text":"لقد ترفع، فوق المشتري، زحل، … فأصبح الشر فينا ظاهر الغلب\nوإن كيوان والمريخ، ما بقيا، … لا يخليانك من فجع ومن سلب\nوكم طلبت أمورا لست مدركها، … تبارك الله، من أغراك بالطلب\nأما رأيت رجالا، بعد شربهم، … في النضر، يرضون أن يسقوا من العلب\nوما أمنت زماني، في تصرفه، … أن ينقل الملك من مصر إلى حلب"},{"id":"diwan-maarri:58","bookId":"diwan-maarri","type":"poem","seq":58,"chapter":"قصائد","title":"الدهر ينسخ أولاه أواخره،","page":"","text":"الدهر ينسخ أولاه أواخره، … فلا يطيلن بهذا اللوم إنصابي\nداء الحياة قديم لا دواء له، … لم يخل بقراط من سقم وأوصاب\nتلك اليهود، فهل من هائد لهم، … والصابئون، وكل جاهل صابي\nوالأنس ما بين إكثار إلى عدم، … كالوحش ما بين إمحال وإخصاب\nلم يثبتوا بقياس أصل دينهم، … فيحكموا بين رفاض ونصاب\nما الركن في قول ناس، لست أذكرهم، … إلا بقية أوثان وأنصاب\nلا أستقيل زماني عثرة أبدا، … ما شاء فليأت، إن الشهد كالصاب"},{"id":"diwan-maarri:59","bookId":"diwan-maarri","type":"poem","seq":59,"chapter":"قصائد","title":"إذا رأيتم كريما، عند غيركم،","page":"","text":"إذا رأيتم كريما، عند غيركم، … فأكرموه على يسر وإنضاب\nفالسيف تعرف ذات الخدر موضعه … من قومها، وهي لم تضرب بقرضاب\nوالشر ينشر، بعد الخير، ميته، … كما أصاب، عميرا، ما جنى ضابي"},{"id":"diwan-maarri:60","bookId":"diwan-maarri","type":"poem","seq":60,"chapter":"قصائد","title":"يأتي الردى، ويواري إثلب جسدا،","page":"","text":"يأتي الردى، ويواري إثلب جسدا، … فافعل جميلا، وجانب كل ثلاب\nوالناس كالخيل، ما هجن بمعطية، … في مريها، كعطايا آل حلاب\nفاسمع كلامي، وحاول أن تعيش به، … فسوف أعوز، بعد اليوم، طلابي\nاستغفر الله، واترك ما حكى لهم … أبو الهذيل، وما قال ابن كلاب\nفالدين قد خس، حتى صار أشرفه … بازا لبازين، أو كلبا لكلاب\nوالظلم، عندي، قبيح لا أجوزه … ولو أطعت لما فاؤوا بأجلاب\nإن السواد لجنس، خيره زمر، … فقس بني آدم منه على اللاب\nلا تنبت الحرة المرعى، ولو سقيت … بعارض، لمياه البحر، حلاب\nلا يكتسون قميصا، في ديارهم، … كالأرض لم تكس من نبت بأسلاب\nدهري قتاد، وحالي ضالة ضؤلت … عما أريد، ولوني لون لبلاب\nوإن وصلت، فشكري شكر بروقة … ترضى ببرق، من الأمطار، خلاب\nفدار خصمك، إن حق أنار له، … ولا تنازع بتمويه وإجلاب\nوحب دنياك طبع في المقيم بها، … فقد منيت بقرن منه غلاب\nلما رأيت سجايا العصر ترخصني، … رددت قدري إلى صبري، فإغلابي"},{"id":"diwan-maarri:61","bookId":"diwan-maarri","type":"poem","seq":61,"chapter":"قصائد","title":"أسوان أنت، لأن الحي نيتهم","page":"","text":"أسوان أنت، لأن الحي نيتهم … أسوان، أي عذاب دون عيذاب\nوالعقل يسعى لنفسي، في مصالحها … فما لطبع، إلى الآفات، جذاب"},{"id":"diwan-maarri:62","bookId":"diwan-maarri","type":"poem","seq":62,"chapter":"قصائد","title":"الحظ لي، ولأهل الأرض كلهم،","page":"","text":"الحظ لي، ولأهل الأرض كلهم، … ألا يراني، أخرى الدهر، أصحابي\nوشقوة غشيت وجهي، بنضرته، … أبر بي من نعيم جر إشحابي\nحابي كثير، ومانبلي بصائبة؛ … وكيف لي في مراميهن بالحابي؟\nقد كنت صعبا ولكن أرهفت غير، … حتى تبين كل الناس أصحابي\nفاحذر من الإنس، أدناهم وأبعدهم، … وإن لقوك بتبجيل وترحاب"},{"id":"diwan-maarri:63","bookId":"diwan-maarri","type":"poem","seq":63,"chapter":"قصائد","title":"استنبط العرب لفظا، وانبرى نبط،","page":"","text":"استنبط العرب لفظا، وانبرى نبط، … يخاطبونك من أفواه أعراب\nكلمت باللحن أهل اللحن أنفسهم، … لأن عيبي، عند القوم، إعرابي\nدنياي لا كنت من أم مخادعة، … كم ميسم لك في وجهي وأقرابي\nأشربت حبك لا ينفيه عن جسدي … سوى ثرى لدماء الإنس شراب\nعند الفراقد أسراري مخبأة، … إذ لست أرضى لآرابي بآرابي\nترائبي، وهي مغنى السر، ما علمت … به، لدي، فهل نالته أترابي؟\nضربتني بحسام، أو بقاطعة، … من منطق، وعن الجرحين إضرابي\nما شد ربك أزرا بي، فينقصني، … من رتبة لي، من بالقول أزرا بي\nأضعت ما كنت أفنيت الزمان به، … بل جر، ما كان، أعدائي وحرابي\nكقينة الكأس، إذ باتت مطربة، … بين الشروب، وليست ذات إطراب\nوالشر جم، ومن تسلم له إبل، … من غارة الجيش، يتركها لخراب\nأسرى بي الأمل اللاهي بصاحبه، … حتى ركبت سرايا، بين أسراب\nهربت من بين إخواني لتحسبني … في معشر، من لباس الذام، هراب\nكأنني، كل حول، محدث حدثا، … يرى به، من تولى المصر، إغرابي\nالسيف والرمح قد أودى زمانهما، … فهل لكفك في عود ومضراب؟"},{"id":"diwan-maarri:64","bookId":"diwan-maarri","type":"poem","seq":64,"chapter":"قصائد","title":"انفض ثيابك من ودي ومعرفتي،","page":"","text":"انفض ثيابك من ودي ومعرفتي، … فإن شخصي هباء، في الضحى، هابي\nوقد نبذت على جمر، خبا، يبسا، … فإن يكن فيه سقط يذك إلهابي\nوقد نصحتك، فاحذر أن ترى أذنا … ترمي إلى السهب إكثاري، وإسهابي"},{"id":"diwan-maarri:65","bookId":"diwan-maarri","type":"poem","seq":65,"chapter":"قصائد","title":"الحمد لله! ما في الأرض وادعة،","page":"","text":"الحمد لله! ما في الأرض وادعة، … كل البرية في هم وتعذيب\nجاء النبي بحق، كي يهذبكم؛ … فهل أحس لكم طبع بتهذيب؟\nعود يصدق، أو غر يكذب، أو … مردد بين تصديق وتكذيب\nولو علمتم بداء الذئب من سغب، … إذا لسامحتم بالشاة للذيب"},{"id":"diwan-maarri:66","bookId":"diwan-maarri","type":"poem","seq":66,"chapter":"قصائد","title":"لا يحسب الجود من رب النخيل جدا،","page":"","text":"لا يحسب الجود من رب النخيل جدا، … حتى تجود على السود الغرابيب\nما أغدر الإنس! كم خشف ترببهم، … فغادروه أكيلا بعد تربيب\nهذي الحياة، أجاءتنا، بمعرفة، … إلى الطعام، وستر بالجلابيب\nلو لم تحس لكان الجسم مطرحا، … لذع الهواجر، أو وقع الشآبيب\nفاهجر صديقك، إن خفت الفساد به؛ … إن الهجاء لمبدوء بتشبيب\nوالكف تقطع، إن خيف الهلاك بها، … على الذراع بتقدير وتسبيب\nطرق النفوس إلى الأخرى مضللة؛ … والرعب فيهن من أجل الرعابيب\nترجو انفساحا، وكم للماء من جهة، … إذا تخلص من ضيق الأنابيب\nأما رأيت صروف الدهر غادية، … على القلوب، بتبغيض وتحبيب\nوكل حي، إذا كانت له أذن، … لم تخله من وشايات وتخبيب\nعجبت للروم، لم يهد الزمان لها … حتفا، هداه إلى سابور أو بيب\nإن تجعل اللجة الخضراء واقية، … فالملك يحفظ بالخضر اليعابيب"},{"id":"diwan-maarri:67","bookId":"diwan-maarri","type":"poem","seq":67,"chapter":"قصائد","title":"إذا قضى الله أمرا جاء مبتدرا،","page":"","text":"إذا قضى الله أمرا جاء مبتدرا، … وكل ما أنت لاقيه بتسبيب\nظلت ملاحية في الشيء تفعله، … جهلا، ملاحية من بعد غربيب\nلو لم يصيبوا مداما من غراسهم، … لجاز أن يمطروها في الشآبيب\nولامترتها، وخيل القوم جائلة، … أيدي الفوارس من صم الأنابيب"},{"id":"diwan-maarri:68","bookId":"diwan-maarri","type":"poem","seq":68,"chapter":"قصائد","title":"دنياك تكنى بأم دفر،","page":"","text":"دنياك تكنى بأم دفر، … لم يكنها الناس أم طيب\nفأذن إلى هاتف مجيد، … قام على غصنه الرطيب\nيكون، عند اللبيب منا، … أبلغ من واعظ خطيب\nيحلف: ما جادت الليالي … إلا بسم لنا قطيب"},{"id":"diwan-maarri:69","bookId":"diwan-maarri","type":"poem","seq":69,"chapter":"قصائد","title":"قبيح أن يحس نحيب باك،","page":"","text":"قبيح أن يحس نحيب باك، … إذا حان الردى، فقضيب نحبي\nولم أرد المنية باختياري، … ولكن أوشك الفتيان سحبي\nولو خيرت لم أترك محلي، … فأسكن في مضيق بعد رحب\nوجدت الموت ينتظم البرايا، … بشجب منه في أعقاب شجب\nفأوصيكم بدنيانا هوانا، … فإني تابع آثار صحبي"},{"id":"diwan-maarri:70","bookId":"diwan-maarri","type":"poem","seq":70,"chapter":"قصائد","title":"ليال ما تفيق من الرزايا،","page":"","text":"ليال ما تفيق من الرزايا، … فويحي من عجائبها وويبي!\nأعادت أسدها أسدا أكيلا، … وأودى ذئبها بأبي ذؤيب"},{"id":"diwan-maarri:71","bookId":"diwan-maarri","type":"poem","seq":71,"chapter":"قصائد","title":"يهاب الناس إيجاف المنايا،","page":"","text":"يهاب الناس إيجاف المنايا، … وهل حاد القضاء عن الهيوب؟\nإذا كشفت أجناس البرايا، … وجدت العالمين ذوي عيوب\nذيولهم كثيرات المخازي، … لما فقدوه من نصح الجيوب\nتحدثك الظنون بما تلاقي، … كأن الظن علام الغيوب"},{"id":"diwan-maarri:72","bookId":"diwan-maarri","type":"poem","seq":72,"chapter":"قصائد","title":"إذا اصفر الفتى لفراق روح،","page":"","text":"إذا اصفر الفتى لفراق روح، … فأهون بالتصعلك والشحوب\nأحوبي صاحبي، فأعير فضلا … علي، أم انتقصت لأجل حوبي؟"},{"id":"diwan-maarri:73","bookId":"diwan-maarri","type":"poem","seq":73,"chapter":"قصائد","title":"بني الآداب! غرتكم، قديما","page":"","text":"بني الآداب! غرتكم، قديما … زخارف مثل زمزمة الذباب\nوما شعراؤكم إلا ذئاب، … تلصص في المدائح والسباب\nأضر لمن تود من الأعادي، … وأسرق، للمقال، من الزباب\nأقارضكم ثناء غير حق، … كأنا منه في مجرى سباب\nأأذهب فيكم أيام شيبي، … كما أذهبت أيام الشباب؟\nمعاذ الله قد ودعت جهلي، … فحسبي من تميم والرباب\nأحاديث الضباب وآل كعب … نبذت سوالكا درج الضباب\nوما سم الحباب، لدي، إلا … كنظم قيل في آل الحباب\nليعد مع الضباب سليل حجر، … وسائر قوله في ابن الضباب\nفما أم الحويرث، في كلامي، … بعارضة، ولا أم الرباب\nوإن مقاتل الفرسان، عندي، … مصارع تلكم الغنم الرباب\nوألقيت الفصاحة عن لساني، … مسلمة إلى العرب اللباب\nشغول، ينقضين بغير حمد، … ولا يرجعن إلا بالتباب\nذروني يفقد، الهذيان، لفظي، … وأغلق للحمام، علي، بابي"},{"id":"diwan-maarri:74","bookId":"diwan-maarri","type":"poem","seq":74,"chapter":"قصائد","title":"من يخضب الشعرات يحسب ظالما،","page":"","text":"من يخضب الشعرات يحسب ظالما، … ويعد أخرق كالظليم الخاضب\nوالشيب في لون الحسام، فلا تدع … جسد النجيع على الحسام القاضب\nعمري غدير، كل أنفاسي به … جرع، تغادره كأمس الناضب"},{"id":"diwan-maarri:75","bookId":"diwan-maarri","type":"poem","seq":75,"chapter":"قصائد","title":"جدث أريح، وأستريح بلحده،","page":"","text":"جدث أريح، وأستريح بلحده، … خير من القصر الذي آذى به\nوصدقت هذا العيش في حبي له، … واغترني بخداعه وكذابه\nوجذبت من مرس الحياة مغاره، … فالآن أخشى البت عند جذابه\nولأشربن من الحمام كؤوسه، … ما بين جامده وبين مذابه\nعذب، يعذبني، البقاء، وللردى … يوم، يخلص من فنون عذابه"},{"id":"diwan-maarri:76","bookId":"diwan-maarri","type":"poem","seq":76,"chapter":"قصائد","title":"كم أمة لعبت بها جهالها،","page":"","text":"كم أمة لعبت بها جهالها، … فتنطست من قبل في تعذيبها\nالخوف يلجئها إلى تصديقها، … والعقل يحملها على تكذيبها\nوجبلة الناس الفساد، فظل من … يسمو بحكمته إلى تهذيبها\nيا ثلة في غفلة، وأويسها ال … قرني مثل أويسها، أي ذيبها\nسبحان مجمد راكد ومقره، … وممير لجة زاخر ومذيبها"},{"id":"diwan-maarri:77","bookId":"diwan-maarri","type":"poem","seq":77,"chapter":"قصائد","title":"قد قيل: إن الروح تأسف، بعدما","page":"","text":"قد قيل: إن الروح تأسف، بعدما … تنأى عن الجسد، الذي غنيت به\nإن كان يصحبها الحجى، فلعلها … تدري، وتأبه للزمان وعتبه\nأو لا، فكم هذيان قوم غابر، … في الكتب، ضاع مداده في كتبه"},{"id":"diwan-maarri:78","bookId":"diwan-maarri","type":"poem","seq":78,"chapter":"قصائد","title":"كم غادة مثل الثريا في العلا","page":"","text":"كم غادة مثل الثريا في العلا … والحسن، قد أضحى الثرى من حجبها\nولعجبها ما قربت مرآتها، … نزهت خلي عن مقالي عج بها"},{"id":"diwan-maarri:79","bookId":"diwan-maarri","type":"poem","seq":79,"chapter":"قصائد","title":"إدأب لربك، لا يلومك عاقل","page":"","text":"إدأب لربك، لا يلومك عاقل … في سجن هذي النفس، أو إدآبها\nسنؤوب في عقبى الحياة مساكنا، … لا علم لي بالأمر، بعد مآبها\nلا تأمنن من الدهور تغيرا، … حتى تكون ظباؤها كذئابها\nويصير في شيبان مجنى غرسها، … ويعود مسقط ثلجها في آبها\nأبقت أحاديث الرجال، وأهلكت … سلفي عتيبيها، وآل ذؤابها"},{"id":"diwan-maarri:80","bookId":"diwan-maarri","type":"poem","seq":80,"chapter":"قصائد","title":"لا ريب أن الله حق، فلتعد","page":"","text":"لا ريب أن الله حق، فلتعد … باللوم أنفسكم على مرتابها\nوغدت عقولكم تعاتب أنفسا، … ليست تريع لنصحها وعتابها\nهلا تتوب من الذنوب خواطىء … قبل اعتراض الموت دون متابها\nبنت النصارى للمسيح كنائسا، … كانت تعيب الفعل من منتابها\nومتى ذكرت محمدا وكتابه، … جاءت يهود بجحدها وكتابها\nأفملة الإسلام ينكر منكر، … وقضاء ربك صاغها وأتى بها\nأين الهدى فنرومه بمشقة، … في البيد، ساطية على مجتابها\nوالعيس، أقتاب لها مستورة، … شكت الذين سروا على أقتابها"},{"id":"diwan-maarri:81","bookId":"diwan-maarri","type":"poem","seq":81,"chapter":"قصائد","title":"لا تلبس الدنيا، فإن لباسها","page":"","text":"لا تلبس الدنيا، فإن لباسها … سقم، وعر الجسم من أثوابها\nأنا خائف من شرها، متوقع … إكآبها، لا الشرب من أكوابها\nفلتفعل النفس الجميل، لأنه … خير وأحسن، لا لأجل ثوابها\nفي بيته الحكم، الذي هو صادق، … فأتوا بيوت القوم من أبوابها\nوتخالف الرؤساء يشهد، مقسما: … إن المعاشر ما اهتدت لصوابها\nوإذا لصوص الأرض أعيت واليا، … ألقى السؤال بها على توابها\nجيبت فلاة للغنى، فأصابه … نفر، وصين الغيب عن جوابها\nآوى بها الله الأنام، فما أوى … لمحالفي ددها ولا أوابها"},{"id":"diwan-maarri:82","bookId":"diwan-maarri","type":"poem","seq":82,"chapter":"قصائد","title":"أهلا بغائلة الردى وإيابها،","page":"","text":"أهلا بغائلة الردى وإيابها، … كيما تسترني بفضل ثيابها\nدنياك دار، إن يكن شهادها … عقلاء، لا يبكوا على غيابها\nقد أظهرت نوبا تزيد على الحصى … عددا، وكم في ضبنها وعيابها\nتفريهم بسيوفها، وتكبهم … برماحها، وتنالهم بصيابها\nما الظافرون بعزها ويسارها، … إلا قريبو الحال من خيابها\nأنياب جامعة السمام فم التي … أطغت، فخلت الراح في أنيابها\nإن المنية لم تهب متهيبا، … فالعجز والتفريط في هيابها\nومن العجائب أن كلا راغب … في أم دفر، وهو من عيابها\nفاتفل عن الترب الفصاحة، إنها … تقضي لناعيها على زريابها"},{"id":"diwan-maarri:83","bookId":"diwan-maarri","type":"poem","seq":83,"chapter":"قصائد","title":"خبر الحياة شرورها، وسرورها،","page":"","text":"خبر الحياة شرورها، وسرورها، … من عاش عدة أول المتقارب\nوافى بذلك أربعين، فما له … عذر، إذا أمسى قليل تجارب\nيا ضارب العود البطيء، وظهره … لا وزر يحمله، كوزر الضارب\nأرفق به، فشهدت أنك ظالم … في ظالمين: أباعد وأقارب\nقل للمدامة، وهي ضد للنهى، … تنضو لها أبدا سيوف محارب\nلو كان لم يحظرك، غير أذية، … شيء، لبت مباحة للشارب\nلكن حماك العقل، وهو مؤمر، … فانأي، وراءك، في التراب التارب"},{"id":"diwan-maarri:84","bookId":"diwan-maarri","type":"poem","seq":84,"chapter":"قصائد","title":"البابلية باب كل بلية،","page":"","text":"البابلية باب كل بلية، … فتوقين هجوم ذاك الباب\nجرت ملاحاة الصديق وهجره، … وأذى النديم، وفرقة الأحباب\nأم الحباب، وإن أميت لهيبها … بمزاجها، وافت كأم حباب\nهتكت حجاب المحصنات وجشمت … مهن العبيد تهضم الأرباب\nوتوهم الشيب المدالف أنهم … لبسوا، على كبر، برود شباب\nوإذا تأملت الحوادث، ألفيت … صهب الدنان أعادي الألباب"},{"id":"diwan-maarri:85","bookId":"diwan-maarri","type":"poem","seq":85,"chapter":"قصائد","title":"شربي، على المقلة، في مقلت،","page":"","text":"شربي، على المقلة، في مقلت، … وأكلي المشرق بالمغرب\nآثر عندي من طعام لهم … يشفع بالمطرف والمطرب\nيا ترب الحالة! كل إلى التر … ب، فجنت حسد المترب"},{"id":"diwan-maarri:86","bookId":"diwan-maarri","type":"poem","seq":86,"chapter":"قصائد","title":"ماوية المرأة لا تصحب الما","page":"","text":"ماوية المرأة لا تصحب الما … وية المرأة، من عجبها\nلعلمها أن الذي صاغها، … آثرها بالحسن في حجبها\nلو كانت الدنيا لها منزلا، … ما قلت عن معرفة عج بها\nسير بنا، فانظر إلى رفقة، … لا تضع الأكوار عن نجبها"},{"id":"diwan-maarri:87","bookId":"diwan-maarri","type":"poem","seq":87,"chapter":"قصائد","title":"إتبع طريقا للهدى لاحبا،","page":"","text":"إتبع طريقا للهدى لاحبا، … وخل آثارا بملحوب\nأف لدنياي، فإني بها … لم أخل من إثم، ومن حوب\nقلت لها: امضي غير مصحوبة! … فقالت: اذهب غير مصحوب"},{"id":"diwan-maarri:88","bookId":"diwan-maarri","type":"poem","seq":88,"chapter":"قصائد","title":"قد أهملت للخياط إبرتها،","page":"","text":"قد أهملت للخياط إبرتها، … فصادفت إبرة لعقربها\nفهي تسقى الحليب ليلتها، … ولم يكن من لذيذ مشربها\nوإنما الخود، في مساربها، … كربة السم في تسربها\nفلا تكوني مثل التي لدغت، … تبدأ، في شرها، بأقربها"},{"id":"diwan-maarri:89","bookId":"diwan-maarri","type":"poem","seq":89,"chapter":"قصائد","title":"إن كؤوس المدام تشبهها الس","page":"","text":"إن كؤوس المدام تشبهها الس … يوف، والموت في مضاربها\nشموسها شمس باطل شرقت، … فلا يكن فوك من مغاربها\nونملها إن تدب في جسد، … أضر للنفس من عقاربها\nوكل ما أذهب العقول، وإن … خالفها، فهو من أقاربها\nجربها عالم بشيمتها، … ويذهب اللب في تجاربها\nوقد تقضى الحياة، راضية، … بدون مانيل من مآربها\nإن شربت راحها زنت وجنت، … فلتتق الله في مشاربها"},{"id":"diwan-maarri:90","bookId":"diwan-maarri","type":"poem","seq":90,"chapter":"قصائد","title":"خف دنيا، كما تخاف شريفا،","page":"","text":"خف دنيا، كما تخاف شريفا، … صال ليث الشرى بظفر وناب\nوالصلال، التي يخاف رداها، … شرها في الرؤوس والأذناب\nهل جناب، نحله، غير دنيا … نا، فإنا منها بشر جناب\nعلق الحين، في الحضارة بالخد … ر، وفي البدو شد بالأطناب\nلا تدرع من القضاء، فما سي … ف المنايا، عن الدروع، بناب\nزارت الشام والعراق وكل الأر … ض، ماجانبت قطين الجناب\nكل علم الطبيب عن مرض المو … ت، وقد ناب فيه كل مناب\nنطقت ألسن الحمام، وبالإي … جاز جاءت،وكثرة الإطناب\nلا يكاد الفتى يجهز، إلا … عن بديل، مكانه، مستناب"},{"id":"diwan-maarri:91","bookId":"diwan-maarri","type":"poem","seq":91,"chapter":"قصائد","title":"أسطر لاب، حولهن، جهول،","page":"","text":"أسطر لاب، حولهن، جهول، … فهو يرجو هديا بأسطرلاب\nلا تقسني على الذي شاع عني، … إن دنياك معدن للخلاب\nقد يسمي الفتى الجبان أبوه … أسدا، وهو من خساس الكلاب\nوالبرايا لفظ الزمان، ولا بد … له من تغير وانقلاب\nعجب الليل من سرورك فيه، … وأتى العين ثاكلا في سلاب"},{"id":"diwan-maarri:92","bookId":"diwan-maarri","type":"poem","seq":92,"chapter":"قصائد","title":"إذا ابنا أب واحد ألفيا","page":"","text":"إذا ابنا أب واحد ألفيا … جوادا وعيرا، فلا تعجب\nفإن الطويل، نجيب القريض، … أخوه المديد، ولم ينجب\nويشجب كل امرىء، في الزمان، … من آل عدنان، أو يشجب"},{"id":"diwan-maarri:93","bookId":"diwan-maarri","type":"poem","seq":93,"chapter":"قصائد","title":"تشاور بكرك في نفسها،","page":"","text":"تشاور بكرك في نفسها، … وتنسى مشاورة الثيب\nوأنت سفيه رأى مثله، … فقال السفاه له: عيب\nأيا جسد المرء! ماذا دهاك؟ … وقد كنت من عنصر طيب\nتخبثت، إذ جمعت أربع … لديك، وأضحكت في الحي بي\nفلا تجزعن إذا ما الحمام … صاح بوفد الضنى: هي بي\nتصير طهورا، إذا ما رجعت … إلى الأصل، كالمطر الصيب\nوما لك مال وإن جزته، … فأعظ عفاتك، أو خيب"},{"id":"diwan-maarri:94","bookId":"diwan-maarri","type":"poem","seq":94,"chapter":"قصائد","title":"معاص تلوح، فأوصيكم","page":"","text":"معاص تلوح، فأوصيكم … بهجرانها، لا بإغبابها\nكأن المهيمن أوصى النفوس … بعشق الحياة، وإحبابها\nإذا دفنت في الثرى هالكا، … تناست عهودا لأحبابها\nألبت على غير نفع لها، … وذاك لقلة ألبابها\nتولى الخليل إلى ربه، … وخلى العروض لأربابها\nفليس بذاكر أوتادها، … ولا مرتج فضل أسبابها"},{"id":"diwan-maarri:95","bookId":"diwan-maarri","type":"poem","seq":95,"chapter":"قصائد","title":"أما والركاب وأقتابها،","page":"","text":"أما والركاب وأقتابها، … تجوب الفلاة بمجتابها\nتنص بكل فتى ناسك، … صحيح النهى غير مرتابها\nمتى ذكرت عنده مومس … فليس، حذارا، بمغتابها\nوأجبال فهر وأحجارها، … وكعبة كعب، ومنتابها\nوكتب، يبين اتقاء المليك … في دارسيها، وكتابها\nلقد عتبت هذه الحادثات، … فلم ترض خلقا بإعتابها"},{"id":"diwan-maarri:96","bookId":"diwan-maarri","type":"poem","seq":96,"chapter":"قصائد","title":"تحل إذا استربت بك، اهتضامي،","page":"","text":"تحل إذا استربت بك، اهتضامي، … وأنت فعلت أفعال المريب\nضريبك، في بني الدنيا، كثير، … وعز الله ربك عن ضريب\nوما العلماء والجهال إلا … قريب، حين تنظر من قريب\nمتى ما يأتني أجلي بأرضي، … فناد على الجنازة للغريب\nأكاشر من لقيت، على حذار، … وليس، على اعتقادي، من عريب"},{"id":"diwan-maarri:97","bookId":"diwan-maarri","type":"poem","seq":97,"chapter":"قصائد","title":"يا أيها المغرور، لب من الحجى،","page":"","text":"يا أيها المغرور، لب من الحجى، … وإذا دعاك، إلى التقى، داع فلب\nإن الشرور لكالسحابة أثجمت، … لاك السرور، كأنه برق خلب\nوأبر من شرب المدامة، صفنت … في عسجد، شرب الرثيئة في العلب\nجاءتك مثل دم الغزال بكأسها، … مقتولة قتلتك، فاله عن السلب\nحلبية في النسبتين، لأنهما … حلب الكروم، وأن موطنها حلب\nوالعقل أنفس ما حبيت، وإن يضع، … يوما، يضع، فغوى الشراب وما حلب\nوالنفس تعلم أنها مطلوبة … بالحادثات، فما تراع من الطلب\nوالدهر أرقم بالصباح وبالدجى، … كالصل يفتك باللديغ، إذا انقلب\nوأرى الملوك ذوي المراتب، غالبوا … أيامهم، فانظر بعيشك من غلب\nسيان عندي مادح متحرض، … في قوله، وأخو الهجاء، إذا ثلب"},{"id":"diwan-maarri:98","bookId":"diwan-maarri","type":"poem","seq":98,"chapter":"قصائد","title":"للرزق أسباب تسبب،","page":"","text":"للرزق أسباب تسبب، … والعيش مأمول، محبب\nوصبابة الإنسان بالد … نيا، أرتك دما تصبب\nشرب امرؤ من قهوة … شامية، حتى تحبب\nوأخوه يكره نغبة، … في الرفد، من ذهب يضبب\nوالموت طب، ليس يب … رئه الحكيم، وإن تطبب\nيا طرف! إن بت الأق … ب، وصم حافرك المقبب\nوجببت، في الجري، الخيو … ل، وكنت من وضح مجبب\nفليدركنك، مرة، … ما أدرك الخرق المربب\nوالصمت يلزمه الفتى، … من بعد ما غنى وشبب"},{"id":"diwan-maarri:99","bookId":"diwan-maarri","type":"poem","seq":99,"chapter":"قصائد","title":"جنى ابن ستين، على نفسه،","page":"","text":"جنى ابن ستين، على نفسه، … بالولد الحادث، ما لا يحب\nتقول عرس الشيخ، في نفسها: … لا كنت يا شر خليل صحب\nأنفع منه، عندها، برجد، … أذهب قرا، أو سقاء سحب"},{"id":"diwan-maarri:100","bookId":"diwan-maarri","type":"poem","seq":100,"chapter":"قصائد","title":"كأنما الأجساد، إن فارقت","page":"","text":"كأنما الأجساد، إن فارقت … أرواحها، صخر ثوى أو خشب\nوما درى الميت: أأكفانه … مخلقة، في رمسه، أم قشب\nشاب، علينا أمرنا، شائب، … وقد وددنا أنه لم يشب\nطوبى لطير تلقط الحبة الملقاة، … أو وحش تقفى العشب\nلا تألف الإنس ولا تعرف القن … س، ولا تسمو إليها الأشب\nفلا تشب الحرب، وقادة؛ … فخامد في نفسه من يشب"},{"id":"diwan-maarri:101","bookId":"diwan-maarri","type":"poem","seq":101,"chapter":"قصائد","title":"قد أعزب العالم أحلامهم؛","page":"","text":"قد أعزب العالم أحلامهم؛ … يا عازب الحلم عن الناس ثب\nنيران حقد بين أحشائهم، … فلفظهم عنها شرار وثب\nتنسيهم، العارفة، الهيف كالأغ … صان، والأعجاز مثل الكثب"},{"id":"diwan-maarri:102","bookId":"diwan-maarri","type":"poem","seq":102,"chapter":"قصائد","title":"أخبرت، عن كتبك، أعجوبة؛","page":"","text":"أخبرت، عن كتبك، أعجوبة؛ … ورب مين ضمنته الكتب\nتواصل الغي، ولولم يكن … فيك حجى، ما عتبتك العتب\nوطبعك الشر، فإن أمكنت … توبة ليل، من سواد، فتب\nويطلب النقلة، عن خيمهم، … ناس، على كل قبيح، رتب"},{"id":"diwan-maarri:103","bookId":"diwan-maarri","type":"poem","seq":103,"chapter":"قصائد","title":"إني ونفسي، أبدا، في جذاب،","page":"","text":"إني ونفسي، أبدا، في جذاب، … أكذبها، وهي تحب الكذاب\nإن أدخل النار، فلي خالق، … يحمل عني مثقلات العذاب\nيقدر أن يسكنني روضة، … فيها، ترامى بالمياه العذاب\nلا أطعم الغسلين، في قعرها، … ولا أغادى بالحميم المذاب"},{"id":"diwan-maarri:104","bookId":"diwan-maarri","type":"poem","seq":104,"chapter":"قصائد","title":"عاقبة الميت محمودة،","page":"","text":"عاقبة الميت محمودة، … إذا كفى الله أليم العقاب\nليس عذاب الله من خانه، … كالقطع للأيدي وضرب الرقاب\nلكنه متصل، فاحتقب … ما شئت لا يوضع وضع الحقاب\nوناره لا تشبه النار، في … إفنائها ما أطعمت من ثقاب\nكم عمل أهمله عامل، … يحفظه خالقنا بارتقاب\nوإنما غودر، في مدنا، … كقاب قوس مد أو بعض قاب\nليتي هباء في قناتي لأى، … أو قطرة بين جناحي عقاب\nأو كنت كدريا، أخا قفرة، … مشربه من آجنات الوقاب\nدنياك ورهاء، لها شارة، … وقبحها يستر تحت النقاب\nيا ناقة في ضرعها قاتل، … تعله مرتضعات السقاب\nهل وألت مغفرة بالذرى؛ … أو أفعوان ساكن بالشقاب\nآه لضعفي! كيف بي هابطا … في الواد، أو مرتغيا في العقاب"},{"id":"diwan-maarri:105","bookId":"diwan-maarri","type":"poem","seq":105,"chapter":"قصائد","title":"ما أجلي، في أجلى، حاضر،","page":"","text":"ما أجلي، في أجلى، حاضر، … من بعد ما جربت أهل الجريب\nكأن حواء، التي زوجها … آدم، لم تلقح بشخص أريب\nقد كثرت، في الأرض، جهالنا، … والعاقل الحازم فينا غريب\nوإن يكن، في موتنا، راحة، … فالفرج الوارد منا قريب\nهل من عريب أو ذوي جرهم، … أو إرم أو آل طسم عريب؟"},{"id":"diwan-maarri:106","bookId":"diwan-maarri","type":"poem","seq":106,"chapter":"قصائد","title":"من جالس المغتاب، فهو مغتاب؛","page":"","text":"من جالس المغتاب، فهو مغتاب؛ … لست على كل جنى بعتاب\nولا مجاز مخطيا، إذا تاب، … وكيف لي بورد نسك مؤتاب\nأقطع منه حندسا، وأجتاب؛ … وتضمر الأقتاب فوق الأقتاب\nتزعجني ذات وجيف رتاب، … تخط في الأرض سطور الكتاب\nإني بنفسي، في التقى، لمرتاب، … ولا أشك في الحمام المنتاب"},{"id":"diwan-maarri:107","bookId":"diwan-maarri","type":"poem","seq":107,"chapter":"قصائد","title":"إذا وهب الله لي نعمة،","page":"","text":"إذا وهب الله لي نعمة، … أفدت المساكين مما وهب\nجعلت لهم عشر سقي الغمام، … وأعطيتهم ربع عشر الذهب\nوإلا فليس على قادح، … إذا ما كبا الزند، دفع اللهب\nولو أرسلت، في المهب، الجنوب، … لما عجزت عن سلوك المهب"},{"id":"diwan-maarri:108","bookId":"diwan-maarri","type":"poem","seq":108,"chapter":"قصائد","title":"يحل بمهر رحيق الرضاب،","page":"","text":"يحل بمهر رحيق الرضاب، … وليس يحل رحيق العنب\nيعيد الفتى، كالذي نابه … جنون، على أنه لم ينب\nوما أخذ العقل من أهله، … وإن هو غر اللمى والشنب"},{"id":"diwan-maarri:109","bookId":"diwan-maarri","type":"poem","seq":109,"chapter":"قصائد","title":"تنافس قوم على رتبة؛","page":"","text":"تنافس قوم على رتبة؛ … كأن الزمان يديم الرتب\nودنياك غر بها جاهل، … فتبت على كل حال وتب\nوكم من بعير قضى دهره، … بشد البطان وعض القتب\nوآخر في مرتع هامل، … تظالع من أشر أو عتب\nولي عمل كجناح الغراب، … أو جنح ليل، إذا ما رتب\nفإن كان يكتبه كاتب، … فقد سود الصبح مما كتب"},{"id":"diwan-maarri:110","bookId":"diwan-maarri","type":"poem","seq":110,"chapter":"قصائد","title":"أخبت ركابي أم أتيح لها خبت،","page":"","text":"أخبت ركابي أم أتيح لها خبت، … عميم رياض ما يزال به نبت\nوكفرها ليل ترهب شهبه، … تخال يهودا عاق عن سيرها السبت\nوهيجها قول، يقال عن الحمى؛ … وذاك حديث ما محدثه ثبت\nومن عاين الدنيا بعين من النهى، … فلا جذل يفضي إليه، ولا كبت\nوفى الله، يا بدر السماء، بزعمه، … وكم جبت جنحا، قبل أن يعبد الجبت\nيعيش أناس، لا يمس جسومهم … شفوف ولا يحذى لأقدامهم سبت\nرقدت زمانا، ثم أرقدني الونى، … وألهبت دهرا، ثم أدركني الهبت"},{"id":"diwan-maarri:111","bookId":"diwan-maarri","type":"poem","seq":111,"chapter":"قصائد","title":"ثلاثة أيام لأهل تنافر،","page":"","text":"ثلاثة أيام لأهل تنافر، … ولكن قول المسلمين هو الثبت\nيرى الأحد النصري عيدا لأهله، … وجمعتنا عيد لنا، ولك السبت\nوما الناس إلا خالف بعد سالف، … كذلك نبت الأرض يخلفه النبت\nإلا افتكر الإنسان في أمر دينه، … بدا نبأ يثني الحجى وبه كبت\nفهل خير عن أنفس، بان وفدها … إلى الله، معمور بأجسامها الخبت؟"},{"id":"diwan-maarri:112","bookId":"diwan-maarri","type":"poem","seq":112,"chapter":"قصائد","title":"ألم تر للدنيا وسوء صنيعها،","page":"","text":"ألم تر للدنيا وسوء صنيعها، … وليس سوى وجه المهيمن ثابت\nتخالف برساها: فبرس، بهامة، … أقر، وبرس يذهب القر نابت\nمصل، ودهري، وغاو، وناسك، … وأزهر مكبوت، وأسود كابت\nأينحل سبت يعقد، الحظ، يومه، … فينجح ساع أم هو الدهر سابت؟"},{"id":"diwan-maarri:113","bookId":"diwan-maarri","type":"poem","seq":113,"chapter":"قصائد","title":"رأيت جماعات من الناس أولعت","page":"","text":"رأيت جماعات من الناس أولعت … بإثبات أشياء استحال ثبوتها\nفقد أخبرت، عن غيها، سنواتها، … كما أخبرت آحادها وسبوتها\nوما هي إلا النار توقد مرة، … فتذكو، وتارات يحين خبوتها"},{"id":"diwan-maarri:114","bookId":"diwan-maarri","type":"poem","seq":114,"chapter":"قصائد","title":"مسيحية من قبلها موسوية ،","page":"","text":"مسيحية من قبلها موسوية ، … حكت لك أخبارا، بعيدا ثبوتها\nوفارس قد شبت لها النار وادعت … لنيرانها أن لا يجوز خبوتها\nفما هذه الأيام إلا نظائر؛ … تساوت بها آحادها وسبوتها"},{"id":"diwan-maarri:115","bookId":"diwan-maarri","type":"poem","seq":115,"chapter":"قصائد","title":"كأن قلوب القوم منا جنادل،","page":"","text":"كأن قلوب القوم منا جنادل، … فليس لها عند الأمور حصاة\nإذا ما ادعوا لله خوفا وطاعة، … فلا ريب أن المدعين عصاة\nوأوصاهم أهل الأمانة والتقى، … فما حفظت بعد المغيب وصاة"},{"id":"diwan-maarri:116","bookId":"diwan-maarri","type":"poem","seq":116,"chapter":"قصائد","title":"إنا حسبنا حسابا لم يصح لنا،","page":"","text":"إنا حسبنا حسابا لم يصح لنا، … قد بان، في كله، التفريط والغلت\nوكثرة المال شغل، زاد في نصب؛ … وقلة منه معدول بها الفلت\nهذي الحبالة قد ضمت جماعتنا، … فهل ينوص فتى منا فينفلت؟\nأصبحت كالقوس حنتها أساورها، … وكنت كالسهم أو كالسيف ينصلت"},{"id":"diwan-maarri:117","bookId":"diwan-maarri","type":"poem","seq":117,"chapter":"قصائد","title":"إذا أتاني حمامي ماحيا شبحي","page":"","text":"إذا أتاني حمامي ماحيا شبحي … وما صنعت، فعيشي كله عنت\nلعل قوما يجازيهم مليكهم، … إذا لقوه، بما صاموا وما قنتوا"},{"id":"diwan-maarri:118","bookId":"diwan-maarri","type":"poem","seq":118,"chapter":"قصائد","title":"لا خير في المال أعطاه وأجمعه،","page":"","text":"لا خير في المال أعطاه وأجمعه، … إذا عريت، فمما حزت عريت\nوما انتفاعي، إذا أصبحت ذا فرة، … وإنما أنا رسل الضرع صريت\nوصاغني الله من ماء، وها أنا ذا … كالماء، أجري بقدر كيف جريت\nبريت للأمر لم أعرف حقائقه، … فليتني، من حساب الله، بريت\nأرى خيال إزار حمه قدر، … ظهرت منه قليلا ثم وريت\nما لي رضيت بما أنكرته زمنا، … وخلتني بصروف الدهر ضريت\nفهل درى الليث إذ ضم الرجاج له … فم، وقدر للشدقين تهريت\nكأننا في قفار، ضل سالكها … نهج الطريق وما في القوم خريت\nلو ينطق الليل نادى كم فرى ظلمي … فجر وأدلجت في حاج وأسريت\nوأعملتني رجال في مآربها، … كأنني جمل، للإنس، أبريت\nلايصبرون، فقير تحت فاقته؛ … إن السباريت جابتها السباريت\nناس، إذا نسكوا عدوا ملائكة؛ … وإن طغوا فهم جن عفاريت\nلا تطريني، فلي نفس مجربة، … تسر وجدا، إذا بالمين أطريت\nوإن مدحت بخير، ليس من شيمي، … حسبتني بقبيح الذم فريت"},{"id":"diwan-maarri:119","bookId":"diwan-maarri","type":"poem","seq":119,"chapter":"قصائد","title":"أرى الأشياء ليس لها ثبات،","page":"","text":"أرى الأشياء ليس لها ثبات، … وما أجسادنا إلا نبات\nبإذن الله تفترق البرايا، … لطيتها، وتجتمع الثبات\nأجلت سبتها أشياع موسى، … أسبت القطع ذاك أم السبات\nسألت عن البواكر أين أضحت، … وعن أهل التروح أين باتوا\nوهل أرواح هذا الخلق إلا … عواري المقادر، لا الهبات؟\nتبغض ساعنا أبدا إلينا، … وهن إلى النفوس محببات\nجياد ما يزال لها خبيب، … قوارب بالأنيس مقربات\nومن يحمى ونسوة آل كسرى … وقوف بالعراء، مسلبات؟\nوما يدري الفتى، والظن جهل، … وأقضية المليك مغيبات\nلعل بنات نعش والثريا … وشرقة، للردى، متأهبات"},{"id":"diwan-maarri:120","bookId":"diwan-maarri","type":"poem","seq":120,"chapter":"قصائد","title":"سحائب مبرقات، مرعدات،","page":"","text":"سحائب مبرقات، مرعدات، … لمهجة كل حي موعدات\nوكيف يقام في أمر مهم، … ليفعل، والمقادر مقعدات؟\nوأنفس هذه الأجسام طير، … بزاة حمامها متصيدات\nفما لك والهنود منعمات، … كأن قدودهن مهندات\nيفندن الحليم، بغير لب، … وهن، وإن غلبن، مفندات\nيخلدن الإماء نضاد صوغ، … فهل تلك الشخوص مخلدات؟\nتقلدت المآثم، باختيار، … أوانس بالفريد مقلدات\nإذا عوتبن في جنف وظلم، … أبت إلا السكوت مبلدات\nيغادرن الجليد قرين ضعف، … صوابر للنوى، متجلدات\nلقد عابت، أحاديث البرايا، … شكول، في الزمان، مولدات\nأتعبد، من إثام تتقيه، … ظوالم، بالأذى، متعبدات؟\nتريق بذاك، في قتل، دماء … رؤوس، في الحجيج، ملبدات\nتعالى الله، لم تصف السجايا، … فأفعال المعاشر مؤيدات\nإذا ما قيل حق في أناس، … فأوجههم له متربدات\nمخازيهم أوابد في الليالي، … فلا تهج الأسى، متأبدات\nوأطهر من ضوارب، في نعيم، … نعام، بالفلا، متهبدات\nتقيد لفظها عن كل بر، … مواش، بالحلي، مقيدات\nعجلن إلى مساءة مستجير، … لواه، في الخطى، متأيدات\nوتنقص، خيرها، أشرا وفتكا، … صواحب منطق متزيدات\nولسن الهائدات، ولا النصارى، … ولكن، في المقال، مهودات\nمضت لعوائد الكذب المورى، … سوادك، بالخنى، متعودات\nتأود منك عقلا في سكون، … غصون خواطر، متأودات\nفلا يجلس على الصعدات لاه، … فأنفاس الفتى متصعدات\nتمر به حوالك، فوق بيض، … وخضر، في العقيق، مسبدات\nومن تخلقه أيام طوال، … فإن شجونه متجددات\nوتسنح بالضحى ظبيات مرد، … بكل عظيمة متمردات\nوقد أغمدن في أزر، ولكن … سيوف لحاظهن مجردات\nووردت اللباس، بلون صبغ، … خدود، بالشباب، موردات\nومن فقد الشبيبة، فالغواني … له، عند الورود، مصردات\nهواجر في التيقظ أو عواص، … وفي طيف الكرى متعهدات\nإذا سهدنه بطويل هجر، … فما أجفانهن مسهدات\nخواطىء غير أسهمها خواط، … لكل كبيرة متعمدات\nتخالفت الغرائز والمعاني، … فكيف توافق المتجسدات؟\nفما بين المقابر نادبات؛ … ومابين الشروب مغردات\nقدحن زناد شوق من زنود، … بنار حليها متوقدات\nولم تنصف بياض الشيب أيد، … لوافد شيبهن مسودات\nتأخر أبيض الفودين ظلم، … إذا شمط القرائن واللدات\nتحيرت العقول، ما أساءت … دوائب في التقى، متهجدات\nوفي مهج الأنيس مثلثات، … على علاتها، وموحدات\nفما عذري، وعند الله علمي، … إذا كذبت قوائل مسندات؟\nفهل علمت بغيب، من أمور، … نجوم للمغيب معردات؟\nوليست بالقدائم، في ضميري، … لعمرك، بل حوادث موجدات\nفلو أمر الذي خلق البرايا، … تهاوت للدجى متسردات\nوأمسى الليث منها ليث غاب، … يجاذب، فرسه، المتوحدات\nوآض الفرغ، للساقين، فرغا، … تحاول، ماءه، المتوردات\nوهب يروم، سنبلة السواري، … خبير، والزرائع محصدات\nونال فريرها بمداه فار، … ذنوب ضيوفه متغمدات\nكأن نعامها، والله قاض، … نعائم بالفلاة مطردات\nوقد زعموا بأن لها عقولا، … وأقضية المليك مؤكدات\nوأن لبعضها لفظا، وفيها … حواسد، مثلنا، ومحسدات\nأتحملني إلى الغفران عيس، … على نص الوجيف، مؤجدات\nولا تخشى الخطوب مسبحات … بعزة ربهن، ممجدات\nأرى حسن الشمائل منك حثت … عليه الأيمن المتوسدات\nفإن الطبع يطمح بالمعالي؛ … وإن كلاب شرك موسدات"},{"id":"diwan-maarri:121","bookId":"diwan-maarri","type":"poem","seq":121,"chapter":"قصائد","title":"على الكذب اتفقنا فاختلفنا،","page":"","text":"على الكذب اتفقنا فاختلفنا، … ومن أسنى خلائقك الصموت\nوقد كذب الذي سمى وليدا: … يعيش، وبر من سمى: يموت"},{"id":"diwan-maarri:122","bookId":"diwan-maarri","type":"poem","seq":122,"chapter":"قصائد","title":"أيا طفل الشفيقة! إن ربي،","page":"","text":"أيا طفل الشفيقة! إن ربي، … على ما شاء من أمر، مقيت\nتكلم، بعد موتك، باعتبار، … وقد أودى بك النبأ المقيت\nتقول حللت عاجلتي، بكرهي، … فعشت وكم لددت وكم سقيت\nرقيت الحول، شهرا بعد شهر، … فليتي، في الأهلة، ما رقيت\nفلما صيح بي، ودنا فطامي، … تيممني الحمام، فما وقيت\nتركت الدار خالية، لغيري، … ولو طال المقام بها شقيت\nنقيت، فما دنست، ولو تمادت … حياة بي، دنست، فما نقيت\nوما يدريك باكيتي؟ عساني … لسكنى الفوز في الأخرى انتقيت\nرقتني الراقيات، وحم يومي، … فغادرني، كأني ما رقيت\nهبيني عشت عمر النسر فيها، … وكان الموت آخر ما لقيت\nفقيرا، فاستضمت، بلا اتقاء … لربي، أو أميرا فاتقيت\nومن صنع المليك إلي أني … تعجلت الرحيل، فما بقيت\nلو أني هضب شابة لارتقيت، … وماء، في القرارة، لاستقيت"},{"id":"diwan-maarri:123","bookId":"diwan-maarri","type":"poem","seq":123,"chapter":"قصائد","title":"أما المكان، فثابت لا ينطوي،","page":"","text":"أما المكان، فثابت لا ينطوي، … لكن زمانك ذاهب لا يثبت\nقال الغوي لقد كبت معاندي؛ … خسرت يداه بأي أمر يكبت\nوالمرء مثل النار شبت وانتهت، … فخبت، وأفلح في الحياة المخبت\nوحوادث الأيام مثل نباتها، … ترعى، ويأمرها المليك فتنبت\nوإذا الفتى كان التراب مآله، … فعلام تسهر أمه وتربت؟\nإن كانت الأحبار تعظم سبتها، … فأخو البصيرة كل يوم مسبت"},{"id":"diwan-maarri:124","bookId":"diwan-maarri","type":"poem","seq":124,"chapter":"قصائد","title":"قد أصبحت، ونعاتها نعاتها،","page":"","text":"قد أصبحت، ونعاتها نعاتها، … وكذلك الدنيا تخيب سعاتها\nكرارة أحزانها، ضرارة … سكانها، مرارة ساعاتها\nنامت دعاة الدولتين فضاعتا، … وهي المنية لا تخيب دعاتها\nذرها، وتلك نصيحة معروفة، … عظمت منافعها وقل وعاتها\nلا تتبعن الغانيات مماشيا، … إن الغواني جمة تبعاتها\nوإذا اطلعن من المناظر فالهدى … أن لا تراك، الدهر، مطلعاتها\nواحذر مقال الناس: إنك بينها … سرحان ضآن حين غاب رعاتها\nودع القراءة إن ظننت جهيرها، … ذكرت به الحاجات مستمعاتها\nفالصوت هدر الفحل تؤنس ركزه … ألافه، فتجيب ممتنعاتها\nأولى من البيض الأوانس، بالعلا، … قلص تجوب الليل مدرعاتها\nجمعت جسوم من غرائز أربع، … وتفرقت من بعد مجتمعاتها\nوهي النفوس، إذا تميز بينها، … فأعزها في العيش مقتنعاتها\nومتى طردت أمورها بقياسها، … فأحقها بمذلة طمعاتها\nوكأن آمال الفتى وحتوفه … فئتان، تهزأ منه مصطرعاتها\nأوقات عاجلة كأن مضيها … ومض البروق، خواطفا لمعاتها\nويخالف الأيام حكم واقع … فيها، ومثل سبوتها جمعاتها\nكم أوقدت لشموعها صبحية … في الليل ثم أطفئت شمعاتها\nفمتى ينبه من رقاد، مهلك، … من قد أضر، بعينه، هجعاتها\nوترادفت هذي الجدوب، ولم تلح … غراء، تبغي الروض منتجعاتها\nوكأن تسبيحا هديل حمامة، … في مجد ربك ألفت سجعاتها\nمن يغتبط بمعيشة، فأمامه … نوب، تطيل، عناءه، فجعاتها\nوإذا رجعت إلى النهى فذواهب … الأيام، غير مؤمل رجعاتها\nتهوى السلامة والقبور مضاجع … سلبت عن اليقظات مضطجعاتها\nدنياك مشبهة السراب، فلا تزل … برزين حلمك موشكا خدعاتها\nرقشاء فيها ليلها ونهارها، … تلك الضئيلة، شأنها لسعاتها\nوترث أغراض الشباب وينطوي … إبانها، فتنيب مرتدعاتها\nوينهنه الرجل الحصيف بسنه … أوطاره، فتضيق متسعاتها\nوتقارعت شوس الخطوب فكشفت، … عن مهلك الحيوان، مقترعاتها\nتستعذب المهجات ورد بقائها، … فتلذه، وتغصها جرعاتها\nوتظل حبات القلوب زرائعا، … كالأرض، والصهوات مزدرعاتها\nإن كان قد عتم الظلام، فطالما … متع النهار فماونت متعاتها\nنظمت قصائد من أذى، مثلاتها … أمثالها، فاتتك منتزعاتها\nوتعين أسباب الحياة وينتهي … أمد لها، فتخون منقطعاتها\nفاخفض حديثك للمحدث جاهدا، … فذميمة الأصوات مرتفعاتها\nمهج تخاف من الردى، ولعله، … إن جاء، تأمن صولة هلعاتها\nأو ما تفيق، من الغرام، بفارك … مشهورة، مع غيرنا وقعاتها\nنفس ترقع أمرها، حتى إذا … أجل تورد، أعجزت رقعاتها\nوترى الصلاة، على الغوي، ثقيلة، … مثل الهضاب تؤوده ركعاتها\nوتضل أفعال الشرور جناتها، … وتفوز بالخيرات مصطنعاتها\nومحاسن الدول،التي غرت بها، … حالت، فقبل حسانها شنعاتها\nوالنار، إن قربت كفك، مرة، … منها، ثنت عن قبضها لذعاتها\nولعل عكسا، في الليالي، كائن، … فتعود، في الشرقات، متضعاتها"},{"id":"diwan-maarri:125","bookId":"diwan-maarri","type":"poem","seq":125,"chapter":"قصائد","title":"بنت عن الدنيا، ولا بنت لي","page":"","text":"بنت عن الدنيا، ولا بنت لي … فيها، ولا عرس ولا أخت\nوقد تحملت، من الوزر، ما … تعجز أن تحمله البخت\nإن مدحوني، ساءني مدحهم، … وخلت أني، في الثرى، سخت\nجسمي أنجاس، فما سرني … أني، بمسك القول، ضمخت\nمن وسخ صاغ الفتى ربه، … فلا يقولن: توسخت!\nوالبخت في الأولى أنال العلا، … وليس في آخرة بخت\nكذاك قالوا، وأحاديثهم، … يبين فيها الجزل والشخت\nلو جاء من أهل البلى مخبر، … سألت عن قوم وأرخت:\nهل فاز بالجنة عمالها، … وهل ثوى في النار نوبخت؟\nوالظلم أن تلزم ما قد جنى، … عليك، بهرام وبيدخت\nوبعض ذا العالم من بعضه، … لولا إياة لم يكن فخت"},{"id":"diwan-maarri:126","bookId":"diwan-maarri","type":"poem","seq":126,"chapter":"قصائد","title":"وارحمتا للأنام كلهم،","page":"","text":"وارحمتا للأنام كلهم، … فإنهم من هوى الحياة أتوا\nأف لهم، ما أقل فطنتهم، … لذوا أكيلا، وإنما سئتوا\nغنوا من الجهل، في محافلهم، … ولو دروا ما تحملوا نأتوا"},{"id":"diwan-maarri:127","bookId":"diwan-maarri","type":"poem","seq":127,"chapter":"قصائد","title":"عليكم بإحسانكم، إنكم","page":"","text":"عليكم بإحسانكم، إنكم … متى تكبتوا غيركم تكبتوا\nيربي المعاشر أبناءهم، … ويشقى الأنام بما ربتوا\nوما الناس إلا نبات الزما … ن، فليحصد القوم ما نبتوا\nفيا للنصارى، إذا أمسكوا، … ويا لليهود، إذا أسبتوا\nوقد سئلوا عن عباداتهم ، … فما أيدوها، ولا ثبتوا\nومن خير ما فعل الفاعلون، … أنهم بتقى أخبتوا"},{"id":"diwan-maarri:128","bookId":"diwan-maarri","type":"poem","seq":128,"chapter":"قصائد","title":"أترغب في الصيت بين الأنام؟","page":"","text":"أترغب في الصيت بين الأنام؟ … وكم خمل النابه الصيت\nوحسب الفتى أنه مائت، … وهل يعرف الشرف الميت؟"},{"id":"diwan-maarri:129","bookId":"diwan-maarri","type":"poem","seq":129,"chapter":"قصائد","title":"يؤمل كل أن يعيش، وإنما","page":"","text":"يؤمل كل أن يعيش، وإنما … تمارس أهوال الزمان، إذا عشتا\nإذا افترقت أجزاء جسمي لم أبل، … حلول الرزايا في مصيف، ولا مشتا\nفرش معدما إن كان يمكن ريشه، … ولا تفخرن، بين الأنام، بما رشتا\nوإن فضت للأقوام بالمال والغنى، … فيا بحر أيقن بالنضوب وإن جشتا"},{"id":"diwan-maarri:130","bookId":"diwan-maarri","type":"poem","seq":130,"chapter":"قصائد","title":"أكرم ضعيفك، والآفاق مجدبة،","page":"","text":"أكرم ضعيفك، والآفاق مجدبة، … ولا تهنه، ولو أعطيته القوتا\nوجانب الناس تأمن سوء فعلهم، … وأن تكون لدى الجلاس ممقوتا\nلا بد من أن يذموا كل من صحبوا، … ولو أراهم حصى المعزاء ياقوتا\nوقض وقتك بالتقوى، تجوزه، … حتى تصادف يوما، فيه، موقوتا\nعنوان القصيدة : إن شئت أن ترزق الدنيا ونعمتها، … إن شئت أن ترزق الدنيا ونعمتها،\nفخل دنياك تظفر بالذي شيتا … أنشأت تطلب منها غير مسعفة،\nوما لها، أيها الإنسان، أنشيتا … فاخش المليك ولا توجد على رهب،\nإن أنت بالجن في الظلماء خشيتا … فإنما تلك أخبار ملفقة،"},{"id":"diwan-maarri:131","bookId":"diwan-maarri","type":"poem","seq":131,"chapter":"قصائد","title":"عيدان قيناتنا من تحت أرجلها،","page":"","text":"عيدان قيناتنا من تحت أرجلها، … وعود قينتكم، في حجرها، باتا\nوما حكين النصارى في لباسهم، … ولا بغين، كأهل السبت، إسباتا\nلكنهن حنيفات بمزعمنا، … ذكرننا الله تمجيدا، وإخباتا\nيثبتن ربا قديرا، لا كفاء له، … وما عمدن، لغير الله، إثباتا"},{"id":"diwan-maarri:132","bookId":"diwan-maarri","type":"poem","seq":132,"chapter":"قصائد","title":"يا صاح! إن حاورت آخر، مشفق","page":"","text":"يا صاح! إن حاورت آخر، مشفق … يبغي رشادك، جاهدا أن تسكتا\nكم بكت الموت الحريص على الذي … يأتي، فسحت مقلتاه، وبكتا\nقد زكت القدمان في غير الهدى، … ويداه عما حازه ما زكتا\nوالنفس شكت في يقين الأمر، وال … كفان، أن رمتا، قنيصا شكتا\nما انفكتا، ولديهما سبب المنى، … تتمسكان به إلى أن فكتا\nلم تشف ذنبي المكتان، وإن لي … شفتين، أخلاف المعيشة، مكتا"},{"id":"diwan-maarri:133","bookId":"diwan-maarri","type":"poem","seq":133,"chapter":"قصائد","title":"كادت سني، إذا نطقت، تقيم لي","page":"","text":"كادت سني، إذا نطقت، تقيم لي … شخصا يعارض بالعظات مبكتا\nوتقول: من بعث اللسان بغير ما … أرضى، فحق أن يهان ويسكتا"},{"id":"diwan-maarri:134","bookId":"diwan-maarri","type":"poem","seq":134,"chapter":"قصائد","title":"لا أخطب الدنيا إلى مالك الد","page":"","text":"لا أخطب الدنيا إلى مالك الد … نيا، ولكن خطبتي أختها\nالنفس فيها، وهي محسودة، … ذات شقاء، عدمت بختها\nوهي تقفي، بالردى، درها، … كما تقفت، بالردى، بختها\nما أم دفر أم طيب، ولو … أنك بالعنبر ضمختها"},{"id":"diwan-maarri:135","bookId":"diwan-maarri","type":"poem","seq":135,"chapter":"قصائد","title":"أي صفاة لا يرى دهرها","page":"","text":"أي صفاة لا يرى دهرها … يجيد، في مدته، نحتها\nكانوا زمانا فوق غبرائهم، … ثم استحالوا، فغدوا تحتها\nأودعهم ربهم سرها، … من بعد ما أطعمهم سحتها"},{"id":"diwan-maarri:136","bookId":"diwan-maarri","type":"poem","seq":136,"chapter":"قصائد","title":"أصمت الشهور، فهلا صمت،","page":"","text":"أصمت الشهور، فهلا صمت، … ولا صوم حتى تطيل الصموتا\nيلاقي الفتى عيشه بالضلال، … ويبقى عليه إلى أن يموتا"},{"id":"diwan-maarri:137","bookId":"diwan-maarri","type":"poem","seq":137,"chapter":"قصائد","title":"أخو الراح إن قال قولا وجدت،","page":"","text":"أخو الراح إن قال قولا وجدت، … أحسن مما يقول، الصموتا\nويشرب منها إلى أن يقيء، … ولا غرو إن قلت: حتى يموتا"},{"id":"diwan-maarri:138","bookId":"diwan-maarri","type":"poem","seq":138,"chapter":"قصائد","title":"يمر بك الزمن الدغفلي،","page":"","text":"يمر بك الزمن الدغفلي، … وكم فيه من رجل أسنتا\nفلا تسأل المرء عن سنه، … ولا ماله، واخش أن تعنتا\nولا تبغين لمحة، في الحياة، … إلى جارتيك إذا كنتا\nفلولا مخافة جن الشباب، … وسوء الغريزة، ما جنتا\nوحسبك من مخزيات الفعال … ما شكتا منك، أو ظنتا\nطربت لقمريتي مربع، … على غصني ضالة غنتا\nبدت لهما زهرات الربيع، … فأحسنتا القول، وافتنتا\nوتعذر نفسك عند الحنين؛ … وتعذل نفسك أن حنتا"},{"id":"diwan-maarri:139","bookId":"diwan-maarri","type":"poem","seq":139,"chapter":"قصائد","title":"عذيري من الدنيا عرتني بظلمها،","page":"","text":"عذيري من الدنيا عرتني بظلمها، … فتمنحني قوتي لتأخذ قوتي\nوجدت بها ديني دنيا، فضرني، … وأضللت منها في مروت مروتي\nأخوت، كما خاتت عقاب، لو انني … قدرت على أمر، فعد أخوتي\nوأصبحت، في تيه الحياة، مناديا، … بأرفع صوتي أين أطلب صوتي\nوما زال حوتي راصدي، وهو آخذي، … فما لمتابي ليس يغسل حوتي؟\nرآني رب الناس فيها متابعا … هواي، فويحي يوم أسكن هوتي\nوما برحت لي ألوة حرجية، … تصير، من رطب العضاه، ألوتي\nأبوتك يا إثمي، ومن لي بأنني … أتيتك، فاشكر، لا شكرت، أبوتي"},{"id":"diwan-maarri:140","bookId":"diwan-maarri","type":"poem","seq":140,"chapter":"قصائد","title":"لقد رجت الله النفوس لكشفه","page":"","text":"لقد رجت الله النفوس لكشفه … أمورا، فأعطى أنفسا ما ترجت\nفإن تنجك الخيل المعدة للوغى، … فعن قدر، يأتي من الله، نجت\nوشتان قتلى في التراب شجاجها، … ومقتولة، بين المجالس، شجت"},{"id":"diwan-maarri:141","bookId":"diwan-maarri","type":"poem","seq":141,"chapter":"قصائد","title":"نوائب، إن جلت تجلت سريعة،","page":"","text":"نوائب، إن جلت تجلت سريعة، … وإما توالت في الزمان تولت\nودنياك، إن قلت أقلت، وإن قلت، … فمن قلت في الدين نجت، وعلت\nغلت، وأغالت، ثم غالت، وأوحشت … وحشت وحاشت واستمالت وملت\nوصلت بنيران، وصلت سيوفها، … وسلت حساما من أذاة، وسلت\nأزالت، وزلت بالفتى عن مقامه، … وحلت، فلما أحكم العقد حلت"},{"id":"diwan-maarri:142","bookId":"diwan-maarri","type":"poem","seq":142,"chapter":"قصائد","title":"قديما كرهت الموت، والله شاهد،","page":"","text":"قديما كرهت الموت، والله شاهد، … وقد عشت حتى أسمحت لي قرونتي\nوأحسبه لو جاءني لأبيته، … ومن عند ربي نصرتي ومعونتي\nإذا أنا واراني التراب، فخلني … وما أنا فيه، قد كفيت مؤونتي"},{"id":"diwan-maarri:143","bookId":"diwan-maarri","type":"poem","seq":143,"chapter":"قصائد","title":"هي الراح تلقي الرمح من راحة الفتى،","page":"","text":"هي الراح تلقي الرمح من راحة الفتى، … وتبدل منه كفه عود ناكت\nوقد وثبت في بزلها وثب حية، … وما قتلت إلا بأسود ساكت"},{"id":"diwan-maarri:144","bookId":"diwan-maarri","type":"poem","seq":144,"chapter":"قصائد","title":"أفارس مقنب، وأمير مصر،","page":"","text":"أفارس مقنب، وأمير مصر، … نزلت عن الكميت إلى الكميت\nفتلك حميدة آدتك حيا؛ … وهذي أشعرتك خفوت ميت"},{"id":"diwan-maarri:145","bookId":"diwan-maarri","type":"poem","seq":145,"chapter":"قصائد","title":"إذا لم يكن خلفي كبير يضيعه","page":"","text":"إذا لم يكن خلفي كبير يضيعه … حمامي، ولا طفل، ففيم حياتي؟\nوما العيش إلا علة برؤها الردى، … فخلي سبيلي أنصرف لطياتي"},{"id":"diwan-maarri:146","bookId":"diwan-maarri","type":"poem","seq":146,"chapter":"قصائد","title":"ألا تتقون الله رهط مسلم!","page":"","text":"ألا تتقون الله رهط مسلم! … فقد جرتم في طاعة الشهوات\nولا تتبعوا الشيطان في خطواته، … فكم فيكم من تابع الخطوات\nعمدتم لرأي المثنوية، بعدما … جرت لذة التوحيد في اللهوات\nومن دون ما أبديتم خضب القنا، … ومار نجيع الخيل في الهبوات\nفما استحسنت هذي البهائم فعلكم، … من الغي، في الأمات والحموات\nوأيسر ما حللتم نحر ذارع، … يعمكم بالسكر والنشوات\nجعلتم عليا جنة، وهو لم يزل، … يعاقب، من خمر، على حسوات\nسألنا مجوسا عن حقيقة دينها؛ … فقالت: نعم لا ننكح الأخوات\nوذلك في أصل التمجس جائز، … ولكن عددناه من الهفوات\nونأبى فظيعات الأمور، ونبتغي … سجودا لنور الشمس في الغدوات\nوأعذر من نسوانكم، في احتمالها … فضوح الرزايا، آتن الفلوات\nفلا تجعلوا فيها الغوي مسلطا، … كما سلط البازي على القطوات\nتهاونتم، بالذكر، لما أتاكم، … ولم تحفلوا بالصوم والصلوات\nرجوتم إماما، في القران، مضللا، … فلما مضى قلتم إلى سنوات\nكذاك بنو حواء: بر وفاجر؛ … ولا بد للأيام من هنوات"},{"id":"diwan-maarri:147","bookId":"diwan-maarri","type":"poem","seq":147,"chapter":"قصائد","title":"للشامتين رزايا في شماتهم،","page":"","text":"للشامتين رزايا في شماتهم، … فكن مصابا ولا تحسب من الشمت\nيبدو سرور أناس أظهروا حزنا، … وإن تستر خلف الألسن الصمت\nأمير قوم أصابته منيته؛ … فضل من قال: إن المرء لم يمت"},{"id":"diwan-maarri:148","bookId":"diwan-maarri","type":"poem","seq":148,"chapter":"قصائد","title":"خلصت من سبرات في السباريت،","page":"","text":"خلصت من سبرات في السباريت، … ورب يوم كريت دون تكريت\nكم بالسماوة من صل ومن أسد، … كلاهما خص في شدق بتهريت\nما زرت دارك حتى شفني تعبي، … وخارت العيس في آثار خريت\nوالخير في الأرض، كالأترج منبته، … وألزم الشر تدخينا بكبريت"},{"id":"diwan-maarri:149","bookId":"diwan-maarri","type":"poem","seq":149,"chapter":"قصائد","title":"الحمد لله قد أصبحت في دعة،","page":"","text":"الحمد لله قد أصبحت في دعة، … أرضى القليل ولا أهتم بالقوت\nوشاهد خالقي أن الصلاة، له، … أجل عندي من دري وياقوتي\nولا أعاشر أهل العصر، إنهم، … إن عوشروا بين محبوب وممقوت\nيسير بي وبغيري الوقت مبتدرا، … إلى محل، من الآجال، موقوت"},{"id":"diwan-maarri:150","bookId":"diwan-maarri","type":"poem","seq":150,"chapter":"قصائد","title":"إدفن أخا الملك دفن المرء مفتقرا،","page":"","text":"إدفن أخا الملك دفن المرء مفتقرا، … ما كان يملك من بيت ولا بيت\nإن التوابيت أجداث مكررة، … فجنب القوم سجنا في التوابيت\nواردد إلى الأم شبحا طال معهدها … بضمه، وهي لا ترجى لتربيت"},{"id":"diwan-maarri:151","bookId":"diwan-maarri","type":"poem","seq":151,"chapter":"قصائد","title":"راعتك دنياك، من ريع الفؤاد، وما","page":"","text":"راعتك دنياك، من ريع الفؤاد، وما … راعتك في العيش، من حسن المراعاة\nكأنما اليوم عبد طالب أمة … من ليلة، قد أجدا في المساعاة\nوأمك السوء لم تحفظك في سبب، … لا بل أضاعتك أصناف الاضاعات\nتبني المنازل أعمار مهدمة، … من الزمان، بأنفاس وساعات\nإن شئت إبليس أن تلقاه منصلتا … بالسيف يضرب، فاعمد للجماعات\nتجدهم في أقاويل مخالفة … وجه الصواب، وأسرار مذاعات\nيباكرون بألباب، وإن خلصت، … معصية، وبأهواء مطاعات\nقالوا وقلنا، دعاو ما تفيد لنا … إلا الأذى واختصاما في المداعات\nتكسب الناس بالأجسام، فامتهنوا … أرواحهم بالرزايا في الصناعات\nوحاولوا الرزق بالأفواه، فاجتهدوا … في جذب نفع بنظم أو سجاعات"},{"id":"diwan-maarri:152","bookId":"diwan-maarri","type":"poem","seq":152,"chapter":"قصائد","title":"مر الزمان فأضحى في الثرى جسد؛","page":"","text":"مر الزمان فأضحى في الثرى جسد؛ … فهل تملى رجال بالملاوات؟\nوالروح أرضية في رأي طائفة، … وعند قوم ترقى في السماوات\nتمضي على هيئة الشخص الذي سكنت … فيه، إلى دار نعمى أو شقاوات\nوكونها في طريح الجسم أحوجها … إلى ملابس، عنتها، وأقوات\nوقدرة الله حق، ليس يعجزها … حشر لخلق، ولا بعث لأموات\nفاعجب لعلوية الأجرام صامتة، … فيما يقال، ومنها ذات أصوات\nولا تطيعن قوما، ما ديانتهم … إلا احتيال على أخذ الإتاوات\nوإنما حمل التوراة قارئها … كسب الفوائد، لا حب التلاوات\nإن الشرائع ألقت بيننا إحنا، … وأودعتنا أفانين العداوات\nوهل أبيحت نساء القوم عن عرض، … للعرب، إلا بأحكام النبوات؟"},{"id":"diwan-maarri:153","bookId":"diwan-maarri","type":"poem","seq":153,"chapter":"قصائد","title":"الكون في جملة العوافي؛","page":"","text":"الكون في جملة العوافي؛ … لا الكون في جملة العفاة\nلين الثرى، للجسوم، خير … من صحبة العالم الجفاة\nقد خفت القوم، فاستراحوا؛ … آه من الصمت والخفات\nلم يبق، للظاعنين، عين … تبكي على الأعظم الرفات\nأرى انكفاتي، إلى المنايا، … أغنى عن الأسرة الكفاة\nأثبت لي خالقا حكيما، … ولست من معشر نفاة\nخبطت في حندس مقيم، … وأعجزت علتي شفاتي\nفمن تراب إلى تراب، … ومن سفاة إلى سفاة\nنعوذ بالله من غوان، … يكن باللب معصفات\nومن صفات النساء، قدما، … أن لسن في الود منصفات\nوما يبين الوفاء، إلا … في زمن الفقد والوفاة\nكم ودع الناس من خليل … سار، فما هم بالتفات"},{"id":"diwan-maarri:154","bookId":"diwan-maarri","type":"poem","seq":154,"chapter":"قصائد","title":"دنياك موموقة","page":"","text":"دنياك موموقة … أكثر من أختها\nلم تبق، من جزلها، … شيئا ولا شختها\nأتى على ذرها الآ … تي على بختها\nفانظر إلى صنعها؛ … وانظر إلى بختها"},{"id":"diwan-maarri:155","bookId":"diwan-maarri","type":"poem","seq":155,"chapter":"قصائد","title":"خذي رأيي، وحسبك ذاك مني،","page":"","text":"خذي رأيي، وحسبك ذاك مني، … على ما في من عوج وأمت\nوماذا يبتغي الجلساء عندي، … أرادوا منطقي وأردت صمتي\nويوجد بيننا أمد قصي، … فأموا سمتهم وأممت سمتي\nفإن القر يدفع لابسيه … إلى يوم، من الأيام، حمت\nأرى الأشياء تجمعها أصول؛ … وكم في الدهر من ثكل وشمت\nهو الحيوان من إنس ووحش؛ … وهن الخيل من دهم وكمت"},{"id":"diwan-maarri:156","bookId":"diwan-maarri","type":"poem","seq":156,"chapter":"قصائد","title":"ترنم في نهارك، مستعينا","page":"","text":"ترنم في نهارك، مستعينا … بذكر الله، في المترنمات\nعنيت بها القوارح، وهي غر، … ولسن بخيلك المتقدمات\nيبتن، بكل مظلمة وفج، … على حوض الردى متهجمات\nإذا السبح الجياد أرحن وقتا، … حملنك مسرجات ملجمات\nوهينم، والظلام عليك داج، … لدى ورق سمعن مهينمات\nولا ترجع، بإيماء، سلاما … على بيض أشرن مسلمات\nألات الظلم جئن بشر ظلم، … وقد واجهننا متظلمات\nفوارس فتنة، أعلام غي، … لقينك بالأساور معلمات\nوسام ما اقتنعن بحسن أصل، … فجئنك بالخضاب موسمات\nرأين الورد في الوجنات حيما، … فغادين البنان معنمات\nوشنفن المسامع قائلات؛ … وكلمن القلوب مكلمات\nأزمن لجهلهن حصى بدر؛ … غرائب لم يكن مثلمات\nأجازين التراب، عن البرايا، … بأكل شخوصها المتجسمات؟\nنقعن بماء زمزم، لانصارى … ولا مجسا، يظلن مزمزمات\nوقد يصبحن عن بر ونسك، … بأطيب عنبر متنسمات\nكأن خواتم الأفواه فضت … عن الصهب العذاب، مختمات\nكؤوس من أجل الراح قدرا، … ولكن ما يزلن مفدمات\nيكاد الشرب لا يبليه عصر، … إذا باشرنه متلثمات\nثنتهن الجماجم من مراد، … بشيب، فانثنين مجمجمات\nخمور الريق لسن بكل حال … على طلابهن محرمات\nولكن الأوانس باعثات … ركابك في مهالك مقتمات\nصحبنك فاستفدت بهن ولدا … أصابك من أذاتك بالسمات\nومن رزق البنين فغير ناء، … بذلك، عن نوائب مسقمات\nفمن ثكل يهاب ومن عقوق … وأرزاء يجئن مصممات\nوإن نعط الإناث، فأي بؤس … تبين في وجوه مقسمات\nيردن بعولة ويردن حليا، … ويلقين الخطوب ملومات\nولسن بدافعات يوم حرب، … ولا في غارة متغشمات\nودفن، والحوادث فاجعات، … لإحداهن، إحدى المكرمات\nوقد يفقدن أزواجا كراما، … فيا للنسوة المتأيمات!\nيلدن أعاديا، ويكن عارا، … إذا أمسين في المتهضمات\nيرعنك، إن خدمن بغير فن، … إذا رحن العشي مخدمات\nوأما الخمر، فهي تزيل عقلا، … فتحت به مغالق مبهمات\nولو ناجتك أقداح الندامى، … عدت عن حملها متندمات\nتذيع السر من حر وعبد، … وتعرب عن كنائز معجمات\nوينفض إلفها الراحات، حتى … تعود من النفائس معدمات\nوزينت القبيح، فباشرته … نفوس كن عنه مخزمات\nويشربها، فيقلسها، غوي؛ … لقد شام الخفي من الشمات\nويرفع شربها لغطا بجهل؛ … كأسراب وردن مسدمات\nلعل الربد عجن لها بربع، … فإضن من السفاه مصلمات\nأو الغربان ملن لها ببيض، … نواصع، فانثنين محممات\nفإن هلكت خروسك أم ليلى، … فما أنا من صحابك واللمات\nفعنك تعود أبنية المعالي، … وأطلال النهى متهدمات\nوقد يضحي صحاتك أهل سجن، … وتلقين الكؤوس محطمات\nولا تخبر شؤونك، واجعلنها … سرائر، في الضمير، مكتمات\nفإن السر في الخلدين ميت، … أخو لحدين، بين مقسمات\nوما الجارات إلا جاريات … بعيبك، إن وجدن مهيمات\nفلا تسأل: أهند أم لميس … ثوت في النسوة المتخيمات\nولا ترمق بعينك رائحات، … إلى حمامهن، مكممات\nفكم حلت عقود النظم وهنا … عقودا للرشاد منظمات\nوكم جنت المعاصم من معاص، … تعود بها المعاضد معصمات\nومن عاشرت من إنس، فحاذر … غوائل، مرد متهكمات\nمتى يطمعن فيك، يرين، تيها، … لأطيب مطعم متأجمات\nويرفعن المقال، عليك، جهلا، … وينفذن الذخائر مغرمات\nتوهمن الظنون، فكن نارا … لما أشعرنه متوهمات\nإذا زين في أيام حفل، … بدت خيل المريد مسومات\nفغر زهر الحجال ولا تغرها، … فتسمح بالدموع مسجمات\nوليس عكوفهن، على المصلى، … أمانا عن غوار مجرمات\nولا تحمد حسانك، إن توافت … بأيد، للسطور، مقومات\nفحمل مغازل النسوان أولى، … بهن، من اليراع مقلمات\nسهام، إن عرفن كتاب لسن … رجعن، بما يسوء، مسممات\nويتركن الرشيد بغير لب، … أتين لهديه متعلمات\nوإن جئن المنجم سائلات، … فلسن عن الضلال بمنجمات\nليأخذن التلاوة عن عجوز، … من اللائي فغرن مهتمات\nيسبحن المليك بكل جنح، … ويركعن الضحى متأثمات\nفما عيب، على الفتيات، لحن، … إذا قلن المراد مترجمات\nولا يدنين من رجل ضرير، … يلقنهن آيا محكمات\nسوى من كان مرتعشا يداه، … ولمته من المتثغمات\nوإن طاوعن أمرك، فانه غيدا … يزرن عرائسا متيممات\nأخذن كريش طاووس لباسا، … ومسكا بالضحى متلغمات\nوأبعدهن من ربات مكر، … سواحر، يغتدين معزمات\nيقلن نهيج الغياب، حتى … يجيئوا بالركاب مزممات\nونعطف هاجر الخلان، كيما … يزول عن السجايا المسئمات\nوجمع طوائف العمار سهل … علينا، بالجوالب موذمات\nزعمن بأن، في مغنى فقير، … كنوزا للملوك مصتمات\nفلا يدخلن دارك باختيار، … فقد ألفيتهن مذممات\nوإن خالسن غرتك ارتقابا، … فحق أن يرحن مشتمات\nوساو لديك أتراب النصارى، … وعينا من يهود، ومسلمات\nومن جاورت من حنف وسرب … صوابىء، فليبن مكرمات\nفإن الناس كلهم سواء، … وإن ذكت الحروب مضرمات\nولا يتأهلن شيخ، مقل، … بمعصرة من المتنعمات\nفإن الفقر عيب، إن أضيفت … إليه السن، جاء بمعظمات\nولكن عرس ذلك بنت دهر، … تجنبت الوجوه محممات\nمن اللائي، إذا لم يجد عام، … تفوقن الحوادث معدمات\nمن الشمط اعتزلن بكل عود، … وأفنين السنين مجرمات\nويغتفر الغنى وخطا برأس، … إذا كانت قواك مسلمات\nوواحدة كفتك، فلا تجاوز … إلى أخرى، تجيء بمؤلمات\nوإن أزعمت صاحبة بضر، … فأجدر أن تروع بمعرمات\nزجاج، إن رفقت به، وإلا … رأيت ضروبه متقصمات\nوصن في الشرخ نفسك عن غوان … يزرن مع الكواكب معتمات\nفقد يسري الغوي، إلى مخاز، … بجنح في سحائب منجمات\nوما حفظ الخريدة مثل بعل، … تكون به من المتحرمات\nيحوط ذمارها من كل خطب، … ويمنعها مصاعب مقرمات\nإذا الغاران غرتهما بحل، … فدينك بالتورع والصمات\nفهذا قول مختبر شفيق، … ونصح للحياة وللممات\nطبائع أربع جشمن أمرا، … فإضن، لحمله، متجشمات\nوأرواح سوالك، في جسوم، … يهن بأن يرين مجسمات"},{"id":"diwan-maarri:157","bookId":"diwan-maarri","type":"poem","seq":157,"chapter":"قصائد","title":"رويدك يا سحابة لا تجودي،","page":"","text":"رويدك يا سحابة لا تجودي، … على السبخات، من جهل، هميت\nطلبت ديانة بين البرايا، … لقد أشوت سهامك إذ رميت\nتزيوا بالتصوف، عن خداع، … فهل زرت الرجال، أو اعتميت؟\nوقاموا في تواجدهم، فداروا، … كأنهم ثمال من كميت\nوما رقصوا حذارا من إله، … ولا يبغون إلا ما حميت\nوجدت الناس ميتا مثل حي، … بحسن الذكر، أو حيا كميت"},{"id":"diwan-maarri:158","bookId":"diwan-maarri","type":"poem","seq":158,"chapter":"قصائد","title":"كفي شموسك، فالسرار أمانة،","page":"","text":"كفي شموسك، فالسرار أمانة، … حملتها، ومتى ثملت رميتها\nما أم ليلاك العتيقة برة، … كنيتها للقوم، أو سميتها\nوهي القتيلة، لم تؤذ بقتلها، … أصمتك، من عرض، وما أصميتها\nوعلى كرام الشرب نمت بالذي … يخفونه، وإلى الكروم نميتها\nوكأنما هي، من ذكاء، نطفة … صفقتها، وبلؤلؤ أطميتها\nوشججتها حمراء، غير مبينة … وضحا يرى في ناصع أدميتها\nومدامة، في راحتيك، بذلتها، … كمدامة، في عارضيك، حميتها\nفتكت بشاربها السلافة عنوة، … حتى ثنت حي النفوس كميتها\nحملت كميتا تحت أدهم لم يزل، … في الأشهبين، مقصرا بكميتها"},{"id":"diwan-maarri:159","bookId":"diwan-maarri","type":"poem","seq":159,"chapter":"قصائد","title":"قد حاطت، الزوج، حرة سألت","page":"","text":"قد حاطت، الزوج، حرة سألت … مليكها العون في حياطتها\nغدت ببرس إلى مرادنها، … أو خيط غزل إلى خياطتها\nأماطت السوء عن ضمائرها، … فلاقت الخير في إماطتها"},{"id":"diwan-maarri:160","bookId":"diwan-maarri","type":"poem","seq":160,"chapter":"قصائد","title":"إنما نحن في ضلال وتعلي","page":"","text":"إنما نحن في ضلال وتعلي … ل، فإن كنت ذا يقين فهاته\nولحب الصحيح آثرت الرو … م انتساب الفتى إلى أمهاته\nجهلوا من أبوه، إلا ظنونا، … وطلى الوحش لاحق بمهاته\nقد يحوز الخب الشحيح جبا الما … ء، ولا يستحق نضح لهاته\nوكثير له، إذا قيست الأش … ياء، عظم يرميه بعض طهاته\nرئس الناس بالدهاء، فما ين … فك جيل ينقاد طوع دهاته"},{"id":"diwan-maarri:161","bookId":"diwan-maarri","type":"poem","seq":161,"chapter":"قصائد","title":"من صفة الدنيا التي أجمع النا","page":"","text":"من صفة الدنيا التي أجمع النا … س عليها، أنها ما صفت\nكم عفة ما عف عنها الردى؛ … وكم ديار لأناس عفت\nالتفت الآمال منا بها، … وقد مضى آملها ما التفت\nيا شفة همت برشف لها، … فانتزعت أكؤسها، ما شفت\nخفت لها نفس الفتى، جاهدا، … وبينما يدأب فيها خفت\nلو أنها تسكن في مثلها، … لكلفت فوق الذي كلفت\nوالأرض غذتنا بألطافها، … ثم تغذتنا، فهل أنصفت؟\nتأكل من دب على ظهرها، … وهي على رغبتها ما اكتفت\nأتنتفي منا لآثامنا، … وخلتها لو نطقت لانتفت"},{"id":"diwan-maarri:162","bookId":"diwan-maarri","type":"poem","seq":162,"chapter":"قصائد","title":"نفوس تشابه أصحابها،","page":"","text":"نفوس تشابه أصحابها، … عتوا في زمانهم، إذ عتت\nوما يرتضي اللب عند البيان، … لا ما أتوه ولا ما أتت"},{"id":"diwan-maarri:163","bookId":"diwan-maarri","type":"poem","seq":163,"chapter":"قصائد","title":"عذيري من صورة قد عثت؛","page":"","text":"عذيري من صورة قد عثت؛ … ومن كف دافنها، إذ حثت\nونفس تمنت لذيذ الطعام، … فلما أصابت مناها غثت\nوجاثت لدى حاكم خصمها، … ومن غير حق لعمري جثت\nفلا ترثين لها، إنها … لجسمك، في ضعفه، ما رثت"},{"id":"diwan-maarri:164","bookId":"diwan-maarri","type":"poem","seq":164,"chapter":"قصائد","title":"ثيابي أكفاني، ورمسي منزلي،","page":"","text":"ثيابي أكفاني، ورمسي منزلي، … وعيشي حمامي، والمنية لي بعث\nتحلي بأسنى الحلي، واحتلبي الغنى، … فأفضل من أمثالك النفر الشعث\nيسيرون، بالأقدام، في سبل الهدى، … إلى الله، حزن ما توطأن أو وعث\nوما في يد قلب، ولا أسؤق برى، … ولا مفرق تاج، ولا أذن رعث"},{"id":"diwan-maarri:165","bookId":"diwan-maarri","type":"poem","seq":165,"chapter":"قصائد","title":"وغانية في دار أشوس ظالم،","page":"","text":"وغانية في دار أشوس ظالم، … تسور مما لم يجب وترعث\nيصاغ لها، في حليها، أيم عسجد؛ … فهل أمنت من لدغه حين تبعث؟"},{"id":"diwan-maarri:166","bookId":"diwan-maarri","type":"poem","seq":166,"chapter":"قصائد","title":"أيا جسدي لا تجزعن من البلى،","page":"","text":"أيا جسدي لا تجزعن من البلى، … إذا صرت في الغبراء، تحثى، وتنبث\nوإن كان هذا الجسم قبل افتراقه … خبيثا، فإن الفعل شر وأخبث\nمناكب ساعاتي ركبت، فأبتغي … لباثا،وسير الدهر لا يتلبث\nنهار وليل عوقبا، أنا فيهما … كأني، بخيطي باطل، أتشبث\nأظن زماني، كونه وفساده، … وليدا، بترب الأرض يلهو ويعبث"},{"id":"diwan-maarri:167","bookId":"diwan-maarri","type":"poem","seq":167,"chapter":"قصائد","title":"من أحسن الدهر وقتا ساعة سلمت","page":"","text":"من أحسن الدهر وقتا ساعة سلمت … من الشرور، وفيها صاحب حدث\nأعجب بدهرك أولاه وآخره؛ … إن الزمان قديم، سنه حدث\nأودى رداه بأجيال، فكم حفرت … أجداث قوم ولم يحفر له جدث"},{"id":"diwan-maarri:168","bookId":"diwan-maarri","type":"poem","seq":168,"chapter":"قصائد","title":"من أعجب الأشياء في دهرنا،","page":"","text":"من أعجب الأشياء في دهرنا، … والله لا ناس، ولا والث\nاثنان باتا في فراش معا، … فأصبحا، بينهما ثالث"},{"id":"diwan-maarri:169","bookId":"diwan-maarri","type":"poem","seq":169,"chapter":"قصائد","title":"لقد لقي المرء، من دهره،","page":"","text":"لقد لقي المرء، من دهره، … عجائب يغلثها الغالث\nوكم بات ثاني عرس له، … فأصبح بينهما ثالث"},{"id":"diwan-maarri:170","bookId":"diwan-maarri","type":"poem","seq":170,"chapter":"قصائد","title":"لا يرهب الموت من كان امرأ فطنا،","page":"","text":"لا يرهب الموت من كان امرأ فطنا، … فإن، في العيش، أرزاء وأحداثا\nوليس يأمن قوم شر دهرهم، … حتى يحلوا، ببطن الأرض، أجداثا"},{"id":"diwan-maarri:171","bookId":"diwan-maarri","type":"poem","seq":171,"chapter":"قصائد","title":"إذا مت لم أحفل بما الله صانع","page":"","text":"إذا مت لم أحفل بما الله صانع … إلى الأرض، من جدب وسقي غيوث\nوما تشعر الغبراء ماذا تجنه: … أأعظم ضأن أم عظام ليوث"},{"id":"diwan-maarri:172","bookId":"diwan-maarri","type":"poem","seq":172,"chapter":"قصائد","title":"تقل جسومنا أقدام سفر،","page":"","text":"تقل جسومنا أقدام سفر، … مشت في ليل داجية بوعث\nوظاهر أمرنا عيش وموت، … ويدأب ناسك لرجاء بعث\nفما رجل مخلدة بحجل؛ … ولا أذن منعمة برعث"},{"id":"diwan-maarri:173","bookId":"diwan-maarri","type":"poem","seq":173,"chapter":"قصائد","title":"أراني في الثلاثة من سجوني،","page":"","text":"أراني في الثلاثة من سجوني، … فلا تسأل عن الخبر النبيث\nلفقدي ناظري، ولزوم بيتي، … وكون النفس في الجسد الخبيث"},{"id":"diwan-maarri:174","bookId":"diwan-maarri","type":"poem","seq":174,"chapter":"قصائد","title":"لا خير في الدنيا، وإن ألهى الفتى،","page":"","text":"لا خير في الدنيا، وإن ألهى الفتى، … فيها، مثان أيدت بمثالث\nشر الحياة بسيطة، مذمومة، … عمدت لها، بالسوء، كف الغالث\nوسلامة كسلامة الجزء الذي، … بالضرب، لز من الطويل الثالث"},{"id":"diwan-maarri:175","bookId":"diwan-maarri","type":"poem","seq":175,"chapter":"قصائد","title":"أكرهت أن يدعى وليدك حارثا؟","page":"","text":"أكرهت أن يدعى وليدك حارثا؟ … يا حارث ابن الحارث ابن الحارث\nتلك الصفات لكل من وطىء الحصى … ما بين موروث وآخر وارث"},{"id":"diwan-maarri:176","bookId":"diwan-maarri","type":"poem","seq":176,"chapter":"قصائد","title":"لما ثوت في الأرض، وهي لطيفة،","page":"","text":"لما ثوت في الأرض، وهي لطيفة، … قدماؤنا أمنت من الأحداث\nلم يستريحوا من شرور ديارهم، … إلا برحلتهم إلى الأجداث"},{"id":"diwan-maarri:177","bookId":"diwan-maarri","type":"poem","seq":177,"chapter":"قصائد","title":"لو نطق الدهر في تصرفه،","page":"","text":"لو نطق الدهر في تصرفه، … لعدنا، كلنا، من التفث\nقال لنا: إنني أحج إلى الل … ه، وأنتم من أقبح الرفث\nنفثتكم مرة، على غلط … مني، فهل تعذرون في النفث؟"},{"id":"diwan-maarri:178","bookId":"diwan-maarri","type":"poem","seq":178,"chapter":"قصائد","title":"أيا أرض فوقك أهل الذنوب،","page":"","text":"أيا أرض فوقك أهل الذنوب، … فهل بك من ذاك هم وبث\nوقد زعموا النار مبعوثة، … تهذب، ممن عليك، الخبث\nوسيان ماض قصير المدى، … وآخر باق، طويل اللبث\nوخلقك، من ربنا، حكمة، … لقد جل عن لعب أو عبث\nوهل يحفل الجسم، في رمسه، … إذا جاءه حافر، فانتبث؟"},{"id":"diwan-maarri:179","bookId":"diwan-maarri","type":"poem","seq":179,"chapter":"قصائد","title":"حظوظ: فربع يخطى الغمام؛","page":"","text":"حظوظ: فربع يخطى الغمام؛ … وربع يجاد؛ وربع يدث\nوكم حدث، من صروف الزمان، … يكرهه شيخنا، والحدث\nمراس الأذى، ولباس الضنى، … وسقي الحمام، وسكنى الجدث"},{"id":"diwan-maarri:180","bookId":"diwan-maarri","type":"poem","seq":180,"chapter":"قصائد","title":"رأيت سحابا خلته متدفقا،","page":"","text":"رأيت سحابا خلته متدفقا، … فأنجم، لم يمطر، وإن حسن الخرج\nوكم فاتك الشيء، الذي كنت راجيا؛ … وجاءك، بالمقدار، ما لم تكن ترجو"},{"id":"diwan-maarri:181","bookId":"diwan-maarri","type":"poem","seq":181,"chapter":"قصائد","title":"لقد جاءنا هذا الشتاء، وتحته","page":"","text":"لقد جاءنا هذا الشتاء، وتحته … فقير معرى، أو أمير مدوج\nوقد يرزق المجدود أقوات أمة؛ … ويحرم، قوتا، واحد، وهو أحوج\nولو كانت الدنيا عروسا وجدتها، … بما قتلت أزواجها، لا تزوج\nفعج يدك اليمنى لتشرب طاهرا، … فقد عيف، للشرب، الإناء المعوج\nعلى سفر هذا الأنام، فخلنا، … لأبعد بين واقع، نتحوج\nولا تعجبن من سالم؛ إن سالما … أخو غمرة، في زاخر يتموج\nوهل هو إلا رائد لعشيرة، … يلاحظ برقا في الدجى يتبوج\nولولا دفاع الله لاقى من الأذى، … كما كان لاقى خامد ومتوج\nإذا وقي الإنسان، لم يخش حادثا؛ … وإن قيل هجام على الحرب أهوج\nوإن بلغ المقدار لم ينج سابح، … ولو أنه في كبة الخيل أعوج\nفلا تشهرن سيفا لتطلب دولة، … فأفضل ما نلت اليسير المروج"},{"id":"diwan-maarri:182","bookId":"diwan-maarri","type":"poem","seq":182,"chapter":"قصائد","title":"جماجم أمثال الكرات، هفت بها،","page":"","text":"جماجم أمثال الكرات، هفت بها، … سيوف، ثناها الضرب، وهي صوالج\nوقد يغلق الانسان من دون شخصه … ولاجا، وهم القلب في النفس والج\nلعمري! لقد حلت وكورا حمائم، … ليالي ضاقت عن ظباء توالج\nأؤمل عفو الله، والصدر جائش، … إذا خلجتني، للمنون، الخوالج\nهناك تود النفس أن ذنوبها … قليل، وأن القدح، بالخير، فالج\nوينسي، أخا الأشواق، رملة عالج … ويبرين، من هول الردى، ما يعالج\nسيأكل هذا الترب أعضاء بادن؛ … وتورث أحجال لها، ودمالج\nويصمي الفتى سهم من الدهر صائب، … وإن صرفت عنه السهام الزوالج"},{"id":"diwan-maarri:183","bookId":"diwan-maarri","type":"poem","seq":183,"chapter":"قصائد","title":"إذا درجت، في العالمين، قبيلة،","page":"","text":"إذا درجت، في العالمين، قبيلة، … فخير لها، من أن تئث، خروجها\nفما أمنت نسوان قوم أعزة، … على عزها، أن تستباح فروجها\nوما تمنع الخود الحصان حصونها، … ولو أن أبراج السماء بروجها\nفما عرجت، في شأوها، أم جندب، … ولا عقلتها شاؤها وعروجها\nتذال كراسي الملوك، وطالما … غدت وهي تحمى بالعوالي مروجها\nعلى الإبل، حتى ما تقل رجالها، … وبالخيل، حتى أثقلتها سروجها\nوما علمت روح بجسمي دخولها … إليه، فهل يخفى عليه خروجها؟"},{"id":"diwan-maarri:184","bookId":"diwan-maarri","type":"poem","seq":184,"chapter":"قصائد","title":"روح ذبيحك، لا تعجله ميتته،","page":"","text":"روح ذبيحك، لا تعجله ميتته، … فتأخذ النحض منه، وهو يختلج\nهذا قبيح، وعلمي، غير متسق، … بما يكون، ولكن في الثرى ألج\nوالناس من أجل هذا الأمر في ظلم، … وما أؤمل أن الفجر ينبلج\nمضى أناس، وأصبحنا على ثقة … أنا سنتبع، فالأشجان تعتلج\nإن أدلجوا، وتخلفنا وراءهم … شيئا يسيرا، فإنا سوف ندلج"},{"id":"diwan-maarri:185","bookId":"diwan-maarri","type":"poem","seq":185,"chapter":"قصائد","title":"بعالج، بات هم النفس يعتلج؛","page":"","text":"بعالج، بات هم النفس يعتلج؛ … فهل أسيت لعين، حين تختلج؟\nإن بشرت بدموع، فهي صادقة؛ … أو خبرت بسرور، قلت: لا يلج\nأدلج إلى رحمة الله، التي بذلت، … فما يسرك إلا في التقى دلج\nقد عيل صبرك، والظلماء داجية، … فاصبر قليلا، لعل الصبح ينبلج\nلا يعرف الدهر إلا معشر غلبوا، … فما استكانوا، ولم يزهوا، وقد فلجوا\nغيوث محل، ومن أدراعهم غدر؛ … بحار جود، وفي أغمارهم خلج\nالألمعيون، إن ظنوا، وإن حدسوا، … ظنينهم، بيقين واضح، ثلجوا"},{"id":"diwan-maarri:186","bookId":"diwan-maarri","type":"poem","seq":186,"chapter":"قصائد","title":"إقنع بأيسر شيء، فالزمان له","page":"","text":"إقنع بأيسر شيء، فالزمان له … محيلة، لا تقضى عندها الحوج\nوما يكف، أذاة عنك، حلف ضنى، … وقد يشجك عود، مسه عوج"},{"id":"diwan-maarri:187","bookId":"diwan-maarri","type":"poem","seq":187,"chapter":"قصائد","title":"أعوذ بالله من ورهاء قائلة،","page":"","text":"أعوذ بالله من ورهاء قائلة، … للزوج: إني إلى الحمام أحتاج\nوهمها في أمور، لو يتابعها … كسرى عليها، لشين الملك والتاج"},{"id":"diwan-maarri:188","bookId":"diwan-maarri","type":"poem","seq":188,"chapter":"قصائد","title":"لقد دجى الزمان فلا تدجوا؛","page":"","text":"لقد دجى الزمان فلا تدجوا؛ … ولج، فلم يدع خصما يلج\nأراني قد نصحت، فما لنصحي، … إذا ما غار في أذن، يمج؟\nعجبنا للركائب مبريات، … يسيل بهن بعد الفج فج\nتنص إلى تهامة، مبتغاها … صلاح، وليس في النيات وج\nهي الدنيا، على ما نحن فيه، … معاش يمترى، ودم يثج\nليالي ما بمكة من مقام، … ولا بيت، بأبطحها، يحج\nوما فتئت ولاة الأمر فيها، … على الصفراء، تصرف أو تشج\nوقد كذب الصحيح، بلا ارتياب، … فهل صدق الأصم أو الأشج؟\nمضى أهل الرجاء على سبيل، … كأنهم العظائم، لم يرجوا\nفما للرمح، قربه رجال، … ينصل للمنية، أو يزج؟"},{"id":"diwan-maarri:189","bookId":"diwan-maarri","type":"poem","seq":189,"chapter":"قصائد","title":"لا تفخرن معاشر بقديمها؛","page":"","text":"لا تفخرن معاشر بقديمها؛ … فلينسبن كلابها ونباجها\nوالخيل، إن مزعت بفرسان الوغى، … فلترجعن إلى الثرى أثباجها\nوإذا البجاد أتى الفتاة بدفئها … وخبائها، فكأنه ديباجها\nكم نال أطيب مطعم هلباجة، … أشر، وأعوز حرة هلباجها"},{"id":"diwan-maarri:190","bookId":"diwan-maarri","type":"poem","seq":190,"chapter":"قصائد","title":"تيمم، فجا واحدا، كل راكب،","page":"","text":"تيمم، فجا واحدا، كل راكب، … ولا بد أني سالك ذلك الفجا\nوسيان أم برة، وحمامة، … غذت ولدا في مهده، وغذت بجا\nفلا تبكرن يوما، بكفك مدية، … لتلك فرخا في مواطنه دجا\nتلفت في دنياه، سابح غمرة، … إلى السيف لهفا، بعدما وسط اللجا\nورجى أمورا، لم تكن بقريبة … إليه، فخطته الحوادث ما رجا\nيرجي معاشا من له بدوامه؛ … وهل يترك الدهر الفقير وما رجا؟\nفلا تبتئس للرزق، إن بض فاترا … ولا تغتبط إن جاش رزقك أو ثجا\nأعوام بحر، إن أصبتم فهين؛ … وإن تخلصوا، فالله ربكم نجا\nضللتم، فهل من كوكب يهتدى به، … فقد طال ما جن الظلام وما دجا\nفلا تأمنوا المرء التقي على التي … تسوء، وإن زار المساجد أو حجا\nولا تقبلوا من كاذب متسوق، … تحيل في نصر المذاهب، واحتجا\nفذلك غاوي الصدر، قلبي كقلبه، … متى ملأ التذكير مسمعه مجا\nوإن، لأجسام الأنام، غرائزا، … إذا حركت للشر طالبه لجا\nفلا آسى للدنيا، إذا هي زايلت، … فما كنت فيها لا سنانا ولا زجا\nوقد خلقت عوجاء، مثل هلالها، … يكون وإياها، القيامة، معوجا\nسواء على النفس، الخبيث ضميرها، … أمكة زارت، للمناسك، أو وجا\nفبالطائف الراح الكميت، سلافة، … إذا ما تمشت في حشا وادع أجا\nفكم من قتيل غادرت، ومكلم … على ألم، غب القتيل، الذي شجا\nمشعشعة لو خالطت، وهو عاقل، … ثبيرا، تداعى بالجهالة، وارتجا\nرأيت الفتى كالعود، يرتع مرة، … وإن مست الأعباء كاهله ضجا"},{"id":"diwan-maarri:191","bookId":"diwan-maarri","type":"poem","seq":191,"chapter":"قصائد","title":"يا سعد! إن أبا سعد لحادثه","page":"","text":"يا سعد! إن أبا سعد لحادثه … أمسى الحمام يسمى عنده فرجا\nوالروح شيء لطيف ليس يدركه … عقل، ويسكن من جسم الفتى حرجا\nسبحان ربك، هل يبقى الرشاد له، … وهل يحس بما يلقى، إذا خرجا؟\nوذاك نور لأجساد يحسنها، … كما تبينت، تحت الليلة، السرجا\nقالت معاشر: يبقى عند جثته، … وقال ناس: إذا لاقى الردى عرجا\nوليس في الإنس من نفس إذا قبضت، … ساف الذين لديها طيبها الأرجا\nوأسعد الناس، بالدنيا، أخو زهد، … نافى بنيها، ونادوا، إذ مضى: درجا"},{"id":"diwan-maarri:192","bookId":"diwan-maarri","type":"poem","seq":192,"chapter":"قصائد","title":"أغنى الأنام تقي في ذرى جبل،","page":"","text":"أغنى الأنام تقي في ذرى جبل، … يرضى القليل، ويأبى الوشي والتاجا\nوأفقر الناس، في دنياهم، ملك، … يضحي، إلى اللجب الجرار، محتاجا\nوقد علمت المنايا غير تاركة … ليثا بخفان، أو ظبيا بفرتاجا"},{"id":"diwan-maarri:193","bookId":"diwan-maarri","type":"poem","seq":193,"chapter":"قصائد","title":"تسريح كفي برغوثا، ظفرت به،","page":"","text":"تسريح كفي برغوثا، ظفرت به، … أبر من درهم تعطيه محتاجا\nلا فرق بين الأسك الجون أطلقه، … وجون كندة أمسى يعقد التاجا\nكلاهما يتوقى، والحياة له … حبيبة، ويروم العيش مهتاجا"},{"id":"diwan-maarri:194","bookId":"diwan-maarri","type":"poem","seq":194,"chapter":"قصائد","title":"لو لم تكن طرق هذا الموت موحشة،","page":"","text":"لو لم تكن طرق هذا الموت موحشة، … مخشية، لاعتراها القوم أفواجا\nوكان من ألقت الدنيا عليه أذى، … يؤمها تاركا، للعيش، أمواجا\nكأس المنية أولى بي، وأروح لي، … من أن أكابد إثراء وإحواجا\nفي كل أرض صروف، غير هازلة، … يلعبن بالناس أفرادا وأزواجا"},{"id":"diwan-maarri:195","bookId":"diwan-maarri","type":"poem","seq":195,"chapter":"قصائد","title":"الوقت يعجل أن تكون محللا","page":"","text":"الوقت يعجل أن تكون محللا … عقد الحياة، بأن تحل الزيجا\nفالدهر لا يسخو بأري للفتى، … حتى يكون، بما أمر، مزيجا\nهزجت نوادب للعقول، فخيبت … أنثى، تروم لطفلها تهزيجا"},{"id":"diwan-maarri:196","bookId":"diwan-maarri","type":"poem","seq":196,"chapter":"قصائد","title":"لا ترع الطائر، يغذو بجه،","page":"","text":"لا ترع الطائر، يغذو بجه، … يلتقط الحب، لكي يمجه\nإن الأنام واقع في لجه، … وظلمة من أمره ملتجه\nدع الفروع، وخذ المحجه؛ … لا تأمنن ذا عاهة مضجه\nإن عصاك، وهي المعوجه، … تحدث في رأس أخيك الشجه"},{"id":"diwan-maarri:197","bookId":"diwan-maarri","type":"poem","seq":197,"chapter":"قصائد","title":"لعمرك ما أنجاك طرفك، في الوغى،","page":"","text":"لعمرك ما أنجاك طرفك، في الوغى، … من الموت، لكن القضاء الذي ينجي\nفلا تك زيرا للنساء، وإن تمل … لهن، فلا تأذن لزير ولا صنج\nولا تدن للصهباء، بنتا لأبيض؛ … ولا تقرب الحمراء، من ولد الزنج"},{"id":"diwan-maarri:198","bookId":"diwan-maarri","type":"poem","seq":198,"chapter":"قصائد","title":"سرت بقوام، يسرق اللب، ناعم،","page":"","text":"سرت بقوام، يسرق اللب، ناعم، … إلى مدلج، تلقى البرى، أخت مدلج\nوقد حار هادي الركب، والليل ضارب … بأرواقه، والصبح لم يتبلج\nتكابد خضراء الحنادس، جونة، … ذخيرتها، من بدرها، نصف دملج\nإلى أن بدا فجر يكشف نهجه … لنا بلسان مفصح، غير لجلج\nوإن خلجت عين لبين، فحسبها، … من البين، يوم، من ردى، متخلج\nكفى حزنا أن الفتى، بعد سومه، … تقول له الأيام: في جدث لج\nوكم وطئت أقدامنا، في ترابها، … جبين أخي كبر، وهامة أبلج"},{"id":"diwan-maarri:199","bookId":"diwan-maarri","type":"poem","seq":199,"chapter":"قصائد","title":"خذوا في سبيل العقل تهدوا بهديه،","page":"","text":"خذوا في سبيل العقل تهدوا بهديه، … ولا يرجون، غير المهيمن، راج\nولا تطفئوا نور المليك، فإنه … ممتع كل من حجى بسراج\nأرى الناس في مجهولة، كبراؤهم … كولدان حي، يلعبون خراج"},{"id":"diwan-maarri:200","bookId":"diwan-maarri","type":"poem","seq":200,"chapter":"قصائد","title":"لكون خلك في رمس أعز له،","page":"","text":"لكون خلك في رمس أعز له، … من أن يكون مليكا عاقد التاج\nالملك يحتاج ألافا لتنصره، … والميت ليس إلى خلق بمحتاج"},{"id":"diwan-maarri:201","bookId":"diwan-maarri","type":"poem","seq":201,"chapter":"قصائد","title":"قد أسرجوا بكميت أطلقت لجما،","page":"","text":"قد أسرجوا بكميت أطلقت لجما، … ولم يهموا بإلجام وإسراج\nيستصبحون، وعين الديك نائمة، … بقهوة مثل عين الديك، مئراج\nدبت دبيب نمال في أناملهم، … بسائر في رؤوس القوم، دراج\nتفرج الهم عنهم، بل تزيدهم، … نكدا، هواجس ما همت بإفراج\nلم يعلموا أن أقدارا ستنزلهم، … بالعنف، من فوق أفدان وأبراج\nوما أرى درجات الفضل مغنية … عن الفتى، عاد محثوثا لإدراج\nأما الحياة، فلا أرجو نوافلها؛ … لكنني لإلهي خائف راجي\nرب السماك ورب الشمس، طالعة، … وكل أزهر، في الظلماء، خراج"},{"id":"diwan-maarri:202","bookId":"diwan-maarri","type":"poem","seq":202,"chapter":"قصائد","title":"ما عاقد الحبل يبغي بالضحى عضدا،","page":"","text":"ما عاقد الحبل يبغي بالضحى عضدا، … إلا كصاحب ملك عاقد التاج\nوما رأينا صروف الدهر تاركة … ليثا، بترج، ولا ظبيا بفرتاج\nما أعدل الموت من آت، وأستره، … فهيجني، فإني غير مهتاج\nالعيش أفقر منا كل ذات غنى؛ … والموت أغنى بحق كل محتاج\nإذا حياة علينا،للأذى فتحت … بابا من الشر، لاقاه بإرتاج"},{"id":"diwan-maarri:203","bookId":"diwan-maarri","type":"poem","seq":203,"chapter":"قصائد","title":"كأنني راكب اللج، الذي عصفت","page":"","text":"كأنني راكب اللج، الذي عصفت … رياحه، فهو في هول وتمويج\nوفي طباعك زيغ، والهلال، على … سموه، حلف تقويس وتعوج\nفزن، من الوزن، لفظا، حين ترسله، … وزن، من الزين، إعطاء بترويج\nوانظر إلى نفسك اللومى بمنظرها، … ولو غدوت أخا ملك وتتويج\nواطلب لبنتك زوجا كي يراعيها، … وخوف ابنك من نسل وتزويج\nما اليسر كالعدم في الأحكام، بل شحطت … حال المياسير عن حال المحاويج"},{"id":"diwan-maarri:204","bookId":"diwan-maarri","type":"poem","seq":204,"chapter":"قصائد","title":"ألا إن الظباء لفي غرور،","page":"","text":"ألا إن الظباء لفي غرور، … ترجي الخلد بعد ليوث ترج\nوأشرف من ترى، في الأرض، قدرا، … يعيش، الدهر، عبد فم وفرج\nوحب الأنفس الدنيا غرور، … أقام الناس في هرج ومرج\nوإن العز، في رمح وترس، … لأظهر منه في قلم ودرج\nوما أختار أني الملك يجبا، … إلي، المال من مكس وخرج\nفدع إلفيك: من عرب وعجم، … إلى حلفيك: من قتب وسرج\nسراجك، في الدجنة، عين ضار، … وإلا فالكواكب خير سرج\nمتى كشفت أخلاق البرايا، … تجد ما شئت من ظلم وحرج\nضغائن لم تزل من قبل نوح، … على ما هان من فرز وعرج\nفجرت قتل هابيل أخوه؛ … وألقت بين معتزل ومرجي\nوخانت ود لقمان لقينا، … ليالي حرفت سمرا بشرج\nفدار معيشة، واحمل أذاة، … لمن صاحبت من حوص وبرج\nفإن الأسد تتبعها ذئاب … وغربان، فمن عور وعرج\nمسيرك ، في البلاد، أقل رزءا … مع الفئتين من قمر وخرج\nوكم خدعت هزبرا، كان جبرا، … من الأملاك، ذات حلى ودرج"},{"id":"diwan-maarri:205","bookId":"diwan-maarri","type":"poem","seq":205,"chapter":"قصائد","title":"وجدت الناس في هرج ومرج،","page":"","text":"وجدت الناس في هرج ومرج، … غواة بين معتزل ومرجي\nفشأن ملوكهم عزف ونزف؛ … وأصحاب الأمور جباة خرج\nوهم زعيمهم إنهاب مال، … حرام النهب، أو إجلال فرج\nوإن شرارة وقعت بواد … لتحرق وحدها سمرا بشرج\nركوب النعش أسرع لابن دهر، … يريد الخير من قتب وسرج\nغدا العصفور، للبازي، أميرا؛ … وأصبح، ثعلبا، ضرغام ترج\nأفي الدنيا، لحاها الله، حق، … فيطلب، في حنادسها، بسرج؟"},{"id":"diwan-maarri:206","bookId":"diwan-maarri","type":"poem","seq":206,"chapter":"قصائد","title":"أنا، للصرورة، في الحياة، مقارن،","page":"","text":"أنا، للصرورة، في الحياة، مقارن، … ما زلت أسبح في البحار الموج\nوصرورة في شيمتين، لأنني، … مذ كنت، لم أحجج ولم أتزوج\nمن مذهبي أن لا أشد بفضة … قدحي، ولا أصغي لشرب معوج\nلكن أقضي مدتي بتقنع، … يغني، وأفرح باليسير الأروج\nهذا، ولست أود أني قائم … بالملك، في ثوبي أغر متوج"},{"id":"diwan-maarri:207","bookId":"diwan-maarri","type":"poem","seq":207,"chapter":"قصائد","title":"وصل الهجير إلى الهجير لعله،","page":"","text":"وصل الهجير إلى الهجير لعله، … في الخلد، يظفر بالهواء السجسج\nسلبته، برد الورد، راحة ميتة، … غصبته، حين كسته برد بنفسج\nغشاه مصفر الأنامل، خافيا … فكأنه، لبنانه، لم ينسج\nولى وخلف عرسه وبناته، … يجنين أطيب مطعم من عوسج"},{"id":"diwan-maarri:208","bookId":"diwan-maarri","type":"poem","seq":208,"chapter":"قصائد","title":"عن لاعج باتوا برملة عالج،","page":"","text":"عن لاعج باتوا برملة عالج، … في ربوتي عود كظهر الفالج\nفي مقفر، تنآه سلمى مدلج، … من بعد طيته، وسلما دالج\nمثل الأساور والدمالج، في الطوى، … أنسوا ذوات أساور ودمالج\nوالأرض قد لفظت حشاشة نورها، … فدجا الظلام سوى الوميض الخالج\nفزعوا إلى ذكر المليك، وحسبهم … أنسا بذلك، في الضمير الوالج"},{"id":"diwan-maarri:209","bookId":"diwan-maarri","type":"poem","seq":209,"chapter":"قصائد","title":"أتعوج أم ليس المشوق بعائج؟","page":"","text":"أتعوج أم ليس المشوق بعائج؟ … هاجت وساوسه لبرق هائج\nسبحان من برأ النجوم، كأنها … در، طفا من فوق بحر مائج\nلو شاء ربك صير الشرطين، من … هذي الكواكب، عند أدنى ثائج\nوالتاج تقوى الله، لا ما رصعوا … ليكون زينا للأمير التائج"},{"id":"diwan-maarri:210","bookId":"diwan-maarri","type":"poem","seq":210,"chapter":"قصائد","title":"إن هاجك البارق فاهتاجي،","page":"","text":"إن هاجك البارق فاهتاجي، … لا يمنع الرزق بإرتاج\nأصبح في لحدي، على وحدتي … لست إلى الدنيا بمحتاج\nما أسد خفان بمتروكة … فيها، ولا غزلان فرتاج\nكشفي رأسي، وافتقاري بها، … خير من التمليك والتاج"},{"id":"diwan-maarri:211","bookId":"diwan-maarri","type":"poem","seq":211,"chapter":"قصائد","title":"أطعت، في الأيام، سداجي؛","page":"","text":"أطعت، في الأيام، سداجي؛ … وسارت الدنيا بأحداجي\nآليت ما أدري، ولا عالمي … من كوكبي في الحندس الداجي\nلا بسط الخالق في مدتي، … حتى يرى الناظر هداجي\nقد ذبح الذارع في ساحة، … فيا له من دم أوداج!\nيسلك محمود، وأمثاله، … طريق خاقان وكنداج"},{"id":"diwan-maarri:212","bookId":"diwan-maarri","type":"poem","seq":212,"chapter":"قصائد","title":"حالي حال اليائس الراجي،","page":"","text":"حالي حال اليائس الراجي، … وإنما أرجع أدراجي\nإذا رأيت الخير في رقدتي، … عددتها ليلة معراجي\nإن قمت من غبرة هذا الثرى، … أهدى إلى خضراء مئراج\nفالحمد لله على نعمة، … تعقب من ضنك وإحراج\nلو أنني البرجيس، أو جاره، … نزلت من أرفع أبراج\nما أم سرياح، إذا ما غدت، … مورثتي أدمع دراج\nينسى الفتى الحربي، في قبره، … أيام إلجام وإسراج\nوخوضه في نفيان الوغى، … على طموح الطرف هراج\nوخضبه الأبيض، مستأنسا، … بأسود، للهول، فراج\nيفض ما أذهب من قونس، … بزئبق، يمتد، رجراج\nأشل، أو أعرج، دهر عدا، … فوارسا، عن شك أعراج"},{"id":"diwan-maarri:213","bookId":"diwan-maarri","type":"poem","seq":213,"chapter":"قصائد","title":"وصفتك، فابتهجت، وقلت خيرا،","page":"","text":"وصفتك، فابتهجت، وقلت خيرا، … لتجزيني، فأدركني ابتهاجي\nإذا كان التقارض من محال، … فأحسن من تمادحنا التهاجي"},{"id":"diwan-maarri:214","bookId":"diwan-maarri","type":"poem","seq":214,"chapter":"قصائد","title":"إذا أثنى علي المرء، يوما،","page":"","text":"إذا أثنى علي المرء، يوما، … بخير ليس في، فذاك هاج\nوحقي، إن أساء بما افتراه، … فلؤم من غريزتي ابتهاجي"},{"id":"diwan-maarri:215","bookId":"diwan-maarri","type":"poem","seq":215,"chapter":"قصائد","title":"غدا الناس كلهم في أذى،","page":"","text":"غدا الناس كلهم في أذى، … فزج حياتك فيمن يزج\nولا تطلبن اللباب الصريح، … فقد سيط عالمنا، وامتزج\nألم تر أن طويل القري … ض من متقاربه، والهزج؟"},{"id":"diwan-maarri:216","bookId":"diwan-maarri","type":"poem","seq":216,"chapter":"قصائد","title":"إذا ما مضى نفس، فاحسبنه","page":"","text":"إذا ما مضى نفس، فاحسبنه … كالخيط، من ثوب عمر، نهج\nوإن هاجك الدهر، فاصبر له، … وعش ذا وقار، كأن لم تهج\nفكم جمرة خمدت، فانقضت، … وكان لها منذ حين وهج\nفيا قائد الجيش خفض عليك، … في غير حظك يعلو الرهج\nزمان حباك قليل العطاء، … ما زال يكثر أخذ المهج\nفلا تود أنفسنا، حسبنا … قضاء، له بأذانا لهج\nأعن باكيا، لج في حزنه؛ … وسل ضاحك القوم مم ابتهج؟\nوعالمنا المنتهي كالصبي، … قيل له، في ابتداء، تهج"},{"id":"diwan-maarri:217","bookId":"diwan-maarri","type":"poem","seq":217,"chapter":"قصائد","title":"يشج بنو آدم بالصخور؛","page":"","text":"يشج بنو آدم بالصخور؛ … وإن المدام بماء تشج\nفما نزل اليمن في شربها، … ولا في وعاء سلاف نشج"},{"id":"diwan-maarri:218","bookId":"diwan-maarri","type":"poem","seq":218,"chapter":"قصائد","title":"يقول لك: انعم مصبحا، متودد","page":"","text":"يقول لك: انعم مصبحا، متودد … إليك، وخير منه أغلب، أصبح\nرجوت بقرب، من خليلك، مرحبا، … وبعدك منه، في الحقائق، أربح\nإذا أنت لم تهرب من الإنس، فاعترف … بطلس تعاوى، أو ثعالب تضبح\nومارس، بحسن الصبر، بلواك، إن هم … أتوا بقبيح، فالذي جئت أقبح\nتروح إلى فعل السفيه وتغتدي، … وتمسي على غير الجميل، وتصبح\nكأن خطوب الدهر بحر، فمن يمت … بفرط صداه، فهو في اللج يسبح"},{"id":"diwan-maarri:219","bookId":"diwan-maarri","type":"poem","seq":219,"chapter":"قصائد","title":"أصاح! هي الدنيا تشابه ميتة؛","page":"","text":"أصاح! هي الدنيا تشابه ميتة؛ … ونحن حواليها الكلاب النوابح\nفمن ظل منها آكلا، فهو خاسر، … ومن عاد عنها ساغبا، فهو رابح\nومن لم تبيته الخطوب، فإنه … سيصبحه من حادث الدهر صابح"},{"id":"diwan-maarri:220","bookId":"diwan-maarri","type":"poem","seq":220,"chapter":"قصائد","title":"لقد سنحت لي فكرة بارحية،","page":"","text":"لقد سنحت لي فكرة بارحية، … وما زادني، إلا اعتبارا، سنوحها\nبربة طوق، ما أقل جناحها … جناحا، وفي خضر الغصون جنوحها\nوهاج، حمياها، أصيل مذكر، … تغنيه شجوا، أو غداة تنوحها\nوتلك، لعمري، شيمة أولية، … توارثها شيث الحمام ونوحها"},{"id":"diwan-maarri:221","bookId":"diwan-maarri","type":"poem","seq":221,"chapter":"قصائد","title":"لقد برحت طير ولست بعائف،","page":"","text":"لقد برحت طير ولست بعائف، … وإن هاج لي بعض الغرام بروحها\nأرى هذيانا، طال من كل أمة، … يضمنه إيجازها وشروحها\nوأوصال جسم، للتراب، مآلها، … ولم يدر دار: أين تذهب روحها؟\nولا بد، يوما، من غدو مبغض، … سنغدوه، أو من روحة سنروحها\nولو رضيت، دون النفوس، بغيرها، … لحطت بعفو، لا قصاص، جروحها"},{"id":"diwan-maarri:222","bookId":"diwan-maarri","type":"poem","seq":222,"chapter":"قصائد","title":"أعاذلتي! إن الحسان قباح؛","page":"","text":"أعاذلتي! إن الحسان قباح؛ … فهل لظلام العالمين صباح؟\nيسمي، ابنه كسرى، فقير ممارس … شقاء، وأسماء البنين تباح\nورب مسمى عنبرا، وهو موهت، … وليثا، وفيه، أن يهيج، نباح"},{"id":"diwan-maarri:223","bookId":"diwan-maarri","type":"poem","seq":223,"chapter":"قصائد","title":"يا أيها الناس! جاز المدح قدركم،","page":"","text":"يا أيها الناس! جاز المدح قدركم، … وقصرت، عن مدى مولاكم، المدح\nإذا استعانوا بأقداح، لها قيم، … على المدامة، فالإثم الذي قدحوا\nوعندهم مسمعات، يأذنون لها؛ … ما للمسامع عما قلن منتدح\nقالوا: غدون مصيبات الغناء لنا، … وتلك عندي مصيبات لهم فدح\nعن الطواويس ما يلبسن مسترق؛ … وهن بعد قماري الضحى الصدح"},{"id":"diwan-maarri:224","bookId":"diwan-maarri","type":"poem","seq":224,"chapter":"قصائد","title":"يا مشرع الرمح في تثبيت مملكة،","page":"","text":"يا مشرع الرمح في تثبيت مملكة، … خير من المارن الخطي مسباح\nيزيد ليلك إظلاما إلى ظلم، … فما له، آخر الأيام، إصباح\nلا يعتم الجنح في مثوى أخي نسك، … وكلما قال شيئا، فهو مصباح\nأموالنا في تقانا، لا رؤوس لها؛ … فكيف تؤمل، عند الله، أرباح؟\nونحن في البحر، ما نجت سفائنه، … وكم تقطع، دون العبر، سباح\nوسوف ننسى، فنمسي، عند عارفنا، … وما لنا، في أقاصي الوهم، أشباح\nتغير الدهر، حتى لو شحا أسد، … لقيل: كش خلال القوم رباح\nليث النزال، ولكن، في منازله، … كلب، على فضلات الزاد، نباح\nتجرع، الموت، نحار لأينقه، … إذا شتا، ولفار المسك ذباح\nيجود بالتبر إن أصحابه بخلوا، … ويكتم السر، إن خزانه باحوا"},{"id":"diwan-maarri:225","bookId":"diwan-maarri","type":"poem","seq":225,"chapter":"قصائد","title":"تجمع أهله زمرا إليه،","page":"","text":"تجمع أهله زمرا إليه، … وصاحت عرسه: أودى فصاحوا\nتخاطبنا، بأفواه المنايا، … من الأيام، ألسنة فصاح\nنصحتكم: أهينوا أم دفر، … فما يبقى لكم، منها، نصاح"},{"id":"diwan-maarri:226","bookId":"diwan-maarri","type":"poem","seq":226,"chapter":"قصائد","title":"نطيح، ولا نطيق دفاع أمر،","page":"","text":"نطيح، ولا نطيق دفاع أمر، … فكيف يروعنا الغادي النطيح\nولم يك أهل خيبر أهل خبر، … بما لاقى السلالم والوطيح\nوجدت الغيب، تجهله البرايا، … فما شق، هديت، وما سطيح"},{"id":"diwan-maarri:227","bookId":"diwan-maarri","type":"poem","seq":227,"chapter":"قصائد","title":"اقنع بما رضي التقي لنفسه،","page":"","text":"اقنع بما رضي التقي لنفسه، … وأباحه لك، في الحياة، مبيح\nمرآة عقلك، إن رأيت بها سوى … ما في حجاك، أرته، وهو قبيح\nأسنى فعالك ما أردت بفعله … رشدا، وخير كلامك التسبيح\nإن الحوادث ما تزال لها مدى؛ … حمل النجوم ببعضهن ذبيح"},{"id":"diwan-maarri:228","bookId":"diwan-maarri","type":"poem","seq":228,"chapter":"قصائد","title":"أستقبح الظاهر من صاحبي؛","page":"","text":"أستقبح الظاهر من صاحبي؛ … وما يواري صدره أقبح\nسببت بالكلب، فأنكرته، … والكلب خير منك، إذ ينبح\nصلى الفتى الجمعة، ثم انثنى … لذارع، في مسحه، يذبح\nيعطى به التاجر أرباحه، … وتاجر الخسران لا يربح\nفليتني عشت بداوية، … حرباؤها، في عوده، يشبح\nيصدى بها الركب، وأعلامها، … كأنها، في آلها، تسبح\nأو بت، في صهوة، مستوطنا، … أمسي، مع الأغفار، أو أصبح\nوالنفس كالجامح، فليثنها … لب، أوابي لجمه تكبح"},{"id":"diwan-maarri:229","bookId":"diwan-maarri","type":"poem","seq":229,"chapter":"قصائد","title":"المرء، حتى يغيب الشبح،","page":"","text":"المرء، حتى يغيب الشبح، … مغتبق همه، ومصطبح\nوالخلق حيتان لجة لعبت، … وفي بحار، من الأذى، سبحوا\nلا تحفلن هجوهم ومدحهم؛ … فإنما القوم أكلب نبح\nولا تهب أسدهم، إذا زأروا؛ … وقل: تداعت ثعالب ضبح\nوهم، من الموت، أهل منزلة، … إن لم يراعوا بطارق صبحوا\nلم يفطنوا للجميل، بل جبلوا … على قبيح، فما لهم قبحوا؟\nفمن لتجر الوداد، إنهم … لا خسروا، عندهم، ولا ربحوا\nأقل منهم، شرا ومرزية، … ما ركبوا، للسرى، وما ذبحوا\nفليتهم كالبهائم اعترفوا … لجما، إذا بان زيغهم كبحوا"},{"id":"diwan-maarri:230","bookId":"diwan-maarri","type":"poem","seq":230,"chapter":"قصائد","title":"يا كاذبا! لا يجوز زائفه،","page":"","text":"يا كاذبا! لا يجوز زائفه، … وما عليه، من فضة، وضح\nكشفت عما تقول مجتهدا، … لعل حقا، لطالب، يضح\nفكلما هذبتك تجربة، … أنشأت، للباحثين، تفتضح"},{"id":"diwan-maarri:231","bookId":"diwan-maarri","type":"poem","seq":231,"chapter":"قصائد","title":"قد علموا أن سيخطف الشبح،","page":"","text":"قد علموا أن سيخطف الشبح، … فاغتبقوا بالمدام واصطبحوا\nما حفظوا جارة، ولا فعلوا … خيرا، ولا في مكارم ربحوا\nغالوا بأثوابهم، فما حسنوا، … في ذهبي اللباس، بل قبحوا\nدعوا إلى الله كي يجيبهم، … سيان هم والخواسىء النبح\nكم قتلوا عاتقا، وكم جرحوا … دنا، وكم فار تاجر ذبحوا\nلا تغبط القوم، في ضلالتهم، … وإن رؤوا، في النعيم، قد سبحوا"},{"id":"diwan-maarri:232","bookId":"diwan-maarri","type":"poem","seq":232,"chapter":"قصائد","title":"العلم، كالقفل، إن ألفيته عسرا،","page":"","text":"العلم، كالقفل، إن ألفيته عسرا، … فخله، ثم عاوده لينفتحا\nوقد يخون رجاء، بعد خدمته، … كالغرب خانت قواه، بعدما متحا"},{"id":"diwan-maarri:233","bookId":"diwan-maarri","type":"poem","seq":233,"chapter":"قصائد","title":"دعوا، وما فيهم زاك، ولا أحد","page":"","text":"دعوا، وما فيهم زاك، ولا أحد … يخشى الإله، فكانوا أكلبا نبحا\nوهل أجل قتيل، من رجالهم، … إذا تؤمل، إلا ماعز ذبحا؟\nخير من الظالم الجبار، شيمته … ظلم وحيف، ظليم يرتعي الذبحا\nوليس عندهم دين ولا نسك، … فلا تغرك أيد تحمل السبحا\nوكم شيوخ غدوا، بيضا مفارقهم، … يسبحون، وباتوا في الخنى سبحا\nلو تعقل الأرض ودت أنها صفرت … منهم، فلم ير فيها ناظر شبحا\nما ثعلب، وابن يحيى، مبتغاي به، … وإن تفاصح، إلا ثعلب ضبحا\nأرى ابن آدم قضى عيشة عجبا، … إن لم يرح خاسرا، منها، فما ربحا\nفإن قدرت، فلا تفعل سوى حسن، … بين الأنام، وجانب كل ما قبحا\nفحيرة الملك خلت المنذرين، بها، … لم يغبقا الراح، في عز، ولا صبحا"},{"id":"diwan-maarri:234","bookId":"diwan-maarri","type":"poem","seq":234,"chapter":"قصائد","title":"قلمت ظفري، تارات، وما جسدي","page":"","text":"قلمت ظفري، تارات، وما جسدي … إلا كذاك، متى ما فارق الروحا\nومن تأمل أقوالي رأى جملا، … يظل، فيهن، سر الناس مشروحا\nإن الحياة لمفروح بها، طلقا، … يغادر الخلد الجذلان مقروحا\nقد ادعيتم، فقلنا: أين شاهدكم؟ … فجاء من بات، عند اللب، مجروحا\nإن صح تعذيب رمس من يحل به، … فجنباني ملحودا ومضروحا\nالوحش والطير أولى أن تنازعني، … فغادراني، بظهر الأرض، مطروحا\nشدا علي دريسا، كي يواريني، … ثم اغدوا بسلام الله، أو روحا\nيا نفس! يا طائرا في سجن مالكه، … لتصبحن، بحمد الله، مسروحا"},{"id":"diwan-maarri:235","bookId":"diwan-maarri","type":"poem","seq":235,"chapter":"قصائد","title":"عجبي للطبيب يلحد في الخا","page":"","text":"عجبي للطبيب يلحد في الخا … لق، من بعد درسه التشريحا\nولقد علم المنجم ما يو … جب، للدين، أن يكون صريحا\nمن نجوم نارية، ونجوم … ناسبت تربة وماء وريحا\nفطن الحاضرين من يفهم التع … ريض، حتى يظنه تصريحا\nرب روح، كطائر القفص المس … جون، ترجو بموتها التسريحا\nفرحوكم بباطل، شيمة الخم … ر، فمهلا! لا أوثر التفريحا\nكيف لي أن أكون، في داري الأخ … رى، معافى من شقوة، مستريحا\nذا اقتناع، كما أنا اليوم فيه، … أو أخلى، فلا أريم الضريحا\nعجبا لي! أعصي، من الجهل، عقلي، … ويظل السليم، عندي، جريحا\nمثل قيس، غداة فارق لبنى، … عاد يشكو، فيما جناه، ذريحا\nيتكنى، أبا الوفاء، رجال، … ما وجدنا الوفاء إلا طريحا\nوأبو جعدة، ذؤالة، من جع … دة؟ لا زال حاملا تتريحا\nوابن عرس عرفت وابن بريح … ثم عرسا جهلته، وبريحا\nومن اليمن، للفتى، أن يجيء ال … موت، يسعى إليه سعيا سريحا\nلم يمارس، من السقام، طويلا، … ومضى، لم يكابد التبريحا"},{"id":"diwan-maarri:236","bookId":"diwan-maarri","type":"poem","seq":236,"chapter":"قصائد","title":"غدوت مريض العقل والدين فالقني","page":"","text":"غدوت مريض العقل والدين فالقني … لتسمع أنباء الأمور الصحائح\nفلا تأكلن ما أخرج الماء، ظالما، … ولا تبغ قوتا من غريض الذبائح\nوأبيض أمات، أرادت صريحه … لأطفالها، دون الغواني الصرائح\nولا تفجعن الطير، وهي غوافل، … بما وضعت، فالظلم شر القبائح\nودع ضرب النحل، الذي بكرت له، … كواسب من أزهار نبت فوائح\nفما أحرزته كي يكون لغيرها، … ولا جمعته للندى والمنائح\nمسحت يدي من كل هذا، فليتني … أبهت لشأني، قبل شيب المسائح\nبني زمني، هل تعلمون سرائرا، … علمت، ولكني بها غير بائح؟\nسريتم على غي، فهلا اهتديتم … بما خيرتكم صافيات القرائح\nوصاح بكم داعي الضلال، فما لكم … أجبتم، على ما خيلت، كل صائح؟\nمتى ما كشفتم عن حقائق دينكم، … تكشفتم عن مخزيات الفضائح\nفإن ترشدوا لا تخضبوا السيف من دم، … ولا تلزموا الأميال سبر الجرائح\nويعجبني دأب الذين ترهبوا، … سوى أكلهم كد النفوس الشحائح\nوأطيب منهم مطعما، في حياته، … سعاة حلال، بين غاد ورائح\nفما حبس النفس المسيح تعبدا، … ولكن مشى، في الأرض، مشية سائح\nيغيبني، في الترب، من هو كاره، … إذا لم يغيبني كريه الروائح\nومن يتوقى أن يجاور أعظما، … كأعظم تلك الهالكات الطرائح\nومن شر أخلاق الأنيس، وفعلهم، … خوار النواعي والتدام النوائح\nوأصفح عن ذنب الصديق وغيره، … لسكناي بيت الحق بين الصفائح\nوأزهد في مدح الفتى، عند صدقه، … فكيف قبولي كاذبات المدائح!\nوما زالت النفس اللجوج مطية، … إلى أن غدت إحدى الرذايا الطلائح\nوما ينفع الانسان أن غمائما … تسح عليه، تحت إحدى الضرائح\nولو كان، في قرب من الماء، رغبة، … لنافس ناس في قبور البطائح"},{"id":"diwan-maarri:237","bookId":"diwan-maarri","type":"poem","seq":237,"chapter":"قصائد","title":"أما وفؤاد بالغرام قريح،","page":"","text":"أما وفؤاد بالغرام قريح، … ودمع بأنواع الهموم سريح\nلقد غرت الدنيا بنيها بمذقها، … وإن سمحوا من ودها بصريح\nأليلى، وكل أصبح ابن ملوح؛ … ولبنى، وما فينا سوى ابن ذريح\nوفي كل حين يونس القوم آية … بشخص قتيل، أو بشخص جريح\nولم يطرحك المرء عنه لعبرة … يراها بمرفوت العظام، طريح\nوليس لنا، في مدة العيش، راحة، … فكيف بموت، من أذاك، مريح\nوتعقد سلوان الفتى عنك نفسه … بأذيال برق، أو دوائب ريح\nوما زال، في بلواك، مذ يوم وضعه … عليك، إلى أن عاد رهن ضريح\nطلبت شفاء منك، واهتجت سائلا … بذاك أبا سلمان، وابن بريح"},{"id":"diwan-maarri:238","bookId":"diwan-maarri","type":"poem","seq":238,"chapter":"قصائد","title":"عجبت للمرء، إذ يسقي حليلته","page":"","text":"عجبت للمرء، إذ يسقي حليلته … سلافة، وهو منها تائب صاح\nكأنها إذ تحست، ثم، أربعة، … أو خمسة، شردت عنه بصحصاح\nكانت ضعيفة عقل، فاستزاد لها … في ضعفه، ضد عذال ونصاح\nوكان في لفظها عي فأيده، … فلم تخبره عن شيء بإفصاح"},{"id":"diwan-maarri:239","bookId":"diwan-maarri","type":"poem","seq":239,"chapter":"قصائد","title":"من عاشر الناس لم يعدم نفاقهم،","page":"","text":"من عاشر الناس لم يعدم نفاقهم، … فما يفوهون، من حق، بتصريح\nفاعجب لتحريق أهل الهند ميتهم، … وذاك أروح من طول التباريح\nإن حرقوه فما يخشون من ضبع … تسري إليه، ولا خفي وتطريح\nوالنار أطيب من كافور ميتنا … غبا، وأذهب للنكراء والريح"},{"id":"diwan-maarri:240","bookId":"diwan-maarri","type":"poem","seq":240,"chapter":"قصائد","title":"كفتك حوادث الأيام قتلا،","page":"","text":"كفتك حوادث الأيام قتلا، … فلا تعرض لسيف، أو لرمح\nتراضى أهل دهرك بالمخازي، … فكيف تعيب رامقة بلمح؟\nوأصحاب الشريف، ولا تساو، … كأصحاب ابن زرعة وابن سمح"},{"id":"diwan-maarri:241","bookId":"diwan-maarri","type":"poem","seq":241,"chapter":"قصائد","title":"أهاتفة الأيك خلي الأنام،","page":"","text":"أهاتفة الأيك خلي الأنام، … ولا تثلبيه ولا تمدحي\nوإن كنت شادية، فاصمتي؛ … وإن كنت باكية، فاصدحي\nكدحنا لفانية حلوة؛ … فكيف نلومك إن تكدحي\nوإن حملت راحتي راحها، … بأقداحها، لم تفز أقدحي\nوما يضحك السن في دهرها؟ … كأن المصائب لم تفدح"},{"id":"diwan-maarri:242","bookId":"diwan-maarri","type":"poem","seq":242,"chapter":"قصائد","title":"إلى النسك ارتح، وأصحابه،","page":"","text":"إلى النسك ارتح، وأصحابه، … إذا فاتك القوم لم يرتح\nوإن قرع الباب غاو علي … ك، فزده وثاقا ولا تفتح\nأخوك امرؤ يستحيه ال … ديق، وآفته أنه يستحي\nرأيت الفتى يلتحى غصنه، … فيهلك من قبل أن يلتحي\nوما كتبته يد للزمان، … فعن يده مرة يمتحي\nوكم بدأ الحي في حاجة، … فأعجله قدر ينتحي\nكما ملىء الغرب من مائه، … وخلي في الجفر لم يمتح"},{"id":"diwan-maarri:243","bookId":"diwan-maarri","type":"poem","seq":243,"chapter":"قصائد","title":"بوارق للحاب لا للسحاب،","page":"","text":"بوارق للحاب لا للسحاب، … طربت إلى ضوء لماحها\nأرى الخمر تجمح بالشاربين، … فلا تخدعن بإسماحها\nوكم طمحت باللبيب الأريب، … فأسقط عن ظهر طماحها\nوليس الزجاج زجاج الخطوب، … ولكن أسنة أرماحها"},{"id":"diwan-maarri:244","bookId":"diwan-maarri","type":"poem","seq":244,"chapter":"قصائد","title":"سمعي موقى، سالم،","page":"","text":"سمعي موقى، سالم، … فقل الصواب ولا تصح\nمن قبل يوم حليمة … حلم الأديم، فما يصح\nوالمرء في تركيبه، … غضب يهيج، إذا نصح"},{"id":"diwan-maarri:245","bookId":"diwan-maarri","type":"poem","seq":245,"chapter":"قصائد","title":"أعوذ بالله من أولي سفه،","page":"","text":"أعوذ بالله من أولي سفه، … أن يعرفوا علة الضلال تزح\nيسقون راحا، لهم، معتقة، … لو أنها من قلبيهم لنزح\nبينهم كالغمام شادية، … تومض في ملبس كقوس قزح\nيجد، في وصلها، ملاعبها، … وهي لجلاسها تقول مزح"},{"id":"diwan-maarri:246","bookId":"diwan-maarri","type":"poem","seq":246,"chapter":"قصائد","title":"هي الراح أهلا لطول الهجاء،","page":"","text":"هي الراح أهلا لطول الهجاء، … وإن خصها معشر بالمدح\nفلا تعجبنك عروس المدام؛ … ولا يطربنك مغن صدح\nومن يفتقد لبه، ساعة؛ … فقد مات فيها بخطب فدح\nقبيح بمن عد بعض البحار، … تغريقه نفسه في قدح"},{"id":"diwan-maarri:247","bookId":"diwan-maarri","type":"poem","seq":247,"chapter":"قصائد","title":"تنسكت بعد الأربعين ضرورة،","page":"","text":"تنسكت بعد الأربعين ضرورة، … ولم يبق إلا أن تقوم الصوارخ\nفكيف ترجي أن تثاب، وإنما … يرى الناس فضل النسك والمرء شارخ"},{"id":"diwan-maarri:248","bookId":"diwan-maarri","type":"poem","seq":248,"chapter":"قصائد","title":"تفرقوا كي يقل شركم،","page":"","text":"تفرقوا كي يقل شركم، … فإنما الناس كلهم وسخ\nأجهل بساداتهم، وإن زعموا … أنهم، في علومهم، رسخوا\nما فسخوا، بالقبيح، عهدهم، … ضنوا، وأما بسرهم فسخوا\nقد نسخ الشرع في عصورهم، … فليتهم مثل شرعهم نسخوا"},{"id":"diwan-maarri:249","bookId":"diwan-maarri","type":"poem","seq":249,"chapter":"قصائد","title":"لا يفقدن، خيركم، مجالسكم؛","page":"","text":"لا يفقدن، خيركم، مجالسكم؛ … ولا تكونوا كأنكم سبخ\nولا كقوم حديث يومهم، … ما أكلوا، أمسهم، وما طبخوا"},{"id":"diwan-maarri:250","bookId":"diwan-maarri","type":"poem","seq":250,"chapter":"قصائد","title":"إذا عقدت عقدا لياليك هذه،","page":"","text":"إذا عقدت عقدا لياليك هذه، … فإن لها من حكم خالقها فسخا\nلعمري لقد طالت على المدلج السرى، … وليس يرى في حندس لهبا يسخا\nوجدنا اتباع الشرع حزما لذي النهى، … ومن جرب الأيام لم ينكر النسخا\nفما بال هذا العصر مافيه آية … من المسخ إن كانت يهود رأت مسخا\nوقال، بأحكام التناسخ، معشر … غلوا، فأجازوا الفسخ في ذاك والرسخا\nومن يعف عن ذنب، ويسخ بنائل، … فخالقنا أعفى، وراحته أسخى"},{"id":"diwan-maarri:251","bookId":"diwan-maarri","type":"poem","seq":251,"chapter":"قصائد","title":"أرى طولا عم البرية كلها،","page":"","text":"أرى طولا عم البرية كلها، … فيقصر بالحكم الإلهي، أو يرخا\nذكرنا الصبا والشرخ، ثم ترادفت، … حوادث أنستنا الشبيبة والشرخا\nوقد ينتحي، الزند، الغوي بجهله، … فيفضل، في القدح، العفارة والمرخا\nفإن كنت ذا لب مكين، فلا تقس … بحمصك والميماس دجلة والكرخا\nوقد فجعت بالفرخ أمس حمامة، … فما بالها تلفي بموضعها فرخا؟"},{"id":"diwan-maarri:252","bookId":"diwan-maarri","type":"poem","seq":252,"chapter":"قصائد","title":"ذكوا على مذهب الكوفي أرضكم،","page":"","text":"ذكوا على مذهب الكوفي أرضكم، … وجانبوا رأيه في مسكر طبخا\nولا تكن هبة الخلات، عندكم، … كالغيث وافق، في إبانه، السبخا"},{"id":"diwan-maarri:253","bookId":"diwan-maarri","type":"poem","seq":253,"chapter":"قصائد","title":"إذا مات ابنها صرخت بجهل،","page":"","text":"إذا مات ابنها صرخت بجهل، … وماذا تستفيد من الصراخ؟\nستتبعه، كعطف الفاء ليست … بمهل، أو كثم على التراخي؟"},{"id":"diwan-maarri:254","bookId":"diwan-maarri","type":"poem","seq":254,"chapter":"قصائد","title":"إن كنت يا ورقاء مهدية،","page":"","text":"إن كنت يا ورقاء مهدية، … فلا تبني الوكر للأفرخ\nولا تكوني مثل إنسية، … متى ينبها حادث تصرخ\nوانفردي في بلد عازب … عنا، وعيشي ذات بال رخي"},{"id":"diwan-maarri:255","bookId":"diwan-maarri","type":"poem","seq":255,"chapter":"قصائد","title":"أحسن بهذا الشرع من ملة،","page":"","text":"أحسن بهذا الشرع من ملة، … يثبت لا ينسخ فيما نسخ\nجاءت أعاجيب، فويح لنا! … كأننا في عالم قد مسخ\nوالجسم كالثوب على روحه، … ينزع أن يخلق، أو يتسخ\nوالنجل إن برا، وإن فاجرا، … كالغصن، من أصل أبيه، فسخ"},{"id":"diwan-maarri:256","bookId":"diwan-maarri","type":"poem","seq":256,"chapter":"قصائد","title":"ألم تر أن الخير يكسبه الحجى","page":"","text":"ألم تر أن الخير يكسبه الحجى … طريفا، وأن الشر في الطبع متلد؟\nلقد رابني مغدى الفقير، بجهله، … على العير، ضربا، ساء ما يتقلد\nيحمله ما لا يطيق، فإن ونى، … أحال على ذي فترة يتجلد\nيظل كزان مفتر، غير محصن، … يقام عليه الحد، شفعا، فيجلد\nتظاهر أبلاد الرزايا بظهره … وكشحيه، فاعذر عاجزا يتبلد\nلنا خالق لا يمتري العقل أنه … قديم، فما هذا الحديث المولد؟\nوإن كان زند البر لم يور طائلا، … فتلك زناد الغي أكبا وأصلد\nوما سرني أني أصبت معاشرا … بظلم، وأني في النعيم مخلد"},{"id":"diwan-maarri:257","bookId":"diwan-maarri","type":"poem","seq":257,"chapter":"قصائد","title":"يكون أخو الدنيا ذليلا، موطأ،","page":"","text":"يكون أخو الدنيا ذليلا، موطأ، … وإن قيل، في الدهر، الأمير المؤيد\nولا بد من خطب يصيب فؤاده … بسهم، فيضحي، الصائد، المتصيد\nبقيت، وإن كان البقاء محببا، … إلى أن وددت العيش لا يتزيد\nوسرت، وقيدي بالحوادث محكم، … كما سار بيت الشعر، وهو مقيد\nوما العمر إلا كالبناء، فإن يزد … على حده، فهو الرفيع المشيد"},{"id":"diwan-maarri:258","bookId":"diwan-maarri","type":"poem","seq":258,"chapter":"قصائد","title":"رميت ظباء القفر، كيما تصيدها،","page":"","text":"رميت ظباء القفر، كيما تصيدها، … ومن صاد عفو الله أرمى وأصيد\nأجدك، هل أنسيت صحبك في السرى، … وكلهم، من نعسة الفجر، أغيد\nكهول عتوا في سنهم، وكأنهم … غصون، على ميس الركائب، ميد\nإذا الصبح أعطى العين عنقود كرمة … ملاحية، ما أملت، أخذه، اليد"},{"id":"diwan-maarri:259","bookId":"diwan-maarri","type":"poem","seq":259,"chapter":"قصائد","title":"لعل نجوم الليل تعمل فكرها","page":"","text":"لعل نجوم الليل تعمل فكرها … لتعلم سرا، فالعيون سواهد\nخرجت إلى ذي الدار كرها، ورحلتي … إلى غيرها بالرغم، والله شاهد\nفهل أنا فيما بين ذينك مجبر، … على عمل، أم مستطيع، فجاهد؟\nعدمتك يا دنيا، فأهلك أجمعوا … على الجهل؛ طاغ: مسلم ومعاهد\nفمفتضح يبدي ضمائر صدره؛ … ومخف ضمير النفس، فهو مجاهد\nأخو شيبة طفل المراد، وهمة، … لها همة، في العيش، عذراء ناهد\nفوا عجبا نقفو أحاديث كاذب، … ونترك، من جهل بنا، ما نشاهد\nلقد ضل هذا الخلق، ما كان فيهم، … ولا كائن، حتى القيامة، زاهد"},{"id":"diwan-maarri:260","bookId":"diwan-maarri","type":"poem","seq":260,"chapter":"قصائد","title":"كأنك، عن كيد الحوادث، راقد،","page":"","text":"كأنك، عن كيد الحوادث، راقد، … وما أمنته، في السماء، الفراقد\nسيجري، على نيران فارس، طارق … فتخمد، والمريخ، في العين، راقد\nوما ابتسمت أيامه النكد عن رضى، … ولكن تحاشى، والصدور حواقد\nأأنفق من نفسي، على الله، زائفا، … لألحق بالأبرار، والله ناقد؟\nوشخصي وروحي مثل طفل وأمه، … لتلك بهذا، من يد الرب، عاقد\nيموتان، مثل الناظرين، تواردا، … فلا هو مفقود، ولا هي فاقد\nولو قبلت أمر المليك جنوبنا، … لما قبلتها، في الظلام، المراقد"},{"id":"diwan-maarri:261","bookId":"diwan-maarri","type":"poem","seq":261,"chapter":"قصائد","title":"يحق كساد الشعر في كل موطن،","page":"","text":"يحق كساد الشعر في كل موطن، … إذا نفقت هذي العروض الكواسد\nعفاة القوافي، كالذي ولماتها، … إذا هن لم يوصلن، فاللفظ فاسد\nومن عاش بين الناس لم يخل من أذى … بما قال واش، أو تكلم حاسد\nوليس جساد في ترائب كاعب، … كأحمر منه مضرب السيف جاسد"},{"id":"diwan-maarri:262","bookId":"diwan-maarri","type":"poem","seq":262,"chapter":"قصائد","title":"ألا إن أخلاق الفتى كزمانه،","page":"","text":"ألا إن أخلاق الفتى كزمانه، … فمنهن بيض، في العيون، وسود\nوتأكلنا أيامنا، فكأنما … تمر بنا الساعات، وهي أسود\nوقد يخمل الإنسان في عنفوانه، … وينبه من بعد النهى، فيسود\nفلا تحسدن يوما على فضل نعمة، … فحسبك عارا أن يقال حسود"},{"id":"diwan-maarri:263","bookId":"diwan-maarri","type":"poem","seq":263,"chapter":"قصائد","title":"عرفت سجايا الدهر: أما شروره","page":"","text":"عرفت سجايا الدهر: أما شروره … فنقد، وأما خيره فوعود\nإذا كانت الدنيا كذاك، فخلها، … ولو أن كل الطالعات سعود\nرقدنا، ولم نملك رقادا عن الأذى؛ … وقامت بما خفنا، ونحن قعود\nفلا يرهبن الموت من ظل راكبا، … فإن انحدارا، في التراب، صعود\nوكم أنذرتنا بالسيول صواعق؛ … وكم خبرتنا بالغمام رعود"},{"id":"diwan-maarri:264","bookId":"diwan-maarri","type":"poem","seq":264,"chapter":"قصائد","title":"لعمري! لقد أدلجت، والركب خالف،","page":"","text":"لعمري! لقد أدلجت، والركب خالف، … وأحييت ليلي، والنجوم شهود\nرجبت سرابيا، كأن إكامه … جوار، ولكن ما لهن نهود\nتمجس حرباء الهجيري وحوله … رواهب خيط، والنعام يهود\nوقد طال عهدي بالشباب، وغيرت … عهود الصبا، للحادثات، عهود\nوزهدني، في هضبة المجد، خبرتي … بأن قرارات الرجال وهود\nكأن كهول القوم أطفال أشهر … تناغت، وأكوار القلاص مهود\nإذا حدثوا لم يفهموا، وإذا دعوا … أجابوا، وفيهم رقدة وسهود\nلهم منصب الإنس المبين، وإنما … على العيس منهم بالنعاس فهود"},{"id":"diwan-maarri:265","bookId":"diwan-maarri","type":"poem","seq":265,"chapter":"قصائد","title":"حياتي، بعد الأربعين، منية،","page":"","text":"حياتي، بعد الأربعين، منية، … ووجدان حلف الأربعين فقود\nفما لي، وقد أدركت خمسة أعقد؟ … أبيني وبين الحادثات عقود؟\nكأنا، من الأيام، فوق ركائب، … إذا قيدت الأنضاء، فهي تقود\nفدل هجير، في زمانك، أنه … سخائم، في أحشائه، وحقود"},{"id":"diwan-maarri:266","bookId":"diwan-maarri","type":"poem","seq":266,"chapter":"قصائد","title":"ألا إنما الدنيا نحوس لأهلها،","page":"","text":"ألا إنما الدنيا نحوس لأهلها، … فما في زمان أنت فيه سعود\nيوصي الفتى، عند الحمام، كأنه … يمر فيقضي حاجة ويعود\nوما يئست، من رجعة، نفس ظاعن … مضت، ولها عند القضاء وعود\nتسير بنا الأيام، وهي حثيثة، … ونحن قيام، فوقها، وقعود\nفما خشيت، في السير، زلة عاثر، … ولكن تساوى مهبط وصعود"},{"id":"diwan-maarri:267","bookId":"diwan-maarri","type":"poem","seq":267,"chapter":"قصائد","title":"أودع يومي عالما ان مثله،","page":"","text":"أودع يومي عالما ان مثله، … إذا مر عن مثلي، فليس يعود\nوما غفلات العيش إلا مناحس، … وإن ظن قوم أنهن سعود\nكأني، على العود الركوب مهجرا، … إذا نص حرباء الظهيرة، عود\nسرى الموت في الظلماء والقوم في الكرى، … وقام على ساق، ونحن قعود\nوتلك، لعمر الله، أصعب خطة، … كأن حدوري في التراب صعود\nوإن حياتي، للمنايا، سحابة؛ … وإن كلامي، للحمام، رعود\nينجز هذا الدهر ما كان موعدا، … وتمطل منه، بالرجاء، وعود"},{"id":"diwan-maarri:268","bookId":"diwan-maarri","type":"poem","seq":268,"chapter":"قصائد","title":"يود الفتى أن الحياة بسيطة؛","page":"","text":"يود الفتى أن الحياة بسيطة؛ … وأن شقاء العيش ليس يبيد\nكذاك نعام القفر يخشى من الردى، … وقوتاه: مرو، بالفلا، وهبيد\nوقد يخطىء الرأي امرؤ، وهو حازم، … كما اختل، في وزن القريض، عبيد\nمضى الواقف الكندي، والسقط غابر، … وصاحت ديار الحي: أين لبيد؟\nتولى ابن حجر، لا يعود لشأنه، … وطالت ليال، والمعالم بيد"},{"id":"diwan-maarri:269","bookId":"diwan-maarri","type":"poem","seq":269,"chapter":"قصائد","title":"إلى الله أشكو مهجة لا تطيعني،","page":"","text":"إلى الله أشكو مهجة لا تطيعني، … وعالم سوء، ليس فيه رشيد\nحجى، مثل مهجور المنازل، داثر، … وجهل، كمسكون الديار، مشيد\nلقد ضل حلم الناس مذ عهد آدم، … فهل هو من ذاك الضلال نشيد؟"},{"id":"diwan-maarri:270","bookId":"diwan-maarri","type":"poem","seq":270,"chapter":"قصائد","title":"أبيدة قالت للوعول، مسرة:","page":"","text":"أبيدة قالت للوعول، مسرة: … تبدن بحكم الله، ثم أبيد\nولا أدعي للفرقدين بعزة، … ولا آل نعش، ما ادعاه لبيد\nوكم ظالم يلتذ شهدا، كأنه … ظليم، قراه، بالفلاة، هبيد\nوكدرية أودت، وغودر مدهن؛ … وبيدانة، منها المراتع بيد\nفإن عبيدا، وابن هند، وتبعا، … وأسرة كسرى، للمليك عبيد"},{"id":"diwan-maarri:271","bookId":"diwan-maarri","type":"poem","seq":271,"chapter":"قصائد","title":"تسمى رشيدا، من لؤي بن غالب،","page":"","text":"تسمى رشيدا، من لؤي بن غالب، … أمير، وهل في العالمين رشيد؟\nفإن أغاني الليالي نياحة، … ومنها بسيط مقتضى، ونشيد"},{"id":"diwan-maarri:272","bookId":"diwan-maarri","type":"poem","seq":272,"chapter":"قصائد","title":"ما وفقوا، حسبوني من خيارهم،","page":"","text":"ما وفقوا، حسبوني من خيارهم، … فخلهم، لا يرجى منهم الرشد\nأما إذا ما دعا الداعي لمكرمة، … فهل قليل، ولكن، في الأذى، حشد\nكم ينشدون صفاء من ديانتهم، … وليس يوجد، حتى الموت، ما نشدوا"},{"id":"diwan-maarri:273","bookId":"diwan-maarri","type":"poem","seq":273,"chapter":"قصائد","title":"الروح تنأى، فلا يدرى بموضعها،","page":"","text":"الروح تنأى، فلا يدرى بموضعها، … وفي التراب، لعمري، يرفث الجسد\nوقد علمنا بأنا، في عواقبنا، … إلى الزوال، ففيم الضغن والحسد؟\nوالجيد ينعم، أو يشقى، ويدركه … ريب المنون، فلا عقد ولا مسد\nيصادف الظبي وابن الظبي قاضية … من حتفه، وكذاك الشبل والأسد\nونحن في عالم، صيغت أوائله … على الفساد، فغي قولنا: فسدوا\nتنفقوا بالخنى والجهل، إذ نفقوا … عند السفاه، وهم، عند الحجى، كسد"},{"id":"diwan-maarri:274","bookId":"diwan-maarri","type":"poem","seq":274,"chapter":"قصائد","title":"عاشوا، كما عاش آباء لهم سلفوا،","page":"","text":"عاشوا، كما عاش آباء لهم سلفوا، … وأورثوا الدين تقليدا، كما وجدوا\nفما يراعون ما قالوا، وما سمعوا؛ … ولا يبالون، من غي، لمن سجدوا\nوالعدم أروح مما فيه عالمهم، … وهو التكلف، إن هبوا، وإن هجدوا\nلم يحم فارس حي، من ردى، فرس؛ … ولا أجدت، فأجدت عرمس أجد\nوالحظ يسري، فيغشى معشرا، حسبوا … من اللئام، وتقضى، دونه، المجد\nوما توقى، سيوف الهند، بيض طلى، … بأن تناط، إلى أعناقها، النجد\nقد يدأب الرجل المنجود، مجتهدا، … في رزق آخر، لم يلمم به النجد"},{"id":"diwan-maarri:275","bookId":"diwan-maarri","type":"poem","seq":275,"chapter":"قصائد","title":"لولا التنافس في الدنيا، لما وضعت","page":"","text":"لولا التنافس في الدنيا، لما وضعت … كتب القناطر، لا المغني، ولا العمد\nقد بالغوا في كلام بان زخرفه، … يوهي العيون، ولم تثبت له عمد\nوما يزالون، في شام وفي يمن، … يستنبطون قياسا ما له أمد\nفذرهم ودناياهم، فقد شغلوا … بها، ويكفيك منها القادر الصمد"},{"id":"diwan-maarri:276","bookId":"diwan-maarri","type":"poem","seq":276,"chapter":"قصائد","title":"تجاوزت عني الأقدار، ذاهبة،","page":"","text":"تجاوزت عني الأقدار، ذاهبة، … فقد تأبدت، حتى ملني الأبد\nوليس هدبا جفوني ريشتي سبد، … إذا تمطر، تحت العارض، السبد\nنشكو إلى الله أنا سيئو شيم، … نحن العبيد، وفي آنافنا عبد\nوالمرء ظالم نفس، تجتني مقرا، … يظنه الشهد، والظلمان تهتبد\nوما تزال جسوم، في محابسها، … حتى يفرج عن أكبادها الكبد\nشربت قهوة هم، كأسها خلدي، … وفي المفارق، مما أطلعت، زبد\nفاجعل سوامك نهبى، ما بكت إبل … مثوى لبيد، ولا أوبارها اللبد\nوالملك يفنى، ولا يبقى لمالكه، … أودى ابن عاد، وأودى نسره لبد"},{"id":"diwan-maarri:277","bookId":"diwan-maarri","type":"poem","seq":277,"chapter":"قصائد","title":"صير عتادك تقوى الله تذخرها،","page":"","text":"صير عتادك تقوى الله تذخرها، … ينجيك منه السابح العتد\nوالحكم جار على الأكتاد، محتمل، … ولا يطيق ثباتا، تحته، الكتد\nكم زال جيل، وهذي الأرض باقية، … ما هم بالزيغ، من أوتادها، وتد\nأقتاد هما بأقتاد على إبل؛ … وهل يبلغ، ما أملته، القتد؟"},{"id":"diwan-maarri:278","bookId":"diwan-maarri","type":"poem","seq":278,"chapter":"قصائد","title":"لو يفهم الناس، ما أبناؤهم جلب،","page":"","text":"لو يفهم الناس، ما أبناؤهم جلب، … وبيع، بالفلس، ألف منهم كسدوا\nفويحهم، بئس ما ربوا وما حضنوا؛ … فهي الخديعة والأضغان والحسد\nوكلنا، في مساعيه، أبو لهب؛ … وعرسهم لم يقع، في جيدها، مسد\nوما الدني، ذراع الخود نمرقه، … مثل السني، ذراع الجسر يتسد\nوالجسم للروح مثل الربع تسكنه، … وما تقيم، إذا ما خرب الجسد\nوهكذا كان أهل الأرض، مذ فطروا؛ … فلا يظن جهول أنهم فسدوا\nما أنت والروض تلقى من غمائمه، … فيه المفارش، للثاوين، والوسد\nكأنما شب، في أقطاره، قطر … بالغيث، أن بال فيه الثور والأسد"},{"id":"diwan-maarri:279","bookId":"diwan-maarri","type":"poem","seq":279,"chapter":"قصائد","title":"أهل البسيطة، في هم حياتهم،","page":"","text":"أهل البسيطة، في هم حياتهم، … ولا يفارق، أهل النجدة، النجد\nأمثالنا كان جيل، قبلنا، فمضوا، … ومثل رزء وجدنا حسه، وجدوا\nوالمجد لله لا خلق يشاركه، … وآل حواء ما طابوا ولا مجدوا\nأما إلى كل شر عن، فانتبهوا … بل لم يناموا، ولكن عن تقى هجدوا\nوالناس يطغون، في دنياهم، أشرا، … لولا المخافة مازكوا ولا سجدوا"},{"id":"diwan-maarri:280","bookId":"diwan-maarri","type":"poem","seq":280,"chapter":"قصائد","title":"في كل أمرك تقليد رضيت به،","page":"","text":"في كل أمرك تقليد رضيت به، … حتى مقالك ربي واحد أحد\nوقد أمرنا بفكر في بدائعه، … وإن تفكر فيه معشر لحدوا\nوأهل كل جدال يمسكون به، … إذا رأوا نور حق ظاهر جحدوا"},{"id":"diwan-maarri:281","bookId":"diwan-maarri","type":"poem","seq":281,"chapter":"قصائد","title":"حوادث الدهر أملاك، لها قنص،","page":"","text":"حوادث الدهر أملاك، لها قنص، … والإنس وحش، فقد أزرى بها الطرد\nوما تبقي، سهام المرء، كثرتها؛ … فاقض الحياة، وأنت الصارم الفرد\nوالشيب شابوا على جهل ومنقصة؛ … والمرد، في كل أمر باطل، مردوا\nوالعيش، كالماء، تغشاه حوائمنا، … فصادرون، وقوم إثرهم وردوا\nومد وقتي، مثل القصر غايته؛ … وفي الهلاك تساوى الدر والبرد\nيا رب أفواه غيد أملئت شنبا، … ثم استحال، ففي أوطانه الدرد\nيغدو، على درعه، الزراد يحكمها، … وهل ينجيه، مما قدر، الزرد؟"},{"id":"diwan-maarri:282","bookId":"diwan-maarri","type":"poem","seq":282,"chapter":"قصائد","title":"عجبت للمدنف المشفي على تلف،","page":"","text":"عجبت للمدنف المشفي على تلف، … ومن يحدث عنه، بالردى، خلدوا\nفهل بلاد يعري الموت ساكنها، … فيبتغى، في الثريا، ذلك البلد؟\nيشقى الوليد، ويشقى والده به، … وفاز من لم يوله، عقله، ولد\nإذا تلبس، بالشجعان، جبنهم، … وبالكرام أسر الضن، أو صلدوا\nعظم ونحض تبنى، منهما، طلل، … كأنها الأرض منها السهل والجلد"},{"id":"diwan-maarri:283","bookId":"diwan-maarri","type":"poem","seq":283,"chapter":"قصائد","title":"إن جاد بالمال سمح، يبتغي شرفا،","page":"","text":"إن جاد بالمال سمح، يبتغي شرفا، … آلت معاشر: ما في كفه جود\nلو ماجد النجم أهل الأرض، عارضه، … منهم، رجال، فقالوا: أنت ممجود\nفالرأي هجرانك الدنيا وساكنها … فأنت، من جود هذي النفس، منجود\nلا تذهب الوجد في إيثار وجدهم، … فإن ذمك، بين الإنس، موجود\nوإن تهجدت، لم تعدم ثواب تقى؛ … وإن هجدت، فإن الليل مهجود"},{"id":"diwan-maarri:284","bookId":"diwan-maarri","type":"poem","seq":284,"chapter":"قصائد","title":"عش ما بدا لك، لا يبقى على زمن،","page":"","text":"عش ما بدا لك، لا يبقى على زمن، … مخودات، ولا أسد، ولا خود\nإن كنت جلدا، فأجلادي إلى نفد؛ … كم صخرة قد تشظت، وهي صيخود"},{"id":"diwan-maarri:285","bookId":"diwan-maarri","type":"poem","seq":285,"chapter":"قصائد","title":"نقضي الحياة، ولم يفصد لشاربنا","page":"","text":"نقضي الحياة، ولم يفصد لشاربنا … دن، ولا عودنا، في الجدب، مفصود\nنفارق العيش، لم نظفر بمعرفة؛ … أي المعاني، بأهل الأرض، مقصود\nلم تعطنا، العلم، أخبار يجيء بها … نقل، ولا كوكب، في الأرض، مرصود\nوابيض ما اخضر من نبت الزمان بنا؛ … وكل زرع، إذا ما هاج، محصود"},{"id":"diwan-maarri:286","bookId":"diwan-maarri","type":"poem","seq":286,"chapter":"قصائد","title":"أودوا إلى الله، ما أد مفخرها","page":"","text":"أودوا إلى الله، ما أد مفخرها … شيء يعد، ولا أود ولا أود\nطوبى لموؤودة في حال مولدها، … ظلما، فليت أباها الفظ موؤود\nيا رب! هل أنا بالغفران، في ظعني … مزود؟ إن قلبي منك مزؤود\nوالناس كالأيك، مخبو لعاضده، … إلى اليبوس، وماض، وهو يمؤود"},{"id":"diwan-maarri:287","bookId":"diwan-maarri","type":"poem","seq":287,"chapter":"قصائد","title":"الصبر يوجد، إن باء له كسرت،","page":"","text":"الصبر يوجد، إن باء له كسرت، … لكنه، بسكون الباء، مفقود\nويحمد الصابر الموفي على غرض، … لا عاجز، بعرى التقصير، معقود\nوقد نفت عنك، إغماضا، ملاحية … في كرمها، وكأن النجم عنقود\nوالمهر، يعطيه أنثى، غير منصفة، … سيب من الله، والمهرية القود\nوالنقد يهدى إلى الدينار، مكرمة؛ … فليته، بعد حسن الضرب، منقود\nلا يحمل الليل هم الساهرين به؛ … ولا يجانب حزنا، وهو مرقود"},{"id":"diwan-maarri:288","bookId":"diwan-maarri","type":"poem","seq":288,"chapter":"قصائد","title":"أسر، إن كنت محمودا على خلق؛","page":"","text":"أسر، إن كنت محمودا على خلق؛ … ولا أسر بأني الملك محمود\nما يصنع الرأس بالتيجان يعقدها؛ … وإنما هو، بعد الموت، جلمود"},{"id":"diwan-maarri:289","bookId":"diwan-maarri","type":"poem","seq":289,"chapter":"قصائد","title":"إن الغنى لعزيز، حين تطلبه،","page":"","text":"إن الغنى لعزيز، حين تطلبه، … والفقر، في عنصر التركيب، موجود\nوالشح ليس غريبا عند أنفسنا، … بل الغريب، وإن لم يرحم، الجود"},{"id":"diwan-maarri:290","bookId":"diwan-maarri","type":"poem","seq":290,"chapter":"قصائد","title":"بقيت حتى كسا الخدين جونهما،","page":"","text":"بقيت حتى كسا الخدين جونهما، … ثم استحال، ومس الجسم تخديد\nبلوت، من هذه الدنيا وساكنها، … عجائبا، وانتهاء الثوب تقديد\nردي كلامك، ما أمللت مستمعا؛ … وهل يمل، من الأنفاس، ترديد؟\nهاجت، بكاي، أغاني القيان بها، … كأنها، من ذوات الثكل، تعديد\nوالناس، في الأرض، أجناس مقلدة، … كالهدي قلد، لم يذعره تهديد\nقالوا، فلما أحالوا أظهروا لددا؛ … فالقول مين، وفي الأصوات تنديد\nضلوا عن الرشد، منهم جاحد جحد، … أو من يحد، وهل، لله، تحديد؟\nلفظ يبدد، من شرخ ومكتهل؛ … والمال يجمع، لم يدركه تبديد\nرموا، فأشووا، ولم يثبت قياسهم … شيئا، سوى أن رمي الموت تسديد\nما سيد غير رعديد علمت به، … كأنما الحتف، إن لاقاه، رعديد\nوالخير يجلب شرا، والذباب دعا … إلى الجنى، إنه في الطعم قنديد\nوخلت أني حرف الوقف، سكنه … وقت، وأدركه، في ذاك، تشديد\nوأشرف الناس، في أعلى مراتبه، … مثل الصديد، ولكن قيل صنديد\nما كبره، وثقيل اللحن يمنعه، … من سرعة الفهم، ترسيل وتمديد"},{"id":"diwan-maarri:291","bookId":"diwan-maarri","type":"poem","seq":291,"chapter":"قصائد","title":"أما الصحاب، فقد مروا وما عادوا،","page":"","text":"أما الصحاب، فقد مروا وما عادوا، … وبيننا، بلقاء الموت، ميعاد\nسر قديم، وأمر غير متضح؛ … فهل، على كشفنا للحق، إسعاد؟\nسيران ضدان من روح ومن جسد، … هذا هبوط، وهذا فيه إصعاد\nأخذ المنايا سوانا، وهي تاركة … قبيلنا، عظة منها وإيعاد\nتوقعوا السيل، أوفى عارض وله … في العين برق، وفي الأسماع إرعاد"},{"id":"diwan-maarri:292","bookId":"diwan-maarri","type":"poem","seq":292,"chapter":"قصائد","title":"إلهنا الله، ملك أول، أحد،","page":"","text":"إلهنا الله، ملك أول، أحد، … تطيعه، من صنوف الناس، آحاد\nلقد عرضنا على الأبرار دينكم، … فكلهم، عن دنايا فعلكم، حادوا\nإن المجوس لأزكى منكم عملا؛ … وإنما شأنكم جحد وإلحاد"},{"id":"diwan-maarri:293","bookId":"diwan-maarri","type":"poem","seq":293,"chapter":"قصائد","title":"الملك لله، لا ننفك في تعب،","page":"","text":"الملك لله، لا ننفك في تعب، … حتى تزايل أرواح وأجساد\nولا يرى حيوان، لا يكون له، … فوق البسيطة، أعداء وحساد\nوما أؤمل، عند الدهر، مصلحة؛ … وإنما هو إتلاف وإفساد\nولا أسر، إذا ما أسرتي خملوا، … وهل أمنت عليهم، إن هم سادوا؟\nوالناس مثل ضراء الصيد، إن غفلت … عن شأنها، فلها بالطبع إيساد\nإذا الأصاغر لاقتها أكابرها، … فتلك، في الشر، أشبال وآساد"},{"id":"diwan-maarri:294","bookId":"diwan-maarri","type":"poem","seq":294,"chapter":"قصائد","title":"الناس، للأرض، أتباع، إذا بخلت","page":"","text":"الناس، للأرض، أتباع، إذا بخلت … ضنوا، وإن هي جادت، مرة، جادوا\nتماجد القوم، والألباب مخبرة … أن ليس، في هذه الأجيال، أمجاد\nوالملك لله، والدنيا بها غير: … خير وشر وإعدام وإيجاد\nوالناس شتى، ولم يجمعهم غرض: … شد وحل وإتهام وإنجاد\nيا ليل! ضدان: قوم في الدجى سهر … تهجدوك، وقوم فيك هجاد\nأنجد أخاك على خير يهم به، … فالمؤمنون، لدى الخيرات، أنجاد"},{"id":"diwan-maarri:295","bookId":"diwan-maarri","type":"poem","seq":295,"chapter":"قصائد","title":"قد وعظتني بك الليالي؛","page":"","text":"قد وعظتني بك الليالي؛ … بغيره يوعظ السعيد\nأبدىء قلى، أو أعد جفاء؛ … فربك المبدىء المعيد\nأنت أمير، وأنت قاض، … وشأنك الوعد والوعيد\nكاليوم بانت فضيلتاه … بأنه جمعة، وعيد\nثم انقضى، فهو غير آت، … من وصفه النازح البعيد\nتعاقب الأنعم الرزايا، … ويخلف، الجابه، القعيد\nأحسن بما القيل فيه غاد، … لو لم يكن، قصره، الصعيد"},{"id":"diwan-maarri:296","bookId":"diwan-maarri","type":"poem","seq":296,"chapter":"قصائد","title":"إن صح لي أنني سعيد،","page":"","text":"إن صح لي أنني سعيد، … فليتني ضمني صعيد\nصمت حياتي إلى مماتي، … لعل يوم الحمام عيد\nوراعني للحساب ذكر، … وغرني أنه بعيد\nوعن يميني وعن شمالي، … يصحبني حافظ قعيد\nحمامة في غصون أيك، … ناحت فأنشأت أستعيد\nوما فقهت المراد منها، … كل فقيه له معيد\nإذا رجونا قضاء وعد، … فكيف لا يرهب الوعيد!"},{"id":"diwan-maarri:297","bookId":"diwan-maarri","type":"poem","seq":297,"chapter":"قصائد","title":"خمرت من الخمار، وذاك نجس،","page":"","text":"خمرت من الخمار، وذاك نجس، … وأما من خمارك، فهو سعد\nونفسك ظبية رتعت بقفر، … يراقب، أخذها، المغوار، جعد\nوزينب، إن أصابتها المنايا، … فهند من وسائقها، ودعد\nجرت عاداتنا بسقوط غيث، … تدل عليه بارقة ورعد\nشرور الدهر أكثر من بنيه، … فقبل، سطت على أمم، وبعد\nتعجل ميت بالهلك نقدا، … فمر، وعنده، للبعث، وعد"},{"id":"diwan-maarri:298","bookId":"diwan-maarri","type":"poem","seq":298,"chapter":"قصائد","title":"أعد لبذلك الإحسان فضلا؛","page":"","text":"أعد لبذلك الإحسان فضلا؛ … وكم من معشر بخلوا وسادوا\nفجد، إن شئت مربحة الليالي، … فما للجود، في سوق، كساد\nأبيت المال بيت من مقال، … متى ينقص يلم به الفساد؟"},{"id":"diwan-maarri:299","bookId":"diwan-maarri","type":"poem","seq":299,"chapter":"قصائد","title":"يحرق نفسه الهندي خوفا،","page":"","text":"يحرق نفسه الهندي خوفا، … ويقصر، دون ما صنع، الجهاد\nوما فعلته عباد النصارى، … ولا شرعية صبأوا وهادوا\nيقرب جسمه للنار عمدا، … وذلك منه دين واجتهاد\nوموت المرء نوم طال جدا … عليه، وكل عيشته سهاد\nنودع بالصلاة وداع يأس، … ونترك في التراب فلا نهاد\nأهال من الثرى، والأرض أم، … وأمك حجرها نعم المهاد\nإذا الروح اللطيفة زايلتني، … فلا هطلت على الرمم العهاد"},{"id":"diwan-maarri:300","bookId":"diwan-maarri","type":"poem","seq":300,"chapter":"قصائد","title":"تفوه دهركم عجبا، فأصغوا","page":"","text":"تفوه دهركم عجبا، فأصغوا … إلى ما ظل يخبر، يا شهود\nإذا افتكر الذين لهم عقول … رأوا نبأ، يحق له السهود\nغدا أهل الشرائع في اختلاف، … تقض به المضاجع والمهود\nفقد كذبت على عيسى النصارى، … كما كذبت على موسى اليهود\nولم تستحدث الأيام خلقا، … ولا حالت، من الزمن، العهود"},{"id":"diwan-maarri:301","bookId":"diwan-maarri","type":"poem","seq":301,"chapter":"قصائد","title":"إذا بلغ الوليد لديك عشرا،","page":"","text":"إذا بلغ الوليد لديك عشرا، … فلا يدخل على الحرم الوليد\nفإن خالفتني وأضعت نصحي، … فأنت، وإن رزقت حجى، بليد\nألا إن النساء حبال غي، … بهن يضيع الشرف التليد"},{"id":"diwan-maarri:302","bookId":"diwan-maarri","type":"poem","seq":302,"chapter":"قصائد","title":"أرى الأيام تفعل كل نكر،","page":"","text":"أرى الأيام تفعل كل نكر، … فما أنا، في العجائب، مستزيد\nأليس قريشكم قتلت حسينا، … وصار، على خلافتكم، يزيد؟"},{"id":"diwan-maarri:303","bookId":"diwan-maarri","type":"poem","seq":303,"chapter":"قصائد","title":"تعالى الله! ما تلقى المطايا","page":"","text":"تعالى الله! ما تلقى المطايا … من الإنسان، والدنيا تصيد؟\nإذا سلمت فنص في الموامي، … فواصد ما به فني القصيد\nوما ينفك، في السنوات، منها … حليب، أو نحير، أو فصيد\nأتجزى، الخير، صيد من ركاب، … كما تجزى، من الأملاك، صيد؟\nأم الإلغاء يشملها، فتضحي، … كأن سوامها زرع حصيد؟\nوكيف، وربها في الحكم عدل، … ودنياها، لخالقها، وصيد!"},{"id":"diwan-maarri:304","bookId":"diwan-maarri","type":"poem","seq":304,"chapter":"قصائد","title":"لا كانت الدنيا، فليس يسرني","page":"","text":"لا كانت الدنيا، فليس يسرني … أني خليفتها، ولا محمودها\nوجهلت أمري، غير أني سالك … طرقا، وختها عادها وثمودها\nزعموا بأن الهضب سوف يذيبه … قدر، ويحدث، للبحار، جمودها\nوتشاجروا في قبة الفلك، التي … ما زال يعظم، في النفوس، عمودها\nفيقول ناس: سوف يدركها الردى؛ … ويمين قوم: لا يجوز همودها\nأتدال يوما فضة من فضة؛ … فيصير، مثل سبيكة، جلمودها؟\nإن فرقت، شهب الثريا، نكبة، … فلجذوة المريخ حق خمودها\nوإذا سيوف الهند أدركها البلى، … فمن العجائب أن تدوم غمودها"},{"id":"diwan-maarri:305","bookId":"diwan-maarri","type":"poem","seq":305,"chapter":"قصائد","title":"أنا صائم طول الحياة، وإنما","page":"","text":"أنا صائم طول الحياة، وإنما … فطري الحمام، ويوم ذاك أعيد\nلونان من ليل وصبح لونا … شعري، وأضعفني الزمان الأيد\nوالناس كالأشعار ينطق دهرهم … بهم، فمطلق معشر، ومقيد\nقالوا: فلان جيد لصديقه، … لا يكذبوا، ما في البرية جيد\nفأميرهم نال الإمارة بالخنى، … وتقيهم، بصلاته، متصيد\nكن من تشاء مهجنا، أو خالصا، … وإذا رزقت غنى فأنت السيد\nواصمت، فما كثر الكلام من امرىء … إلا وظن بأنه متزيد"},{"id":"diwan-maarri:306","bookId":"diwan-maarri","type":"poem","seq":306,"chapter":"قصائد","title":"قد كان قبلك ذادة ومقاول","page":"","text":"قد كان قبلك ذادة ومقاول … ذادوا وما صرف، الخطوب، ذياد\nأمراء، حكام كأيام أتت، … شفعا بها، الجمعات والأعياد\nكزياد الأموي، أو كزياد الم … ري، إذ ولى، فأين زياد؟\nتثنى الخناصر في الكرام عليهم، … وتمد نحو سناهم الأجياد\nوالمطلقات، من النفوس، كأنما … جمعت لها الأغلال والأقياد\nوحبائل الأيام، ليس بمفلت … صقر مكائدها، ولا فياد"},{"id":"diwan-maarri:307","bookId":"diwan-maarri","type":"poem","seq":307,"chapter":"قصائد","title":"الله أكبر! ما اشتريت بضاعة،","page":"","text":"الله أكبر! ما اشتريت بضاعة، … إلا وأدرك، سوقها، الإكساد\nبدن بلا بدن يعيش، وكم طوى … جسد سنيه، وما عليه جساد\nأضحت تظن بك الديانة والغنى … والعلم، فاهتاجت لك الحساد\nولقد صفرت من الثلاث، كأنما … أدم حواك، من الخلو، مساد\nشغل، السعادة عنك، أهل ممالك … رزقوا الذي حرم الكرام، وسادوا\nرقدوا، ولم ترقد، ونالوا ما ابتغوا، … وعجزت عنه، وللكيان فساد\nومن المعاشر من يظل، كأنه … ضمن الفؤاد، يساد حين يساد\nخمدت خواطر منهم، وتكاثفت … أرواحهم، فكأنها أجساد\nمهدت لهم فرش، وبات لديهم … وسد، وبت، وما لديك وساد\nمن يؤت حظا يبتهج، ويكن له … عز، فترهب، ضأنه، الآساد\nولو ادعى ظبي الفلاة ولاءه، … لعداه، من قناصه، الإيساد"},{"id":"diwan-maarri:308","bookId":"diwan-maarri","type":"poem","seq":308,"chapter":"قصائد","title":"ما سرني أني إمام زمانه،","page":"","text":"ما سرني أني إمام زمانه، … تلقى إلي، من الأمور، مقالد\nيا حار! إن العمر حار، فانتبه! … يا خالد اتق، ليس يعرف خالد\nفعلام تجتلب الحمام، بجهلها، … مهج تطاعن في الوغى، وتجالد؟\nيرجو الأب الطفل الصغير، وطالما … هلك الوليد، وعاش فينا الوالد"},{"id":"diwan-maarri:309","bookId":"diwan-maarri","type":"poem","seq":309,"chapter":"قصائد","title":"آليت ما مثري الزمان، وإن طغا،","page":"","text":"آليت ما مثري الزمان، وإن طغا، … مثر، ولا مسعوده مسعود\nما سر غاوينا الجهول، وإنما … هتف الحمام به، وناح العود\nكاساته الملأى، وعزف قيانه، … للحادثات بوارق ورعود\nهلكت سعود، في القبائل، جمة؛ … وأقام، في جو السماء، سعود\nبدر يصور، ثم يمحق نوره، … ويغرب المريخ، ثم يعود\nلا تحملن ثقلا علي، فإنني، … وهنا، وقدام الركاب، صعود\nوالوعد يرقب، والنجاح، لمثلنا، … أن يستمر، بمطله، الموعود\nومن العجائب ظن قوم أنه … يثني الفتى بالغي، وهو قعود"},{"id":"diwan-maarri:310","bookId":"diwan-maarri","type":"poem","seq":310,"chapter":"قصائد","title":"كوني الثريا، أو حضار، أو ال","page":"","text":"كوني الثريا، أو حضار، أو ال … جوزاء، أو كالشمس لا تلد\nفلتلك أشرف من مؤنثة، … نجلت، فضاق بنسلها البلد"},{"id":"diwan-maarri:311","bookId":"diwan-maarri","type":"poem","seq":311,"chapter":"قصائد","title":"أقعد، فما نفع القيا","page":"","text":"أقعد، فما نفع القيا … م، ولا ثنى، خيرا، قعود\nغنتك دنياك الخلو … ب، وحبها، في الكف، عود\nأما إساءتها، فقد … كانت، وحسناها رعود\nوالمرء يهبط هاويا؛ … والعيش، من كلف، صعود\nوالشخص مثل اليوم يم … ضي في الزمان، فلا يعود\nأسعد بلا من، فإن … الجود بالنعمى سعود\nوالغيث أهنؤه الذي … يهمي، وليس له رعود"},{"id":"diwan-maarri:312","bookId":"diwan-maarri","type":"poem","seq":312,"chapter":"قصائد","title":"يا سابحا يصهل في غرة!","page":"","text":"يا سابحا يصهل في غرة! … أين وجيه الخيل والذائد؟\nآدى له، في الدهر، ما يبتغي، … ثم أتاه قدر آئد\nهل يأمن الحوت من الشهب أن … يأخذه، في الكفة، الصائد؟\nأو حمل نزه، في الجو، أن … يغتاله، بالمدية، الكائد؟\nإن كان للمريخ عقل، فما … يستر عنه أنه بائد\nيوصي الفتى بالأمر، من بعده، … كأنه، من بينه، عائد\nيكذبني الرائد، في زعمه، … ومهلك، إن كذب، الرائد\nوالخير لا يكفر، فليحسن المس … لم، والصابىء، والهائد\nفوائد الأيام محبوبة، … وفاقد، لذتها، الفائد\nفزج دنياك، فما يخلد ال … ناقص، في العيش، ولا الزائد\nوإن منهاج الردى يستوي، … فيه، مسود القوم والسائد\nوإنما يلقى شجاع الوغى، … كما يلاقي النافر الحائد\nتقصف، بالقدرة، رضوى، كما … يقصف هذا الغصن المائد\nولو درى الموؤود ما عندنا … من نبأ، ما عتب الوائد\nقد شيد القصر لسكانه، … وغير من يسكنه الشائد"},{"id":"diwan-maarri:313","bookId":"diwan-maarri","type":"poem","seq":313,"chapter":"قصائد","title":"إن شربوا الراح، فما شربنا،","page":"","text":"إن شربوا الراح، فما شربنا، … في الراح، إلا الأزرق البارد\nلا تطرد الوحش، فما يلبث ال … مطرود، في الدنيا، ولا الطارد\nأخت بني الصارد، في دهرها، … أصابها سهم ردى، صارد\nكان لها كرمان، هذا أبى ال … سقيا، وهذا أبدا وارد\nلا توحش الوحدة أصحابها، … إن سهيلا، وحده، فارد\nوكم ترى، في الأفق، من كوكب … يعظم أن يرمى به المارد\nخبرتني أمرا، فقل راشدا: … من أين هذا الخبر الشارد؟\nعليك بالصدق، فلا حظ لي … في كذب، ينظمه السارد\nمن يدن، للشاكة، أثوابه، … يصبه منها غصن هارد"},{"id":"diwan-maarri:314","bookId":"diwan-maarri","type":"poem","seq":314,"chapter":"قصائد","title":"مولاك مولاك، الذي ما له","page":"","text":"مولاك مولاك، الذي ما له … ند، وخاب الكافر الجاحد\nآمن به، والنفس ترقى، وإن … لم يبق إلا نفس واحد\nترج بذاك العفو منه، إذا … ألحدت ثم انصرف اللاحد"},{"id":"diwan-maarri:315","bookId":"diwan-maarri","type":"poem","seq":315,"chapter":"قصائد","title":"ما أسلم المسلمون شرهم،","page":"","text":"ما أسلم المسلمون شرهم، … ولا يهود لتوبة هادوا\nولا النصارى لدينهم نصروا، … وكلهم لي بذاك أشهاد"},{"id":"diwan-maarri:316","bookId":"diwan-maarri","type":"poem","seq":316,"chapter":"قصائد","title":"صاح، ما تضحك البروق شماتا","page":"","text":"صاح، ما تضحك البروق شماتا … بحمام، ولا تبكي الرعود\nيا محلي، عليك مني سلام، … سوف أمضي وينجز الموعود\nليت شعري، عمن يحلك بعدي، … أقيام لصالح أم قعود؟\nأيرجون أن أعود إليهم؟ … لا ترجوا، فإنني لا أعود!\nولجسمي إلى التراب هبوط، … ولروحي إلى الهواء صعود\nوعلى حالها تدوم الليالي، … فنحوس لمعشر أو سعود"},{"id":"diwan-maarri:317","bookId":"diwan-maarri","type":"poem","seq":317,"chapter":"قصائد","title":"سلوا، معشر الموتى، الذي جاء وافدا","page":"","text":"سلوا، معشر الموتى، الذي جاء وافدا … إليكم، يخبر، فهو أقربكم عهدا\nيحدثكم أن البلاد مقيمة … على ما عهدتم ذلك الهضب والوهدا\nولم تفتأ الدنيا تغر خليلها، … وتبدله، من غمض أجفانها، سهدا\nتريه الدجى في هيئة النور، خدعة، … وتطعمه صابا، فيحسبه شهدا\nوقد حملته فوق نعش، وطالما … سرى فوق عنس، أو علا فرسا نهدا\nولم تترك من حيلة لتغره، … ولم يبق، في إخلاصه، حبها جهدا"},{"id":"diwan-maarri:318","bookId":"diwan-maarri","type":"poem","seq":318,"chapter":"قصائد","title":"ألا ترحم الأشياخ لما تأودوا،","page":"","text":"ألا ترحم الأشياخ لما تأودوا، … يقولون: قد كنا الغرانقة المردا\nتردوا بخضر من حديد، وأقبلوا … على الخيل تردي، وهي من فوقها تردى\nوجاؤوا بها سوم الجراد، مغيرة، … يقودون، للموت، المطهمة الجردا\nترى الهم لا شيء، سوى الأكل، همه، … له جسد ما اسطاع حرا ولا بردا\nيقل العصا، مستثقل الطمر، بعدما … علا فرسا، واجتاب ماذية سردا\nولا تترك الأيام مردى لظبية … من الأدم، تختار الكباث ولا المردا\nولم يلف منها فارد القمر مخلصا، … وقد بلغت أحداثها القمر الفردا\nوجدنا دريدا، من هوازن، لم يجد … صروف الليالي، حين تأكله، دردا\nرعت قبل نبتا جد عدنان، واعترت … إيادا، فأبلت من قبائلها بردا\nيخوف، بالذئب، المسن، وقد مضى … له زمن، لا يرهب الأسد الوردا\nنزلنا بدار كالضيوف، ولم نرد … براحا لها، حتى أجدت لنا طردا"},{"id":"diwan-maarri:319","bookId":"diwan-maarri","type":"poem","seq":319,"chapter":"قصائد","title":"أرى حيوان الأرض، غير أنيسها،","page":"","text":"أرى حيوان الأرض، غير أنيسها، … إذا اقتات لم يفرح بظلم ولا جدا\nأتعلم أسد الغيل، بعد افتراسها، … تحاول درا، أو تحاول عسجدا؟\nوما اتخذ الأبراد سرحان قفرة، … ولا شب نارا أين غار وأنجدا\nوأضعف من تلقاه من آل آدم، … إذا ما شتا، يبغي وقودا وبرجدا\nوأنصفهم ما هابت الوحش سبة، … ولا وقعت من خشية الله سجدا"},{"id":"diwan-maarri:320","bookId":"diwan-maarri","type":"poem","seq":320,"chapter":"قصائد","title":"الخير كالعرفج الممطور، ضرمه","page":"","text":"الخير كالعرفج الممطور، ضرمه … راع، يئط، ولما أن ذكا خمدا\nوالشر كالنار، شبت، ليلها، بغضا، … يأتي على جمرها دهر، وما همدا\nأما ترى شجر الإثمار متعبة، … لم تجن، حتى أذاقت غارسا كمدا؟\nوالشاك في كل أرض، حان منبته، … بالطبع، لا الغمر يستسقي، ولا الثمدا\nلا تشكرن الذي يوليك عارفة، … حتى يكون، لما أولاك، معتمدا\nولا تشيمن حساما، كي تريق دما؛ … كفاك سيف لهذا الدهر ما غمدا\nوشاع في الناس قول لست أعهده، … وذاك أن رجالا ذامت الصمدا\nأيحمد المرء، لم يهمم بمكرمة، … يوما، ويترك مولى العرف ما حمدا؟"},{"id":"diwan-maarri:321","bookId":"diwan-maarri","type":"poem","seq":321,"chapter":"قصائد","title":"قد ساءها العقم، لا ضمت ولا ولدت!","page":"","text":"قد ساءها العقم، لا ضمت ولا ولدت! … وذاك خير لها لو أعطيت رشدا\nما يأخذ الموت، من نفس لمنفرد، … شيئا سواها، إذا ما اغتال واحتشدا\nومنشد الخير لا تصغي له أذن، … قد ضل مذ كانت الدنيا، فما نشدا"},{"id":"diwan-maarri:322","bookId":"diwan-maarri","type":"poem","seq":322,"chapter":"قصائد","title":"من عاش تسعين حولا، فهو مغترب،","page":"","text":"من عاش تسعين حولا، فهو مغترب، … قد زايل الأهل، إلا معشرا جددا\nوشاهد الناس من كهل، ومقتبل، … ودالف الخطو، لا يحصي لهم عددا"},{"id":"diwan-maarri:323","bookId":"diwan-maarri","type":"poem","seq":323,"chapter":"قصائد","title":"الصدر بيت، إذا ما السر زايله،","page":"","text":"الصدر بيت، إذا ما السر زايله، … فما يكن ببيت، بعده، أبدا\nفاحفظ ضميرك عن خل تجالسه؛ … فكم خفي خفاه ماكر، فبدا\nوللحقود علامات يبن بها، … كما رأيت، بشدق الهادر، الزبدا\nيستحسن المرء دنياه، فتقلته، … والعين تستحسن الهندي والربدا\nفازجر هواك، وحاذر أن تطاوعه، … فإنه لغوي، طالما عبدا"},{"id":"diwan-maarri:324","bookId":"diwan-maarri","type":"poem","seq":324,"chapter":"قصائد","title":"حورفت في كل مطلوب هممت به،","page":"","text":"حورفت في كل مطلوب هممت به، … حتى زهدت، فما خليت والزهدا\nفالحمد لله! صابي ما يزايلني، … ولست أصدق إن سميته شهدا\nوما أظن جنان الخلد يدركها … إلا معاشر، كانوا في التقى جهدا\nيمضي النهار، فما أنفك في شغل، … ولا أطيق، إذا جن الدجى، سهدا\nأما المهاد، فجنبي فيه مضطجع، … والدين عقد جنوب تهجر المهدا"},{"id":"diwan-maarri:325","bookId":"diwan-maarri","type":"poem","seq":325,"chapter":"قصائد","title":"نادى حشا الأم بالطفل الذي اشتملت","page":"","text":"نادى حشا الأم بالطفل الذي اشتملت … عليه: ويحك لا تظهر ومت كمدا!\nفإن خرجت إلى الدنيا لقيت أذى … من الحوادث، بله القيظ والجمدا\nوما تخلص يوما من مكارهها، … وأنت لا بد فيها بالغ أمدا\nورب مثلك وافاها على صغر، … حتى أسن، فلم يحمد ولا حمدا\nلا تأمن الكف من أيامها شللا، … ولا النواظر كفا عن، أو رمدا\nفإن أبيت قبول النصح معتديا، … فاصنع جميلا، وراع الواحد الصمدا\nفسوف تلقى بها الآمال واسعة، … إذا أجزت مدى منها رأيت مدا\nوتركب اللج تبغي أن تفيد غنى، … وتقطع الأرض لا تلفي بها ثمدا\nوإن سعدت، فما تنفك في تعب، … وإن شقيت، فمن للجسم لو همدا؟\nثم المنايا، فإما أن يقال مضى … ذميم فعل، وإما كوكب خمدا\nوالمرء نصل حسام، والحياة له … سل، وأصون للهندي أن غمدا\nفلو تكلم ذاك الطفل قال له: … إليك عني! فما أنشئت معتمدا!\nفكيف أحمل عتبا؟ إن جرى قدر … علي، أدرك ذا جد ومن سمدا"},{"id":"diwan-maarri:326","bookId":"diwan-maarri","type":"poem","seq":326,"chapter":"قصائد","title":"الصبر أروح من حاج تكلفه،","page":"","text":"الصبر أروح من حاج تكلفه، … ترجي له الخيل والمهرية القودا\nوالهم، للحي، إلف لا يفارقه، … حتى يعود، مع الأموات، مفقودا\nتلك النوابح، خالت بدر ليلتها، … قرصا، وظنت ثريا الليل عنقودا"},{"id":"diwan-maarri:327","bookId":"diwan-maarri","type":"poem","seq":327,"chapter":"قصائد","title":"أنحت جهلا، وقد ناحت مطوقة،","page":"","text":"أنحت جهلا، وقد ناحت مطوقة، … من الحمام، على خضراء مقلوده\nقامت على الناعم الأملود، هاتفة، … وما تشاق إلى بيضاء أملوده\nوأم دفر، لعمري، شر والدة، … وبنتها أم ليلى شر مولوده\nفاجلد أخاك عليها، إن ألم بها، … فإنها أخذت، واللب، مجلوده"},{"id":"diwan-maarri:328","bookId":"diwan-maarri","type":"poem","seq":328,"chapter":"قصائد","title":"ترجو يهود المسيح يأتي،","page":"","text":"ترجو يهود المسيح يأتي، … وتأمل، الدهر، أن يهودا\nوكيف ترعى لهم عهود، … من بعد ما ضيعوا العهودا\nوكل ما عندهم دعاو، … حتى يقيموا به الشهودا\nغدوا وأشياخهم، لجهل، … كولدة، أوطنوا المهودا\nوليس بيتي على الروابي، … وإنما آلف الوهودا"},{"id":"diwan-maarri:329","bookId":"diwan-maarri","type":"poem","seq":329,"chapter":"قصائد","title":"قضاء الله يبتعث المنايا،","page":"","text":"قضاء الله يبتعث المنايا، … فيهلكن الأساود والأسودا\nفعيشا مفضلين، أو استميحا، … وسودا معشرا، أو لا تسودا\nفما بهج، الصديق، الدهر، إلا … وكر، فسر ذا الضغن الحسودا\nيسير بيضه والسود، حتى … يبيد، برغمها، بيضا وسودا"},{"id":"diwan-maarri:330","bookId":"diwan-maarri","type":"poem","seq":330,"chapter":"قصائد","title":"أبيد، على التناسب، كل يوم،","page":"","text":"أبيد، على التناسب، كل يوم، … كأني لم أجب بيدا فبيدا\nوأقضائي، من الرؤساء، كوني … وكونهم، لخالقنا، عبيدا\nصلاتي، في الظهائر، لا اصطلائي … بهن، أروم زبدا في زبيدا\nقضاء الله يفجعني وشيكا، … ولو كنت الحطيئة أو لبيدا\nكأن ذوي التنعم، في البرايا، … نعام، راح يلتقط الهبيدا"},{"id":"diwan-maarri:331","bookId":"diwan-maarri","type":"poem","seq":331,"chapter":"قصائد","title":"يا صاع، لست أريد صاع مكيلة،","page":"","text":"يا صاع، لست أريد صاع مكيلة، … فأضيفه، لكن أرخم صاعدا\nلا تدنون من الشرور وأهلها، … فتكون من أهل العلى متباعدا\nفالمرء يقعد، بالمكارم، قائما، … ويقوم، في طلب المعالي، قاعدا\nخير المواهب ما أتاك ميسرا … غير المرازح، بالمطال، مواعدا\nوالغيث أهنأ ما تراه عطية، … ما لم يحث بوارقا ورواعدا\nخمس براحتها تعان، وراحة، … بأشاجع تدعو، لأيد، ساعدا\nعون له عون، إلى أن يبلغ الخ … لاق، جل مظاهرا ومساعدا"},{"id":"diwan-maarri:332","bookId":"diwan-maarri","type":"poem","seq":332,"chapter":"قصائد","title":"يستأسد النبت الغضيض، فلا تلم","page":"","text":"يستأسد النبت الغضيض، فلا تلم … رجلا، متى أبصرته مستأسدا\nوإذا حسدت، فإن شكر فضيلة … أن لا تؤاخذ، في الإساءة، حاسدا\nومن الرزية أن تبيت مكلفا … إصلاح من صحب الغريزة، فاسدا\nوالدين متجر ميت، فلذاك لا … تلفيه، في الأحياء، إلا كاسدا"},{"id":"diwan-maarri:333","bookId":"diwan-maarri","type":"poem","seq":333,"chapter":"قصائد","title":"كأنما العالم ضأن، غدت","page":"","text":"كأنما العالم ضأن، غدت … للرعي، والموت أبو جعده\nفهادج، حامل عكازة، … وفارس، معتقل صعده\nوآخر يدرك من قبله، … ويترك الدنيا لمن بعده\nعيش، كما تعهد، لامخلف … وعيده، بل مخلف وعده\nهل يأمن البرجيس، في عزه، … من قدر يعدمه سعده؟\nكأنما النجم، لخوف الردى، … تأخذه من فرق رعده\nكم لابن، في الأرض، لم يدكر … لبناه، مذ بان، ولا دعده\nأحاذر السيل، ومن لي بمن … جاة، إذا أسمعني رعده؟\nوالوقت لا يفتأ، في مره، … مقربا، من أجل، بعده\nفراقب الخالق، بالغيب، في الن … يامة والقيامة والقعده"},{"id":"diwan-maarri:334","bookId":"diwan-maarri","type":"poem","seq":334,"chapter":"قصائد","title":"لقد غادر العيش هذا السواد،","page":"","text":"لقد غادر العيش هذا السواد، … يعاني، من الدهر، بيضا وسودا\nوتنعكس الحال، حتى ترى … ظباء الأراك يخفن الأسودا\nينفق فكري علي التقى، … ويأبى له الطبع إلا كسودا\nيسود الفتى، كارها، قومه، … ويأمره اللب أن لا يسودا\nفإن خمولك دراع عليك، … وقيت بها عائبا أو حسودا"},{"id":"diwan-maarri:335","bookId":"diwan-maarri","type":"poem","seq":335,"chapter":"قصائد","title":"تروم، بجهلك، لقيا الكرام،","page":"","text":"تروم، بجهلك، لقيا الكرام، … ولست، لذي كرم، واجدا\nوتحسب أن التقي الذي … تشاهده، راكعا ساجدا\nتنبه، فأنت على غرة، … إخالك مستيقظا، هاجدا"},{"id":"diwan-maarri:336","bookId":"diwan-maarri","type":"poem","seq":336,"chapter":"قصائد","title":"حوائج نفسي كالغواني قصائر،","page":"","text":"حوائج نفسي كالغواني قصائر، … وحاجات غيري كالنساء الردائد\nإذا أغضب، الخيل، الشكيم، فما لها … عليه اقتدار، غير أزم الحدائد\nوما يسبح الإنسان في لج غمرة … من العز، إلا بعد خوض الشدائد\nوما كف عقلي أن يؤمل بائدا، … من الأمر، إني بائد وابن بائد\nأحيد، فتشويني السهام، ولو رمت … قسي حمامي لم تجدني بحائد\nلعمرك ما شام الغمائم شائمي، … ولا طلب الروض السحابي رائد\nتذاد، عن الحوض، الغرائب، ضنة، … وحوض الردى، ما دونه كف ذائد\nوكيف أرجي، من زمان، زيادة، … وقد حذف الأصلي حذف الزوائد؟\nأواك ضن، فاهرب من الانس، طالما … تبرم مضنى من حديث العوائد\nوقد يخلف، الظن، المعيد إصابة، … كما أعون الدجال في آل صائد\nوما أعجبتني، لابن آدم، شيمة، … على كل حال من مسود وسائد\nوتسليك، عن نيل الفوائد، ساعة، … ثنت وصف حي، بعدها، كاسم فائد\nوما يبلغ الأحياء عزا بكثرة؛ … وهل لحصى المعزاء قدر الفرائد؟\nله العدد الوافي، ولكن دنت له، … فما أخذته، ناظمات القلائد\nتقسم أطواق المنايا، ولم تزل … تبت سلوكا، من عقود الخرائد\nوخالف ناس في السجايا، ليشهروا، … كما جعل التصريع ختم القصائد"},{"id":"diwan-maarri:337","bookId":"diwan-maarri","type":"poem","seq":337,"chapter":"قصائد","title":"لقد ركزوا الأرماح، غير حميدة،","page":"","text":"لقد ركزوا الأرماح، غير حميدة، … فبعدا، لخيل، في الوغى، لم تطارد\nتداعوا، فقالوا: ناسك وابن ناسك، … وما هو إلا مارد وابن مارد\nوما زال عراف الكواكب ذاكرا … إماما، كنجم، في الدجنة، فارد\nوما يجمع الأشتات إلا مهذب … من القوم، يحمى باردا فوق بارد\nإذا نال ما يرجوه من زحل، الذي … بدا شره، لم يبغه من عطارد\nوإن يك، في الدنيا، سعود، فإنما … تكون قليلا كالشذوذ الشوارد\nأرى كدرا عم الموارد، كلها، … فمت، أو تجرع من خبيث الموارد"},{"id":"diwan-maarri:338","bookId":"diwan-maarri","type":"poem","seq":338,"chapter":"قصائد","title":"أعن واقد، خبرتني، وابن جمرة،","page":"","text":"أعن واقد، خبرتني، وابن جمرة، … وآل شهاب، خامد كل واقد\nوما الناس إلا خائفو الله، وحده، … إذا وقع التمي في كف ناقد\nرقوا، ورقدنا، فاعتلوا في هوينا، … وتلك المراقي غير هذي المراقد\nفراق در، أعطاك، غير مقصر … نظام الثريا، أو فريد الفراقد\nإذا خلجتني، من حياة، منية، … فلست على الباغي العدو بحاقد\nوأفرق من يوم تصم غواته، … فتعول إعوال النساء الفواقد"},{"id":"diwan-maarri:339","bookId":"diwan-maarri","type":"poem","seq":339,"chapter":"قصائد","title":"إذا ما رأيتم عصبة هجرية،","page":"","text":"إذا ما رأيتم عصبة هجرية، … فمن رأيها، للناس، هجر المساجد\nوللدهر سر مرقد كل ساهر، … على غرة، أو موقظ كل هاجد\nيقولون: تأثير القران مغير، … من الدين، آثار السراة الأماجد\nمتى ينزل الأمر السماوي لا يفد، … سوى شبح، رمح الكمي المناجد\nوإن لحق، الإسلام، خطب يغضه، … فما وجدت، مثلا له، نفس واجد\nإذا عظموا كيوان عظمت واحدا، … يكون له كيوان أول ساجد"},{"id":"diwan-maarri:340","bookId":"diwan-maarri","type":"poem","seq":340,"chapter":"قصائد","title":"خطوب تألت: لا يزال، معذبا،","page":"","text":"خطوب تألت: لا يزال، معذبا، … أخوها، وحلت كل كف وساعد\nوما فوق هذي الأرض إلا مؤهل … لهم، فقارب في الظنون وباعد\nإذا جل خطب ساعد، المرء، ضده … ولا خير في الإخوان، إن لم تساعد\nوقد يهجر الحتف القيام إلى الوغى، … ويطرق أبيات النساء القواعد\nفإن رمت جودا، فليجىء منك مطلقا، … وأكرمه عن تقييده بالمواعد\nفأهنأ غيم جاد، في الأرض، نائلا، … غمام سقاها في صموت الرواعد\nوإن المنايا لا يغب نزولها، … فتخفض أرباب الجدود الصواعد\nعنوان القصيدة : إذا كنت من فرط السفاه معطلا، … إذا كنت من فرط السفاه معطلا،\nفيا جاحد اشهد أنني غير جاحد … أخاف، من الله، العقوبة آجلا،\nوأزعم أن الأمر في يد واحد … فإني رأيت الملحدين تعودهم"},{"id":"diwan-maarri:341","bookId":"diwan-maarri","type":"poem","seq":341,"chapter":"قصائد","title":"يكون الذي سمى، من القوم، خالدا","page":"","text":"يكون الذي سمى، من القوم، خالدا … كذوبا، لأن المرء ليس بخالد\nيجالد محروم على الأمر فاته، … وأحرزه، بالحظ، من لم يجالد\nأرى كل مولود يناسب والدا، … وما كل مولود الأنام بوالد\nويجري قضاء، مالكم عنه حاجز، … فألقوا إلى مولاكم بالمقالد"},{"id":"diwan-maarri:342","bookId":"diwan-maarri","type":"poem","seq":342,"chapter":"قصائد","title":"لقد مات جني الصبا منذ برهة،","page":"","text":"لقد مات جني الصبا منذ برهة، … وتأبى عفاري القلب غير مرود\nأمرت، وأمرت أم دفر، وإن حلت، … فكم حلأت قوما غداة ورود\nشربت برودا لم يدع نار غلة، … وعن منكبي ألقيت خير برود\nفإن قتير الشيب لم يحم جانبا، … فكان بعكس من قتير سرود\nأقيمي، فإني لا رقيمي معجبي؛ … ورودي، فإني لا أهش لرود\nأعز بني الدنيا، بغير مذلة، … مبين وجى، منها، فقيد شرود\nبعقاقة أهل العقيق ومنعج؛ … وزرادة، بالحتف، أهل زرود\nفرود السواري والتوائم، في الدجى، … تقر لرب، صاغها، بفرود"},{"id":"diwan-maarri:343","bookId":"diwan-maarri","type":"poem","seq":343,"chapter":"قصائد","title":"إذا المرء لم يغلب، من الغيظ، سورة،","page":"","text":"إذا المرء لم يغلب، من الغيظ، سورة، … فليس، وإن فض الصفا، بشديد\nومن جمع الضرات يطلب لذة، … فقد بات، في الإضرار، غير سديد\nوإن يلتمس أخرى، جديدا لحاجة، … فلا يأمنن منها ابتغاء جديد"},{"id":"diwan-maarri:344","bookId":"diwan-maarri","type":"poem","seq":344,"chapter":"قصائد","title":"كأني، وإن أمست تضم، جميعنا،","page":"","text":"كأني، وإن أمست تضم، جميعنا، … مدائن في غبر المهامه، بيد\nإذا قلت شعرا، لست فيه بحائب، … فما أنا إلا تائب كلبيد\nوبائية من ضعف عقل نفوسنا، … كبائية من شاردات عبيد\nغدوت أعد الحرف سعدا، كأنني … ظليم تغذى، راضيا، بهبيد"},{"id":"diwan-maarri:345","bookId":"diwan-maarri","type":"poem","seq":345,"chapter":"قصائد","title":"خوى دن شرب فاستجابوا إلى التقى،","page":"","text":"خوى دن شرب فاستجابوا إلى التقى، … فعيسهم نحو الطواف خوادي\nتوي دين في ظنه: ما حرائر، … نظائر آم، وكلت بتوادي\nرويدك! لو لم يلحد السيف لم تكن … لتحمل، هام الملحدين، هواد\nتغيرت الأشياء في كل موطن، … ومن لجواد، نائلا، بجواد؟\nفما للسوادي، بالمعاشر، في الدجى، … لقد غفلت عن رحلة بسواد\nوليس ركابي، عن رضاي، عوادنا، … ولكن عداها، أن تسير، عوادي\nأتجمع، في ربع، قيان، كأنها … شوادن، باللحن الخفيف، شوادي\nبواد، نأت عنه العيون، وعنده … بوادن، للأمر القبيح، بوادي\nوما تشبه، الشمس، الروادن مردا، … كخيل، بميدان الفسوق، رواد\nوكل رواد، لا تصاب، أبية … متى نوزعت، في منطق، لرواد\nفهل قاتل منهن غيداء، مرة … فواد، وهل، للمومسات، فوادي؟\nتفرعت الجرد العراب، لعزة، … كوادن، بين المقرفات، كوادي\nتروح إليهن الغواة، عشية، … وهن على ضد الجميل غوادي\nحوى، دين قوم، مالهم، فنفوسهم … إلى الفتكات المخزيات حوادي\nوقامت، على أهل الرشاد، نوادب، … وغصت، بأهل المنديات، نوادي\nأوى، دير نصرانية، متظاهر … بنسك، ألا إن الذئاب أوادي\nسوى ديدن الجهال يذهب عنهم، … وقد طال جهري، فيهم، وسوادي\nوتدري المواضي ما دواء دوائب … يبتن، لرهط المرء، شر دوادي\nوإن دوادا، حين أنكر عقله، … لغير مقيت، عند أم دواد\nأتأمل، ريا بالورود، ركائب … صوادر عن صداء، وهي صواد؟"},{"id":"diwan-maarri:346","bookId":"diwan-maarri","type":"poem","seq":346,"chapter":"قصائد","title":"ما زالت الروح، قبل اليوم، في دعة،","page":"","text":"ما زالت الروح، قبل اليوم، في دعة، … حتى استقرت، بحكم الله، في الجسد\nفالآن تلك وهذا من قذى وأذى، … لا يخليانك بله الغل والحسد\nقال الدني لمال كان ساد به: … لأكرمنك، لولا أنت لم أسد"},{"id":"diwan-maarri:347","bookId":"diwan-maarri","type":"poem","seq":347,"chapter":"قصائد","title":"لا بد للروح أن تنأى عن الجسد،","page":"","text":"لا بد للروح أن تنأى عن الجسد، … فلا تخيم على الأضغان والحسد\nواجعل، لعزمتك، الظلماء ناجية، … نجومها كعلوب النسع والمسد\nفهل تحاذر، من طعن السماك، ردى، … أم بالهلال توقى مخلب الأسد؟\nمن لا يسد ويسئد في حنادسه، … ويسد خيرا، إلى العافين، لا يسد\nحمل المدجج تركا فوق هامته، … أشف للرأس من وضع على الوسد\nوضربة القرن، في الهيجاء، منتصرا، … أولى به من خصام الجيرة الفسد\nومغرم بالمخازي، طالب صلة، … مغرى بتنفيق أشعار له كسد"},{"id":"diwan-maarri:348","bookId":"diwan-maarri","type":"poem","seq":348,"chapter":"قصائد","title":"إن كان قلبك فيه خوف بارئه،","page":"","text":"إن كان قلبك فيه خوف بارئه، … فلا تجاوز حذار الله بالحسد\nهما نقيضان لا يستجمعان به، … والظبي غير مقيم في ذرا الأسد\nوالروح في حب دنياها معذبة، … حتى يقال لها: بيني عن الجسد\nما لا تطيق هلاك حين تحمله، … والدر يهلك دون النظم في المسد"},{"id":"diwan-maarri:349","bookId":"diwan-maarri","type":"poem","seq":349,"chapter":"قصائد","title":"نعم الوساد يميني ما بقيت لها،","page":"","text":"نعم الوساد يميني ما بقيت لها، … وإن أغيب أوسدها فأتسد\nالترب جدي، وساعاتي ركائب لي، … والعيش سيري، وموتي راحة الجسد\nالعين من أرق، والشخص من قلق، … والقلب من أمل، والنفس من حسد\nإنبه وسد، فهما هم تكابده، … واخمل، إذا شئت أن تحظى، ولا تسد\nواجبن أو اشجع، فطرق الموت واحدة، … والظبي فيهن مثل السيد والأسد\nوذات عقد تلاقي من أذى وقذى، … كما تلاقيه ذات الحطب والمسد"},{"id":"diwan-maarri:350","bookId":"diwan-maarri","type":"poem","seq":350,"chapter":"قصائد","title":"قد أهبط الروضة الزهراء، عارية،","page":"","text":"قد أهبط الروضة الزهراء، عارية، … سدى لها الغيث نسجا، فالنبات سد\nتمسي الشقائق فيها، وهي قانية، … مما سقاها رعاف الجدي والأسد\nيغنى بنو الملك، إن حلوا بساحتها، … عن الزرابي والأنماط والوسد\nلا حس للجسم بعد الروح نعلمه، … فهل تحس إذا بانت عن الجسد؟\nوالطبع يهوي إلى ما شان، يطلبه، … لكن يجر إلى ما زان بالمسد\nوفي الغرائز أخلاق مذممة، … فهل نلام على النكراء والحسد؟\nأهكذا كان أهل الأرض قبلكم، … أم غيروا بسجايا منهم فسد؟"},{"id":"diwan-maarri:351","bookId":"diwan-maarri","type":"poem","seq":351,"chapter":"قصائد","title":"ما الخير صوم يذوب الصائمون له،","page":"","text":"ما الخير صوم يذوب الصائمون له، … ولا صلاة، ولا صوف على الجسد\nوإنما هو ترك الشر مطرحا، … ونفضك الصدر من غل ومن حسد\nما دامت الوحش والأنعام خائفة … فرسا، فما صح أمر النسك للأسد"},{"id":"diwan-maarri:352","bookId":"diwan-maarri","type":"poem","seq":352,"chapter":"قصائد","title":"خدر العروس، وإن كانت محببة،","page":"","text":"خدر العروس، وإن كانت محببة، … أدهى وأفتك من عريسة الأسد\nوشركة الخل، فيما هان، تفسده … عليك، فاتق من أخلاقك الفسد\nما عاش جسمان، في الدنيا، بواحدة … من النفوس، ولا النفسان بالجسد\nونية الخير، مثل الطير، آبية … صدر الفتى، فليحاذر صائد الحسد\nكم ساد، في مدة الأيام، من رجل، … ثم انقضى، فهو مثل المرء لم يسد\nعنوان القصيدة : ما يحسن المرء غير الغش والحسد؛ … ما يحسن المرء غير الغش والحسد؛\nوما أخوك سوى الضرغامة الأسد … لا خير في الناس، إن ألقوا سيادتهم\nإليك، طوعا، فخالفهم ولا تسد … فليس يرضون عن وال ولا ملك،\nولو أتوا بالأماني في قوى مسد … جاؤوا الفخار بأموال لهم نفق،\nولم يجيئوا بأخلاق لهم كسد … وإن تكن هذه الأرواح خالصة،\nفهن يفسدن في أرواحنا الفسد … وقد رأينا، كثيرا بيننا، جسدا\nبغير روح، فهل روح بلا جسد؟ … تطهرت، بنبيذ التمر، طائفة،\nوقد أجازوا طهورا بالدم الجسد … فالحمد لله! ما نفسي بسامية،"},{"id":"diwan-maarri:353","bookId":"diwan-maarri","type":"poem","seq":353,"chapter":"قصائد","title":"مللت عيشي، فعوجي يا منية بي،","page":"","text":"مللت عيشي، فعوجي يا منية بي، … وذقت فنيه: من بؤس ومن رغد\nغدي سيوجد أمسي، لا ينازعني … في ذاك خلق، وأمسي لا يصير غدي"},{"id":"diwan-maarri:354","bookId":"diwan-maarri","type":"poem","seq":354,"chapter":"قصائد","title":"نفس قد استودعت جسما إلى أمد،","page":"","text":"نفس قد استودعت جسما إلى أمد، … فإن تفارقه بالمقدار لا يعد\nأوعد وعد، سوف يأتي، بعدنا، زمن … كأننا فيه لم نوعد ولم نعد\nتصعد الفكر، ثم ارتد منحدرا، … فحار بين هبوط الملك والصعد\nلو تسلك الروح، في الأجبال، عالمة … كعلمنا، هدمتها كثرة الرعد"},{"id":"diwan-maarri:355","bookId":"diwan-maarri","type":"poem","seq":355,"chapter":"قصائد","title":"أصمت وإن تأب فانطق شطر ما سمعت","page":"","text":"أصمت وإن تأب فانطق شطر ما سمعت … أذناك، فالفم نصف اثنين في العدد\nواجعله غاية مايأتي اللسان به، … وإن تجاوز لم يقرب من السدد\nالناس أجمع، من دنياهم خلقوا، … فما انتقالك من أد إلى أدد\nبعدا لهم من رجال لاحلوم لهم، … يمشون في الوعث، إعراضا عن الجدد\nوددت أن إلهي كان غادرني، … ومدتي، في يديها، أقصر المدد\nتخاصم الحظ في شيء يجود به، … وراح خصمك منه بين اللدد"},{"id":"diwan-maarri:356","bookId":"diwan-maarri","type":"poem","seq":356,"chapter":"قصائد","title":"إذا غدوت عن الأوطان مرتحلا،","page":"","text":"إذا غدوت عن الأوطان مرتحلا، … فضاه في البين حذف الواو من يعد\nكانت، فبانت، وما حنت إلى وطن، … وعاد غاد إلى وكر، ولم تعد\nسعدت، إن كنت بحرا فائضا بجدا؛ … والبحر ليس بمحسوب من السعد"},{"id":"diwan-maarri:357","bookId":"diwan-maarri","type":"poem","seq":357,"chapter":"قصائد","title":"وعظت قوما، فلم يرعوا إلى عظتي،","page":"","text":"وعظت قوما، فلم يرعوا إلى عظتي، … مثل امرىء القيس ناجى طائر الوادي\nأرى الزمان وشيكا، مبطئا، وله … حال تخالف إيشاكي وإروادي\nكم جاد، قبلي، حضار وبادية … للوارثين بأفراس وأذواد\nإن المنايا أرتنا حجة، شرحت … فضل العطايا لبخال، وأجواد\nوالعفو آمل من ربي، إذا حضرت … نفسي، وفارقت عوادي لأعوادي"},{"id":"diwan-maarri:358","bookId":"diwan-maarri","type":"poem","seq":358,"chapter":"قصائد","title":"جاءت أحاديث، إن صحت، فإن لها","page":"","text":"جاءت أحاديث، إن صحت، فإن لها … شأنا، ولكن فيها ضعف إسناد\nفشاور العقل، واترك غيره هدرا؛ … فالعقل خير مشير ضمه النادي"},{"id":"diwan-maarri:359","bookId":"diwan-maarri","type":"poem","seq":359,"chapter":"قصائد","title":"الله يشهد أني جاهل ورع،","page":"","text":"الله يشهد أني جاهل ورع، … فليحضر الناس إقراري وإشهادي\nهذا، ورب صديق لي أفاد غنى، … زهدت فيه، على عدمي وإزهادي\nأعمى البصيرة، لا يهديه ناظره، … إذ كل أعمى لديه، من عصا، هاد\nوقد علمت، إذا سهدت من حذر، … أن ليس ينفي خطوب الدهر تسهاد"},{"id":"diwan-maarri:360","bookId":"diwan-maarri","type":"poem","seq":360,"chapter":"قصائد","title":"يا آل يعقوب! ما توراتكم نبأ","page":"","text":"يا آل يعقوب! ما توراتكم نبأ … من وري زند، ولكن وري أكباد\nإن كان لم يبد للأغمار سركم، … فإنه لي، في أكنانه، باد\nلقد أكلتم بأمر، كله كذب، … على تقادم أزمان وآباد\nورابني أن أحبارا، لكم، رسخوا … في العلم، ليسوا، على حال، بعباد"},{"id":"diwan-maarri:361","bookId":"diwan-maarri","type":"poem","seq":361,"chapter":"قصائد","title":"دنياي! فيك هوى نفسي ومهلكها،","page":"","text":"دنياي! فيك هوى نفسي ومهلكها، … والماء يودي بنفس الوارد الصادي\nوما قصدتك مختارا فتعذلني … فيك العواذل، إن حاولت إقصادي\nوالمرء يطلب أمرا، ما يبينه، … كالحرف يلفظ بين الزاي والصاد\nموتان: هذا بورس عل ميته، … وآخر زاد على ورس بفرصاد"},{"id":"diwan-maarri:362","bookId":"diwan-maarri","type":"poem","seq":362,"chapter":"قصائد","title":"سميت نجلك مسعودا، وصادفه","page":"","text":"سميت نجلك مسعودا، وصادفه … ريب الزمان، فأمسى غير مسعود\nعودي يخاف من الإحراق، صاحبه، … إن قال ربي لأجسام البلى: عودي\nحاشا لربك من إخلاف موعده، … وإنما الخلف في قولي وموعودي"},{"id":"diwan-maarri:363","bookId":"diwan-maarri","type":"poem","seq":363,"chapter":"قصائد","title":"محمودنا الله، والمسعود خائفه،","page":"","text":"محمودنا الله، والمسعود خائفه، … فعد عن ذكر محمود ومسعود\nملكان لو أنني خيرت ملكهما، … وعود صلب، أشار العقل بالعود\nالقبر لا ريب منزول، فما أربي … إلى ارتقاء رفيع السمك، مصعود\nقوتي غناي، وطمري ساتري، وتقى … مولاي كنزي، وورد الموت موعودي\nوالنفس أمارة بالسوء ما اجترمت، … إلا وسيىء طبعي قائل: عودي"},{"id":"diwan-maarri:364","bookId":"diwan-maarri","type":"poem","seq":364,"chapter":"قصائد","title":"لا يعجبن الفتى بفضل،","page":"","text":"لا يعجبن الفتى بفضل، … فإنه مقتضى بوعد\nيقول: جاوزت، في المعالي، … آل سعيد وآل سعد\nفليس فوقي، وليس مثلي، … وليس قبلي، وليس بعدي\nوالده خصه بعدوى … من موته، والحمام يعدي\nأودى بفرسان كل جيل، … من سبط، فيهم، وجعد\nوما ثنى الحادثات معدى … من مثل بسطام وابن معدي\nيا زينبا، حليت، ودعدا، … كم مر من زينب ودعد\nفالحمد لله قل خيري، … وصار قربي نظير بعدي\nوقد بدا لي، من المنايا … بارقة آذنت برعد"},{"id":"diwan-maarri:365","bookId":"diwan-maarri","type":"poem","seq":365,"chapter":"قصائد","title":"إذا دنوت لشام، أو مررت به،","page":"","text":"إذا دنوت لشام، أو مررت به، … فنكبيه وراء الظهر، أو حيدي\nقد غير الدهر منه، بعد مبتهج، … وألحد السيف فيه، بعد توحيد"},{"id":"diwan-maarri:366","bookId":"diwan-maarri","type":"poem","seq":366,"chapter":"قصائد","title":"تعالى الله! كم ملك مهيب،","page":"","text":"تعالى الله! كم ملك مهيب، … تبدل، بعد قصر، ضيق لحد\nأقر بأن لي ربا قديرا، … ولا ألقى بدائعه بجحد\nلو اني في عداد الرمل صحبي، … لأودعت الثرى، وتركت وحدي"},{"id":"diwan-maarri:367","bookId":"diwan-maarri","type":"poem","seq":367,"chapter":"قصائد","title":"بوحدانية العلام دنا،","page":"","text":"بوحدانية العلام دنا، … فذرني أقطع الأيام وحدي\nسألت، عن الحقائق، كل يوم، … فما ألفيت إلا حرف جحد\nسوى أني أزول بغير شك، … ففي أي البلاد يكون لحدي؟"},{"id":"diwan-maarri:368","bookId":"diwan-maarri","type":"poem","seq":368,"chapter":"قصائد","title":"أما عرف المقيم بأرض مصر،","page":"","text":"أما عرف المقيم بأرض مصر، … وميض بوارق، ودوي رعد؟\nورب غمامة نشأت، فزالت، … وليس ثرى محلتنا بجعد\nإذا رزق الفتى في المحل جدا، … رعى ما شاء من ثعد ومعد\nوما نالت خلافتها قريش، … وأرغم سعدها إلا بسعد\nفإن، لهذه الدنيا، طريقا، … عليه يمر من قبلي وبعدي\nإذا وعدتك خيرا ماطلته؛ … وهل يرجى لها إنجاز وعد؟\nفزج العيش من صفو ورنق؛ … ودع شجنيك من هند ودعد\nولا تجلس إلى أهل الدنايا، … فإن خلائق السفهاء تعدي"},{"id":"diwan-maarri:369","bookId":"diwan-maarri","type":"poem","seq":369,"chapter":"قصائد","title":"أمامة! كيف لي بإمام صدق،","page":"","text":"أمامة! كيف لي بإمام صدق، … ودائي مشرقي، فمتى معادي؟\nفخافي شرتي، ودعي رجائي، … فإني، مثل عاد الناس، عاد\nكنود جاءنا منها كنود، … وأعيا القوم سعد من سعاد\nأما لكم، بني الدنيا، عقول … تصد عن التنافس والتعادي؟\nأسنتنا المآل إلى صعيد، … فما بال الأسنة والصعاد؟\nومن يك حظه، منكم، دنوا، … فإن أجل حظي في البعاد\nوقد جربتكم، فوجدت جهلا … مبينا في السباط وفي الجعاد\nأذاة من صديق، أو عدو، … فبؤس للأصادق والأعادي\nوتغدر هذه الأيام مني، … كما أغدرن من إرم وعاد"},{"id":"diwan-maarri:370","bookId":"diwan-maarri","type":"poem","seq":370,"chapter":"قصائد","title":"أكمها ليس بينهم بصير!","page":"","text":"أكمها ليس بينهم بصير! … أما لكم، إلى العلياء، هادي؟\nعمرنا، الدهر، شبانا وشيبا، … فبؤس للرقاد وللسهاد!\nوأوطنا الديار، بكل وقت، … فألفينا الروابي كالوهاد\nيمهد للغني فراش نوم؛ … وقبر كان أروح من مهاد\nإذا اقترنت بجسم الحي روح، … فتلك وذاك في حالي جهاد"},{"id":"diwan-maarri:371","bookId":"diwan-maarri","type":"poem","seq":371,"chapter":"قصائد","title":"عجبت لشارب بزجاج راح،","page":"","text":"عجبت لشارب بزجاج راح، … دوين العقل، سدا من حديد\nولم يحتج إلى عون بقطر، … ولم يك صاحب الأيد الشديد\nرأى شمس المدام تغور فيه، … وتطلع في ذرى قدح جديد\nمقيما، غير ذي سفر، تكفا … بندمانيه من جم العديد\nكذي القرنين، لكن ضل هذا، … ويسر ذاك للرأي السديد"},{"id":"diwan-maarri:372","bookId":"diwan-maarri","type":"poem","seq":372,"chapter":"قصائد","title":"كأني كنت في أزمان عاد،","page":"","text":"كأني كنت في أزمان عاد، … أعاشر آل قيل، أو مريد\nوما عفت الحوادث عن شجاع، … فتعفو عن عتيبة أو دريد\nأريد الآن مغفرة، فإني … أراقب حتف مغفرة بريد\nوإن صوارد الأيام تأتي … على عقبانها، وعلى الصريد"},{"id":"diwan-maarri:373","bookId":"diwan-maarri","type":"poem","seq":373,"chapter":"قصائد","title":"إركع لربك في نهارك واسجد،","page":"","text":"إركع لربك في نهارك واسجد، … ومتى أطقت تهجدا فتهجد\nوإذ غلا البر النقي، فشارك ال … فرس الكريم وساو طرفك تمجد\nواجعل لنفسك من سليط ضيائها … أدما، ونزر حلاوة من عنجد\nوارسم بفخار شرابك، لا ترد … قدح اللجين ولا إناء العسجد\nيكفيك صيفك من ثيابك ساتر، … وإذا شتوت فقطعة من برجد\nأنهاك أن تلي الحكومة، أو ترى … حلف الخطابة، أو إمام المسجد\nوذر الإمارة، واتخاذك درة … في المصر، يحسبها حسام المنجد\nتلك الأمور كرهتها لأقارب … وأصادق، فابخل بنفسك أو جد\nولقد وجدت ولاء قوم سبة، … فاصرف ولاءك للقديم الموجد\nولتحل عرسك بالتقى، فنظامه … أسنى لها من لؤلؤ وزبرجد\nكل يسبح، فافهم التقديس في … صوت الغراب، وفي صياح الجدجد\nوانزل بعرضك في أعز محلة، … فالغور ليس بموطن للمنجد"},{"id":"diwan-maarri:374","bookId":"diwan-maarri","type":"poem","seq":374,"chapter":"قصائد","title":"أكتم حديثك عن أخيك، ولا تكن","page":"","text":"أكتم حديثك عن أخيك، ولا تكن … أسرار قلبك مثل أسرار اليد\nولكل عصر حائد، ومقدم … للحرب، يضرب في جبين الأصيد\nفمضى يزيد ومخلد في دولة، … وثنى الزمان إلى يزيد ومزيد\nوتقارب الأسماء، ليس بموجب … كون التقارب، في الفعال، الأزيد\nفالغمر نافى الغمر، عند قياسه، … والسيد غير مشابه للسيد\nوتدير الأوطان حب، وطالما … قنص الحمام على الغصون الميد\nظلم الأنام، فناص بيدك مفردا، … حتى تعد من الرجال البيد\nومتى رزقت شجاعة وبلاغة، … أوطنت، من ربع العلى، بمشيد\nفالطير سؤددها الرفيع، وعزها، … قسما على خطبائها والصيد\nوإذا الحمام أتى، فما يكفيكه … نفر الجبان، ولا حياد الحيد\nومقيد، عند القضاء، كمطلق، … فيما ينوب، ومطلق كمقيد\nفالظبية الغيداء، صبحها الردى، … أدماء ترتع في النبات الأغيد\nقدر يريك حليف ضعف أيدا، … ويرد قرن الأيد ضد مؤيد"},{"id":"diwan-maarri:375","bookId":"diwan-maarri","type":"poem","seq":375,"chapter":"قصائد","title":"أما المجاور، فارعه وتوقه،","page":"","text":"أما المجاور، فارعه وتوقه، … واستعف ربك من جوار الملحد\nليس الذي جحد المليك، وقد بدت … آياته، بأخ لمن لم يجحد\nوأرى التوحد، في حياتك، نعمة، … فإن استطعت بلوغه، فتوحد"},{"id":"diwan-maarri:376","bookId":"diwan-maarri","type":"poem","seq":376,"chapter":"قصائد","title":"لا تبدءوني بالعداوة منكم،","page":"","text":"لا تبدءوني بالعداوة منكم، … فمسيحكم، عندي، نظير محمد\nأيعيث ضوء الصبح ناظر مدلج، … أم نحن أجمع في ظلام سرمد\nكمه البصائر، لا يبين لها الهدى، … أو مبصر، أبدا، بعيني أرمد\nجسد يعذب، في الحياة، حسبته … مستشعرا حسد العظام الهمد\nإن السيوف تراح في أغمادها، … وتظل في تعب، إذا لم تغمد\nمن لي بجسم لا يحس رزية، … لكن يعد كتربة، أو جلمد\nروح إذا اتصلت بشخص لم يزل … هو وهي، في مرض العناء المكمد\nإن كنت من ريح، فيا ريح اسكني، … أو كنت من لهب، فيا لهب اخمد"},{"id":"diwan-maarri:377","bookId":"diwan-maarri","type":"poem","seq":377,"chapter":"قصائد","title":"كفي دموعك، للتفرق، واطلبي","page":"","text":"كفي دموعك، للتفرق، واطلبي … دمعا يبارك مثل دمع الزاهد\nفبقطرة منه تبوخ جهنم، … فيما يقال، حديث غير مشاهد\nخافي إلهك، واحذري من أمة، … لم يلبسوا، في الدين، ثوب مجاهد\nأكلوا فأفنوا ثم غنوا وانتشوا … في رقصهم، وتمتعوا بالشاهد\nحالت عهود الخلق، كم من مسلم، … أمسى يروم شفاعة بمعاهد\nوهو الزمان قضى، بغير تناصف، … بين الأنام، وضاع جهد الجاهد\nسهد الفتى لمطالب ما نالها، … وأصابها من بات ليس بساهد"},{"id":"diwan-maarri:378","bookId":"diwan-maarri","type":"poem","seq":378,"chapter":"قصائد","title":"الله صورني، ولست بعالم،","page":"","text":"الله صورني، ولست بعالم، … لم ذاك، سبحان القدير الواحد\nفلتشهد الساعات، والأنفاس لي، … أني برئت من الغوي الجاحد"},{"id":"diwan-maarri:379","bookId":"diwan-maarri","type":"poem","seq":379,"chapter":"قصائد","title":"لا شام للسلطان، إلا أن يرى","page":"","text":"لا شام للسلطان، إلا أن يرى … نعم البداوة كالنعام الطارد\nويكون، للبادين، عذب مياهه، … مثل المدامة لا تحل لوارد\nوتظل أبيات، لهم، شعرية، … كبيوت شعر، في البلاد، شوارد\nويقوم ملك في الأنام، كأنه … ملك يبرح بالخبيث المارد\nصنع اليدين بقتل كل مخالف … بالسيف، يضرب بالحديد البارد\nقالوا: سيملكنا إمام عادل، … يرمي أعادينا بسهم صارد\nوالأرض موطن شرة وضغائن، … ما أسمحت بسرور يوم فارد\nولو أن فيها ناظرا، كالمشتري، … يعطي السعود، وكاتبا كعطارد"},{"id":"diwan-maarri:380","bookId":"diwan-maarri","type":"poem","seq":380,"chapter":"قصائد","title":"جهل مرامي أن تكون موافقي،","page":"","text":"جهل مرامي أن تكون موافقي، … وشكوك نفسي، بينهن، تعادي\nليس التكثر من خليقة صادق، … فاذهب لعادك أستمر لعادي\nلو كان لي غيم لجاد بمائه، … من غير إبراق، ولا إرعاد\nأخلف، إذا أوعدت غافر زلة … من جارم، وأنل بلا ميعاد\nولقد غدوت بأمة وبإمة … قزميتين، وهمة من عاد\nوالجسم يهوي، بالطباع، إلى الثرى … ويبين فيه تكلف الإصعاد\nوإخال نفسي، حين تفقد شخصها، … تلقى الذي عملته قبل معاد\nلا تشربن ما عشت من دم أبيض … سبط، ولا سود، يلحن، جعاد\nدعة، لمثلك، ترك دعد للنوى، … وسعادة لك هجرة لسعاد\nلم تبلغ الآراب شدة ساعد، … ما لم يعنها الله بالإسعاد"},{"id":"diwan-maarri:381","bookId":"diwan-maarri","type":"poem","seq":381,"chapter":"قصائد","title":"أروى دم قلبا، وتلك سفاهة؛","page":"","text":"أروى دم قلبا، وتلك سفاهة؛ … والدهر من عجل ومن إرواد\nفروائح، وبواكر، ومعارف، … ومناكر، وحواضر، وبواد\nوجواد قوم، عد من بخلائهم، … وحليف بخل، عد في الأجواد\nوالخلق أطوار، يزيل شخوصهم، … بعد المثول، مثبت الأطواد\nشيم، من الدنيا، يجاز بها المدى، … ستشاكل الأذواء بالأذواد\nواد من الموت الزؤام، وكلنا … أشفى ليدفع فوق جرف الوادي\nسفر يطول، من الأنام، على كرى … من غفلة، وكرى من الأزواد\nوأوادم الزمن الطويل كثيرة، … وأوادم الطعم الشهي أواد\nوأمض من ثقل العيادة، للفتى، … نوب تكون عوادي العواد\nلا يفجعنك، والخطوب كثيرة، … أن الغوادر، للفراق، غواد\nعمدت لنا الأيام، وهي دوائب، … لترد أقداما مكان هواد\nفطوارق جاءتهم بطوارد، … ونوادب قامت لهم بنواد\nهم بأسودة القلوب، مناخه … للبيض، حين أنخن بالأفواد"},{"id":"diwan-maarri:382","bookId":"diwan-maarri","type":"poem","seq":382,"chapter":"قصائد","title":"اذكر إلهك، إن هببت من الكرى،","page":"","text":"اذكر إلهك، إن هببت من الكرى، … وإذا هممت لهجعة ورقاد\nإحذر مجيئك، في الحساب، بزائف، … فالله ربك أنقد النقاد\nتغشى جهنم دمعة من تائب، … فتبوخ، وهي شديدة الإيقاد"},{"id":"diwan-maarri:383","bookId":"diwan-maarri","type":"poem","seq":383,"chapter":"قصائد","title":"قلدتني الفتيا، فتوجني غدا","page":"","text":"قلدتني الفتيا، فتوجني غدا … تاجا، بإعفائي من التقليد\nومن الرزية أن يكون فؤا … دك الوقاد في جسد، عليه، بليد\nوحوادث الأيام تولد جلة، … وتعود تصغر ضد كل وليد"},{"id":"diwan-maarri:384","bookId":"diwan-maarri","type":"poem","seq":384,"chapter":"قصائد","title":"إن شئت كل الخير يجمع في","page":"","text":"إن شئت كل الخير يجمع في … الأولى، فبت كالصارم الفرد\nماذا يروق العين من أشر، … عقباه صائرة إلى درد\nوتصاغ، للبيض، الأساور من … لبس الأساور سابغ الزرد\nوأمن، على المال، الرجال، ولا … تأمنهم أبدا على الخرد"},{"id":"diwan-maarri:385","bookId":"diwan-maarri","type":"poem","seq":385,"chapter":"قصائد","title":"وجدنا اختلافا، بيننا، في إلهنا،","page":"","text":"وجدنا اختلافا، بيننا، في إلهنا، … وفي غيره، عز الذي جل واتحد\nلنا جمعة، والسبت يدعى لأمة … أطافت بموسى، والنصارى لها الأحد\nفهل، لبواقي السبعة الزهر، معشر، … يجلونها ممن تنسك أو جحد؟\nتقرب ناس بالمدام، وعندنا، … على كل حال، أن شاربها يحد\nوما كفهم عن شربها سوط ضارب، … ولا السيف، إن السيف من سوطه أحد"},{"id":"diwan-maarri:386","bookId":"diwan-maarri","type":"poem","seq":386,"chapter":"قصائد","title":"لا تكرموا جسدي، إذا ما حل بي","page":"","text":"لا تكرموا جسدي، إذا ما حل بي … ريب المنون، فلا فضيلة للجسد\nكالبرد كان على اللوابس نافقا، … حتى إذا فنيت بشاشته كسد\nأرواحنا ظلمت، فتلك بيوتها … درس، خوين من الضغائن والحسد\nواروه من قبل الفساد، فإنه … جسم، إذا فقدت حرارته فسد\nلا تغبطوا رجلا على ما ناله، … إن بات قد ساد الرجال، ولم يسد\nفحوادث الأيام غير توارك … نسر النجوم، ولا السماك، ولا الأسد"},{"id":"diwan-maarri:387","bookId":"diwan-maarri","type":"poem","seq":387,"chapter":"قصائد","title":"ما جلب الخير إلى","page":"","text":"ما جلب الخير إلى … صاحب عقل، وكسد\nأشد خطب، يتقى، … فراق روح لجسد\nيذكر أن سوف يعم … أهل شر وحسد\nطوفان نار كائن، … يخرج من قلب الأسد\nأصيغة العالم ذا، … أم طال دهر، ففسد؟\nأهون، من سؤالهم، … حطبك في ريح وسد\nإن لم يجئك، بغنى، … يوم، فقد سد مسد"},{"id":"diwan-maarri:388","bookId":"diwan-maarri","type":"poem","seq":388,"chapter":"قصائد","title":"يلقاك، بالماء النمير، الفتى،","page":"","text":"يلقاك، بالماء النمير، الفتى، … وفي ضمير النفس نار تقد\nيعطيك لفظا، لينا مسه، … ومثل حد السيف ما يعتقد\nويمرح الإنسان، من جهله، … وهو أسير في رباط وقد\nكم حلت الأيام من حيلة، … ثمت حلت كل عقد عقد\nوالمرء كالبائع في سوقه، … يأخذ ما يعطى ولا ينتقد\nحتى إذا اليوم انقضى ساءه … ما تجد النفس، وما يفتقد\nلا أحقد، الآن، على صاحب، … إن رابني، معدن خير حقد\nفهذه الدنيا على ما ترى، … لم تد مقتولا ولم تستقد"},{"id":"diwan-maarri:389","bookId":"diwan-maarri","type":"poem","seq":389,"chapter":"قصائد","title":"إذا اجتمع اثنان، في منزل،","page":"","text":"إذا اجتمع اثنان، في منزل، … على خربة، فضحا للأبد\nتبد الحظوظ على أهلها، … ولكن تباد، ومن لم يبد\nوفي وحدة المرء ستر له، … فكن مثل سيفك حلف الربد\nولا تعرضن لبنت الكروم، … أخت السرور، وأم الزبد\nفإن وسعت، للفتى، ساعة، … فسوف تغادره في كبد\nوما زلت، بعد غراب الصبا، … قرين البزاة، فقع يا لبد"},{"id":"diwan-maarri:390","bookId":"diwan-maarri","type":"poem","seq":390,"chapter":"قصائد","title":"يسمون بالجهل عبد الرحيم،","page":"","text":"يسمون بالجهل عبد الرحيم، … وعبد العزيز، وعبد الصمد\nوما بلغوا أن يكونوا له … عبيدا، وذلك أقصى الأمد\nولكنه خالق العالمين: … ذائب أجزائهم، والجمد\nتعمده يغنك، بالهدي، أن … تدرس مغنيهم، والعمد\nإذا كان ما نالني، بالقضاء، … فمن سوء رأيي طول الكمد\nولم يبق، في الأمر، من حيلة، … فيقصر من عمر، أو يمد\nوإن ثمودا أتت، بحرهم، … خطوب، فما تركت من ثمد\nرأيت الفتى شب حتى انتهى، … وما زال يفنى إلى أن همد\nكمصباح ليل بدا يستنير، … ثم تناقص حتى خمد\nولولا الذي بان من حكمه، … لقلنا: طويل زمان سمد\nإذا طفئت في الثرى أعين، … فقد أمنت من عمى أو رمد"},{"id":"diwan-maarri:391","bookId":"diwan-maarri","type":"poem","seq":391,"chapter":"قصائد","title":"تغيبت في منزلي برهة،","page":"","text":"تغيبت في منزلي برهة، … ستير العيوب فقيد الحسد\nفلما مضى العمر، إلا الأقل، … وحم لروحي فراق الجسد\nبعثت شفيعا إلى صالح، … وذاك من القوم رأي فسد\nفيسمع مني سجع الحمام، … وأسمع منه زئير الأسد\nفلا يعجبني هذا النفاق، … فكم نفقت محنة ما كسد"},{"id":"diwan-maarri:392","bookId":"diwan-maarri","type":"poem","seq":392,"chapter":"قصائد","title":"ما يعرف، اليوم، من عاد وشيعتها،","page":"","text":"ما يعرف، اليوم، من عاد وشيعتها، … وآل جرهم، لا بطن ولا فخذ\nأطارهم، شيمة العنقاء، دهرهم، … فليس يعلم خلق أية أخذوا"},{"id":"diwan-maarri:393","bookId":"diwan-maarri","type":"poem","seq":393,"chapter":"قصائد","title":"الناس أكثر مما أنت ملتمس،","page":"","text":"الناس أكثر مما أنت ملتمس، … إن لم يوازرك هذا المستعان، فذا\nوما يريبك من سهم رميت به، … وقد أصابك مرات فما نفذا"},{"id":"diwan-maarri:394","bookId":"diwan-maarri","type":"poem","seq":394,"chapter":"قصائد","title":"ليت البسيطة لا تلقى بظاهرها","page":"","text":"ليت البسيطة لا تلقى بظاهرها … شعبا، يعد، ولا بطنا، ولا فخذا\nأعارك الله ما أعطاك موهبة، … لو كان ما نلت موهوبا لما أخذا"},{"id":"diwan-maarri:395","bookId":"diwan-maarri","type":"poem","seq":395,"chapter":"قصائد","title":"يا لهف نفسي على أني رجعت إلى","page":"","text":"يا لهف نفسي على أني رجعت إلى … هذي البلاد، ولم أهلك ببغداذا\nإذا رأيت أمورا لا توافقني، … قلت: الإياب إلى الأوطان أدى ذا"},{"id":"diwan-maarri:396","bookId":"diwan-maarri","type":"poem","seq":396,"chapter":"قصائد","title":"تلفع بالعباء رجال صدق،","page":"","text":"تلفع بالعباء رجال صدق، … وأوسع غيرهم سرقا ولاذا\nفلا تعجب لأحكام الليالي، … فإن صروفها بنيت على ذا"},{"id":"diwan-maarri:397","bookId":"diwan-maarri","type":"poem","seq":397,"chapter":"قصائد","title":"يا واعظي بالصمت! ما لك لا","page":"","text":"يا واعظي بالصمت! ما لك لا … تلقي إلي حديثك اللذا؟\nإن الجديدين، اللذين هما … سبقان، بذاني وما بذا\nكالنابلين غدت سهامهما … ليست مريشة، ولا قذا\nوكأن، للساعات، أجنحة، … فإخالهن بها قطا حذا\nقدر ينادي الحتف، من كثب؛ … دع ذا إلى الميقات، أو خذ ذا\nأملي بياض الصبح أنبته، … وعهدته، بالأمس، منجذا\nخل السرور لمن يعز به، … واعبد إلهك واحدا فذا"},{"id":"diwan-maarri:398","bookId":"diwan-maarri","type":"poem","seq":398,"chapter":"قصائد","title":"نبذتم الأديان من خلفكم،","page":"","text":"نبذتم الأديان من خلفكم، … وليس في الحكمة أن تنبذا\nلا قاضي المصر أطعتم، ولا … الحبر، ولا القس، ولا الموبذا\nإن عرضت ملتكم، بينهم، … قال جميع القوم: لا حبذا"},{"id":"diwan-maarri:399","bookId":"diwan-maarri","type":"poem","seq":399,"chapter":"قصائد","title":"تفادى نفوس العالمين من الردى،","page":"","text":"تفادى نفوس العالمين من الردى، … ولا بد، للنفس المشيحة، من أخذ\nترى المرء جبار الحياة، وإن دنت … منيته ألفيته، وهو مستخذي"},{"id":"diwan-maarri:400","bookId":"diwan-maarri","type":"poem","seq":400,"chapter":"قصائد","title":"من يبغ، عندي، نحوا، أو يرد لغة،","page":"","text":"من يبغ، عندي، نحوا، أو يرد لغة، … فما يساعف من هذا ولا هذي\nيكفيك شرا، من الدنيا، ومنقصة، … أن لا يبين لك الهادي من الهاذي"},{"id":"diwan-maarri:401","bookId":"diwan-maarri","type":"poem","seq":401,"chapter":"قصائد","title":"شئمت يا همة، عادت شآمية،","page":"","text":"شئمت يا همة، عادت شآمية، … من بعد ما أوطنت، عصرا، ببغداذ\nولست ذات نخيل، لا ولا أنف … كرمية، فتقولي شفني داذي"},{"id":"diwan-maarri:402","bookId":"diwan-maarri","type":"poem","seq":402,"chapter":"قصائد","title":"لو انك، مثل ما ظنوا، كريم،","page":"","text":"لو انك، مثل ما ظنوا، كريم، … لما فتنتك بنت الكرم هذي\nولا أصبحت فاقد كل عقل، … تباذي، في المجالس، أو تهاذي"},{"id":"diwan-maarri:403","bookId":"diwan-maarri","type":"poem","seq":403,"chapter":"قصائد","title":"من يوق لا يكلم، وإن عمدت له","page":"","text":"من يوق لا يكلم، وإن عمدت له … نبل، تغادر شخصه كالقنفذ\nبلغته مرهفة النصال، وأثبتت … فيما عليه، وكلها لم تنفذ"},{"id":"diwan-maarri:404","bookId":"diwan-maarri","type":"poem","seq":404,"chapter":"قصائد","title":"صوارمهم علقت بالكشوح،","page":"","text":"صوارمهم علقت بالكشوح، … مكان تمائمهم والعوذ\nوما يمنع، الخائفين الحمام، … لبس دروعهم والخوذ"},{"id":"diwan-maarri:405","bookId":"diwan-maarri","type":"poem","seq":405,"chapter":"قصائد","title":"جرى المين فيهم، كابرا بعد كابر،","page":"","text":"جرى المين فيهم، كابرا بعد كابر، … عن الخبر يحكي، لا عن السلف، الحبر\nخبرت بني الدنيا، وأصبحت راغبا … إليهم، كأني ما شفاني بهم خبر\nجبلة ظلم، لا قوام بحربها، … وصيغة سوء، ما لمكسورها جبر\nتلاوتكم ليست لرشد، ولا هدى … بعشرين، ما فيها ادغام ولا نبر\nوما العيش إلا عبر أسفار ظاعن، … لمقلته، مما يمارسه، العبر\nتغبرتها بالسير، حتى تركتها … طليح ركاب، ما لأخلافها غبر\nوقد مات، من بعد التغشمر، جهلها، … فغيب، إلا أن هامتها القبر\nحديث أتانا عن يمان ومشئم، … وأولى البرايا، بالذي فري، الكبر\nخف الله، حتى في جنى النحل ذقته، … فما جمعت إلا لأنفسها الدبر\nإذا أنت زوجت العجوز، على الصبا … فأيامها صن، عليك، وصنبر\nوتحطيم أرماح الوغى إبر صغا، … بها القول: كم طعن يهيجه أبر\nوصبرك فضل فيك، إن كنت قادرا، … وإلا فعجز، من خلائقك، الصبر\nلقاؤك ما فيه، لمثلي، خيرة، … ولا لك، فانظر أين يلتمس الشبر"},{"id":"diwan-maarri:406","bookId":"diwan-maarri","type":"poem","seq":406,"chapter":"قصائد","title":"إذا كان لم يقتر عليك، عطاءه،","page":"","text":"إذا كان لم يقتر عليك، عطاءه، … إلهك، فليهجر أناملك القتر\nونحن بنو الدهر، الذي هو خاتر، … فليس بناء، من خلائقنا، الختر\nأمور شجت، إن لم تتم، فإنها … أراقم تزجي، الحتف، أذنابها البتر\nولم يحم، ظبيا نافرا، كون مسكه … عتيرة مسك، أن يلم به العتر\nوحبك هذي الدار أس إمامة … لجهلك، والبادي، على باطن، ستر\nعجبت لركب الموج يرجون كوكبا، … وجيش المنايا، من نفوسهم، فتر\nمدامة سن وافقتها مدامة، … إذا هي دبت، فالعظام بها فتر\nتغولان لب المرء من كل وجهة، … فكلتاهما يغشاك أن يغلب الهتر"},{"id":"diwan-maarri:407","bookId":"diwan-maarri","type":"poem","seq":407,"chapter":"قصائد","title":"قيان غدت، خمسا وعشرا، على عصا","page":"","text":"قيان غدت، خمسا وعشرا، على عصا … لخمس وعشر، لا يحس لها جذر\nتحلت بشذر بعد أطواق حندس … قديم، ومن صوغ الندى ذلك الشذر\nلقد أكثرت، في يومها، أم ناهض … من السجع، حتى مل منطقها الهذر\nوقد جوانحنا، البهر عذرت في نوحها وغنائها، … فلما أطالت فيهما بطل العذر"},{"id":"diwan-maarri:408","bookId":"diwan-maarri","type":"poem","seq":408,"chapter":"قصائد","title":"تقنع من الدنيا بلمح، فإنها،","page":"","text":"تقنع من الدنيا بلمح، فإنها، … لدى كل زوج، حائض ما لها طهر\nمتى ما تطلق تعط مهرا، وإن تزد … فنفسك، بعد الدين والراحة، المهر\nولم تر بطن الأرض، يلقي، لظهرها، … رجالا، كما يلقى، إلى بطنها، الظهر\nبنو الشرخ زادوا، عن بني الشيخ، قوة، … ويضعف، عن ضعف بقارحه المهر\nإذا ما جرينا، والذين تقدموا … مضوا، وترامى، في جوانحنا البهر\nتمتع أبكار الزمان بأيده … وجئنا بوهن، بعدما خرف الدهر\nفليت الفتى كالبدر جدد عمره، … يعود هلالا كلما فني الشهر"},{"id":"diwan-maarri:409","bookId":"diwan-maarri","type":"poem","seq":409,"chapter":"قصائد","title":"غفرت زمانا في انتكاس مآثم،","page":"","text":"غفرت زمانا في انتكاس مآثم، … وعند مليك الناس يلتمس الغفر\nوفي وحدة الإنسان أصناف لذة؛ … وكل صنوف الوحش يجمعها القفر\nلعل ذنوبا كن للدين سلما؛ … ونارك، دون الماء، يقدحها الحفر\nتطل بمسك، أو تضمخ بعنبر، … أرى أم دفر، ما عدانا ابنها دفر\nوما القبر إلا منزل، نفرت له … كذوب المنى، ثم اطمأن بها النفر"},{"id":"diwan-maarri:410","bookId":"diwan-maarri","type":"poem","seq":410,"chapter":"قصائد","title":"بيوت، فمهدوم يرى ومقوض،","page":"","text":"بيوت، فمهدوم يرى ومقوض، … بكسر، وبيت من قريض له كسر\nحوادث فيها رائحات ومغتد؛ … وأمران: عسر، في البرية، أو يسر\nوإن رجالا، كان نسر، لديهم، … إلها، عليهم، قبلنا، طلع النسر\nوعاشوا يرون اليسر إفضال مكثر … على مقتر، ثم انقضى الناس واليسر\nلهم سنة أن لا يضيع معدم، … إذا سنة أزرى، بأنجمها، الأسر\nوما ربح الدنيا بممكن تاجر … على حالة، بل كل أعمالها خسر\nحياة كجسر بين موتين: أول … وثان، وفقد الشخص أن يعبر الجسر"},{"id":"diwan-maarri:411","bookId":"diwan-maarri","type":"poem","seq":411,"chapter":"قصائد","title":"دعي، وذري، الأقدار تمضي لشأنها،","page":"","text":"دعي، وذري، الأقدار تمضي لشأنها، … فلم تحم ملكا لا دمشق ولا مصر\nولا الحرة السوداء حاطت سيادة؛ … ولا البصرة البيضاء حصنها البصر\nتروم قياسا للحوادث، ضلة، … وتلك أصول، ليس يجمعها حصر\nوعند ضياء الفجر صليت الضحى، … وعند غروب الشمس صليت العصر\nوما يجمل التقصير في كل موطن، … ولا كل مفروض الصلاة له قصر\nإذا لم يكن بد من الموت، فالقه، … أفض به الفودان أم فري الخصر\nعلي مضى، من بعد نصر وعزة؛ … وحمزة أودى قبل أن ينزل النصر\nوإني أرى ذرية الشيخ آدم، … قديما، عليهم، بالردى، أخذ الإصر"},{"id":"diwan-maarri:412","bookId":"diwan-maarri","type":"poem","seq":412,"chapter":"قصائد","title":"إذا زادك المال افتقارا وحاجة","page":"","text":"إذا زادك المال افتقارا وحاجة … إلى جامعيه، فالثراء هو الفقر\nألم تر أن الملك ليس بدائم … على ملكه، إلا وعسكره وقر؟\nتتبع، آثار الرياض، حمامة، … ويعجبها، فيما تزاوله، النقر\nتهم بنهض، ثم تثني برغبة، … فما شعرت، حتى أتيح لها صقر\nوقد عرفتها أمها، أمس، شره، … وأن الردى يقرو المكان الذي تقرو\nومن حان، يوما، جار في عينه عمى، … وفي لبه ضعف، وفي سمعه وقر"},{"id":"diwan-maarri:413","bookId":"diwan-maarri","type":"poem","seq":413,"chapter":"قصائد","title":"تلقب ملك قاهرا، من سفاهة؛","page":"","text":"تلقب ملك قاهرا، من سفاهة؛ … ولله مولاه الممالك والقهر\nأتغضب أن تدعى لئيما مذمما؛ … وحسبك، لؤما، أن والدك الدهر\nتزوج، دنياه، الغبي بجهله، … فقد نشزت من بعد ما قبض المهر\nتطهر ببعد من أذاها وكيدها، … فتلك بغي، لا يصح لها طهر\nوأنفقت، بالأنفاس، عمري، مجزءا، … بها اليوم ثم الشهر، يتبعه الشهر\nيسيرا يسيرا مثل ما أخذ المدى، … على الناس، ماش، في جوانحه بهر\nكذر على ظهر الكثيب، فلم يزل … به السير، حتى صار من خلفه الظهر"},{"id":"diwan-maarri:414","bookId":"diwan-maarri","type":"poem","seq":414,"chapter":"قصائد","title":"إذا كنت قد جاوزت خمسين حجة،","page":"","text":"إذا كنت قد جاوزت خمسين حجة، … ولم ألق خيرا، فالمنية لي ستر\nوما أتوقى، والخطوب كثيرة، … من الدهر، إلا أن يحل بي الهتر\nأحاديث عن قيل بن عتر ورهطه، … رويدك ما قيل ووالده عتر؟\nغدت أمنا الدنيا إلينا مسيئة، … لها، عندنا، من كل ناحية وتر\nونحن كركب الموج، ما بين بعضهم … وبين الردى، إلا الذراع أو الفتر"},{"id":"diwan-maarri:415","bookId":"diwan-maarri","type":"poem","seq":415,"chapter":"قصائد","title":"أجل سلاح، يتقي المرء قرنه","page":"","text":"أجل سلاح، يتقي المرء قرنه … به، أجل، يوم الهياج، مؤخر\nورب كمي يحمل السيف، صارما، … إلى الحرب، والأقدار تلهو وتسخر\nوكنزك في الغبراء، لا بد، ضائع، … ولكن لدى الخضراء يحمى ويذخر\nتفاخر، ظنا منك أنك ماجد، … وحسبك، من ذام، غدوك تفخر\nوما شرف الإنسان إلا عطية … حدتها الليالي، والقضاء المسخر"},{"id":"diwan-maarri:416","bookId":"diwan-maarri","type":"poem","seq":416,"chapter":"قصائد","title":"إذا صغر، اسما، حاسدوك، فلا ترع","page":"","text":"إذا صغر، اسما، حاسدوك، فلا ترع … لذلك، والدنيا، بسعدك، تفغر\nفإن الثريا واللجين، وحسبنا … بها، وسهيلا، كلهن مصغر"},{"id":"diwan-maarri:417","bookId":"diwan-maarri","type":"poem","seq":417,"chapter":"قصائد","title":"لعمري، لقد عز المباح عليكم،","page":"","text":"لعمري، لقد عز المباح عليكم، … وهان، بجهل، ما يصان ويحظر\nوفي الحق أشباه من الذهب، الذي … نشاهده، ثقل ومكث ومنظر"},{"id":"diwan-maarri:418","bookId":"diwan-maarri","type":"poem","seq":418,"chapter":"قصائد","title":"حوتنا شرور، لا صلاح لمثلها،","page":"","text":"حوتنا شرور، لا صلاح لمثلها، … فإن شذ منا صالح، فهو نادر\nوما فسدت أخلاقنا باختيارنا، … ولكن بأمر سببته المقادر\nوفي الأصل غش، والفروع توابع؛ … وكيف وفاء النجل والأب غادر!\nإذا اعتلت الأفعال، جاءت عليلة، … كحالاتها، أسماؤها والمصادر\nفقل للغراب الجون، إن كان سامعا: … أأنت، على تغيير لونك، قادر؟\nسماحك مجهول، ونحلك واضح، … ومجدك ضاوي، وجسمك حادر\nبني العصر! إن كانت طوالا شخوصكم، … فإنكم في المكرمات حيادر\nومن قبل، نادى الوكر أين ابن أجدل … أواني، وقال الغاب أين الخوادر؟\nوفي كل أرض، للمنية، غائل، … عليه يمين أنه لا يغادر\nفواد به ظبي، وليس لنفسه … فواد، وتردى، في ذراها، الفوادر"},{"id":"diwan-maarri:419","bookId":"diwan-maarri","type":"poem","seq":419,"chapter":"قصائد","title":"دع القوم! سلوا بالضغائن، بينهم،","page":"","text":"دع القوم! سلوا بالضغائن، بينهم، … خناجر، واشرب ما سقتك الخناجر\nطعام غني الإنس والفاقد الغنى … سواء، إذا ما غيبته الحناجر\nبهجت بفرع لا ثبات لأصله، … ففيم تلاحي، أو علام تشاجر؟\nإذا أنت هاجرت القبائح والخنى، … فأنت، على قرب الديار، مهاجر\nتعرض، للطير السوانح، زاجر؛ … أما لك من عقل يكفك زاجر؟\nولكنها الدنيا أرت من يحبها … محاجر تسقى، دونهن، المحاجر\nمتى ما فعلت الخير ثم كفرته، … فلا تأسفن! إن المهيمن آجر\nولو لم يبر الحر إلا مخافة … من الخزي، بين الناس، إن قيل فاجر\nفنزه جميلا، جئته، عن جزاية … تؤمل، أو ربح، كأنك تاجر\nوبالجد زار، اللات، أهل ضلالة، … وعظمت العزى، وأكرم باجر\nشتونا وصفنا وارتبعنا، فلم يدم … شتاء، وزال القيظ عنا، وناجر"},{"id":"diwan-maarri:420","bookId":"diwan-maarri","type":"poem","seq":420,"chapter":"قصائد","title":"أرى كل أم، عبرها غير مبطىء،","page":"","text":"أرى كل أم، عبرها غير مبطىء، … وما أم دفر بالتي بان عبرها\nهي النفس تهوى الرحب، في كل منزل، … فكيف بها إن ضاق، في الأرض، قبرها\nوآخر عهد القوم بي يوم تنطوي … علي جرور الورد، يكره زبرها\nفهل يرتجي، خضر الملابس، ظاعن، … وقد مزقت، في باطن الترب، غبرها؟\nأتتني أنباء، كثير شجونها، … لها طرق أعيى، على الناس، خبرها\nهفا دونها قس النصارى، وموبذ ال … مجوس، وديان اليهود، وحبرها\nوخطوا أحاديثا لهم في صحائف، … لقد ضاعت الأوراق، فيها، وحبرها\nتخالفت الأشياع في عقب الردى، … وتلك بحار، ليس يدرك عبرها\nوقيل: نفوس الناس تستطيع فعلها؛ … وقال رجال: بل تبين جبرها\nولو خلقت أجسادنا من صبارة، … لقل، على كر الحوادث، صبرها\nيجيئك شهرا ناجر، بعد قرها، … وصنبرها، بعد المقيظ، ووبرها\nوما أحرزت، نفس المدجج، في الوغى … مضبرة، يستأسر، الوحش، ضبرها\nأو النثرة الحصداء، قورب نسجها، … لها حلق هال، الأسنة، عبرها\nإذا أودعتها جثة، وتعرضت … لبيض الظبا، لم يمكن السيف هبرها\nوأودت بنو وبر وببر، فما حمى … عزيز، ولا شم توقل وبرها\nوقد سمي المرء الهزبر، تفاؤلا، … وليس بباق، في الليالي، هزبرها\nنوائب ألقت، في النفوس، جرائحا، … عصى، كل آس، في البرية، سبرها\nلي القوت، فليعمر، سرنديب، حظها … من الدر، أو يكثر، بغانة، تبرها"},{"id":"diwan-maarri:421","bookId":"diwan-maarri","type":"poem","seq":421,"chapter":"قصائد","title":"عجبت لورقاء الجناحين، شأنها،","page":"","text":"عجبت لورقاء الجناحين، شأنها، … إذا غني الأقوام بالمال، فقرها\nغدت أمس في قرية صفرية، … بقرية يوعي بها، الزاد، نقرها\nفما أخذت إلا ثلاثا ونحوها … من الحب، حتى جاء، بالحتف، صقرها\nوما رجعت يوما إلى عقر دارها، … وكان، بكفي ذلك السهم، عقرها\nأرى أدهم الظلماء يعقب شقرة، … فتودي بها دهم الجياد، وشقرها\nفعظم أخا النسك التقي، لدينه، … ونفسك فاحقر، نافع لك حقرها\nولا تقرإ الكتب المضلل درسها، … وقد وضحت طرق الهداية، فاقرها\nفيا مهجة كالعود، أمست مناخة، … إذا شكت الأثقال، ضوعف وقرها\nمتى سمعت أذني مقالة ناصح، … أتيح لها، عن قاتل النصح، وقرها"},{"id":"diwan-maarri:422","bookId":"diwan-maarri","type":"poem","seq":422,"chapter":"قصائد","title":"أرى أمنا، والحمد لله ربنا،","page":"","text":"أرى أمنا، والحمد لله ربنا، … يهب علينا، بالحوادث، مورها\nفما زيد منها، قبضة الكف، زبدها، … ولا عمرت فيها، لخير، عمورها\nولم تدر، يوما، ضأنها ومعيزها … بما احتلفت آسادها ونمورها\nتشتت فيها رأينا، وتوفقت، … على ريبة، أمواهها وخمورها\nتوامر، فيما لا يحل، نفوسنا … بتيهاء، لا تخفى علينا أمورها"},{"id":"diwan-maarri:423","bookId":"diwan-maarri","type":"poem","seq":423,"chapter":"قصائد","title":"تسمى سرورا، جاهل متخرص،","page":"","text":"تسمى سرورا، جاهل متخرص، … بفيه البرى! هل، في الزمان، سرور؟\nنعم! ثم جزء من ألوف كثيرة … من الخير، والأجزاء، بعد، شرور\nيسار وعدم وادكار وغفلة، … وعز وذل، كل ذاك غرور\nحوانا مكان، لا يجوز انتقاله، … ودهر له بالساكنيه مرور\nفكر على الأبطال، أو كر في الوغى، … لهذي الليالي حملة وكرور\nنأت، عن ذرور العين، مقلة شارق، … لها كلما لاح الصباح درور"},{"id":"diwan-maarri:424","bookId":"diwan-maarri","type":"poem","seq":424,"chapter":"قصائد","title":"عقولكم، في كل حال، بكية،","page":"","text":"عقولكم، في كل حال، بكية، … ولكن دموع الباكيات غزار\nيعود فنيد الملك، إن عاد جده … معد، إليكم، أو أبوه نزار\nوما صح للمرء المحصل أنه … بكوفان قبر، للإمام، يزار\nأخو الدين من عادى القبيح، وأصبحت … له حجرة، من عفة، وإزار"},{"id":"diwan-maarri:425","bookId":"diwan-maarri","type":"poem","seq":425,"chapter":"قصائد","title":"أسيت، إذ غابت الأحجال والغرر؛","page":"","text":"أسيت، إذ غابت الأحجال والغرر؛ … وإنما الناس، في أيامهم، عرر\nوعذت بالله من عام، أخي سنة، … نجومه، في دخان ثائر، شرر\nكأنما بره در لعزته، … وكيف تؤكل، عند المعدم، الدرر\nوطرة الروض يدمي الرجل موطئها، … ينسيك ما جنت الأصداغ والطرر\nأدرر يمينك بالجدوى، إذا قدرت؛ … إن المنايا، لعمري، منهج درر\nوقاب أسماعنا جاءت بمنفعة، … وماأتتنا بشيء، يحمد، السرر\nسراء دهرك لم تكمل لدى أحد؛ … فليت طفلك لم تقطع له سرر\nأسرك، الآن، أن تلقى على قلق، … مثل الأسر، حماه، نومه، السرر\nلم نهجر الماء إلا بعد تجربة، … لقد شربنا، فلم تذهب بها الحرر\nسرارة الوهد، يلقى الجنب مضجعها، … خير من التبر، منسوجا به السرر\nما قرة العين، ذات الورد، معوزة، … وغيبت، عن بواكي الأعين، القرر\nفينا التحاسد معروف، فهل حسدت … مجترة الإبل أخرى، ما لها جرر؟\nما شرة من خليل النفس واحدة، … لا بل توافيك، من تلقائه، شرر\nنهاك ناهيك عن بيع على غرر، … وأنت كلك، فيما بان لي، غرر\nأم عقيل، فما عن ظلمها عقل؛ … تلك الصريرات، فيهم، ضاعت الصرر\nمر الليالي، إذا استولى على مرس، … تقضبت منه بالمستمسك المرر\nوالشر، في الإنس، مبثوث، وغيرهم، … والنفع، مذ كان، ممزوج به الضرر\nتشاكلوا في سجيات مذممة، … وأشبهت لبوات الغابة الهرر\nتناقض في بني الدنيا، كدهرهم، … يمضي المقيظ، وتأتي، بعده، القرر\nلله در شباب، سار ظاعنه، … لو رده، من دموع الآسف، الدرر"},{"id":"diwan-maarri:426","bookId":"diwan-maarri","type":"poem","seq":426,"chapter":"قصائد","title":"زهوي على المرء، فوقي، متلف، وعلى","page":"","text":"زهوي على المرء، فوقي، متلف، وعلى … مثلي، غبا، وعلى من دونه، أشر\nحسب البرية من قربى، تضمهم … أشياء توجد، منها ألف البشر\nوالناس، كالنار، كانوا في نشاءتهم … يستضوأ السقط منها ثم ينتشر\nوالأرض تنبت من نخل ومن عشر، … وما يخلد لا نخل ولا عشر\nلو يعقلون لهنوا أهل ميتهم، … ولم تقم، لوليد فيهم، البشر"},{"id":"diwan-maarri:427","bookId":"diwan-maarri","type":"poem","seq":427,"chapter":"قصائد","title":"الدهر كالربع، لم يعلم بحالته،","page":"","text":"الدهر كالربع، لم يعلم بحالته، … هل عند ذي الدار، من سكانها، خبر؟\nوسوف يقدم، حتى يستسر به … سنا النهار، ويفني، شرخه، الكبر"},{"id":"diwan-maarri:428","bookId":"diwan-maarri","type":"poem","seq":428,"chapter":"قصائد","title":"نخشى السعير، ودنيانا، وإن عشقت،","page":"","text":"نخشى السعير، ودنيانا، وإن عشقت، … مثل الوطيس تلظى، ملؤه سعر\nما زلت أغسل وجهي للطهور به، … مسيا وصبحا، وقلبي حشوه ذعر\nكأنما رمت إنقاء لحالكه، … حتى اتقاني، بصافي لونه، الشعر"},{"id":"diwan-maarri:429","bookId":"diwan-maarri","type":"poem","seq":429,"chapter":"قصائد","title":"حاجي نظيم جمان، والحياة معي","page":"","text":"حاجي نظيم جمان، والحياة معي … سلك قصير، فيأبى جمعها القصر\nأما المراد فجم، لا يحيط به … شرح، ولكن عمر المرء مختصر\nوالدهر يخطب أهل اللب، مذ عقلوا … ما خاف عيا، ولا أزرى به الحصر\nوالغي في كل شيء، ليس يعدمه … باغيه، حتى من الأعناب تعتصر\nوالشر في عالم، شاهدته، خلق، … ما صدهم عن أذاه الحر والخصر\nفالصم، من عنصر الإفساد، حاسدة، … لصحة السمع، خلدا، ما له بصر"},{"id":"diwan-maarri:430","bookId":"diwan-maarri","type":"poem","seq":430,"chapter":"قصائد","title":"أرمى، وجدك، من رامي بني ثعل،","page":"","text":"أرمى، وجدك، من رامي بني ثعل، … حتف، لديه إزاء الحوض، والعقر\nيغشاهم الكره، في الدنيا، فآدبهم … منه، كآدب قيس، ليس ينتقر\nإن عوضوا بذنوب، أسلفت، سقرا، … فلم ترمهم، على علاتها، سقر\nأغناهم الله من مال، وأفقرهم … من الرشاد، فما استغنوا، بل افتقروا\nويحقرون أخا الإعدام، بينهم، … وإن أفضل منهم للذي احتقروا\nكأنما العمر سلك مده قدر، … فيه الفواقر، لا در ولا فقر\nولاجت النار، كالشقراء، يحبسها، … عن مهرها، القيد، وهنا، فهي لا تقر\nبدت بليل، كعين الديك، عن شحط، … أو عرفه، بمحل، دونه أقر\nيعاقر الراح شرب، حولها، سهد، … تروي، التراب نجيعا، سوق ما عقروا"},{"id":"diwan-maarri:431","bookId":"diwan-maarri","type":"poem","seq":431,"chapter":"قصائد","title":"من ادعى الخير من قوم، فهم كذب،","page":"","text":"من ادعى الخير من قوم، فهم كذب، … لا خير، في هذه الدنيا، ولا خير\nوسيرة الدهر ما تنفك معجبة، … كالبحر، تغرق في ضحضاحها السير\nنمتار، من أمنا الغبراء، حاجتنا … وللبسيطة من أجسادنا مير\nكم غيرتنا بأمر خط حادثه، … وربنا الله لم تلمم به الغير"},{"id":"diwan-maarri:432","bookId":"diwan-maarri","type":"poem","seq":432,"chapter":"قصائد","title":"منازل المجد، من سكانها، دثر،","page":"","text":"منازل المجد، من سكانها، دثر، … قد عثرتهم، صروف، بالفتى، عثر\nهب الديانة لا ترعى، فما لهم … حق المروءة لم يرعوا، وإن كثروا؟\nلا يحلبون، لضيف طارق، غمرا، … إلا وثم نفوس، للقرى، خثر\nأنحن أفضل أم أشياء جامدة، … أضحت، سواء لديها، العين والأثر؟\nما هز، سيفك، تيه بل مقلده، … لما أنار له التأثير والأثر"},{"id":"diwan-maarri:433","bookId":"diwan-maarri","type":"poem","seq":433,"chapter":"قصائد","title":"تورعوا، يا بني حواء، عن كذب،","page":"","text":"تورعوا، يا بني حواء، عن كذب، … فما لكم، عند رب صاغكم، خطر\nلم تجدبوا لقبيح من فعالكم، … ولم يجئكم، لحسن التوبة، المطر"},{"id":"diwan-maarri:434","bookId":"diwan-maarri","type":"poem","seq":434,"chapter":"قصائد","title":"تشكت، الضيعة، الشقراء، جاهدة،","page":"","text":"تشكت، الضيعة، الشقراء، جاهدة، … فقيل: صبرا إلى أن ينبت الشقر\nولا مقر على اللذات، أولها … شهد، يغر، ولكن غبه مقر\nآلى الزمان، يقينا، أن سيجمعنا، … إلى التراب، ورسل الموت تنتقر\nيغنى الفتى، بالمنايا، عن مآربه، … وينفخ الروح في طفل، فيفتقر\nعرفت أمرا، فلا تزعجك حادثة، … ما كان مثلك، في أمثالها، يقر\nعندي لخلي إعظام، لمنته، … وإنني، للذي أوليه، محتقر"},{"id":"diwan-maarri:435","bookId":"diwan-maarri","type":"poem","seq":435,"chapter":"قصائد","title":"قد شاب رأسي، ومن نبت الثرى جسدي،","page":"","text":"قد شاب رأسي، ومن نبت الثرى جسدي، … فالنبت آخر ما يعتو به الزهر\nإذا ركبت، لإدراك العلا، سفنا، … فالبحر يحمل ما لا يحمل النهر"},{"id":"diwan-maarri:436","bookId":"diwan-maarri","type":"poem","seq":436,"chapter":"قصائد","title":"سم الهلال، إذا عاينته، قمرا،","page":"","text":"سم الهلال، إذا عاينته، قمرا، … إن الأهلة، عن وشك، لأقمار\nولا تقولن: حجين، إنه لقب، … وإنما يلفظ، التلقيب، أغمار\nهل صح قول من الحاكي، فنقبله، … أم كل ذاك أباطيل وأسمار؟\nأما العقول، فآلت أنه كذب، … والعقل غرس، له، بالصدق، أثمار\nما هاج، للحازم الماضي، سوى حزن، … عود يجاوبه، في الشرب، مزمار\nهل تعرف الماء، تغشاه القطا زمرا … قبل الصباح، وفيه الجن سمار\nكأن كيوان، في ظلماء حندسه، … من الهمود وطول المكث، مسمار\nمن يرزق الحظ يسعد أين كان به، … ومن يخيب، فإن الموت مضمار\nكانت عجائب، والمقدار صيرها … إلى ابن حرب، ولاقى، الحتف، عمار\nما فات أعيا، ولم ترجع، إلى مضر، … عين، وجول، في الآفاق، أنمار\nينهى لسانك عن شيء، منافقة، … والسر بالشيء، ينهى عنه أمار"},{"id":"diwan-maarri:437","bookId":"diwan-maarri","type":"poem","seq":437,"chapter":"قصائد","title":"لا ملك للملك المقصور نعلمه،","page":"","text":"لا ملك للملك المقصور نعلمه، … وكل ملك، على الرحمن، مقصور\nمضت قرون، وتمضي بعدنا أمم، … والسر خاف، إلى أن ينفخ الصور\nلم يحص أعداد رمل الأرض ساكنها؛ … وكل ذلك، عند الله، محصور"},{"id":"diwan-maarri:438","bookId":"diwan-maarri","type":"poem","seq":438,"chapter":"قصائد","title":"أمور سكان هذي الأرض كلهم،","page":"","text":"أمور سكان هذي الأرض كلهم، … كلفظهم، فيه منظوم ومنثور\nيلقي، المهند مأثورا، أخو كرم، … ولا يشيع قبيح عنه، مأثور"},{"id":"diwan-maarri:439","bookId":"diwan-maarri","type":"poem","seq":439,"chapter":"قصائد","title":"جيب الزمان على الآفات مزرور","page":"","text":"جيب الزمان على الآفات مزرور … ما فيه إلا شقي الجد مضرور\nأرى شواهد جبر، لا أحققه، … كأن كلا، إلى ما ساء، مجرور\nهون عليك، فما الدنيا بدائمة، … وإنما أنت مثل الناس مغرور\nولو تصور أهل الدهر صورته، … لم يمس منهم لبيب، وهو مسرور\nلقد حججت، فأعطتك السرى عنتا، … فهل علمت بأن الحج مبرور؟\nوالخير والشر ممزوجان، ما افترقا، … فكل شهد عليه الصاب مذرور\nوعالم فيه أضداد، مقابلة، … غنى وفقر، ومكروب ومقرور"},{"id":"diwan-maarri:440","bookId":"diwan-maarri","type":"poem","seq":440,"chapter":"قصائد","title":"تخيل من بني الدنيا، غدا عجبا،","page":"","text":"تخيل من بني الدنيا، غدا عجبا، … للمفكرين، وكل الناس محسور\nكأن إعراب أغراب ثووا، رمنا، … بالدو، فينا، بحكم النحو، مأسور\nفناطق، يسكن الأمصار من عجم، … نطق ابن بيداء، لما يحوه سور\nوناظم لعروض الشعر، عن عرض، … وما يحس بأن البيت مكسور\nومغتد بحبال الصيد ينصبها، … كيما يفيء له من ذاك ميسور"},{"id":"diwan-maarri:441","bookId":"diwan-maarri","type":"poem","seq":441,"chapter":"قصائد","title":"لا يبصر القوم، في مغناك، غسل يد","page":"","text":"لا يبصر القوم، في مغناك، غسل يد … على الطعام، إلى أن يرفع السور\nولا يكن ذاك إلا بعد كفهم … أكفهم، ويسير الفعل ميسور\nفإن تقريب خدام الفتى حرضا، … والضيف يأكل، رأي منه مخسور"},{"id":"diwan-maarri:442","bookId":"diwan-maarri","type":"poem","seq":442,"chapter":"قصائد","title":"الصمت أولى، وما رجل ممنعة،","page":"","text":"الصمت أولى، وما رجل ممنعة، … إلا لها بصروف الدهر تعثير\nوالنقل غير أنباء سمعت بها؛ … وآفة القول تقليل وتكثير\nوالعقل زين، ولكن فوقه قدر، … فما له، في ابتغاء الرزق، تأثير"},{"id":"diwan-maarri:443","bookId":"diwan-maarri","type":"poem","seq":443,"chapter":"قصائد","title":"ما باختياري ميلادي، ولا هرمي،","page":"","text":"ما باختياري ميلادي، ولا هرمي، … ولا حياتي، فهل لي بعد تخيير؟\nولا إقامة إلا عن يدي قدر، … ولا مسير إذا لم يقض تسيير\nزعمت أنك تهديني لواضحة، … كذبت، هذا الذي تحكيه تحيير\nعيرت أمرا، فهل غيرت منكره، … أم ليس عندك للنكراء تغيير؟"},{"id":"diwan-maarri:444","bookId":"diwan-maarri","type":"poem","seq":444,"chapter":"قصائد","title":"غير وأنكر، على ذي الفحش، منطقه،","page":"","text":"غير وأنكر، على ذي الفحش، منطقه، … إذا أجاز خنا زير خنازير\nأما الجسوم، فإنس في مناظرها، … لها، من النحض، تشبيك وتأزير\nكأنها، ورجال ينهضون بها، … من الفخامة هونات بهازير\nيعزر الملك، توقيرا، وحق له، … على المآثم، تأديب وتعزير"},{"id":"diwan-maarri:445","bookId":"diwan-maarri","type":"poem","seq":445,"chapter":"قصائد","title":"لهفي على ليلة ويوم،","page":"","text":"لهفي على ليلة ويوم، … تألفت منهما الشهور\nوألفيا عنصري زمان، … ليس، لأسراره، ظهور\nقد أصبح الدين مضمحلا، … وغيرت آيه الدهور\nفلا زكاة، ولا صيام، … ولا صلاة، ولا طهور\nواعتاض، حل النكاح، قوم … بنسوة، ما لها مهور"},{"id":"diwan-maarri:446","bookId":"diwan-maarri","type":"poem","seq":446,"chapter":"قصائد","title":"كأنما الأرض شاع فيها،","page":"","text":"كأنما الأرض شاع فيها، … من طيب أزهارها، بخور\nأثنت على ربها السواري، … والنبت والماء والصخور\nونحن فوق التراب ثقل، … يكاد من تحتنا يخور\nلا تفتخر! إن كل فخر … لله، واستعجم الفخور\nألا ترى أن أم دفر، … كأنها آلها السخور؟"},{"id":"diwan-maarri:447","bookId":"diwan-maarri","type":"poem","seq":447,"chapter":"قصائد","title":"كم سبحت أربع جوار،","page":"","text":"كم سبحت أربع جوار، … لها بتسبيحها حبور\nفمن جنوب ومن شمال، … ومن صبا، أختها الدبور\nوالشهب، جمعا، وشعرياها، … تلك الغميصاء والعبور\nفمجدوا ربكم إلى أن … تلفظ، أمواتها، القبور\nفكل ما تفعل البرايا، … إلا تقى ربها، يبور\nوالصبر، حزم، على الرزايا، … وقبلنا فضل الصبور\nوهل أمنتم على ثبير، … أن يتداعى به الثبور؟\nفكل ذي مشية سيرمى … بعثرة، ما لها جبور\nطال وقوفي، وراء جسر، … وإنما ينظر العبور\nإن ابن آسى مضى، ولكن … دل، على فضله، الزبور"},{"id":"diwan-maarri:448","bookId":"diwan-maarri","type":"poem","seq":448,"chapter":"قصائد","title":"إذا سنة بكى تشرين فيها،","page":"","text":"إذا سنة بكى تشرين فيها، … وساعده بدمعته أذار\nفرودي حيث شئت، بغير أزل، … وليس عليك من جدب حذار\nفذاك أوان تخضر الروابي، … لناظرها، وتبيض الوذار\nأيلقى العذر أم أبت الخطايا، … قديما، أن يكون لك اعتذار؟"},{"id":"diwan-maarri:449","bookId":"diwan-maarri","type":"poem","seq":449,"chapter":"قصائد","title":"ثلاث مآرب: عنس، وكور،","page":"","text":"ثلاث مآرب: عنس، وكور، … ونهج قد أبان، فهل بكور؟\nوبعض الناس، في الدنيا، كطير … أوانف أن تلائمها الوكور\nذكور لا إناث لها، ولكن … قرائنها المهندة الذكور\nعرفتكم بني حواء، قدما، … فكلكم أخو ضغن مكور\nوما فيكم، على الإحسان، جاز، … ولا منكم، على النعمى، شكور"},{"id":"diwan-maarri:450","bookId":"diwan-maarri","type":"poem","seq":450,"chapter":"قصائد","title":"أمور تستخف بها حلوم،","page":"","text":"أمور تستخف بها حلوم، … وما يدري الفتى لمن الثبور\nكتاب محمد، وكتاب موسى، … وإنجيل ابن مريم، والزبور\nنهت أمما، فما قبلت، وبارت … نصيحتها، فكل القوم بور\nودارا ساكن وحياة قوم، … كجسر، فوقه اتصل العبور\nيعطل منزل، ويزار قبر، … وما تبقى الديار ولا القبور\nحمام فاتك، فهل انتصار، … وكسر دائم، فمتى الجبور؟\nوملك كالرياح جرت قبول، … فلم تلبث، وأعقبت الدبور\nأصول قد بنين على فساد، … وتقوى الله سوق لا تبور\nليطلع المليك عليك فيها، … وأنت، على نوائبها، صبور"},{"id":"diwan-maarri:451","bookId":"diwan-maarri","type":"poem","seq":451,"chapter":"قصائد","title":"للحال بالقدر اللطيف تغير،","page":"","text":"للحال بالقدر اللطيف تغير، … فلينأ عنك تفاؤل وتطير\nقد حار آدم، في القضاء، وآله، … أفللملائك، في السماء، تحير؟\nتتخيرين الأمر كي تحظي به؛ … هيهات ليس، على الزمان، تخير\nوتديري عند السماك أو السها، … فلكل جسم، في التراب، تدير"},{"id":"diwan-maarri:452","bookId":"diwan-maarri","type":"poem","seq":452,"chapter":"قصائد","title":"أنا، بالليالي والحوادث، أخبر،","page":"","text":"أنا، بالليالي والحوادث، أخبر، … سفر يجد بنا، وجسر يعبر\nواجهت قبرة، فخفت تطيرا؛ … ما كل ميت، لا أبا لك، يقبر\nمن أحسن الأحداث وضعك غابرا … في الترب، يأكله تراب أغير\nما أجهل الأمم، الذين عرفتهم، … ولعل سالفهم أضل وأتبر\nيدعون في جمعاتهم، بسفاهة، … لأميرهم، فيكاد يبكي المنبر\nجئنا على كره، ونرحل رغما، … ولعلنا ما بين ذلك نجبر\nما قيل في عظم المليك وعزه، … فالله أعظم، في القياس، وأكبر\nوكأنما رؤياك رؤيا نائم، … بالعكس، في عقبى الزمان، تعبر\nفإذا بكيت بها فتلك مسرة، … وإذا ضحكت، فذاك عين تعبر\nسر الفتى، من جهله، بزمانه، … وهو الأسير، ليوم قتل يصبر\nلعبت به أيامه، فكأنه … حرف يلين، في الكلام، وينبر\nعجز الأطبة عن جروح نوائب، … ليست، بغير قضاء ربك، تسبر\nوالمين أغلب في المعاشر، كم أخ … للدفر، وهو، إذا يسمى، العنبر\nشرف اللئيم، وكم شريف رأسه … هدر يقط، كما يقط المزبر\nسل أم غيلان الصموت عن ابنها، … وبنات أوبر، ما أبوها أوبر\nوالشر يجلبه العلاء، وكم شكا، … نبأ، علي، ما شكاه قنبر"},{"id":"diwan-maarri:453","bookId":"diwan-maarri","type":"poem","seq":453,"chapter":"قصائد","title":"إجعل تقاك الهاء، تعرف همسها،","page":"","text":"إجعل تقاك الهاء، تعرف همسها، … والراء، كررها، الزمان، مكرر\nقالوا: جهنم! قلت: إن شرارها … ولهيبها، يصلاهما المتشرر\nلا تخبرن، بكنه دينك، معشرا … شطرا، وإن تفعل، فأنت مغرر\nواصمت، فإن الصمت يكفي أهله، … والنطق يظهر كامنا، ويقرر"},{"id":"diwan-maarri:454","bookId":"diwan-maarri","type":"poem","seq":454,"chapter":"قصائد","title":"أصبحت غير مميز من عالم","page":"","text":"أصبحت غير مميز من عالم … مثل البهائم، كلهم متحير\nيتخيرون، على المليك، قضاءه؛ … سفه الغواة، وليس فيهم خير\nفاكفف لسانك أن تعير، واعلمن … أن ليس يأمن، ما يعيب، معير\nما حط، رتبتك، الحسود، وما الذي … ضر الأمير بأن يقال أمير\nوسهيل اللماح صغر لفظه، … فانظر أهيره، بذاك، مهير؟\nوعهدتني، زمن الشبيبة، ذاكيا … قبسي، فأخمد، والخطوب تغير\nلا يستطيع الناس دفع فضيلة، … بالقدر، صيرها إليك مصير\nهذي الكواكب، للمليك، شواهد، … منها الخفي، لناظر، والنير\nنمنا، وما رقدت، وحل مقيمنا، … والنجم، في أفق السماء، يسير\nوالمرء حياه المشيب، فشانه … عند الحبائب، وهو نضر شير\nآليت، لا يدري بما هو كائن … متفائل بالأمر، أو متطير\nكالدار صبحها سوى قطانها، … فثووا بها، وتحمل المتدير"},{"id":"diwan-maarri:455","bookId":"diwan-maarri","type":"poem","seq":455,"chapter":"قصائد","title":"كيف احتيالك والقضاء مدبر،","page":"","text":"كيف احتيالك والقضاء مدبر، … تجني الأذى، وتقول إنك مجبر\nأرواحنا معنا، وليس لنا بها … علم، فكيف إذا حوتها الأقبر؟\nومتى سرى، عن أربعين، حليفها، … فالشخص يصغر، والحوادث تكبر\nنفس تحس بأمر أخرى، هذه … جسر إليها، بالمخاوف يعبر\nمن للدفين بأن يفرج لحده … عنه، فينهض، وهو أشعث أغبر؟\nوالدهر يقدم، والمعاشر تنقضي، … والعجز تصديق بمين يخبر\nزعم الفلاسفة، الذين تنطسوا، … أن المنية كسرها لا يجبر\nقالوا وآدم مثل أوبر، والورى … كبناته، جهل امرؤ ما أوبر\nكل الذي تحكون عن مولاكم … كذب، أتاكم عن يهود يحبر\nرامت به الأحبار نيل معيشة … في الدهر، والعمل القبيح يتبر\nعكس الأنام بحكمة من ربه، … فتحكم الهجري فيه وسنبر\nكذب يقال على المنابر دائما، … أفلا يميد، لما يقال، المنبر؟\nوأجل طيبهم دم من ظبية، … وقذى من الحيتان، وهو العنبر\nولعل دنيانا كرقدة حالم، … بالعكس مما نحن فيه تعبر\nفالعين تبكي، في المنام، فتجتني … فرحا، وتضحك في الرقاد فتعبر\nوالنفس ليس لها، على ما نالها … صبر، ولكن بالكراهة تصبر\nيغدو المدجج بازيا أو أجدلا، … فيروح محتكما عليه القبر"},{"id":"diwan-maarri:456","bookId":"diwan-maarri","type":"poem","seq":456,"chapter":"قصائد","title":"يا صالح اجعل وصف شخصك واسمه","page":"","text":"يا صالح اجعل وصف شخصك واسمه … مثلين، إنك في بحارك ماهر\nما فضة الإنسان إلا فضة، … والتبر تتبير، وجدك ظاهر\nوالدر در للهموم، تسره؛ … إن الجواهر، بالأذاة، جواهر\nكذب الذي سمى المملك قاهرا؛ … نحن الأذلة، والمليك القاهر\nوكذاك يدعى طاهرا من كله … نجس، ويفقد، في الأنام، الطاهر"},{"id":"diwan-maarri:457","bookId":"diwan-maarri","type":"poem","seq":457,"chapter":"قصائد","title":"يا رب! عيشة ذي الضلال خسار،","page":"","text":"يا رب! عيشة ذي الضلال خسار، … أطلق أسيرك، فالحياة إسار\nوكأن عمر المرء شقة ظاعن، … تسرى بأنفاس له، وتسار\nوكأنما الدنيا كعاب، أينا … رجى لها صلة، فذاك يسار\nستعود أشباه لعاد مرة، … وتهب من رقداتها الأيسار\nوإذا الفتى لحظ الزمان بعينه، … هان الشقاء عليه والإعسار"},{"id":"diwan-maarri:458","bookId":"diwan-maarri","type":"poem","seq":458,"chapter":"قصائد","title":"الحظ يقسم، عاش بشر ما اشتكى","page":"","text":"الحظ يقسم، عاش بشر ما اشتكى … نظرا، وعمر، أكمها، بشار\nوهي الحوادث عوذ، ولواقح، … وشوائل، وحوائل، وعشار\nكم شرن من أري، يكون مقيله … ثغرا، يشار له وليس يشار\nوالفقر موت، غير أن حليفه … يرجى له، بتمول، إنشار\nونرى مباشرة التراب مهانة، … وإليه ترجع هذه الأبشار\nقد ضن من رزق الغنى بزكاته، … وغدا فلا فلح ولا تعشار\nلم يعط ربع العشر من أوراقه، … فترام من سقي الحيا أعشار"},{"id":"diwan-maarri:459","bookId":"diwan-maarri","type":"poem","seq":459,"chapter":"قصائد","title":"ذهب الكرام، فليتهم ذهب يرى،","page":"","text":"ذهب الكرام، فليتهم ذهب يرى، … ونضار أحساب الرجال نضار\nإن يبق لا يهرم، وإن يطرح إلى … حمراء موقدة، فليس يضار\nلا يدرك اليوم، الذي خلفته، … تقريب سابقة، ولا إحضار"},{"id":"diwan-maarri:460","bookId":"diwan-maarri","type":"poem","seq":460,"chapter":"قصائد","title":"أقصرت من قصر النهار، وقد أنى","page":"","text":"أقصرت من قصر النهار، وقد أنى … مني الغروب، وليس لي إقصار\nوينال طالب حاجة، بفلاته، … ما لا تجود بمثله الأمصار\nوإذا الحوادث جهزت جيشا لها، … خمدت قريش فيه والأنصار\nأنا ما حججت، فكم تحج نوائب … شخصي، ويفقد، عندها، الإحصار\nقدم الزمان، وعمره، إن قسته، … فلديه أعمار النسور قصار\nالهم منتشر، ولكن ربه … يوما، يصير إلى الثرى، فيصار\nوالمعصرات، من الخراد، عواصف، … كالمعصرات، صنيعها إعصار\nكم يسمع الناس العظات، وكم رأوا … غير الجميل، فغضت الأبصار"},{"id":"diwan-maarri:461","bookId":"diwan-maarri","type":"poem","seq":461,"chapter":"قصائد","title":"أفطر وصم، أو صم وأفطر، خائفا،","page":"","text":"أفطر وصم، أو صم وأفطر، خائفا، … صوم المنية ما له إفطار\nوأراع من تربي، ولا أرتاع من … تربي، وفي قرب الأنيس خطار\nمن كالصعيد الحر، من أبنائه … زهر الربيع، وروضه المعطار\nوكأن في كف الزمان، بنوره، … قطرا، تعم بنشره الأقطار\nمتمطرين إلى الخيانة والأذى … وهم السحائب، ما لها إمطار\nومن الفضيلة للجوامد أنها … لا حس يتبعها، ولا أوطار\nتخذ الغراب، على المفارق، موقعا … ولقد علمت بأنه سيطار"},{"id":"diwan-maarri:462","bookId":"diwan-maarri","type":"poem","seq":462,"chapter":"قصائد","title":"اللب قطب، والأمور له رحى،","page":"","text":"اللب قطب، والأمور له رحى، … فيه تدبر كلها وتدار\nوالبدر يكمل، والمحاق مآله، … وكذا الأهلة عقبها الإبدار\nإلزم ذراك، وإن لقيت خصاصة، … فالليث يستر حاله الإخدار\nلم تدر ناقة صالح، لما غدت، … أن الرواح يحم فيه قدار\nهذي الشخوص، من التراب، كوائن، … فالمرء، لولا أن يحس، جدار\nوتضن بالشيء القليل، وكل ما … تعطي وتملك، ما له مقدار\nويقول داري، من يقول، وأعبدي؛ … مه! فالعبيد، لربنا، والدار\nيا إنس! كم يرد، الحياة، معاشر … ويكون، من تلف، لهم إصدار\nأتروم من زمن وفاء مرضيا، … إن الزمان، كأهله، غدار\nتقفون، والفلك المسخر دائر، … وتقدرون، فتضحك الأقدار"},{"id":"diwan-maarri:463","bookId":"diwan-maarri","type":"poem","seq":463,"chapter":"قصائد","title":"طرق العلا مجهولة، فكأنها","page":"","text":"طرق العلا مجهولة، فكأنها … صم العدائد، ما لها أجذار\nوالعقل أنذرنا بما هو كائن … في الدهر، ثم تشعب الإنذار\nأعذرت طفلك، سالكا نهج الهدى، … ولذاك، في طلب العلا، إعذار\nونحاذر الأشياء، بعد يقيننا، … أن لا يرد الكائنات حذار\nبالصمت يدرك طامر رامه، … وتخيب منه بعوضة مهذار"},{"id":"diwan-maarri:464","bookId":"diwan-maarri","type":"poem","seq":464,"chapter":"قصائد","title":"أمتار من هذا الأنام، وكيف لي،","page":"","text":"أمتار من هذا الأنام، وكيف لي، … ومن الزمان وشره أمتار\nستر وبخل، والتجنب والنوى، … أستار مثلك، دوننا إستار\nلو تترك الدنيا الفتى ومراده، … لوجدته يشتط، أو يختار\nأمسى يذم الخاترين، محققا، … والله يشهد أنه ختار\nوإذا الغنى لزم الغني، لأجله، … طلب المعين، فذلك الإقتار\nولرب مشتار في الذرى، … فجنى المنية في الذي يشتار"},{"id":"diwan-maarri:465","bookId":"diwan-maarri","type":"poem","seq":465,"chapter":"قصائد","title":"لا تصحبن، يد الليالي، فاجرا،","page":"","text":"لا تصحبن، يد الليالي، فاجرا، … فالجار يؤخذ أن يعيب الجار\nهذي سجايا آل آدم، إنهم، … لثمار كل ظلامة أشجار\nوالله ليس بطالب، من جابر، … ما نال أبجر وابنه حجار\nضربت كنانة، خشب، فتية، … لقب، مضى لأبيهم، النجار\nثم استبيحوا، عنوة، فكأنهم … جاروا، وما كانوا الرسول أجاروا\nفجرت قريش بالفجار وحربه، … ولكل نفس، في الحياة، فجار\nأهجر ولا تهجر، وهجر ثم لا … تهجر، فيذهب، ماءك، الإهجار\nوأراك توجر، حين توجر، ناشئا، … عظة، وإن لم يرضك الإيجار\nوإذا بذلتم نائلا لتعوضوا … عنه، فأنتم، في الجميل، تجار\nثعل بن عمرو ما حماه شامخ، … صعب ولا ثعل الوحوش، وجار\nقد عاد شوك فزارة متحرقا، … وتصدعت، من دارم، الأحجار"},{"id":"diwan-maarri:466","bookId":"diwan-maarri","type":"poem","seq":466,"chapter":"قصائد","title":"لا تأسفن لفائت، ما واحد","page":"","text":"لا تأسفن لفائت، ما واحد … يقضى له، في نفسه، إيثار\nويود أن لا تنقضي آثاره، … ولتدرسن، كشخصه، الآثار\nتمشي علينا الحادثات، ووطؤها، … كسنا البوارق ليس فيه عثار\nأظننت دهرك، عن خطابك، صامتا، … وإذا أبهت، فإنه مكثار\nهذا امرؤ القيس بن حجر في الثرى … دثرت معالمه، فأين دثار؟\nإن كان من قتل المحارب مجبرا … يسطى عليه، فأين يبغى الثار؟\nتلفي الكبير، على تقادم سنه، … والطبع فيه طماعة وكثار\nوتخاف من كون الردى، وكأنه … صيد، لضارية الخطوب، مثار\nفابعد، من الثرثار، حتى الورد من … نهر، على الظمأ، اسمه الثرثار"},{"id":"diwan-maarri:467","bookId":"diwan-maarri","type":"poem","seq":467,"chapter":"قصائد","title":"دنياك تشبه ناضحا مترددا،","page":"","text":"دنياك تشبه ناضحا مترددا، … من شأنها الإقبال والإدبار\nآليت ما الحبر المداد بكاذب، … بل تكذب العلماء والأحبار\nزعموا رجالا كالنخيل جسومهم، … ومعاشر أماتهم أشبار\nإن يصغروا أو يعظموا فبقدرة، … ولربنا الإعظام والإكبار\nووجدت أصناف التكلم ستة، … بالمين منها أفرد الإخبار\nخاطت إبار الشيب فودك، بعدما … خلق الشباب، فهل لهن إبار؟\nيستصغر الحي الحقير، ودونه … أمم، توهم أنه جبار\nجشب كفاك مطاعما، وعباءة … أغنتك أن تتخير الأوبار\nأما وبار، فقد تحمل أهلها، … وتخلفت بعد القطين وبار\nوالشخص، في الغبراء، غبر، فانثنى … وكأنما هو للغبار غبار\nيا طالبا ثأر القتيل، ألم يبن … لك أن كل العالمين جبار؟\nوتخالف الأهواء: هذا مدع … فعلا، وذلك دينه الإجبار"},{"id":"diwan-maarri:468","bookId":"diwan-maarri","type":"poem","seq":468,"chapter":"قصائد","title":"أجزاء دهر ينقضين، ولم يكن","page":"","text":"أجزاء دهر ينقضين، ولم يكن … بيني وبين جميعهن جوار\nيمضي، كإيماض البروق، وما لها … مكث، فيسمع، أو يقال حوار\nأنوار مهلا! كم ثوى من ربرب … نور، ولاحت، في الدجى، أنوار\nمنع الزيارة، من لميس وزينب، … حتف، لكل خريدة زوار\nوتسير عن أترابها، لترابها … جمل، ويورث دملج وسوار\nيرمي، فلا يشوي الزمان، إذا رمى … سهما، وأخطأ ذلك الاسوار\nونسور للرتب العلا، فيردنا، … للقدر، صرف نوائب سوار\nوكأنما الصبح الفتيق مهند … للقهر، ماء فرنده موار\nقد ذر قرن، ثم غاب، فهل له … معنى؟ أجل، هو للنفوس بوار\nإن غار بيت أمنا في ليله، … فإذا يغور، فثائر مغوار\nصور تبدل غيرها، فمعوض … بالخيط خيط، والصوار صوار\nإني أواري خلتي، فأريهم … ريا، وفي سر الفؤاد أوار\nيخفي العيوب، وفي الغيوب حديثها، … وغدا يبين، أمرها، المشوار\nوونى الرجال العاملون، وما ونى … فلك، بخدمة ربه دوار\nويكر، من جيش القضاء، مسلط، … ثور وشابة، تحته، خوار\nأطوار دارك بعته من ظالم؛ … والناس، مثل زمانهم، أطوار\nما زال ربك ثابتا في ملكه، … ينمي إليه، للعباد، جؤار\nوأتت على الأكوار، جمع الكور، وال … كور المسرح، هذه الأكوار\nأيام، سنبلة السماء زريعة، … وسهيلها، فحل النجوم، حوار"},{"id":"diwan-maarri:469","bookId":"diwan-maarri","type":"poem","seq":469,"chapter":"قصائد","title":"أما القيامة، فالتنازع شائع","page":"","text":"أما القيامة، فالتنازع شائع … فيها، وما لخبيئها إصحار\nقالت معاشر: ما للؤلؤ عائم، … يوما، إلى ظلم المحار، محار\nوبدائع الله القدير كثيرة، … فيحور، فيها، لبنا، ويحار\nهذي حروف اللفظ سطر واحد، … منها يؤلف للكلام بحار\nأفهم أخاك بما تشاء ولا تبل، … يا حار، قلت هناك، أو يا حار\nغرض الفتى الإخبار عما عنده، … ومن الرجال، بقوله، سحار\nلم تأت آصالي بما أنا شاكر … منها، فتفعل مثله الأسحار"},{"id":"diwan-maarri:470","bookId":"diwan-maarri","type":"poem","seq":470,"chapter":"قصائد","title":"طفئت عيون الناظرين، وأشرقت","page":"","text":"طفئت عيون الناظرين، وأشرقت … عين الغزالة، ما بها عوار\nويكون، للزهر الطوالع، منتهى … يذوين فيه، كما ذوى النوار"},{"id":"diwan-maarri:471","bookId":"diwan-maarri","type":"poem","seq":471,"chapter":"قصائد","title":"أيزورنا شرخ الشباب، فيرتجى،","page":"","text":"أيزورنا شرخ الشباب، فيرتجى، … أم يستقر بمنزل، فيزار؟\nهيهات ما لم ينتفض من قبره … مضر، فيبعث، أو يهب نزار\nأضللته، وصبرت عنه، فلا يدي … أزمت عليه، ولا الدموع غزار\nتطوى النضارة، بالليالي، مثل ما … يطوى، بأيدي الصائنات، إزار\nوالعيش حرب لم يضع أوزارها … إلا الحمام، وكلنا أوزار"},{"id":"diwan-maarri:472","bookId":"diwan-maarri","type":"poem","seq":472,"chapter":"قصائد","title":"بين الغريزة والرشاد نفار،","page":"","text":"بين الغريزة والرشاد نفار، … وعلى الزخارف ضمت الأسفار\nوإذا اقتضيت، مع السعادة، كابيا، … أوريته نارا، فقيل عفار\nأما زمانك بالأنيس، فآهل، … لكنه، مما تود، قفار\nأقفرت من جهتين: قفر معازة، … وطعام ليل جاء، وهو قفار\nوإذا تساوى، في القبيح، فعالنا، … فمن التقي، وأينا الكفار؟\nوالناس بين إقامة وتحمل، … وكأنما أيامهم أسفار\nوالحتف أنصف بينهم، لم تمتنع … منه الرئال، ولا نجا الأغفار\nوالذنب، ما غفرانه بتصنع … منا، ولكن ربنا الغفار\nوكم اشتكت أشفار عين سهدها، … وشفاؤها مما ألم شفار\nوالمرء مثل الليث، يفرس دائما، … ولقد يخيب، وتظفر الأظفار\nولطالما صابرت ليلا عاتما، … فمتى يكون الصبح والإسفار؟\nيرجو السلامة ركب خرق متلف، … ومن الخفير أتاهم الإخفار"},{"id":"diwan-maarri:473","bookId":"diwan-maarri","type":"poem","seq":473,"chapter":"قصائد","title":"يا ليل! قد نام الشجي، ولم ينم،","page":"","text":"يا ليل! قد نام الشجي، ولم ينم، … جنح الدجنة، نجمها المسهار\nإن كانت الخضراء روضا ناضرا، … فلعل زهر نجومها أزهار\nوالناس مثل النبت يظهره الحيا، … ويكون، أول هلكه، الإظهار\nترعاه راعية، وتهتك برده … أخرى، ومنه شقائق وبهار\nما ميز الأطفال في إشباحها … للعين، حل ولادة، وعهار\nوالجهل أغلب، غير علم أننا … نفنى، ويبقى الواحد القهار\nوكأن أبناء الذين هم الذرى … أعفاء أهل، لا أقول مهار\nيا ليت آدم كان طلق أمهم، … أو كان حرمها عليه ظهار\nولدتهم، في غير طهر، عاركا، … فلذاك تفقد فيهم الأطهار\nولدي سر، ليس يمكن ذكره، … يخفى على البصراء، وهو نهار\nأما هدى، فوجدته، ما بيننا، … سرا، ولكن الضلال جهار\nوالرزء يبدي، للكريم، فضيلة، … كالمسك ترفع نشره الأفهار\nفازجر عزيزتك المسيئة، جاهدا، … واستكف أن تتخير الأصهار"},{"id":"diwan-maarri:474","bookId":"diwan-maarri","type":"poem","seq":474,"chapter":"قصائد","title":"كم بالمدينة من غريب نازل،","page":"","text":"كم بالمدينة من غريب نازل، … لا ضابىء منهم، ولا قيار\nأما الذين تديروا، فتحملوا، … وتخلفت، بعد القطين، ديار\nسار الزمان بهم إلى أجداثهم؛ … وكذا الزمان بأهله سيار\nكن حيث شئت بلجة، أو ربوة، … أو وهدة، سينالك التيار\nقد أعرست عرس الأمير بتابع … ضرع، فأين حليلها المغيار؟\nوالدهر سيد في الخديعة، ضيغم … في الفرس، طائر مسلك طيار\nوالأرض تقتات الجسوم، كأنما … هذا الحمام، لتربها، ميار\nوالله يحمد، كلما طال المدى، … طمت الشرور، وقلت الأخيار\nلا حظ، في الدنيا، لعالي همة، … والوحش أفضل صيدها الأعيار"},{"id":"diwan-maarri:475","bookId":"diwan-maarri","type":"poem","seq":475,"chapter":"قصائد","title":"ما للفتى عقرت، حجاه وما له،","page":"","text":"ما للفتى عقرت، حجاه وما له، … حمراء صافية، فقيل عقار\nقرعت بماء، وهي ذائب عسجد، … فطفت عليه، من اللجين، نقار\nأودى أبوها، وهو أسود حالك، … فأقام، يخلفه عليها القار\nلو كان قدسا، ثم هبت ريحها … بهضابه، لم يبق فيه وقار\nقد أفقرته، وفي تجنبها غنى، … ومن المليك غناه والإفقار\nلو تحمل الشرب الرواسي، أوهموا، … أن ليس، فوق ظهورهم، أوقار"},{"id":"diwan-maarri:476","bookId":"diwan-maarri","type":"poem","seq":476,"chapter":"قصائد","title":"قد أذكرت هذي السنون من الأذى،","page":"","text":"قد أذكرت هذي السنون من الأذى، … لا أن ناسيها له أذكار\nوتعارف القوم، الذين عرفتهم، … بالمنكرات، فعطل الإنكار\nما للمنية من عوان أبكرت، … فأوت إليها العون والأبكار\nهل تعلم الطير الغوادي علمنا، … أم لا يصح لمثلها أفكار؟\nلو أنها شعرت بما هو كائن، … لم تتخذ لفراخها الأوكار"},{"id":"diwan-maarri:477","bookId":"diwan-maarri","type":"poem","seq":477,"chapter":"قصائد","title":"يا ظالما! عقد اليدين، مصليا،","page":"","text":"يا ظالما! عقد اليدين، مصليا، … من دون ظلمك يعقد الزنار\nأتظن أنك للمحاسن كاسب، … وخبي أمرك شرة وشنار؟\nومع الفتى، من نفسه، نمية، … ما زال يحلف أنها دينار\nليل بلا نور، أجن بمهمه … حبس الأدلة، ليس فيه منار\nوهي الحياة، فعفة، أو فتنة، … ثم الممات، فجنة أو نار"},{"id":"diwan-maarri:478","bookId":"diwan-maarri","type":"poem","seq":478,"chapter":"قصائد","title":"أتعار عينك يا بن أحمر، ضلة،","page":"","text":"أتعار عينك يا بن أحمر، ضلة، … ويسوم ليس ببارح، وتعار\nمن قبل باهلة، التي ينمى لها … جداك، قيلت فيهما الأشعار\nوكذاك أحكام الزمان، وإنما … ثوب الحياة، وما يضم، معار\nوالدهر عار لا يغادر ملبسا، … فالمجد مندرس به والعار"},{"id":"diwan-maarri:479","bookId":"diwan-maarri","type":"poem","seq":479,"chapter":"قصائد","title":"أعمارنا جاءت، كآي كتابنا،","page":"","text":"أعمارنا جاءت، كآي كتابنا، … منها طوال وفيت، وقصار\nوالنفس في آمالها، كطريدة … بين الجوارح، ما لها أنصار\nومن الرجال محارف في دينه، … وعن المقادر غضت الأبصار\nصلى، فقصر، وهو غير مسافر، … متيمما، ومحله الأمصار\nدفع الزكاة إلى الغني، سفاهة، … وغدا يحج، فرده الإحصار\nإني رقدت فعمت في لجج المنى، … ثم انتبهت، فعادني إقصار\nإن كنت صاحب جنة، في ربوة، … فتوق أن ينتابها إعصار"},{"id":"diwan-maarri:480","bookId":"diwan-maarri","type":"poem","seq":480,"chapter":"قصائد","title":"لا علم لي بم يختم العمر؟","page":"","text":"لا علم لي بم يختم العمر؟ … شجر الحياة، له الردى ثمر\nتغنيك ساعات، مواشكة، … عما تقول البيض والسمر\nوالإنس تهوى قربها أنسا، … وكأنها الآساد والنمر\nحجبت عقلك، عن محاورة … بالخمر، وهي لمثله خمر\nمن سره بدن يعيش به، … فسروري التلويح والضمر\nليل يجن، وفي حنادسه … قمر، تجاول تحته قمر\nوالسود، في الهبوات، يكشفها … خضر المتون، صدورها حمر\nوالناس في تيه، بلا أمر، … والله يفصل عنده الأمر\nوتكشف الغمرات عن رجل، … وهو الجهول، بشأنه، الغمر\nآليت ما في جيلنا أحد … يختار، لا زيد ولا عمرو\nعمنا على در، فأعوزنا؛ … إن الجواهر دونها الغمر\nوأرى المعاشر، في غرائزهم … سوء الطباع: الختل والقمر\nنار، فميتهم الرماد هبا، … وكأنما أحياؤهم جمر\nوتشوقني، في الجنح، زامرة، … ما دينها لعب ولا زمر\nأين الذين كلامهم أبدا … قطر الجهام، وجودهم همر\nإن يغمروك بنائل وندى … منهم فما بصدروهم غمر\nليس امرؤ، في العصر، أعلمه، … إلا وباطن أمره إمر\nأما اللئيم، فعنده حلل، … وغدا الكريم، وثوبه طمر\nطمر الجهول إلى مراتبه، … ثم انثنى وحباؤه طمر"},{"id":"diwan-maarri:481","bookId":"diwan-maarri","type":"poem","seq":481,"chapter":"قصائد","title":"عبر الشباب، لأمه العبر،","page":"","text":"عبر الشباب، لأمه العبر، … لا غابر منه، ولا غبر\nكالأدهم الجاري مضى، فإذا … آثاره، بمفارقي، غبر\nونعوذ بالخلاق، من أمم … أوفى المنازل، منهم، القبر\nإبر العقارب، فوق ألسنهم، … محمولة، فكلامهم أبر\nمن جبرئيل، إذا تخوفهم؛ … لا إيل، عندهم، ولا جبر\nوخبرتهم، فوجدت أخبرهم … مثل الطريدة، ما لها خبر\nهل يعصمنك من لقاء ردى، … بالرغم، أنك عالم حبر؟\nوحصلت من ورق على ورق … بيض، يشق متونها الحبر\nفضت نهاك بفضة سبكت، … ولقد قضى، بتبارك، التبر\nوالله أكبر، فالولاء له، … وكذا الولاء يحوزه الكبر\nلو لم تكن، في القوم، أصغرهم، … ما بان فيك، عليهم، كبر\nوالداء يطرد بالأمر، وصر … ف الخطب، وقت نزوله، الصبر\nوالعيش سقم، لا سآم له، … وجراحه يعيا بها السبر\nوالناس خيرهم كشرهم، … وتساوت النعرات والدبر\nما آل ببر، إن وصفتهم، … إلا ضراغم، جدها ببر\nهاو إلى وهد، يخالفه … راقي الهضاب، كأنه وبر\nيوفي على شرفات منبره، … من همه التحقيق والنبر\nيتلو العظات، وليس متعظا، … بل شده، لحزامه، ضبر\nقد أقطع السبروت يملأ، بال … آل، المروت، فيشحب السبر\nأودى الزمان بذي الأمان، فلا ال … عرجي موجود، ولا جبر"},{"id":"diwan-maarri:482","bookId":"diwan-maarri","type":"poem","seq":482,"chapter":"قصائد","title":"أشدد يديك بما أقو","page":"","text":"أشدد يديك بما أقو … ل، فقول بعض الناس در\nلا تدنون من النسا … ء، فإن غب الأري مر\nوالباء مثل الباء، تخ … فض للدناءة أو تجر\nسل الفؤاد عن الحيا … ة، فإنها شر وشر\nقد نلت منها ما كفا … ك، فما ظفرت بما يسر\nصدف الطبيب عن الطعا … م، وقال: مأكله يضر\nكل يا طبيب! ولا خلا … ص من الردى، فلمن تغر؟\nوالعام يمضي دولتي … ن، فمنهما ومد وقر\nوكذاك عام بعده، … وغفلت عن عمر يمر\nوأرى النوائب لا تزا … ل، كأنها سحب تدر\nإن تنهزم خيل لها، … فحذار من أخرى تكر\nقمر يلوح، مخبرا … بالهلك، أو شمس تذر\nدهما توافينا السنو … ن، ولم يكن فيهن غر\nوالدرع لا تنجي الفتى، … وكأنها في العين كر\nعنوان القصيدة : إن غاض بحر، مدة، … إن غاض بحر، مدة،\nفلطالما غدر الغدير … فلك يدور بحكمة،\nوله، بلا ريب، مدير … إن من مالكنا بما\nنهوى، فمالكنا قدير … أولا، فعالم آدم،"},{"id":"diwan-maarri:483","bookId":"diwan-maarri","type":"poem","seq":483,"chapter":"قصائد","title":"طال صومي، ولست أرفع سومي،","page":"","text":"طال صومي، ولست أرفع سومي، … ووفودي، على المنية، فطر\nأيها الشيب لا يريبك من كف … ي مقص، ولا يواريك خطر\nإن نهيت النفس اللجوج عن الإث … م، وطابت، فإنما أنت عطر\nلحت مثل الكافور، كفر ذنبا، … فلتبرد، إن كان أغلي قطر"},{"id":"diwan-maarri:484","bookId":"diwan-maarri","type":"poem","seq":484,"chapter":"قصائد","title":"ضحك الدهر، في محياك، مكر،","page":"","text":"ضحك الدهر، في محياك، مكر، … ما له، غير أن يسوءك، فكر\nواعتقاد الإنسان، فيك جميلا، … منة، لا ينالها منك شكر\nوالحديث المسموع يوزن بالعق … ل، فيضوى إليه عرف ونكر\nليس بالسن تستحق المنايا؛ … كم نجا بازل وعوجل بكر\nوعوان حازت حلي كعاب، … فاجأتها، من الحوادث، بكر\nقد ركبت الوجناء في جوشن الحن … دس، أكرى في رحلها وهي تكر\nراجيا حسن حالة، إن تخطت … ني، فإعمالها ليحسن ذكر\nساهرا عمر ليلتي، وكأني … طائر، تحته، من الكور، وكر\nأتقضى مع الصباح، فلا أط … لب رزقا، وبي من السهد سكر\nعكر العيش في إنائي، وهل يؤ … مل من صفوه، وقد فات عكر؟"},{"id":"diwan-maarri:485","bookId":"diwan-maarri","type":"poem","seq":485,"chapter":"قصائد","title":"سألتني عن رهط قيل وعتر،","page":"","text":"سألتني عن رهط قيل وعتر، … أين؟ إلا الحديث قيل وعتر\nخاب من خلف الحياة هتيكا، … ما عليه، من الديانة، ستر\nوالفتى والردى، كراكب لج، … إنما نفسه من الموت فتر\nإن تطل عيشة، فإن المنايا … سوف يقضى لها، بمن عاش، وتر\nمن عيوب الكبير قولهم، إن … زل يوما، قد أدرك الشيخ هتر"},{"id":"diwan-maarri:486","bookId":"diwan-maarri","type":"poem","seq":486,"chapter":"قصائد","title":"إصبر، فمن حيث أهين الحصى","page":"","text":"إصبر، فمن حيث أهين الحصى … يكرم، في أدراجه، الدر\nنحن عبيد الله في أرضه، … وأعوز، المستعبد، الحر\nبفضل مولانا وإحسانه، … يماط عنا البؤس والضر\nأما يرى الإنسان، في نفسه، … آيات رب، كلها غر؟\nفي فمه عذب، وفي عينه … ملح، وفي مسمعه مر\nيكر موتانا إلى الحشر، إن … قال لهم بارئهم: كروا\nيخلف منا آخر أولا، … كأننا السنبل والبر\nوالمد يكفيك، ولكن، في … طبعك، أن يدخر الكر\nبنوك يا دنيا على غرة، … لو لم يغروا بك، ما سروا\nوهي المقادير، فذا حتفه … قيظ، وذا ميتته قر"},{"id":"diwan-maarri:487","bookId":"diwan-maarri","type":"poem","seq":487,"chapter":"قصائد","title":"لو شاء ربي لصاغني ملكا","page":"","text":"لو شاء ربي لصاغني ملكا … أو ملكا، ليس يعجز القدر\nأيد مني، وقال أي دم، … أرقت، فهو الجبار والهدر\nفي أصلنا الزيغ والفساد، وه … ذا الليل طبع، لجنحه، الخدر\nقد علم الله أنني رجل، … لا أفتري، ما افتريت يا غدر\nأعلم أني، إذا حييت، قذى، … وأنني، بعد ميتتي، مدر\nكم من رجال جسومهم عفر، … تبنى بهم، أو عليهم الجدر\nيغدو الفتى للأمور، يلمح كالبا … زي، وفي طرف لبه سدر\nلا أزعم الصفو مازجا كدرا، … بل مزعمي أن كله كدر"},{"id":"diwan-maarri:488","bookId":"diwan-maarri","type":"poem","seq":488,"chapter":"قصائد","title":"ما جدري، أمات صاحبه،","page":"","text":"ما جدري، أمات صاحبه، … من جدري، أتت به جدر\nما سدرت، في العيان، أعينهم، … لكن عيون الحجى بها سدر\nوالبدر بعد الكمال ممتحق، … ففيم، يا قوم! تجمع البدر؟\nكيف وفى، للخليل، مؤتمن، … وطبعه، بالأذاة، مبتدر؟\nوالعالم ابن، والدهر والده، … نجل غوي، ووالد غدر\nفي الترب، والصخر، والثمار، … وفي الماء، نفوس يصوغها القدر\nفصادر لا ورود يدركه، … ووارد لا يناله صدر\nإن سلم المرء من عواقبه، … فكل رزء يصيبه هدر\nوالرجل إن حل خدر غانية، … كالرجل في المشي، حلها خدر\nيضمنا الجهل في تصرفنا، … ما شد منا رهط ولا قدروا\nنطلب نورا، يلوح ساطعه، … ودون ذاك الظلام والغدر\nتواضعوا، في الخطوب، ترتفعوا، … فالشهب، عند الرجوم، تنكدر\nلا يطلع الغرب، شافيا ظمأ، … حتى يرى قبل، وهو منحدر\nوالسهل، قدامه الحزونة، والص … فو، من العيش، بعده كدر\nفدر جودا، فدر زاخرة … حصى، تساوى الأنيس والفدر\nإن وطئت، هالك الوغى، فرس، … فجسمه، بعد روحه، مدر"},{"id":"diwan-maarri:489","bookId":"diwan-maarri","type":"poem","seq":489,"chapter":"قصائد","title":"لعمري لقد فضح الأولين","page":"","text":"لعمري لقد فضح الأولين … ما كتبوه وما سطروا\nوقد علم الله أن العباد، … إن يرزقوا نعمة يبطروا\nوإن عجبوا لاحتباس الغمام، … فأعجب من ذاك أن يمطروا\nكأنهم، لقديم الضلال، … جمال على نهجها تقطر\nإذا القوم صاموا فعافوا الطعام، … وقالوا المحال، فقد أفطروا"},{"id":"diwan-maarri:490","bookId":"diwan-maarri","type":"poem","seq":490,"chapter":"قصائد","title":"أيا سارحا في الجو، دنياك معدن","page":"","text":"أيا سارحا في الجو، دنياك معدن … يفوز بشر، فابغ، في غيرها، وكرا\nفإن أنت لم تملك وشيك فراقها، … فعف، ولا تنكح عوانا ولا بكرا\nوألقاك فيها والداك، فلا تضع … بها ولدا، يلقى الشدائد والنكرا\nسمعنا وشاهدنا البدي، وحسبنا، … من العيش، أن فهنا، لخالقنا، شكرا\nإذا ما فعلت الخير، فانس فعاله، … فإنك، ما تنساه، أحيا له ذكرا\nوحاذر من الصهباء، فهي عدوة … من الصهب، مشت في مفاصلك السكرا\nولا خير في الممكورة الخود، أضمرت … لك الغل، وامتارت جوانحها مكرا\nإذا صح فكر المرء فيما ينوبه … من الدهر، لم يشغل، بحادثة، فكرا\nوتغلب كانت سيف بكر ورمحها، … فأمست ترامي، عن حرائبها، بكرا\nكريت عن الشهر الكريت وجزته، … فما لي أكرى عن زماني إذا أكرى؟"},{"id":"diwan-maarri:491","bookId":"diwan-maarri","type":"poem","seq":491,"chapter":"قصائد","title":"أرى الأرض، فيها دولة مضرية،","page":"","text":"أرى الأرض، فيها دولة مضرية، … يكون دم الباغي عداوتها مضرا\nوأردية بيضا تبدل أهلها، … بحكمك رب الناس، أردية خضرا\nوقد زعموا أن القران مغير … ملوك بني النضر، الألى ملكوا النضرا\nوما أعفت الأيام بدوا من الردى، … ولا حضرا، فاسأل بدا عنه والحضرا"},{"id":"diwan-maarri:492","bookId":"diwan-maarri","type":"poem","seq":492,"chapter":"قصائد","title":"إذا حان يومي، فلأوسد بموضع","page":"","text":"إذا حان يومي، فلأوسد بموضع … من الأرض، لم يحفر به أحد قبرا\nهم الناس إن جازاهم الله بالذي … توخوه، لم يرحم جهولا ولا حبرا\nيرى عنتا، في قرب حي وميت … من الإنس، من جلى سرائرهم خبرا\nفيا ليتني لا أشهد الحشر فيهم، … إذا بعثوا شعثا رؤوسهم، غبرا\nإذا تم، في ما تؤنس العين، مضجعي، … فزدني، هداك الله، من سعة شبرا\nوإن سألوا عن مذهبي، فهو خشية … من الله، لا طوقا أبث ولا جبرا"},{"id":"diwan-maarri:493","bookId":"diwan-maarri","type":"poem","seq":493,"chapter":"قصائد","title":"أسرك أن كانت بوجهك وجنة","page":"","text":"أسرك أن كانت بوجهك وجنة … سمية عير، تحمل المسك والعطرا\nوما علم، الأغراض، خاطر حندس … يعد له غاو، يعانده، الخطرا\nفلا القطر آواه، ولا القطر ضمه، … ولا هو ممن يسحب الوشي والقطرا\nأعيش بإفطار وصوم ويقظة … ونوم، فلا صوما حمدت ولا فطرا"},{"id":"diwan-maarri:494","bookId":"diwan-maarri","type":"poem","seq":494,"chapter":"قصائد","title":"إذا آمن الإنسان بالله، فليكن","page":"","text":"إذا آمن الإنسان بالله، فليكن … لبيبا، ولا يخلط بإيمانه كفرا\nإذا نفرت نفس عن الجسم، لم تعد … إليه، فأبعد بالذي فعلت نفرا\nكأن وليدا، مات قبل سقوطه … على الأرض، ناج من حبالته طفرا\nتمنيت أني بين روض ومنهل، … مع الوحش، لا مصرا أحل ولا كفرا\nيقولون مسك الجفر أودع حكمة … إذا كتبت أطراسها ملأت جفرا\nوغافرة، في نيقة، رضعت غنى، … كمغفرة، في النيق، مرضعة غفرا\nمتى ملأت، كفيك، دنياك أرسلت … ملما، يعيد الكف، من جودها، صفرا\nأمن أم دفر تبتغون عطية، … وقد فرقت فيهم سلالتها دفرا\nوكم من عفير الوجه بين أديمها، … وقد كان يرمي قبلها الأدم والعفرا\nغدوت مع الأحياء، مذ حان مولدي … إلى اليوم، ما ننفك، في دأب، سفرا\nوربك عم الوهد، بالرزق، والربا، … وأمطر بالموت العمائر والقفرا\nوإن حبب الله الحسام إلى امرىء، … حباه به، في كل مفرغة، خفرا\nوصير جفنا جفنه، وغراره … غرارا لعينيه، وشفرته شفرا\nوقد ضفرت، فرعا، كريمة معشر، … فما حل إلا الغاسلات له ضفرا\nدنا نيرها من كفها لتعبد، … وألقت دنانيرا براحتها صفرا\nإذا هجرت زيرين: زير أوانس، … وزير غناء، فهي راجية عفرا\nوردنا، بلا وفر، ديار حياتنا، … ونترك فيها، يوم نرتحل، الوفرا\nولو لم يقدر خالق الليث فرسه … لمطعمه، لم يعطه الناب والظفرا\nتطول الليالي والزمان، وتنبري … حوادث لا تبقي، على ظهرها، شفرا\nولا ريب في مهوى الرفيع إلى الثرى، … ولو انه جارى السماكين والغفرا\nولو أن أبراج السماء بروجه، … لبدل منها، غير ممتنع، جفرا\nعجبت لرق ضمن المين، بعدما … تخيره قوم، لتوراتهم، سفرا\nكما وسق، الراح، السقاء، وربما … يضاهي مزادا، من مشاربهم، وفرا"},{"id":"diwan-maarri:495","bookId":"diwan-maarri","type":"poem","seq":495,"chapter":"قصائد","title":"لقد أصبحت دنياك، من فرط حبها،","page":"","text":"لقد أصبحت دنياك، من فرط حبها، … ترينا كثيرا، من نوائبها، نزرا\nولو ظهرت أحداثها لسمعتها … تغيظ، أو عاينت أعينها خزرا\nتواصلنا رميا، وتوسعنا أذى، … وتقتلنا ختلا، وتلحظنا شزرا\nولا ريب عند اللب في أن خيرها … بكي، وإن أمست مصائبها غزرا\nوقد جهزت للعقل راحا تغوله، … فدعها ولا تشرب طلاء، ولا مزرا\nولو أنها جلابة العفو خلتها … حراما، فأنى وهي تجتلب الوزرا\nإذا زارت الشرب المراجيح هتكت … فلم تترك فيهم إزارا ولا أزرا"},{"id":"diwan-maarri:496","bookId":"diwan-maarri","type":"poem","seq":496,"chapter":"قصائد","title":"هو البر في بحر، وإن سكن البرا،","page":"","text":"هو البر في بحر، وإن سكن البرا، … إذا هو جاء الخير لم يعدم الشرا\nوهل تظفر الدنيا علي بمنة، … وما ساء فيها النفس أضعاف ما سرا\nيلاقي حليف العيش ما هو كاره، … ولو لم يكن إلا الهواجر والقرا\nنوائب منها عمت الكهل، والفتى، … وطفل الورى، والشيخ، والعبد، والحرا\nإذا وصلت، بالجسم، روح، فإنها … وجثمانها تصلى الشدائد والضرا\nبدا فرح من معرس، أفما درى … بما اختار من سوء الفعال، وما جرا؟\nسعى آدم جد البرية في أذى … لذرية، في ظهره، تشبه الذرا\nتلا الناس، في النكراء، نهج أبيهم، … وغر بنوه، في الحياة، كما غرا\nيقول الغواة: الخضر حي، عليهم … عفاء، نعم ليل، من الفتن، اخضرا\nولو صدقوا، ما انفك في شر حالة … يعاني بها الأسفار، أشعث، مغبرا\nولكن من أعطاهم الخبر افترى، … وألفي مثل السيد، أجمع وافترا\nجنى قائل بالمين، يطلب ثروة، … ويعذر فيه من تكذب مضطرا\nخذا الآن فيما نحن فيه، وخليا … غدا، فهو لم يقدم، وأمس، فقد مرا\nلنفسي ما أطعمت، لم يدر آكل، … سواي، أحلوا، جاز في الفم، أم مرا\nومن شيم الإنس العقوق، وجاهل … محاول بر عند من أكل البرا\nعجبت لهذي الشمس، يمضي نهارنا، … إذا غربت، حتى إذا طلعت كرا\nلها ناظر لم يدر ما سنة الكرى، … ولا ذر، مذ قال المليك له: ذرا\nوساعاتنا، كالخيل، تجري إلى مدى، … حوالك، دهما، لا محجلة، غرا\nنعيم طما عند امرىء، ومسخر … له، بمجال الحوت يلتمس الدرا\nسواي الذي أرعى السوام، وساقه، … وبالجد، لا بالسعي، أحتلب الدرا\nومن ذا الذي ينضو لباس بقائه … نقي بياض، لم يدنس له زرا؟"},{"id":"diwan-maarri:497","bookId":"diwan-maarri","type":"poem","seq":497,"chapter":"قصائد","title":"تعالى الذي صاغ النجوم بقدرة،","page":"","text":"تعالى الذي صاغ النجوم بقدرة، … عن القول أضحى فاعل السوء مجبرا\nأرى عالما يشكو إلى الله جهله، … وكم من برى يعلو، فيخطب، منبرا\nهم القوم، سافوا عنبرا بمعاطس، … فخافوا وسافوا بالصوارم عنبرا\nيعيش الفتى، ما عاش، كالظبي لم يفد … بدنياه، إلا أن يعال ويكبرا\nولم يدر لما أن أتاها، ولا درى … إلى أين يمضي، فاستكان مدبرا"},{"id":"diwan-maarri:498","bookId":"diwan-maarri","type":"poem","seq":498,"chapter":"قصائد","title":"إذا طلع الشيب الملم، فحيه،","page":"","text":"إذا طلع الشيب الملم، فحيه، … ولا ترض للعين الشباب المزورا\nلقد غاب، عن فوديك، خمسين حجة، … فأهلا به لما دنا، وتسورا\nفمن عثرات المرء، في الرأي، أنه … إذا ما جرى ذكر الخضاب تشورا"},{"id":"diwan-maarri:499","bookId":"diwan-maarri","type":"poem","seq":499,"chapter":"قصائد","title":"جوارك هذا العالم، اليوم، نكبة","page":"","text":"جوارك هذا العالم، اليوم، نكبة … عليك، وليس البين عنه ميسرا\nسيعلم ذاك المدعي صحة الهدى، … متى كان حق، أينا كان أخسرا"},{"id":"diwan-maarri:500","bookId":"diwan-maarri","type":"poem","seq":500,"chapter":"قصائد","title":"إذا ودك الإنسان يوما لخلة،","page":"","text":"إذا ودك الإنسان يوما لخلة، … فغيرها مر الزمان، تنكرا\nويشرب ماء المزن، ما دام صافيا، … ويزهد فيه وارد، إن تعكرا\nوما زال فقر المرء يأتي على الغنى، … ونسيانه مستدركا ما تذكرا\nشرابك بئس الشيء سر، وإنما … أفاد سرورا باطلا، حين أسكرا\nوفي الناس من أعطى الجميل بديهة، … وضن بفعل الخير لما تفكرا\nفخف قول من لاقاك من غير سالف … حميد، فأبدى بالنفاق تشكرا\nوكم أضمر المصحوب مكرا بصاحب، … فألفى قضاء الله أدهى وأمكرا\nيقوم عليه النوح ليلا، ولو غدا … سليما لأجرى شأو غي وبكرا"},{"id":"diwan-maarri:501","bookId":"diwan-maarri","type":"poem","seq":501,"chapter":"قصائد","title":"أتت جامع، يوم العروبة، جامعا،","page":"","text":"أتت جامع، يوم العروبة، جامعا، … تقص على الشهاد، بالمصر، أمرها\nفلو لم يقوموا ناصرين لصوتها، … لخلت سماء الله تمطر جمرها\nفهدوا بناء كان يأوي، فناءه، … فواجر، ألقت للفواحش خمرها\nوزامرة، ليست من الربد، خضبت … يديها ورجليها، تنفق زمرها\nألفنا بلاد الشام إلف ولادة، … نلاقي بها سود الخطوب وحمرها\nفطورا نداري، من سبيعة، ليثها، … وحينا نصادي، من ربيعة، نمرها\nأليس تميم غير الدهر سعدها؛ … أليس زبيد أهلك الدهر عمرها؟\nوددت بأني، في عماية، فارد، … تعاشرني الأروى، فأكره قمرها\nأفر من الطغوى إلى كل قفرة، … أؤانس طغياها، وآلف قمرها\nفإني أرى الآفاق دانت لظالم، … يغر بغاياها، ويشرب خمرها\nولو كانت الدنيا من الإنس لم تكن … سوى مومس، أفنت، بما ساء، عمرها\nتدين لمجدود، وإن بات غيره … يهز لها بيض الحروب، وسمرها\nوما العيش إلا لجة باطلية، … ومن بلغ الخمسين جاوز غمرها\nوما زالت الأقدار تترك ذا النهى … عديما، وتعطي منية النفس غمرها\nإذا يسر الله الخطوب فكم يد، … وإن قصرت، تجني من الصاب تمرها\nولولا أصول، في الجياد، كوامن، … لما آبت الفرسان تحمد ضمرها"},{"id":"diwan-maarri:502","bookId":"diwan-maarri","type":"poem","seq":502,"chapter":"قصائد","title":"إذا ردنت فيما يعود لطفلها","page":"","text":"إذا ردنت فيما يعود لطفلها … بنفع، فآمرها ورج إمارها\nوجنتك الأولى عروسك وافقت … رضاك، فإن أجنتك فاجن ثمارها\nوما هذه الدنيا بأهل وديعة، … فلا تأتمنها، قد عرفت أمارها\nولا أحمد البيضاء تشرب محضها … وتسقي بنيها والنزيل سمارها\nوتترك جمر الزوج يخبو، لرحلة … إلى الركن والبطحاء، ترمي جمارها\nوأولى بها من بيت مكة بيتها، … إذا هي قضت حجها واعتمارها\nمتى شربت خمرا، فلست بآمن … عليها غويا أن يحل خمارها\nفقد عريت بالكأس من كل ملبس … جميل، وألقت في حشاك خمارها\nمع القمر الساري تعلق ودها، … فما بذلت للخل إلا قمارها\nوخير النساء الحاميات نفوسها … من العار، قبل الخيل تحمي ذمارها\nأراني غمرا بالأمور، ولم أزل … أجوب دجاها، أو أخوض غمارها\nوأفضل من مزمار شرب نعامة، … تكرر، في السهب الرحيب، زمارها"},{"id":"diwan-maarri:503","bookId":"diwan-maarri","type":"poem","seq":503,"chapter":"قصائد","title":"أريد، من الدنيا، خمود شرورها،","page":"","text":"أريد، من الدنيا، خمود شرورها، … فتوقد، ما بين الجوانح، نارها\nتضللني في مهمه بعد مهمه، … عدمت به أنوارها ومنارها\nوتظهر لي مقتا، وأضمر حبها، … كأني جهول ما عرفت شنارها"},{"id":"diwan-maarri:504","bookId":"diwan-maarri","type":"poem","seq":504,"chapter":"قصائد","title":"إذا ركبت إجارها، ورأيتها","page":"","text":"إذا ركبت إجارها، ورأيتها … تكلم يوما، في التستر، جارها\nفبادر إليها البت، واهجر وصالها، … وقل تلك عنس حل راع هجارها\nوإن شاجرت في ابن لها أو كريمة … عليها، فياسرها، وخل شجارها\nإذا شئت يوما أن تقارن حرة … من الناس، فاختر قومها ونجارها\nفمنهن من تعطي الرباح عشيرها؛ … ومنهن من تنبي بخسر تجارها"},{"id":"diwan-maarri:505","bookId":"diwan-maarri","type":"poem","seq":505,"chapter":"قصائد","title":"إن التجارب طير تألف الخمرا،","page":"","text":"إن التجارب طير تألف الخمرا، … يصيدها من أفاد اللب والعمرا\nكم جزت شهرا وكم جرمت من سنة، … وما أراني إلا جاهلا غمرا\nوالغي كالنجم عريانا، بلا ستر، … وللحقوق وجوه ألبست خمرا\nألا سفينة، أو عبرا أمد له … كفي، فأنجو من شر لها غمرا\nفلا يغرنك من قرائنا زمر، … يتلون، في الظلم، الفرقان والزمرا\nيقامرون بما أوتوه من حكم، … وصاحب الظلم مقمور إذا قمرا\nيبدي التدين، محتالا، ضمائره … غير الجميل، إذا ما جسمه ضمرا\nيشدو مزامير داود، ويفضله، … في النسك، نافخ مزمار له زمرا\nولا تشيفن، على دار، لتنظرها، … فمن أشاف على قوم كمن دمرا\nيوفي، على المنبر العالي، خطيبهم؛ … وإنما يعظ الآساد والنمرا\nهم السباع، إذا عنت فرائسها؛ … وإن دعوت لخير حولوا حمرا\nقد صدق الناس ما الألباب تبطله، … حتى لظنوا عجوزا تحلب القمرا\nأناقة هو أم شاة، فيمنحها … عسا تغيث به الأضياف، أو غمرا\nوحدثتك رجال عن أوائلها؛ … فاسمع أحاديث مين تشبه السمرا\nرجوت أغصان سدر أن تظللني، … وقد تقلص منها الظل وانشمرا\nيخالف، الطبع، معقول خصصت به، … فاقبل إذا ما نهاك العقل، أو أمرا\nوالدار تدمر من كل، وما غرضي … كون بتدمر لكن منزل دمرا\nوالإنس أشجار ناس أثمرت مقرا، … وأكثر القوم شاك يفقد الثمرا\nوما التقي بأهل أن تسميه … برا، ولو حج بيت الله، واعتمرا\nوالقلب يغرى بما تهدي الرياح له، … كحملها الريح من زيد إلى عمرا\nثب من طمار، إذا لم تستطع سربا؛ … وثب شبيه التميمي الذي طمرا"},{"id":"diwan-maarri:506","bookId":"diwan-maarri","type":"poem","seq":506,"chapter":"قصائد","title":"ما يفتأ المرء، والأبراد يخلقها","page":"","text":"ما يفتأ المرء، والأبراد يخلقها … باللبس، عصرا، إلى أن يلبس الكبرا\nوذاك برد، إذا ما اجتابه رجل، … ألغى الحبور، وألقى بالفم الحبرا\nيا ساكني الأرض! كم ركب سألتهم … بما فعلتم، فلم أعرف لكم خبرا\nزالت خطوب، فلم تذكر شدائدها، … والعود ينسى، إذا ما أعفي، الدبرا\nولن تصيبوا، من الدنيا، سوى صبر، … حتى تكونوا، على أحداثها، صبرا\nوحبها، وهي، مذ كانت، محببة، … أقام داود يتلو، ليله، الزبرا\nدنياكم لكم، دوني، حكمت، بها، … حكم ابن عجلان يجنيها الذي أبرا\nأما رأيت فقيه المصر أقبل من … دفن الصديق، فلم يوعظ بمن قبرا؟\nأنت ابن وقتك، والماضي حديث كرى، … ولا حلاوة للباقي الذي غبرا\nويعبر الحي بالخالي، فيعبره، … وكم رأى ذات ألوان، فما اعتبرا"},{"id":"diwan-maarri:507","bookId":"diwan-maarri","type":"poem","seq":507,"chapter":"قصائد","title":"إذا وفت، لتجار الهند، فائدة،","page":"","text":"إذا وفت، لتجار الهند، فائدة، … فاجعل، مع الله، في دنياك متجرا\nودين مكة، طاوعنا أئمته، … عصرا، فما بال دين جاء من هجرا\nوالسعد يدرك أقواما، فيرفعهم، … وقد ينال، إلى أن يعبد، الحجرا\nوشرفت، ذات أنواط، قبائلها، … ولم تباين، على علاتها، الشجرا\nفاترك ثعالب إنس في منازلها؛ … ودع ثعالب وحش تسكن الوجرا\nوما ثعالب، في قيس ولا يمن، … إلا ثعالب دجن تنفض الوبرا\nأتزجرون أميرا أن يكلفكم … ضيما، فيحمد، غب الشأن، من زجرا\nقد كان يحسن في داجي شبيبته، … حتى إذا لاح، فجرا، شيبه فجرا\nفإن علباء المدعو في أسد، … ساق الحمام، فأسقى ماءه حجرا\nكاد العذاب من الخضراء يمطرنا، … وكادت الأرض ترغو تحتنا ضجرا\nإن صح جسم، فإن الدين منتكس، … تظنه، كل حين، مدنفا هجرا"},{"id":"diwan-maarri:508","bookId":"diwan-maarri","type":"poem","seq":508,"chapter":"قصائد","title":"فوارس الدهر جاءت تسبق النذرا،","page":"","text":"فوارس الدهر جاءت تسبق النذرا، … كأنما هي خيل تنفض العذرا\nفاجعل شعارك حمد الله، تذكره … في كل دهرك، واستشعر به حذرا\nواعذر سواك، فأما النفس إن جرمت … فانقم عليها، ولا تقبل لها عذرا\nوكثرة القول دلت أن صاحبها … ألغى، وبذر، فاهجر، واتق البذرا\nفإن، في الطير، ذا ريش، به ضرع، … إذا أفاق أطال النطق والهذرا"},{"id":"diwan-maarri:509","bookId":"diwan-maarri","type":"poem","seq":509,"chapter":"قصائد","title":"تأخر الشيب عني مثل مقدمه","page":"","text":"تأخر الشيب عني مثل مقدمه … على سواي، ووقت الشيب ما حضرا\nوكم تعدت، يبيس الأرض، راعية … من السوام، ورامت عينها الخضرا\nوأطول الحين يلفى مثل أقصره، … فاسأل ربيعة عما قلت، أو مضرا"},{"id":"diwan-maarri:510","bookId":"diwan-maarri","type":"poem","seq":510,"chapter":"قصائد","title":"أما الحياة، ففقر لا غنى معه","page":"","text":"أما الحياة، ففقر لا غنى معه … والموت يغني، فسبحان الذي قدرا\nلو أنصف العيش لم تذمم صحابته، … وما غدرنا، ولكن عيشنا غدرا\nغفران ربك، هل تغدو، مؤملة، … أغفار شابة، أن تدعى بها فدرا\nأم خص، بالأمل المبسوط، كل فتى … من آل حواء، ينسي ورده الصدرا\nيا صاح! ما خدرت رجلي، فأشكوها، … ولم أزل والبرايا نشتكي الخدرا\nليلا من الغي، لا أنوار يطلعها، … فالركب يخبط، في ظلمائه، الغدرا\nلا تقربن جدريا، ما أردت به … داء يرى، بل شرابا مودعا جدرا\nزفت إلى البدر، والدينار قيمتها، … عند السباء، وكانت تسكن المدرا\nوالخير يندر، تارات، فنعرفه، … ولا يقاس على حرف، إذا ندرا\nوكم مصائب، في الأيام، فادحة، … لولا الحمام، لعدت كلها هدرا"},{"id":"diwan-maarri:511","bookId":"diwan-maarri","type":"poem","seq":511,"chapter":"قصائد","title":"الدين هجر الفتى اللذات عن يسر،","page":"","text":"الدين هجر الفتى اللذات عن يسر، … في صحة واقتدار منه ما عمرا\nوالحلم صبر أخي عز لظالمه، … حتى يقول أناس ذل أو قمرا\nوالغمر يأتي غمار اللج، يحسبها … ضحضاح ماء، فنلفيه وقد غمرا\nوالظبي أشجع من ليث ومن نمر، … إذا ألم يضاهي الليث والنمرا\nومن عناء الليالي خادم ضغن … إن يؤمر الأمر يفعل غير ما أمرا"},{"id":"diwan-maarri:512","bookId":"diwan-maarri","type":"poem","seq":512,"chapter":"قصائد","title":"يذوي الربيع وتخضر البلاد له،","page":"","text":"يذوي الربيع وتخضر البلاد له، … ونحن مثل سوام، نرتعي الخضرا\nولا انتباه لإنس من رقادهم، … إلا إذا قيل: هذا الموت قد حضرا\nوما القبائل، إلا في مقابلة … جيش المنية من عدنان أو مضرا"},{"id":"diwan-maarri:513","bookId":"diwan-maarri","type":"poem","seq":513,"chapter":"قصائد","title":"لا يوقد النار ذاك الحي في أثري،","page":"","text":"لا يوقد النار ذاك الحي في أثري، … فلست أوقد في آثارهم نارا\nحلف السفاه يرى أقمار حندسه … دراهما، ويظن الشمس دينارا"},{"id":"diwan-maarri:514","bookId":"diwan-maarri","type":"poem","seq":514,"chapter":"قصائد","title":"يغدو، إلى كسب قيراط، أخو عمل،","page":"","text":"يغدو، إلى كسب قيراط، أخو عمل، … لو يوزن الإثم فيه كان قنطارا\nيبغي التشبث، بالأوقات، جائزها، … هيهات ما الوقت إلا طائر طارا\nفازجر خواطر نفس غير محسنة، … فقد تجشم، في دنياك، أخطارا\nوالناس يخزون، بالسوآت، أنفسهم، … حتى يقضوا، من الأشياء، أوطارا\nوهجر لذة حين، غير دائمة، … يرد، بالمنطق، المتفال معطارا\nوقد تكون أيادي القوم باذلة، … حتى تعد، مع الأمطار، أمطارا\nإن صمت عن مأكل العاي ومشربه، … فلا تحاول، على الأعراض، إفطارا\nوإن أطيب، من مسك ومن قطر، … أن لا تطور، لدار السوء، أقطارا"},{"id":"diwan-maarri:515","bookId":"diwan-maarri","type":"poem","seq":515,"chapter":"قصائد","title":"يا نحل، إن شار شهدا منك مكتسب،","page":"","text":"يا نحل، إن شار شهدا منك مكتسب، … فحسبه أن، بعد الموت، إنشارا\nوما أسر لتعشير الغراب أسى؛ … ولا أبكي خليطا حل تعشارا\nولا توهمت أنثى الأنجم امرأة؛ … ولا ظننت سهيلا كان عشارا\nولست أحمد بشرى، وهي كاذبة، … ولا أوافق حمادا وبشارا"},{"id":"diwan-maarri:516","bookId":"diwan-maarri","type":"poem","seq":516,"chapter":"قصائد","title":"أبعد من الناس تطرح ثقل ألفتهم،","page":"","text":"أبعد من الناس تطرح ثقل ألفتهم، … ولا ترد لك أعوانا وأنصارا\nولا تحاول من قوم، إذا صحبوا، … أذكوا لرغمك أسماعا وأبصارا\nلما تبينت طول الدهر، طال به … فكري، فأشعر هذي النفس إقصارا\nيا لهف! كم مدن أملاك غدون، فلا … فيه، وكم فلوات عدن أمصارا\nوالله أكبر، لا يدنو القياس له، … ولا يجوز عليه كان أو صارا\nلا ملك لي، وأرى الدنيا تحاصرني، … وما حججت، وقد لاقيت إحصارا"},{"id":"diwan-maarri:517","bookId":"diwan-maarri","type":"poem","seq":517,"chapter":"قصائد","title":"قر البخيل، فأمسى، من تحفظه،","page":"","text":"قر البخيل، فأمسى، من تحفظه، … يلقي على الجسم دينارا فدينارا\nيشكو الشتاء، فيرجو أن يدفئه؛ … أوقد صلاءك، ليس العسجد النارا"},{"id":"diwan-maarri:518","bookId":"diwan-maarri","type":"poem","seq":518,"chapter":"قصائد","title":"كم يسر الأمر، لم تأمل تيسره؛","page":"","text":"كم يسر الأمر، لم تأمل تيسره؛ … وكم حذرت، فما وقيت محذورا\nفاغفر ذنوبا لتجزى بعد مغفرة؛ … واعذر لتصبح بين الناس معذورا"},{"id":"diwan-maarri:519","bookId":"diwan-maarri","type":"poem","seq":519,"chapter":"قصائد","title":"أقاتلي الزمان، قصاص عمد،","page":"","text":"أقاتلي الزمان، قصاص عمد، … لأني قد قتلت بنيه خبرا؟\nولم أسفك دماءهم، ولكن … عرفت شؤونهم كشفا وسبرا\nغدوت وريبه فرسي رهان، … يجيد نوائبا، وأجيد صبرا\nكأن نفوسنا إبل صعاب، … براها عقلها، والعيس تبرا\nوكم ساع ليحبر في بناء، … فلم يرزق بما يبنيه حبرا\nكأم القز يخرج من حشاها … ذرى بيت لها، فيعود قبرا\nلعلك منجزي أغبار ديني، … إذا قمنا من الأجداث غبرا\nوحافر معدن لاقى تبارا، … وكان عناؤه ليصيب تبرا\nتوافقنا على شيم خساس، … فما بال الجهول يسر كبرا؟\nفهذا يسأل البخلاء نيلا؛ … وهذا يضرب الكرماء هبرا\nجلوس المرء في وبر، مليكا، … نظير طلوعه في الهضب وبرا\nودعواك الطبيب، لجبر عضو، … أخف عليك من دعواك جبرا\nوما يحمي الفتى، كبرا، وزردا … بموت، لبسه زردا وكبرا\nنقضي وقتنا بغنى وعدم؛ … وننفق لفظنا همسا ونبرا\nإلى الخلاق، أبرأ من لسان … تعود أن يروع الناس أبرا\nومن يبدع طويا في سهول، … فلا يترك، مع الطارين، زبرا\nكأنا في بحار من خطوب، … وليس يرى لها الراؤون عبرا"},{"id":"diwan-maarri:520","bookId":"diwan-maarri","type":"poem","seq":520,"chapter":"قصائد","title":"أمرت هذه الدنيا، ومرت،","page":"","text":"أمرت هذه الدنيا، ومرت، … وإمرارا أؤنب لا مرورا\nوأغرانا بها طبع لئيم؛ … وأعطت من حبائلها غرورا\nقرتك من القرى، وقرت بهلك، … وأقرت عبأها، وقرت شرورا\nأيلبث لي، فأذكره، زمان، … فإني خلته نسي السرورا"},{"id":"diwan-maarri:521","bookId":"diwan-maarri","type":"poem","seq":521,"chapter":"قصائد","title":"أتفرح بالسرير، عميد ملك،","page":"","text":"أتفرح بالسرير، عميد ملك، … بجهلك والحصول على السريره\nولو قررت فكرك في المنايا، … إذا لبكيت بالعين القريره\nأكل عشية جسد جرير … إلى جدث، ليسأل عن جريره\nوما رقت، ولا رثت الليالي، … من السرحان للأظبي الغريره\nفهل أوصت، بنيها، أم خشف، … بأن لا تظلموا أحدا بريره؟\nتودعنا الحياة بمر كأس، … إذا انتقضت من الحي المريره\nنأى عنه النسيس، فقد تساوى … له لمس الحديدة والحريره"},{"id":"diwan-maarri:522","bookId":"diwan-maarri","type":"poem","seq":522,"chapter":"قصائد","title":"لا يجزعن، من المنية، عاقل،","page":"","text":"لا يجزعن، من المنية، عاقل، … فالنعش من نعش الفتى أن يعثرا\nوالعيش من عشي البصير، أصابه … قلب وإسكان، فسم لتدثرا\nوالدفن دفء في الشتاء، وظلة … في القيظ، حق لمثلها أن يؤثرا\nأعني بذلك أنه لي مؤمن … من كل رزء، في حياتي أثرا\nإن الذي نظم الأنام قضى له … بسلوكه النكبات، حتى ينثرا\nوالرب لم يزدد، ولا هو ناقص؛ … ما قل ملك إلهنا فيكثرا"},{"id":"diwan-maarri:523","bookId":"diwan-maarri","type":"poem","seq":523,"chapter":"قصائد","title":"لم أرض رأي ولاة قوم، لقبوا","page":"","text":"لم أرض رأي ولاة قوم، لقبوا … ملكا بمقتدر، وآخر قاهرا\nهذي صفات الله، جل جلاله، … فالحق بمن هجر الغواة مظاهرا\nنبغي التطهر، والقضاء جرى لنا … بسواه، حتى ما نعاين طاهرا\nوالناس في ظلم الشكوك تنازعوا … فيها، وما لمحوا نهارا باهرا\nنمضي ونترك البلاد عريضة، … والصبح أنور، والنجوم زواهرا\nعش ما بدا لك، لن ترى إلا مدى … يطوى كعادته، ودهرا داهرا\nلا تولدوا، وإذا أبى طبع، فلا … تئدوا، وأكرم بالتراب مصاهرا\nوالجسم أصل فرعته قدرة، … فأبان خالقه حصى وجواهرا\nكم قائم بعظاته متفقه في … الدين، يوجد حين يكشف عاهرا\nوعلمت قلب المرء يغرق في هوى … دنياه، خاب مكاتما ومجاهرا\nماذا أفدت بأن أطلت تفكرا … فيها، وقد أفنيت ليلك ساهرا؟\nوخمول ذكرك، في الحياة، سلامة، … ودهاك من أمسى لذكرك شاهرا\nفتجنبن متوافقين على الأذى، … متخالفين بواطنا وظواهرا\nوإخالنا في البحر، ليس بسالم … منه الذي ركب الغوارب ماهرا\nملكوا فما سلكوا سبيل الرشد، بل … ملأوا الديار ضواربا ومزاهرا"},{"id":"diwan-maarri:524","bookId":"diwan-maarri","type":"poem","seq":524,"chapter":"قصائد","title":"ما للنعائم لا تمل نفارها؛","page":"","text":"ما للنعائم لا تمل نفارها؛ … والشهب تألف سيرها وسفارها\nوالطبع يخفر ذمة من ناسك؛ … والعقل يكره، جاهدا، إخفارها\nتلت النصارى، في الصوامع، كتبها … ويهود تقرأ، بالقوى، أسفارها\nليس المعاشر، سبدت هاماتها، … كمعاشر أمست تجم وفارها\nوأعد قص الظفر شيمة ناسك، … والهند، بعد، مطيلة أظفارها\nملل غدت فرقا، وكل شريعة … تبدي، لمضمر غيرها، إكفارها\nوالرملة البيضاء غودر أهلها، … بعد الرفاغة، يأكلون قفارها\nوالعرب خالفت الحضارة، وانتقت … سكنى الفلاة، ورعلها وصفارها\nكانت إماؤهم زوافر مورد، … فالآن أثقل نضرها أزفارها\nأهلت بها الأمصار، فهي ضوارب … عمد الممالك، لا تريد قفارها\nلم يبق إلا أن تؤم جيادهم … رمحا، لتقطع رملها وجفارها\nعتروا الفوارس بالصوارم والقنا، … والملك في مصر يعتر فارها\nجعلوا الشفار هواديا لتنوفة … مرهاء، تكحل بالدجى أشفارها\nتكبو زناد القادحين، وعامر، … بالشام، تقدح مرخها وعفارها\nوإذا الذنوب طمت، فأخلص توبة … لله، يلف بفضله غفارها"},{"id":"diwan-maarri:525","bookId":"diwan-maarri","type":"poem","seq":525,"chapter":"قصائد","title":"مثل الفتى، عند التغرب والنوى،","page":"","text":"مثل الفتى، عند التغرب والنوى، … مثل الشرارة إن تفارق نارها\nإن صادفت أرضا أرتك خمودها؛ … أو وافقت أكلا أرتك منارها\nولبئس نفس المرء نفس حسنت … فعل القبيح له، فنص شنارها\nورهاء، مفسدة، أهانت عرضها … حتى أصيب، وأكرمت دينارها\nوأساء ناكح زوجة نصرانة، … قطعت، لأجل نكاحه، زنارها"},{"id":"diwan-maarri:526","bookId":"diwan-maarri","type":"poem","seq":526,"chapter":"قصائد","title":"ما لي بما بعد الردى مخبره؛","page":"","text":"ما لي بما بعد الردى مخبره؛ … قد أدمت الآنف هذي البره\nالليل، والإصباح، والقيظ، وال … إبراد، والمنزل، والمقبره\nكم رام سبر الأمر، من قبلنا، … فنادت القدرة لن تسبره\nفاجبر فقيرا بعطاء له، … إن كان، في طولك، أن تجبره\nسبحان مولانا الذي صاغنا، … ما ظهرت، في عضة، عكبره\nعشنا وجسر الموت قدامنا، … فشمر الآن لكي تعبره\nوالعز في الثروة، والعيش في ال … حبرة، والحرفة في المحبره"},{"id":"diwan-maarri:527","bookId":"diwan-maarri","type":"poem","seq":527,"chapter":"قصائد","title":"إياك والأيمان تلقي بها،","page":"","text":"إياك والأيمان تلقي بها، … فإنها محرجة مكفره\nوذمة المؤمن مخفورة … بالدين، لا تدنو لها مخفره\nعيس تباري جدلها بالفتى، … فجد لها يا رب بالمغفره\nأقفر، في المطعم، ركبانها، … والقوم بالدوية المقفره\nما حاولوا عفوك لا غيره، … من ولد، تمنحه، أو فره\nكم جاوزوا من حندس مظلم، … ليبلغوا رحمتك المسفره\nما الغفر، في أنجمه، آمن الاق … دار، بله الغفر والمغفره\nأيلحد الشيخ، وملحوده … قد آن للحافر أن يحفره؟\nبيني وبين البعث طول البلى، … ومن لهذي النفس أن تطفره؟"},{"id":"diwan-maarri:528","bookId":"diwan-maarri","type":"poem","seq":528,"chapter":"قصائد","title":"من عاش سبعين، فهو في نصب،","page":"","text":"من عاش سبعين، فهو في نصب، … وليس للعيش بعدها خيره\nوالخير من زئبق تشكله، … وإنما يرقب امرؤ غيره\nلا يتطير، بناعب، أحد، … فكل ما شاهد الفتى طيره\nرؤيتك الميت في الكرى سبب، … يقول: من يفقد الحياة، يره\nهل سار في الناس أول بتقى، … فيتبع الناس، بعده، سيره؟\nملوكنا الصالحون، كلهم … زير نساء، يهش للزيره"},{"id":"diwan-maarri:529","bookId":"diwan-maarri","type":"poem","seq":529,"chapter":"قصائد","title":"يا حصان النساء! كم فارسا ول","page":"","text":"يا حصان النساء! كم فارسا ول … دك؟ مه! إنما ولدت قبورا\nمن أراد البقاء، وهو حبيب، … فليعدن، للحزن، قلبا صبورا\nلو درى بالذي علمت ثبير، … لدعا، من أذى الحياة، ثبورا\nما ترى، في الزمان، إلا قتيلا، … أو أسيرا، لحتفه، مصبورا\nعبر الناس فوق جسر أمامي، … وتخلفت لا أريد عبورا\nأشعر الله، خالق الأمم، الشع … رى الغميصاء ذلة، والعبورا\nوتحب الأم الخلوب، وداوود … يحب الدنيا، ويتلو الزبورا\nكلنا، يشهد الإله، كسير … يترجى، بضعف رأي، جبورا\nقد خبرنا، فكيف يغتر بالش … يء الذي بات عندنا مخبورا؟"},{"id":"diwan-maarri:530","bookId":"diwan-maarri","type":"poem","seq":530,"chapter":"قصائد","title":"استرد الحياة منك، لعمر الله،","page":"","text":"استرد الحياة منك، لعمر الله، … من كان، للحياة، معيرا\nربما تدرجين في أول النم … ل، إذا ما عدون عيرا فعيرا\nوتحلين قرية، فسقاك ال … موت كأسا، كما سقاها البعيرا\nأترجين، من إلهك، عفوا، … وتخافين، في الحساب، السعيرا؟\nلعن الحرص، كم تحكرت قوتا … ثم خلفت بره والشعيرا"},{"id":"diwan-maarri:531","bookId":"diwan-maarri","type":"poem","seq":531,"chapter":"قصائد","title":"قد يحج الفتى ويغنى بعرس،","page":"","text":"قد يحج الفتى ويغنى بعرس، … وهو، من صرة اللجين، صروره\nبدر المال مثل بدر الدجى يم … حق، من بعد أن يتم، ضروره\nحجة، إن أقمتها لضعيف، … حجة، في حقوقها، مبروره\nأيها المرء! إنما أنت كالنم … لة، تغدو لبرة مجروره\nيبعث الله، في نهار وليل، … بركات، من رزقه، مدروره\nما لباس التقوى على الناس، لكن … ثيابا، على الخنى، مزروره\nأدفئوا بالطعان، بين التراقي، … والحوايا، أسنة مقروره\nقد تلاقي، الحمام في وضح اليو … م، نفوس بصبحها مسروره\nوترى الحق يستنير، فتدري … أنها، في حياتها، مغروره"},{"id":"diwan-maarri:532","bookId":"diwan-maarri","type":"poem","seq":532,"chapter":"قصائد","title":"أتدري النجوم بما عندنا،","page":"","text":"أتدري النجوم بما عندنا، … وتشكو، من الأين، أسفارها\nوتغبط غانية، في النساء، … تعبط، في بيتها، فارها\nبني آدم كلكم ظالم، … فما تنصف العين أشفارها\nوقد أهلت بالخنى داركم، … فلا أبعد الله إقفارها\nويلهم، نساكها، تربها، … كما ظل يلهم كفارها\nفهل قام، من لحده، ميت … يعيب، على النفس، إخفارها\nيقول: جنينا ذنوبا لنا، … وجدنا المهيمن غفارها\nكأن حياة الفتى ليلة، … يرجي أخو اللب إسفارها\nمضى المرء موسى، وأضحت يهود … تتلو، على الدهر، أسفارها\nنقلم، للنسك، أظفارنا، … وطولت الهند أظفارها"},{"id":"diwan-maarri:533","bookId":"diwan-maarri","type":"poem","seq":533,"chapter":"قصائد","title":"تباركت! إن الموت فرض على الفتى،","page":"","text":"تباركت! إن الموت فرض على الفتى، … ولو أنه بعض النجوم التي تسري\nورب امرىء ، كالنسر في العز والعلا، … هوى بسنان، مثل قادمة النسر\nوهون ما نلقى، من البؤس، أننا … بنو سفر، أو عابرون على جسر\nوما يترك الإنسان دنياه، راضيا، … بعز، ولكن مستضاما على قسر\nوما تمنع الآداب والملك سيدا، … كقابوس، في أيامه وفناخسر\nمتى ألق، من بعد المنية، أسرتي … أخبرهم أني خلصت من الأسر\nسما نفر، ضرب المئين، ولم أزل … بحمدك مثل الكسر يضرب في الكسر\nعنوان القصيدة : غدا رمضاني ليس عني بمنقض، … غدا رمضاني ليس عني بمنقض،\nوكل زماني ليلتي آخر الشهر … أروم خلاصا من قضاء مسلط\nعلي، توخى قاهر الناس بالقهر … رمى آل صخر بالصخور، وجرولا\nبهضب، وألقى الراسيات على فهر … ولو طار جبريل، بقية عمره،\nعن الدهر، ما اسطاع الخروج من الدهر … وقد زعموا الأفلاك يدركها البلى،\nفإن كان حقا، فالنجاسة كالطهر … وأما الذي لا ريب فيه لعاقل،\nفغدر الليالي بالظلامية الزهر … وإن صح أن النيرات محسة،\nفماذا نكرتم من وداد ومن صهر؟ … لعل سهيلا، وهو فحل كواكب،\nتزوج بنتا للسماك على مهر … يقولون تأتي فوقنا، مثل ما أتى\nبنو الأرض في حال السرار، أو الجهر … فيا ليت شعري هل تراع من الردى\nوتركع نسكا بالعشاء وبالظهر … وتكذب، أن المين في آل آدم"},{"id":"diwan-maarri:534","bookId":"diwan-maarri","type":"poem","seq":534,"chapter":"قصائد","title":"لقد وضعت حواء، أمك، بكرها","page":"","text":"لقد وضعت حواء، أمك، بكرها … بدار الرزايا، من عوان ومن بكر\nولم يتناول، درة الحق، غائص … من الناس، إلا بالروية والفكر\nصروف الليالي إن سمحن، لماجد؛ … بذكر جميل، عدن يعصفن بالذكر\nمكرن بكل المدركات جسومها … وأعراضها، فليلحق المكر بالمكر\nنهار كذي اللب العديم، وليلة … كإحدى بنات الزنج، يلعبن بالدكر\nفهل علمت شغواء، في النيق، أنها … سيخلجها ريب المنون من الوكر؟\nفإن جهلت ذاك المصاب، فراحة؛ … وإن أيقنته، فهي في نبإ نكر\nدع النسل! إن النسل عقباه ميتة؛ … ويهجر طيب الراح، خوفا من السكر\nعلى الذم بتنا مجمعين، وحالنا، … من الرعب، حال المجمعين على الشكر\nوهل يصبح السادي الجديلي بازلا، … إذا لم يجز، في سنه، عصر البكر؟\nأراع، فلا أرعى، ومثلي معاشر … تنام، فلا تنمي، وتكرى، فلا تكري"},{"id":"diwan-maarri:535","bookId":"diwan-maarri","type":"poem","seq":535,"chapter":"قصائد","title":"أرى ابن أبي إسحاق أسحقه الردى،","page":"","text":"أرى ابن أبي إسحاق أسحقه الردى، … وأدرك عمر الدهر نفس أبي عمرو\nتباهوا بأمر صيروه مكاسبا، … فعاد عليهم بالخسيس من الأمر\nبكسوة برد، أو بإعطاء بلغة … من العيش، لا جم العطاء ولا غمر\nولم يصنعوا شيئا، ولكن تنازعوا … أباطيل تضحي مثل هامدة الجمر\nفلا يضع الله المساعي في التقى، … فمن يسع فيها لا يخف غبن القمر\nأما قاله الكوفي في الزهد، مثل ما … تغنى به البصري، في صفة الخمر؟"},{"id":"diwan-maarri:536","bookId":"diwan-maarri","type":"poem","seq":536,"chapter":"قصائد","title":"مغنية هذي الحمامة، أصبحت","page":"","text":"مغنية هذي الحمامة، أصبحت … تغني على ظهر الطريق، بلا جذر\nأرامت، من الله، الثواب، أم انبرت … تؤمل بالسجع التخلص من نذر؟\nلقد أكثرت، حتى حسبت مقالها، … وإن كان معدوم السقاط، من الهذر\nتخوفنا من أم دفر، خديعة، … ومكرا، فلم تذر الدموع، ولم تذر\nعدمناك دنيانا على السخط والرضا، … فقد شفنا زرع تكون من بذر\nوإنا لعذريون فيك من الهوى، … ولسنا بعذريين فيك من العذر"},{"id":"diwan-maarri:537","bookId":"diwan-maarri","type":"poem","seq":537,"chapter":"قصائد","title":"غبقنا الأذى، والجاشرية همنا،","page":"","text":"غبقنا الأذى، والجاشرية همنا، … ونادى ظلام لا سبيل إلى الجشر\nأتكتب سطرا، ليس فيه تخوف … لربك؛ ما أولى بنانك بالأشر\nوإن بتكت عشر، فمن بعد ما جنت … بكل فسيط، قض أكثر من عشر\nوما زالت الأيام، يبشر صرفها … أديمي، حتى ما يحس من البشر\nوحبري أودى بالمدى، فكأنه … جديد مدى، أنحت لحبرك بالقشر\nوأعجب ما تخشاه دعوة هاتف، … أتيتم، فهبوا يا نيام إلى الحشر\nفيا ليتنا عشنا حياة، بلا ردى، … يد الدهر، أو متنا مماتا بلا نشر"},{"id":"diwan-maarri:538","bookId":"diwan-maarri","type":"poem","seq":538,"chapter":"قصائد","title":"ترج بلطف القول رد مخالف","page":"","text":"ترج بلطف القول رد مخالف … إليك، فكم طرف يسكن بالنقر\nوإن لم تر الصقر الحمامة، دهرها، … فمن شيم الورق الحذار من الصقر\nوإن جاء ضيف طارق، عن ضرورة، … فذخر لقاريه الطعام الذي يقري\nتعودت مني عادة، فتركتها، … وما ذاك من نسيان حق ولا حقر\nوإن اقتناع النفس من أحسن الغنى، … كما أن سوء الحرص من أقبح الفقر"},{"id":"diwan-maarri:539","bookId":"diwan-maarri","type":"poem","seq":539,"chapter":"قصائد","title":"أرى كفر طاب أعجز الماء حفرها،","page":"","text":"أرى كفر طاب أعجز الماء حفرها، … وبالس أغناها الفرات عن الحفر\nكذلك مجرى الرزق واد بلا ندى، … وواد به فيض، وآخر ذو جفر\nخبرت البرايا، والتصعلك، والغنى، … وخفض الحشايا، والوجيف مع السفر\nفأطيب أرض الله ما قل أهله، … ولم ينأ فيه القوت عن يدك السفر\nيعاني مقيم بالعراق، وفارس، … وبالشام، ما لم يلقه ساكن القفر\nفمل عن بني حواء من نسل آدم، … لتنزل بين الحو، والأدم، والعفر\nولا بد، في دنياك، من نصب لها، … وهل وضع الأثقال دهرك عن شفر؟\nأليس هزبر الغاب، وهو مملك … على الوحش، يبغي الصيد بالناب والظفر\nوأنت، إذا استعملت أكواب عسجد، … أسأت ويجزيك الاناء من الصفر\nلقد سكنت نفسي، على الكره، جسمها، … فألفيتها لا تستقر من النفر\nفإن لم تنل وفرا من المال، فاستعن … وفارة عقل، فهي أزكى من الوفر\nوإن لم يكن لب الفتى مع شخصه … وليدا، فما يفري لنفع ولا يفري\nيسمي غوي من يخالف كافرا؛ … له الويل، أي الناس خال من الكفر؟\nحصلنا على التمويه، وارتاب بعضنا … ببعض، فعند العين ريب من الشفر\nوليس الذي قال اليهودي ثابتا، … سوى أنه بالخط أثبت في السفر\nغفرنا وما أغنى اغتفارا، وإنما … عنيت انتكاس البرء لا كرم الغفر\nإذا خشيت أم، على ابن، منية، … فيا أم دفر قد أمنت على دفر"},{"id":"diwan-maarri:540","bookId":"diwan-maarri","type":"poem","seq":540,"chapter":"قصائد","title":"إذا سعد البازي، البعيد مغاره،","page":"","text":"إذا سعد البازي، البعيد مغاره، … تأدى إليه رزقه، وهو في الوكر\nويحوي الفتى بالجد مال عدوه، … على رغمه، من غير حرص ولا مكر\nولو نحست طي لألحق حاتم … بحي، سواها، مثل تغلب أو بكر\nوما أمد، في الدهر، يبلغ، مرة، … بأبعد مما ناله المرء بالفكر\nكلوا طيبا، فالطيب، فيما طعمتم، … يبين على أفواهكم خالص الشكر\nوقد لاح شيب في الذرا فصحوتم، … وصح لكم أن الشباب من السكر\nفلا تنسووا الله، الذي لو هديتم … إلى رشدكم، ما زال منكم على ذكر\nولا تنكروا حق الكبير، فإنه … لأوجب مما تعرفون من النكر"},{"id":"diwan-maarri:541","bookId":"diwan-maarri","type":"poem","seq":541,"chapter":"قصائد","title":"إذا كسر العبد الإناء، فعده","page":"","text":"إذا كسر العبد الإناء، فعده … اذاة له، إن الإناء إلى كسر\nرفيقك أسرى في يديك، فلا تكن … غليظا عليهم واتق الله في الأسر\nنمر، سراعا، بين عدمين، ما لنا … لباث، كأنا عابرون على جسر\nنسير ونسري، عامدين، لمنزل … تشد يداه ربقة السائر المسري\nوقد نأمل الآمال، وهي منوطة … إلى ذنب السرحان، أو عنق النسر"},{"id":"diwan-maarri:542","bookId":"diwan-maarri","type":"poem","seq":542,"chapter":"قصائد","title":"إذا كنت ذا ثنتين فاغد محاربا","page":"","text":"إذا كنت ذا ثنتين فاغد محاربا … عدوين، واحذر من ثلاث ضرائر\nوإن هن أبدين المودة والرضا، … فكم من حقود غيبت في السرائر!\nقرانك ما بين النساء أذية … لهن، فلا تحمل أذاة الحرائر\nوإن كنت غرا بالزمان وأهله، … فتكفيك إحدى الآنسات الغرائر\nلقد ود أصحاب الكبائر لو رأوا … جرائرهم مقذوفة في الجرائر"},{"id":"diwan-maarri:543","bookId":"diwan-maarri","type":"poem","seq":543,"chapter":"قصائد","title":"يعيب أناس أن قوما تجردوا","page":"","text":"يعيب أناس أن قوما تجردوا … لحمامهم، نصب العيون الشوازر\nلقد سعدوا، إن كان لم يجر، عندهم … من الوزر، إلا تركهم للمآزر"},{"id":"diwan-maarri:544","bookId":"diwan-maarri","type":"poem","seq":544,"chapter":"قصائد","title":"عجبت لهذا الشخص يأوي إلى الثرى","page":"","text":"عجبت لهذا الشخص يأوي إلى الثرى … وقد عاش، دهرا، في الرفاق السوائر\nتقلبه الأيام في كل وجهة، … كتقليب وزن في فلوك الدوائر"},{"id":"diwan-maarri:545","bookId":"diwan-maarri","type":"poem","seq":545,"chapter":"قصائد","title":"قضاء يوافي من جميع جهاته،","page":"","text":"قضاء يوافي من جميع جهاته، … كما هو عن أيماننا والأياسر\nولو لم يرد، جور البزاة على القطا، … مكونها، ما صاغها بمناسر\nرأيت سكوتي متجرا، فلزمته، … إذا لم يفد ربحا، فلست بخاسر"},{"id":"diwan-maarri:546","bookId":"diwan-maarri","type":"poem","seq":546,"chapter":"قصائد","title":"يقول لك العقل، الذي بين الهدى:","page":"","text":"يقول لك العقل، الذي بين الهدى: … إذا أنت لم تدرأ عدوا فداره\nوقبل يد الجاني، الذي لست واصلا … إلى قطعها، وانظر سقوط جداره\nوما الوقت إلا طائر يأخذ المدى، … فبادره، إذ كل النهى في بداره\nرأتك البرايا ظالما، يا ابن آدم، … وبئس الفتى من جار عند اقتداره\nونالت أذاة عنه جارا ونائيا، … وأمن منه ضيغم في خداره\nوفارة دارين افتراها لطيبه، … وما أمنت، بلواه، فارة داره\nويجهل حتى يسأل الفلك، الذي … يدور عليه، كيف بدء مداره\nيحاور نجم الليل، جهلا، كأنه، … على طول نأي، طالع في انحداره\nوما برحت في الصدر، للضغن، أنؤر، … عجبت لها لم تشتعل في صداره"},{"id":"diwan-maarri:547","bookId":"diwan-maarri","type":"poem","seq":547,"chapter":"قصائد","title":"لنفسي، إن تنأ عن الجسم، روعة،","page":"","text":"لنفسي، إن تنأ عن الجسم، روعة، … كروعة أنثى، أجليت عن ديارها\nفإن رحلت، بالرغم، مستقرها، … فما كان سكناها له باختيارها\nففوزوا بنسك، في الحياة، وثبتوا … لأقدامكم في الأرض، قبل انهيارها\nوإن تعظموا، في دينكم، جمعاتكم، … فإن رجالا أولعت بشيارها"},{"id":"diwan-maarri:548","bookId":"diwan-maarri","type":"poem","seq":548,"chapter":"قصائد","title":"تعاليت رب النجم، هل هو عالم","page":"","text":"تعاليت رب النجم، هل هو عالم … بحالاته، في مطلع ومغار؟\nأم الشهب لم تشعر، كما جهل الهدى، … وقود، لدى غار، يحش بغار\nولم يدر سيف الهند ما جشم الفتى … به من سرى ليل، وبعد مغار\nومن هوي الدنيا الكذوب، فإنه … رهين بثوبي ذلة وصغار\nإذا هي جادت خسرت، وإذا أبت، … فكم حسرت من جلة وصغار"},{"id":"diwan-maarri:549","bookId":"diwan-maarri","type":"poem","seq":549,"chapter":"قصائد","title":"إذا كنت لا تسطيع دفع صغيرة","page":"","text":"إذا كنت لا تسطيع دفع صغيرة … ألمت، ولا تسطيع دفع كبير\nفسلم إلى الله المقادير، راضيا؛ … ولا تسألن بالأمر غير خبير\nوليس بغال ناصح تستفيده، … ولو كار من تبر بمثل ثبير"},{"id":"diwan-maarri:550","bookId":"diwan-maarri","type":"poem","seq":550,"chapter":"قصائد","title":"ما للبصائر لا تخلو من السدر،","page":"","text":"ما للبصائر لا تخلو من السدر، … والعقل يعصى، فيمسي وهو كالهدر\nآليت أثني على قوم بنسكهم، … وقد تكشف سهل الأرض عن غدر\nإن قلت صفوا بإلغاز، فمعتمدي … صفوا من الصف لا صفوا من الكدر\nمن كان، في الدهر، ذا جد أفاد به … ما شاء، حتى اشتراء البدر بالبدر\nوقس، بما كان، أمرا لم يكن، تره، … فالرجل تعرف بعض الموت بالخدر\nعلى خبيئك أستار، مضاعفة، … بالعقل والصمت والأبواب والجدر\nلكل وقت شؤون تستعد له، … والهم في الورد غير الهم في الصدر\nما قلت أسري، في ليل، على عمل، … أداره الله، والأفلاك لم تدر\nأضر من جدري، شان حامله، … بحمله، جدري، جاء من جدر\nوالمرء ينكر ما لم تجر عادته … بمثله، ثم يبغي الحوت في الغدر\nطأ بالحوافر قتلى في مصارعها، … فالجسم، بعد فراق الروح، كالمدر\nوالنفس تطلب أغراضا، ولو علمت … بالغيب، سيئت بمخبوء من القدر"},{"id":"diwan-maarri:551","bookId":"diwan-maarri","type":"poem","seq":551,"chapter":"قصائد","title":"أمسى خليلك، عند اللب، محتقرا،","page":"","text":"أمسى خليلك، عند اللب، محتقرا، … وليس في الملإ الغادي بمحتقر\nتخال نور الأقاحي، في عوارضه، … يدنى إليه بكأس ذائب الشقر\nإن يعطها، وهو رضوى، في زجاجته، … يعدم رشادا، فلا يحلم ولا يقر\nكم سيد جعلته الراح من خرق، … وكان كالهضب من ثهلان أو أقر\nوالراح تجعل مر العيش، عندهم، … حلوا، وقد ذكرتهم أول المقر\nتخالسوا لذة، منها، معجلة، … ولم يبالوا بما يلقون من سقر\nوأغنت الشرب إلا من جميل نهى، … من يفتقر منه يوجد شر مفتقر"},{"id":"diwan-maarri:552","bookId":"diwan-maarri","type":"poem","seq":552,"chapter":"قصائد","title":"يا ربة الخدر عدي ميتة وسنا،","page":"","text":"يا ربة الخدر عدي ميتة وسنا، … فإنما أنت إحدى الغيد من مضر\nطيبي، ضميرا، بأمر لا محيد له، … يلقاه بالرغم أهل البدو والحضر\nلم تكفه الخضر من لؤم ولا كرم، … ولا تجاوز عن موسى ولا الخضر\nلو كانت الريح تحتي ما نجوت بها، … فكيف أنجو بذات الشد والحضر!"},{"id":"diwan-maarri:553","bookId":"diwan-maarri","type":"poem","seq":553,"chapter":"قصائد","title":"السعد يجعل ذري الدبا نعما؛","page":"","text":"السعد يجعل ذري الدبا نعما؛ … والنحس يهلك ما للمرء من أمر\nوالخمر تخمير عقل، فاجف ضاربة … ترمي الحجا في ضراء الورد والخمر\nيعلل الحي نفسا، غير باقية، … حتى يقصر عنه الليل بالسمر\nلا يعجبنك، في جنح الدجى، قمر، … فإن عقبى محاق غاية القمر\nوالدهر أنسى بني بكر بجيرهم، … وسوف ينسي قريشا غدرة الشمر\nولا تروقنك الأغصان، مائدة، … فإنما تحمد الأشجار بالثمر\nعجبت للظبي منسوبا إلى أسد، … وللمهاة التي تعزى إلى النمر\nفي عالم غيرة الحمراء عادتهم، … وليس تعرف فيهم غيرة الحمر\nوحج، كلمي، بعض الناس، معتمرا، … فهل ألام على حج ومعتمر؟\nومضمرات أمور زادهن، سنا، … إضمارهن، وتجري الخيل بالضمر\nخلدتهن بسجن السر من خلد، … سوداؤه من أعادي البيض في الخمر\nلما تولى يزيد الأمر هان على … معاشر كونه، من قبل، في عمر\nتخاف قمر الليالي، وهي باهشة … إلى الأنام، بأيدي غالة قمر\nنعوذ بالله من ملك، نشبهه … غيما، أراق متى لا يمر لا يمر\nوللمقادير أحكام، إذا وقعت … بالهضب مار، أو اللجي لم يمر\nصار الكتاب مزامير الغواة، لهم … به أغاني في حاميم والزمر\nصلوا به، ثم صلوا، في مظالمهم، … مثل السيوف، على المستأنس، القمر\nقد خانت البعل أنثى، تستجيش له … بهمزة، هو غيث جد منهمر"},{"id":"diwan-maarri:554","bookId":"diwan-maarri","type":"poem","seq":554,"chapter":"قصائد","title":"قد باشروك بمكروه أديت به،","page":"","text":"قد باشروك بمكروه أديت به، … حتى توهمت أن ليسوا من البشر\nزهو التكبر لا زهو النخيل بهم، … والنبع ليس بمجني من العشر\nخمسا وعشرا أجادوا في قراءتهم، … ووفروا المال من خمس ومن عشر\nوما يحجون من دين ولا نسك، … وإنما ذاك إفراط من الأشر\nإذا استشاروك فانصحهم، وإن غضبوا … فإن كفيت ولم تسأل فلا تشر\nإن الليالي تسقي الحتف ساكنها: … قيلا وصبحا وفي الظلماء والجشر\nوتلهم النحل جمع الأري جاهدة … حتى إذا جم قالت للعديم: شر\nتعطي وتأخذ، حتى مبسما دردا … أعطت بأخذ الذي فيه من الأشر\nوقد طوتني، كأني ضرب منسرح، … فيا لطي لطي غير منتشر\nوالله ينشر أرواحا بقدرته، … ويبعث الغيث في أرواحه النشر"},{"id":"diwan-maarri:555","bookId":"diwan-maarri","type":"poem","seq":555,"chapter":"قصائد","title":"كم ينظم الدهر من عقد وينثره،","page":"","text":"كم ينظم الدهر من عقد وينثره، … وليس عقد ثرياه بمنتثر\nوطال وقت على ماض، فغادره، … بلا جهاز ولا أثر ولا أثر\nنشكو نفوسا، إلينا، غير محسنة، … ما إن تحن على أقدامنا العثر"},{"id":"diwan-maarri:556","bookId":"diwan-maarri","type":"poem","seq":556,"chapter":"قصائد","title":"إن كان لم يترك قيس له وطرا،","page":"","text":"إن كان لم يترك قيس له وطرا، … إلا قضاه، فما قضيت من وطر\nورب نفس أصابت عيشة رغدا، … لو لم تبت، من مناياها، على خطر\nأمور دنياك سطر، خطه قدر، … وحبها، في السجايا، أول السطر\nصمنا عن القوت، يوما، ثم أعقبه، … فطر، ولا صوم نرجوه من الفطر\nشاطر ضعيفك ما أوتيت من نشب، … وعد ذكرك أخت الجيرة الشطر\nعيشي بعز وموتي غير خاضعة، … شفيت بالمطر، بعد السقي بالمطر\nتضوع دارك مسكا، وهي خالية … مثل القسيمة بعد الأصهب العطر\nكأنما الروض، لما طل، باكرها، … من كل قطر، بمشبوب من القطر\nوما اختيال مغانيها بمنقصة، … إذ ليس ذلك من عجب ولا بطر\nوما أصيح بغربان الشباب: قعي؛ … ولا أنادي غراب الراس: لا تطر\nويحمل، الهم، قلبي، معفيا جسدي؛ … رأسي أحم، وظهري غير منأطر\nوما أميرك، يا ابن المجد، منتسبا، … لكنه ابن تراب، عنه، منفطر\nوالإسم لفظ، أتاك القائلون به، … نأى، ولم يدن للمعنى، ولم يطر\nأبو نعامة، بالأعدان، مولده، … فكيف أصبح معزوا إلى قطر؟"},{"id":"diwan-maarri:557","bookId":"diwan-maarri","type":"poem","seq":557,"chapter":"قصائد","title":"يا طائر اظعن من الدنيا، ولا تكر","page":"","text":"يا طائر اظعن من الدنيا، ولا تكر … للفرخ، واعتش للأرزاق، وابتكر\nوإن صديت، فلا تشرب مدامهم، … فالعقل يرهب منها غائل السكر\nكأنما الخير ماء كان، وارده، … أهل العصور، فما أبقوا سوى العكر\nوما تريك مرائي العين، صادقة، … فاجعل لنفسك مرآة من الفكر\nمن حاول الحزم في إسداء عارفة، … فليلقها عند أهل الحاجة الشكر\nومن بغى الأجر محضا، فليناد لها … برا فقيرا، وإن لاقاه بالنكر\nأنسى المواعظ في رأد الضحى، أصلا، … وما أتاني بالروحات في البكر\nلم تغفل، القول، أيام تحاورني، … كم ذكرتني، فألفت غير مذكر"},{"id":"diwan-maarri:558","bookId":"diwan-maarri","type":"poem","seq":558,"chapter":"قصائد","title":"فعلت فعل تجار مخسرين به،","page":"","text":"فعلت فعل تجار مخسرين به، … فاعبد إلهك ترزق خير متجر\nما للمذاهب قد أمست مغيرة، … لها انتساب إلى القداح، أو هجر\nقالوا: البرية فوضى، لا حساب لها، … وإنما هي مثل النبت والشجر\nفالجاهلية خير من إباحتهم … سجية الحارث الحراب، أو حجر\nفما أفادوا سوى إحلال نسوتهم، … معرضات لأهل الباطن الفجر\nوإن أحسن من تعظيمهم رجلا … صفرا من الحكم، التعظيم للحجر\nوهل ثعالب طي في منازلها، … إلا ثعالب وحش بتن في الوجر؟\nضل الأنام، وهذا منهج أمم، … يهدي إلى الحق، فاسلكه ولا تجر\nخل العباد وما اختاروا، فملكهم، … إذا نظرت، كعبد راح مؤتجر\nيغنيك ظل سيال، يستظل به، … عن سائل التبر في البنيان والحجر"},{"id":"diwan-maarri:559","bookId":"diwan-maarri","type":"poem","seq":559,"chapter":"قصائد","title":"إرجع إلى السن، فانظر ما تقادمها،","page":"","text":"إرجع إلى السن، فانظر ما تقادمها، … فاحكم عليه ولا تحكم على الشعر\nفكم ثلاثين حولا شيبت، ومضت … ستون، والشيب فيها غير مستعر\nوليس ذلك إلا صبغة جعلت … طبعا، وإن قيل: شاب الرأس للذعر\nتمضي الحياة، وما لي إثرها أسف، … وددت أن معير العيش لم يعر\nوالموت يسلب ما في الأنف من شمم … تحت التراب، وما في الخد من صعر\nأرى فراري، من المقدار، سيئة، … لو تعلم الخيل علمي فيه لم تعر\nولا ألوم أخا الإلحاد، بل رجلا … يخشى السعير، وما ينفك في سعر"},{"id":"diwan-maarri:560","bookId":"diwan-maarri","type":"poem","seq":560,"chapter":"قصائد","title":"جر يا غراب وأفسد، لن ترى أحدا","page":"","text":"جر يا غراب وأفسد، لن ترى أحدا … إلا مسيئا، وأي الخلق لم يجر؟\nفخذ من الزرع ما يكفيك من عرض، … وحاول الرزق، في العالي من الشجر\nوما ألومك، بل أوليك معذرة، … إذا خطفت ذبال القوم في الحجر\nفآل حواء راعوا الأسد مخدرة، … ولم ينادوا، بسلم، ربة الوجر\nومن أتاهم بظلم، فهو عندهم … كجالب التمر، مغترا، إلى هجر\nهم المعاشر ضاموا كل من صحبوا … من جنسهم، وأباحوا كل محتجر\nلو كنت حافظ أثمار، لهم، ينعت، … ثم اقتربت، لما أخلوك من حجر"},{"id":"diwan-maarri:561","bookId":"diwan-maarri","type":"poem","seq":561,"chapter":"قصائد","title":"لا تقطع الحين مغتابا لغافلة","page":"","text":"لا تقطع الحين مغتابا لغافلة … من النفوس، ولا تجلس إلى السمر\nتوخ نقل أبي زيد، وكتب أبي … عمرو، وخل كلاما في أبي عمر"},{"id":"diwan-maarri:562","bookId":"diwan-maarri","type":"poem","seq":562,"chapter":"قصائد","title":"أكرم عجوزك، إن كانت موحدة","page":"","text":"أكرم عجوزك، إن كانت موحدة … على التحنف، أو كانت بزنار\nنادت على الدين، في الآفاق، طائفة، … يا قوم! من يشتري دينا بدينار؟\nجنوا كبائر آثام، وقد زعموا … أن الصغائر تجني الخلد في النار"},{"id":"diwan-maarri:563","bookId":"diwan-maarri","type":"poem","seq":563,"chapter":"قصائد","title":"ما بين موسى، ولا فرعون، تفرقة","page":"","text":"ما بين موسى، ولا فرعون، تفرقة … عند المنون، بإكبار وإصغار\nكأنها ذات قر، أطعمت لهبا … ما ضمه الحطب من سدر ومن غار\nأو أم أجر، جرى قتل على نفر … حر وعبد، فجرتهم إلى الغار\nترمي بعضوين ذي نطق وذي خرس … إلى فم لصنوف الطعم فغار"},{"id":"diwan-maarri:564","bookId":"diwan-maarri","type":"poem","seq":564,"chapter":"قصائد","title":"تناقض ما لنا إلا السكوت له،","page":"","text":"تناقض ما لنا إلا السكوت له، … وأن نعوذ بمولانا من النار\nيد بخمس مئين عسجد فديت، … ما بالها قطعت في ربع دينار؟"},{"id":"diwan-maarri:565","bookId":"diwan-maarri","type":"poem","seq":565,"chapter":"قصائد","title":"خير من الظلم للوالين، لو عقلوا،","page":"","text":"خير من الظلم للوالين، لو عقلوا، … عزل بعنف، وغزل بالصنانير\nذللت حتى دنا نير إلى كتد، … وإنما ذاك من حب الدنانير\nفلا يغرنك المنسوج من ذهب، … فقد تواريك أطمار، بلا نير\nشدت مناطق نضر في هوى نفر … من الملوك، ثووا تحت الزنانير\nألهى البرية إلقاء إلى هضم، … كأنما هو حصب في التنانير\nعاثت ذئاب، فلم يزجر معرتها … مستضعفون لفقدان السنانير"},{"id":"diwan-maarri:566","bookId":"diwan-maarri","type":"poem","seq":566,"chapter":"قصائد","title":"لا ينزلن، بأنطاكية، ورع؛","page":"","text":"لا ينزلن، بأنطاكية، ورع؛ … كم حلل، الدين، عقد للزنانير\nبها مدام كذوب التبر، تمزجه، … للشاربين، وجوه كالدنانير\nبيض لوابس ديباج، حمدت لها … سود الإماء، وشعري الصنانير"},{"id":"diwan-maarri:567","bookId":"diwan-maarri","type":"poem","seq":567,"chapter":"قصائد","title":"عصر شتاء، وعصر قيظ،","page":"","text":"عصر شتاء، وعصر قيظ، … وعيد فطر، وعيد نحر\nويوم نعمى، ويوم بؤس، … ونحن في خدعة وسحر\nكأننا، والزمان يمضي، … ركب سفين بلج بحر\nيا طفل حلت بك الرزايا، … فأنت منها صريم سحر\nبأي ذنب أخذت فينا، … لم تجن إلا كذنب صحر"},{"id":"diwan-maarri:568","bookId":"diwan-maarri","type":"poem","seq":568,"chapter":"قصائد","title":"سئمت الكون في مصر وكفر،","page":"","text":"سئمت الكون في مصر وكفر، … ومن لي أن أحل جنوب قفر\nأعلل، حين أغرث، بالخزامى؛ … وأشرب، إن ظمئت، نزيع جفر\nأرى الأيام أنضاء البرايا، … عليها منهم أشباح سفر\nفما يبرقن من زول عجيب؛ … ولا يفرقن من صبح ونفر\nيسرن بمن حملن الدهر، حتى … ينخن بهم إلى أبيات حفر\nفما فرع الفتاة، إذا توارت، … بمفتقر إلى سرح وضفر\nيفارقها الفتى، والدمع جار، … كذاك جرت عوائد أم دفر\nتحد شفارها لردى بنيها، … وما ترجى كرامتها لشفر\nغفرنا بين أمراض الدنايا؛ … وربك أهل إحسان وغفر\nسأتركها، موفرة، لقوم؛ … وهل سمحت لمرتحل بوفر؟\nألا هذا اليقين، فخذه مني، … ودع لمموه ما بات يفري"},{"id":"diwan-maarri:569","bookId":"diwan-maarri","type":"poem","seq":569,"chapter":"قصائد","title":"حديث فواجر، وشراب خمر،","page":"","text":"حديث فواجر، وشراب خمر، … وقتلى يطرحون لأم عمرو\nومهلك دولة، وقيام أخرى؛ … كذاك الدهر أمر بعد أمر\nوموت لا تؤخر عنه نفس، … تهدد، بعده، بصلاء جمر\nوإن الغمر، كان به أناس … يروون العفاة بكل غمر\nتفرق أيها الجسم المعنى! … فجمعك للحوادث بات يمري\nوجدت بخيبر الحمى كثيرا، … ولم توسعك من رطب وتمر\nوما عاشرت، في الدنيا، خليلا، … يريك مودة، إلا لقمر"},{"id":"diwan-maarri:570","bookId":"diwan-maarri","type":"poem","seq":570,"chapter":"قصائد","title":"أهاب منيتي وأحب ستري؛","page":"","text":"أهاب منيتي وأحب ستري؛ … وخوف الشيخ من هرم وهتر\nولو كنت الفنيق، ومثل رضوى … سنامي، هدت الأيام كتري\nألم ترني صرمت حبال عزمي، … كما صرم الخليط حبال فتر؟\nهي الأيام، أعينها روان، … إلى الإنسان، من حول وشتر\nوما يأتيك ما تهوى بضرب … وطعن، في صدور الخيل، نتر\nوما عترت رماح الدهر، إلا … لعتر سواي، دائبة، وعتري\nكأني الأضبط السعدي، سعدي … حمامي، يستجيش بكل قتر\nسألحق رهط شداد بن عاد، … وقائل وفدهم قيل بن عتر\nوكيف أروم تقويم الليالي، … وقد بنيت على ختل وختر؟\nأؤمل جنة رحبت وراحت، … وتعجز قدرتي عن نيل فتر\nوكم وترت لي النكبات قوسا، … كأن الدهر يطلبني بوتر\nأرى الساعات أمكر ساعيات، … فمن ربات أذناب وبتر\nوكم من فارس عيت قناة … بمصرعه، وصادته بقتر"},{"id":"diwan-maarri:571","bookId":"diwan-maarri","type":"poem","seq":571,"chapter":"قصائد","title":"عبيط ضوائن، ونحير جزر،","page":"","text":"عبيط ضوائن، ونحير جزر، … على من أيها الإنسان تزري؟\nقد احتالت، على السفه، البرايا، … بما اتخذته من راح ومزر\nأخفت، على المآثم، ضعف أيد؛ … ورمت بشرب ذلك شد أزر؟\nحياة مرة، وردى ذعاف؛ … كأنا منه في مد وجزر\nفما صنعي، تمر يداي شزرا؛ … وتنقض مرة الأيام شزري\nهل الأمراء إلا في خسار؛ … أو الوزراء إلا أهل وزر؟\nلكل شيمة، وإلى التغاضي … أجيء الكل من خوص وخزر\nتخيرت، اللباس، بنات سام، … ونسوة حام لم تستر بإزر\nبودي أن تهب من المنايا، … فتعلم أنني لم يشو حزري\nولاة العالمين ذئاب ختل، … تكون من الشقاء رعاة فزر\nوما سمحت، ليعربها، الليالي، … وحي نزارها، إلا بنزر\nفإن بخلت عليك نجوم صدق، … فقد مطرتك أنواء بغزر"},{"id":"diwan-maarri:572","bookId":"diwan-maarri","type":"poem","seq":572,"chapter":"قصائد","title":"يجل الملك عن نظم ونثر،","page":"","text":"يجل الملك عن نظم ونثر، … وعن خبر تحدثه بأثر\nوتضؤل فيه هذي الشمس، حتى … تعود كأنها دينار عثر\nوكم دثرت مغان من أناس، … وقد ضاقت بذي لجب ودثر\nإذا أثريت من صبر جميل، … فأنت، وإن فقدت المال، مثر\nكثير، من تكبر بالمعالي … على ما كان من قل وكثر\nأحاول، من بني الدنيا، صلاحا، … وتأبى أن تجيب نفوس غثر\nوأوثر أن أصونهم بجهدي، … وكيف إثارتي والموت إثري؟\nأحاذر، في الزمان الرغد، جدبا … وآمل، في الجدوب، زمان طثر\nوبثر مائح الحدثان يطمو، … إذا التقت المياه بكل بثر\nولو أني عثرت على الثريا، … لكنت محالفا زللي وعثري\nوأهل حزونة حزنوا، وسهل … تسلوا أن ثووا بثرى دمثر"},{"id":"diwan-maarri:573","bookId":"diwan-maarri","type":"poem","seq":573,"chapter":"قصائد","title":"رأيت الحتف طوف كل أفق ،","page":"","text":"رأيت الحتف طوف كل أفق ، … وجاب الأرض من مصر وكفر\nوكيف يثمر الإنسان وفرا، … ولم يخرج من الدنيا بوفر؟\nولم أر مثل أيامي سراعا، … خيول فوارس، وركاب سفر\nلقد عجبوا لأهل البيت، لما … أتاهم علمهم في مسك جفر\nومرآة المنجم، وهي صغرى، … أرته كل عامرة وقفر"},{"id":"diwan-maarri:574","bookId":"diwan-maarri","type":"poem","seq":574,"chapter":"قصائد","title":"ألما تعجبي، من غير سخر،","page":"","text":"ألما تعجبي، من غير سخر، … لقدح الدهر في جبل وصخر\nومخر الغادر الهجري أرضا، … لهتك أوانس، كبنات مخر\nوما كان التجارب من رجال، … سوى ملك يرام، وحب فخر\nكفاك اللب رحلة جاهلي، … تزيرك إيلة وبلاد نخر\nومن يذخر، لطول العيش، مالا، … فإن تقاي عند الله ذخري"},{"id":"diwan-maarri:575","bookId":"diwan-maarri","type":"poem","seq":575,"chapter":"قصائد","title":"ألم ترني، مع الأيام، أمسي","page":"","text":"ألم ترني، مع الأيام، أمسي … وأضحي بين تفليس وحجر؟\nتوخ الأجر في وحش وإنس، … ففي كل النفوس مرام أجر\nولا تجنبني الإحسان ضنا، … إذا ما كان نجرك غير نجري\nوإن هجر المجاور، فاهجرنه، … ولا تقذف حليلته بهجر\nوخف شر الأصاغر من بنيه؛ … وقل ما شئت في أسد وأجر\nولن تلقى، كفعل الخير، فعلا، … ولا مثل المثوبة ربح تجر\nتوقع، بعد هذا الغي، رشدا، … فمن بعد الظلام ضياء فجر\nحشدت، أو انفردت، فلليالي … كتائب، سوف تطرقني بمجر\nفويح النفس من أمل بعيد، … لأية غاية، في الأرض، تجري؟\nزجرت لك الزمان، فلا تضيع … يقين عيافتي، وصحيح زجري"},{"id":"diwan-maarri:576","bookId":"diwan-maarri","type":"poem","seq":576,"chapter":"قصائد","title":"بحكمة خالقي طيي ونشري،","page":"","text":"بحكمة خالقي طيي ونشري، … وليس بمعجز الخلاق حشري\nوقد رفق الذي أوصى أناسا … بعشر في الزكاة، ونصف عشر\nإذا أشرت أكف من رجال، … فما أولى أناملهم بأشر\nأحبك أيها الدنيا كغيري، … وأشراني قلاك، ولست أشري\nونهوى العيش فيك مع الرزايا، … وما طولت من خمس وعشر\nوهذا الدهر بشر بالمنايا، … فلم فرحت ببشر أم بشر؟\nتخون أربعي، ومضى بخمسي، … وأعلق، في حبال الشمس، عشري\nسطور، نحن نكتبها، ليال … مداها كالمدى غريت بقشر"},{"id":"diwan-maarri:577","bookId":"diwan-maarri","type":"poem","seq":577,"chapter":"قصائد","title":"أعن عفر تلم بسرب عفر،","page":"","text":"أعن عفر تلم بسرب عفر، … وتغفر، في الشكاة، لأم غفر؟\nأما في الأرض من رجل لبيب، … فيفرق بين إيمان وكفر؟\nوجدت أباك مفتريا حديثا، … فأنت على مقص الشيخ تفري\nتأمل! هل ترى في الدار شفرا؟ … كأن العين ما سترت بشفر\nخطوب الدهر، من بيض وسود، … عصفن بكل ذي بيض وصفر\nإذا أوتيت ملء يد طعاما، … فأطعم من عراك، ولو كظفر"},{"id":"diwan-maarri:578","bookId":"diwan-maarri","type":"poem","seq":578,"chapter":"قصائد","title":"خذ المرآة، واستخبر نجوما،","page":"","text":"خذ المرآة، واستخبر نجوما، … تمر بمطعم الأري المشور\nتدل على الحمام، بلا ارتياب، … ولكن لا تدل على النشور"},{"id":"diwan-maarri:579","bookId":"diwan-maarri","type":"poem","seq":579,"chapter":"قصائد","title":"غدت دار الشرور، ونحن فيها،","page":"","text":"غدت دار الشرور، ونحن فيها، … فمن يهدي إلى دار السرور؟\nلقد بدلت حالا، بعد حال، … فصرت إلى الغرور من الغرور\nفصبرا! إن أمر، عليك، عيش؛ … فإنك في المقام على المرور"},{"id":"diwan-maarri:580","bookId":"diwan-maarri","type":"poem","seq":580,"chapter":"قصائد","title":"أفي الإحسان غربا جاء جذبا،","page":"","text":"أفي الإحسان غربا جاء جذبا، … وعند الشر ماء في حدور\nفإنك لا إلى شهب الثريا … بلغت، ولا حسبت من البدور\nوتخمص، من مطاعمها، رجال، … لأن همومها ملء الصدور\nودفن الغانيات، لهن أوفى … من الكلل المنيعة، والخدور"},{"id":"diwan-maarri:581","bookId":"diwan-maarri","type":"poem","seq":581,"chapter":"قصائد","title":"تزوج، إن أردت، فتاة صدق،","page":"","text":"تزوج، إن أردت، فتاة صدق، … كمضمر نعم، دام على الضمير\nإذا اطلع الأوانس لم تطلع … إلى عرس تمر، ولا أمير"},{"id":"diwan-maarri:582","bookId":"diwan-maarri","type":"poem","seq":582,"chapter":"قصائد","title":"أرى بشرا، عقولهم ضعاف،","page":"","text":"أرى بشرا، عقولهم ضعاف، … أزالوها لتعدم بالخمور\nأبانوا عن قبائح منكرات، … فدع ما لا يبين من الأمور\nوعاشوا بالخداع، فكل قوم … تعاشر من ذئاب، أو نمور\nإذا ضحكوا لزيد أو لعمرو، … فإن السم يخبأ في العمور"},{"id":"diwan-maarri:583","bookId":"diwan-maarri","type":"poem","seq":583,"chapter":"قصائد","title":"أوى ربي إلي، فما وقوفي","page":"","text":"أوى ربي إلي، فما وقوفي … على تلك المنازل والأواري؟\nوإن طوار ذاك الربع أودى، … بربرب أهله، نوب طواري\nعواري الفتى متعقبات، … بطون بناته منها عواري\nفنزه ناظريك عن الغواني، … وأكرم جارتيك عن الحوار\nإذا قصر الجدار، فلا تشرف … لتنظر ما تستر في الجوار\nوجدت مدى الحوادث واقعات … بلبات المثلب، والحوار\nولا تعجبك ريا عند ريا، … ولا نور تبين من نوار\nوأعرض عن جوار الدار، أوفت … عليه، بزينة أصلا، جواري\nتطلع من سوارك، باختلاس، … إلى خلخال غيرك والسوار\nزوائر بالعشي ومزر شرب، … يكثر مرزياتك والزواري\nعليك العقل، وافعل ما رآه … جميلا، فهو مشتار الشوار\nولا تقبل من التوراة حكما، … فإن الحق عنها في توار\nأرى أسفارها ليهود أضحت … بواري، قد حسبن من البوار\nإذا أخلصت، للخلاق، سرا، … فليست من ضوائرك الضواري\nوإن مر الصوار، فلا تلفت، … بمطرد النسيم، إلى الصوار\nفوار، من زنادك، مثل كاب، … متى ما حلت الغير الفواري\nأسرب، حول دوار، نساء … بمكة، أو عذارى في دوار"},{"id":"diwan-maarri:584","bookId":"diwan-maarri","type":"poem","seq":584,"chapter":"قصائد","title":"وجدت الناس كالأرضين شتى،","page":"","text":"وجدت الناس كالأرضين شتى، … فمن دمث يريع، أو حرار\nجليس الخير كالداري ألقى … لك الريا، كمنتسم العرار\nولكن ضده، في الربع، قين، … أطار إليك مفترق الشرار\nيباكر ظالم جنفا وعرا، … كما بكر الظليم على العرار\nوحب العيش أعبد كل حر، … وعلم ساغبا أكل المرار\nيوقره الكرى، فيقر طورا، … ويمنعه الحذار من القرار\nألاح فلم يعج، بغرار نوم، … لبيضات وضعن على غرار\nفما للمين ينطق بالتنادي؛ … وما للحق يهمس في السرار؟\nأصاح! كأن هذا الدهر شهر، … خلقنا منه في ليل السرار\nوكم عاد أباد، وكم ثمود … أتاها صالح، ذات المرار\nفمهلا يا متمم! إن فهرا … حوت، من مالك، دية الفرار\nعتابك خالدا لم يجد شيئا، … ولا نص الملام إلى ضرار\nلجأت إلى السكوت من التلاحي، … كما لجأ الجبان إلى الفرار\nويجمع مني الشفتين صمتي، … وأبخل، في المحافل، بافتراري\nوكان تأنسي بهم، قديما، … عثارا، حم في شأو اغتراري\nيئست من اكتساب الخير لما … رأيت الخير وفر للشرار\nولم نحلل بدنيانا اختيارا، … ولكن جاء ذاك على اضطرار"},{"id":"diwan-maarri:585","bookId":"diwan-maarri","type":"poem","seq":585,"chapter":"قصائد","title":"أرانا اللب أنا في ضلال؛","page":"","text":"أرانا اللب أنا في ضلال؛ … وأنا موطنون بشر دار\nندار، على الذي نهوى سواه، … بحكم الله في الفلك المدار\nوما يدريك، والإنسان غمر، … وقد يدرى خليلك، وهو دار\nلعل مفاصل البناء تضحي … طلاء للسقيفة، والجدار\nيرجي الناس كلهم حظوظا؛ … وللأقدار فعل باقتدار\nوما رتباتهم إلا غروب، … دوائب في طلوع وانحدار\nإذا كان الذي يأتي قضاء، … فمكثي ليس ينقص عن بدار"},{"id":"diwan-maarri:586","bookId":"diwan-maarri","type":"poem","seq":586,"chapter":"قصائد","title":"تخيم، يا بن آدم، في ارتحال،","page":"","text":"تخيم، يا بن آدم، في ارتحال، … وترقد في ذراك، وأنت ساري\nويأمل ساكن الدنيا رباحا، … وليس الحي إلا في خسار\nغدا العميان، في شرق وغرب، … يعدون العصي من اليسار\nقني فوارس، ما كان منهم … فوارس رحرحان ولا النسار"},{"id":"diwan-maarri:587","bookId":"diwan-maarri","type":"poem","seq":587,"chapter":"قصائد","title":"أصاب، الأخفشين، بصير خطب،","page":"","text":"أصاب، الأخفشين، بصير خطب، … أعاد الأعشيين بلا حوار\nوغيل المازني، من الليالي، … بزند من خطوب الدهر واري\nوللجرمي ما اجترمت يداه؛ … وحسبك من فلاح أو بوار\nفأما فرخه، فبلا جناح، … يطير بحمل أقلام جواري\nولم يهمم بلقط الحب، يوما … فيوجد رهن أشراك دواري\nولا يرد المياه، إذا هواف، … من الأفراخ، متن من الأوار\nأتم، من النسور، بقاء عمر، … نسور الطير لا الشهب السواري\nوأكثر ما شكاه، من الرزايا، … عواري، لضيعته، عواري\nفطورا بالمغارب مستشارا؛ … وطورا بالمشارق في غرار\nولم يخف الحمام، فألجأته … مطلات الصقور إلى تواري\nأجل من الفريد لخازنيه، … وأبقى، في الأكف، من السواري\nوما نفع المبرد من حميم؛ … وصادت ثعلبا نوب ضواري"},{"id":"diwan-maarri:588","bookId":"diwan-maarri","type":"poem","seq":588,"chapter":"قصائد","title":"لا تطلب الغرض البعيد وتسهر،","page":"","text":"لا تطلب الغرض البعيد وتسهر، … ما يقض يأت، وطالب لم يبهر\nجيل فجيل يذهبون، وينطوي … خبر، ويصبح خامل كمشهر\nوالمرء يغشاه الأذى من حيث لا … يخشاه، فاعجب من صروف الأدهر\nومحمد، وهو المنبأ، يشتكي … لمكان أكلته انقطاع الأبهر\nلا تغبطن على الهبات، فإنها … زهر يزول مع الزمان الأزهر\nوالنبت يظهر للعيون، وإن مضت … سنة له، فكأنه لم يظهر\nفي كل عام تستهل غمائم … بشقائق النعمان، أو بالعبهر\nومن الرزية عاهر متوهم … في الناسكين، وناسك في العهر\nومحاسن الدنيا الأنيس، وإنما … أشباح سادتهم أهلة أشهر\nوإذا أردتم للبنين كرامة، … فالحزم أجمع تركهم في الأظهر\nوالرأي أن تدعوا الصوارم كلها … بقرى المشارف، والرماح بسمهر"},{"id":"diwan-maarri:589","bookId":"diwan-maarri","type":"poem","seq":589,"chapter":"قصائد","title":"أصحاب ليكة أهلكوا بظهيرة","page":"","text":"أصحاب ليكة أهلكوا بظهيرة … حميت، وعاد بالرياح الصرصر\nهون عليك أنلت نصرا في الوغى، … أم قال جدك، صادقا، لا تنصر\nكسرى أصاب الكسر جابر ملكه، … والقصر كر على تطاول قيصر\nلا تحمدن، ولا تذمن امرأ … فينا، فغير مقصر كمقصر\nآليت لا ينفك جسمي في أذى، … حتى يعود إلى قديم العنصر\nوإذا رجعت إليه صارت أعظمي … تربا، تهافت في طوال الأعصر\nوالله خالقنا اللطيف مكون … ما لا يبين لسامع، أو مبصر\nأيام لم تك في المواطن كوفة … لمكوف، أو بصرة لمبصر\nكم أهرم، الفتيات، وقت ذاهب، … والشمس تطلع كالفتاة المعصر\nوالعقل يعجب للشروع: تمجس … وتحنف وتهود وتنصر\nفاحذر ولا تدع الأمور مضاعة، … وانظر بقلب مفكر متبصر\nفالنفس، إن هي أطلقت من سجنها، … فكأنها، في شخصها، لم تحصر\nوالطول في وسطى البنان لعلة، … كالنقص في إبهامها والخنصر"},{"id":"diwan-maarri:590","bookId":"diwan-maarri","type":"poem","seq":590,"chapter":"قصائد","title":"يا نفس! آه لمتجر متنزر،","page":"","text":"يا نفس! آه لمتجر متنزر، … جربته، فرجعت عين المخسر\nأعلى ابن أد يفترون، كما افترت، … قدما، على النمروز، شأن الأنسر؟\nسر سيعلن، والحياة معارة، … ولتقضين بها ديون المعسر\nكخبيء نعم وبئس، يخبأ فيهما، … ويكون ذاك على اشتراط مفسر\nأنا في إسار الدهر، لست بمطلق … أبدا، فأسر أخا الطلاقة، أو سر\nوالعيش جسر نال من هو جاسر، … أو كاد فيه، وخاب من لم يجسر\nوإذا قرنت بلام ملك مضمرا، … فتحت به، فكأنها لم تكسر\nوكأن من بلغ العلا لم ينخفض؛ … وكأن من فقد الغنى لم يوسر\nويدلني، أن الممات فضيلة، … كون الطريق إليه غير ميسر\nلولا نفاسته لسهل نهجه، … كأذى الضعيف على اللئيم المكسر\nآليت لو رزق العديم فطانة، … لنفى الهموم، وبات غير محسر\nولئن يعد حمامة، خير له … من أن يضاف إلى ذوات المنسر\nوإذا المعلى عاد أكثر مغرما، … فاقنع بفذك من قداح الميسر"},{"id":"diwan-maarri:591","bookId":"diwan-maarri","type":"poem","seq":591,"chapter":"قصائد","title":"النفس، عند فراقها جثمانها،","page":"","text":"النفس، عند فراقها جثمانها، … مخزونة لدروس ربع عامر\nكحمامة صيدت، فثنت جيدها … أسفا، لتنظر حال وكر دامر"},{"id":"diwan-maarri:592","bookId":"diwan-maarri","type":"poem","seq":592,"chapter":"قصائد","title":"سألت منجمها عن الطفل الذي","page":"","text":"سألت منجمها عن الطفل الذي … في المهد: كم هو عائش من دهره؟\nفأجابها: مائة، ليأخذ درهما، … وأتى الحمام وليدها في شهره\nقلب الزمان، فرب خود تبتغي … زوجا، وتبذل غاليا من مهره\nإن كانت امرأة الفتى في طهرها، … فلعله لم يغشها في طهره\nكره الجهول بناته، وسليله … أجنى، لما يغتاله، من صهره\nأعدى عدو لابن آدم، خلته، … ولد يكون خروجه من ظهره\nوسفاهة الإنسان موهمة له … بذ القوارح، في الرهان، بمهره\nوعقاب والدك الرؤوف تحدب، … ويشق أنف الطرف خشية بهره\nأتسر شيبك عن جليسك، ضلة، … والشيب ليس بعاجز عن جهره\nكم سائل وافى، ودارك سائل … نهر الغنى، فيها، فعاد بنهره\nوالغمر، إن لم تهده شمس الضحى، … لم يهده جنح الظلام بزهره\nفاضرب يتيمك طالبا تأديبه، … ما عد ذلك راشد من قهره\nوالسعد يثني المستضام كغالب … سهك الجبال، من الأنام، بفهره\nوالنحس يعتاد البصير ولبه، … حتى يقيم عشاءه في ظهره"},{"id":"diwan-maarri:593","bookId":"diwan-maarri","type":"poem","seq":593,"chapter":"قصائد","title":"قدم الفتى، ومضى بغير تئية،","page":"","text":"قدم الفتى، ومضى بغير تئية، … كهلال أول ليلة من شهره\nلقد استراح من الحياة معجل، … لو عاش كابد شدة في دهره"},{"id":"diwan-maarri:594","bookId":"diwan-maarri","type":"poem","seq":594,"chapter":"قصائد","title":"أنوار تحسب من سنا الأنوار؟","page":"","text":"أنوار تحسب من سنا الأنوار؟ … ومن البوار مها عرضن بواري\nبيض دوار للقلوب، كأنها … عين بدوار وعين دوار\nهذي أواري المنازل ما درت … أنى أواري، في حشاي، أواري\nأما فواري المين عنك، فصادفت … سمعا، وأما الوجد منك فواري\nوإذا الحواريات صدنك، فابتكر، … مثل الحواريات، إثر حوار\nيرأمن سقبا في الرواح، وإنما … تبني على حور وحسن حوار\nيلعبن بالزوار لعب قوامر، … وإذا بلغن رضا، فهن ذواري\nمثل الصوار، إذا شممت صوارها، … فشجون قلبك، للهموم، صواري\nفاجعل سواري غادة وبراهما، … لبرى غواد، في الركاب، سواري\nيرقلن في خلق الشوار، وفوقها … أخلاق إنس، للقبيح، شواري\nلا تشكون، ففي الشكاية ذلة، … ولتعرضن الخيل بالمشوار\nآليت ما منع الخوار أوابدا … في هضب شابة، والنقا الخوار\nريع اللبيب من المشيب، لأنه … ما زال يؤذن بانتقال جوار\nما أبأس الحيوان، ليس لنابت … أسف بما يبدو من النوار\nوكأن من سكن الفناء متى غدا … للقبر، لم ينزل له بطوار\nتلك النسور من الوكور طوائر، … ومقادر من فوقهن طواري\nإن العواري استرد جميعها، … فالراح منها، والجسوم عواري\nأشباح ناس في الزمان، يرى لها، … مثل الحباب، تظاهر وتواري\nيخلطن فيه بغيرهن، فما مضى … غير الذي يأتي، وهن جواري\nأعيا سوار الدهر كل مساور؛ … ورمى الخليل بأسهم الأسوار\nفاحذر، وإن بعدت غزاتك في العدى، … قدرا أغار على أبي المغوار\nزجرت، قواريها، الزواجر بالضحى، … والحادثات من الحمام قواري\nلو فكرت طلب الغنى في ذاهب الأ … كوار، ما قعدت على الأكوار\nوالندب في حكم الهدان، وذو الصبا … كأخي النهى، والذمر كالعوار\nويقال إن مدى الليالي جاعل … جبلا، أقام كزاخر موار\nجرت القضايا في الأنام، وأمضيت … صدقا، بأسوار ولا أسوار"},{"id":"diwan-maarri:595","bookId":"diwan-maarri","type":"poem","seq":595,"chapter":"قصائد","title":"لا تأنفن من احترافك طالبا","page":"","text":"لا تأنفن من احترافك طالبا … حلا، وعد مكاسب الفجار\nفالمجد أدركه، على علاته، … قوم، بيثرب، من بني النجار\nوإذا أمنت، على الظعينة، زلة، … فاصفح، إن اطلعت من الإجار\nفلهذه النفس الكذوب تشوف، … حتى تكف، عن الأذى، بهجار\nوالقول يوجع، والعتاب ضغينة، … والهجر مشتق عن الإهجار\nفاختر لنفسك منزلا تخلو به؛ … كل الثعالب رائح لوجار\nرأس ابن آدم، أصله وفروعه، … قدماه ضد النبت والأشجار\nوإذا قطعت رؤوس تلك، فجائز، … يوما، تراجعها بحكم جاري\nومتى نزعت، لحلف روح، هامة، … فهو الردى، عمدا، بغير شجار\nوالشر في طبع الأنام، فإن يبن … شيئا سواه، فليس خيم نجار\nهفت الجبال، من الرجال، بعسجد … أو فضة، وهما من الأحجار\nرغبوا، فأزهد من ترى فوق الثرى … يبغون، عند الله، ربح تجار"},{"id":"diwan-maarri:596","bookId":"diwan-maarri","type":"poem","seq":596,"chapter":"قصائد","title":"الشيب أزهار الشباب، فما له","page":"","text":"الشيب أزهار الشباب، فما له … يخفى، وحسن الروض بالأزهار؟\nود الذي هوي الحسان لو اشترى … ظلماء لمته، بألف نهار\nوالناس مثل النبت، أي بهارة … ذهبت، فلم تنفض سليل بهار؟\nليت الجياد، غداة صادفها الردى، … ما أعقبت بنتائج الأمهار\nهار عليه موقف من خائف، … للدهر، فتكة سائف أو هاري\nلولا السفاهة، ما تعلل جاهل … بتخير الأحماء، والأصهار\nإنا لفي وقت الغروب، وقد مضى … زمن الضحاء، وساعة الإظهار\nما أم دفر، في الحياة، مروعة … بطلاق ذي شرف، ولا بظهار\nولقد تشابه، في الظواهر، مولد … حل النكاح، ومولد بعهار\nوالإنس في عماء لم يتبينوا، … بالفكر، إلا حكمة القهار\nيبغي، الطهارة، ناسك، ومحله … في مومس برئت من الإطهار\nومن الرزايا ما يفيء لك العلا، … كالمسك فاح بموقع الأفهار\nأسنيت من مر السنين، ولم أرد … أسنيت من ضوء السنا البهار\nوجهرت، من قلب الوداد، ذمامها … فذممت في سري وعند جهاري\nوشهرت في الدنيا، ومن لي أن أرى … كالنير الفاني، مع الإشهار\nوكأن ساهرة السماء تضمنت … أنفا، من التسهيد والإسهار"},{"id":"diwan-maarri:597","bookId":"diwan-maarri","type":"poem","seq":597,"chapter":"قصائد","title":"سبحان ربك! هل يزول، كغيره،","page":"","text":"سبحان ربك! هل يزول، كغيره، … شرف النجوم وسؤدد الأقمار؟\nفكأن من خلق النفوس رأى لها … ظلما، فعاجلها بسوء دمار\nما سرني بقناعة أوتيتها، … في العيش، ملكا غالب وذمار\nومن المعاشر من يكون ثراؤه … مهر البغي، وبسرة الخمار\nوالشر مشتهر المكان معرف؛ … والخير يلمح من وراء خمار\nويقامر الإنسان، طول حياته، … قدرا تمنع من رضا بقمار\nخف من تود، كما تخاف معاديا، … وتمار فيمن ليس فيه تماري\nفالرزء يبعثه القريب، وما درى … مضر بما تجني يدا أنمار\nيغدو الفتى، والخيل ملك يمينه، … وكأنه غاد بلب حمار\nفإذا ملكت الأرض، فاحم ترابها … من غرسه شجرا بغير ثمار\nإن قلت السمراء عندك، برهة، … فاجزأ بمحض، مرة، وسمار\nوقد ادعى من ليس يثبت قوله، … عظم الجسوم، وبسطة الأعمار\nما كابر إلا كآخر غابر؛ … والحق يعلم وجهه بأمار\nوتغنت الدنيا بصوت واحد؛ … لا تحسن الربداء غير زمار\nومن المجرب، والمدى متطاول … عدت كواكبه من الأغمار\nوشربت كأسا، في الشبيبة، سادرا، … فوجدت بعد الشيب فرط خمار\nما بال هذا الليل طال، وقد يرى … متقاصرا عن جلسة السمار؟\nأتروم فجرا كالحسام، ودونه … نجم أقام، تمكن المسمار؟\nتلقى الفتى كالريح، إن أودعته … سرا أذيع، فصار كالمزمار\nما زال ملك الله يظهر دائبا، … إذ آدم وبنوه في الإضمار\nفامنع ذمارك، إن قدرت، فإنني … عدت الخطوب، فما حميت ذماري\nتقفو الظعائن من نويرة أجمرت … أجمالها، سحرا، لرمي جمار\nوعددت من عمار مكة، بعدما … كنت المريد، يعد في العمار\nفليغن عن لبس الشفوف نسائجا … بالتبر، لبسك رثة الأطمار"},{"id":"diwan-maarri:598","bookId":"diwan-maarri","type":"poem","seq":598,"chapter":"قصائد","title":"جاءتك لذة ساعة، فأخذتها","page":"","text":"جاءتك لذة ساعة، فأخذتها … بالعار، لم تحفل سواد العار\nوابتعت ما يفنى بأغلى سعره؛ … هلا الخلود بأرخص الأسعار!\nوعريت بالكأس الكميت عن التقى، … فاعجب لجسمك، وهو كاس عار\nوسوائل الأشعار غير لوابث، … ولو ارتدين سوائر الأشعار"},{"id":"diwan-maarri:599","bookId":"diwan-maarri","type":"poem","seq":599,"chapter":"قصائد","title":"تلف البصائر، والزمان مفجع،","page":"","text":"تلف البصائر، والزمان مفجع، … أدهى وأفجع من توى الأبصار\nبلغ الفتى هرما، فظن زمانه … هرما، وذم تقادم الأعصار\nكم عاين الفتيات، بعد شبيبة، … عجزا، ودنياهن في الإعصار\nورميت بالهمم الطوال، وغالها … كر الخطوب، فعوضت بقصار\nوالوحش، في الفلوات، أجمل عشرة … للمرء، من أهليه في الأمصار\nوإذا حصلت مراقبا، في منزل، … سكانه، ألفيت خدن حصار\nوالحلم أفضل ناصر تدعونه، … فالزمه يكفك قلة الأنصار\nوتفكر الإنسان يثني غربه، … ويرد جامحه إلى الإقصار"},{"id":"diwan-maarri:600","bookId":"diwan-maarri","type":"poem","seq":600,"chapter":"قصائد","title":"ما حركت قدم ولا بسطت يد،","page":"","text":"ما حركت قدم ولا بسطت يد، … إلا لها سبب من المقدار\nخطب تساوى فيه آل محرق، … وملوك ساسان، ورهط قدار\nيدري الفتى كم عاش من أيامه … يوما، وما هو، كم يعيش، بداري\nوتجوز معرفتي بمسقط هامتي … في الورد، لا بالقبر في الإصدار\nداران، أما هذه فمسيئة … جدا، ولا خبر لتلك الدار\nما جاء منها وافد متسرع، … فنقول للنبإ الجديد: بدار\nوالملك ثبت للقديم، وأبرزت … بلقيس، عارية، بغير صدار\nولرب أجساد جديرات الثرى، … بالصون عادت في طلاء جدار\nجسد توى، إن تفترق أجزاؤه، … لم تنأ عن فلك عليه مدار\nوإذا بدور المال هبت محاقها، … فهلال مجدك غير ذي إبدار"},{"id":"diwan-maarri:601","bookId":"diwan-maarri","type":"poem","seq":601,"chapter":"قصائد","title":"بالغار، من هضبي عماية، نازل،","page":"","text":"بالغار، من هضبي عماية، نازل، … ما زال توقد ناره بالغار\nوكبائر الأشياء تحدث غيرها، … فتعيدها موصوفة بصغار\nومغار هذا الدهر تقطع خيله … أسباب حبل، للحياة، مغار\nلا تبخلن على خليلك، إن بغى … خلا سواك، فتبخلي وتغاري\nلا يجعلن هندا هنيدة فوك، فالت … صغير مقرون إلى الإصغار\nإن الثريا حين صغر، لفظها، … أهل البسيطة، ما دنت لصغار"},{"id":"diwan-maarri:602","bookId":"diwan-maarri","type":"poem","seq":602,"chapter":"قصائد","title":"غسل المليك بلاده، من أهلها،","page":"","text":"غسل المليك بلاده، من أهلها، … بالماء، إذ جاؤوا بسوء شنار\nويقال إن الله، جل ثناؤه، … يوما يطهر أرضه بالنار\nكم مسلم عبد الهوى، فوجدته، … فيما يحل، كعاقد الزنار\nكذبوا أن ادعوا الهدى، فجميعهم … يسعون في تيه بغير منار\nفاهرب بدينك من أولئك، إنهم … حربوك واحتربوا على الدينار"},{"id":"diwan-maarri:603","bookId":"diwan-maarri","type":"poem","seq":603,"chapter":"قصائد","title":"يا شهب، إنك في السماء قديمة،","page":"","text":"يا شهب، إنك في السماء قديمة، … وأشرت للحكماء كل مشار\nأخبرت عن موت، يكون منجما، … أفتخبرين بحادث الإنشار؟\nمن للمملك تبع، أو قيصر، … لو كان مثل مليكك العشار\nوالدهر مفتن الغوائل، مهلك … رب الحسام، وحامل المئشار\nصمما حشا أذن الكميت، ودرهمي … كمه أحل بناظري بشار\nوالناس، في ضد الهدى، متشيع … لزم الغلو، وناصبي شاري\nبخل الأنام، فهل ترى من قائل … أفنى، عشاري الكوم، حسن عشار\nوكأن تعشير الغراب محدث … أن الخليط يحل في تعشار\nوالعمر مقسوم على الأكوان بالج … زء الأقل، وليس بالأعشار"},{"id":"diwan-maarri:604","bookId":"diwan-maarri","type":"poem","seq":604,"chapter":"قصائد","title":"كيف الرباح، وقد تألى ربنا","page":"","text":"كيف الرباح، وقد تألى ربنا … بالعصر، إن المرء حلف خسار\nوتقاسم الأيام من مرت به، … من أهلها، كتقاسم الأيسار\nهي سبعة مثل القداح، فوائز … متساويات في غنى ويسار\nمتشابهات ما اقتضين من الفتى … نفسا، فرام اللي بالإعسار\nومن العجائب أنني عان بها، … أرجو المنية أن تفك إساري\nوالموت يأخذ كل حين، باكر، … أو مظهر، أو رائح، أو ساري\nومن الجهات الست، لا هو طارق … من عن يميني، مرة، ويساري\nما يفخر الأسدي، بعد حمامه، … بنسور معركة ولا بنسار"},{"id":"diwan-maarri:605","bookId":"diwan-maarri","type":"poem","seq":605,"chapter":"قصائد","title":"يا أم دفر! إنما أكرمت عن","page":"","text":"يا أم دفر! إنما أكرمت عن … أمه، وحقك أن يقال دفار\nوإذا التثمت ظننت ذات نضارة؛ … ومتى سفرت قبحت في الإسفار\nغلب السفاه، فكم تلقب معشر … بالمؤمنين، وهم من الكفار\nومن البلية، أن يسمى، صادقا، … من وصفه الأولى كذوب فار\nطلب اللئيم من اللئام تحرما، … والخافرون أتوه بالإخفار\nورميت أعوامي ورائي، مثل ما … رمت المطي مهامه السفار\nوركبت منها أربعين مطية، … لم تخل من عنت وسوء نفار\nبذل الكريم عتائرا من سارح، … فأفاد من شكر عتائر فار\nحادث كتابك، فهو آمن جانبا، … من أهل تسبيد، وأهل وفار\nوفوائد الأسفار جمع السفر، في الد … نيا، تفوق فوائد الأسفار\nوالعيس تؤثر بالنضار، وتمتري … نضر المعيشة في فلا وجفار\nحست الظلام، فآض تعصره الضحى، … من بين أعطاف، لها، وذفار\nوالطرف، أجفره القضاء، فخصه، … بالرخص، ما فيه من الإجفار\nوالآل شخص الحي أين لقيته، … فكأنه، في المين، آل قفار\nشبح يعود إلى التراب، فينطوي، … كهشيم رغل، أو حطام صفار\nأين الخليط، لقد تأبد ربعه، … والحي أجمع حل في أحفار\nأمل تعلق بالنجوم، فلا تقل، … عند النعام، ولا مع الأغفار\nرمنا المآرب بالسفاه، ولم تكن … لتنال إلا بانتضاء شفار\nألقاك عن عفر، وجسمي بنية … عفرية، والزند غير عفار\nشذ التقي، فما يقاس على أبي … ذر، وشيمته رجال غفار\nأرأيت أسد الجزع، بعد فريسها، … تعتام بالأظفار جزع ظفار؟\nوالصبح قد غسل الدجى بمعينه، … إلا بقية إثمد الأشفار\nغفران ربك، قلما فعل الفتى … ما ليس محوجه إلى استغفار"},{"id":"diwan-maarri:606","bookId":"diwan-maarri","type":"poem","seq":606,"chapter":"قصائد","title":"الدهر يصمت، وهو أبلغ ناطق،","page":"","text":"الدهر يصمت، وهو أبلغ ناطق، … من موجز ندس، ومن ثرثار\nيمشي على قدمين، من ظلمائه … ونهاره، ما همتا بعثار\nضنت يداه، وتلك منه سجية، … أن تجريا أحدا على الإيثار\nوالعيش ضد القول، يحمد طوله، … ويذم هادي القوم في الإكثار\nوالسيل، إن بعث النبات من الثرى، … فله، بحظرك، سيىء الآثار\nقتلتكم الدنيا، فهل من قائم، … في أمكم، يرضي بمطلب ثار؟\nنوب تسور على ابن آدم خلتها … صيدا، حثثن على أغن مثار\nوإذا تقضت ساعة بلبانة، … فكأن فائتها لبون دثار"},{"id":"diwan-maarri:607","bookId":"diwan-maarri","type":"poem","seq":607,"chapter":"قصائد","title":"المرء يأبر خسة في طبعه،","page":"","text":"المرء يأبر خسة في طبعه، … ولرب صاحب منصل أبار\nوالحر، في أوطانه، متغرب، … فتظنه، في مصره، بوبار\nضلت يهود، وإنما توراتها … كذب من العلماء والأحبار\nقد أسندوا عن مثلهم، ثم اعتلوا، … فنموا بإسناد إلى الجبار\nوإذا غلبت مناضلا، عن دينه، … ألقى مقالده إلى الأخبار\nأقسام لفظك ستة، وجميعها … لا مين يلحقه سوى الإخبار\nمن خوف بارئك امتطيت نجيبة، … عادت بسيرك مثل قوس الباري\nفإذا وردت منى، فغايات المنى … ملقى جرائم، في الحياة، كبار\nكم أينق ينضو، الظلام، وجيفها، … وإلى تبار شفهن تباري\nقد صير الإنسان، في أحشائه، … قبرا لغانية عن الإقبار\nما جاد، من دمه المصون، بقطرة، … وأجاد وصف دمائها بجبار\nكم أعظم الأقوام خبا، وانبروا … يتمسحون، لأرضه، بجبار\nوالسهب، تغشاه السعود، فينثني … متقسما في السكن بالأشبار"},{"id":"diwan-maarri:608","bookId":"diwan-maarri","type":"poem","seq":608,"chapter":"قصائد","title":"يا رب لا أدعو لميس كما دعا","page":"","text":"يا رب لا أدعو لميس كما دعا … أوس، ولا دعوى زهير حار\nوالنفس لاجئة إلى جسد لها، … خلقت محاذرة من الإصحار\nوغدت محارات الحجيج إلى منى، … وكأنما ينظمن در محار\nيخبطن، في قيظ، سراب هواجر، … ويخلن فيه الروض بالأسحار"},{"id":"diwan-maarri:609","bookId":"diwan-maarri","type":"poem","seq":609,"chapter":"قصائد","title":"أفنوا الذخائر، فالقضاء مجهز","page":"","text":"أفنوا الذخائر، فالقضاء مجهز … أجناده، لخبيئة المذخار\nلا تسخرن، فما الزمان وأهله … إلا سراب تنوفة مسخار\nإفخرهم، ولو انهم ذهب صفا … ذهبوا، فكيف وهم من الفخار\nإن السماء تهذبت أنوارها، … وتخلفوا بالأرض شر بخار\nوالخير، قد يأتي أخيرا، مثل ما … أجناك ينع النخلة الميخار"},{"id":"diwan-maarri:610","bookId":"diwan-maarri","type":"poem","seq":610,"chapter":"قصائد","title":"الوغد يجعل ما أنيل غنيمة،","page":"","text":"الوغد يجعل ما أنيل غنيمة، … ويغير في الأطماع كل مغار\nوالحر يجزي، بالصنيعة، مسديا، … فكأن فعلهما نكاح شغار\nولكل ما أصبحت تدرك حسه … ضد، وكبرة من ترى كصغار\nشيع أجلت يوم خم، وانثنت … أخرى تعارضها بيوم الغار\nفاصغر لتعظم، كم تجمع واثب … ثم استعز، فعز بعد صغار"},{"id":"diwan-maarri:611","bookId":"diwan-maarri","type":"poem","seq":611,"chapter":"قصائد","title":"الدهر إن ينصرك ينصر، بعدها،","page":"","text":"الدهر إن ينصرك ينصر، بعدها، … ذا إحنة، فيحور كل محار\nوهواجر الأيام يسلب حرها … ما أودعته ذواهب الأسحار"},{"id":"diwan-maarri:612","bookId":"diwan-maarri","type":"poem","seq":612,"chapter":"قصائد","title":"صل القبائل بالفخار، وإنما","page":"","text":"صل القبائل بالفخار، وإنما … خلقوا من الصلصال كالفخار\nوسيوجد الغدري عظما ناخرا، … فتقل رغبته إلى النخار\nفعليك بالتقوى، ذخيرة ظاعن؛ … إن التقية أفضل الأذخار\nآل الفتى، كالآل، فوق ترابه، … وشرابه كسرابه السخار"},{"id":"diwan-maarri:613","bookId":"diwan-maarri","type":"poem","seq":613,"chapter":"قصائد","title":"الناس بالأقدار نالوا كل ما","page":"","text":"الناس بالأقدار نالوا كل ما … رزقوا، ولم يعطوا على الأقدار\nوالسر يظهره الفؤاد، ودونه … ستران من صدر له، وصدار\nوالنخل يجنى حين يرطب زهوه؛ … والبدر يكسف ليلة الإبدار\nكاس له حلل، وعار، من له، … لو بات، يستر شخصه بجدار\nلا ييأسن من الثواب مراقب … لله في الإيراد والإصدار\nفترى بدائع، أنبأت متحسسا … إن الجزاء بغير هذي الدار"},{"id":"diwan-maarri:614","bookId":"diwan-maarri","type":"poem","seq":614,"chapter":"قصائد","title":"يعرى اللئيم من الثناء، ويكتسي","page":"","text":"يعرى اللئيم من الثناء، ويكتسي … حلل النواسج، فهو كاس عار\nوالدهر لم يشعر بما هو كائن … فيه، فكيف يذم في الأشعار؟\nما استرجعت هبة الحياة من الفتى، … بل كان ما يعطاه رد معار"},{"id":"diwan-maarri:615","bookId":"diwan-maarri","type":"poem","seq":615,"chapter":"قصائد","title":"عاين أواخر كائن بأوائل؛","page":"","text":"عاين أواخر كائن بأوائل؛ … إن الهلال يحق بالإبدار\nوالليل يؤذن بالصباح، فإن ترم … فيه سراك، لحاجة، فبدار\nأرجوت أن تعطى اختيارك، والفتى … يغدو على شمس من الأقدار\nوأرى العروس تحجبت، في خدرها، … كمعرس الآساد في الأخدار\nأحسن جوارا للفتاة، وعدها … أخت السماك على دنو الدار\nكتجاور العينين لن تتلاقيا، … وحجاز بينهما قصير جدار\nوالحي دار بالذي هو حادث، … وله من الأمل المضلل دار\nيسعى الحريص، وما القضاء بغافل … عن رب إيراد، ولا إصدار\nكم نعمة لله يحسبها امرؤ … بالشحط، وهي قريبة المزدار"},{"id":"diwan-maarri:616","bookId":"diwan-maarri","type":"poem","seq":616,"chapter":"قصائد","title":"إن نال، من مصر، قضاء نازل،","page":"","text":"إن نال، من مصر، قضاء نازل، … فمصير هذا الخلق شر مصير\nوالدهر قص قنا جذيمة، في الوغى، … وعصاه تنضو الخيل تحت قصير\nورمى حذيفة، من شذاه، بمروة، … وسطا على مروان في بوصير\nيدعى الفتى المنصور، وهو مسلم … للحتف، لا يدعو له بنصير\nيلفى الحصير من الملوك معفرا، … لم يوق من وجه الثرى بحصير\nقصرت عن رتب الكرام، لأنني … في عالم جبلوا على التقصير\nوقد ادعى، بصر الغراب، الخلد في … ظلماء، ليس غرابها ببصير\nوالمرء فيه بصيرة مخبوءة، … ليست بغانية عن التبصير"},{"id":"diwan-maarri:617","bookId":"diwan-maarri","type":"poem","seq":617,"chapter":"قصائد","title":"استحي من شمس النهار، ومن","page":"","text":"استحي من شمس النهار، ومن … قمر الدجى، ونجومه الزهر\nيجرين في الفلك المدار، بإذ … ن الله، لا يخشين من بهر\nولهن بالتعظيم، في خلدي، … أولى وأجدر من بني فهر\nسبحان خالقهن، لست أقو … ل: الشهب كابية مع الدهر\nلا بل أفكر: هل رزقن حجى … نجسا يمزن به من الطهر\nأم هل لأنثاها الحصان، بذي الت … ذكير، من قربى ومن صهر\nأم يخطب، العوا، السماك، ويع … طيها الذي ترضاه من مهر\nأما الهلال، فإنه عجب … ينمي ويمحق في مدى شهر\nفبرئت من غاو، أخي سفه، … متمرد في السر والجهر\nألغى صلاة العصر، محتقرا، … ورمى، وراء الظهر، بالظهر\nفامنح ضعيفك، إن عراك، ولو … نزرا، ولا تصرفه بالكهر\nوارفع له شقراء، ترمح في … دهماء، مثل تأرن المهر\nوانصف يتيمك في التراث، ولا … تأخذه بالإعنات والقهر"},{"id":"diwan-maarri:618","bookId":"diwan-maarri","type":"poem","seq":618,"chapter":"قصائد","title":"ما راعت البرة في بذرها؛","page":"","text":"ما راعت البرة في بذرها؛ … فنهنه الأدمع أو أذرها\nزوجة إبراهيم سارت إلى … مقام إبراهيم، في نذرها\nعصته، في ذاك، ولم تعتذر، … وجرمها أيسر من عذرها\nتهذر في النسك، ولم تعتذر، … وصمتها أبلغ من هذرها\nلعل خيرا منك، في دينها، … آخذة الدينار في جذرها\nوإنما تحمد ردانة، … باتت، من الله، على خدرها"},{"id":"diwan-maarri:619","bookId":"diwan-maarri","type":"poem","seq":619,"chapter":"قصائد","title":"قومي إلى ربك مختارة،","page":"","text":"قومي إلى ربك مختارة، … بغير زنار وزنار\nشرفني الله، ولا آ … مل الجنة، بل عتقا من النار\nما قيمتي فلس، وفي حكم … ه أني أودى ألف دينار"},{"id":"diwan-maarri:620","bookId":"diwan-maarri","type":"poem","seq":620,"chapter":"قصائد","title":"هي طرق: فمن ظهور، وأرحا","page":"","text":"هي طرق: فمن ظهور، وأرحا … م، ودنيا أتت بظلم وقمر\nكنت طفلا في المهد، والآن لا أه … وى رجوعا إليه، فاعجب لأمري\nولعلي كذاك في داري الأخ … رى، إذا ما ادكرت ريق عمري\nطال مني تحمل، خلت أني … قابض، من أذاته، فوق جمر\nكم أعاني، للدهر، بيضا وسودا، … بين خضر، من السنين، وحمر\nكيف لي بالفلاة تنضي المطايا … بضمير، يكسو جلابيب ضمر\nبنوى تمري، الذي غذيته، … لنواها، التي من البعد تمري\nزمرت ربدها، وغنت بها الور … ق، ولا حوب في غناء وزمر\nإلزم الصمت، إن أردت نجاة، … ليس ضحضاح منطق مثل غمر\nلفظة قلتها، وإن هي هانت، … جاوزت، في الأنام، حسوة خمر\nتنفد الوقت غير جالب نفع، … خائضا في حديث زيد وعمرو"},{"id":"diwan-maarri:621","bookId":"diwan-maarri","type":"poem","seq":621,"chapter":"قصائد","title":"ما مقامي إلا إقامة عان؛","page":"","text":"ما مقامي إلا إقامة عان؛ … كيف أسري، وفي يد الدهر أسري؟\nويسار الفتى يمين، وإن كا … ن أشلا، سام الأمور بيسر\nتبعت تبعا، وفي القصر غالت … قيصرا، وانتحت لكسرى بكسر\nوطوت طيئا، وآدت إيادا، … وأصابت ملوك قسر بقسر\nإن جسرا على المنية حزم، … والبرايا، من عبشة، فوق جسر\nولقابوس كان قبس، وفنا … خسر أروته من فناء وخسر\nوكذاك النعمان زال نعيم … عن ذراه، والعود رهن بحسر\nسوف ألقى من الزمان، كما لا … قوا بعنف، لا يستقال، ودسر\nولو اني السهى، أو النسر قد شا … هدت عصرين من يغوث ونسر"},{"id":"diwan-maarri:622","bookId":"diwan-maarri","type":"poem","seq":622,"chapter":"قصائد","title":"إختلاف قد عمنا في اعتقاد،","page":"","text":"إختلاف قد عمنا في اعتقاد، … وصلاة لربنا، وطهور\nونساء ممهورة في البرايا؛ … وسبايا سيقت بغير مهور\nورأيت الحمام يأتي، على العا … لم، من قاهر ومن مقهور\nوادعوا للمعمرين أمورا، … لست أدري ما هن في المشهور\nأتراهم، فيما تقضى من الأي … ام، عدوا سنيهم بالشهور\nكلما لاح، للعيون، هلال، … كان حولا، لديهم، في الدهور\nهكذا ينبغي وإلا، فإن ال … عقل يثنى في حالة المبهور\nحملوا المثقلات، ثمت أضحى، … في بطون الأجداث، بالي الظهور"},{"id":"diwan-maarri:623","bookId":"diwan-maarri","type":"poem","seq":623,"chapter":"قصائد","title":"ذكرتني عقوبة من إلهي،","page":"","text":"ذكرتني عقوبة من إلهي، … فاستطير الفواد للتذكير\nفكري أنت، ربما هدي الإن … سان، للمشكلات، بالتفكير\nما الذي نستفيد، في هذه الدن … يا، بطول الرواح والتبكير؟\nشجر العيش معدن للرزايا، … أودت الطير فيه بالتوكير\nكلنا غادر، يميل إلى الظل، … م، وصفو الأيام للتعكير\nورجال الأنام مثل الغواني، … غير فرق التأنيث والتذكير\nعرفتني، حتى شهرت، الليالي، … ثم صالت علي بالتنكير\nفاحسبيني كفضة هذبت، في … كل عصر، بمس نار وكير\nخلصيني من ضنك ما أنا فيه؛ … واطرحيني لمنكر ونكير\nواحذري من أخيك والأب والأم … وشدي الرتاج بالتسكير"},{"id":"diwan-maarri:624","bookId":"diwan-maarri","type":"poem","seq":624,"chapter":"قصائد","title":"فكروا في الأمور يكشف لكم بع","page":"","text":"فكروا في الأمور يكشف لكم بع … ض الذي تجهلون بالتفكير\nلو درى الطائر الموكر بالعقبى، … أبى أن يهم بالتوكير\nحرق الهند من يموت، فما زا … دوه في روحة، ولا تبكير\nواستراحوا من ضغطة القبر، ميتا، … وسؤال لمنكر ونكير\nلا ذكور ولا إناث من العا … لم يهدى، للرشد، بالتذكير"},{"id":"diwan-maarri:625","bookId":"diwan-maarri","type":"poem","seq":625,"chapter":"قصائد","title":"إلى م أجر قيود الحياة،","page":"","text":"إلى م أجر قيود الحياة، … ولا بد من فك هذا الإسار\nودنياي، إن وهبت، باليمين، … يسار الفتى، أخذت باليسار\nفلا تغبطن بعض خدامها، … فكلهم دائب في خسار\nقدمنا إليها، على رغمنا، … ونخرج، من ضنكها، باقتسار\nفلا تأمنن! إن وفد الحمام … غاد، على مهج القوم، سار\nفتى يتنادى: حناني الزمان؛ … وما بعد ذلك إلا انكسار\nفطورا تجيش غمار المياه؛ … وطورا تصادف ذات انحسار\nوما جهل الحي، من عامر، … سرور النسور بقتلى النسار"},{"id":"diwan-maarri:626","bookId":"diwan-maarri","type":"poem","seq":626,"chapter":"قصائد","title":"تعود، إلى الأرض، أجسادنا،","page":"","text":"تعود، إلى الأرض، أجسادنا، … ونلحق بالعنصر الطاهر\nويقضي بنا، فرضه، ناسك، … يمر اليدين على الظاهر"},{"id":"diwan-maarri:627","bookId":"diwan-maarri","type":"poem","seq":627,"chapter":"قصائد","title":"لئن سقتك الليالي مرة ضربا،","page":"","text":"لئن سقتك الليالي مرة ضربا، … فكم سقتك على مر الزمان مقر\nإن المشقر لم تخلد ممالكه، … شقر تقاد، ولا مسحوبة كشقر\nوإنما هذه الدنيا لنا تلف، … إذا الفقير تصدى لليسار فقر\nفأذر دمعك، إن جهالها ابتسموا … من جهلهم، وإذا خف الأنام فقر\nواهرب من الناس، ما في قربهم شرف؛ … إن الفنيق إذا دانى الأنيس عقر\nوالصقر يلبس، إن طال المدى، هرما، … حتى إذا مر بين الهاتفات تفر\nلو عاشت الشمس فينا ألبست ظلما، … أو حاول البدر منا حاجة لحقر\nولدت يا أم طفلا شب في عنت، … فليت كشحك، عن ذاك الجنين، بقر\nلتستريحا، فكم عانى أذى قرس، … عند الشتاء، ولاقى وغرة، فصقر\nفلا تقر بمجد لامرىء أبدا، … إن كنت، بالله رب النيرات، تقر"},{"id":"diwan-maarri:628","bookId":"diwan-maarri","type":"poem","seq":628,"chapter":"قصائد","title":"عش مجبرا، أو غير مجبر،","page":"","text":"عش مجبرا، أو غير مجبر، … فالخلق مربوب مدبر\nوالخير يهمس بينهم، … ويقام للسوآت منبر\nفاخش البرية كلها؛ … إني بها أدرى وأخبر\nوإذا افتقرت فلا تهن؛ … وإذا غنيت فلا تجبر\nوالحي، إن يعط البقاء، … فإنه يفنى ويكبر\nويصير ما قضى، من ال … أيام، أحلاما تعبر\nوالله صغرنا، فمن … يبغ العلا يصرف ويثبر\nمثل الحميا، والثريا، … واللجين بلا مكبر\nوالعود أحمد في الجميل، … فإن تشب فالعود أصبر\nلو كنت كالبدر المنير، … أو الغزالة، وهي أكبر\nلعلمت أني للثرى … أدعى، وأني فيه أقبر\nوإذا عملت لما يزو … ل، فذلك العمل المتبر\nمن قبلنا سعت السعاة … لرهط وثاب بن جعبر\nجمعوا له من كل أو … ب، واجتنى النخل المؤبر\nلعب الولائد بالسبا … ئك، واطرحن بنات أوبر\nوالعنبرية لا تبالي، … أن تعيش بغير عنبر\nلا يفخرن الهاشمي … على امرىء من آل بربر\nفالحق يحلف: ما علي … عنده إلا كقنبر\nإن شاء من خلق السما … ك أعاشني، فنهضت أغبر\nعجلان أنفض لمتي، … لتحد أعمالي وتسبر"},{"id":"diwan-maarri:629","bookId":"diwan-maarri","type":"poem","seq":629,"chapter":"قصائد","title":"إدفع الشر، إذا جاء، بشر،","page":"","text":"إدفع الشر، إذا جاء، بشر، … وتواضع، إنما أنت بشر\nيا غرابا همه في غارة، … يتمنى أقطا فوق مشر\nنحن في ليل علينا دامس، … كيف للمدلج بالصبح جشر\nهذه الأجسام ترب هامد، … فمن الجهل افتخار وأشر\nجسد من أربع تلحظها، … سبعة راتبة في اثني عشر\nوعجيب فرح النفس، إذا … شاع في الأرض ثناها وانتشر\nشجر أفضله مثمره، … ومن الناس نخيل وعشر\nمستشار خائن في نصحه، … وأمين ناصح لم يستشر\nومتى شاء الذي صورنا، … أشعر الميت نشورا، فنشر\nفافعل الخير وأمل غبه، … فهو الذخر إذا الله حشر"},{"id":"diwan-maarri:630","bookId":"diwan-maarri","type":"poem","seq":630,"chapter":"قصائد","title":"رحت في الناس، كربع دارس،","page":"","text":"رحت في الناس، كربع دارس، … أخذت منه رياح ومطر\nخبأ الدجن، لأرض، جوده، … وطوى أرضي، بخيلا، ما قطر\nمستطار أنا من خوف الردى، … كل شيء في كتاب مستطر\nغفر الله لعبد غافل، … هو في أعظم جهل وخطر\nترك الآجل لم يحفل به، … ومن العاجل لم يقض الوطر\nحكم الرب لبدر، فاستوى، … وهلال مستجد، فانأطر\nتظهر الدين، وتخفي غيره؛ … إنما شأنك مكر وبطر"},{"id":"diwan-maarri:631","bookId":"diwan-maarri","type":"poem","seq":631,"chapter":"قصائد","title":"أمر الخالق، فاقبل ما أمر؛","page":"","text":"أمر الخالق، فاقبل ما أمر؛ … واشكر الله إن العذب أمر\nأضمر الخيفة، واضمر، قلما … أحرز الطرف المدى حتى ضمر\nأيها الملحد لا تعص النهى، … فلقد صح قياس، واستمر\nإن تعد، في الجسم يوما، روحه، … فهو كالربع خلا ثم عمر\nوهي الدنيا، أذاها أبدا، … زمر واردة إثر زمر\nيا أبا السبطين لا تحفل بها، … أعتيق، ساد فيها، أم عمر\nعجبا للدهر! صبح، ودجى، … ونجوم، وهلال، وقمر\nوغصون أثمرت نائية، … ودوان ليس فيهن ثمر\nوغوي كر في حيرته، … بعدما حج لنسك، واعتمر\nعام في الغمر زمانا، فنجا، … وانثنى الآن غريقا في الغمر\nزحلي واجم، يصحبه … زهري الطبع، غنى وزمر\nوهموم ألفت مقمورها؛ … وسرور آبه حين قمر\nتلك أنباء أرتنا عبرا … معجبات، كأحاديث السمر\nفي حياة كخيال طارق، … شغل الفكر، وخلاك ومر"},{"id":"diwan-maarri:632","bookId":"diwan-maarri","type":"poem","seq":632,"chapter":"قصائد","title":"قصر اليوم بكأس، كاس من","page":"","text":"قصر اليوم بكأس، كاس من … صد عنها، وانبرى لا يقتصر\nتلك نار الغي، من يصطلها … يحترق بالدفء، في الوقت الخصر\nولهذي الراح ريح عصفت … بهشيم اللب، في ريح وصر\nلؤمت كرميه تشربها، … ونداماك حصور وحصر\nألوين الليل تمري قهوة، … وملاحي الثريا تعتصر؟\nأيصر الخمر، في أخلافها، … حالب يحتلب الغاوي المصر؟\nعش نقي العرض، أن تتركها، … وإذا مت، فللرحمة صر\nحج، من غير تقى، صاحبنا، … كأخي بحتر عام المنتصر"},{"id":"diwan-maarri:633","bookId":"diwan-maarri","type":"poem","seq":633,"chapter":"قصائد","title":"لو كنت كالرائش، أو ذي المنار،","page":"","text":"لو كنت كالرائش، أو ذي المنار، … لعشت في الدنيا كثير الشنار\nوليتها لم يك، من بعدها، … خوف حساب وعقاب بنار"},{"id":"diwan-maarri:634","bookId":"diwan-maarri","type":"poem","seq":634,"chapter":"قصائد","title":"لا تعذلاني، فالذي أبتغي،","page":"","text":"لا تعذلاني، فالذي أبتغي، … من هذه الدنيا، حقير يسير\nبت أسيرا في يدي برهة، … تسير بي وقتي، إذ لا أسير\nكطائر قيل: ألا تغتدي؟ … فقال: أنى وجناحي كسير؟"},{"id":"diwan-maarri:635","bookId":"diwan-maarri","type":"poem","seq":635,"chapter":"قصائد","title":"ما لمت، في أفعاله، صالحا،","page":"","text":"ما لمت، في أفعاله، صالحا، … بل خلته أحسن مني ضمير\nيا قوم! لو كنت أميرا لكم … ذممتم، في الغيب، ذاك الأمير\nوإنما سائسكم دائب، ير … عى المطايا، ويسوق الحمير\nوابن جمير، فوقكم عاتم، … فهل سمعتم بأبيه جمير؟\nوردتم الآجن من دينكم، … وما ظفرتم بالصريح النمير\nعالمكم يضرب في غمرة، … كالعلج، بالقفر، يلس الغمير\nفعرفوني بفتى منكم، … لا يمتري الناس، ولكن يمير\nسامرتكم دهرا، وفارقتكم، … عن هجرة ما سمر ابنا سمير\nإن أقمر الليل، على وفدكم، … وجدتكم من قمر أو قمير"},{"id":"diwan-maarri:636","bookId":"diwan-maarri","type":"poem","seq":636,"chapter":"قصائد","title":"لزينب يحلو جني أمر،","page":"","text":"لزينب يحلو جني أمر، … وقد علقت كفها بالقمر\nفيا أفق! من أين تلك النجوم؛ … ويا غرس! من أين ذاك الثمر؟\nويا صاح! كيف لنا بالممات، … على ما نهى ربنا أو أمر؟\nفهل علم البدر والطالعات، … وهنا، بأنباء هذا السمر؟\nتبارك خالقنا، في البلاد، … وما زال عنا بعلم خمر\nيعود أخوك إلى غيه، … وإن حج، من نسكه، واعتمر\nوخالفك الناس في مذهب، … فقلت: علي، وقالوا: عمر\nوأنى يرجون غمر الهدى، … وقد غرقوا في جمام الغمر؟\nيساء الغبين بما ناله، … ويفرح، من جهله، من قمر\nأتدعى، بغير تقاك، التقي، … وليس الطمر سوى ما طمر؟\nفبت ضامرا لطلاب الثناء، … فما سبق الطرف حتى ضمر\nومن يفتكر في صنيع الأنام، … يبصر، إذا ضل، إحدى الأمر\nولو لم يكن، في قضاء المليك، … ما نحن في ضبنه، ما استمر"},{"id":"diwan-maarri:637","bookId":"diwan-maarri","type":"poem","seq":637,"chapter":"قصائد","title":"مساجدكم ومواخيركم،","page":"","text":"مساجدكم ومواخيركم، … سواء، فبعدا لكم من بشر!\nوما أنتم بالنبات الحميد، … ولا بالنخيل ولا بالعشر\nولكن قتاد عديم الجناة، … كثير الأذاة، أبى غير شر\nوليلكم أبدا مظلم، … فهل ترقبون صباحا جشر؟\nفيا ليتني في الثرى، لا أقوم … إن الله ناداكم، أو حشر\nوما سرني أنني في الحياة، … وإن بان لي شرف وانتشر\nأرى أربعا آزرت سبعة، … وتلك نوازل في اثني عشر"},{"id":"diwan-maarri:638","bookId":"diwan-maarri","type":"poem","seq":638,"chapter":"قصائد","title":"عجبت لطير، بلطف المليك،","page":"","text":"عجبت لطير، بلطف المليك، … مخلوقة لصلاح الثمر\nتثقبه، مولعات به، … ولو لم تزره تهاوى، فمر\nتحل محلا لها ثانيا، … وتترك منزلها قد دمر"},{"id":"diwan-maarri:639","bookId":"diwan-maarri","type":"poem","seq":639,"chapter":"قصائد","title":"لعمري! لقد طال هذا السفر","page":"","text":"لعمري! لقد طال هذا السفر … علي، وأصبحت أحدو النفر\nأأخرج من تحت هذي السماء؟ … فكيف الإباق، وأين المفر؟\nوكم عشت من سنة، في الزمان، … وجاوزت من رجب، أو صفر\nوما جعلت، لأسود العرين، … أظافير، إلا ابتغاء الظفر\nلحا الله قوما، إذا جئتهم … بصدق الأحاديث، قالوا: كفر\nوإن غفرت موبقات الذنوب، … فكل مصائبهم تغتفر\nوروح الفتى أشبهت طائرا … أطير، فما عاد لما نفر\nهنيئا لجسمي، إذا ما استقر، … وصار لعنصره في العفر\nولست أبالي، إذا ما بليت، … من وطىء القبر، أو من حفر\nتحجب دنياك عن طالب، … وليس تحجبها من خفر"},{"id":"diwan-maarri:640","bookId":"diwan-maarri","type":"poem","seq":640,"chapter":"قصائد","title":"وجدت الأنام على خطة،","page":"","text":"وجدت الأنام على خطة، … نهارهم كالظلام اعتكر\nفلا يزهدنك، في العارفات، … أن الذي نالها ما شكر\nوقد شرب الدهر صفو الأنام، … فلم يبق، في الأرض، إلا العكر\nوما، عند خلك، غير النفاق؛ … وما خلته ناسيا، فادكر\nأرى سنة، وهو في حيلة، … ولم يغف حقا، ولكن مكر\nتفكر، فقد حار هذا الدليل، … وما يكشف النهج غير الفكر\nفيا ليتني حجر، لا يحس، … بالخطب، أو طائر ما احتكر\nإذا ما أنار صباح غدا؛ … وإن جن ليل عليه وكر\nفذكر أخاك بإحسانه، … فقد راح في غفلة، وابتكر"},{"id":"diwan-maarri:641","bookId":"diwan-maarri","type":"poem","seq":641,"chapter":"قصائد","title":"فقدت البحور وأهل الوفاء،","page":"","text":"فقدت البحور وأهل الوفاء، … وأصبحت في غدر كالغدر\nوما زال يردؤ ذاك الجواد، … حتى أبر عليه الكدر\nتعود الجسوم إلى عنصر … به مدرت، في الحياض، المدر\nيشق الحريص على نفسه، … ويطلب من عيشه أن يدر\nويأتي، الفتى، رزقه وادعا، … ولو كان في النيق عند الفدر\nفلا تغبطن ذوي نعمة، … فإن المنايا غضاب هدر\nولو عوضوا عنبرا عن برى، … وبدل، يوما، حصاهم بدر\nجرى خلف، وادعى المدعون: … إنا على ما أردنا قدر\nوقالت معاشر: لا نستطيع، … بل نحن مثل الربى والجدر\nوكل يؤمل صفو الحياة، … وذلك في فلك لم يدر"},{"id":"diwan-maarri:642","bookId":"diwan-maarri","type":"poem","seq":642,"chapter":"قصائد","title":"إذا عثر القوم، فاغفر لهم،","page":"","text":"إذا عثر القوم، فاغفر لهم، … فأقدام كل فريق عثر\nوإن دثر القلب، فأسف له، … ولا تبكينك ربوع دثر\nلو ان القبيح له جثة، … وحمله بازل، لم يثر\nإذا كثر الناس شاع الفسا … د، كما فسد القول لما كثر\nوذلك لو أكلته السباع … لعادت ذوات نفوس خثر\nله أثر، كجروح السيوف، … ولا أثر يصحب منه الأثر"},{"id":"diwan-maarri:643","bookId":"diwan-maarri","type":"poem","seq":643,"chapter":"قصائد","title":"أغارت عليهم خيول الزمان،","page":"","text":"أغارت عليهم خيول الزمان، … كأن خيولهم لم تغر\nوقد كان يركبها طفلهم، … حليف الرضاع، ولم يتغر\nومن يدفع القدر الأولي، … إذا فمه لأكيل فغر؟\nلقد غرني أمل في الحياة، … كأني بما يفعل الدهر غر"},{"id":"diwan-maarri:644","bookId":"diwan-maarri","type":"poem","seq":644,"chapter":"قصائد","title":"تحفظ بدينك يا ناسكا،","page":"","text":"تحفظ بدينك يا ناسكا، … يرى أنه رابح، ما خسر\nفلست كغيرك، أطلقت في … حياتك، بل أنت عان أسر\nوللسبك رد كسير الزجاج، … ولا يسبك الدر إن ينكسر\nورزقك يأتي، بلا ريبة، … فسر في بلادك، أو لا تسر\nولا تيأسن من الملك أن … يعود، إذا جيش قوم كسر\nفقد يرجع القمر المستنير … مقتبلا، بعد أن يستسر\nهو الدهر يفنى، ونفسي على … وناها، وكون مناها عسر\nوكم فيك يا بحر من لؤلؤ، … ولكن لجك لا ينحسر\nفأكره، على الخير، مجبولة … على غيره، في علان وسر\nفلم يجعل التبر حلي الفتاة، … حتى أهين، وحتى كسر"},{"id":"diwan-maarri:645","bookId":"diwan-maarri","type":"poem","seq":645,"chapter":"قصائد","title":"أرى الشهد يرجع مثل الصبر؛","page":"","text":"أرى الشهد يرجع مثل الصبر؛ … فما لابن آدم لا يعتبر؟\nوخبره صادق بالحديث، … فإن شك، في ذاك، فليختبر\nوجبر وكسر له في الزمان، … ويكسر يوما فلا ينجبر\nفلا تبر في مأثم ناقة، … فربك إما يعاقب يبر\nوكل الأنام هجين الفعال، … فأين يصاب الجواد المبر؟\nونفسك عق بترك الس … رور، فإن عقوقك للنفس بر\nسألنا المعاشر عن خيرهم، … فقالوا، بغير اكتراث: قبر\nفقلنا: وكيف أتاه الحمام، … عاجله بغتة أم صبر؟\nفقالوا: تمادى به وقته، … وأدركه الموت لما كبر\nوغادر، في أهله، ثروة، … ومالا أذيع، ونخلا أبر\nفلا يسقط الدمع سقط اللوى؛ … ولا تدكر حبرة في حبر\nولكنني أستعين المليك، … وإن يأتني حادث أصطبر\nودنياي ألقى بطول الهوان، … وهل هي إلا كجسر عبر؟"},{"id":"diwan-maarri:646","bookId":"diwan-maarri","type":"poem","seq":646,"chapter":"قصائد","title":"أبيتم سوى مين وخلف وغلظة،","page":"","text":"أبيتم سوى مين وخلف وغلظة، … فليس لوعد، في الجميل، نجوز\nوإن الذي تحكون ليس بجائز، … ولكن سواه، في القياس، يجوز"},{"id":"diwan-maarri:647","bookId":"diwan-maarri","type":"poem","seq":647,"chapter":"قصائد","title":"لا تمسين، على من مات، ملتهفا،","page":"","text":"لا تمسين، على من مات، ملتهفا، … فالناشئات، إذا طال المدى، عجز\nقصرت أن تدرك العلياء في شرف، … إن القصائد لم يلحق بها الرجز\nأما الحجاز، فما يرجى المقام به، … لأنه بالحرار الخمس محتجز\nوالشام، فيه وقود الحرب مشتعل، … يشبه القوم، شدت منهم الحجز\nوبالعراق وميض يستهل دما، … وراعد، بلقاء الشر، يرتجز\nوآخر الدهر يلفى مثل أوله، … والصدر يأتي، على مقداره، العجز\nفجهزيني، لحاك الله والدة، … علي أتبع أصحابي، فأنتجز"},{"id":"diwan-maarri:648","bookId":"diwan-maarri","type":"poem","seq":648,"chapter":"قصائد","title":"تجنب الوعد يوما أن تفوه به،","page":"","text":"تجنب الوعد يوما أن تفوه به، … فإن وعدت، فلا يذممك إنجاز\nواصمت، فإن كلام المرء يهلكه؛ … وإن نطقت، فإفصاح وإيجاز\nوإن عجزت عن الخيرات تفعلها، … فلا يكن، دون ترك الشر، إعجاز"},{"id":"diwan-maarri:649","bookId":"diwan-maarri","type":"poem","seq":649,"chapter":"قصائد","title":"أردت إهانتي، فحماك مني،","page":"","text":"أردت إهانتي، فحماك مني، … قضاء في، كان له نجوز\nوجدتني اللجين، أو الثريا، … وتصغير المصغر لا يجوز\nأرى الفتيان والفتيات، جمعا، … أصابتهم بشرتها العجوز"},{"id":"diwan-maarri:650","bookId":"diwan-maarri","type":"poem","seq":650,"chapter":"قصائد","title":"لحاك الله، يا دنيا، خلوبا؛","page":"","text":"لحاك الله، يا دنيا، خلوبا؛ … فأنت الغادة البكر العجوز\nوجدناك الطريق إلى المنايا، … وقد طال المدى فمتى نجوز؟\nسئمنا من أذاك، فنجزينا، … فإن مروءة الوعد النجوز"},{"id":"diwan-maarri:651","bookId":"diwan-maarri","type":"poem","seq":651,"chapter":"قصائد","title":"أجاز الشافعي فعال شيء،","page":"","text":"أجاز الشافعي فعال شيء، … وقال أبو حنيفة لا يجوز\nفضل الشيب والشبان منا، … وما اهتدت الفتاة ولا العجوز\nلقد نزل الفقيه بدار قوم، … فكان لأمره فيهم نجوز\nولم آمن على الفقهاء حبسا، … إذا ما قيل للأمناء جوزوا"},{"id":"diwan-maarri:652","bookId":"diwan-maarri","type":"poem","seq":652,"chapter":"قصائد","title":"أرى الخير، في عمري، حسرة،","page":"","text":"أرى الخير، في عمري، حسرة، … لأني، عن فعله، عاجز\nإذا رمته مرة، في الزمان، … رجعت، ولي دونه حاجز\nيماطل جد أخا حاجة، … له أجل بالردى ناجز\nولم أرق في درجات الكريم؛ … وهل يبلغ الشاعر الراجز؟"},{"id":"diwan-maarri:653","bookId":"diwan-maarri","type":"poem","seq":653,"chapter":"قصائد","title":"إن راز عاذلك الرازي، مختبرا،","page":"","text":"إن راز عاذلك الرازي، مختبرا، … أو الحجازي، لم يعجبه مارازا\nوالخلق شتى، ولكن ضمهم خلق، … للشر، لم يلق بين الناس إفرازا\nوالملك لله، ما الأجراز ممرعة، … بحمل قومك، أسيافا وأجرازا\nما لي أرى شرك الساعات قد وصلت … وصل الأديم، فما يحتجن خرازا\nوخان، خانا، زمان ما وفى لفتى، … وليس يغفل عن قيل بشيرازا\nلا تصغين إلى حاز لتسمعه، … فما يطيق لما أخفيت إبرازا\nأراد إحراز قوت كيف أمكنه، … فظل يكتب للنسوان أحرازا"},{"id":"diwan-maarri:654","bookId":"diwan-maarri","type":"poem","seq":654,"chapter":"قصائد","title":"الناس مختلفون، قيل: المرء لا","page":"","text":"الناس مختلفون، قيل: المرء لا … يجزى على عمل، وقيل: يجازا\nوالله حق، من تدبر أمره … عرف اليقين، وآنس الإعجازا\nرجزت، بتسبيح المليك، حمامة … بالشام، توطن، أو تحل حجازا\nوالطير مثل الإنس تعرف ربها، … وترى بها الشعراء، والرجازا\nفيهن مسهاب، يعد، وناطق … ترك المقال، وآثر الإيجازا\nفاسأل حجاك، إذا أردت هداية، … واحبس لسانك أن يقول مجازا\nلا ترض وعدا، إن قدرت على ندى، … وإذا وعدت، فيسر الإنجازا\nجاءتك أعناق الأمور بواديا، … ولقد لمحت بلبك الأعجازا"},{"id":"diwan-maarri:655","bookId":"diwan-maarri","type":"poem","seq":655,"chapter":"قصائد","title":"يا أم دفر لو رحلت عن الورى","page":"","text":"يا أم دفر لو رحلت عن الورى … كسروا، ولو من آل ضبة، كوزا\nإني ذممتك، فاشهري، أو أشرعي، … لا أرهب المعمود والمركوزا\nعشت السليم، وما عنيت سلامة، … لكن بسمك مرهقا، منكوزا\nموسى بعثت لكل حي معضبا، … فقضى عليه معجلا موكوزا"},{"id":"diwan-maarri:656","bookId":"diwan-maarri","type":"poem","seq":656,"chapter":"قصائد","title":"غدا ابن عجوز لها مائرا،","page":"","text":"غدا ابن عجوز لها مائرا، … فقد صادف ابنة ظل عجوزا\nأجازت عليه بنات لها، … وعاقت ركائبه أن تجوزا"},{"id":"diwan-maarri:657","bookId":"diwan-maarri","type":"poem","seq":657,"chapter":"قصائد","title":"توخي جميلا، وافعليه لحسنه،","page":"","text":"توخي جميلا، وافعليه لحسنه، … ولا تحكمي أن المليك به يجزي\nفذاك إليه: إن أراد فملكه … عظيم، وإلا فالحمام لنا مجز\nوكنت كنار، في الشباب، شبيبة، … فصرت عجوزا تنسبين إلى العجز\nفإن الذي تهوين، من رتبة الرضا، … يسير لدى ما تتقين من الرجز"},{"id":"diwan-maarri:658","bookId":"diwan-maarri","type":"poem","seq":658,"chapter":"قصائد","title":"تماطل أمرا دونه أبعد النوى،","page":"","text":"تماطل أمرا دونه أبعد النوى، … فبادر، إذا رعت البعيد وناجز\nأردت إلى أرض الحجاز تحملا، … فعاقتك عنه عائقات الحواجز\nعجزت عن الكسب الذي يجلب الغنى، … وما أنت عن كسب الدنايا بعاجز\nومن لم ينل، في القول، رتبة شاعر، … تقنع في نظم برتبة راجز"},{"id":"diwan-maarri:659","bookId":"diwan-maarri","type":"poem","seq":659,"chapter":"قصائد","title":"كادت تساوى نفوس الناس كلهم","page":"","text":"كادت تساوى نفوس الناس كلهم … في الشر، ما بين منبوز ونباز\nظلم الحمامة في الدنيا، وإن حسبت … في الصالحات، كظلم الصقر والباز"},{"id":"diwan-maarri:660","bookId":"diwan-maarri","type":"poem","seq":660,"chapter":"قصائد","title":"إذا ما عانق الخمسين حي،","page":"","text":"إذا ما عانق الخمسين حي، … ثنته السن عن عنق وجمز\nوتهزأ منه ربات المغاني، … كما هزئت برؤبة أم حمز\nفلا أعرفك بين القوم توحي … بطعن، في محدثهم، وغمز\nولا تهمز جليسك من قريب، … تنبهه على سقط بهمز\nفشر الناس معروف، لديهم … بقول، في مثالبهم، ولمز\nلقد كذب الذين طغوا، فقالوا: … أتى من ربنا أمر برمز\nألم ترني عرفت وعيد رب، … أقل تكلمي، وأطال ضمزا؟\nومن لي أن أفر، على طمر، … من الدنيا الخبيثة، أو دلمز؟"},{"id":"diwan-maarri:661","bookId":"diwan-maarri","type":"poem","seq":661,"chapter":"قصائد","title":"أعاذلتي ارتجزت على المنايا،","page":"","text":"أعاذلتي ارتجزت على المنايا، … أؤمل أن يشجعني ارتجازي\nتمر حوادث، ويطول دهر، … ويفتقر المجيز إلى المجاز\nوكيف أروم منك جميل فعل، … إذا أيقنت أني غير جاز؟\nوليس على الحقائق كل قولي، … ولكن فيه أصناف المجاز\nلعل الرافدين، ونيل مصر، … يحرن، فينتقلن إلى الحجاز"},{"id":"diwan-maarri:662","bookId":"diwan-maarri","type":"poem","seq":662,"chapter":"قصائد","title":"صنعة عزت الأنام بلطف،","page":"","text":"صنعة عزت الأنام بلطف، … وعزتها إلى القدير العوازي\nملك أنشأ السموات، فالبدر … لديه في صورة الجلواز\nكم له كوكب أبر وأز النا … س، حتى سطا على أبرواز\nأغوى زيج ناظر في معاني ال … شهب، أم حل بالمنايا الغوازي؟\nنصت البين في حواء زياد … بارحات، كأنهن الحوازي\nونوى زينب تهون على القلب، … وفيه مثل الشرار النوازي\nلنفوس جوازىء باصطبار، … يتوقعن خلسة للجواز\nليس معط، في دولة اليسر، منه، … مثل معط في دولة الإعواز\nووجدنا خوازن المال ضيعن، … وأبقين منفسا للخوازي\nوالرزايا زوائري باختياري، … وسواهن، بعد ذاك، الروازي\nوالليالي هوازىء، راجعات … في أبي جادها، وفي هواز\nلا أواريك في طلاب المعالي، … وهي في الغدر كالظلال الأوازي\nلو ملكت الأراك، أجمع، والا … سحل لم تحصلي على مضواز\nجوزينا، ونحن سفر بأرض … أظمأتنا، وما لنا من جواز\nنخبط الليل، والبوازل كا … لخمس ريعت من البزاة البوازي\nفوز الركب يبتغون صلاحا … من حمام، والفوز للفواز\nوإذا حازت الأنامل ملكا، … صار هلكا في قبضة الحواز"},{"id":"diwan-maarri:663","bookId":"diwan-maarri","type":"poem","seq":663,"chapter":"قصائد","title":"أوجز الدهر، في المقال، إلى أن","page":"","text":"أوجز الدهر، في المقال، إلى أن … جعل الصمت غاية الإيجاز\nمنطقا ليس بالنثير، ولا الشع … ري، ولا في طرائق الرجاز\nوعدتنا الأيام كل عجيب، … وتلون الوعود بالإنجاز\nهي مثل الغواني إن تحسن الأو … جه منها، فالثقل في الأعجاز\nمن يرد صفو عيشة يبغ، من دن … ياه، أمرا مبين الإعجاز\nفافعل الخير إن جزاك الفتى عن … ه، وإلا فالله، بالخير، جاز\nلا تقيد علي لفظي، فإني … مثل غيري، تكلمي بالمجاز\nتنسب الشهب من يمان وشا … مي، ويلغى انتسابها في الحجاز\nإنما عشرة الأنام نفاق، … وتباه في باطل، وتجاز"},{"id":"diwan-maarri:664","bookId":"diwan-maarri","type":"poem","seq":664,"chapter":"قصائد","title":"أوعز الدهر بالفناء إلى النا","page":"","text":"أوعز الدهر بالفناء إلى النا … س، فواها لذلك الإيعاز\nوتداعوا في آل زيد وعمرو، … وعزاهم، لتربة الأرض، عاز\nأعرضوا عن مدائح وتهان، … فالمراثي أولى بكم والتعازي"},{"id":"diwan-maarri:665","bookId":"diwan-maarri","type":"poem","seq":665,"chapter":"قصائد","title":"عنصر واحد، وما القار في هي","page":"","text":"عنصر واحد، وما القار في هي … ت لعمري، كالمسك في خرخاز\nكن من الروم، أو من الترك، أو … سابح، أو فارس، أو الإيخاز\nصورة خبرت بأنك مجبو … ل على الشر، والمهيمن خاز\nواختلاف من منصب وبلاد؛ … واتفاق على رضا بالمخازي"},{"id":"diwan-maarri:666","bookId":"diwan-maarri","type":"poem","seq":666,"chapter":"قصائد","title":"فارسا كان رب فارس، كسرى","page":"","text":"فارسا كان رب فارس، كسرى … رحلته الخطوب عن شيداز\nفاغد كاللؤلؤ، الذي باسمه، … أغناك عن نسبة إلى خيداز"},{"id":"diwan-maarri:667","bookId":"diwan-maarri","type":"poem","seq":667,"chapter":"قصائد","title":"عل زمانا يديل آخره،","page":"","text":"عل زمانا يديل آخره، … فقد يكون الرشاد في العجز\nإلى الأنين استراح خدن ضنى، … كما استعان السفاة بالرجز\nوالدين نصح الجيوب مقترنا، … مدى الليالي، بعفة الحجز\nيا صاح! إني لزائف عملي، … فحق أني وجدت لم أجز"},{"id":"diwan-maarri:668","bookId":"diwan-maarri","type":"poem","seq":668,"chapter":"قصائد","title":"بقائي الطويل، وغي البسيط،","page":"","text":"بقائي الطويل، وغي البسيط، … وأصبحت مضطربا كالرجز\nولي نفس لم يزل دائبا، … ينجز وقتي، حتى نجز\nفأثن على الله تعط الثواب، … وإلا فكم مادح لم يجز\nوما انفك سعي الفتى للضلال، … إلى أن ثوى، أو إلى أن عجز\nفهل أنت محتجز؟ إنه، … ليوم الحمام، تشد الحجز"},{"id":"diwan-maarri:669","bookId":"diwan-maarri","type":"poem","seq":669,"chapter":"قصائد","title":"تداولني صبح ومسي وحندس،","page":"","text":"تداولني صبح ومسي وحندس، … ومر علي اليوم والغد والأمس\nيضيء نهار، ثم يخدر مظلم، … ويطلع بدر، ثم تعقبه شمس\nأسير عن الدنيا، وما أنا ذاكر … لها بسلام، إن أحداثها حمس\nصرورة ما حالين، ما لكعابها، … ولا الركن، تقبيل، لدي، ولا لمس\nولم أرث النصف الفتاة، ولم ترث … بي الربع، بل ربع تطاول أو خمس\nلعمري، لقد جاوزت خمسين حجة، … وحسبي عشر، في الشدائد، أو خمس\nوإن ذهبت كالفيء، فهي كمغنم … يحاز، ولم يفرد، لخالقه، الخمس\nفللخبر المروى، وللعالم القلى، … وللجسد المثوى، وللأثر الطمس\nبدار بدار الخير، يا قلب تائبا، … ألست بدار أن منزلي الرمس؟\nوأجهر حينا، ثم أهمس تارة؛ … وسيان، عند الواحد، الجهر والهمس\nوأقمس في لج النوائب طالبا؛ … ويغرقني من دون لؤلؤه القمس\nولم أك ندا للكلابي أبتغي، … من السؤر، ما فيه لذي شنب غمس"},{"id":"diwan-maarri:670","bookId":"diwan-maarri","type":"poem","seq":670,"chapter":"قصائد","title":"إذا ما أسن الشيخ أقصاه أهله،","page":"","text":"إذا ما أسن الشيخ أقصاه أهله، … وجار عليه النجل والعبد والعرس\nوصار كبنت الموم، تسهر في الدجى، … بكاه له طبع، ولمته برس\nوأكثر قولا، والصواب لمثله، … على فضله، أن لا يحس له جرس\nيسبح، كيما يغفر الله ذنبه؛ … رويدك في عهد الصبا ملىء الطرس\nوقد كان من فرسان حرب وغارة، … فلم يغن عنه السيف والرمح والترس\nوأصبح عند الغانيات مبغضا، … كأن خزه خزي، وعنبره كرس\nعجبت لقبر فيه ضيق تزاحمت، … على الكون فيه، العرب والروم والفرس\nمتى يأكل الجثمان يسكنه غيره، … يد الدهر، حرسا جاء من بعده حرس\nوكم درست هذي البسيطة عالما، … وعالم جيل من عوائده الدرس\nلقد فرست تلك الأسود طوائفا: … أنيسا ووحشا، ثم أدركها الفرس\nوما برح الإنسان في البؤس مذ جرت … به الروح، لا مذ زال عن رأسه الغرس\nفلا تعذلينا، كلنا ابن لئيمة؛ … وهل تعذب الأثمار إن لؤم الغرس؟\nطفونا ونرسو الآن، لا سر أسودي … بملك البرايا، ما العراق وما النرس\nفإني أرى الكافور والطيب، كله، … يزول بموت، جاء في يده ورس\nمضى الناس، إلا أننا في صبابة، … كآخر ما تبقي الحياض أو الخرس\nولم يسمعوا قولا، أمن صمم بهم؟ … ولم يفهموا رجعا، كأنهم خرس"},{"id":"diwan-maarri:671","bookId":"diwan-maarri","type":"poem","seq":671,"chapter":"قصائد","title":"لو اني كلب، لاعترتني حمية","page":"","text":"لو اني كلب، لاعترتني حمية … لجروي، أن يلقى كما لقي الإنس\nأرى الحي جنسا ظل يشمل عالمي … بأنواعه، لا بورك النوع والجنس"},{"id":"diwan-maarri:672","bookId":"diwan-maarri","type":"poem","seq":672,"chapter":"قصائد","title":"نصحتك أجسام البرية أجناس،","page":"","text":"نصحتك أجسام البرية أجناس، … وخير من الأعراس برس وعرناس\nولا تلجي الحمام، قد جاء ناصح … بتحريمه، من قبل أن يفسد الناس\nفكيف به لما اعتدى، في طريقه، … رجيب وحواش وتنج وأشناس\nتمازج بالعرب الأعاجم، والتقى … على الغدر أنواع تذم، وأجناس\nأناس كقوم ذاهبين وجوههم، … ولكنهم في باطن الأمر نسناس\nجزى الله، عني مؤنسي بصدوده، … جميلا، ففي الإيحاش ما هو إيناس\nتخافين شيطانا، من الجن، ماردا، … وعندك شيطان، من الإنس، خناس"},{"id":"diwan-maarri:673","bookId":"diwan-maarri","type":"poem","seq":673,"chapter":"قصائد","title":"ألم تر للشعرى العبور توقدت","page":"","text":"ألم تر للشعرى العبور توقدت … بعال رفيع، لم تنله القوابس\nتبارك رب الناس، ليس لما أبى … مريد، ولا دون الذي شاء حابس\nسيوف بها جونان: جار وجاسد؛ … وخيل عليها الماء رطب ويابس\nويعبس وجه الدهر، والمرء ضاحك، … ويضحك هزءا، والوجوه عوابس\nتكره نطق الناس فيما يريبه، … فأفحم، حتى ليس في القوم نابس\nبرود المخازي لابن آدم حلة، … لعمري، لقد أعيت عليه الملابس"},{"id":"diwan-maarri:674","bookId":"diwan-maarri","type":"poem","seq":674,"chapter":"قصائد","title":"نراقب ضوء الفجر، والليل دامس","page":"","text":"نراقب ضوء الفجر، والليل دامس … وما يستر الإنسان إلا الروامس\nتنمس منا بالديانة معشر، … وقد بطلت، عند اللبيب، النوامس\nفكيف ترى المنهاج، والليل مقمر، … ولم تره، واليوم أزهر شامس؟\nوتحملنا الأيام حمل عوائم … بنا في خضم، كلنا فيه قامس\nفهن لأهل اليسر نوق أذلة؛ … وهن لأهل العسر خيل شوامس\nفما سئم الساري، وقد بلغ المدى؛ … ولا رزمت، في السير، تلك العرامس\nودنياك دار، من يحل فناءها، … فقد غمسته في الشرور القوامس\nوسلطانها كالنار، إن هي لومست … تحرق ما يدنو لها، ويلامس\nويجمعنا من صنعة الرب أربع، … ومن فوقها، والملك لله، خامس\nوما فتئت نيران فارس يعتلي … بها العز، حتى أبطلتها الأحامس\nتكلم هذا الدهر بالنصح، معلنا، … جهارا، بما أخفته عنا الهوامس\nوكيف نرجي للثماد بقاءها، … إذا نضبت عنا البحور القلامس؟\nيباكرنا الجون المضيء فينقضي، … ويعقبنا منه الأحم الدلامس\nوإنا رأينا الملك يخلق ثوبه، … وتخبرنا عنه الديار الطوامس\nإذا دخل الهرماس جلق واليا، … فما كذبت فيما تقول الهرامس\nلهم سلف، قدام سنبس، أيد، … وعز على وجه الزمان قدامس\nوتبسط فينا قدرة الله حادثا، … فتودي الثعالي والليوث الكهامس"},{"id":"diwan-maarri:675","bookId":"diwan-maarri","type":"poem","seq":675,"chapter":"قصائد","title":"تشاد المغاني، والقبور دوارس،","page":"","text":"تشاد المغاني، والقبور دوارس، … ولايمنع المطروق باب وحارس\nيقولون: إن الدين ينسخ مثل ما … تولت، بإقبال الحنيفة، فارس\nومهما يكن، فالله ليس بزائل، … ويجني الفتى، من بعد، ماهو غارس\nأرى مقرا، في آخر العيش، كائنا، … نسيت له ما أطعمتك الجوارس\nأيا قيل! إن النار صال بحرها … مقيم صلاة، والمهند وارس\nوبالرملة الشعثاء شيب وولدة، … أصابهم، مما جنيت، الدهارس\nفأبعد من الصفراء، واليوم واقد؛ … وأدن من الشقراء، والليل قارس\nوقد ظهرت أملاك مصر عليهم، … فهل مارست من ظلمها ما تمارس؟\nوأحسن منكم، في الرعية، سيرة، … طغج بن جف، حين قام، وبارس\nوبالحظ يدعى تابع القوم سيدا، … وتأكل آساد العرين الهجارس\nتقيم، على الدهر، الفوارس في الدجى؛ … وترحل، من فوق الجياد، الفوارس"},{"id":"diwan-maarri:676","bookId":"diwan-maarri","type":"poem","seq":676,"chapter":"قصائد","title":"تمنت غلاما يافعا، نافعا لها،","page":"","text":"تمنت غلاما يافعا، نافعا لها، … وذاك دهاء دس فيه الدهارس\nسررت به، إذ قيل أعطيت فارسا، … وماهو إلا ضيغم لك فارس\nألم تسمعي الأيام نادت صروفها: … خذوا مقرا مما تفيء الجوارس\nوحاذر، أن ننسى الزمان، فما ونى … يذاكرنا أحداثه، ويدارس\nيخوفنا أهوال ماهو كائن؛ … ويكفيه، من أهواله، مانمارس"},{"id":"diwan-maarri:677","bookId":"diwan-maarri","type":"poem","seq":677,"chapter":"قصائد","title":"ينشر، في الدنيا، الحديث وينطوي،","page":"","text":"ينشر، في الدنيا، الحديث وينطوي، … وتفرس آساد العرين، وتفرس\nإذا أوجدت، يوما، من الوجد أوجدت … من الوجد، هذا خلقها، وهو أشرس\nوقد يعظ الإنسان عي من الدجى، … وينذره داع، من الصبح، أخرس\nوما حرصه في العلم يدرس كتبه، … وقد شاهد الآثار تمحى وتدرس\nنسير نهارا، ثم نسري، إذا دجت … علينا الليالي، والخفير المعرس\nألم تر أشجارا تحرق، عهدها … قديم، وأخرى للشبيبة تغرس؟\nوتختلف الأغراض: ماء على الصلى … يحم، وماء، في الشمال، يغرس\nمتى ماتحاول فارسا من فراسة، … فإني من زيد وبسطام أفرس\nإخال، فلا أشوي، وتلك فضيلة، … ولكنني بالخيل لا أتمرس\nونومك، في الصحراء، أروح من ذرا … تشاد، وأموال تصان وتحرس\nوكم عض مغبر البنان، تندما … على ما جنى، قبل، البنان المورس"},{"id":"diwan-maarri:678","bookId":"diwan-maarri","type":"poem","seq":678,"chapter":"قصائد","title":"نفوس أصابتها المنايا، فلا تكن","page":"","text":"نفوس أصابتها المنايا، فلا تكن … يؤوسا، لعل الله يوما يؤوسها\nوما برحت أجسادها تطلب العلا … من الدهر، حتى زايلتها رؤوسها\nبئت بالظبا أبيات عز، فأودعت … بيوت حفير، أحكمتها فؤوسها\nوكانوا كآساد الشرى، ليس فيهم … كؤوس، فدارت للمنايا كؤوسها"},{"id":"diwan-maarri:679","bookId":"diwan-maarri","type":"poem","seq":679,"chapter":"قصائد","title":"المشيدات، التي رفعت،","page":"","text":"المشيدات، التي رفعت، … أربع من أهلها درس\nقام للأيام، في أذني، … واعظ من شأنه الخرس\nأخلقت، جسم الفتى، جدد، … ذات خلق، لينه شرس\nفشتاء، بعده ومد، … ومصيف، إثره قرس\nلبت، حول الماء، من ظمإ، … إن غربي ماله مرس\nكم أبن الغاب من أسد؛ … أي ليث ليس يفترس\nمهجتي ضد يحاربني، … أنا مني كيف أحترس؟\nإنما دنياك غانية، … لم يهنىء زوجها، العرس\nأم شبل، فوقها لبد، … ظفرها، من قتلنا، ورس\nفالقها بالزهد، مدرعا، … في يديك السيف والترس\nإن دنا، من فارس، أجل، … حار، لايجري به الفرس\nكل من حانت منيته، … لم يدافع، دونه، حرس\nليس يبقى فرع نابتة، … أصلها، في الموت، مغترس\nخبرتني كل ناطقة، … ذاك حتى الزير والجرس"},{"id":"diwan-maarri:680","bookId":"diwan-maarri","type":"poem","seq":680,"chapter":"قصائد","title":"من لي بأني وحيد لا يصاحبني","page":"","text":"من لي بأني وحيد لا يصاحبني … حي، سوى الله، لا جن ولا أنس\nأما الظباء، فقد أودى الزمان بها، … فما نراها، ولكن هذه الكنس\nفكيف لا تخبث النفس التي جعلت، … من جسمها، في وعاء، كله دنس؟\nرأيت فتيان قومي عانسي حذر، … إن الفتو إذا لم ينكحوا عنسوا\nسلكت طرق المعالي، ثم قلت لهم: … سيروا ورائي، فلما شارفوا خنسوا"},{"id":"diwan-maarri:681","bookId":"diwan-maarri","type":"poem","seq":681,"chapter":"قصائد","title":"إذا جلست على أقتاد ناجية،","page":"","text":"إذا جلست على أقتاد ناجية، … فما أبالي أغار القوم أم جلسوا\nأنسل إبليس أم حواء، ويحكم، … هذا الأنام، ففي أفعالهم دلس\nإن يؤمنوا لا يؤدوا، أو يكن لهم … عز يضيموا، وإن أعياهم اختلسوا\nذاد المكارم عن كرم وذات جنى، … في النخل، شرب أبى إخراجه البلس\nلا تحفظ الشرب، مثل الطير، واردة … أجنا، إذا ما أصابوا ريهم قلسوا\nياسر أخاك، ولا تهجم له حرما، … من قبل زكي في أكمامه العلس\nقد أظلم الدهر، والصبح الجلي نأت … عنه المطامع، فليرفع لنا الغلس"},{"id":"diwan-maarri:682","bookId":"diwan-maarri","type":"poem","seq":682,"chapter":"قصائد","title":"أما الحسام، فما أدناك من أجل،","page":"","text":"أما الحسام، فما أدناك من أجل، … ولا يرد الحمام الدرع والترس\nوالناس، من صنعة الخلاق، كلهم … كالخط يقرأ حينا ثم يندرس\nقد ادعى النسك أقوام، بزعمهم، … وكيف نسك غوي رمحه ورس\nوقد جنى الإثم، تغشاه صحابته، … والنبل والسيف والخطي والفرس\nيا ظبي ما أنت والضرغام تؤنسه؛ … إن الضراغم من أخلاقها الشرس\nأيعلم الليث، لما راح مفترسا، … بأنه، عن قريب، سوف يفترس؟\nلمن تواخذ بالجرى التي سلفت، … وما تحرك حتى حرك الجرس\nيستحسن القوم ألفاظا، إذا امتحنت … يوما، فأحسن منها العي والخرس\nوآل إسرال غادوا، في مدارسهم، … تلاوة، ومحال كل ما درسوا\nأرسلت غربك تبغي الماء، مجتهدا، … وما على الغرب لما خانك المرس\nوبئس ما يأمل الجانون من ثمر، … إن قال عارف غرس: بئس ما غرسوا\nقد عمر النسر ما حم المليك له، … وما لمنزله قفل ولا حرس\nرأى، مناحة أهل الدار، شامتهم، … فما تخيل إلا أنها عرس"},{"id":"diwan-maarri:683","bookId":"diwan-maarri","type":"poem","seq":683,"chapter":"قصائد","title":"حجر، على الناس حجر، ليت أنهم،","page":"","text":"حجر، على الناس حجر، ليت أنهم، … مثل الحجارة، لا ماتوا ولا نبسوا\nجاؤوا بدعوى، فلما حصلت وجدت … مثل الهباء، وقيل الأمر ملتبس\nوالقوم شر، فلا يسررك إن بسطوا … لك الوجوه، ولا يحزنك إن عبسوا\nأمر بدا ثم أخفى، شأنه، قدر، … كالنار ماتت، فلم ينشر لها قبس\nوخامل ما نأت عنه نباهته، … كأنه الجمر غطى ضوءه اليبس\nدنياي هل لي زاد أستعين به … على الرحيل، فإني فيك محتبس"},{"id":"diwan-maarri:684","bookId":"diwan-maarri","type":"poem","seq":684,"chapter":"قصائد","title":"هل يغسل الناس عن وجه الثرى مطر،","page":"","text":"هل يغسل الناس عن وجه الثرى مطر، … فما بقوا لم يبارح، وجهه، دنس\nوالأرض ليس بمرجو طهارتها، … إلا إذا زال عن آفاقها الأنس\nتناسلوا، فنمى شر بنسلهم؛ … وكم فجور، إذا شبانهم عنسوا\nأزكى من العين، في آنافها شمم، … عين من الوحش، في آنافها خنس\nوما الظباء، عليها الحلي، محسنة، … بل الظباء لها، بين الغضا، كنس\nإحتج، في الغي بالنسيان، والدهم، … وقد غووا بادكار، لا أقول نسوا"},{"id":"diwan-maarri:685","bookId":"diwan-maarri","type":"poem","seq":685,"chapter":"قصائد","title":"دنياك دار شرور لا سرور بها،","page":"","text":"دنياك دار شرور لا سرور بها، … وليس يدري أخوها كيف يحترس\nبينا امرؤ يتوقى الذئب عن عرض، … أتاه ليث، على العلات، يفترس\nألا ترى هرمي مصر، وإن شمخا، … كلاهما بيقين سوف يندرس\nولو أطاع أمير العقل صاحبه، … لكان آثر، من أن ينطق، الخرس\nمع الأنام أحاديث مولدة … للإنس، تزرع كي تبقى وتغترس\nلم تخلق الخيل من عر ومصمتة، … إلا ليركض، في حاجاته، الفرس\nأوان قر يوافي، بعده، ومد، … من الزمان، وحر بعده قرس\nخذ يا أخا الحرب أو ضع لأمة وضنت؛ … فما يوقيك لا درع ولا ترس\nولم يبل رب مسحاة يقلبها، … ولا حليف قناة، رمحه ورس\nقد يخطىء، الموت، ملقى في تنوفته، … ويهلك المرء في قصر، له حرس\nوما حمى، عن صليل السيف، هامته، … إن بات يصدح في أيديهم الجرس\nمد النهار حبال الشمس، كافلة … بأن سيقضب، من عيش الفتى، مرس\nظن الحياة عروسا، خلقها حسن؛ … وإنما هي غول خلقها شرس\nونحن في غير شيء، والبقاء جرى … مجرى الردى، ونظير المأتم العرس"},{"id":"diwan-maarri:686","bookId":"diwan-maarri","type":"poem","seq":686,"chapter":"قصائد","title":"يزورني القوم، هذا أرضه يمن","page":"","text":"يزورني القوم، هذا أرضه يمن … من البلاد، وهذا داره الطبس\nقالوا: سمعنا حديثا عنك، قلت لهم: … لا يبعد الله إلا معشرا لبسوا\nيبغون مني مينا لست أحسنه، … فإن صدقت، عرتهم أوجه عبس\nأعاننا الله، كل في معيشته … يلقى العناء، فدري فوقنا دبس\nماذا تريدون؟ لا مال تيسر لي … فيستماح، ولا علم فيقتبس\nأتسألون جهولا أن يفيدكم، … وتحلبون سفيا، ضرعها يبس؟\nما يعجب الناس إلا قول مختدع، … كأن قوما إذا ما شريوا أبسوا\nقد أنفدوا في ضياع كل ما عمروا، … فكان مثل جلال البدن ما لبسوا\nأنا الشقي بأني لا أطيق لكم … معونة، وصروف الدهر تحتبس\nمن لليمانين أن يمسوا، ونارهم … شبيبة، وسهيل بينهم قبس\nوللبداوي أن يبنى الخباء له … في ضاحكات، بهن العبس والعبس\nكأن أسرار أقوام، وإن كتمت، … أنفاس ولهان، تطفى حين تحتبس\nوحدثت، عن خباياهم، وجوههم، … فقد أتوك بنجواهم، وما نبسوا\nساعاتنا كذئاب الختل، إن غبست، … في الليل، فالذئب في ألوانه الغبس"},{"id":"diwan-maarri:687","bookId":"diwan-maarri","type":"poem","seq":687,"chapter":"قصائد","title":"الجسم كالصفر، يكسوه الثرى صدأ،","page":"","text":"الجسم كالصفر، يكسوه الثرى صدأ، … والخير كالتبر، لا يدنو له الدنس\nلو دام في الأرض، عمر الدهر، مختزنا … لما تغير عما يعهد الأنس"},{"id":"diwan-maarri:688","bookId":"diwan-maarri","type":"poem","seq":688,"chapter":"قصائد","title":"إن كان إبليس ذا جند يصول بهم،","page":"","text":"إن كان إبليس ذا جند يصول بهم، … فالنفس أكبر من يدعوه إبليس\nلا شب ربك نيران الشباب! لهم … إلى المدامة تهجير وتغليس\nوالدهر، في الحجر، ترجى منه عارفة، … أنى وقد بان إعسار وتفليس؟\nوموه الناس، حتى ظن جاهلهم … أن النبوة تمويه وتدليس\nجاءت، من الفلك العلوي، حادثة، … فيها استوى جبناء القوم والليس\nلو هب هجاد قوم، في الثرى، دفنوا … لضاقت المدن والبيد الأماليس\nمتى أفارق دنياي التي غدرت، … ويدرك اسمي، في الأسماء، تطليس؟"},{"id":"diwan-maarri:689","bookId":"diwan-maarri","type":"poem","seq":689,"chapter":"قصائد","title":"الظلم في الطبع، فالجارات مرهقة","page":"","text":"الظلم في الطبع، فالجارات مرهقة … والعرف يستر، والميزان مبخوس\nوالطرف يضرب، والأنعام مأكلة، … والعير حامل ثقل، وهو منخوس"},{"id":"diwan-maarri:690","bookId":"diwan-maarri","type":"poem","seq":690,"chapter":"قصائد","title":"أوحى المليك إلى من في بسيطته،","page":"","text":"أوحى المليك إلى من في بسيطته، … من البرية، جوسوا الأرض أو حوسوا\nفأنتم قوم سوء، لا صلاح لكم، … مسعودكم، عند أهل الأرض، منحوس"},{"id":"diwan-maarri:691","bookId":"diwan-maarri","type":"poem","seq":691,"chapter":"قصائد","title":"لا خير للفم في بسط الحياة له،","page":"","text":"لا خير للفم في بسط الحياة له، … حتى تساقط أنياب وأضراس\nأظاعن أنت أم راس على مضض، … حتى تخونك، من دنياك، أمراس؟\nهل تمنعنك بيض أو مثقفة، … أو ينجينك أجمال وأفراس؟\nأضعت شاء جعلت الذئب حارسه، … أما علمت بأن الذئب حراس؟\nوإن رأيت هزبر الغاب مفترسا، … فقد يكون زمانا، وهو فراس\nلا تفرق النفس من حتف يحل بها، … فالنفس أنثى، لها بالموت إعراس\nتحالفوا، كل رأس منهم سدل، … يجر نفعا إليه ذلك الراس\nأظلمت، فاهتجت تبغي، في جميعهم، … نبراس ليل وما في القوم نبراس\nتعلم الكفر أولاهم وآخرهم، … فكل أرض بها جمع ومدراس\nوعن قليل يصير الأمر منتقلا … عنهم، وتخفت للأجراس أجراس"},{"id":"diwan-maarri:692","bookId":"diwan-maarri","type":"poem","seq":692,"chapter":"قصائد","title":"تراب غيرت منه سمات،","page":"","text":"تراب غيرت منه سمات، … فطير في مواكنها وناس\nهو الليث اسم مأواه عرين، … أوالظبي اسم مأواه كناس\nتجانست البرايا في معان، … ولم يجلب مودتها الجناس\nإذا أنبأت، عن غرض، بلفظ، … فقل: خنساء شطت، أو خناس"},{"id":"diwan-maarri:693","bookId":"diwan-maarri","type":"poem","seq":693,"chapter":"قصائد","title":"إذا رفعوا كلامهم بمدح،","page":"","text":"إذا رفعوا كلامهم بمدح، … فلفظي، في مواطنه، رسيس\nوما حمدي لآدم، أو بنيه، … وأشهد أن كلهم خسيس\nوزوجك أيها الدنيا تمنى … طلاقك، قبل أن يقع المسيس\nتحدث هذه الأيام جهرا، … ويحسب أن مانطقت هسيس\nتعالى الله! أين ملوك لخم، … لقد خمدوا فما لهم حسيس\nوأسأل خالقي نسأ برفق، … إذا لم يبق لي إلا النسيس"},{"id":"diwan-maarri:694","bookId":"diwan-maarri","type":"poem","seq":694,"chapter":"قصائد","title":"أيوجد، في الورى، نفر طهارى،","page":"","text":"أيوجد، في الورى، نفر طهارى، … أم الأقوام كلهم رجوس؟\nبنات العم تأباها النصارى، … وبالأخوات أعرست المجوس"},{"id":"diwan-maarri:695","bookId":"diwan-maarri","type":"poem","seq":695,"chapter":"قصائد","title":"كنت الفقير، فخطئت لك صيب،","page":"","text":"كنت الفقير، فخطئت لك صيب، … ورزقت إثراء، فقيل مقرطس\nخرصوا، فقالوا إن عالم آدم، … قد كان يلفظ أنفسا إذ يعطس\nفلذاك صار الحمد عند عطاسهم … خلقا لهم، وأخو الحجى متنطس"},{"id":"diwan-maarri:696","bookId":"diwan-maarri","type":"poem","seq":696,"chapter":"قصائد","title":"ثمل الكبير، فظل يحسب أنه","page":"","text":"ثمل الكبير، فظل يحسب أنه … كر الشباب، ولان عظم يابس\nوكأنها، لما دنت من شيبه، … شقر، لنور الأقحوان ملابس\nويظنها نار الخليل سليمة، … ويكاد يأخذ من سناها القابس\nضحكت إليه، وهي هازئة به، … لما حساها، وهو أزور عابس\nما الناس ناس، إذ تغير شكلهم، … قل ما بدا لك، فالديار بسابس\nما شفني برد أمح سوى الصبا، … ولقد تمزق لي سواه ملابس\nحبستك أقدار ذوتك عن المنى، … فمضى الصحاب وأنت ثاو حابس"},{"id":"diwan-maarri:697","bookId":"diwan-maarri","type":"poem","seq":697,"chapter":"قصائد","title":"جنت الغوارس، واستقل أخو الغنى","page":"","text":"جنت الغوارس، واستقل أخو الغنى … وسعى المؤمل، واستراح اليائس\nواللب حرف، والجهالة نعمة، … والكيس الفطن الشقي الكائس\nوإذا رجعت إلى الحقائق لم يكن، … في العالم البشري، إلا بائس\nوالموت باز، والنفوس حمائم، … وهزبر عريس، ونحن فرائس\nإن الأوانس، أن تزور قبورها، … خير لها من أن يقال عرائس\nكم نال قبلك، في طعامك، من يد … نصب، إلى أن لاس قوتك لائس\nفكوارب، وزوارع، وكوافر، … وحواصد، وجوامع، ودوائس\nوخطوب دهر غير ذلك جمة، … دون اغتذائك، والأمور لبائس\nوكذاك ما عناهم حتى رأوا … شجرا. بها ثمر الندامة نائس\nومتى ركبت إلى الديانة غالها … فكر، على حسن الضمير، دسائس\nوالعقل يعجب، والشرائع كلها، … خبر يقلد لم يقسه قائس\nمتمجسون، ومسلمون، ومعشر … متنصرون، وهائدون رسائس\nوبيوت نيران تزار تعبدا، … ومساجد معمورة، وكنائس\nوالصابئون يعظمون كواكبا، … وطباع كل، في الشرور، حبائس\nأنى ينال أخو الديانة سؤددا، … ومآرب الرجل الشريف خسائس؟\nوإذا الرئاسة لم تعن بسياسة … عقلية، خطىء الصواب السائس"},{"id":"diwan-maarri:698","bookId":"diwan-maarri","type":"poem","seq":698,"chapter":"قصائد","title":"يا رب أخرجني إلى دار الرضى،","page":"","text":"يا رب أخرجني إلى دار الرضى، … عجلا، فهذا عالم منكوس\nظلوا كدائرة تحول بعضها … من بعضها، فجميعها معكوس\nلا كيس بينهم، وأفضل من ترى، … في دينه، مثل العقير يكوس\nيبغون بالخسر الرباح، وبالأذى … حسن الثواب، فكلهم موكوس\nوأرى ملوكا لا تحوط رعية، … فعلام تؤخذ جزية ومكوس؟"},{"id":"diwan-maarri:699","bookId":"diwan-maarri","type":"poem","seq":699,"chapter":"قصائد","title":"إذا الحي ألبس أكفانه،","page":"","text":"إذا الحي ألبس أكفانه، … فقد فني اللبس واللابس\nويبلى المحيا، فلا ضاحك، … إذا سر دهر، ولا عابس\nويحبس في جدث ضيق، … وليس بمطلقه الحابس\nفما هو في سلف سائر؛ … ولا هو في حندس قابس\nيجاور قوما أجادوا العظات، … وما فيهم أحد نابس"},{"id":"diwan-maarri:700","bookId":"diwan-maarri","type":"poem","seq":700,"chapter":"قصائد","title":"شر أشجار، علمت بها،","page":"","text":"شر أشجار، علمت بها، … شجرات أثمرت ناسا\nحملت بيضا وأغربة، … وأتت بالقوم أجناسا\nكلهم أخفت جوانحه … ماردا، في الصدر، خناسا\nلم تسق عذبا، ولا أرجا، … بل أذيات وأدناسا\nتعب ما نحن فيه، وهل … يجلب الإيحاش إيناسا؟\nخذ حساما، سعد، أو قلما، … وخذي يا دعد عرناسا"},{"id":"diwan-maarri:701","bookId":"diwan-maarri","type":"poem","seq":701,"chapter":"قصائد","title":"يا روح، كم تحملين الجسم لاهية،","page":"","text":"يا روح، كم تحملين الجسم لاهية، … أبليته، فاطرحيه، طالما لبسا\nإن كنت آثرت سكناه، فمخطئة، … فيما فعلت، وكم من ضاحك عبسا\nأو لا، فجبر، وإن أشوى، فجاهلة، … كالماء لم يدر ما لاقاه إذ حبسا\nلو لم تحليه لم يهتج لمعصية، … وكان كالترب ما أخنى ولا نبسا\nتركت مصباح عقل ما اهتديت به، … والله أعطاك من نور الحجى قبسا"},{"id":"diwan-maarri:702","bookId":"diwan-maarri","type":"poem","seq":702,"chapter":"قصائد","title":"الحمد لله! قد أصبحت في لجج،","page":"","text":"الحمد لله! قد أصبحت في لجج، … مكابدا، من هموم الدهر، قاموسا\nقالت معاشر: لم يبعث إلهكم، … إلى البرية، عيساها ولا موسى\nوإنما جعلوا، للقوم، مأكلة، … وصيروا، لجميع الناس، ناموسا\nولو قدرت لعاقبت الذين طغوا، … حتى يعود حليف الغي مرموسا"},{"id":"diwan-maarri:703","bookId":"diwan-maarri","type":"poem","seq":703,"chapter":"قصائد","title":"يطهر، الجسد، المغرور، صاحبه،","page":"","text":"يطهر، الجسد، المغرور، صاحبه، … وإنما صيغ أقذارا وأنجاسا\nكم ادعى الطهر ناس، ثم كشفهم … مر الزمان، فكان القوم أرجاسا\nلا يمنع، الملك الجبار من قدر … يغير الحال، ما أجدى وما جاسا\nولو غدا الكوكب المريخ في يده، … كالسهم، واتخذ البرجيس برجاسا"},{"id":"diwan-maarri:704","bookId":"diwan-maarri","type":"poem","seq":704,"chapter":"قصائد","title":"يسوسون الأمور بغير عقل","page":"","text":"يسوسون الأمور بغير عقل … فينفذ أمرهم، ويقال: ساسه\nفأف من الحياة، وأف مني، … ومن زمن رئاسته خساسه"},{"id":"diwan-maarri:705","bookId":"diwan-maarri","type":"poem","seq":705,"chapter":"قصائد","title":"القدس لم يفرض عليك مزاره،","page":"","text":"القدس لم يفرض عليك مزاره، … فاسجد لربك في الحياة مقدسا\nأصبحت في يومي أسائل عن غدي، … متخبرا عن حاله متندسا\nأما اليقين، فلا يقين، وإنما … أقصى اجتهادي أن أظن وأحدسا\nلا ترهبن من الظباء كوادسا، … ولو انتشقن مع الصباح الكندسا\nوإذا النهار خشيت منه غوائلا، … فعليك من ليل يعينك حندسا\nفالجنح أخضر كالسدوس، تخاله … من حبة خضراء غشي سندسا"},{"id":"diwan-maarri:706","bookId":"diwan-maarri","type":"poem","seq":706,"chapter":"قصائد","title":"من لي بإمليسية، أعني بها","page":"","text":"من لي بإمليسية، أعني بها … وجناء، تقطع في الدجى الإمليسا\nأطلبتم أدبا لدي، ولم أزل … منه أعاني الحجر والتفليسا؟\nما كنت ذا يسر، فأجمعه، ولا … ذا صحة، فأحالف التغليسا\nوأردتموني أن أكون مدلسا؛ … هيهات! غيري آثر التدليسا\nليس الأنام بمنجح، فإذا دعا … داعي الضلال، فلا يجدكم ليسا\nإن مات صاحبكم، فجدوا بعده … في النسك، واتخذوا الخشوع جليسا\nفالله ما اختار البقاء وطوله، … إلا لشر عباده إبليسا\nوأرى الذئاب الطلس، يعجز كيدها … عن كيد شيب أظهروا التطليسا\nوتخالسوا الغرض الحرام، وقد رأوا … شعرا، كملوية الرياض خليسا"},{"id":"diwan-maarri:707","bookId":"diwan-maarri","type":"poem","seq":707,"chapter":"قصائد","title":"داء هذا الأنام لا يقبل الطب،داء هذا الأنام لا يقبل الطب،","page":"","text":"داء هذا الأنام لا يقبل الطب،داء هذا الأنام لا يقبل الطب، … وقدما أراه داء نجيسا\nفكر حسنت، لقوم، أمورا، … فاستجازوا التهويد والتمجيسا\nمعشر صيروا المدامة قربا … نا، وناس ألقوا بها التنجيسا\nرب ربع، كأنه النجم في العز، … أتاه ريب الزمان فجيسا\nوالفتى غير آمن من أذى الده … ر، ولو كان شخصه البرجيسا"},{"id":"diwan-maarri:708","bookId":"diwan-maarri","type":"poem","seq":708,"chapter":"قصائد","title":"إذا ما غضوب غاضبت كل ريبة،","page":"","text":"إذا ما غضوب غاضبت كل ريبة، … وكانت لميس لا تقر على اللمس\nفقد حازتا فضل الحياة، وعدتا … مكان الثريا، في المكارم، والشمس\nأخمسين قد أفنيتها ليس نافعي، … بتأخير يوم، أن أعض على خمسي\nنرجي إيابا من غد، وهو آيب، … وكان صوابا لو بكينا على أمس\nوما زال هذا الجسم، مذ فارق الثرى، … على تعب، حتى أعيد إلى الرمس\nألم تر أيام الفتى، في عظاته، … بهمس تناجي، أو أدق من الهمس\nتوخت عواري الملوك بردها … جهارا، وآثار الأكارم بالطمس\nولم تترك العز القديم لفارس؛ … ولم ترع حقا من فوارسها الحمس\nأرتك، برغم الأنف، سيف ابن ظالم، … حمائله موصولة بفتى الحمس\nوصار دم الديك المؤذن، سحرة، … لأهل المغاني حسوة لفم النمس\nوما سرني أني ابن ساسان أغتدي … على الملك، في الإيوان، أصبح أو أمسي"},{"id":"diwan-maarri:709","bookId":"diwan-maarri","type":"poem","seq":709,"chapter":"قصائد","title":"تصدق على الطير الغوادي بشربة","page":"","text":"تصدق على الطير الغوادي بشربة … من الماء، واعددها أحق من الإنس\nفما جنسها جان عليك أذية، … بحال، إذا ما خفت من ذلك الجنس\nلقد فرعتنا قدرة أزلية، … فعشنا، وعدنا راجعين إلى القنس\nتذكرنا الأيام أمرا، فننطوي … عليه، زمانا، ثم لا بد أن تنسي\nفلا تتعرض، في طريقك، ناظرا … نساء النصارى غاديات إلى الكنس"},{"id":"diwan-maarri:710","bookId":"diwan-maarri","type":"poem","seq":710,"chapter":"قصائد","title":"أيا ظبيات الإنس لست مناديا","page":"","text":"أيا ظبيات الإنس لست مناديا … وحوشا، ولكن غانيات مع الإنس\nيشبهن، في بعض المحاسن، ربربا، … وما هن بالسفع الخدود، ولا الخنس\nتمسكن طيبا أم تمسكن حلية، … فإني رأيت النوع يلحق بالجنس\nولا خير في جون الذوائب عانس، … إذا لم يبت فوق الرحالة والعنس\nومن لا يجد حفظ التجارب لا يزل … على السن، غمرا، إن طول المدى ينسي"},{"id":"diwan-maarri:711","bookId":"diwan-maarri","type":"poem","seq":711,"chapter":"قصائد","title":"إذا حضرت عندي الجماعة أوحشت،","page":"","text":"إذا حضرت عندي الجماعة أوحشت، … فما وحدتي إلا صحيفة إيناسي\nطهارة مثلي في التباعد عنكم؛ … وقربكم يجني همومي وأدناسي\nوألقى إلي اللب عهدا حفظته، … وخالفته غير الملول ولا الناسي\nوأعجب مني كيف أخطىء دائما، … على أنني من أعرف الناس بالناس\nنصحتك يا أم البنات، فحاذري … وساوس ولاج الأساود، خناس\nولا تلبسي الحجلين بنتك، والبرى … لتشهد عرسا، واشغلنها بعرناس"},{"id":"diwan-maarri:712","bookId":"diwan-maarri","type":"poem","seq":712,"chapter":"قصائد","title":"خصاؤك خير من زواجك حرة،","page":"","text":"خصاؤك خير من زواجك حرة، … فكيف إذا أصبحت زوجا لمومس\nوإن كتاب المهر، فيما التمسته، … نظير كتاب الشاعر المتلمس\nفلا تشهدن فيه الشهود، وألقه … إليهم، وعد كالعائر المتشمس\nولبسك ثوب السقم أحسن منظرا، … وأبهج من ثوب الغوي المنمس\nوإنك إن تستعمل العقل لا يزل … مبيتك في ليل، بعقلك، مشمس"},{"id":"diwan-maarri:713","bookId":"diwan-maarri","type":"poem","seq":713,"chapter":"قصائد","title":"إذا صفت النفس اللجوج، فإنما","page":"","text":"إذا صفت النفس اللجوج، فإنما … تعاني من الجثمان شر المحابس\nوما لبس الإنسان أبهى من التقى، … وإن هو غالى في حسان الملابس\nويبدي لدنياه الفتى وجه ضاحك، … وما فتئت تبدي له وجه عابس\nسرى ملك الأواب يحمل روحه … تنير، كما تجلو الدجى نار قابس\nشباب وشيب، كالنبات، كثيرة، … فمن بين رطب يستباح ويابس\nوخير بلاد الله ما كان خاليا … من الإنس، فاسكن في القفار البسابس"},{"id":"diwan-maarri:714","bookId":"diwan-maarri","type":"poem","seq":714,"chapter":"قصائد","title":"غدت أم دفر، وهي غير حميدة،","page":"","text":"غدت أم دفر، وهي غير حميدة، … مغنية، عوادة في المجالس\nتعود على من لم يمت بحمامه؛ … وتعلي فقيرا عد بعض المفالس\nوما نفس حسان الذي شاع جبنه، … بأسلم من نفس الكمي المخالس\nفيا ليت أني لم أكن في برية، … وإلا فوحشيا بإحدى الأمالس\nيسوف أزهار الربيع تعلة، … ويأمن في البيداء شر المجالس\nومن يسكن الأمصار لا يعدم الأذى … بإبليس، مشفوعا بمثل الأبالس\nيساور أسدا من غواة مساور، … وطلس ذئاب من رجال الطيالس\nمتى ما تصب يوما طعاما لظالم، … فقم عنه، وافغر بعده فم قالس\nوما جاوزت خيل، خوائل ألسا، … إلى الروم إلا بالشرور الأوالس\nأدالس نفسي، ثم أظلم صحبتي، … إذا رمت خلا منهم لم يدالس"},{"id":"diwan-maarri:715","bookId":"diwan-maarri","type":"poem","seq":715,"chapter":"قصائد","title":"هي الدار، ما حالت لعمري عهودها،","page":"","text":"هي الدار، ما حالت لعمري عهودها، … ولا افتقدت من زيها غير ناسها\nفكم حلها من ضيغم في عرينه؛ … وكم سكنتها ظبية في كناسها"},{"id":"diwan-maarri:716","bookId":"diwan-maarri","type":"poem","seq":716,"chapter":"قصائد","title":"إذا طلع النسران غارت ظعائن،","page":"","text":"إذا طلع النسران غارت ظعائن، … وكان مراس القر شر مراس\nوإن تبد، في الصبح، الثريا، فإنها … تيمم بالتسيار آل قراس\nلو ان بني الدنيا، يد الدهر، مشيهم … على الزف، لم أعدده غير هراس\nوما ظفرت أفراس قوم يحثها … فوارسها في عنجد وقراس\nجسوم تنمت ثم عادت، فأصبحت … ضروبا، كزرع نابت وغراس\nوما تركت بيض الزمان وسوده … كراسي عز، كلهن كراس\nولم يمنعوا، بالضرب والطعن، حادثا … أتى، دون أدراع لهم وتراس\nتداعت بلفظ العجم أعراب مذحج، … وأعرب أهلا فارس وخراس\nفإن ليوث الحتف نال افتراسها … ضراغم، من ليث وحي فراس\nفيا أم دفر لا سلمت غوية، … عليك قراعي، دائبا، وضراسي\nأتبغين مني، في المقال، تعصبا؛ … وأي أذاة ما عصبت براسي؟\nتسير بنا هذي الليالي، كأنها … سفائن بحر، ما لهن مراسي"},{"id":"diwan-maarri:717","bookId":"diwan-maarri","type":"poem","seq":717,"chapter":"قصائد","title":"ترومون، بالناموس، كسبا، فسعيكم،","page":"","text":"ترومون، بالناموس، كسبا، فسعيكم، … إذا لاحت الأطماع، سعي نموس\nوما وعظتكم ليلة بعد ليلة … ولا ضوء أقمار، بدت، وشموس\nنوقر دنيانا لناس، وبعضنا … تبوأ منها، فوق ظهر شموس\nفواها لأشباح لكم، غير أنها … تبدل، من أوطانها، برموس\nوأعظم آثار الأنام، بقية، … تغيره أيامه بطموس"},{"id":"diwan-maarri:718","bookId":"diwan-maarri","type":"poem","seq":718,"chapter":"قصائد","title":"إرفع مجنك، أو ضع؛ للفتى قدر،","page":"","text":"إرفع مجنك، أو ضع؛ للفتى قدر، … يلم بالنفس دون الدرع والترس\nإن الرئاسة والريس، اللذان هما … أصل الحقود، فلا ترأس ولا ترس\nكم عاذل جرسه في الليل فائدتي … به، كفائدة الحراس بالجرس\nلا تودع السر مزمارا، فيعلنه … بجهله، بعد طول الصمت والخرس\nفاز امرؤ باتت الأقدار تحرسه، … وإن مددت إليه كف محترس\nأحسن إلى الناقة الوجناء تبعثها، … فيما تشاء، وأكرم عشرة الفرس\nواردد عصاك عن السوداء، ماهنة، … وارفق بعبدك في المصطاف والقرس\nوالحي للأرض، إن يهلك فطعمتها، … وإن يعش يحي بعض الأربع الدرس\nأم له أكلته، طالما بذلت … له مآكل من زرع ومغترس\nتمسكت، بحبال العمر، مهجته، … والوقت بالمر يوهي قوة المرس\nوالدهر أنحى على ذي مارن أرج، … بطيبه، وعلى ذي مارن ورس\nدنياك تضحي، إذا جادت، مذممة، … أدالت الضأن من ليث الشرى المرس\nما زال يفترس الأعناق، معتديا؛ … فالآن أصبح فراسا كمفترس\nهي العروس، أبانت عن سماجتها، … فلا يغرك منها ليلة العرس\nواحذر مقال أناس كان منقبضا، … يلقى العفاة بوجه العابس الشرس"},{"id":"diwan-maarri:719","bookId":"diwan-maarri","type":"poem","seq":719,"chapter":"قصائد","title":"لعالم العلو فعل، لا خفاء به،","page":"","text":"لعالم العلو فعل، لا خفاء به، … في عالم الأرض، من وحش ومن أنس\nفالخنس الكنس الأفراد، خالقها … مدبر لاحتقار الخنس في الكنس\nإنا، بعلم إلهي، كلنا دنس، … فكيف نخلو من الأقذار والدنس؟\nفليت وشح الثريا لم تزن أفقا، … وقرطها فوق أذن الغرب لم ينس"},{"id":"diwan-maarri:720","bookId":"diwan-maarri","type":"poem","seq":720,"chapter":"قصائد","title":"والخنس الخمس، ما يخلو فتى ورع","page":"","text":"والخنس الخمس، ما يخلو فتى ورع … من مارد، في ضمير الصدر، خناس\nعداوة الحمق أعفى من صداقتهم، … فابعد من الناس تأمن شرة الناس\nقد آنسوني بإيحاشي، إذا بعدوا، … وأوحشوني، في قرب، بإيناس\nوالشر طبع، وقد بثت غريزته، … مقسومة بين أنواع وأجناس\nذكرت لفظا، وأنسيت المراد به، … من قائليه، فأنت الذاكر الناسي\nتخرص القوم في الأخبار، أو مسخوا، … فبدلوا، بعد إنس، جيل نسناس\nتصعد الجوهر الصافي، وخلفنا، … في الأرض، كثرة أوساخ وأدناس"},{"id":"diwan-maarri:721","bookId":"diwan-maarri","type":"poem","seq":721,"chapter":"قصائد","title":"سمتك أمك دينارا وقد كذبت،","page":"","text":"سمتك أمك دينارا وقد كذبت، … لو كنته، لم تكن حمال أدناس\nممزجا من دنايا، خالطت وسخا؛ … مقسما بين أنواع وأجناس\nزرت القبور، فما آنست من شبح؛ … هيهات أوحش خل بعد إيناس\nفعذ بربك من وسواس مشبهة، … خنساء، ترميك من جن بخناس\nيا والي المصر والإقليم! هل حفظت … صنائع لك، أم كل امرىء ناسي؟\nأودعت ضغنا، فلا تجحده مودعه؛ … إن الأمانة لم ترفع من الناس"},{"id":"diwan-maarri:722","bookId":"diwan-maarri","type":"poem","seq":722,"chapter":"قصائد","title":"لله لطف خفي في بريته،","page":"","text":"لله لطف خفي في بريته، … أعيا دواء المنايا كل نطيس\nما بال أشباح قوم، في الثرى، جعلت … لم تبق إلا حديثا في القراطيس؟"},{"id":"diwan-maarri:723","bookId":"diwan-maarri","type":"poem","seq":723,"chapter":"قصائد","title":"إن الجديدين قد جربت فعلهما","page":"","text":"إن الجديدين قد جربت فعلهما … جنسين ضدين من نعم ومن بيس\nحوادث الدهر ما تنفك غادية … على الأنام، بإلباس وتلبيس\nألوت بكسري، ولم تترك مرازبه، … وبالمناذر أودت، والقوابيس\nزارت حسينا، وحست بالردى حسنا، … وواجهت آل عباس بتعبيس\nالطاعنين، وغيث الركب منسكب، … إذا ازدهى الجري، أشباح الضغابيس\nفرسان خيل، إذا خلوا أعنتها، … لا يمسكون حذارا بالقرابيس"},{"id":"diwan-maarri:724","bookId":"diwan-maarri","type":"poem","seq":724,"chapter":"قصائد","title":"ذهاب عيني صان الجسم، آونة،","page":"","text":"ذهاب عيني صان الجسم، آونة، … عن التطرح في البيد الأماليس\nوأن أبيت سمير الكدر في بلد، … تطوى فلاه بتهجير وتغليس\nأهوى الحياة، وحسبي، من معائبها، … أني أعيش بتمويه وتدليس\nنطالب الدهر بالأحرار، وهو لنا … مبين عذرين: إفلاس وتفليس\nفاكتم حديثك، لا يشعر به أحد … من رهط جبريل، أو من رهط إبليس\nوقد علمت، وغيري، عن مشاهدة، … أن العلا إلف قوم، في الوغى، ليس\nويوم جيران أنسي، في سماجته، … على الخيار، وأيام الدياليس"},{"id":"diwan-maarri:725","bookId":"diwan-maarri","type":"poem","seq":725,"chapter":"قصائد","title":"إن الجديدين ما رثا ولا خلقا،","page":"","text":"إن الجديدين ما رثا ولا خلقا، … ولم يدوما على نعمى ولا بوس\nقد أنذر، المنذرين، الحتف، وافترسا … الفرسان، واقتبسا نيران قابوس"},{"id":"diwan-maarri:726","bookId":"diwan-maarri","type":"poem","seq":726,"chapter":"قصائد","title":"تعالي قدرة، وخفوت جرس،","page":"","text":"تعالي قدرة، وخفوت جرس، … أزالا عنك حرسا بعد حرس\nأرى خرسا، من الأيام، وافت … بكر لم يكن من ذات خرس\nوأشهد أنني غاو جهول، … وإن بالغت في بحث ودرس\nيجاد ثرى، وأجعل فيه غرسا، … فيفقد ساعدي، ويقوم غرسي\nوجدنا ذاهب الفتيين أفنى … ملوك الأرض من عرب وفرس\nوما البران مثلهما، ولكن … هما الأسدان يبتغيان فرسي\nسيلقى كل من حذر، المنايا، … فضع ثقليك من درع وترس\nلنا رب، وليس له نظير، … يسير أمره جبلا، ويرسي\nتظل الشمس ماهنة لديه، … فما بلقيس أم ما ست برس!\nقضاء خط، ما الأقلام فيه … بمعملة، ولم يحفظ بطرس\nغذا العرسان، بابنهما، عدوا، … أقل أذية منه ابن عرس\nلقد ألقاك، في تعب وهم، … وليد جاء بين دم وغرس\nوما الفتيان، إلا مثل نام … من الفتيان، تحت ثرى وكرس\nتشابهت الخطوب، فما تناءت … حريرة لابس وقميص برس\nوما غذي الأمير، كما رعاه … فنيق الشول من سلم وشرس\nكأن الشدو، في الأعراس، نوح، … وأصوات النوادب لهو عرس\nأنامك، أيها الدنيا، ثمار، … فما تبقى على ومد وقرس\nولو بقيت لأدركها مزيل، … بريب الدهر، من عجم وضرس\nوليس ابن الزبير صحيح رأي، … إذا ما ناب عن مدر بورس"},{"id":"diwan-maarri:727","bookId":"diwan-maarri","type":"poem","seq":727,"chapter":"قصائد","title":"ثلاث مراتب: ملك رفيع،","page":"","text":"ثلاث مراتب: ملك رفيع، … وإنسان، وجيل غير إنس\nفإن فعل الفتى خيرا، تعالى … إلى قنس الملائك، خير قنس\nوإن خفضته همته، تهاوى … إلى جنس البهائم، شر جنس"},{"id":"diwan-maarri:728","bookId":"diwan-maarri","type":"poem","seq":728,"chapter":"قصائد","title":"كأن منجم الأقوام أعمى","page":"","text":"كأن منجم الأقوام أعمى … لديه الصحف يقرؤها بلمس\nلقد طال العناء، فكم يعاني … سطورا عاد كاتبها بطمس\nدعا موسى فزال، وقام عيسى، … وجاء محمد بصلاة خمس\nوقيل يجيء دين غير هذا، … وأودى الناس بين غد وأمس\nومن لي أن يعود الدين غضا، … فينقع من تنسك، بعد خمس؟\nومهما كان، في دنياك، أمر، … فما تخليك من قمر وشمس\nوآخرها بأولها شبيه، … وتصبح في عجائبها، وتمسي\nقدوم أصاغر، ورحيل شيب، … وهجرة منزل، وحلول رمس\nلحاها الله دارا ما تداري … بمثل المين، في لجج وقمس\nإذا قلت المحال رفعت صوتي؛ … وإن قلت اليقين أطلت همسي"},{"id":"diwan-maarri:729","bookId":"diwan-maarri","type":"poem","seq":729,"chapter":"قصائد","title":"سجايا، كلها غدر وخبث،","page":"","text":"سجايا، كلها غدر وخبث، … توارثها أناس عن أناس\nيهاجر، غابه، الضرغام، كيما … ينازع ظبي رمل في كناس\nوتقبح، بعد أهليها، المغاني، … كقبح غيوبهم بعد الإناس\nيراد بك الجميل، على اقتسار، … وتذكر بالوفاء وأنت ناسي\nوحملت الذنوب قرا ضعيف، … وسرت بهن في طرق التناسي\nيفارق، شهلة، كهل وشرخ، … فواسي بالتشابه والجناس\nوما أرضاك رأي من دريد، … غداة يروم قربا من خناس"},{"id":"diwan-maarri:730","bookId":"diwan-maarri","type":"poem","seq":730,"chapter":"قصائد","title":"أمذهبة التراس لرد كيد،","page":"","text":"أمذهبة التراس لرد كيد، … صروف الدهر مذهبة التراس\nوكيف أروم، في أدب وفهم، … دراسا، والمآل هو اندراسي!\nنعم، للعضد ربتني مليكي، … وكان بحكمة منه اغتراسي\nأقام الملك حراسا عليه، … وما تنفى الحوادث باحتراس\nكأنا، في السفائن، عائمات، … وعند الموت ألقيت المراسي\nتخلف بعدنا جيل ونجم، … فأزهر شائم، وأشم راسي\nفرار من مهاريس المنايا، … بأقدام يطأن على هراس\nفكم قارن من رأس برجل؛ … وكم ألحقن من قدم براس\nفقدم من تأخر في العطايا، … وأخر من تقدم في المراس\nفنحن، وما فراستنا بمين، … كلفظ الدارمي أبي فراس\nإذا أتهمت في أيام قيظ، … فعد الناجيات إلى قراس\nأذود عن الفرائس ضاريات، … وأعلم أن غايتها افتراسي\nوقد يغنى ابن آدم، وهو حر، … بلا فرس، يعد، ولا فراس\nبيثرب حفرة خرست، ونادى … مغيبها، فأسمع ذا خراس"},{"id":"diwan-maarri:731","bookId":"diwan-maarri","type":"poem","seq":731,"chapter":"قصائد","title":"رآني، في الكرى، رجل كأني،","page":"","text":"رآني، في الكرى، رجل كأني، … من الذهب، اتخذت غشاء راسي\nقلنسوة، خصصت بها، نضارا، … كهرمز أو كملك أولي خراس\nفقلت معبرا: ذهب ذهابي، … وتلك نباهة لي في اندراسي\nنهيتك أن تعرض بنت قيل، … تقيل في الذوابل والتراس\nكأن مغارس اللثتين فجر، … يعل بماء عالية الغراس\nكأن سبيئة في الرأس، منها، … ببيت فم سبيئة بيت راس\nوروق، كالهبا وأقل، ملقى … على شوك القتاد، أو الهراس\nتنزل كاحتلاب الدر، ضاقت … مسالكه، فأتعب في المراس\nرضيت به على مضض، لعلمي … بأن فرائسي تجني افتراسي\nومن لأخيك، لو يحدو ركابا، … بأفراس يطأن على القراس؟\nأقمت، وكان بعض الحزم، يوما … لركب السفن أن تلقي المراسي\nجعلتك حارسي، فبغيت كيدي، … وهمك، حين أهجع، في احتراسي\nكراسي الهضب طيش في رجال، … ألظوا بالأسرة والكراسي"},{"id":"diwan-maarri:732","bookId":"diwan-maarri","type":"poem","seq":732,"chapter":"قصائد","title":"حمى ثلاث في حميا علة","page":"","text":"حمى ثلاث في حميا علة … خير لنفسك من ثلاثة أكؤس\nلا تشربن الخمر، فهي غوية، … ساقت بأنعمها طويل الأبؤس\nعجبا لنا ولمن مضى، أقدامنا … يمشين فوق جسومهم والأرؤس\nولسوف يفعله بنا من بعدنا؛ … إن المنون سهامها في الأقؤس\nراس الفتى زمنا، وراس حمامه، … فغدا الرئيس كأنه لم يرأس"},{"id":"diwan-maarri:733","bookId":"diwan-maarri","type":"poem","seq":733,"chapter":"قصائد","title":"غضب الأمير من الملام، وهل ترى","page":"","text":"غضب الأمير من الملام، وهل ترى … أحدا يفوز بعرضه لم يدنس؟\nأنا جاهل، إلا بأمر واحد، … ما عالمي هذا بأهل تأنس\nفتوقهم من أسود، أو أبيض، … أو أسمر ما بين ذين مجنس\nوالعنس، تعتق من أذاك، أسر من … غر العواتق، والغواني العنس\nإن الكرى في العين يحمد، والكرى … عند البرى، كمد الحسان الأنس\nأما الجواري كنسا، فيفتنني، … فمتى لحاقي بالجواري الكنس؟\nوالخلق غير الخلق، كم أنف اللأى … من صيد ضارية، بأنف أخنس"},{"id":"diwan-maarri:734","bookId":"diwan-maarri","type":"poem","seq":734,"chapter":"قصائد","title":"أنسيت حق الله أم أهملته،","page":"","text":"أنسيت حق الله أم أهملته، … شر من الناسي هو المتناسي\nنبغي الطهارة في الحياة، وإنما … أجسادنا جمل من الأدناس\nسبحان جامعها إلى غبرائها، … في حيز الأنواع والأجناس\nإن صح عقلك، فالتفرد نعمة، … ونوى الأوانس غاية الإيناس\nأبلست من وسواس حلي، خلته … إبليس، وسوس في صدور الناس\nما شمت من شماء قبل، وهل نأت … خنساء عن شيطانها الخناس؟\nأو لا، وأله العرس، عن غزل لها، … بالغزل، فهي شقيقة العرناس\nزيدت بها ألف ونون، إن من … فرس الرقاب نطقت بالفرناس\nيرمي الضراء بسيده، متختلا، … كيما يصيد له ربيب كناس\nنسخ المعاشر، فالغضنفر ثعلب … في لؤمه، والناس كالنسناس\nوتفكرت نفس اللبيب، وقد رأت، … أشخوص جن أم شخوص أناس\nعرب وعجم دائلون، وكلنا … في الظلم أهل تشابه وجناس\nفلقيت من زيد وعمرو مثل ما … لاقيت من ذنك ومن أشناس"},{"id":"diwan-maarri:735","bookId":"diwan-maarri","type":"poem","seq":735,"chapter":"قصائد","title":"لا ذنب للدنيا، فكيف نلومها؟","page":"","text":"لا ذنب للدنيا، فكيف نلومها؟ … واللوم يلحقني وأهل نحاسي\nعنب وخمر، في الإناء، وشارب، … فمن الملوم: أعاصر أم حاس؟"},{"id":"diwan-maarri:736","bookId":"diwan-maarri","type":"poem","seq":736,"chapter":"قصائد","title":"قد يرفع الله الوضيع بنكتة،","page":"","text":"قد يرفع الله الوضيع بنكتة، … كالنقع زار معاطسا بملاطس\nفاذهب لشأنك في الأمور، ولا تبت … كالنكس يجنح من حذار العاطس"},{"id":"diwan-maarri:737","bookId":"diwan-maarri","type":"poem","seq":737,"chapter":"قصائد","title":"لا ترقدوا فوق الرحال، فإنما","page":"","text":"لا ترقدوا فوق الرحال، فإنما … ترمى النجوم بغير طرف الناعس\nولرب جد مكثر، أبناؤه … يبغون عيشهم بجد تاعس\nلم يدع حظي يا لسعد في الوغى، … بل صاح في الأيام يا لمقاعس\nللموت حد، لا يقرب حينه … بصدور بيض، أو صدور مداعس"},{"id":"diwan-maarri:738","bookId":"diwan-maarri","type":"poem","seq":738,"chapter":"قصائد","title":"قد فاضت الدنيا، بأدناسها،","page":"","text":"قد فاضت الدنيا، بأدناسها، … على براياها وأجناسها\nوالشر في العالم، حتى التي … مكسبها من فضل عرناسها\nوكل حي فوقها ظالم، … وما بها أظلم من ناسها"},{"id":"diwan-maarri:739","bookId":"diwan-maarri","type":"poem","seq":739,"chapter":"قصائد","title":"ارتاحت النفس بتطهيرها؛","page":"","text":"ارتاحت النفس بتطهيرها؛ … وربها قاض بتدنيسها\nإن كانت الدنيا عروسا، ترى، … فلتنصرف عنك بتعنيسها\nكالغول غالتك بتلوينها، … بين تقديها وتبنيسها\nكم آنستني، بعد إيحاشها، … وأوحشتني، بعد تأنيسها\nضعيفها مثل فرا نيسب، … فر، حذارا، من فرانيسها\nيكفيك طعم، جنسه واحد، … أطعمة ضرت بتجنيسها\nوالثوب في أرضك من وخشها، … يغنيك عن أثواب تنيسها\nكم من عرا ناس كسا أهله … نسوتهم برس عرانيسها"},{"id":"diwan-maarri:740","bookId":"diwan-maarri","type":"poem","seq":740,"chapter":"قصائد","title":"بنت نصارى، نزلت من ذرى","page":"","text":"بنت نصارى، نزلت من ذرى … عال إلى قبر وناووس\nفي حلل غبر، وكم أشبهت … ثيابها حلة طاووس"},{"id":"diwan-maarri:741","bookId":"diwan-maarri","type":"poem","seq":741,"chapter":"قصائد","title":"أيها الرجل، إنما أنت ذئب","page":"","text":"أيها الرجل، إنما أنت ذئب … في ذئاب من المعاشر طلس\nحقك الآن، إن قلست مداما، … أن تداوى من الخمار بقلس\nشهد اللب: أن ما أفسد، المع … قول، أمر إمر، بغور وجلس\nتذر الحازم الحصيف من القو … م، غويا، كأنه حلف ألس\nوإذا لم تنل يداك اغتصابي، … رامتا بالخداع كيدي، وخلسي\nلست حلف المدام، بل حلس بيت … مثل ميت قد زايل النضو حلسي\nكيف للجسم أن يكون، إذا أب … لس إلفي العقاب، إحراق بلس؟\nما لنفسي بين النفوس معنا … ة، إذا لم تفز بطوق وسلس\nلو ينادى، في كل سوق، عليها، … ما اشتراها أخو رشاد بفلس\nقدر يسمن الحصاة، فتدعى … جبلا، أو يذيب رضوى بهلس\nكيف تهديك، للخفيات، عين، … لا ترى الآل، في مهامه ملس؟"},{"id":"diwan-maarri:742","bookId":"diwan-maarri","type":"poem","seq":742,"chapter":"قصائد","title":"قال قوم، ولا أدين بما قالوه:","page":"","text":"قال قوم، ولا أدين بما قالوه: … إن ابن آدم كابن عرس\nجهل الناس ما أبوه، على الده … ر، ولكنه مسمى بحرس\nفي حديث رواه قوم لقوم، … رهن طرس مستنسخ بعد طرس"},{"id":"diwan-maarri:743","bookId":"diwan-maarri","type":"poem","seq":743,"chapter":"قصائد","title":"أم دفر جزيت شرا، فديا","page":"","text":"أم دفر جزيت شرا، فديا … نك يغدو كالضيغم الهماس\nأقرضينا في المحل مدا بصاع، … واتركينا من فرط هذا الشماس\nأتضحى بالهم، أو أتمسى، … وتقضى من الخطوب التماسي\nمفنيا، بين ليلتين، زماني، … ليلة طلقة وأخرى عماس\nجهلت هرمس الغيوم، وما تن … جم إلا عن جرية الهرماس\nيقدر الله أن ترى كفر طاب، … حولها العاصي أو المياس\nزعموا أنني سأرجع شرخا، … كيف لي، كيف لي، وذاك التماسي؟\nوأزور الجنان أحبر فيها، … بعد طول الهمود في الأرماس\nوتزول العيون عني، إذا حم، … بعين الحياة، ثم، انغماسي\nأيما طارق أصابك، يا طا … رق، حتى مساك للغي ماسي؟\nضاع دين الداعي، فرحت تروم … الدين عند القسيس والشماس\nأتهد الإنجيل، في يوم كنس، … بعد حفظ الأسباع والأخماس؟\nهاهنا ما تريد، قد ظهر الأم … ر الذي كان، قبل، في الديماس"},{"id":"diwan-maarri:744","bookId":"diwan-maarri","type":"poem","seq":744,"chapter":"قصائد","title":"طاعم أنت، وارد عذب ماء،","page":"","text":"طاعم أنت، وارد عذب ماء، … معرس بالفتاة، حاذ، كاسي\nفاتق الله، لا تؤمن ما يق … بح من ريبة، ومن شرب كاسي"},{"id":"diwan-maarri:745","bookId":"diwan-maarri","type":"poem","seq":745,"chapter":"قصائد","title":"ظلم مستضعف، وأخذ مكوس،","page":"","text":"ظلم مستضعف، وأخذ مكوس، … وحياة في عالم منكوس\nجل رب الأنام، زيد كعمرو، … وأخو البر ليس بالموكوس\nوكذا الجمر، مثله الرجم، قد مي … ز بلفظ مغير، معكوس"},{"id":"diwan-maarri:746","bookId":"diwan-maarri","type":"poem","seq":746,"chapter":"قصائد","title":"غنيت في شرخك، أذكى من قبس،","page":"","text":"غنيت في شرخك، أذكى من قبس، … وكنت بحرا ثم أصبحت يبس\nأما تراني في الزمان، محتبس، … أعمارنا تعجز عما يقتبس\nتضيق أن يكشف فيها ما التبس، … وهي قصيرات كآيات عبس\nلو قبل النصح لساني ما نبس … -"},{"id":"diwan-maarri:747","bookId":"diwan-maarri","type":"poem","seq":747,"chapter":"قصائد","title":"أف لما نحن فيه من عنت،","page":"","text":"أف لما نحن فيه من عنت، … فكلنا في تحيل ودلس\nما النحو والشعر والكلام، وما … مرقش، والمسيب بن علس\nطالت على ساهر دجنته، … والصبح ناء، فمن لنا بعلس؟\nمثل الذئاب المطلسون، وإن … لاقوك بيضا، وفي السراح طلس\nيقنعني بلسن يمارس لي، … فإن أتتني حلاوة، فبلس\nفلس ما اخترت، إن أروح من … يسار قارون، عفة وفلس\nيدنو إليك الفتى لحاجته، … حتى إذا نال ما أراد ملس\nوالسلس، في الأذن، غير مجتلب … زينا، وكم زان في اليدين سلس\nلا تك ثقلا على جليسك في ال … قوم، فكم آكل ثنى، فقلس\nإن كنت ذا الألس، فابعدن، ولا … يخفى على الناس من جنى وألس\nوإن رزقت النهى، فأنت على ال … أصحاب حلي، تنازعوه، خلس\nواجلس بحيث انتهيت متييا، … فما يبالي الكريم أين جلس"},{"id":"diwan-maarri:748","bookId":"diwan-maarri","type":"poem","seq":748,"chapter":"قصائد","title":"لقد نأش الأقوام، في الدهر، مخلصا،","page":"","text":"لقد نأش الأقوام، في الدهر، مخلصا، … وعادوا بلا نجح، فكيف تنوش؟\nوآدم ولى، عن بنيه، بحسرة، … وودع شيث أهله، وأنوش"},{"id":"diwan-maarri:749","bookId":"diwan-maarri","type":"poem","seq":749,"chapter":"قصائد","title":"خذي من رزق ربك غير بسل،","page":"","text":"خذي من رزق ربك غير بسل، … كما أخذت من المرعى الوحوش\nوحلي مثلهن البر، حتى … تلاقين المنون، وهن حوش"},{"id":"diwan-maarri:750","bookId":"diwan-maarri","type":"poem","seq":750,"chapter":"قصائد","title":"أرى حسن البقاء لمن يرجي","page":"","text":"أرى حسن البقاء لمن يرجي … فلاحا، أو به رجل يعيش\nوما أمدي، ولا أملي بسام … إلى نجح يكون، فكم أعيش؟"},{"id":"diwan-maarri:751","bookId":"diwan-maarri","type":"poem","seq":751,"chapter":"قصائد","title":"لا خير من بعد خمسين انقضت كملا","page":"","text":"لا خير من بعد خمسين انقضت كملا … في أن تمارس أمراضا وأرعاشا\nوقد يعيش الفتى، حتى يقال له: … ما مات، عند لقاء الموت، بل عاشا"},{"id":"diwan-maarri:752","bookId":"diwan-maarri","type":"poem","seq":752,"chapter":"قصائد","title":"بشاشة أيام مضت وشبيبة،","page":"","text":"بشاشة أيام مضت وشبيبة، … بشاشة، خانت أهلها، وبشاش\nوما زال هذا الدهر يثني جوامحا … بلجم، ويثني مقرما بخشاش\nويرسل صقرا، للمنون، مسلطا، … فيظفر من أبطالنا بخشاش\nيصيب أخا النبل الصياب، ويعتدي … لدى الطعن في الهيجا، بذات رشاش\nلعمري لقد نادى، وإن كان صامتا: … مكثتم طويلا، فاظعنوا بغشاش"},{"id":"diwan-maarri:753","bookId":"diwan-maarri","type":"poem","seq":753,"chapter":"قصائد","title":"إن الطبيب وذا التنجيم ما فتئا","page":"","text":"إن الطبيب وذا التنجيم ما فتئا … مشهرين، بتقويم وكناش\nيعللان، وفي التعليل مأربة، … ويستميلان قلب المترف الناشي"},{"id":"diwan-maarri:754","bookId":"diwan-maarri","type":"poem","seq":754,"chapter":"قصائد","title":"أنعش في السماء، وذاك أمر","page":"","text":"أنعش في السماء، وذاك أمر … يدل على هلاك بنات نعش\nألم يتبينوا الخطب الموارى، … بجهل، أم قضاء الله يعشي؟"},{"id":"diwan-maarri:755","bookId":"diwan-maarri","type":"poem","seq":755,"chapter":"قصائد","title":"ألم تر طيئا وبني كلاب،","page":"","text":"ألم تر طيئا وبني كلاب، … سموا لبلاد غزة، والعريش\nولو قدروا على الطير الغوادي، … لما نهضت إلى وكر بريش\nإذا آتاك هذا الدهر ملكا، … فما لك من أقذ ولا مريش\nيجوز كون راعي الضأن قيلا، … وأن تدعى الخلافة في الحريش"},{"id":"diwan-maarri:756","bookId":"diwan-maarri","type":"poem","seq":756,"chapter":"قصائد","title":"ركوب النعش وافى بانتعاش،","page":"","text":"ركوب النعش وافى بانتعاش، … أراح من التعثر رجل عاش\nألم تعجب من الشيخ المعنى، … يقوم على انحناء وارتعاش\nيكون عن الصلاة له قعود؛ … ويمشي بالمفاوز للمعاش"},{"id":"diwan-maarri:757","bookId":"diwan-maarri","type":"poem","seq":757,"chapter":"قصائد","title":"تنكر صالح، فضباب قيس،","page":"","text":"تنكر صالح، فضباب قيس، … ضباب، يتقين من احتراش\nفقد ظعنوا، وما زجروا بصوت، … فيذعرهم، ولا طعنوا براش\nلضربة فارس، في يوم حرب، … تطير الروح منك مع الفراش\nأخف عليك من سقم طويل، … وموت، بعد ذاك، على الفراش\nوحتف مثل حتف أبي ذؤيب، … ونكز مثل نكز أبي خراش\nأرانا في مضللة، ويأبى … ردى الإنسان رشوة كل راش\nأسود الدهر تفرس كل حي، … ونحن الآن أجر في احتراش\nغدا الخصمان يجتذبان أمرا، … فقل ما شئت في كلبي هراش\nكأثمار، وما اقترشت ذنوبا، … وأرماح التنازع في اقتراش\nفطورا ينسبون إلى معد؛ … وطورا ينسبون إلى إراش"},{"id":"diwan-maarri:758","bookId":"diwan-maarri","type":"poem","seq":758,"chapter":"قصائد","title":"أوقدت نارا بافتكارك أظهرت","page":"","text":"أوقدت نارا بافتكارك أظهرت … نهجا، وأنت على سناها عاش\nمتكهن، ومنجم، ومعزم، … وجميع ذاك تحيل لمعاش\nقد أرعشت يد سائل من كبرة، … ولنائل بسطت على الإرعاش"},{"id":"diwan-maarri:759","bookId":"diwan-maarri","type":"poem","seq":759,"chapter":"قصائد","title":"ما أنا بالواغل، يوما، على ال","page":"","text":"ما أنا بالواغل، يوما، على ال … شرب، ولا مثلي بالوارش\nلا أعرش الجفر ولا النخل، في الدن … يا، وما تبقى يد العارش\nلست نسيبا لقريش، ولا … أتبع إثر الرجل القارش\nوالنسل فرش لهموم الفتى؛ … والعقل مسلوب من الفارش\nلولا أبو الضب وأجداده، … لم يرتقب كيدا من الحارش\nفاجعل حذائي خشبا، إنني … أريد إبقاء على الدارش\nكان أديما لمجس الأذى، … يلتمس الرزق مع الجارش"},{"id":"diwan-maarri:760","bookId":"diwan-maarri","type":"poem","seq":760,"chapter":"قصائد","title":"خمسون قد عشتها، فلا تعش،","page":"","text":"خمسون قد عشتها، فلا تعش، … والنعش لفظ من قولك انتعش\nوالموت خير لمن تأمله … من عمر جاري اللعاب، مرتعش\nلا يقرأ السطر بالنهار، وقد … كان يجلي كالصقر ثم عشي"},{"id":"diwan-maarri:761","bookId":"diwan-maarri","type":"poem","seq":761,"chapter":"قصائد","title":"لم يكن لي عرش، فيثلم عرشي،","page":"","text":"لم يكن لي عرش، فيثلم عرشي، … كم جروح جرحتها ذات أرش\nمقنعي، في الزمان، ستري ودفني، … من لباس راق العيون وفرش\nقد شربت المياه بالخزف الوخ … ش، غني عن محكمات بجرش\nوتغنيت في الأمور، فنابت … قدمي عن ركوب دهم وبرش\nأم دفر! إني هويتك جدا، … أي ضب تركت من غير حرش!\nخففي الهمز، في النوائب، عني، … واحمليني على قراءة ورش"},{"id":"diwan-maarri:762","bookId":"diwan-maarri","type":"poem","seq":762,"chapter":"قصائد","title":"ما بال رأسك لا تبش بلونه","page":"","text":"ما بال رأسك لا تبش بلونه … عين، وبات بكل ذي نظر يبش\nيمسي، كبعض الروم، أبيض باردا، … ولقد يكون كأنه بعض الحبش"},{"id":"diwan-maarri:763","bookId":"diwan-maarri","type":"poem","seq":763,"chapter":"قصائد","title":"إنصح، فإن النصح للمرء مث","page":"","text":"إنصح، فإن النصح للمرء مث … ل الغيث، أروى بوابل وبغش\nوراقب الله أن تغش، فقد … يفسد رأي اللبيب حين يغش"},{"id":"diwan-maarri:764","bookId":"diwan-maarri","type":"poem","seq":764,"chapter":"قصائد","title":"تزوجتها، وهي، فيما تظن","page":"","text":"تزوجتها، وهي، فيما تظن … شمس الضحى، بأواق، ونش\nينوش بها القلب أوطاره، … فليت مآربه لم تنش\nعروسك أفعى، فهب قربها، … وخف من سليلك، فهو الحنش\nتنشى الفتى بلذيذ المدام، … فكان الخمار عقيب التنش\nإذا لم يطيبك حسن الثناء، … فلا خير في مسك قوم ينش\nلعمري، لقد أمن العائذون، … وعونش ذو بغضة، فاعتنش\nفيا قس وقع برزق الخطي … ب، وانظر بمسجدنا يا منش"},{"id":"diwan-maarri:765","bookId":"diwan-maarri","type":"poem","seq":765,"chapter":"قصائد","title":"صوفية، شهدت، للعقل، نسبتهم،","page":"","text":"صوفية، شهدت، للعقل، نسبتهم، … بأنهم ضأن صوف، نطحها يقص\nلا ترقصن مهيرات مكرمة، … فللمهارى، قديما، يعرف الرقص\nولا يبينن: أفي أعناقها غيد، … لمن تأمل، أم أزرى بها الوقص\nتواجد القوم من نسك، بزعمهم، … والله يشهد ما زادوا، كما نقصوا\nلا نال خيرا فتى أمست أنامله … مداري السرح، موصولا بها العقص"},{"id":"diwan-maarri:766","bookId":"diwan-maarri","type":"poem","seq":766,"chapter":"قصائد","title":"غنينا في الحياة ذوي اضطرار،","page":"","text":"غنينا في الحياة ذوي اضطرار، … كطير السجن أعوزها الخلاص\nتصيب القوم، من نوب الليالي، … سهام، لا تنهنهها الدلاص\nفهل في الأرض من فرج لحر، … تزجى في مطالبه القلاص؟"},{"id":"diwan-maarri:767","bookId":"diwan-maarri","type":"poem","seq":767,"chapter":"قصائد","title":"أخو الحرب كالوافر الدائري،","page":"","text":"أخو الحرب كالوافر الدائري، … أعضب في الخطب أو أعقص\nيرى كامل سالمه كاملا … فيخزل، بالدهر، أو يوقص\nومن لك بالعيش في غرة، … تظل مطاياك لا ترقص؟\nوإنك مقتضب الشعر، لا … يزاد بحال، ولا ينقص"},{"id":"diwan-maarri:768","bookId":"diwan-maarri","type":"poem","seq":768,"chapter":"قصائد","title":"سواء على هذا الحمام أضيغما","page":"","text":"سواء على هذا الحمام أضيغما … أزار المنايا، أم توفى بها درصا\nفإن تتركوا الموت الطبيعي يأتكم، … ولم تستعينوا لا حساما ولا خرصا\nوكان لكم حرص على العيش بين، … فما لكم حمتم، على ضده، حرصا؟"},{"id":"diwan-maarri:769","bookId":"diwan-maarri","type":"poem","seq":769,"chapter":"قصائد","title":"إذا قص آثاري الغواة ليحتذوا","page":"","text":"إذا قص آثاري الغواة ليحتذوا … عليها، فودي أن أكون قصيصا\nمن الطير، أو نبتا بأرض مضلة، … وإلا فظبيا، في الظباء، حصيصا\nوكم ملك، في الأرض، لاقى خصاصة، … وكان، بإكرام العفاة، خصيصا\nإليك، فإني قد أقامت ركائبي … لأرفع سيرا، للحمام، نصيصا"},{"id":"diwan-maarri:770","bookId":"diwan-maarri","type":"poem","seq":770,"chapter":"قصائد","title":"غدا الحق في دار، تحرز أهلها","page":"","text":"غدا الحق في دار، تحرز أهلها … وطفت بهم، كالسارق المتلصص\nفقالوا ألا اذهب! ما لمثلك عندنا … مقيل، وحاذر من يقين مفصص\nألم ترنا رحنا مع الطير بالهدى، … وأنت طريح، ذو جناح مقصص؟\nإذا شهر الإنسان بالدين لم تكن … له رتبة المستأنس، المتخصص\nفطبعك سلطان، لعقلك، غالب، … تداوله أهواؤه بالتشصص\nسقيت شرابا لم تهنأ ببرده، … فعنيت، من بعد الصدى، بالتغصص"},{"id":"diwan-maarri:771","bookId":"diwan-maarri","type":"poem","seq":771,"chapter":"قصائد","title":"تضاعف همي أن أتتني منيتي،","page":"","text":"تضاعف همي أن أتتني منيتي، … ولم تقض حاجي بالمطايا الرواقص\nوما عالمي، إن عشت فيه، بزائد، … ولا هو، إن ألقيت منه، بناقص"},{"id":"diwan-maarri:772","bookId":"diwan-maarri","type":"poem","seq":772,"chapter":"قصائد","title":"تكذب قوم يستعيرون سؤددا،","page":"","text":"تكذب قوم يستعيرون سؤددا، … وتلك سجايا للنفوس النواقص\nإذا مت لم أحفل بما قال عائبي؛ … وهل ضر تربا رميه بالمشاقص؟"},{"id":"diwan-maarri:773","bookId":"diwan-maarri","type":"poem","seq":773,"chapter":"قصائد","title":"وقعنا، في الحياة، بلا اختيار،","page":"","text":"وقعنا، في الحياة، بلا اختيار، … وخالقنا يعجل بالخلاص\nركبنا فوق أكتاد الليالي؛ … فواها، ما أخبك من قلاص!\nونبل الدهر تنفذ كل ترس، … وتسلك بين أثناء الدلاص\nفهون ما أتيح من الرزايا، … وما لاقيت من لص ولاص"},{"id":"diwan-maarri:774","bookId":"diwan-maarri","type":"poem","seq":774,"chapter":"قصائد","title":"لقد حرصوا على الدنيا، فبادوا","page":"","text":"لقد حرصوا على الدنيا، فبادوا … فلا تك، في الحياة، من الحراص\nوأودعهم، على كره، ثراهم؛ … فأرض القوم خالية العراص\nتصدق من أتاك بغير صدق، … وما أولى أمينك باختراص\nوليس أخوك إلا ليث غاب، … يسور إلى افتراسك بافتراص"},{"id":"diwan-maarri:775","bookId":"diwan-maarri","type":"poem","seq":775,"chapter":"قصائد","title":"قد عمنا الغش، وأزرى بنا","page":"","text":"قد عمنا الغش، وأزرى بنا … في زمن أعوز فيه الخصوص\nإن نصح السلطان في أمره، … رأى ذوي النصح بعين الشصوص\nوكل من فوق الثرى خائن، … حتى عدول المصر مثل اللصوص"},{"id":"diwan-maarri:776","bookId":"diwan-maarri","type":"poem","seq":776,"chapter":"قصائد","title":"يكاد المشيب ينادي الغوي:","page":"","text":"يكاد المشيب ينادي الغوي: … ويحك أتعبتني بالمقص\nوتزعم أنك فيما فعلت، … على أثر، من رشيد، تقص\nوهل تلك من شيم الراشدين؟ … وما زاد في كل حال نقص\nويا ناظرا في نصول الخضاب، … شغلك عن لمم أو عقص\nإذا ستر الناس عنك الأمور، … فلا تك عن أمرهم ذا تقص"},{"id":"diwan-maarri:777","bookId":"diwan-maarri","type":"poem","seq":777,"chapter":"قصائد","title":"ظمئت إلى ماء الشباب، ولم يزل","page":"","text":"ظمئت إلى ماء الشباب، ولم يزل … يغور على طول المدى ويغيض\nتراه مع الإخوان لا تستطيعه؛ … حبيب متى يبعد، فأنت بغيض"},{"id":"diwan-maarri:778","bookId":"diwan-maarri","type":"poem","seq":778,"chapter":"قصائد","title":"قد رضت نفسي، حتى ذل جامحها،","page":"","text":"قد رضت نفسي، حتى ذل جامحها، … فما أصاحب صعب النفس، ما ريضا\nيا ألسنا كسيوف الهند خلقتها، … ما لي رأيتك أشبهت المقاريضا؟\nإن الغمود إذا سلت صوارمها، … قلن اليقين، وألغين المعاريضا"},{"id":"diwan-maarri:779","bookId":"diwan-maarri","type":"poem","seq":779,"chapter":"قصائد","title":"بعض الرجال، كقبر الميت، تمنحه","page":"","text":"بعض الرجال، كقبر الميت، تمنحه … أعز شيء، ولا يعطيك تعويضا\nوالسمح في العدم مثل الصخر في ديم، … يخضر شيئا، ولا يسطيع ترويضا\nقوض خياما على الدنيا، فإن بها … خلائقا، أوجبت للحر تقويضا\nوخذ لنفسك، من عمر تضيعه، … جزءا، ولا ترسلن الأمر تفويضا\nخصتك نخلة أرض أطعمتك جنى، … فاجعل لها دون نخل القوم تحويضا"},{"id":"diwan-maarri:780","bookId":"diwan-maarri","type":"poem","seq":780,"chapter":"قصائد","title":"بئس الشهادة، إن سألت، شهادة،","page":"","text":"بئس الشهادة، إن سألت، شهادة، … يرجو الملاطف قرضها وقراضها\nولشر أصحاب الرجال عصابة … تعطيك دون ثيابها أعراضها\nإن الليالي ما تصرم عنهم، … إلا لتبلغ فيهم أغراضها\nأوما رأيت جنائزا محمولة، … تمشي الغواة أمامها وعراضها\nتبغي من الآمال ذلة مسعف، … تلك المصاعب أتعبت من راضها\nبكر الطبيب على الدواء، وللردى، … كأس، تعم صحاحها ومراضها"},{"id":"diwan-maarri:781","bookId":"diwan-maarri","type":"poem","seq":781,"chapter":"قصائد","title":"لا أسأل المرء قرضا من شهادته،","page":"","text":"لا أسأل المرء قرضا من شهادته، … ولا أروح على شيبي بمقراض\nإذا غدوت ببطن الأرض مضطجعا، … فثم أفقد أوصابي وأمراضي\nتيمموا بترابي، عل فعلكم، … بعد الهمود، يوافيني بأغراضي\nوإن جعلت بحكم الله في خزف، … يقضي الطهور، فإني شاكر راض\nجواهر ألفتها قدرة عجب، … وزايلتها، فصارت مثل أعراض"},{"id":"diwan-maarri:782","bookId":"diwan-maarri","type":"poem","seq":782,"chapter":"قصائد","title":"أما والله لو أني تقي،","page":"","text":"أما والله لو أني تقي، … لما آخيت مثلك، وهو قاض\nولكن بت شرا منك فعلا، … فأغنيت الوداد عن التقاضي\nفلا تنقض حبال العهد مني، … فما تخشى، لدي، من انتقاضي"},{"id":"diwan-maarri:783","bookId":"diwan-maarri","type":"poem","seq":783,"chapter":"قصائد","title":"رياضك غير دائمة، فروضي،","page":"","text":"رياضك غير دائمة، فروضي، … نوافل بعد إحكام الفروض\nأقارضك الشهادة، غير بر، … كلانا طاح في تلك القروض\nوما يأتيك بالأغراض خل، … ولا شد الرواحل بالغروض\nوجسم المرء للأعراض ربع، … فهل زكاه تزكية العروض؟\nمغانيه محيلات المعاني، … كبيت الشعر قطع بالعروض"},{"id":"diwan-maarri:784","bookId":"diwan-maarri","type":"poem","seq":784,"chapter":"قصائد","title":"ما يشأ ربك يفعل قادرا،","page":"","text":"ما يشأ ربك يفعل قادرا، … جل عن كل مقال واعتراض\nقد تجمعنا على غير هدى، … وتفرقنا على غير تراض\nوتقارضنا شهادات التقى، … ثم صرنا لزوال وانقراض\nواستعارت صحة أجسامنا، … واستعانت بمودات مراض"},{"id":"diwan-maarri:785","bookId":"diwan-maarri","type":"poem","seq":785,"chapter":"قصائد","title":"أوف ديوني، وخل أقراضي،","page":"","text":"أوف ديوني، وخل أقراضي، … مثلك لا يهتدي لأغراضي\nما لبني آدم غدوا أمما، … لهم عروض بغير أعراض؟\nكم رجل ماطلت منيته، … قليل مال كثير أمراض\nوهو بدنياه مولع كلف، … يقنع، من صيدها، بمعراض\nحلت، نحاس الناموس، فضة شي … ب لك، حلت حديد مقراض\nلم ترض ذاك الفتاة عنك، ولا … ربك، فيما فعلته، راض\nقصا وخضبا لأعين لمح، … ولم يزدهن غير إعراض"},{"id":"diwan-maarri:786","bookId":"diwan-maarri","type":"poem","seq":786,"chapter":"قصائد","title":"إنما المرء نطفة، ومداه","page":"","text":"إنما المرء نطفة، ومداه … خطفة، ليس عطفة حين يمضي\nوكأن الأنام سرح حسام، … يتسلى بخلة بعد حمض\nصاح! إن جال في الحوادث فكري، … صاح يا للأسى ينفر غمضي!\nإن تراعوا، من المراعاة، ربا … لا تراعوا، بالروع، من ذات رمض"},{"id":"diwan-maarri:787","bookId":"diwan-maarri","type":"poem","seq":787,"chapter":"قصائد","title":"أعبد الله، لا تظاهر لمن جا","page":"","text":"أعبد الله، لا تظاهر لمن جا … ورت، يوما، بسنة أو برفض\nرب خفض أتاك من بعد بأسا … ء، وبؤس لقيته غب خفض\nقد نفضت السهام أبغي المقايي … س، فلم يثبت الرمية نفضي\nأيها الناظرون! هذا قضاء، … هل علمتم إلى م أصبح يفضي؟"},{"id":"diwan-maarri:788","bookId":"diwan-maarri","type":"poem","seq":788,"chapter":"قصائد","title":"أرى جوهرا حل فيه عرض،","page":"","text":"أرى جوهرا حل فيه عرض، … تبارك خالقه ما الغرض؟\nإذا راض، في نسك، قلبه، … غدا، وهو صعب، كأن لم يرض\nيداوى المريض، كيما يصح، … وهل صحة الجسم إلا مرض؟\nفلا تتركن ورعا في الحياة، … وأد، إلى ربك، المفترض\nفكم ملك شيد المكرمات، … ونال بها الصيت، ثم انقرض"},{"id":"diwan-maarri:789","bookId":"diwan-maarri","type":"poem","seq":789,"chapter":"قصائد","title":"غدوت أسيرا، في الزمان، كأنني","page":"","text":"غدوت أسيرا، في الزمان، كأنني … عروض طويل، قبضها ليس يبسط\nوإن كنت، في بعض الحكومة، قاسطا، … فغيري، من هذي البرية، أقسط\nوأوتاد أبيات من الشعر حزته، … كأوتاد بيت الشعر حين توسط"},{"id":"diwan-maarri:790","bookId":"diwan-maarri","type":"poem","seq":790,"chapter":"قصائد","title":"غدت، من تميم، أسرة فوق أرضها،","page":"","text":"غدت، من تميم، أسرة فوق أرضها، … وحاجبها تحت الثرى، ولقيطها\nلعمري! لقد أضحت فوارس منهم، … كأن لم يكن مروتها ووقيطها\nفقد بدلوا أجداثهم من سروجهم، … فأنبت روضا طلها وسقيطها"},{"id":"diwan-maarri:791","bookId":"diwan-maarri","type":"poem","seq":791,"chapter":"قصائد","title":"أين امرؤ القيس والعذارى،","page":"","text":"أين امرؤ القيس والعذارى، … إذ مال، من تحته، الغبيط\nله كميتان: ذات كأس … تزبد، والسابح الربيط\nيباكر الصيد بالمذاكي، … فيأنس الموحش الهبيط\nاستنبط العرب في الموامي، … بعدك، واستعرب النبيط\nكأن دنياك ماء حوض … آخره آجن خبيط\nوالقوت فيها لنا مباح … لو أنه، من دم، عبيط"},{"id":"diwan-maarri:792","bookId":"diwan-maarri","type":"poem","seq":792,"chapter":"قصائد","title":"إذا قلت فوائدنا جفينا،","page":"","text":"إذا قلت فوائدنا جفينا، … بذاك يزم أينقه الخليط\nولم أوثر لمصباحي خمودا، … ولكن خان، موقده، السليط"},{"id":"diwan-maarri:793","bookId":"diwan-maarri","type":"poem","seq":793,"chapter":"قصائد","title":"تنوط بنا الحوادث كل ثقل،","page":"","text":"تنوط بنا الحوادث كل ثقل، … ورب الناس يصرف ما تنوط\nوليس بحانط رمثي بأرض، … إذا ما قارن الكفن الحنوط\nولم أقنط لسوء الفعل مني، … وحق لمثل فاعلها القنوط"},{"id":"diwan-maarri:794","bookId":"diwan-maarri","type":"poem","seq":794,"chapter":"قصائد","title":"إذا انفرد الفتى أمنت عليه","page":"","text":"إذا انفرد الفتى أمنت عليه … دنايا، ليس يؤمنها الخلاط\nفلا كذب يقال، ولا نميم، … ولا غلط يخاف، ولا غلاط\nوكم نهض امرؤ من بين قوم، … وفي هاديه، من خزي، علاط"},{"id":"diwan-maarri:795","bookId":"diwan-maarri","type":"poem","seq":795,"chapter":"قصائد","title":"وجدت الناس عمهم سقوط،","page":"","text":"وجدت الناس عمهم سقوط، … وكل الخيل يدركها سقاط\nغدت للقاطها نسوان قوم، … وأفراس الأمير لها لقاط\nأما يعطي ذوي الحاجات حقا، … وفوق شواته السيف السقاط؟"},{"id":"diwan-maarri:796","bookId":"diwan-maarri","type":"poem","seq":796,"chapter":"قصائد","title":"أجاهد بالظهارة حين أشتو،","page":"","text":"أجاهد بالظهارة حين أشتو، … وذاك جهاد مثلي والرباط\nمضى كانون ما استعملت فيه … حميم الماء، فاقدم يا سباط\nتشابه، أنفس الحشرات، نفسي، … يكون لهن بالصيف ارتباط\nلقد رقد المعاشر في ثراهم، … فما هب الجعاد ولا السباط"},{"id":"diwan-maarri:797","bookId":"diwan-maarri","type":"poem","seq":797,"chapter":"قصائد","title":"ماذا يريبك من غراب طار عن","page":"","text":"ماذا يريبك من غراب طار عن … وكر، يكون به لباز مسقط؟\nوافضحتا! لك في شمالك، غاديا، … عود المراة، وفي يمينك ملقط\nأوما قرأت سجل دهرك ناطقا … بالهلك، يشكل بالخطوب وينقط؟"},{"id":"diwan-maarri:798","bookId":"diwan-maarri","type":"poem","seq":798,"chapter":"قصائد","title":"أما اليقين، فإننا سكن البلى","page":"","text":"أما اليقين، فإننا سكن البلى … ولنا، هناك، جماعة فراط\nولكل دهر حلية من أهله، … ما فيهم جنف، ولا إفراط\nوالغيد مختلف مواضع حليها، … وتناءت الأحجال والأقراط\nكم لاحت الأشراط في جنح الدجى، … فمتى تبين لبعثنا أشراط؟\nوكأن هذا الخلق أهل جهنم، … ولهم، من الموت الزؤام، سراط\nلو لم تكن مثل الجماعة زائفا، … لم يشجك الدينار والقيراط"},{"id":"diwan-maarri:799","bookId":"diwan-maarri","type":"poem","seq":799,"chapter":"قصائد","title":"كلامك ملتبس لا يبين","page":"","text":"كلامك ملتبس لا يبين … كالخط أغفله الناقط\nنصحتك لا تعترف يا أخي … بي، فأنا الرجل الساقط\nولو كنت ملقى بظهر الطريق، … لم يلتقط مثلي اللاقط"},{"id":"diwan-maarri:800","bookId":"diwan-maarri","type":"poem","seq":800,"chapter":"قصائد","title":"الحكم لله، فالبث مفردا أبدا،","page":"","text":"الحكم لله، فالبث مفردا أبدا، … ولا تكن بصنوف الناس مختلطا\nولست أدري سوى أني أرى رجلا … يرب نسلا لريب الدهر، قد غلطا"},{"id":"diwan-maarri:801","bookId":"diwan-maarri","type":"poem","seq":801,"chapter":"قصائد","title":"حملت ثقل الليالي في بني زمني،","page":"","text":"حملت ثقل الليالي في بني زمني، … فقد ظللنا بذاك الثقل نحاطا\nلو حاطنا الله لم نحفل بمرزية، … وكيف يخشى رزايا الدهر من حاطا؟"},{"id":"diwan-maarri:802","bookId":"diwan-maarri","type":"poem","seq":802,"chapter":"قصائد","title":"أما الإله، فأمر لست مدركه،","page":"","text":"أما الإله، فأمر لست مدركه، … فاحذر لجيلك، فوق الأرض، إسخاطا\nوالشيب قد خطط الفودين عن عرض، … وما عدا جدة الأيام ما خاطا"},{"id":"diwan-maarri:803","bookId":"diwan-maarri","type":"poem","seq":803,"chapter":"قصائد","title":"يا قلب لا أدعوك في أكرومة،","page":"","text":"يا قلب لا أدعوك في أكرومة، … إلا تقاعس دونها وتباطا\nوالموت حاس ما تعيف آجنا، … وتضيف الأعراب والأنباطا\nولقد حفرت عن اليقين بخاطر، … ما كاد يبلغ حفره الإنباطا\nوليدركن جعادنا وسباطنا، … ما أدرك النعمان في ساباطا\nأيفكني هذا الحمام، تفضلا، … فالعيش أوثقني، وشد رباطا"},{"id":"diwan-maarri:804","bookId":"diwan-maarri","type":"poem","seq":804,"chapter":"قصائد","title":"هل يفرح الناعب الغداف بسقيا ال","page":"","text":"هل يفرح الناعب الغداف بسقيا ال … أرض، إن طالع الدجى سقطا\nيلهم أن التراب، إن وقع ال … غيث، أتى بالحبوب، فالتقطا\nسبح لله ناعب صوته غا … ق، وكدرية تصيح قطا\nولو جزينا على خلائقنا، … أمسك عنا الحيا، فما نقطا"},{"id":"diwan-maarri:805","bookId":"diwan-maarri","type":"poem","seq":805,"chapter":"قصائد","title":"المرء يقدم دنياه، على خطر،","page":"","text":"المرء يقدم دنياه، على خطر، … بالكره منه، وينآها على سخط\nيخيط إثما إلى إثم، فيلبسه، … كأن مفرقه بالشيب لم يخط"},{"id":"diwan-maarri:806","bookId":"diwan-maarri","type":"poem","seq":806,"chapter":"قصائد","title":"أعرض عن الثور، مصبوغا أطايبه","page":"","text":"أعرض عن الثور، مصبوغا أطايبه … بالزعفران، إلى ثور من الأقط\nفالرزق يهتف يا إنس اعملوا وكلوا؛ … يا أيها الظبي رد، يا طائر التقط\nوالحتف مثل غمام جاد وابله؛ … والناس يدعون، لو أغنى الدعاء، قط\nوما يسيل، ولكن ينبري نقطا، … حتى يغرق أهل الأرض بالنقط\nأسقط بما شئت، أو طر يا غراب لنا، … فإنما نحن، في الدنيا، من السقط"},{"id":"diwan-maarri:807","bookId":"diwan-maarri","type":"poem","seq":807,"chapter":"قصائد","title":"الحمد لله، أضحى الناس في عجب،","page":"","text":"الحمد لله، أضحى الناس في عجب، … مستهترين بإفراط وتفريط\nوالزند في حب أسوار يسوره، … كالأذن في حب تشنيف وتقريط\nيبغي الحظوظ أناس من ظبى وقنا، … وآخرون بغوها بالمشاريط\nفجد بعرف، ولو بالنزر، محتسبا، … إن القناطير تحوى بالقراريط"},{"id":"diwan-maarri:808","bookId":"diwan-maarri","type":"poem","seq":808,"chapter":"قصائد","title":"أستغفر الله، رب مدكر","page":"","text":"أستغفر الله، رب مدكر … أخطأ في مدة مضت، وخطي\nخاط إليه، الخروق، زائره، … وجفنه بالرقاد لم يخط\nأسخطه البين، ثم أرضته عقباه، … فنال الرضا من السخط\nذاب عليه لعاب لاعبة، … بصارم للسراب ممتخط"},{"id":"diwan-maarri:809","bookId":"diwan-maarri","type":"poem","seq":809,"chapter":"قصائد","title":"يا ربة الصمت! أنت آمنة،","page":"","text":"يا ربة الصمت! أنت آمنة، … إذا هفا ناطق، من السقط\nوصلك بالنار والشنار، فقد … عفناه، إذ قط شعره، فقط\nإنا التقطنا بالخرق طيف كرى، … بل كان صحبي له من اللقط\nألطف به زار آقطي رهج، … ما شعروا كيف صنعة الأقط\nلو سار ذاك الخيال في مطر، … لم يخش فيه من بلة النقط\nبميت غادرته أينقهم، … من وطئها، مثل حية الرقط\nينبه مغفي فلاته بقطا، … بين أيادي رواحل بقط"},{"id":"diwan-maarri:810","bookId":"diwan-maarri","type":"poem","seq":810,"chapter":"قصائد","title":"طرق الغي سهلة، واسعات،","page":"","text":"طرق الغي سهلة، واسعات، … وطريق الهدى كسم الخياط\nمطلع شق، لا تكلفه الضم … ر إلا مضروبة بالسياط\nكيف لي بالسهوب يسلكها الرك … ب، حياتي فيها بقطع النياط\nعاريات من النبات، ولكن … ألبست من سرابها كالرياط"},{"id":"diwan-maarri:811","bookId":"diwan-maarri","type":"poem","seq":811,"chapter":"قصائد","title":"قطعت البلاد، فمن صاعد","page":"","text":"قطعت البلاد، فمن صاعد … بغيث النوال، ومن هابط\nتمد عصاك إلى النابحات، … فيعجبن من جأشك الرابط\nوتغبط كلا على ما حواه، … وما لك في العيش من غابط\nوقفت على كل باب، رأيت، … حتى نهاك أبو ضابط"},{"id":"diwan-maarri:812","bookId":"diwan-maarri","type":"poem","seq":812,"chapter":"قصائد","title":"أعوذ بربي من سخطه،","page":"","text":"أعوذ بربي من سخطه، … وتفريط نفسي وإفراطها\nتدين الملوك، وإن عظمت، … لما شاء، من خلف أفراطها\nوتجري المقادير منه على … عظام النجوم، وأشراطها\nوما دفعت حكماء الرجال … حتفا، بحكمة بقراطها\nولكن يجيء قضاء يري … ك أخا غيها مثل سقراطها\nفلا تبخلن يد كزة، … على المستميح، بقيراطها"},{"id":"diwan-maarri:813","bookId":"diwan-maarri","type":"poem","seq":813,"chapter":"قصائد","title":"يغني الفتى ملبس يستره،","page":"","text":"يغني الفتى ملبس يستره، … وقوته في دجى الظلام فقط\nوحظه أن يكون منفردا، … كطائر لا يراع أين سقط\nلا يلقط الحب من زروعهم، … وإن رأى حبة النبات لقط\nفذاك لو طار في غمامته، … لما أصاب الجناح منه نقط"},{"id":"diwan-maarri:814","bookId":"diwan-maarri","type":"poem","seq":814,"chapter":"قصائد","title":"هل تحفظ الأرض موتاها، وأهلهم،","page":"","text":"هل تحفظ الأرض موتاها، وأهلهم، … لما بدا اليأس، ألغوهم، فما حفظوا\nإن شاء ربك جازاهم بفعلهم … واللفظ، حين تثار الأقبر اللفظ"},{"id":"diwan-maarri:815","bookId":"diwan-maarri","type":"poem","seq":815,"chapter":"قصائد","title":"من الناس من لفظه لؤلؤ،","page":"","text":"من الناس من لفظه لؤلؤ، … يبادره اللقط، إذ يلفظ\nوبعضهم قوله كالحصى، … يقال فيلغى، ولا يحفظ"},{"id":"diwan-maarri:816","bookId":"diwan-maarri","type":"poem","seq":816,"chapter":"قصائد","title":"بتم هجودا في الغنى، ولو انتهت","page":"","text":"بتم هجودا في الغنى، ولو انتهت … هذي النفوس، لبتم أيقاظا\nصافت سهامكم، وقرطس غيكم، … فشتا بأربعة الصدور وقاظا"},{"id":"diwan-maarri:817","bookId":"diwan-maarri","type":"poem","seq":817,"chapter":"قصائد","title":"ابن خمسين ضمه عقد تسعين،","page":"","text":"ابن خمسين ضمه عقد تسعين، … يزجي له، من الموت، حظا\nيتشكى فظاظة من حياة؛ … وأظن الحمام منها أفظا\nليخف صاحب الديانة والصو … ن مقالا من جاهل، يتحظى\nيسبك الصائغ الزجاج، ولا يس … تطيع سبكا للدر، إن يتشظى\nيتلظى الفتى، وكم شبت الشع … رى وقودا، في حندس يتلظى\nكيف لي أن أكون في رأس شما … ء، وأرعى في الوحش آسا ومظا؟"},{"id":"diwan-maarri:818","bookId":"diwan-maarri","type":"poem","seq":818,"chapter":"قصائد","title":"إذا كنت بالله المهيمن واثقا،","page":"","text":"إذا كنت بالله المهيمن واثقا، … فسلم إليه الأمر، في اللفظ واللحظ\nيدبرك خلاق يدير مقادرا، … تخطيك إحسان الغمائم، أو تحظي"},{"id":"diwan-maarri:819","bookId":"diwan-maarri","type":"poem","seq":819,"chapter":"قصائد","title":"رضيت ملاوة، فوعيت علما،","page":"","text":"رضيت ملاوة، فوعيت علما، … وأحفظني الزمان، فقل حفظي\nإذا ما قلت نثرا، أو نظيما، … تتبع سارقو الألفاظ لفظي"},{"id":"diwan-maarri:820","bookId":"diwan-maarri","type":"poem","seq":820,"chapter":"قصائد","title":"ما زلت في الغمرات لست بخالص","page":"","text":"ما زلت في الغمرات لست بخالص … منهن، فاشت، على رجائك، أو قظ\nومن البرية من يعيب، بجهله، … أهل السنات، وليس بالمتيقظ"},{"id":"diwan-maarri:821","bookId":"diwan-maarri","type":"poem","seq":821,"chapter":"قصائد","title":"الموت حظ لمن تأمله،","page":"","text":"الموت حظ لمن تأمله، … وليس في العيش أن تؤمل حظ\nلا سيما للذي يخط عليه ال … وزر إن قال، أو رنا ولحظ"},{"id":"diwan-maarri:822","bookId":"diwan-maarri","type":"poem","seq":822,"chapter":"قصائد","title":"إذا أنت لم تحضر مع القوم مسجدا،","page":"","text":"إذا أنت لم تحضر مع القوم مسجدا، … فصل إلى أن يقضي الجمعة الجمع\nولا تأمنن أن يحشر، اليوم، ربه؛ … له بصر، من قدرة، وله سمع\nفيخبر بالتقصير عنك مؤنبا، … وتسكب دمعا، حيث لا ينفع الدمع\nهنالك لا ترجو صريخا مزعزعا … صدور عوال، فوقها، للردى، لمع"},{"id":"diwan-maarri:823","bookId":"diwan-maarri","type":"poem","seq":823,"chapter":"قصائد","title":"إذا خطب الزهراء كهل وناشىء،","page":"","text":"إذا خطب الزهراء كهل وناشىء، … فإن الصبا فيها شفيع مشفع\nولا يزهدنها عدمه، إن مده … لأبرك من صاع الكبير، وأنفع\nوما لأخي ستين قدرة سائر … إليها، ولكن عجزه ليس يدفع\nويخفض، في كل المواطن، ذمه، … وإن كان يدنى، في المحل، ويرفع"},{"id":"diwan-maarri:824","bookId":"diwan-maarri","type":"poem","seq":824,"chapter":"قصائد","title":"ألا يكشف القصاص وال، فإن هم","page":"","text":"ألا يكشف القصاص وال، فإن هم … أتوا بيقين، فليقصوا لينفعوا\nوإن خرصوا مينا، بغير تحرج، … فأوجب شيء أن يهانوا ويصفعوا\nومن جاء منهم واثقا بشفاعة، … فكم شافع في هين، لا يشفع\nسعوا لفساد الدين في كل مسجد، … فما بالهم لم يستضاموا ويدفعوا؟"},{"id":"diwan-maarri:825","bookId":"diwan-maarri","type":"poem","seq":825,"chapter":"قصائد","title":"هي النفس، عناها من الدهر فاجع","page":"","text":"هي النفس، عناها من الدهر فاجع … برزء، وغناها لتطرب ساجع\nولم تدر من أنى تعد لنا الخطا، … ولا أين تقضى للجنوب المضاجع\nوما هذه الساعات إلا أراقم، … وما شجعت في لمسهن الأشاجع\nأرى الناس أنفاس التراب، فظاهر … إلينا، ومردود إلى الأرض، راجع\nشربت سني الأربعين تجرعا، … فيا مقرا ما شربه في ناجع\nجهلنا، فحي، في الضلالة، ميت، … أخو سكرة في غيه، لا يراجع\nيذم، إذا لاقاك يقظان هاجعا، … وحمد، لذئب الخرق، يقظان هاجع"},{"id":"diwan-maarri:826","bookId":"diwan-maarri","type":"poem","seq":826,"chapter":"قصائد","title":"دولاتكم شمعات يستضاء بها،","page":"","text":"دولاتكم شمعات يستضاء بها، … فبادروها إلى أن تطفأ الشمع\nوالنفس تفنى بأنفاس مكررة، … وساطع النار تخبي نوره اللمع\nكم سامعي اللفظ قوال، كأنهم … تحت البسيطة ما قالوا ولا سمعوا\nوالعلم يدرك أن المرء مختلس … من الحياة، ولكن يغلب الطمع\nوقد سقتهم غمامات بكت زمنا … بلا ابتسام، فما جادوا ولا دمعوا\nلا تجمعوا المال، واحبوه مواليه، … فالممسكون تراث كل ما جمعوا\nوالوقت لله، والدنيا مخلفة … من بعدنا، وتساوى الهام والزمع\nوليس يثبت للأيام من شرف، … إذا تفاخرت الآحاد والجمع\nورب أبيض، كان الوشي مبتذلا … في صونه، أكلته أضبع خمع"},{"id":"diwan-maarri:827","bookId":"diwan-maarri","type":"poem","seq":827,"chapter":"قصائد","title":"المال يسكت عن حق، وينطق في","page":"","text":"المال يسكت عن حق، وينطق في … بطل، وتجمع إكراما له الشيع\nوجزية القوم صدت عنهم، فغدت … مساجد القوم مقرونا بها البيع"},{"id":"diwan-maarri:828","bookId":"diwan-maarri","type":"poem","seq":828,"chapter":"قصائد","title":"نغدو على الأرض في حالات ساكنها","page":"","text":"نغدو على الأرض في حالات ساكنها … وتحتها لهدوء الحس نضطجع\nوالموت خير وفيه لامرىء دعة … أن يضرب الترب لايحدث له وجع\nتشابه القوم في علمي إذا جبنوا … فلا ألوم ولا أثني إذا شجعوا\nقريضهم كقريض الباركات وما … سجع الحمائم إلا مثل ما سجعوا\nترى وميض حياء لا حيا قلقا … عند الثريا وهل سار فمنتجع\nبئس المعاشر إن ناموا فلا انتبهوا … من الرقاد وإن غابوا فلا رجعوا\nكم أنفد الليل ناس غفلة وكرى … ولو أحسوا خفي الأمر ما هجعوا\nيشجو الفراق فلولا إلف مفتقد … للظاعنين لما أبكوا ولا فجعوا"},{"id":"diwan-maarri:829","bookId":"diwan-maarri","type":"poem","seq":829,"chapter":"قصائد","title":"قالت معاشر: كل عاجز ضرع،","page":"","text":"قالت معاشر: كل عاجز ضرع، … ما للخلائق لا بطء ولا سرع\nمدبرون، فلا عتب، إذا خطئوا … على المسيء، ولا حمد، إذا برعوا\nوقد وجدت لهذا القول، في زمني، … شواهدا، ونهاني، دونه، الورع\nوالناس ضأن تساوت في غرائزها، … يلقون، بالأرض، كفا، كلما افترعوا\nوالعيش ورد سيسقى الحي آخره، … عند الحمام، وأنفاس الفتى جرع\nشاموا بروق المنايا، غير مانعهم … من الحوادث، ما شاموا وما ادرعوا\nويدعي، الرتبة العليا، أخسهم، … فما يجاب لهم داع، إذا ضرعوا\nوأدركوا، بدعاويهم، مدى زحل، … من الرغام، بما قاسوه أو ذرعوا\nيسعون في المنهج المسلوك، قد سبقوا … إلى الذي هو، عند الغر، مخترع\nأبكار هذي المعاني ثيبات حجى، … في كل عصر لها جان ومفترع\nوخالفوا الشرع، لما جاءهم بتقى؛ … واستحسنوا، من قبيح الفعل، ما شرعوا\nوجدت ما ازدرعوه، كان عن قدر، … والحق أن بنيهم شر ما ازدرعوا\nولو يكشف عن أبصارهم، لرأت … آمالهم والمنايا كيف تصطرع\nعادت لياليهم دهما، بلا وضح، … وقد يكون بهن الغر والدرع\nوالمرء، ما عاش، مبسوط إساءته، … يشقى به القوم، إن هانوا وإن فرعوا\nوالطير والوحش غاديها وصالحها … والليث والشبل والذيال والذرع\nلا فضل يحباه مخلوق على جهة … من حاله، وتساوى النسر والمرع\nوالهذر يعطيك، عن فقد الهدى، نبأ، … ويكثر القول طير، شأنها الضرع"},{"id":"diwan-maarri:830","bookId":"diwan-maarri","type":"poem","seq":830,"chapter":"قصائد","title":"من رام أن يلزم الأشياء واجبها،","page":"","text":"من رام أن يلزم الأشياء واجبها، … فإنه ببقاء ليس ينتفع\nأرضي انتباهي بما لم يرضه حلمي … قدما، وأدفع أوقاتي، فتندفع\nوخف بالجهل أقوام، فبلغهم … منازلا، بسناء العز تلتفع\nأما رأيت جبال الأرض لازمة … قرارها، وغبار الأرض يرتفع؟"},{"id":"diwan-maarri:831","bookId":"diwan-maarri","type":"poem","seq":831,"chapter":"قصائد","title":"حيران أنت فأي الناس تتبع؛","page":"","text":"حيران أنت فأي الناس تتبع؛ … تجري الحظوظ، وكل جاهل طبع\nوالأم بالسدس عادت، وهي أرأف من … بنت لها النصف، أو عرس لها الربع\nوالحتف، كالثائر العادي، يصرعنا؛ … والأرض تأكل، هلا تكتفي الضبع؟\nأما دعاويك، فهي الآن مضحكة، … وما لنفسك من أطماعها شبع\nيا فاسقا يتراءى أنه ملك؛ … وفارة، عند قوم، أنها سبع\nما أشبه الناس بالأنعام، ضمهم، … إلى البسيطة، مصطاف ومرتبع\nإن لم تكن فحل إبل كنت مشبهه، … أعراسك الذود عدت، وابنك الربع"},{"id":"diwan-maarri:832","bookId":"diwan-maarri","type":"poem","seq":832,"chapter":"قصائد","title":"أما الزمان، فأوقات مواصلة؛","page":"","text":"أما الزمان، فأوقات مواصلة؛ … يا سعد ويحك، هل أحسست من بلع\nأسرر جميلك، وافعل ما هممت به، … إن المليك على الأسرار مطلع\nولتركب الجنح، لا عودا ولا فرسا، … كأنما الشهب فيه الأينق الظلع\nوما الهلال بظفر الليث ترهبه، … لكنه، من بقايا آكل، صلع\nوالشري، يوجد في أعقابه ضرب، … خير من الأري، في أعقابه سلع\nوإن جهلت، هداك الله، من كبر، … فكل طود منيف شأنه الصلع\nوأم دفر، إذا طلقتها بذلت … رفدا، وكانت كعرس حين تختلع\nوسرت، عمري، إلى قبري على مهل، … وقد دنوت، فحق الخوف والهلع\nما نحن أم ما برايا عالم كثر، … في قدرة، بعضها، الأفلاك، يبتلع\nتهزم الرعد، حتى خلته أسدا، … أمامه، من بروق، ألسن دلع"},{"id":"diwan-maarri:833","bookId":"diwan-maarri","type":"poem","seq":833,"chapter":"قصائد","title":"المين أهلك فوق الأرض ساكنها،","page":"","text":"المين أهلك فوق الأرض ساكنها، … فما تصادق، في أبنائها، الشيع\nلولا عداوة أصل في طباعهم، … كانت مساجد مقرونا بها البيع"},{"id":"diwan-maarri:834","bookId":"diwan-maarri","type":"poem","seq":834,"chapter":"قصائد","title":"النفس في العالم العلوي مركزها،","page":"","text":"النفس في العالم العلوي مركزها، … وليس في الجو، للأجساد، مزدرع\nتفرع الناس عن أصل به درن، … فالعالمون، إذا ميزتهم، شرع\nوالجد آدم، والمثوى أديم ثرى، … وإن تخالفت الأهواء والشرع\nما ربة التاج والقرطين مارية، … إلا كمارية، في إثرها ذرع\nوإن خنساء، إذ تزجي قصائدها، … نظير خنساء، يدعو ظمئها الكرع\nما أكثر الورع المزؤود من جبن، … فينا وإن قل، في أشياعنا، الورع\nولابس المغفر الدرعي جاء به، … كالسيد أدرع، في ليل له درع\nوالعيش ماء مزاد، راح يحمله … طاوي الفلاة، وأنفاس الفتى جرع\nإذا دعيت لأمر عادني بأذى، … أو رزء دين، فإبطائي هو السرع\nغدت جيوش المنايا حول واحدة … من النفوس، عليها الجيش يقترع\nإذا أبيدت، فما عندي، إذا أخذت، … فرع ينوب، ولا عذراء تفترع\nوإن حباني، سعدا، من به ثقتي، … فليس ينقص حظي أنني ضرع\nتشابه الإنس، إلا أن يشذ حجى، … والطير شتى، ومنها الفتخ والمرع"},{"id":"diwan-maarri:835","bookId":"diwan-maarri","type":"poem","seq":835,"chapter":"قصائد","title":"الدهر كالشاعر المقوي، ونحن به","page":"","text":"الدهر كالشاعر المقوي، ونحن به … مثل الفواصل، مخفوض ومرفوع\nما سر، يوما، بشيء من محاسنه، … إلا وذاك، بسوء الفعل، مشفوع\nوالمرء يرغب في الدنيا ويعجبه … غناه، وهو، إلى ما ساء، مدفوع"},{"id":"diwan-maarri:836","bookId":"diwan-maarri","type":"poem","seq":836,"chapter":"قصائد","title":"إذا داع دعاك لرشد أمر،","page":"","text":"إذا داع دعاك لرشد أمر، … فلب ولا يفتك له اتباع\nتغير ملك حمير ثم كسرى، … ولم تقبل، تغيرها، الطباع\nوجدت الناس في جبل وسهل، … كأنهم الذئاب، أو السباع\nرجال مثل ما اهترشت كلاب؛ … ونسوان كما اغتلم الضباع\nأزال الله خيرا عن أمير، … له ولد، على علم يباع\nجوار، كالنياق يسقن عنه، … وفي أحشائهن له رباع"},{"id":"diwan-maarri:837","bookId":"diwan-maarri","type":"poem","seq":837,"chapter":"قصائد","title":"سأخرج بالكراهة، من زماني","page":"","text":"سأخرج بالكراهة، من زماني … وفي كشحي، من يده، قطاع\nوما زال البقاء يرث حبلي، … إلى أن حان، للمرس، انقطاع\nلبيب القوم تألفه الرزايا، … ويأمر بالرشاد، فلا يطاع\nفلا تأمل، من الدنيا، صلاحا، … فذاك هو الذي لا يستطاع"},{"id":"diwan-maarri:838","bookId":"diwan-maarri","type":"poem","seq":838,"chapter":"قصائد","title":"إذا ما الأصل ألفي غير زاك،","page":"","text":"إذا ما الأصل ألفي غير زاك، … فما تزكو، مدى الدهر، الفروع\nوليس يوافق ابن أب وأم … أخاه، فكيف تتفق الشروع؟\nفإن أكدى المنيل، فلا تلمه، … فقد تخلو، من الرسل، الضروع\nوذكر بالتقى نفرا غفولا، … فلولا السقي ما نمت الزروع\nبني حواء كيف الأمن منكم، … ولم يؤهل، بغير الحقد، روع؟\nإذا كان القضاء يجيء حتما، … فما هذي المغافر والدروع؟\nأذكركم برحلتكم لعلي … أروع قلوبكم، ولمن أروع!"},{"id":"diwan-maarri:839","bookId":"diwan-maarri","type":"poem","seq":839,"chapter":"قصائد","title":"إن دمعي نبع، وما العود نبع،","page":"","text":"إن دمعي نبع، وما العود نبع، … وحواني، من منزل الهم، ربع\nخذ بضبعي، إذا أطقت غياثا، … فمسير الأيام تحتي ضبع\nنل يسيرا مني، ولا تسبعني، … في نوالي، فإن ظمئي سبع\nوالسجايا شتى، فلا يقنص اللي … ث هزبرا، والهر للفار سبع\nوتداني الأيام يحدث نقصا … وازديادا، والجسم للنفس تبع\nخمسة، في نظيرها خمس خمسات، … تنمت، والنصف، في النصف ربع\nيغدر الخل إن تكفل، يوما … بوفاء، والغدر في الناس طبع"},{"id":"diwan-maarri:840","bookId":"diwan-maarri","type":"poem","seq":840,"chapter":"قصائد","title":"لقد جاء قوم يدعون فضيلة،","page":"","text":"لقد جاء قوم يدعون فضيلة، … وكلهم يبغي لمهجته نفعا\nوما انخفضوا كي يرفعوكم، وإنما … رأوا خفضكم، طول الحياة، لهم رفعا\nوما ثبتوا من شاهد يهتدى به، … فإن لزموا دعواهم، فالزموا الدفعا\nندين بأن الله وتر، وخوفه … رشاد، فصلوا الوتر في الدهر والشفعا\nودنياكم الدار التي ما تضمنت … زكيا، فلا تبكوا أثافيها السفعا"},{"id":"diwan-maarri:841","bookId":"diwan-maarri","type":"poem","seq":841,"chapter":"قصائد","title":"لعمرك ما آسى، إذا ما تحملت،","page":"","text":"لعمرك ما آسى، إذا ما تحملت، … عن الجسم، روح كان يدعى لها ربعا\nوما أسأل الأحياء، بعدي، زيارة … ثلاثا، لإيناس الدفين، ولا سبعا\nولا ترث الزوجات عني حصة، … من المال، ثمنا، في الفريضة، أو ربعا\nجوار بني الدنيا ضنى لي دائم، … تمنيت، لما شفني، الغب والربعا\nلقد فعلوا الخير القليل، تكلفا، … وجاؤوا الذي جاؤوه، من شرهم، طبعا\nفأين ينابيع الندى وبحاره؛ … وهل أبقت الأيام، من أسد، ضبعا؟\nإذا حرقت عيدانهم، فألوة؛ … وإن عجمت، في حادث، وجدت نبعا"},{"id":"diwan-maarri:842","bookId":"diwan-maarri","type":"poem","seq":842,"chapter":"قصائد","title":"خير النساء اللواتي لا يلدن لكم،","page":"","text":"خير النساء اللواتي لا يلدن لكم، … فإن ولدن، فخير النسل ما نفعا\nوأكثر النسل يشقى الوالدان به، … فليته كان عن آبائه دفعا\nأضاع داريك من دنيا وآخرة، … لا الحي أغنى، ولا في هالك شفعا\nوكم سليل رجاه للجمال أب، … فكان خزيا، بأعلى هضبة، رفعا"},{"id":"diwan-maarri:843","bookId":"diwan-maarri","type":"poem","seq":843,"chapter":"قصائد","title":"برد الصبا، ليس مثل البرد تخلعه،","page":"","text":"برد الصبا، ليس مثل البرد تخلعه، … وجاز أن يستعيد اللبس من خلعه\nفأجد، واجدد، وآجد، واجد من صمد … غفرانه واخش واخشش نفسك الطلعه\nواعرض أحاديث من قوم، أتوك بها، … على قياسك، تحلف أنهم ولعه"},{"id":"diwan-maarri:844","bookId":"diwan-maarri","type":"poem","seq":844,"chapter":"قصائد","title":"لا تخبأن، لغد، رزقا، وبعد غد،","page":"","text":"لا تخبأن، لغد، رزقا، وبعد غد، … فكل يوم يوافي رزقه معه\nواذخر جميلا لأدنى القوت، تدركه، … وللقيامة، تعرف ذاك أجمعه\nفرق تلادك فيما شئت، محتقرا، … فليس يذرف، خلف النعش، أدمعه\nوافعل بغيرك ما تهواه يفعله، … وأسمع الناس ما تختار مسمعه\nوأكثر الإنس مثل الذئب تصحبه، … إذا تبين منك الضعف أطمعه"},{"id":"diwan-maarri:845","bookId":"diwan-maarri","type":"poem","seq":845,"chapter":"قصائد","title":"إذا عفوت، عن الإنسان، سيئة،","page":"","text":"إذا عفوت، عن الإنسان، سيئة، … فلا تروعه تثريبا وتقريعا\nوإن كفيت عناء، فاجتنب كلفا؛ … غان عن النزع مروي الإبل تشريعا\nوالمرء يوجد من عدم، وما نقلت، … عنه الحوادث، من عاداته، ريعا\nإن يألف الهضب لا يبغ الوهود به؛ … أو يألف الوهد لا يؤثر به ريعا\nوفي الضرورة يلغى ما تعوده، … والغفر يأكل، في الرمل، الأساريعا\nوكيف يطلب عدلا من غريزته … تولد الظلم تثميرا وتفريعا؟\nلكل حال سجايا، والقريض بنا، … لا تقتضيك، بغير البدء، تصريعا"},{"id":"diwan-maarri:846","bookId":"diwan-maarri","type":"poem","seq":846,"chapter":"قصائد","title":"إذا ما بيعة زيرت لغي","page":"","text":"إذا ما بيعة زيرت لغي … فأعط، لهجرها، أيمان بيعه\nولا تجعلك، للأيام، كلبا، … ظباء من ذؤيبة أو سبيعه\nفإن الدهر ينقل كل حال، … كما نقل الحكومة من ضبيعه"},{"id":"diwan-maarri:847","bookId":"diwan-maarri","type":"poem","seq":847,"chapter":"قصائد","title":"أزعمت أنك آخذ، من لذة","page":"","text":"أزعمت أنك آخذ، من لذة … حظا، وأنك لا تؤمل مرجعا؟\nحتى م تصبح، للضعيف، مقويا، … فعل السفيه، وللجبان مشجعا؟\nلو لم نراع، أمامنا، إلا الردى … وبلى الجسوم، لكان أمرا موجعا\nوإذا هممت بمطلب لتناله، … لاقيت، من نوب الزمان، مفجعا\nوالشخص لا ينفك من تعب أتى … من نفسه، حتى يصادف مضجعا"},{"id":"diwan-maarri:848","bookId":"diwan-maarri","type":"poem","seq":848,"chapter":"قصائد","title":"يا ثالث الثنيين في خمسة،","page":"","text":"يا ثالث الثنيين في خمسة، … إربع، لكي تستخبر الأربعا\nينبع، من عينيك، ماء لها، … إذا خليط يمموا ينبعا\nفهل ترى كسرا على الأرض، من … كسراك، أو من تبع، تبعا؟\nوكم لقينا ضبعا، أقبلت … تفترس الآساد، والأضبعا"},{"id":"diwan-maarri:849","bookId":"diwan-maarri","type":"poem","seq":849,"chapter":"قصائد","title":"لعمري! لقد أوضعت في الغي برهة،","page":"","text":"لعمري! لقد أوضعت في الغي برهة، … فما لك في ركب التقى غير موضع\nوكم هد، من ثهلان، شامخ طوده، … ولكن ترى ثهلان لم يتضعضع\nحلبت الزمان العود أشطر ثرة، … صفي، وما تنفك من جهل مرضع\nفدع عنك ذكر البارقية، تعتزي … لبارق حي، أو لبارق موضع\nإذا خضعت أعناق رهط لكفرهم، … فأعناق طلاب الهدى غير خضع"},{"id":"diwan-maarri:850","bookId":"diwan-maarri","type":"poem","seq":850,"chapter":"قصائد","title":"حبست كتاب العين في كل وجهة،","page":"","text":"حبست كتاب العين في كل وجهة، … فخذ حذرا من ترجمان المفجع\nتق الله، واترك أدمعا إثر هالك، … فلم تلق إلا حاملا قلب موجع\nوأي انتفاع للهديل، الذي مضى، … على عهد نوح، بالهديل المرجع\nكأن خطيبا موفيا رأس منبر، … يبث هذاء، بالكلام المسجع\nإذا كان جسمي، في الثرى، غير عالم، … فلحدي خير من مبيتي بمهجع"},{"id":"diwan-maarri:851","bookId":"diwan-maarri","type":"poem","seq":851,"chapter":"قصائد","title":"عليك بفعل الخير، لو لم يكن له،","page":"","text":"عليك بفعل الخير، لو لم يكن له، … من الفضل، إلا حسنه في المسامع\nلعمرك! ما في عالم الأرض زاهد … يقينا، ولا الرهبان أهل الصوامع\nأرى أمراء الناس يمسون شرهم، … إذا خطفوا خطف البزاة اللوامع\nوفي كل مصر حاكم، فموفق، … وطاغ يحابي في أخس المطامع\nيجور، فينفي الملك عن مستحقه، … فتسكب أسراب العيون الدوامع\nومن حوله قوم كأن وجوههم … صفا، لم يلين بالغيوث الهوامع\nعدول، لهم ظلم الضعيف سجية، … يسمون أعراب القرى والجوامع"},{"id":"diwan-maarri:852","bookId":"diwan-maarri","type":"poem","seq":852,"chapter":"قصائد","title":"سواء هجودي في الدجى، وتهجدي","page":"","text":"سواء هجودي في الدجى، وتهجدي … علي، إذا أصبحت غير مطيع\nهم الناس ضرب السيف لم يغن فيهم، … ويكفيك عود السوء ضرب قطيع"},{"id":"diwan-maarri:853","bookId":"diwan-maarri","type":"poem","seq":853,"chapter":"قصائد","title":"إذا فزعنا، فإن الأمن غايتنا؛","page":"","text":"إذا فزعنا، فإن الأمن غايتنا؛ … وإن أمنا، فما نخلو من الفزع\nوشيمة الإنس ممزوج بها ملل، … فما ندوم على صبر ولا جزع\nوسبتك الشعر الغربيب تطرحه، … ما رغب الشيخ في البادي من النزع\nونغبة إثر أخرى أطفأت ظمأ؛ … ورب ملبس دجن خيط من قزع\nوشر ساكن هذي الأرض عالمنا، … واللوب في الجزع أغلى قيمة الجزع\nلولا فوارس، فوق الأرض، مشرعة، … ما هابت الوحش قرب الشزب المزع\nزع نفسك اليوم، واندبها إلى حسن، … فإن أطاعت، فأدب غيرها وزع"},{"id":"diwan-maarri:854","bookId":"diwan-maarri","type":"poem","seq":854,"chapter":"قصائد","title":"تزوج، بعد واحدة، ثلاثا،","page":"","text":"تزوج، بعد واحدة، ثلاثا، … وقال لعرسه يكفيك ربعي\nفيرضيها، إذا قنعت بقوت، … ويرجمها، إذا مالت لتبع\nومن جمع اثنتين، فما توخى، … سبيل الحق في خمس وربع\nوعقلك يا أخا السبعين واه، … كأنك في ملاعبك ابن سبع\nظلمت، وكلنا جان ظلوم، … وطبعك في الخيانة مثل طبعي\nيسرك أن ربع سواك خال، … إذا مكنت من أهل وربع\nولولا ذاك ما حملت، لرمي، … معابل صائد، وقسي نبع"},{"id":"diwan-maarri:855","bookId":"diwan-maarri","type":"poem","seq":855,"chapter":"قصائد","title":"سباك الله يا دنيا عروسا،","page":"","text":"سباك الله يا دنيا عروسا، … فكم أوفدت لي شمعا بشمع\nوما ينفك، في يمن وشام … غرورك، شائما بخفي لمع\nوما أبهجتني منذ التقينا، … وإن نوهت بي ورفعت سمعي\nإذا ما أعظمي كانت هباء، … فإن الله لا يعييه جمعي\nولم أستغل منك فداء نفسي … بشيء، فاعجبي لرقوء دمعي\nبفقد غرائزي شمي وذوقي، … ولمسي تابعا بصري وسمعي\nأرى الدولات فيك وإن تمادت … غمائم أثجمت بوشيك همع"},{"id":"diwan-maarri:856","bookId":"diwan-maarri","type":"poem","seq":856,"chapter":"قصائد","title":"كإنائك الجسم الذي هو صورة","page":"","text":"كإنائك الجسم الذي هو صورة … لك في الحياة، فحاذري أن تخدعي\nلا فضل للقدح الذي استودعته … ضربا، ولكن فضله للمودع"},{"id":"diwan-maarri:857","bookId":"diwan-maarri","type":"poem","seq":857,"chapter":"قصائد","title":"ما لي رأيتك لا تلم بمسجد،","page":"","text":"ما لي رأيتك لا تلم بمسجد، … حتى كأنك في البلاغ السابع؟\nسبح بواحدة، ففيها بلغة … للمتقين، وكل بخمس أصابع\nيا أولا، في الكفر، لم يك ثانيا، … طال استتارك بالإمام الرابع\nوالشمر عندك، في الحسين، موفق … لما حماه من الفرات النابع\nما صح عندي أن ذات خلاخل، … تقفى، من الجن الغواة، بتابع"},{"id":"diwan-maarri:858","bookId":"diwan-maarri","type":"poem","seq":858,"chapter":"قصائد","title":"الطيلسان اشتق، في لفظه،","page":"","text":"الطيلسان اشتق، في لفظه، … من طلسة المبتكر الجامع\nوزيد ما زيد لتوكيده، … فالشر في بارقه اللامع\nأما استحى العدل، وأخباره … سيئة في أذن السامع؟\nما جار شماسك في حكمه؛ … ولا يهوديك بالطامع\nفالقس خير لك، فيما أرى، … من مسلم يخطب في الجامع"},{"id":"diwan-maarri:859","bookId":"diwan-maarri","type":"poem","seq":859,"chapter":"قصائد","title":"مرحبا بالموت والعيش دجى","page":"","text":"مرحبا بالموت والعيش دجى … وحمام المرء، كالفجر سطع\nأمل أحصد، لا ترسله … كف حي، فإذا مات انقطع\nأمر الحازم نفسا بالتقى، … ذاك أمر من لبيب لم يطع\nكم أراد الخلد قوم، فرأوا … مسلكا، إن يلتمس لا يستطع\nلست أدري، ألقسم المال أم … لاقتضاب الرأس، يدعى بالنطع\nطلب المشتار أريا، فإذا … جثة البائس في الأرض قطع"},{"id":"diwan-maarri:860","bookId":"diwan-maarri","type":"poem","seq":860,"chapter":"قصائد","title":"عجبت لآمرنا لم يطع،","page":"","text":"عجبت لآمرنا لم يطع، … وللخلد عز، فلم يستطع\nونظم أناس تناهى إلي، … من عهد آدم، ثم انقطع\nوأشنب إن أنظرته المنون، … فلا بد من قصم أو لطع\nفلا تيأسن لليل دجا، … ولا تفرحن بفجر سطع\nولا تحفلن، أللسيب أم … مع السيف قدم ذاك النطع"},{"id":"diwan-maarri:861","bookId":"diwan-maarri","type":"poem","seq":861,"chapter":"قصائد","title":"إذا قلت إن الشيب لله صبغه،","page":"","text":"إذا قلت إن الشيب لله صبغه، … فقد ضل بادي الغي، للشيب صابغ\nنوابغ فود لا يبالين خاضبا، … تروع منها جرول والنوابغ"},{"id":"diwan-maarri:862","bookId":"diwan-maarri","type":"poem","seq":862,"chapter":"قصائد","title":"من عثرة القوم أن كنوا وليدهم","page":"","text":"من عثرة القوم أن كنوا وليدهم … أبا فلان، ولم ينسل ولا بلغا\nكالسيف سمي قطاعا، وما ضربت … به الأكف، ولا في هامة ولغا\nقد هان مين على أفواهنا، فغدا … ذو النسك غير مبال أن يكون لغا\nوأروح الرزق ما وافاك، في دعة، … حلا، وقسم في أيامه بلغا"},{"id":"diwan-maarri:863","bookId":"diwan-maarri","type":"poem","seq":863,"chapter":"قصائد","title":"سقى ديارك غاد، ماؤه نعم،","page":"","text":"سقى ديارك غاد، ماؤه نعم، … كالقرم سدم، فهو الهادر الراغي\nوليفرغ السعد فيها قادر صمد، … فلست أقنع من دجن بإفراغ"},{"id":"diwan-maarri:864","bookId":"diwan-maarri","type":"poem","seq":864,"chapter":"قصائد","title":"عد عن شارب كأس أسكرت،","page":"","text":"عد عن شارب كأس أسكرت، … فهو مثل الكلب، في الرجس ولغ\nوالفتى ساع لأقصى أمل، … لم يزل يطلبه، حتى بلغ"},{"id":"diwan-maarri:865","bookId":"diwan-maarri","type":"poem","seq":865,"chapter":"قصائد","title":"مومس، كالإناء دنسه الشر","page":"","text":"مومس، كالإناء دنسه الشر … ب، ووغد، كأنه الكلب والغ\nوعقول ليست ترد فتيلا، … لقضاء، في عالم الله بالغ"},{"id":"diwan-maarri:866","bookId":"diwan-maarri","type":"poem","seq":866,"chapter":"قصائد","title":"أخو سفر، قصده لحده،","page":"","text":"أخو سفر، قصده لحده، … تمادى به السير، حتى بلغ\nودنياك مثل الإناء الخبيث، … وصاحبها مثل كلب ولغ"},{"id":"diwan-maarri:867","bookId":"diwan-maarri","type":"poem","seq":867,"chapter":"قصائد","title":"ما كان في هذه الدنيا بنو زمن،","page":"","text":"ما كان في هذه الدنيا بنو زمن، … إلا وعندي من أخبارهم طرف\nيخبر العقل أن القوم ما كرموا، … ولا أفادوا ولا طابوا ولا عرفوا\nعاشوا قليلا، وماجوا في ضلالتهم، … ولا يفوزون إن جوزوا بما اقترفوا\nإذا شقيت، فجسم ناله نصب، … وإن ترفت، فماذا ينفع الترف؟\nيا أم دفر، لحاك الله والدة، … منك الإضاعة والتفريط والسرف\nلو أنك العرس أوقعت الطلاق بها، … لكنك الأم، هلي لي عنك منصرف؟\nولن يصيب خفافا من يقايضه، … يوما، بندبة لما فاتها الشرف\nقالت رجال: عقول الشهب وافرة، … لو صح ذلك قلنا: مسها خرف"},{"id":"diwan-maarri:868","bookId":"diwan-maarri","type":"poem","seq":868,"chapter":"قصائد","title":"ينجمون، وما يدرون لو سئلوا","page":"","text":"ينجمون، وما يدرون لو سئلوا … عن البعوضة، أنى منهم تقف\nوفرقتهم، على علاتها، ملل، … وعند كل فريق أنهم ثقفوا\nدع البرية للخطبان تأكله، … فإنهم كنعام فيه ينتقف\nولو درت، بمخازيهم، بيوتهم، … هوت عليهم ولم تنظرهم السقف"},{"id":"diwan-maarri:869","bookId":"diwan-maarri","type":"poem","seq":869,"chapter":"قصائد","title":"إنا، معاشر هذا الخلق، في سفه،","page":"","text":"إنا، معاشر هذا الخلق، في سفه، … حتى كأنا، على الأخلاق، نختلف\nإن الرجال، إذا لم يحمها رشد، … مثل النساء عراها الخلف والخلف\nألا ترى جمع ما لا عقل يسنده، … جمع المؤنث فيه التاء والألف؟\nويوصف القوم، في العلياء، أنهم … شم الأنوف، وفي آنافهم ذلف\nكم من أخ بأخيه غير متصل، … كالعين، ليست بلفظ الخاء تأتلف\nتلاف أمرك من قبل التلاف به، … فغاية الناس، في دنياهم، التلف\nولا تقولن، إذا ما جئت مخزية، … قول الغواة: على هذا مضى السلف\nلا تحلفن على صدق ولا كذب، … فما يفيدك، إلا المأثم، الحلف\nلولا حذاري أن الله يسألني … عما فعلت، لقلت عندي الكلف\nكنا فتوا، فقد مد البقاء لنا، … حتى غدونا، ومنا الشيب والدلف\nيفنى الزمان، وأنفاس الأنام له … خطا، بهن إلى الآجال، يزدلف\nوأم دفر فروك وافقت صلفا … مني، وكان جزاء الفارك الصلف\nوكم ضحكت إليها، وهي عابسة، … ثم افتكرت، فزال الحب والكلف\nوالناس من أربع شتى، إذا ائتلفت … ردت إلى سبعة، في الحكم تختلف\nإقرأ كلامي، إذا ضم الثرى جسدي، … فإنه لك ممن قاله خلف"},{"id":"diwan-maarri:870","bookId":"diwan-maarri","type":"poem","seq":870,"chapter":"قصائد","title":"الفكر حبل، متى يمسك على طرف","page":"","text":"الفكر حبل، متى يمسك على طرف … منه، ينط بالثريا ذلك الطرف\nوالعقل كالبحر، ما غيضت غواربه … شيئا، ومنه بنو الأيام تغترف\nأبني بجهلي دارا، لست مالكها، … أقيم فيها قليلا، ثم أنصرف\nسرفت، والله يرجى أن يسامحنا، … وفي القديم خلا، من أهله، سرف\nأأنكر الله ذنبا خطه ملك، … وبالذي خطه الإنسان أعترف؟\nتقوى فيهدى إليك الزاد عن عرض، … وتفتري الأرض جوالا، فتقترف\nتروم رزقا بأن سموك متكلا، … وأدين الناس من يسعى ويحترف\nيكفيك، أدما بنحض، ماء نابتة، … وظلمك النحل ما يعطيكه الضرف\nإذا افتكرنا علمنا أن ذا ضعة … أعلى النجوم، ولله انتهى الشرف"},{"id":"diwan-maarri:871","bookId":"diwan-maarri","type":"poem","seq":871,"chapter":"قصائد","title":"حسب الفتى، من ذنوب، وصفه رجلا","page":"","text":"حسب الفتى، من ذنوب، وصفه رجلا … بالخير، وهو على ضد الذي يصف\nوقد خبرت بني الدنيا، فليتهم، … أو ليتني حملتني عنهم العصف\nفظالم آخذ ما لا يحل له؛ … ومنصف ظل فيهم ليس ينتصف"},{"id":"diwan-maarri:872","bookId":"diwan-maarri","type":"poem","seq":872,"chapter":"قصائد","title":"خاب الذي سار عن دنياه مرتحلا،","page":"","text":"خاب الذي سار عن دنياه مرتحلا، … وليس في كفه من دينه طرف\nلا خير للمرء إلا خير آخرة … يبقي عليه، فذاك العز والشرف\nنرجو السلامة في العقبى وما حسنت … أعمالنا، فيرجى الفوز والغرف\nما بان قوم عن الأولى بما جمعوا … من الحطام، ولكن بالذي اقترفوا\nسألت عقلي فلم يخبر وقلت له: … سل الرجال، فما أفتوا ولا عرفوا\nقالوا، فمالوا، فلما أن حدوتهم … إلى القياس، أبانوا العجز واعترفوا\nجاران: ملك ومحتاج أتى زمن … عليهما، فتساوى البؤس والترف\nإن تركب الخيل أو تضرب مراكبها … من عسجد، فإلى الغبراء تنصرف\nوالفقر أحمد من مال تبذره، … إن افتقارك مأمون به السرف\nيعرى الفقير وبالدينار كسوته، … وفي صوانك، ما إعداده خرف"},{"id":"diwan-maarri:873","bookId":"diwan-maarri","type":"poem","seq":873,"chapter":"قصائد","title":"طال التبسط، منا، في حوائجنا؛","page":"","text":"طال التبسط، منا، في حوائجنا؛ … وإنما نحن فوق الأرض أضياف\nيريد خل خليلا كي يوافقه … في الطبع، هيهات إن الناس أخياف\nلولا التخالف لم تركض لغارتها … خيل، ولم تقن أرماح وأسياف"},{"id":"diwan-maarri:874","bookId":"diwan-maarri","type":"poem","seq":874,"chapter":"قصائد","title":"شكوت، من أهل هذا العصر، غدرهم","page":"","text":"شكوت، من أهل هذا العصر، غدرهم … لا تنكرن، فعلى هذا مضى السلف\nوما اعترافي بعيب الجنس منقصة، … والعين يعرف، في آنافها، الذلف\nوالإلف هان له أمري، فقصرني، … كما تهون، على ذي المنطق، الألف\nأمسى النفاق دروعا يستجن بها … من الأذى، ويقوي سردها الحلف\nأفني زماني بأنفاس، كما قطعت، … مدى بعيدا، مواش، في السرى، دلف\nإذا تخلفت، أو خلفت عن أمل، … سلا همومي أني ليس لي خلف\nترجى الحياة، إذا كانت، مودعة، … وقل خير حياة، حشوها كلف\nلم يمض كون من الأكوان في زمن … علي، إلا به للحتف أزدلف\nفحسن الوعد بالإيجاز تتبعه، … إذا مواعد قوم شأنها الخلف\nإنا ائتلفنا، لأن الله ركبنا … من أربع، ثم صرنا بعد نختلف\nرأى بنو الحزم أن العيش فائدة، … حتى استبانوا، فقالوا: حبذا التلف\nوقلما تسكن الأضغان في خلد، … إلا وفي وجه من يسعى بها كلف"},{"id":"diwan-maarri:875","bookId":"diwan-maarri","type":"poem","seq":875,"chapter":"قصائد","title":"صوفية ما رضوا للصوف نسبتهم","page":"","text":"صوفية ما رضوا للصوف نسبتهم … حتى ادعوا أنهم من طاعة صوفوا\nتبارك الله، دهر حشوه كذب، … فالمرء منا بغير الحق موصوف\nإن أثمر الغصن، فامتدت إليه يد … تجنيه ظلما، فليت الغصن مقصوف"},{"id":"diwan-maarri:876","bookId":"diwan-maarri","type":"poem","seq":876,"chapter":"قصائد","title":"الأرض لله، ما استحيى الحلول بها","page":"","text":"الأرض لله، ما استحيى الحلول بها … أن يدعوها، وهم في الدار أضياف\nتنازعوا في عواري، فبينهم … نبل حطام، وأرماح وأسياف\nإن خالفوك، ولم يجرر خلافهم … شرا، فلا بأس أن الناس أخياف"},{"id":"diwan-maarri:877","bookId":"diwan-maarri","type":"poem","seq":877,"chapter":"قصائد","title":"صدقتك، صاحبي، لا مال عندي،","page":"","text":"صدقتك، صاحبي، لا مال عندي، … وقد كثر الضيافن والضيوف\nأناس، في أكفهم عصي؛ … وقوم، في أكفهم سيوف\nدراهمهم نقيات، ولكن … نفوسهم، إذا كشفت، زيوف\nوما في الأرض من شرب كريم، … يسر بورده الصادي العيوف"},{"id":"diwan-maarri:878","bookId":"diwan-maarri","type":"poem","seq":878,"chapter":"قصائد","title":"ألم تر أن جسمي فيه فضل،","page":"","text":"ألم تر أن جسمي فيه فضل، … وجسمك قد أضر به الشسوف؟\nتطيب جاهدا، وتعل دوني، … فما أغناك أنك فيلسوف\nكأنك، في يد الأيام، مال، … وكل المال، عن قدر، يسوف\nوأحسب أننا إبل رذايا، … أجد، وراءها، حاد عسوف\nأسفت لفائت، وسلوت عنه، … وهل مثلي على ماض أسوف؟\nلقد عشت الكثير من الليالي، … ولم أرقب متى يقع الكسوف\nفهل لطوالع الأقمار عقل، … فتعلم حين يدركها الخسوف؟\nأتسمع أو تعاين أو تعاني … بلاء، أو تذوق أو تسوف؟"},{"id":"diwan-maarri:879","bookId":"diwan-maarri","type":"poem","seq":879,"chapter":"قصائد","title":"رددت إلى مليك الحق أمري،","page":"","text":"رددت إلى مليك الحق أمري، … فلم أسأل متى يقع الكسوف\nفكم سلم الجهول من المنايا، … وعوجل بالحمام الفيلسوف"},{"id":"diwan-maarri:880","bookId":"diwan-maarri","type":"poem","seq":880,"chapter":"قصائد","title":"الناس مثل الماء تضربه الصبا،","page":"","text":"الناس مثل الماء تضربه الصبا، … فيكون منه تفرق وتألف\nوالخير يفعله الكريم بطبعه، … وإذا اللئيم سخا، فذاك تكلف\nقد يحسب الصمت الطويل من الفتى … حلما يوقر، وهو فيه تخلف\nنرجو من الله الثواب مجازيا، … وله علينا، في القديم، تسلف"},{"id":"diwan-maarri:881","bookId":"diwan-maarri","type":"poem","seq":881,"chapter":"قصائد","title":"زعموا بأنهم صفوا لمليكهم،","page":"","text":"زعموا بأنهم صفوا لمليكهم، … كذبوك ما صافوا، ولكن صافوا\nشجر الخلاف قلوبهم، ويح لها، … غرضي خلاف الحق، لا الصفصاف\nفتبارك الله، الذي هو قادر، … تعيا وتقصر، دونه، الأوصاف\nالظلم أكثر ما يعيش به الفتى، … وأقل شيء عنده الإنصاف\nمنعت، من القسم، الحقوق، كأنها … رجز تهافت ما له أنصاف\nوعنوا، فقال الشافعي ومالك … وأبو حنيفة، قبل، والخصاف"},{"id":"diwan-maarri:882","bookId":"diwan-maarri","type":"poem","seq":882,"chapter":"قصائد","title":"ما لي رأيتك معرضا،","page":"","text":"ما لي رأيتك معرضا، … فاسمع إذا نطق الحصيف\nالدهر ليس بمنصف، … والعيب يستره النصيف\nوالأرض أم برة، … والسهم عن غرض يصيف\nإنا شتونا فوقها، … ولعلنا فيها نصيف\nفالبث وحيدا، لا وصي … فة، في ذراك، ولا وصيف\nتأذى الأصول الثابتا … ت، فيحسد الغصن القصيف"},{"id":"diwan-maarri:883","bookId":"diwan-maarri","type":"poem","seq":883,"chapter":"قصائد","title":"غرك سود الشعرات التي","page":"","text":"غرك سود الشعرات التي … في الوجه مني، وأنا الدالف\nكلفتني شيمة عصر مضى، … هيهات منك العصر السالف\nوقد سئمنا زمنا مؤذيا، … أروح، من سالمه، التالف\nيحلف لا أبقى على واحد؛ … وبر، في أيمانه، الحالف"},{"id":"diwan-maarri:884","bookId":"diwan-maarri","type":"poem","seq":884,"chapter":"قصائد","title":"فاء لك الحلم، فاله عن رشإ،","page":"","text":"فاء لك الحلم، فاله عن رشإ، … خالط منه عرف المدامة فا\nوابك على طائر، رماه فتى … لاه، فأوهى، بفهره، الكتفا\nأو صادفته، حبالة نصبت، … فظل فيها كأنما كتفا\nبكر يبغي المعاش مجتهدا، … فقص عند الشروق، أو نتفا\nكأنه، في الحياة، ما فرع ال … غصن، فغنى عليه، أو هتفا"},{"id":"diwan-maarri:885","bookId":"diwan-maarri","type":"poem","seq":885,"chapter":"قصائد","title":"عوى، في سواد الليل، عاف لعله","page":"","text":"عوى، في سواد الليل، عاف لعله … يجاب، وأنى، والديار عوافي؟\nوليس، إذا الحساد كانت عيونهم … شوافن، للداء الدفين شوافي\nصوافن خيل، عند باب مملك، … جمعن، وما أوقاته بصوافي\nوسرك مثل العرس أوفت لواحد، … وأعوزها، للصاحبين، توافي\nوأسرار بعض الناس باتت، لناظر، … كأسرار كف، غيرهن، خوافي\nخواتم أعمال الفتى، إن بغى الهدى، … هدته وإلا، فالهموم ضوافي\nوأعمارنا أبيات شعر، كأنما … أواخرها، للمنشدين، قوافي\nإذا حسنت زانت، وإن قبحت جنت … أذى وهوى، فيما يسوء، هوافي\nنوى، في، باغ ما يضر، ودونه … خطوب، لإيجاب الحقود نوافي\nوكم طالب وافى، وقد شارف الغنى، … سوافي ريح، فانثنى بسواف\nطوافي در، يمنح الجد أهله … برفق، فيغني عن سرى وطواف\nحوى، في رخاء، وادع فضل نعمة … عداها مكل، والركاب حوافي"},{"id":"diwan-maarri:886","bookId":"diwan-maarri","type":"poem","seq":886,"chapter":"قصائد","title":"أيا شجر العرا! أوسعت ريا،","page":"","text":"أيا شجر العرا! أوسعت ريا، … فقد جف العضاه، ولم تجفي\nوما يبقى، إذا فتشت، حي … تخيره الحوادث، أو تنفي\nلكافور غدا الكافور زادا، … وجفت أبحر من آل جف\nوهل فات، الحتوف، أخو هذيل، … كأن ملاءتيه على هجف\nأو العادي السليك وصاحباه، … أو الأسدي كالصعل الهزف\nتجم جيوشها، فيضل فيها … فتى، يجتاب صفا بعد صف\nتكلفت الوفاء، وحم يوم … أراح من التوافي بالتوفي\nودهري، بالمغار، أغار صبري، … وعلمني التعفف بالتعفي\nأما شغل الأنام، عن التقافي، … بما وعد الزمان من التقفي؟\nوقد صدقت ظنون من رجال، … تخفوا ما توارى بالتخفي\nرأوا متسترا عنهم بسد … ليأجوج، كمستتر بشف\nلقد عجب القضاء لركب موج، … يقابله بمزمار ودف\nولو نالت عقاب اللوح لبا، … عداها، عن تكفوئها، التكفي\nوقد يغني المسف، إلى الدنايا، … تعيشه من الخوص المسف\nووطء السف، يحمي الرجل منه … بكور يد على ذرة بسف\nوكم بسط البنان، فعاد صفرا، … وزار الجود كفا ذات كف\nوما رف الكعاب سوى عناء، … وإن عنيت لمسواك برف\nوكم زفت إلى جدث عروس، … وقد همت إلى عرس بزف\nأرى دنياك خالطها قذاها، … وأعيت أن يهذبها مصفي\nبنوها مثلها، فحللت منها، … بوهد أو بهضب أو بقف\nتهيج صغائر الأشياء خطبا … جليلا، ما سناه بمستشف\nوإن القتل في أحد وبدر، … جنى القتلين في نهر وطف\nوإن لذ القبيح غواة قوم، … فإن الفضل يعرف للأعف\nوليس علي غير بلوغ جهدي، … وضيفي قانع مني بضف\nإذا استثقلت أثوابي ونعلي، … فثقلي في التجرد والتحفي\nلعل مطية مني قريب، … فيحمل سيرها قدما بخف\nوما سل المهند للتوقي، … كسل المشرفية للتشفي\nوليس الخمس، ضاربة بسيف، … نظير الخمس، ضاربة بدف\nأباغي حظه بقنا وخيل، … كباغيه بمنوال وحف؟\nوما الجبل الوقور لجاذبيه، … على العلات، كالجزء الأخف\nوجسمي شمعة والنفس نار، … إذا حان الردى خمدت بأف\nأعيرت، النعام، أولات فرع، … خلو الهام من ريش وزف؟\nلعل النبع تثنيه الليالي … أخا ورق، ونور مستكف\nإذا ما القائل الكندي ذلت … له الأوزان، فاعترفي بشف\nفإن عطاردا، في الجو، أولى … بأن يزن الكلام وأن يقفي\nوأقصي عن مآربك البرايا، … ولا يغررك خل بالتحفي\nوفذ، في مقاصده، بليغ، … أحب إلي من إلف ألف\nلعمر أبيك ما خالي بخال … لشائمه، ولا شهدي بهف\nفإن أعط القليل يكن هنيئا، … يجيء المستميح بغير شف\nإذا ورد الفقير، على احتياجي … أغثت لهيفه بالمستدف\nولو كان الكثير لقل عندي، … وأهون بالطفيف المستطف"},{"id":"diwan-maarri:887","bookId":"diwan-maarri","type":"poem","seq":887,"chapter":"قصائد","title":"غدونا مثقلين بما اكتسبنا","page":"","text":"غدونا مثقلين بما اكتسبنا … وعل العفو منه سوف يعفي\nوفكري سل حب المال مني، … ووجدي بالحياة أطال شعفي\nوكون الجسم في جسدي خبيا، … أشق عليه من هرم وضعف\nستضربني الحوادث في نظيري، … فتمحقني، ولا أزداد ضعفي\nوتنزلني سيول الدهر، كرها، … إلى وادي من جبلي ونعفي"},{"id":"diwan-maarri:888","bookId":"diwan-maarri","type":"poem","seq":888,"chapter":"قصائد","title":"بحمد الله، لم تخلق كعاب،","page":"","text":"بحمد الله، لم تخلق كعاب، … تجنب كل مخزية وعنف!\nفجدع حل في أذني غلام، … أبر لديه من قرط وشنف\nولا سيما إذا أعطيت أيدا، … لمد يديك، أو أنفا بأنف\nأرى الأيام تجحد ثم تثني … بإيجاب، وتوجب ثم تنفي\nوإن لم يعقل الأقدام عيب، … حملن الثقل من فدع وحنف\nوقد يحتال، في رد الرزايا، … بعود مغرد، وبعود صنف\nوكم غرت معاطس، من رجال، … بريح ألوة أو ريح رنف"},{"id":"diwan-maarri:889","bookId":"diwan-maarri","type":"poem","seq":889,"chapter":"قصائد","title":"توافقت اليهود مع النصارى،","page":"","text":"توافقت اليهود مع النصارى، … على قتل المسيح، بلا اختلاف\nوما اصطلحوا على ترك الدنايا، … بل اصطلحوا على شرب السلاف\nتلافيناهم بالقول فيه، … فجاءهم التلافي بالتلاف\nتخير خلقنا، والشر طبع، … فما نحتاج فيه إلى اختلاف\nترفق إن ديني ليس نبعا، … ولكن بالخلاف من الخلاف\nوقد دمنا على سوء السجايا، … كما دامت قريش على الإلاف\nفقد لاحت مخايل صادقات، … تروق العين باللمع الولاف\nفمن لك بالغريريات سارت … بأشباه، نسبن إلى علاف"},{"id":"diwan-maarri:890","bookId":"diwan-maarri","type":"poem","seq":890,"chapter":"قصائد","title":"لقد نفق الرديء، ورب مر،","page":"","text":"لقد نفق الرديء، ورب مر، … من الأقوات، يجعل في الصحاف\nوأكرمني، على عيبي، رجال، … كما روي القريض على الزحاف\nومن يركب إلى الهيجاء خيلا، … فإن سواه يقدم، وهو حافي"},{"id":"diwan-maarri:891","bookId":"diwan-maarri","type":"poem","seq":891,"chapter":"قصائد","title":"إذا ما ألحدت أمم بجهل،","page":"","text":"إذا ما ألحدت أمم بجهل، … فقابلها بتوحيد السيوف\nكأنا، في سجايانا، نقود، … كثيرات البهارج والزيوف\nوهذي الأرض للملك المرجى، … نلم بها، كإلمام الضيوف"},{"id":"diwan-maarri:892","bookId":"diwan-maarri","type":"poem","seq":892,"chapter":"قصائد","title":"تلا كتاب الله، من حفظه،","page":"","text":"تلا كتاب الله، من حفظه، … من هو بالكأس مليء حفي\nكأنه، من سوء أفعاله، … يبدد الخمر على المصحف\nلا تضف الشارب، في سكره، … ولا تنزله، ولا تلحف"},{"id":"diwan-maarri:893","bookId":"diwan-maarri","type":"poem","seq":893,"chapter":"قصائد","title":"كأنما دنياك وحشية،","page":"","text":"كأنما دنياك وحشية، … نظرت في آثار أظلافها\nما بقي الواحد من ألفها، … بل هو من ستة آلافها\nتطلب أري النحل من خلفها، … وذائب السم بأخلافها\nإن أخلفتك، اليوم، موعودها، … فعرفها جار بإخلافها\nحلفت: ما حالفها عاقل، … وشأنها الغدر بأحلافها\nأتلف، إذا أعطتك، أعراضها، … فإنها رهن بإتلافها\nتلك عجوز ألفت شرها، … قبل بني فهر وإيلافها"},{"id":"diwan-maarri:894","bookId":"diwan-maarri","type":"poem","seq":894,"chapter":"قصائد","title":"زعم الزاعمون، والقول، من مي","page":"","text":"زعم الزاعمون، والقول، من مي … ن وصدق، يروى، فعالي وعيفي\nإن شقا، يلوح في باطن البر … ة، قسم بيني وبين الضعيف"},{"id":"diwan-maarri:895","bookId":"diwan-maarri","type":"poem","seq":895,"chapter":"قصائد","title":"الليالي مغيرات السجايا،","page":"","text":"الليالي مغيرات السجايا، … كم جعلن الذيفان شرب عيوف\nقد غدا القوم للنضار، فنالو … ه، وبتنا ومن لنا بالزيوف\nأولا يبصر الفتى الذهب الأح … مر، تحذى به نعال السيوف؟\nللحديد العلا على سائر الجو … هر، ذل العدى وعز الضيوف"},{"id":"diwan-maarri:896","bookId":"diwan-maarri","type":"poem","seq":896,"chapter":"قصائد","title":"أيا والي المصر لا تظلمن،","page":"","text":"أيا والي المصر لا تظلمن، … فكم جاء مثلك ثم انصرف\nوقد أبر النخل ملاكه، … وقيض غيرهم، فاخترف\nإن القول حرفه كاذب، … فإن القضاء به ما انحرف\nفلا ترسلن حبال الرجا، … وأمسك بكفك منها طرف\nتواضع، إذا ما رزقت العلاء، … فذلك مما يزيد الشرف\nودارك أحسن إلى جارها، … ولا تجعلن لها مشترف\nوإن ألبس الله ثوب الشفاء، … فلا تؤثرن عليه الترف\nتغيض المياه، وقد طالما … تيممها وارد، فاغترف\nومن أمنته خطوب المنون، … تخوف من هرم، أو خرف\nيقارف مستكبرات الذنوب، … ويغفل عن ذنبه المقترف\nولي منزل، في الثرى، ما يزار، … ولو رامه زائر ما عرف\nوقد لمت أن جمدت أدمعي، … وما لمت جفني لما ذرف"},{"id":"diwan-maarri:897","bookId":"diwan-maarri","type":"poem","seq":897,"chapter":"قصائد","title":"وجدت ابن آدم في غرة،","page":"","text":"وجدت ابن آدم في غرة، … بما يستفيد وما يطرف\nتعلق دنياه قبل الفطام، … وما زال يدأب حتى خرف\nوتسمو لطارفها عينه، … وخير لناظرها لو طرف\nيسر بها، عصر إقبالها … كأن تغيرها ما عرف\nويذرف، من حبها، دمعه، … وما يجلب الحظ دمع ذرف\nوكم مر، يوما، على قبره، … حسان الوجوه، فلم تشترف\nأيلتمس الماء من ناكز، … ويترك جما لمن يغترف؟\nولم يقترف من رضا ربه، … ولكن جرائمه يقترف\nكعامل قوم أساء الصنيع، … ولا ريب في أنه ينصرف\nوقد جاء، غافلنا، رزقه، … وإن كان للقوت لم يحترف\nأيا ظبية القاع! خافي الرماة، … ولا يخدعنك روض يرف"},{"id":"diwan-maarri:898","bookId":"diwan-maarri","type":"poem","seq":898,"chapter":"قصائد","title":"راعد تحته صلف،","page":"","text":"راعد تحته صلف، … ودم كله ظلف\nويح شماء، للثرى … شمم الأنف والذلف\nفتن الشيخ بالحيا … ة، وإن كان قد دلف\nيفهم المرء صاحبي … ه، على أنه ألف\nفاتق الله وحده، … وتحمل له الكلف\nوافعل الخير، فالحدي … ث كثير قد اختلف\nلا تقومن في المسا … جد، ترجو بها الزلف\nمعملا بسط راحتي … ك إلى نائل يلف\nورم الرزق في البلا … د، فإن رمته ازدلف\nواظلف النفس، والطري … د سريع إلى الظلف\nوتلاف الذي مضى، … قبل أن ينزل التلف\nحلف الدهر جاهدا، … وهو بر، إذا حلف\nليبتن كل عق … د، إذا نظمه ائتلف\nلو تراءى لناظر … بان، في وجهه، الكلف\nسل بقابوس أرضه، … وسجستان عن خلف\nولجيما عن الفوا … رس، حتى أبي دلف\nسلف القوم نعمة، … ثم بادوا كمن سلف"},{"id":"diwan-maarri:899","bookId":"diwan-maarri","type":"poem","seq":899,"chapter":"قصائد","title":"وجوهكم كلف، وأفواهكم عدى،","page":"","text":"وجوهكم كلف، وأفواهكم عدى، … وأكبادكم سود، وأعينكم زرق\nوما بي طرق للمسير ولا السرى، … لأني ضرير، لا تضيء لي الطرق\nأغربانك السحم استقلت مع الضحى … سوانح، أم مرت حمائمك الورق\nرحلت، فلا دنيا ولا دين نلته، … وما أوبتي إلا السفاهة والخرق\nمتى يخلص التقوى، لمولاه، لا تغض … عطاياه من صلى وقبلته الشرق\nأرى حيوان الأرض يرهب حتفه، … ويفزعه رعد، ويطمعه برق\nفيا طائر ائمني، ويا ظبي لا تخف … شذاي، فما بيني وبينكما فرق"},{"id":"diwan-maarri:900","bookId":"diwan-maarri","type":"poem","seq":900,"chapter":"قصائد","title":"لعمرك! ما في الأرض كهل مجرب،","page":"","text":"لعمرك! ما في الأرض كهل مجرب، … ولا ناشىء إلا لإثم مراهق\nإذا بض بالشيء القليل، فإنه، … لسوء السجايا، بالتبجح فاهق\nولو كان، من هذي الشواهق، سيد، … ثنته المنايا، وهو بالنفس شاهق\nوكم من جواد فيهم شهدت له … نواهقه، والشاحجات النواهق"},{"id":"diwan-maarri:901","bookId":"diwan-maarri","type":"poem","seq":901,"chapter":"قصائد","title":"متى ينفع الأقوام حي يكن له","page":"","text":"متى ينفع الأقوام حي يكن له … أذاة بهم، والحين بالنفس لاحق\nفما تسحق، المرو، الأكف، ولا الحصا … ولكن يغادي، إثمد العين، ساحق\nفإن بورك الخير الذي أنت صانع، … فأهل، وإلا فالخطوب مواحق"},{"id":"diwan-maarri:902","bookId":"diwan-maarri","type":"poem","seq":902,"chapter":"قصائد","title":"أرى الناس شرا من زمان حواهم؛","page":"","text":"أرى الناس شرا من زمان حواهم؛ … فهل وجدت للعالمين حقائق؟\nوقد كذبوا عن ساعة ودقيقة، … وما كذبت ساعاتهم والدقائق\nإذا لم يكن لي، بالشقيقة، منزل، … فلا طهرت عزاؤها والشقائق"},{"id":"diwan-maarri:903","bookId":"diwan-maarri","type":"poem","seq":903,"chapter":"قصائد","title":"أراني، في قيد الحياة، مكلفا","page":"","text":"أراني، في قيد الحياة، مكلفا … ثقائل، أمشي تحتها وأطابق\nإذا كنت في دار الشقاء مصليا، … فإنك، في دار السعادة، سابق\nإذا الحر لم ينهض بفرض صلاته، … فذلك عبد، من يد الدهر، آبق\nتقي يعاني ظمئه، ومضلل … له صابح، من غير حل، وغابق"},{"id":"diwan-maarri:904","bookId":"diwan-maarri","type":"poem","seq":904,"chapter":"قصائد","title":"فؤادك خفاق وبرقك خافق،","page":"","text":"فؤادك خفاق وبرقك خافق، … وأعياك في الدنيا خليل موافق\nتخير، فإما وحدة مثل ميتة؛ … وإما جليس، في الحياة، منافق\nأردت رفيقا كي ينالك رفقه، … فدعه، إذا لم تأت منه المرافق"},{"id":"diwan-maarri:905","bookId":"diwan-maarri","type":"poem","seq":905,"chapter":"قصائد","title":"إذا خطب الزهراء شيخ له غنى","page":"","text":"إذا خطب الزهراء شيخ له غنى … وناشىء عدم، آثرت من تعانق\nوقل غناء عن فتاة، وزوجها، … أخو هرم، أحجالها والمخانق\nوإن حاولت، ركب الظلام، نياقهم، … فتلك، لعمر الله، بئس الأيانق\nوما تستوي الأخدان، قيم هذه … مسن، وللأخرى ولي غرانق\nتوقوا سبيل الغانيات، فكلها … كليث الشرى، والطيب فيها فرانق"},{"id":"diwan-maarri:906","bookId":"diwan-maarri","type":"poem","seq":906,"chapter":"قصائد","title":"أرقت، فهل نجم الدجنة آرق،","page":"","text":"أرقت، فهل نجم الدجنة آرق، … وتجري الغوادي، بالردى، والطوارق\nويطربني، بعد النهى، قول قائل: … سقى بارقا من جانب الغور بارق\nأبى الدهر جودا بالسرور، وإن دنا … إليه الفتى، أو ناله، فهو سارق\nهل اليوم إلا شارق ثم غارب، … أو الليل إلا غارب ثم شارق؟\nمرازب كسرى ما وقت مهجة له، … وقيصر لم يمنع، رداه، البطارق\nويغبر في الأيام، من طال عمره، … فتغبر، من طول البقاء، المفارق\nمحا ألفات الشرخ عن طرس شيبه، … لتخلو من لون الشباب المهارق\nوما زال، في شرب الأباريق، كارها … لما بعثته، في الرياح، الأبارق\nيعافون تربا فيه تطوى جسومهم، … ومنه بحق فرشها والنمارق\nويشبه كعبا إذا بكى، ومتمما، … لدى كل عقل، معبد ومخارق\nنظير ابنة الجون، التي النوح شأنها، … مغنية، عن صوتها، اللب مارق"},{"id":"diwan-maarri:907","bookId":"diwan-maarri","type":"poem","seq":907,"chapter":"قصائد","title":"أيعلم نجم طارق برزية،","page":"","text":"أيعلم نجم طارق برزية، … من الدهر، أم لا هم للإنس طارقه؟\nوهل فرقد الخضراء، في الجو، موقن … بأن أخاه، بعد حين، مفارقه؟\nوما أرقته الحادثات، وكلنا، … إذا ناب خطب، ساهر الليل، آرقه\nلقد مر حرس، بعد حرس، جميعه، … حنادس لم يذرر، مع الصبح، شارقه\nتغيرت الأشياء، والملك ثابت؛ … مغاربه موفورة ومشارقه\nمراد جرت أقلامه، فتبادرت، … بأمر، وجفت بالقضاء مهارقه\nوهل أفلت، الأيام، كسرى، وحوله … مرازبه، أو قيصر وبطارقه؟\nأبارق هذا الموت سبح ربه؟ … نعم! وأعانت أكمه وأبارقه\nودنياك ليست للسرور معدة، … فمن ناله من أهلها، فهو سارقه\nوقد عشت حتى لو ترى العيش لاح لي … هباء، كنسج العنكبوت شبارقه\nفخف دعوة المظلوم، إن دعاءه … ملم بنوري الحجاب وخارقه\nيخادع ملك الأرض، حتى إذا أتت … منيته، لم تغن عنه مخارقه"},{"id":"diwan-maarri:908","bookId":"diwan-maarri","type":"poem","seq":908,"chapter":"قصائد","title":"طباع الورى فيها النفاق، فأقصهم","page":"","text":"طباع الورى فيها النفاق، فأقصهم … وحيدا، ولا تصحب خليلا تنافقه\nوما تحسن الأيام أن ترزق الفتى، … وإن كان ذا حظ، صديقا يوافقه\nيضاحك خل خله، وضميره … عبوس، وضاع الود لولا مرافقه"},{"id":"diwan-maarri:909","bookId":"diwan-maarri","type":"poem","seq":909,"chapter":"قصائد","title":"يسيء امرؤ منا، فيبغض دائما،","page":"","text":"يسيء امرؤ منا، فيبغض دائما، … ودنياك ما زالت تسيء وتومق\nأسر هواها الشيخ والكهل والفتى، … بجهل، فمن كل النواظر ترمق\nوما هي أهل أن يؤهل مثلها … لود، ولكن ابن آدم أحمق"},{"id":"diwan-maarri:910","bookId":"diwan-maarri","type":"poem","seq":910,"chapter":"قصائد","title":"خير لآدم والخلق، الذي خرجوا","page":"","text":"خير لآدم والخلق، الذي خرجوا … من ظهره، أن يكونوا قبل ما خلقوا\nفهل أحس، وبالي جسمه رمم، … بما رآه بنوه من أذى، ولقوا؟\nوما تريد بدار لست مالكها، … تقيم فيها قليلا ثم تنطلق؟\nفارقتها، غير محمود، على سخط، … وفي ضميرك، من وجد بها، علق\nتبوأ الشخص، من غبراء مظلمة، … قرارة، بعدما أزرى به القلق\nتكون للروح ثوبا ثم يخلعه، … والثوب ينهج حتى الدرع والحلق\nوأخلقته الليالي في تجددها، … والغدر منهن في أخلاقه خلق\nوالناس شتى، فيعطى المقت صادقهم، … عن الأمور، ويحبى الكاذب الملق\nيغدو إلى المين من قلت دراهمه، … فيجمع المال ما يفري ويختلق\nوربما عذل الإنسان مهجته … في الصدق، حين يرى جد الذي يلق\nويخلف الظن، في الأشياء، صاحبه، … والغيم يكدي، وداعي البرق يأتلق"},{"id":"diwan-maarri:911","bookId":"diwan-maarri","type":"poem","seq":911,"chapter":"قصائد","title":"سلطانك النار، إن تعدل، فنافعة،","page":"","text":"سلطانك النار، إن تعدل، فنافعة، … وإن تجر، فلها ضير وإحراق\nوقربه اللج، إن أعطاك فائدة، … فليس يؤمن إهلاك وإغراق\nوالمال رزق، فمن يدركه يحظ به، … وليس يغنيك إشآم وإعراق\nوالحق كالشمس، وارتها حنادسها، … فما لها، في عيون الناس، إشراق"},{"id":"diwan-maarri:912","bookId":"diwan-maarri","type":"poem","seq":912,"chapter":"قصائد","title":"يغنيك ما حل في السجايا،","page":"","text":"يغنيك ما حل في السجايا، … أن يتعدى بك الفسوق\nكيف يطيق النهوض عاد، … عليه، من مأثم، وسوق؟\nكم غرست نخلة بأرض، … فلم يقدر لها بسوق\nلا يفرحن، بالحياة، غر، … فإنها، مهلكا، تسوق\nما نفق الصدق في البرايا، … ولم تزل للمحال سوق"},{"id":"diwan-maarri:913","bookId":"diwan-maarri","type":"poem","seq":913,"chapter":"قصائد","title":"أنافق في الحياة، كفعل غيري،","page":"","text":"أنافق في الحياة، كفعل غيري، … وكل الناس شأنهم النفاق\nأعلل مهجتي، ويصيح دهري: … ألا تغدو، فقد ذهب الرفاق\nبلى، والسير من أفعال غيري، … وإن طال اتكاء وارتفاق\nتخالفت البرية في العطايا، … ويجمعها لدى الهلك اتفاق\nأنصفق أن تغيرنا الليالي، … ويسمع، من مزاهرنا، اصطفاق؟"},{"id":"diwan-maarri:914","bookId":"diwan-maarri","type":"poem","seq":914,"chapter":"قصائد","title":"فرق بدا، ومن الحوادث يفرق","page":"","text":"فرق بدا، ومن الحوادث يفرق … شيخ يغادى، بالخطوب، ويطرق\nسبحان خالقنا، وطاء أغبر، … من تحتنا، وله غطاء أزرق\nوالشهب، في بحر السماء، سوابح، … تطفو لناظرة العيون، وتغرق\nأعرقت خيلك في محاولة الغنى، … وحواه غيرك مشئم، أو معرق\nوأخو الحجى، في أمره، متحير، … جمع، التجارب، عمره المتفرق\nوتعهد ابن العبد برقة ثهمد، … فمضى وشيكا، واستقر الأبرق\nعز الذي أعفى الجماد، فما ترى … حجرا يغص بمأكل، أو يشرق\nمتعريا في صيفه وشتائه، … ما ريع، قط، لملبس يتخرق\nمتجلدا، أو خلته متبلدا، … لا دمع فيه، بفادح، يترقرق\nلا حس يؤلمه، فيظهر مجزعا، … إن راح يضرب ملطس، أو مطرق\nلم يغد غدوة طائر متكسب، … وافاه، يلقط، أجدل أو زرق\nأحمام ما لك في ركوب حمائم … ورق، ومن شر الركاب الأورق؟\nوالصخر يلبث، لا يقارف مرة … ذنبا، ولا هو، من حياء، مطرق\nوالدهر أخرق، ما اهتدى لصنيعة، … وبنوه كلهم سفيه أخرق\nوتشابهت أجسامنا، وتخالفت … أغراضنا، فمغرب ومشرق\nيا هم! ويحك غيرتك نوائب؛ … والغصن يورق، في الزمان، ويورق\nملأت صحيفتك الذنوب، وفعلك … الحبر الأحم، وفود رأسك مهرق\nوكأنما نفض الرماد، كآبة، … فوق الجبين، وقلبك المتحرق\nلص الكرى ملك الردى، في زعمهم؛ … إن الحياة، من الأنام، لتسرق\nمن يعط شيئا يستلبه، ومن ينم، … جنح الظلام، فإنه سيؤرق\nزجر الغراب، تطيرا، ونقيضه … ديك، لأهل الدار، أبيض أفرق\nهذا السفاه، كأننا حمضية، … أو خيط بلقعة غذاه العشرق"},{"id":"diwan-maarri:915","bookId":"diwan-maarri","type":"poem","seq":915,"chapter":"قصائد","title":"الدهر يزبق من حواه، كأنهم","page":"","text":"الدهر يزبق من حواه، كأنهم … شعر يغير، فهو أحمر أزبق\nوالبهم يربق، والأنام بهائم … أبدا تقيد، بالقضاء، وتربق\nفلك يدور على معاشر جمة، … وكأنه سجن عليهم مطبق\nفي كل حين يستهل، من الأذى، … مطر، يخص أماكنا، ويطبق\nمهج تهارش في الخسيس، وإن غدت … كالنابحات، فكل طعم خربق\nلا تفرحن بما بلغت من العلا، … وإذا سبقت، فعن قليل تسبق\nوليحذر، الدعوى، اللبيب، فإنها، … للفضل، مهلكة، وخطب موبق\nلو قال بدر التم: إني درهم؛ … قالت له السفهاء: أنت مزأبق\nإياك والدنيا، فإن لباسها … يبلي الجسوم، وطيبها لا يعبق\nولها هموم، بالنفوس لوابق، … وسرورها، بصدورنا، لا يلبق\nوالله خالقنا لأمر شاءه، … أبق العبيد، وعبده لا يأبق"},{"id":"diwan-maarri:916","bookId":"diwan-maarri","type":"poem","seq":916,"chapter":"قصائد","title":"الغيب مجهول، يحار دليله؛","page":"","text":"الغيب مجهول، يحار دليله؛ … واللب يأمر أهله أن يتقوا\nلا تظلموا الموتى، وإن طال المدى؛ … إني أخاف عليكم أن تلتقوا\nهذي المهابط والمغابط صورت … للعالمين، ليهبطوا، أو يرتقوا\nلا تدعوا عتقا على مولاكم، … فالرأي أوجب أنكم لم تعتقوا\nلم تستطيعوا أن تقوا مهجاتكم، … فتخيروا، قبل الندامة، وانتقوا\nإن مسكم ظمأ، فقول نذيركم: … لا ذنب لي، قد قلت للقوم: استقوا"},{"id":"diwan-maarri:917","bookId":"diwan-maarri","type":"poem","seq":917,"chapter":"قصائد","title":"ما ركب الخائن، في فعله،","page":"","text":"ما ركب الخائن، في فعله، … أقبح مما ركب السارق\nشتان مأمون وذو خلسة، … كأنه، من عجل، بارق\nقد آنست، فعلك، شهب الدجى، … ليلا، وقد أبصرك الشارق\nفكيف لم تحرقك شمس الضحى؛ … وكيف لا يرجمك الطارق؟\nهذي طباع الناس معروفة، … فخالطوا العالم، أو فارقوا"},{"id":"diwan-maarri:918","bookId":"diwan-maarri","type":"poem","seq":918,"chapter":"قصائد","title":"يا ناق صبرا أنت في أينق،","page":"","text":"يا ناق صبرا أنت في أينق، … شطت مراعيها وأيناقها\nأغراضها حالت بإغراضها، … وقد برى الأعناق إعناقها"},{"id":"diwan-maarri:919","bookId":"diwan-maarri","type":"poem","seq":919,"chapter":"قصائد","title":"ألم ير أفعالك، الشارق،","page":"","text":"ألم ير أفعالك، الشارق، … وكوكب ليلتك الطارق؟\nتخون أمينك ديناره، … وفي ربعه يقطع السارق"},{"id":"diwan-maarri:920","bookId":"diwan-maarri","type":"poem","seq":920,"chapter":"قصائد","title":"إذا رشقت دنياك هذي إلى الفتى،","page":"","text":"إذا رشقت دنياك هذي إلى الفتى، … رمته بنبل من غوايتها رشقا\nفتحرجه غما، وتوسعه أذى، … وإن ذمها جهرا أسر لها عشقا\nوقد زعموا أن الشقي هو الذي … حوى السعد فيها، والسعادة للأشقى\nفإن كان حقا ما يقال، فإنها … منام يعيد النقس، في حكمه\nأرى أم دفر أهلها أم عنبر … فما صرفوا عنها معاطسهم نشقا"},{"id":"diwan-maarri:921","bookId":"diwan-maarri","type":"poem","seq":921,"chapter":"قصائد","title":"لسان الفتى يدعى سنانا، وتارة","page":"","text":"لسان الفتى يدعى سنانا، وتارة … حساما، وكم من لفظة ضربت عنقا\nلقد ورد الناس الحياة أمامنا، … فما تركوا إلا الأجونة والرنقا\nوأنقى سواد الرأس دهر وغاسل … لباسا، فأما سوء طبع، فما أنقى"},{"id":"diwan-maarri:922","bookId":"diwan-maarri","type":"poem","seq":922,"chapter":"قصائد","title":"هو الرزق يجريه المليك، ولن ترى","page":"","text":"هو الرزق يجريه المليك، ولن ترى … أخا عيشة، بالحرص، يطعم أو يسقى\nوكم أمر العقل السليم بصالح، … فما فعلوا إلا الخيانة والفسقا"},{"id":"diwan-maarri:923","bookId":"diwan-maarri","type":"poem","seq":923,"chapter":"قصائد","title":"يباين شكل غيره، في حياته،","page":"","text":"يباين شكل غيره، في حياته، … فإن هلكا، لم تلف، بينهما، فرقا\nومن يفتقد حال الزمان وأهله، … يذم بهم غربا، من الأرض، أو شرقا\nيجد قولهم مينا، وودهم قلى، … وخيرهم شرا، وصنعتهم خرقا\nوبشرهم خدعا، وفقرهم غنى، … وعلمهم جهلا، وحكمتهم زرقا\nأحي كلاب! كم رعى النبت قبلكم … فريق، وشاموا، في حنادسهم، برقا\nوصابوا على عاف، وآبوا إلى رضى، … وجابوا إلى علياء نازحة خرقا\nوليلا طلى قارا بقار، وأكمه … مراقبة، من شهبه، حدقا زرقا\nإذا نشأت فيه الغمامة خلتها، … بإيماضها، زنجية فصدت عرقا\nومروا بمقصود الحمام، فغادروا … خوالد ضمت فيه أفرخها الورقا\nرأينا شؤون الدهر خفضا ورفعة، … ونحن أسارى، في الحوادث، أو غرقى\nهوى معتل، كالغيث م المزن، واعتلى … خفيض، كنقع، من لدن حافر، يرقى\nفلا تأمنوا شامية يمنية … تعادي، فلا تبقي خباء ولا فرقا\nيخرق، درع المرء، سمر رماحها، … وإن كان مرا، في مذاقته، خرقا\nإذا طلبوا أقصى العلا اتخذوا له، … بصم العوالي، في ترائبكم، طرقا\nإذا كنتم أوراق أثل زهوا لكم … جراد نبال، كي تبيدكم، ورقا\nأطارق هم ضاف، هل أنت عاذر، … متى لم تجد بي، عند مرتحل، طرقا؟\nوأعوزني ماء أزيل به الصدى، … فلا عيش، إن لم أشرب الكدر الطرقا\nهم الناس، أجبال شوامخ في الذرى، … وأودية لا تبلغ الأكم والبرقا\nفسكران يسترقى، ويبذل بسلة، … وآخر صاحي اللب، يغضب أن يرقى"},{"id":"diwan-maarri:924","bookId":"diwan-maarri","type":"poem","seq":924,"chapter":"قصائد","title":"إذا سلقت عرس الفتى في كلامها،","page":"","text":"إذا سلقت عرس الفتى في كلامها، … فما هي إلا سلقة عارضت سلقا\nوأحسن أثواب الأوانس بردة … من الحسن، لا تنضى لغسل ولا تلقى\nويفعل، فعلا سيئا، رب منظر … جميل، ويأتي الخير من لم يرق خلقا\nوما أم غيلان محرمة الصلى، … ولا أم ليلى، في محابسها، طلقا"},{"id":"diwan-maarri:925","bookId":"diwan-maarri","type":"poem","seq":925,"chapter":"قصائد","title":"عليك بتقوى الله في كل مشهد،","page":"","text":"عليك بتقوى الله في كل مشهد، … فلله ما أذكى نسيما، وما أبقى\nإذا ما ركبت الحزم، مستبطنا له، … سبقت به من لا تظن له سبقا\nوحبي للدنيا كحبك خالص، … وفي عنقينا، من هوى، جعلت ربقا\nحذرنا، فصادتنا الخلوب كغيرنا، … وأي غراب ما أجادت له طبقا"},{"id":"diwan-maarri:926","bookId":"diwan-maarri","type":"poem","seq":926,"chapter":"قصائد","title":"سقينا بفضل الله، والأرض منزل","page":"","text":"سقينا بفضل الله، والأرض منزل … يحل به من ليس أهلا لأن يسقى\nوما طهرت بالعشر خمسة أوسق، … نفوس أقلت، من مآثمها، وسقا\nوفي كل أرض أمة جعلوا التقى … هي الشيمة الشنعاء، واستحسنوا الفسقا"},{"id":"diwan-maarri:927","bookId":"diwan-maarri","type":"poem","seq":927,"chapter":"قصائد","title":"إذا ما استهل الطفل قال ولاته،","page":"","text":"إذا ما استهل الطفل قال ولاته، … وإن صمتوا: عان الخطوب ورشقها\nشقينا بدنيانا، على طول ودها، … فدونك مارسها، حياتك، واشقها\nولا تظهرن الزهد فيها، فكلنا … شهيد بأن القلب يضمر عشقها"},{"id":"diwan-maarri:928","bookId":"diwan-maarri","type":"poem","seq":928,"chapter":"قصائد","title":"جاء القران، وأمر الله أرسله،","page":"","text":"جاء القران، وأمر الله أرسله، … وكان ستر على الأديان، فانخرقا\nما أبرم الملك، إلا عاد منتقضا؛ … ولا تألف إلا شت وافترقا\nمذاهب، جعلوها من معايشهم، … من يعمل الفكر فيها تعطه الأرقا\nإحذر سليلك، فالنار التي خرجت … من زندها، إن أصابت عوده احترقا\nوكلنا قوم سوء، لا أخص به … بعض الأنام، ولكن أجمع الفرقا\nلا ترجون أخا منهم، ولا ولدا، … وإن رأيت حياء أسبغ العرقا\nوالنفس شر من الأعداء كلهم، … وإن خلت بك يوما، فاحترز فرقا\nكم سيد، بارق الجدوى بميسمه، … ساووا به الجدي، عند الحتف، والبرقا\nإن رمت من شيخ رهط، في ديانته، … دليل عقل على ما قاله خرقا\nوكيف أجني، ولم يورق لهم غصني؛ … والغصن لم يجن حتى ألبس الورقا\nعز المهيمن! كم من راحة بتكت … ظلما، وكان سواها يأخذ السرقا\nوالدر لاقى المنايا في أكفهم، … وكم ثوى البحر لا يخشى به غرقا\nمين يردد، لم يرضوا بباطله، … حتى أبانوا، إلى تصديقه، طرقا\nلا رشد، فاصمت، ولا تسألهم رشدا، … فاللب، في الإنس، طيف زائر طرقا\nوآكل القوت لم يعدم له عنتا؛ … وشارب الماء لم يأمن به شرقا\nوناظر العين والدنيا به رئيت، … ما إن درى أسوادا حل أم زرقا\nإذا كشفت عن الرهبان، حالهم، … فكلهم يتوخى التبر والورقا"},{"id":"diwan-maarri:929","bookId":"diwan-maarri","type":"poem","seq":929,"chapter":"قصائد","title":"المرء كالبدر بينا لاح، كاملة","page":"","text":"المرء كالبدر بينا لاح، كاملة … أنواره، عاد للنقصان فامتحقا\nوالناس كالزرع باق في منابته، … حتى يهيج، ومرعي وما لحقا\nعل البلى سيفيد الشخص فائدة، … فالمسك يزداد من طيب، إذا سحقا"},{"id":"diwan-maarri:930","bookId":"diwan-maarri","type":"poem","seq":930,"chapter":"قصائد","title":"لا تلحقني مينا، إن نطقت به،","page":"","text":"لا تلحقني مينا، إن نطقت به، … إن الغريب، إذا ألحقته لحقا\nأما الجماد، فإني بت أغبطه، … إذ ليس يعلم إما آد أو محقا\nلا يشعر العود بالنار التي أخذت … فيه، ولا الأصهب الداري إذ سحقا"},{"id":"diwan-maarri:931","bookId":"diwan-maarri","type":"poem","seq":931,"chapter":"قصائد","title":"قل للحمامة قد أصبحت شادية،","page":"","text":"قل للحمامة قد أصبحت شادية، … فهجت للذاكر المحزون تشويقا\nكساك ربك ريشا تدفعين به، … قر الشتاء، وحلى الجيد تطويقا\nفهل تراعين من باز على شرف، … يهدي إليك، عن الفرخين، تعويقا؟\nأما ترين قسي الدهر وترها … رام مصيب، أعار النبل تفويقا؟\nيغنيك وكرك عن بيت يزينه … غاو، من القوم، إذهابا وتزويقا"},{"id":"diwan-maarri:932","bookId":"diwan-maarri","type":"poem","seq":932,"chapter":"قصائد","title":"ما راعها من قرى عم وجارمها،","page":"","text":"ما راعها من قرى عم وجارمها، … إلا الأباريق يحملن الأباريقا\nومومسات توافيها حنادسها … بطارقين، يخالون البطاريقا\nلم يكفهم ريق كرم، من شرابهم، … حتى أضافوا إليه، من فم، ريقا\nلو عجلت، لغوي فاجر، سقر، … لأشعروا جمرات النار تحريقا\nلقد تفكرت في الدنيا وساكنها، … فأحدث الفكر أشجانا وتأريقا\nقد أغرقوا في معاصيهم، فما لهم … لا يؤنسون، من الطوفان، تغريقا؟\nوصيروا لأناس ، في الأذى، طرقا … وذللوا الإثم إعمالا وتطريقا\nأعرق آدم هذا لا يمازجه … سواه، أم مس، من إبليس، تعريقا؟\nيخشى، ذوي رطيب حامل ثمرا، … مؤمل، من غصون اليبس، توريقا\nكم تطلب المال في سهل وفي جبل، … وتقطع الأرض تغريبا وتشريقا\nوقد شهدت مخاريق الوغى لعبت، … مجيدة، لدروع القوم، تخريقا\nفراقب الله! إن السعد يتبعه … نحس، وإن، لجمع الدهر، تفريقا\nومر موسى ولم يترك، لأمته، … إلا أحاديث يودعن المهاريقا"},{"id":"diwan-maarri:933","bookId":"diwan-maarri","type":"poem","seq":933,"chapter":"قصائد","title":"يا حاديينا! ألا سوقا بنا سحرا؛","page":"","text":"يا حاديينا! ألا سوقا بنا سحرا؛ … ويا وميضي هوانا والصبا شوقا\nلا يغرض المرء مما يغتدي غرضا، … يمسي ويضحي، بنبل الدهر، مرشوقا\nحناه دهر، فضاهى القوس من كبر، … وقد تراه، كصدر الرمح، ممشوقا\nولى الشباب، ومن شوق لرؤيته، … يظل مشبهه، في الروض، منشوقا\nمن كان عن آل هند والرباب سلا، … فما يزال بقاء الدهر معشوقا"},{"id":"diwan-maarri:934","bookId":"diwan-maarri","type":"poem","seq":934,"chapter":"قصائد","title":"مهر الفتاة، إذا غلا، صون لها،","page":"","text":"مهر الفتاة، إذا غلا، صون لها، … من أن يبت عشيرها تطليقها\nهوي الفراق، وخاف من إغرامه، … فأدام، في أسبابه، تعليقها\nولربما ورثته، أو سبقت بها … أقدار ميتتها، فكان طليقها"},{"id":"diwan-maarri:935","bookId":"diwan-maarri","type":"poem","seq":935,"chapter":"قصائد","title":"ما غاب إسحاق البرايا عنهم،","page":"","text":"ما غاب إسحاق البرايا عنهم، … فاسأل بني يعقوب عن إسحاقا\nما في جميع الناس إلا خاسر، … فإليهم رجع القبيح وحاقا\nلا نعلم الموتى تهم بكرة، … لكن أحياء تروم لحاقا\nلو صح أن البدر ليس بعاقل، … هنأته ألا يحس محاقا"},{"id":"diwan-maarri:936","bookId":"diwan-maarri","type":"poem","seq":936,"chapter":"قصائد","title":"لدنياك حسن، على أنني،","page":"","text":"لدنياك حسن، على أنني، … أرى حسنها حسنا، مخلقا\nفما طلقت هي بل طلقت، … ولست بأول من طلقا\nفلا تأسفن على مطلب … يفوت، إذا بابه أغلقا\nأرى حلبا حازها صالح، … وجال سنان على جلقا\nوحسان في سلفي طيىء، … يصرف، من عزه، أبلقا\nفلما رأت خيلهم، بالغبار، … ثغاما، على جيشهم، علقا\nرمت جامع الرملة المستضام، … فأصبح، بالدم، قد خلقا\nوما ينفع، الكاعب المستبا … ة، هام، على عضب، فلقا\nوطل قتيل، فلم يدكر، … وغل أسير، فما أطلقا\nوكم تركت آهلا وحده؛ … وكم غادرت مثريا مملقا\nيسائل في الحي عن ماله، … وما القول في طائر حلقا\nولم يك دهرهم شاعرا، … ولكنه لم يزل مفلقا\nإذا كان هذا فعال الزمان، … فإن به، كامنا، أولقا\nفليت السماكين لم يطلعا؛ … وليت المنيرين لم يخلقا"},{"id":"diwan-maarri:937","bookId":"diwan-maarri","type":"poem","seq":937,"chapter":"قصائد","title":"يقولون: في المصر العدول، وإنما","page":"","text":"يقولون: في المصر العدول، وإنما … حقيقة ما قالوا: العدول عن الحق\nولست بمختار لقومي كونهم … قضاة، ولا وضع الشهادة في رق"},{"id":"diwan-maarri:938","bookId":"diwan-maarri","type":"poem","seq":938,"chapter":"قصائد","title":"لقد ساس أهل الأرض قوم تفتقت","page":"","text":"لقد ساس أهل الأرض قوم تفتقت … أمور، فما ألفت لهم يد راتق\nهم هتكوا بالراح أستار عاذل، … ولم يحفظوا بالنسك حرمة ناتق\nإذا جرحوا دنا، فلم يرج عندهم … قصاصا، أجادوا قتل عذراء عاتق\nوصاغوا بما تجني الولاة مراكنا، … وزادوا على أسيافهم والمناتق\nولو كان للدنيا، لدى الله، قيمة، … لما نظروا في آهلات الرساتق"},{"id":"diwan-maarri:939","bookId":"diwan-maarri","type":"poem","seq":939,"chapter":"قصائد","title":"ألا هل أتى، قبر الفقيرة، طارق،","page":"","text":"ألا هل أتى، قبر الفقيرة، طارق، … يخبرها بالغيب عن فعل طارق\nتنصر من بعد الثلاثين حجة، … وكم لاح شيب، قبلها، في المفارق\nوما هب من نوم الصبا يطلب النهى، … مع الفجر، إلا وهي في كف شارق\nوفارق دين الوالدين بزائل، … ولولا ضلال بالفتى لم يفارق\nفوا عجبا من أزرق العين، غادر، … أفاد، فمالت نفسه للأزارق\nفكم من سوار رد نبل أساور، … ومن أرق شوقا إلى ذات يارق\nفبعدا لها من زلة في مغارب، … من الأرض، يثنى خزيها، ومشارق\nصلاة الأمير الكاسمي بمسجد، … أبر وأزكى من صلاة البطارق\nمخاريق تبدو في الكنائس منهم، … بلحن لهم، يحكي غناء مخارق\nوإن حجازي النمار ولبسها، … لأشرف من ديباجهم والنمارق\nأرى مهرق الدمعات يوجب سفحه … جنايات خطب، أثبتت في المهارق\nوما عاق، لب الفيل، عن ذكر أهله … ومغناه، إلا ضربه بالمطارق\nعددت زمانا في السيوف، أو القنا، … فأصبحت نكسا في السهام الموارق\nوحسبك من عار، يشب وقوده، … سجودك للصلبان في كل شارق\nرأيت وجوها كالدنانير أحكمت … زنانير، فانظر ما حديث المعارق\nفدونك خنزيرا تعرق عظمه، … لتوجد كالطائي تدعى بعارق\nوما حزن الإسلام مغداك زاريا … عليه، ولكن رحت روحة فارق\nوآثرت حر النار، تسعر دائما، … على الفقر، أو غصن له غير وارق\nوأحلف ما ضر، الكريم، ظهوره … مع الرهط، يمشي في القميص الشبارق\nتجرع موت، لا تجرع لذة … من الخمر، في كاساتهم والأبارق\nتركت ضياء الشمس يهديك نورها، … وتبعت، في الظلماء، لمحة بارق"},{"id":"diwan-maarri:940","bookId":"diwan-maarri","type":"poem","seq":940,"chapter":"قصائد","title":"سألت عن الأجيال في كل برهة،","page":"","text":"سألت عن الأجيال في كل برهة، … فكانوا فريقا سار إثر فريق\nكأن بريقا، لامرىء القيس، لامعا، … أغص جميع الشائمين بريق\nوخرق ثوب العيش طول لباسه، … وهبت حريق طيرت بحريق\nإذا أنت عاتبت المقادير، لم تزل … كعتبة، أو كالأخنس بن شريق\nوما زال يخبي، جاهدا، نار قومه، … أبو لهب، حتى مضى لحريق\nألم تر أن المرء، فوق فراشه، … يفوق على ظمء فواق غريق؟\nفإني أرى البطريق والراهب، الذي … بقلته، سارا معا بطريق\nيغير بالمريق عشر بنانه، … خضاب حمام، للنفوس، مريق\nوما يترك الضرغام في أجماته؛ … ولا ذات روق في ظلال وريق"},{"id":"diwan-maarri:941","bookId":"diwan-maarri","type":"poem","seq":941,"chapter":"قصائد","title":"لنا أرب، لم نقضه منك، فادكر،","page":"","text":"لنا أرب، لم نقضه منك، فادكر، … لك الخير، هل بعد الحمام تلاق؟\nأرى أم دفر أخلقتني، وجزتها … إلى غيرها، سيرا بغير خلاق\nستأخذ إرثي، وهي في غير عدة، … ومذ زمن جهزتها بطلاق"},{"id":"diwan-maarri:942","bookId":"diwan-maarri","type":"poem","seq":942,"chapter":"قصائد","title":"قد آن مني ترحال، ولم أفق،","page":"","text":"قد آن مني ترحال، ولم أفق، … والسكر يفضح في الركبان والرفق\nقل ما تشاء، ولا ترهبك عاذلة، … إن النفاق لمردود إلى النفق\nأخبرتني بأحاديث مناقضة، … فرابني، منك، قول غير متفق\nما خضب رأس كخضب في بنان يد، … وحمرة الفجر ليست حمرة الشفق\nتمضي الحوادث بالحوراء، راتعة، … بين الخمائل، والجوزاء في الأفق"},{"id":"diwan-maarri:943","bookId":"diwan-maarri","type":"poem","seq":943,"chapter":"قصائد","title":"تستروا بأمور في ديانتهم،","page":"","text":"تستروا بأمور في ديانتهم، … وإنما دينهم دين الزناديق\nنكذب العقل في تصديق كاذبهم؛ … والعقل أولى بإكرام وتصديق"},{"id":"diwan-maarri:944","bookId":"diwan-maarri","type":"poem","seq":944,"chapter":"قصائد","title":"يا تاجر المصر! ما أنصفت سائمة،","page":"","text":"يا تاجر المصر! ما أنصفت سائمة، … كذبتها في حديث منك منسوق\nإن تشك قطع طريق بالفلاة، فكم … قطعت، من قبل، طرق الناس في السوق"},{"id":"diwan-maarri:945","bookId":"diwan-maarri","type":"poem","seq":945,"chapter":"قصائد","title":"اعمل لأخراك شروى من يموت غدا،","page":"","text":"اعمل لأخراك شروى من يموت غدا، … وادأب لدنياك، فعل الغابر الباقي\nإن البهائم، مثل الإنس، غافلة؛ … وإنما نحن بهم ذات أرباق\nوأم شبلين في غيل ومأسدة، … كأم خشفين في شت وطباق\nوالمرء يسبق، فيما ليس يكسبه … نفعا، وليس إلى خير بسباق"},{"id":"diwan-maarri:946","bookId":"diwan-maarri","type":"poem","seq":946,"chapter":"قصائد","title":"لقد فنيت، وهل تبقى، إذا عمرت،","page":"","text":"لقد فنيت، وهل تبقى، إذا عمرت، … جوالة بين تغريب وإشراق؟\nوكم سحابة قوم غر لامعها، … وإن دعتك بإرعاد وإبراق\nإن السيوف مخاريق، إذا عصيت … بها الفوارس أودى كل مخراق\nأورقت عصرا، فإن أورقت في طلب، … فإن إيراق كفي هاج إيراقي\nوالجد يأتيك بالأشياء ممكنة، … ولا تنال بإشآم وإعراق\nأغرقت في حبي الدنيا، على سفه، … فقد تكسبت إحراقا بإغراق\nأطرق كرى، ليس لي علم بشأن غد، … ولا لغيري، ولا يحزنك إطراقي\nفالحمد لله ما فارقت سيئة، … وكيف لي من ضنى دين بإفراق؟\nوالنسك لا نسك موجود فنبغيه، … فعد عن فقهاء اللفظ، مراق\nوما احتيالي في الأقدار، إن جعلت … عصب التجار لشعث الهام سراق\nهذب سجاياك لا يكثر بها دنس، … من الدنايا، ليرقى، في العلا، راق\nفكل مرآة قوم زبرة صقلت، … حتى أرتهم بصافي اللون رقراق\nيرقي المعزم ولدانا ليورثهم … نفعا، ولا نفع إلا بسلة الراقي"},{"id":"diwan-maarri:947","bookId":"diwan-maarri","type":"poem","seq":947,"chapter":"قصائد","title":"لقاء الناس ألجأني، برغمي،","page":"","text":"لقاء الناس ألجأني، برغمي، … إلى حسن التجمل والنفاق\nوما ألقى عريبا باختياري، … ولكن حم ذلك باتفاق\nوقد يغشى الفتى لجج المنايا، … حذارا من أحاديث الرفاق\nوتصطفق المزاهر مخبرات، … زواهر، في المآثم، باصطفاق"},{"id":"diwan-maarri:948","bookId":"diwan-maarri","type":"poem","seq":948,"chapter":"قصائد","title":"إذا كانت لك امرأة حصان،","page":"","text":"إذا كانت لك امرأة حصان، … فأنت محسد بين الفريق\nفإن جمعت إلى الإحصان عقلا، … فبورك مثمر الغصن الوريق\nولا تأمن، فإن النفس أضحت … إلى النكراء، كالريح الخريق\nولا تجعل فناءك مستضاما، … بمطلع يكون إلى الطريق\nوما النكبات إلا موج بحر، … يظل الحي فيها كالغريق\nومن لم تشرق الدنيا بماء، … فأقسم أن ستشرقه بريق"},{"id":"diwan-maarri:949","bookId":"diwan-maarri","type":"poem","seq":949,"chapter":"قصائد","title":"أما الحقيقة، فهي أني ذاهب،","page":"","text":"أما الحقيقة، فهي أني ذاهب، … والله يعلم بالذي أنا لاق\nوأظنني، من بعد، لست بذاكر … ما كان من يسر، ومن إملاق\nلم ألف كالثقفي، بل عرسي هي الس … وداء، ما جهزتها بطلاق\nعجبا لبرديها الدجنة والضحى، … ووشاحها من نجمها المقلاق\nكم أخلق العصران مهجة معصر، … وهما على أمن من الإخلاق\nدنياك غادرة، وإن صادت فتى … بالخلق، فهي ذميمة الأخلاق\nيستمطر الأغمار من لذاتها، … سحبا تليح بمومض ألاق\nلم تلق وابلها، ولكن خلتها … خيلا مسومة مع العلاق\nوإذا المنى فتحت رتاج معيشة، … بكرت عليه بمحكم الإغلاق\nومتى رضيت بصاحب من أهلها، … فلقد منيت بكاذب ملاق\nشهب يسيرها القضاء، وتحتها … خلق تشاهدها، بغير خلاق\nما لي وللنفر، الذين عهدتهم … بالكرخ من شاش ومن إيلاق\nحلق مجادلة كشرب مهلهل، … شربوا على رغم بكأس حلاق\nوالروح طائر محبس في سجنه، … حتى يمن رداه بالإطلاق\nسيموت محمود ويهلك آلك، … ويدوم وجه الواحد الخلاق\nيا مرحبا بالموت من متنظر، … إن كان ثم تعارف وتلاق\nساعاتنا، تحت النفوس، نجائب … وخدت بهن بعيدة الإطلاق\nألق الحياة إلى الممات، مجردا؛ … إن الحياة كثيرة الأعلاق\nما زلت تجتابين حلة فارك، … حتى رميت بمصلف مطلاق"},{"id":"diwan-maarri:950","bookId":"diwan-maarri","type":"poem","seq":950,"chapter":"قصائد","title":"ظهور الركاب، عند اللبيب،","page":"","text":"ظهور الركاب، عند اللبيب، … أولى به من ظهور الطرق\nفإن راقه منظر مسه … بإثم، ويؤذيه إن لم يرق\nإذا لم تعن، أو تغث شاكيا، … فإن الجلوس عليها خرق"},{"id":"diwan-maarri:951","bookId":"diwan-maarri","type":"poem","seq":951,"chapter":"قصائد","title":"أسأت بعبدك في عسفه،","page":"","text":"أسأت بعبدك في عسفه، … وحملت عيرك ما لم يطق\nوسوف يجازيك رب السماء، … فشمر لأحكامه، وانتطق"},{"id":"diwan-maarri:952","bookId":"diwan-maarri","type":"poem","seq":952,"chapter":"قصائد","title":"هو الفلك الدوار، أجراه ربه","page":"","text":"هو الفلك الدوار، أجراه ربه … على ما ترى، من قبل أن تجري الفلك\nله العز، لم يشركه، في الملك، غيره؛ … فيا جهل إنسان يقول: لي الملك\nوأيامه منظومة في حياته؛ … ولا نظم يبقى حين يمتلىء السلك\nخلقنا لشيء غير باد، وإنما … نعيش قليلا، ثم يدركنا الهلك\nكخيل صيام تألك، الدهر، لجمها … بغيظ، فقد أدمى نواجذها الألك"},{"id":"diwan-maarri:953","bookId":"diwan-maarri","type":"poem","seq":953,"chapter":"قصائد","title":"لخالقنا الحكم القديم، وكم فتى","page":"","text":"لخالقنا الحكم القديم، وكم فتى … له خلق رحب وعيشته ضنك\nفهون عليك الخطب، ما فتىء الردى … يجيش على كسرى الجيوش، فمن زنك\nإذا ألجأتهم ساعة، من زمانهم، … إلى الشر، لم يغنوا فتيلا، ولم ينكوا\nأفنك هذا، أيها الدهر، سادرا، … وتأتي المنايا بعدما لقي الفنك\nلعنك ينجاب الظلام، فتهتدي، … إذا عنك، في رأد الضحى، ذهب العنك"},{"id":"diwan-maarri:954","bookId":"diwan-maarri","type":"poem","seq":954,"chapter":"قصائد","title":"تدين غاويهم حذار أميرهم،","page":"","text":"تدين غاويهم حذار أميرهم، … فلما انقضت أيامه ذهب النسك\nفأصبح، من بعد التمسك بالتقى، … لأردانه من طيب فاجرة مسك\nوهل ينفع التمسيك والمسك، تحته … خبيث نبيث، والذي فوقه المسك؟\nإذا مسك الإعدام، فاصبر ولا تكن … جزوعا، لكي يردى الفتى وبه مسك"},{"id":"diwan-maarri:955","bookId":"diwan-maarri","type":"poem","seq":955,"chapter":"قصائد","title":"تمسك بتقوى الله، لست بقائل","page":"","text":"تمسك بتقوى الله، لست بقائل … تمسك، ومعناي السوار، ولا المسك\nومن يبل بالدنيا وسوء فعالها، … فليس له إلا التعبد والنسك"},{"id":"diwan-maarri:956","bookId":"diwan-maarri","type":"poem","seq":956,"chapter":"قصائد","title":"ضحكنا، وكان الضحك منا سفاهة،","page":"","text":"ضحكنا، وكان الضحك منا سفاهة، … وحق لسكان البسيطة أن يبكوا\nيحطمنا ريب الزمان، كأننا … زجاج، ولكن لا يعاد له سبك"},{"id":"diwan-maarri:957","bookId":"diwan-maarri","type":"poem","seq":957,"chapter":"قصائد","title":"دع الناس واصحب واخش بيداء قفرة،","page":"","text":"دع الناس واصحب واخش بيداء قفرة، … فإن رضاهم غاية ليس تدرك\nإذا ذكروا المخلوق عابوا وأطنبوا؛ … وإن ذكروا الخلاق حابوا وأشركوا\nكلفت بدنياك، التي هي خدعة، … وهل خلة منها أغر وأفرك؟\nإذا سمحت عادت لما سمحت به، … وكم أذنبت، والذنب، بالأرض، يعرك\nولو لم يكن فينا هواها غريزة، … لكان إذا جر المهالك يترك\nمتى أنا تالي الركب، فوق مطية، … على منهل، يغني عن الماء، تبرك\nإذا فاتك الإثراء من غير وجهه، … فإن قليل الخل أولى وأبرك\nونحن، بعلم الله، من متحرك … يرى ساكنا، أو ساكن يتحرك"},{"id":"diwan-maarri:958","bookId":"diwan-maarri","type":"poem","seq":958,"chapter":"قصائد","title":"عليك بتقوى الله في كل حالة،","page":"","text":"عليك بتقوى الله في كل حالة، … فإن الذي نص الركاب سيبرك\nإذا مرت الأوقات حرك ساكن، … وسكن، في أضعافها، المتحرك\nتباين في الدين المقال، فجاحد، … وصاحب توحيد، وآخر مشرك\nوتعجز دنياك القوي يرومها، … ويطلب، أخراه، الضعيف، فيدرك\nومن للفتى، وهو الشقي بأنه … يدوم على ضنك الشقاء، ويترك\nولم أر إلا أم دفر ظعينة، … تحب على غدر قبيح، وتفرك"},{"id":"diwan-maarri:959","bookId":"diwan-maarri","type":"poem","seq":959,"chapter":"قصائد","title":"كأن إبارا، في المفارق، خيطت","page":"","text":"كأن إبارا، في المفارق، خيطت … برود المنايا، والليالي سلوكها\nيرى الفكر أن النور، في الدهر، محدث، … وما عنصر الأوقات، إلا حلوكها\nفلا ترغبوا في الملك تعصون بالظبا … عليه، فمن أشقى الرجال ملوكها\nوإن غروب الشمس، كل عشية، … يحدث أهل اللب عنه دلوكها\nوما فتئت رسل الحمام تزورنا، … إذا لم تشافه، ذكرتنا ألوكها\nفكونوا جيادا أضمرت، خوف غارة، … صوائم إلا من شكيم تلوكها"},{"id":"diwan-maarri:960","bookId":"diwan-maarri","type":"poem","seq":960,"chapter":"قصائد","title":"لو صح ما قال رسطاليس، من قدم،","page":"","text":"لو صح ما قال رسطاليس، من قدم، … وهب من مات لم يجمعهم الفلك\nومذهبي، في البرايا، كونهم شيعا، … كالثلج والقار، منه الجون والحلك\nما اسود حام لذنب كان أحدثه، … لكن غريزة لون خطها الملك\nإن لم يكن، في سماء فوقنا، بشر، … فليس في الأرض، أو ما تحتها، ملك\nكم حل، حيث تبنى الحي، من أمم، … ثم انقضوا، وسبيلا واحدا سلكوا\nإن تسأل العقل، لا يوجدك من خبر … عن الأوائل، إلا أنهم هلكوا"},{"id":"diwan-maarri:961","bookId":"diwan-maarri","type":"poem","seq":961,"chapter":"قصائد","title":"يجوز أن تطفأ الشمس التي وقدت","page":"","text":"يجوز أن تطفأ الشمس التي وقدت … من عهد عاد، وأذكى نارها الملك\nفإن خبت في طوال الدهر حمرتها، … فلا محالة من أن ينقض الفلك\nمضى الأنام، فلولا علم حالهم، … لقلت قول زهير: أية سلكوا\nفي الملك لم يخرجوا عنه، ولا انتقلوا … منه، فكيف اعتقادي أنهم هلكوا؟"},{"id":"diwan-maarri:962","bookId":"diwan-maarri","type":"poem","seq":962,"chapter":"قصائد","title":"لا تأسفن على شيء تفات به،","page":"","text":"لا تأسفن على شيء تفات به، … فقد تساوى لديك الجون والكرك\nوالعز ينقل عن ناس لغيرهم، … والأسد تعدو وفي آذانها فرك\nنفسي أخاطب، والدنيا لها غير، … وفي الحمام، إذا طال المدى، درك\nوطنتها للذي تلقاه من غرق، … لما أحس، بهلك المركب، العرك\nيا طائرا من سجون الدهر في قفص، … لتذبحن، فلا سجن ولا شرك\nما بال حظي عني قاعدا أبدا، … إن كان من نبت أرض، فاسمه البرك\nتكسى الوجوه جمالا، ثم تسلبه، … ويجمع المال، حرصا، ثم يترك\nوالعيش أين، وفي مثوى امرىء دعة، … والله فرد، وشرب الموت مشترك"},{"id":"diwan-maarri:963","bookId":"diwan-maarri","type":"poem","seq":963,"chapter":"قصائد","title":"لانت، على المس بالأيدي، جسومهم،","page":"","text":"لانت، على المس بالأيدي، جسومهم، … وفي الصدور، لعمري، ينبت الحسك\nفي الحرب عقل رجال، إن هم قتلوا؛ … وفي الحجى عقل نسوان لها مسك\nتمسكوا بحبال النسك في زمن، … ولاح نزر، فخلوا ما به امتسكوا"},{"id":"diwan-maarri:964","bookId":"diwan-maarri","type":"poem","seq":964,"chapter":"قصائد","title":"أزول، وليس في الخلاق شك،","page":"","text":"أزول، وليس في الخلاق شك، … فلا تبكوا علي، ولا تبكوا\nخذوا سيري، فهن لكم صلاح، … وصلوا في حياتكم، وزكوا\nولا تصغوا إلى أخبار قوم، … يصدق، مينها، العقل الأرك\nأرى عملا كلا عمل، وأمرا … يجر، فساده، قدر مصك\nوأسطارا تمثل فوق طرس، … وتطمس، بعد ذلك، أو تحك\nولولا أنكم ظلم، غواة، … لصدكم الذكاء، فلم تذكوا\nكأنكم، بني حواء، وحش، … تضمنها السماوة والأبك\nأتى المسرى على شرفات كسرى، … وأورث ملكه خان وكك\nفهل عاينتم، في الأرض، حيا، … وليس عليه للحدثان صك؟\nهي الأيام، من وهد يعلى، … بأبنية، ومن قصر يدك\nوما نفع الأوائل، من قريش، … ولاة الحجر، ما اجتذبوا ومكوا\nفلا تشقوا بنصركم أميرا، … كما شقيت به كلب وعك\nوما الإنسان، في التطواف، إلا … أسير للزمان، فهل يفك؟"},{"id":"diwan-maarri:965","bookId":"diwan-maarri","type":"poem","seq":965,"chapter":"قصائد","title":"سفكت دم الدنان، وما تشكت،","page":"","text":"سفكت دم الدنان، وما تشكت، … ويشكى، من دم الأقوام، سفك\nأعفك، عن يسار تبتغيه، … رجال، من بني حواء، عفك\nلفك الريح عن أمر عجيب، … يخبر أن أهل الأرض لفك\nإذا أفكوا، فلا تقبل وميز، … فأكثر ما جلوه عليك إفك"},{"id":"diwan-maarri:966","bookId":"diwan-maarri","type":"poem","seq":966,"chapter":"قصائد","title":"ركب الأنام، من الزمان، مطية،","page":"","text":"ركب الأنام، من الزمان، مطية، … ليست كما اعتاد الركائب تبرك\nواها لدنيانا الذميمة منزلا، … لو أن هذا الشخص فيها يترك\nوهويتها، فرأيت خلة غادر، … ورضيت أنك، في وصالك، تشرك\nوالمرء مثل الحرف، بين سهاده … وكراه، يسكن تارة، ويحرك\nقد يدرك الساعي لباريه رضا، … فرضا البرية غاية لا تدرك"},{"id":"diwan-maarri:967","bookId":"diwan-maarri","type":"poem","seq":967,"chapter":"قصائد","title":"طلب النساء شبابه، حتى إذا","page":"","text":"طلب النساء شبابه، حتى إذا … وضحت مفارقه تأهل ينسك\nوجزته، في عرس له، أيامه، … بفعاله، ولكل حبل ممسك\nتفل وفى بالعهد، ليس بذي حلى، … خير من الغدار، وهو ممسك\nمن مسك ذي دارين، أو مسك غدا … يلقى، بصنعتها، العبير ويعسك\nعنوان القصيدة : يا كند! ما خلت السكون تحركت … يا كند! ما خلت السكون تحركت\nبعد السكون، ولا أخوها السكسك … نوب فرسنك لا يروق عيونها\nحلل تلوح، كأنهن الفرسك … حقد الزمان حسيكة في صدره،"},{"id":"diwan-maarri:968","bookId":"diwan-maarri","type":"poem","seq":968,"chapter":"قصائد","title":"عمل كلا عمل، ووقت فائت،","page":"","text":"عمل كلا عمل، ووقت فائت، … ويد إذا ملكت رمت ما تملك\nوشخوص أقوام تلوح، فأمة … قدمت مجددة، وأخرى تهلك\nأما الجسوم فللتراب مآلها، … وعييت بالأرواح أنى تسلك"},{"id":"diwan-maarri:969","bookId":"diwan-maarri","type":"poem","seq":969,"chapter":"قصائد","title":"تسمت رجال بالملوك سفاهة،","page":"","text":"تسمت رجال بالملوك سفاهة، … ولا ملك إلا للذي خلق الملكا\nأرى فلكا ما دار إلا لحكمة، … فلا تنس من أجرى، لحاجتك، الفلكا\nومدت حبال الشمس، من قبل عصرنا، … على أمم، لم تترك لهم سلكا\nوتعجبنا الدنيا الهلوك، وإنها … لأم رجال كلهم سقي الهلكا\nهما حالتا سوء: حياة بلوعة، … وموت، فخير هذه النفس أو تلكا"},{"id":"diwan-maarri:970","bookId":"diwan-maarri","type":"poem","seq":970,"chapter":"قصائد","title":"أرى كل خير، في الزمان، مفارقا،","page":"","text":"أرى كل خير، في الزمان، مفارقا، … فلا تأسفن فيها لقلة خيركا\nودنياك سارت بالأنام مغذة، … فلا فرق فيها بين سيري وسيركا\nأصاح! أتدري كيف، بعدك، حالها؟ … أجل مثل ما شاهدته بعد غيركا\nفإن كنت لا تسطيع، للنفع، كثرة، … فلا تعدمنك النفس قلة ضيركا"},{"id":"diwan-maarri:971","bookId":"diwan-maarri","type":"poem","seq":971,"chapter":"قصائد","title":"أيا مفرقي! هلا ابيضضت على المدى،","page":"","text":"أيا مفرقي! هلا ابيضضت على المدى، … فما سرني أن بت أسود حالكا\nقبيح بفود الشيخ تشبيه لونه … بفود الفتى، والله يعلم ذلكا\nفبعدا لهذا الجسم، يا روح، مسلكا؛ … وبعدا لهذي الروح، يا جسم، سالكا\nتواصلتما، فاستحدث الوصل منكما … عجائب، كانت للرجال مهالكا"},{"id":"diwan-maarri:972","bookId":"diwan-maarri","type":"poem","seq":972,"chapter":"قصائد","title":"سأفعل خيرا ما استطعت، فلا تقم","page":"","text":"سأفعل خيرا ما استطعت، فلا تقم … علي صلاة، يوم أصبح هالكا\nفما فيكم من خير يدعى به، … يفرج عني، بالمضيق، المسالكا\nفمن مبلغ عني المآلك معشرا: … عليا ومحمودا وخانا وآلكا\nفما أتمنى أنني كأجلكم، … ولكن أضاهي المقترين الصعالكا\nوينفر عقلي مغضبا إن تركته … سدى، واتبعت الشافعي ومالكا"},{"id":"diwan-maarri:973","bookId":"diwan-maarri","type":"poem","seq":973,"chapter":"قصائد","title":"إذا قال فيك الناس ما لا تحبه،","page":"","text":"إذا قال فيك الناس ما لا تحبه، … فصبرا يفىء ود العدو إليكا\nوقد نطقوا مينا على الله، وافتروا، … فما لهم لا يفترون عليكا؟\nولو صرت سلكا ما حماني تضاؤلي … حماما، توخى عامرا وسليكا\nففارق، إلى الله، الجديدين راضيا، … ولا تعقد الأدناس في سمليكا\nمللت مسيرا فوق نضويك، فالتمس … نزولك بالصحراء عن جمليكا"},{"id":"diwan-maarri:974","bookId":"diwan-maarri","type":"poem","seq":974,"chapter":"قصائد","title":"رأيت بجنح، في الزمان، حلوكا،","page":"","text":"رأيت بجنح، في الزمان، حلوكا، … وللشمس فيها مشرقا ودلوكا\nخطبت إلى الدنيا بجهلك نفسها، … فلم تستطع فيما أردت سلوكا\nوهل ينكح المرء الموفق أمه، … ولو أصبحت بين الرجال هلوكا؟\nوكم حل فيها معشر، بعد معشر … من الناس، عاشوا سوقة وملوكا\nفما بلغتهم منك، بعد رحيلهم، … ألوك، ولا أهدوا إليك ألوكا\nوقفت على أجداثهم، وسألتهم، … فما رجعوا قولا ولا سألوكا\nولا علم لي من أمرهم، غير أنهم … لو انتبهوا من رقدة عذلوكا\nتخلفت بعد الظاعنين، كأنهم … رأوك أخا وهن، فما حملوكا"},{"id":"diwan-maarri:975","bookId":"diwan-maarri","type":"poem","seq":975,"chapter":"قصائد","title":"الموت ربع فناء، لم يضع قدما","page":"","text":"الموت ربع فناء، لم يضع قدما … فيه امرؤ، فثناها نحو ما تركا\nوالملك لله، من يظفر بنيل غنى … يردده قسرا، وتضمن نفسه الدركا\nلو كان لي أو لغيري قدر أنملة، … فوق التراب، لكان الأمر مشتركا\nولو صفا العقل، ألقى الثقل حامله … عنه، ولم تر في الهيجاء معتركا\nإن الأديم، الذي ألقاه صاحبه، … يرضي القبيلة في تقسيمه شركا\nدع القطاة، فإن تقدر لفيك تبت … إليه تسري، ولم تنصب لها شركا\nوللمنايا سعى الساعون، مذ خلقوا، … فلا تبالي أنص الركب أم أركا\nوالحتف أيسر، والأرواح ناظرة … طلاقها من حليل، طالما فركا\nوالشخص مثل نجيب رام عنبرة … من المنون، فلما سافها بركا"},{"id":"diwan-maarri:976","bookId":"diwan-maarri","type":"poem","seq":976,"chapter":"قصائد","title":"خف يا كريم على عرض تعرضه","page":"","text":"خف يا كريم على عرض تعرضه … لعائب، فلئيم لا يقاس بكا\nإن الزجاجة لما حطمت سبكت، … وكم تكسر من در، فما سبكا"},{"id":"diwan-maarri:977","bookId":"diwan-maarri","type":"poem","seq":977,"chapter":"قصائد","title":"إن يرسل النفس في اللذات صاحبها،","page":"","text":"إن يرسل النفس في اللذات صاحبها، … فما يخلدن صعلوكا ولا ملكا\nومن يطهر بخوف الله مهجته، … فذاك إنسان قوم يشبه الملكا\nوشارب الخمر يلفى، من غوايته، … كأن مارد جنان به سلكا\nتغير العقل، حتى يستجيز به … مد اليمين، لكيما تقبض الفلكا\nتبيت عنها عديم الزاد، مخفقه، … وقد توهمت أن الخافقين لكا\nعمر الغريزة عشرون اقتفت مائة؛ … هيهات أي لجام، قلما ألكا\nوما أسائل، عن شخص، لمولده … عشر وتسعون، إلا قيل قد هلكا\nتمسخت في أمور، غير طائلة، … سهد ونوم، ووفت نصفها حلكا\nوالمرء يحرص إما ضاربا فرسا … إلى المنون، وإما راكبا فلكا"},{"id":"diwan-maarri:978","bookId":"diwan-maarri","type":"poem","seq":978,"chapter":"قصائد","title":"تظل كفي لحرفي، إن لمست بها","page":"","text":"تظل كفي لحرفي، إن لمست بها … سهيك طيب، كأخرى باشرت سهكا\nتغشى النوائب حالي، وهي رازحة، … كالشعر يلقى زحافا بعدما نهكا"},{"id":"diwan-maarri:979","bookId":"diwan-maarri","type":"poem","seq":979,"chapter":"قصائد","title":"أم الكتاب، إذا قومت محكمها،","page":"","text":"أم الكتاب، إذا قومت محكمها، … وجدتها لأداء الفرض تكفيكا\nلم يشف قلبك فرقان ولا عظة؛ … وآية، لو أطعت الله، تشفيكا\nما لي علمتك، إن أوضعت في كذب، … كأنك الشعر لم تكذب قوافيكا\nكالبحر بالشام مر لا يصاب به … در، ومن شر راد القوم طافيكا\nومن سجايا المخازي أن ترى أشرا، … ترمي عشيرك بالداء الذي فيكا\nتجاف هجرا، فلا ألقاك معتذرا، … فأي أي حياة في تجافيكا؟\nوهل ألم ودادا رم من شعث، … وقد لمحت تلافي في تلافيكا\nولم أصاحبك في تيهاء مقفرة، … بها يصافن ماء من يصافيكا\nإياك عني، فأخشى أن تحرقني، … فإنما تقذف النيران من فيكا\nما نال داريك الداري من أرج، … لكن منافثك الأدنى منافيكا\nمن لي بأني أرض، ما فعلت بها … من القبيح، استقرت لا تكافيكا\nعافاني الله مما بت جانيه، … فلم يزل من جناياتي يعافيكا\nولو فريت أديمي فري ملتمس … نفعا، لما آلمت نفسي أشافيكا\nإذا ابتهجت وأعطاك المليك غنى، … غدوت كالربع لم تحمد عوافيكا\nيحلك الحي، بعد الحي، عن شحط، … وما سوافك إلا من سوافيكا\nتلقي أثافي قول غير متئب، … فما يبوخ سعير من أثافيكا\nوآجن حوضك الملآن من أسن، … وقد تشهر بالإشراق صافيكا\nظلت خوافيك، والبلوى مكشفة، … قوادما، وبدا للإنس خافيكا\nكعلة الجسم أدنته إلى شجب، … يعد أشنع من غدر توافيكا"},{"id":"diwan-maarri:980","bookId":"diwan-maarri","type":"poem","seq":980,"chapter":"قصائد","title":"قل للمشيب: يد الأيام دائبة،","page":"","text":"قل للمشيب: يد الأيام دائبة، … تنقيك، والمرء، من جهل، ينقيكا\nلو كنت كالجبل الراسي لأودني، … بالثقل، أنك في رأسي ترقيكا\nوكيف يقطع إنسان مدى أجل … عليك، والملك الديان يبقيكا!\nفلا الأساة، أطالت في تفكرها، … تشفي ضناك، ولا الكهان ترقيكا\nلما صببت سقيت الوجد، منحنيا، … من الصبيب، أو الحناء يسقيكا\nلاقاك بالخطر مغرور على خطر، … وكنت بالعطر أولى في تلقيكا\nيقص آثار أقوام أولي سفه، … وبالمقصين في النعماء يشقيكا\nيا صبغة الله من أعطاك واقية، … فإن صبغ أناس لا يوقيكا"},{"id":"diwan-maarri:981","bookId":"diwan-maarri","type":"poem","seq":981,"chapter":"قصائد","title":"كن صاحب الخير تنويه وتفعله،","page":"","text":"كن صاحب الخير تنويه وتفعله، … مع الأنام، على أن لا يدينوكا\nإذا طلبت نداهم صرت ضدهم، … وإن ترد منهم عزا يهينوكا\nفعش بنفسك، فالإخوان أكثرهم … إلا يشينوك، يوما، لا يزينوكا\nوكم أعانك ناس ما استعنت بهم، … أو استعنت بقوم لم يعينوكا"},{"id":"diwan-maarri:982","bookId":"diwan-maarri","type":"poem","seq":982,"chapter":"قصائد","title":"شفاء ما بك أعياني وأعياكا،","page":"","text":"شفاء ما بك أعياني وأعياكا، … فارج الذي هو أبداني وإياكا\nما لي أراك غبيا لست تقدر أن … تحصي خطاك، فهل تحصي خطاياكا؟\nوكيف تعجز عن إدراك مرتحل، … والليل والصبح كانا من مطاياكا\nقد أرذياك بسير، إن ركبتهما، … ولم يصير بحال من رزاياكا\nأذهبت يوما، فلم تعدده مرزية، … وعد ذاهب مال من رزاياكا\nوالعمر أنفس ما الإنسان منفقه، … فاجعله لله تحمد في سجاياكا\nواغفر لعبدك ما يجنيه من زلل، … ولا تأي بسوء من تأياكا\nيا أيها الملك، ما آساك في نفس، … معاشر، بأبيت اللعن، حياكا\nولا عجوز مكناة وغانية، … كلتاهما في المغاني من سباياكا\nسقيت في حدثان السلم أسقية، … فقد نسيت لذيذا من حمياكا\nوأنت بالليل، تسمو الحادثات إلى … سهاك عمدا، ولا تخلي ثرياكا"},{"id":"diwan-maarri:983","bookId":"diwan-maarri","type":"poem","seq":983,"chapter":"قصائد","title":"هل آن للقيد أن تفكه؟","page":"","text":"هل آن للقيد أن تفكه؟ … إن قبيح الفعال حكه\nبكل أرض أمير سوء، … يضرب للناس شر سكه\nقد كثر الغش، واستعانت … به الأشداء والأركه\nفما ترى مسكة بحال، … إلا وقد موزجت بسكه!\nولم يجد سائل عليما، … يزيل بالموضحات شكه\nكم فارس يغتدي لغاب، … وفارس يقتدي بشكه\nفخلهم والذي أرادوا، … وحل بالقدس، أو بمكه\nصكهم الدهر صك أعمى، … تكتب أيدي الفناء صكه\nقد ثربت يثرب عليهم، … وبكة المسلمين بكه"},{"id":"diwan-maarri:984","bookId":"diwan-maarri","type":"poem","seq":984,"chapter":"قصائد","title":"عش يا ابن آدم عدة الوزن الذي","page":"","text":"عش يا ابن آدم عدة الوزن الذي … يدعى الطويل، ولا تجاوز ذلكا\nفإذا بلغت، وأربعين، ثمانيا، … فحياة مثلك أن يوسد هالكا\nما سرني، والله يعلم غايتي، … أني كخان في الملوك وآلكا"},{"id":"diwan-maarri:985","bookId":"diwan-maarri","type":"poem","seq":985,"chapter":"قصائد","title":"أجمل بي من أن أعد امرأ،","page":"","text":"أجمل بي من أن أعد امرأ، … أوذيك في أهلك، أن أهلكا\nمالك تستجهلني دائما، … وإنما ذلك من جهلكا\nوكنت في سيرك مستعجلا، … فالآن سيرت على مهلكا"},{"id":"diwan-maarri:986","bookId":"diwan-maarri","type":"poem","seq":986,"chapter":"قصائد","title":"بطول سراك وترحالكا،","page":"","text":"بطول سراك وترحالكا، … وتمك من بعد إنحالكا\nتكلم، فخبر بني آدم … بما علم الله من حالكا\nأظنك غير مبالي الضمير، … بخصبك، يوما، وإمحالكا\nويا عالما بصروف الزمان، … كما علم القوم من ذلكا"},{"id":"diwan-maarri:987","bookId":"diwan-maarri","type":"poem","seq":987,"chapter":"قصائد","title":"وجدتكم لم تعرفوا سبل الهدى،","page":"","text":"وجدتكم لم تعرفوا سبل الهدى، … فلا توضحوا للقوم سبل المهالك\nأخير على مجرى قديم، كلهذم … يفرج، للخطي، ضيق المسالك؟\nوما الدهر إلا حالك بعد أبيض … يذيع بنا، أو أبيض بعد حالك\nبلوت أمور الناس من عهد آدم، … فلم أر إلا هالكا إثر هالك\nمتى مت، لم أحفل تحية واقف … علي، ولم أعلم بإحدى المآلك\nإذا كان هذا الترب يجمع بيننا، … فأهل الرزايا مثل أهل الممالك"},{"id":"diwan-maarri:988","bookId":"diwan-maarri","type":"poem","seq":988,"chapter":"قصائد","title":"كأن عقول القوم، والله شاهد،","page":"","text":"كأن عقول القوم، والله شاهد، … جمعن لهم من نافرات أوارك\nيميلون للدنيا، على سطواتها، … وما نشرت من شرها المتدارك\nوما هي إلا قسمة بين أهلها، … لكلهم فيها نصيب مشارك\nأقامت سليمان، الذي شاع ملكه، … يراقب أطهار النساء العوارك\nإذا بعثت منها إلى الأرض نائلا، … وإن قل، ألفته له غير تارك\nوكم أرسلت من طارق وملمة، … أبانت لها الركبان فوق الموارك\nوأركد فيها تحت عبء، لو انه … على العيس ما فرت به في المبارك\nتباركت يا رب العلا، أنت صغتها، … فليتك، في أرزائها، لم تبارك\nأعانقها عند الوداع، تشبثا، … وأي وداع بين قال وفارك!"},{"id":"diwan-maarri:989","bookId":"diwan-maarri","type":"poem","seq":989,"chapter":"قصائد","title":"بطن التراب كفاني شر ظاهره،","page":"","text":"بطن التراب كفاني شر ظاهره، … وبين العدل بين العبد والملك\nقد عشت عمرا طويلا، ماعلمت به … حسا يحس لجني ولا ملك\nوالملك لله، ما ضاعت أكابره، … ولا أصاغر أحياء، ولا هلك\nإن مات جسم فهذي الأرض تخزنه، … وإن نأت عنه روح، فهي بالفلك\nولو غدوت سليكا جاءني قدر، … أخا السرى، أو صغير السلك والسلك"},{"id":"diwan-maarri:990","bookId":"diwan-maarri","type":"poem","seq":990,"chapter":"قصائد","title":"ترقبن الهواء، بلطف رب","page":"","text":"ترقبن الهواء، بلطف رب … قدير، إن تركت له هواك\nبواك يبتغين من المنايا، … إذا قامت، على جدث، بواك\nحواك عنك أمرا غير زين، … يشين، إذا التراب غدا حواك\nذوى كالروض روضك يوم شبت … جمار من لظى أسف ذواك\nرواءك، فاشربي ودعي ثمادا، … وأحواضا يكون لها رواك\nزواك الله عن جنف وظلم، … فشكرا إن أنعمه زواك\nسواك أحق أن يلقى قذوفا … بطيب القول، طيبة السواك\nشواك منعته ذهبا مصوغا، … مخافة ما يفوه به شواك\nنواك هي التي لا ريب فيها، … وللأيام أقدار نواك\nلواك الله عنا، حين بتنا … قريبا من صريمك، أو لواك"},{"id":"diwan-maarri:991","bookId":"diwan-maarri","type":"poem","seq":991,"chapter":"قصائد","title":"متى تشرك مع امرأة سواها،","page":"","text":"متى تشرك مع امرأة سواها، … فقد أخطأت في الرأي التريك\nفلو يرجى، مع الشركاء، خير، … لما كان الإله بلا شريك"},{"id":"diwan-maarri:992","bookId":"diwan-maarri","type":"poem","seq":992,"chapter":"قصائد","title":"سبح وصل وطف، بمكة، زائرا،","page":"","text":"سبح وصل وطف، بمكة، زائرا، … سبعين، لاسبعا، فلست بناسك\nجهل الديانة من إذا عرضت له … أطماعه، لم يلف بالمتماسك"},{"id":"diwan-maarri:993","bookId":"diwan-maarri","type":"poem","seq":993,"chapter":"قصائد","title":"أتراك، يوما، قائلا، عن نية","page":"","text":"أتراك، يوما، قائلا، عن نية … خلصت، لنفسك: يا لجوج تراك\nأدراك دهرك عن تقاك بجهده، … فدراك، من قبل الفوات، دراك\nأبراك ربك، فوق ظهر مطية، … سارت لتبلغ ساعة الإبراك\nأفراكن أنا للزمان بمحصد، … بانت عليه شواهد الافراك؟\nأشراك ذنبك، والمهيمن غافر، … ما كان من خطإ سوى الإشراك\nما بال دينك ناقصا آلاته، … والنعل ما نفعت بغير شراك\nوعراك رازية الحقوق، فلم تقم … للحق إلا بعد طول عراك\nوأراك، يا سمع، الحمام، فلم تبن … سجع الحمام بأسجل وأراك\nأصبحت من سكن الحياة، وواجب، … يوما، سكوني بعد طول حراك\nوالطير تلتمس المعاش، غواديا، … في الأرض، وهي كثيرة الأشراك"},{"id":"diwan-maarri:994","bookId":"diwan-maarri","type":"poem","seq":994,"chapter":"قصائد","title":"إن كنت ذارع أرض لم ألمك بها،","page":"","text":"إن كنت ذارع أرض لم ألمك بها، … أو كنت ذارع خمر فالملامة لك\nكم سلت الراح من يمناك، خادعة، … سيف الرشاد، وأعطته لمن ختلك\nقتلتها بمزاج، وهي ثائرة، … بما فعلت، وكم مثل لها قتلك\nركبت منها كميتا خر فارسها، … ولو ركبت سواها أشهبا حملك\nتدعى الشموس، وما يعني بذاك لها … إلا الشماس، فجنب دائما ثملك\nإن الشمول رياح شمأل عصفت … باللب، والسكر غي فادح شملك\nأرح جمالك من غرض ومن قتب، … واجعل ظلامك، في نيل العلا، جملك\nأملتها للمغاني والغنى، زمنا، … فلم تنل من يسار، أو هوى، أملك\nأرسلت إبلك، قبل اليوم، هاملة، … وكان جدك يرعى، مرة، هملك\nأما الكبير، فما تزداد شيمته … إلا قبوحا، فحسن بالتقى عملك\nوانبذ، إلى من تشكى قرة، سملا … من الثياب، وأورد ظامئا سملك\nلا ترملن إلى الدنيا، تحاولها، … واصرف إلى الله معطيك المنى رملك\nلم تبد لي عنك، إلا مجملا، خبرا، … وقد شرحت لغيري، موضحا، جملك\nالأرض دار اهتضام، والأنام بها … مثل الذئاب، فأحرز دونهم حملك"},{"id":"diwan-maarri:995","bookId":"diwan-maarri","type":"poem","seq":995,"chapter":"قصائد","title":"يا سيد! هل لك في ظبي تغازله،","page":"","text":"يا سيد! هل لك في ظبي تغازله، … تلقي نيوبك، في تأشيره، قبلك\nهذي جبلة سوء غير صالحة؛ … فهل سوى الله، من أجناده، جبلك؟\nوكم حبلت وحوش الرمل راتعة، … ومن أمامك يوم شره حبلك\nترجو قبول مليك، لا نظير له، … وقد أتيت إلى عبد، فما قبلك\nبخلت بالهين المنزور، تبذله … لله خوفا، وكم حق له قبلك\nخمسون جرت عليها الذيل، ذاهبة؛ … تبا لعقلك إن شيء مضى تبلك\nنفرت من قول واش، بالكلام رمى، … وما غدا بك ما استوجبت لو نبلك\nأسبل، على السائل، المعروف مبتدرا، … تحمد، وأسبل على باغي الندى سبلك\nولا تكن، لسبيل الشر، مبتكرا؛ … واصرف إلى الخير من نهج الهدى سبلك"},{"id":"diwan-maarri:996","bookId":"diwan-maarri","type":"poem","seq":996,"chapter":"قصائد","title":"ربيت شبلا، فلما أن غدا أسدا","page":"","text":"ربيت شبلا، فلما أن غدا أسدا … عدا عليك، فلولا ربه أكلك\nجنيت أمرا، فود الشيخ من أسف، … لما جنيت على ذي السن لو ثكلك\nمرحت كالفرس الذيال، آونة، … ثم اعتراك أبو سعد، فقد شكلك\nإن اتكلت على من لا يضيع له … خلق، فإن قضاء الله ما وكلك\nلبست ذنبا، كريش الناعبات، متى … يرحض بدجلة يزدد في العيون حلك\nولو نضحت، على خديك، من ندم، … رشاش دمع بجفني تائب غسلك\nأشعرت هما، فزاد النوم طارقه، … كأنه، بسهاد واصب، كحلك\nفما نشطت لإخباري بفادحة، … أوضعت فيها، ولم أنشط لأن أسلك\nملائك تحتها إنس وسائمة؛ … فالأغبياء سوام والتقي ملك\nفلا تعلم صغير القوم معصية، … فذاك وزر، إلى أمثاله، عدلك\nفالسلك ما اسطاع يوما ثقب لؤلؤة، … لكن أصاب طريقا نافذا، فسلك\nيلحاك، في هجرك الإحسان، مضطغن … عليك، لولا اشتعال الضغن ما عذلك\nيريك نصرا، ولا يسخو بنصرته، … إلا اكتسابا، وإن خفت العدى خذلك\nمن يبد أمرك لا يذممك في خلف … ولا جهار، ولكن لام من جهلك\nأراد وردك أقوام لترويهم، … فالآن تشكو، إذا شاكي الصدى نهلك\nأمهلت في عنفوان الشرخ، آونة، … حتى كبرت وفضت برهة مهلك\nرماك بالقول ملحي تعد له … سيفا، أحدك بالنكراء، أو صقلك\nرآك شوك قتاد ليس يمكنه، … ولو رآك غضيض النبت لابتقلك\nلله داران: فالأولى، وثانية … أخرى، متى شاء في سلطانه نقلك"},{"id":"diwan-maarri:997","bookId":"diwan-maarri","type":"poem","seq":997,"chapter":"قصائد","title":"ألصبح أصبح، والظلا","page":"","text":"ألصبح أصبح، والظلا … م، كما تراه، أحم حالك\nيتباريان ويسلكا … ن، إلى الورى، ضيق المسالك\nأسدان يفترسان من … مرا به، فأبه لذلك\nحملا الممالك، عن ردى … قاض، إلى خان وآلك\nأودى الملوك على احترا … سهم، ولم تبق الممالك\nلا يكذبن مؤجل؛ … ما سالم إلا كهالك\nيا رضو! لا أرجو لقا … ءك، بل أخاف لقاء مالك"},{"id":"diwan-maarri:998","bookId":"diwan-maarri","type":"poem","seq":998,"chapter":"قصائد","title":"متى أهلك يا قومي،","page":"","text":"متى أهلك يا قومي، … فقد حق لي المهلك\nفقير كل من في الأر … ض، إن العبد لا يملك"},{"id":"diwan-maarri:999","bookId":"diwan-maarri","type":"poem","seq":999,"chapter":"قصائد","title":"ألا يا جون! ما وفقت","page":"","text":"ألا يا جون! ما وفقت … إن زايلت قاموسك\nورأيي لك، في العال … م، أن تلزم ناموسك\nوما يبقى، على الأيا … م، لا موسى، ولا موسك\nويا راهب! لا ألحا … ك أن تضرب ناقوسك\nوما أجنأ من جاءك، … يرمي بالأذى قوسك\nوما تعصمك الوحد … ة، أن تنزل ناووسك\nويا رازي! ما للخي … ل لا تمنع شالوسك؟\nأخاف الدهر أن يبد … ل نعماء الغنى بوسك\nأسعد المشتري أوح … ش، من عزك، مأنوسك\nألا تنهض للحرب، … وتدعو، للوغى، شوسك؟\nوكم تحبس زريابك، … في السجن، وطاووسك؟\nفإن الوحش، في البيدا … ء، ضاهى سوسها سوسك\nولا تأمن، في الحند … س، من وطئك فاعوسك\nومن عادات ريب الده … ر أن يذعر بابوسك\nفسل نعمانك الأو … ل، عن ذاك، وقابوسك"},{"id":"diwan-maarri:1000","bookId":"diwan-maarri","type":"poem","seq":1000,"chapter":"قصائد","title":"شربت الراح بالراح،","page":"","text":"شربت الراح بالراح، … وقد كنت لها تارك\nفيا صاح! نهى الصاح … ي، جهل عنك مدارك\nوتسقاها لدنياك، … وتلك المومس الفارك\nترجى، عندها، وصلا؛ … رويدا! إنها عارك\nتخون الأول العهد، … فخل العرس، أو شارك\nمتى يلحقني، بالرك … ب، هذا الجمل الآرك؟\nألا قد ذهب الناس، … ونضوي رازم بارك"},{"id":"diwan-maarri:1001","bookId":"diwan-maarri","type":"poem","seq":1001,"chapter":"قصائد","title":"تجنب حانة الصهبا","page":"","text":"تجنب حانة الصهبا … ء، واهجر أبدا حانك\nولا ترسل على الثل … ة، في الغفلة، سرحانك\nولا ترفع، لغير الله، … في الحندس ألحانك\nويا دهر! لحاك الله … ما هنأت فرحانك\nوما أخليت من سقم، … يفض الجسم قرحانك\nفقل: روحك مولانا، … لراجيك، وريحانك\nفقد أجريت جيحان … ك في الأرض، وسيحانك\nوقد أرسلت شيبان … ك، بالرزق، وملحانك"},{"id":"diwan-maarri:1002","bookId":"diwan-maarri","type":"poem","seq":1002,"chapter":"قصائد","title":"يا آكل التفاح لا تبعدن،","page":"","text":"يا آكل التفاح لا تبعدن، … ولا يقم يوم ردى ثاكلك\nقال النصيري، وما قلته، … فاسمع وشجع، في الوغى، ناكلك\nقد كنت، في دهرك، تفاحة، … وكان تفاحك ذا آكلك\nوحرف هاج لحت، فيما مضى، … وطالما تشكله شاكلك"},{"id":"diwan-maarri:1003","bookId":"diwan-maarri","type":"poem","seq":1003,"chapter":"قصائد","title":"يا خالق البدر وشمس الضحى،","page":"","text":"يا خالق البدر وشمس الضحى، … معولي في كل حال عليك\nوكل ملك لك عبد، وما … يبقى له ملك، فيدعى مليك\nإن ابن يعقوب، سليكا، غدا … كابن عمير، في المنايا، سليك\nومثل ورقاء زهير مضت … ورقاء، تعلو زهرا بين أيك\nقد رامت النفس لها موئلا، … فقلت مهلا! ليس هذا إليك\nإن الذي صاغك يقضي بما … شاء، ويمضي، فازجري عاذليك\nالبحر، في قدرته، نغبة؛ … والفلك الأعظم، فيها، فليك"},{"id":"diwan-maarri:1004","bookId":"diwan-maarri","type":"poem","seq":1004,"chapter":"قصائد","title":"حديث، على العالمين، التبك،","page":"","text":"حديث، على العالمين، التبك، … فبك على الناس، أو لا تبك\nوهم ينتزون، ولا يحجزون؛ … كأنهم الطير تحت الشبك\nوما يخلد الملك الآدمي … لا ما أذاب، ولا ما سبك\nوهل يمنع، الفارس المستمي … ت، ما خاط زراده، أو حبك؟\nوإن إلهي، إله السما … ء، ورب الوهود، ورب النبك\nسألت المحدث عن شأنه، … فما زال يضعف حتى ارتبك\nوعلوي أقداره جامع … هزبر العرين، وعلج الأبك\nلقد بعل المرء عمرو، بها، … فصد، عن الكاس في بعلبك"},{"id":"diwan-maarri:1005","bookId":"diwan-maarri","type":"poem","seq":1005,"chapter":"قصائد","title":"إله الأنام ورب الغمام،","page":"","text":"إله الأنام ورب الغمام، … لنا الفقر دونك، والملك لك\nإذا أنا لم أغن في لذة، … أسفت، وضاق علي الفلك\nولست كموسى أهاب الحمام، … ولكن أود لقاء الملك\nحياة العباد سبيل النفاد، … وما ابيض فودي حتى حلك\nإذا ما تباشر أهل الغلام … به، فالتباشر معنى: هلك\nألم تريا أن سلك الزما … ن أفنى السليك، وأفنى السلك؟"},{"id":"diwan-maarri:1006","bookId":"diwan-maarri","type":"poem","seq":1006,"chapter":"قصائد","title":"إذا المرء صور للناظرين،","page":"","text":"إذا المرء صور للناظرين، … فقد سار في شر نهج سلك\nأرى العلج، في قفره، معتقا، … ولاقى الهوان جواد ملك\nوما حظه في حزام يشد، … ليركب، أو في لجام ألك\nوكم أولد الملك المستباة؛ … وكم نكح العبد بنت الملك"},{"id":"diwan-maarri:1007","bookId":"diwan-maarri","type":"poem","seq":1007,"chapter":"قصائد","title":"ألكني إلى من له حكمة؛","page":"","text":"ألكني إلى من له حكمة؛ … ألكني إليه، ألكني ألك\nأرى ملكا طانه للحمام، … فكيف يوقى بطين الملك؟\nفما لي أخاف طريق الردى، … وذلك خير طريق سلك\nيريحك من عيشة مرة، … ومال أضيع، ومال ملك"},{"id":"diwan-maarri:1008","bookId":"diwan-maarri","type":"poem","seq":1008,"chapter":"قصائد","title":"جرى الناس مجرى واحدا، في طباعهم،","page":"","text":"جرى الناس مجرى واحدا، في طباعهم، … فلم يرزق التهذيب أنثى ولا فحل\nأرى الأري، تغشاه الخطوب، فينثني … ممرا، فهل شاهدت من مقر يحلو؟\nوبين بني حواء، والخلق كله، … شرور، فما هذي العداوة والذحل؟\nتق الله، حتى في جنى النحل شرته، … فما جمعت إلا لأنفسها النحل\nوإن خفت من رب، فلا ترج عارضا … من المزن، تهوى أن يزول به المحل\nفهل علمت وجناء، والبر يبتغى … عليها، فتزهى أن يشد بها الرحل؟"},{"id":"diwan-maarri:1009","bookId":"diwan-maarri","type":"poem","seq":1009,"chapter":"قصائد","title":"إذا كان ما قال الحكيم، فما خلا","page":"","text":"إذا كان ما قال الحكيم، فما خلا … زماني مني، منذ كان، ولا يخلو\nأفرق طورا، ثم أجمع تارة؛ … ومثلي، في حالاته، السدر والنخل\nوأبخل بالطبع الذي لست غالبا؛ … ومن شر أخلاق الرجال هو البخل\nأراد ابنه المثري ليأخذ إرثه، … ولو عقل الآباء ما وضع السخل"},{"id":"diwan-maarri:1010","bookId":"diwan-maarri","type":"poem","seq":1010,"chapter":"قصائد","title":"إذا شئت أن ترقى جدارك، مرة،","page":"","text":"إذا شئت أن ترقى جدارك، مرة، … لأمر، فآذن جار بيتك من قبل\nولا تفجأنه بالطلوع، فربما … أصاب الفتى، من هتك جارته، خبل\nوما زال يفتن امرؤ، في اختياله، … وفي مشيه، حتى مشى وله كبل\nوإن سبيل الخير، للمرء، واضح، … إلى يوم يقضي، ثم تنقطع السبل\nويسمع أقوال الرجال تعيبه، … وأهون منها في مواقعها النبل\nيحل ديار المنديات، برغمه، … ويرحل عنها والفؤاد به تبل\nإذا مسك العيش انقضت وتقضبت، … فما يسأل الضرغام ما فعل الشبل\nعلقت بحبل العمر خمسين حجة، … فقد رث، حتى كاد ينصرم الحبل\nوهل ينفع الطل، الذي هو نازل، … بذات رمال، عندما جحد الوبل؟"},{"id":"diwan-maarri:1011","bookId":"diwan-maarri","type":"poem","seq":1011,"chapter":"قصائد","title":"وردت إلى دار المصائب، مجبرا،","page":"","text":"وردت إلى دار المصائب، مجبرا، … وأصبحت فيها ليس يعجبني النقل\nأعاني شرورا لا قوام بمثلها، … وأدناس طبع لا يهذبه الصقل\nسحائب للسقيا، وسحب من الردى، … ونبت أناس، مثل ما نبت البقل\nوللحي رزق ما أتاه بسعيه، … وعقل، ولكن ليس ينفعه العقل"},{"id":"diwan-maarri:1012","bookId":"diwan-maarri","type":"poem","seq":1012,"chapter":"قصائد","title":"أميتة شهب الدجى أم محسة،","page":"","text":"أميتة شهب الدجى أم محسة، … ولا عقل أم في آلها الحس والعقل؟\nودان أناس بالجزاء وكونه؛ … وقال رجال: إنما أنتم بقل\nفأوصيكم أما قبيحا فجانبوا؛ … وأما جميلا من فعال فلا تقلوا\nفإني وجدت النفس تبدي ندامة … على ما جنته، حين يحضرها النقل\nوإن صدئت أرواحنا، في جسومنا، … فيوشك يوما أن يعاودها الصقل"},{"id":"diwan-maarri:1013","bookId":"diwan-maarri","type":"poem","seq":1013,"chapter":"قصائد","title":"يقولون: إن الجسم ينقل روحه","page":"","text":"يقولون: إن الجسم ينقل روحه … إلى غيره، حتى يهذبها النقل\nفلا تقبلن ما يخبرونك ضلة، … إذا لم يؤيد، ما أتوك به، العقل\nوليس جسوم كالنخيل، وإن سما … بها الفرع، إلا مثل ما نبت البقل\nفعش وادعا وارفق بنفسك طالبا، … فإن حسام الهند ينهكه الصقل"},{"id":"diwan-maarri:1014","bookId":"diwan-maarri","type":"poem","seq":1014,"chapter":"قصائد","title":"يصون الحجى والبذل أعراض معشر؛","page":"","text":"يصون الحجى والبذل أعراض معشر؛ … وأين يرى العرض الذي ليس يبذل؟\nوصاحب نكر، بات يعذر بيننا، … وفاعل معروف يلام ويعذل\nوقدما وجدنا مبطل القوم يعتدي، … فينصر، والغادي مع الحق يخذل\nفإن يك رذلا عصرنا وأنامه، … فما بعد هذا العصر شر وأرذل"},{"id":"diwan-maarri:1015","bookId":"diwan-maarri","type":"poem","seq":1015,"chapter":"قصائد","title":"أيسجنني رب العلا، وهو منصف،","page":"","text":"أيسجنني رب العلا، وهو منصف، … وإن تقن راح، فهي لا ريب تبزل\nفيا عجبا للشمس تنشر بالضحى، … وتطوى الدجى، والبدر ينمو ويهزل\nومعتزلي لم أوافقه، ساعة، … أقول له: في اللفظ دينك أجزل\nأريد به من جزلة الظهر، لم أرد … من الجزل في الأقوال تلوى وتجزل\nجهلت: أقاضي الري أكثر مأثما، … بما نصه، أم شاعر يتغزل\nوأعلم أن ابن المعلم هازل … بأصحابه، والباقلاني أهزل\nوكم من فقيه خابط في ضلالة، … وحجته فيها الكتاب المنزل\nوقارئكم يرجو بتطريبه الغنى، … فآض كما غنى، ليكسب، زلزل\nيرى الخلد عينا، والزبابة مسمعا، … ويقزل في التنميس، والذئب أقزل\nفما لعذاب فوقكم لا يعمكم؛ … وما بال أرض تحتكم لا تزلزل؟\nفعفوا وصلوا واصمتوا عن تناظر، … فكل أمير، بالحوادث، يعزل\nوما رد عن آل السماك سلاحه، … ولا كف عنه الموت، إن قيل أعزل\nأسيفك سيف أم حسامك مشرط؛ … ورمحك رمح أم قناتك مغزل؟"},{"id":"diwan-maarri:1016","bookId":"diwan-maarri","type":"poem","seq":1016,"chapter":"قصائد","title":"بني آدم! من نال مجدا فإنه","page":"","text":"بني آدم! من نال مجدا فإنه … سينقله، من ذلك المجد، ناقل\nومثلان زيد الخيل، فيكم، وغيره؛ … وسيان قس، في الكلام، وباقل\nلكل أخي نفس حجى وفطانة، … وتعرف أفعال الحسام الصياقل\nولو لم يكن مستنفر العصم عاقلا، … لما بات في أعلى الذرى، وهو عاقل"},{"id":"diwan-maarri:1017","bookId":"diwan-maarri","type":"poem","seq":1017,"chapter":"قصائد","title":"إذا ما الردينيات جارت سمت لها","page":"","text":"إذا ما الردينيات جارت سمت لها … مرادن، فيها كرسف ومغازل\nدعت ربها أن يهلك البيض والقنا، … وكل له، من قدرة الله، آزل\nرياء بني حواء، في الطبع، ثابت، … فمنهم مجد، في النفاق، وهازل\nسخوا، ليقول الناس جادوا، وأقدموا، … ليذكر، في الهيجاء، قرن منازل\nوغزلان فرتاج انتحتك خيانة، … وآساد خفان التي لا تغازل\nفيا عجبا للشمس ليس لها سنا، … وللبدر لم تحمل سراه المنازل\nفهل فرحت، بالحمد، خيل سوابق، … وبالمدح، تلك المثقلات البوازل؟"},{"id":"diwan-maarri:1018","bookId":"diwan-maarri","type":"poem","seq":1018,"chapter":"قصائد","title":"عجبت لملبوس الحرير، وإنما","page":"","text":"عجبت لملبوس الحرير، وإنما … بدت، كبنيات النقيع، غوازله\nوللشهد يجني أريه مترنم، … كذبان غيث، لم تضيع جوازله\nكأني بهذا البدر قد زال نوره؛ … وقد درست آثاره ومنازله\nأكان، بحكم من إلهك، ناشئا، … يعاطي الثريا سره، فتغازله؟\nيسير بتقدير المليك لغاية، … فلا هو آتيها ولا السير هازله\nألا هل رأت هذي الفراقد رمينا … فراقد في وحش، رعى الوحش آزله؟\nفإن كان حساسا، من الشهب كوكب، … فما ريع من قبر تبوأ نازله\nمتى يتولى الأرض نجم، فإنه … يدوم زمانا، ثم ربك عازله\nهما فتيا دهر يمران بالفتى، … فلو عد هضب، غيرته زلازله\nكحلفي مغار، كل يوم وليلة، … على الآل، أو في المال ترغو بوازله"},{"id":"diwan-maarri:1019","bookId":"diwan-maarri","type":"poem","seq":1019,"chapter":"قصائد","title":"ناديت، حتى بدا في المنطق الصحل،","page":"","text":"ناديت، حتى بدا في المنطق الصحل، … تخالف الناس والأغراض والنحل\nرجوا إماما، بحق، أن يقوم لهم؛ … هيهات لا بل حلول ثم مرتحل\nولن يزالوا بشر في زمانهم، … ما دام فوقهم المريخ، أو زحل\nفاكفف بسيرك ذيل الخطب، مبتدرا، … فالخلق أمره، أو فيه الدجى كحل"},{"id":"diwan-maarri:1020","bookId":"diwan-maarri","type":"poem","seq":1020,"chapter":"قصائد","title":"نقضي المآرب، والساعات ساعية،","page":"","text":"نقضي المآرب، والساعات ساعية، … كأنهن صعاب، تحتنا، ذلل\nوقت يمر، وأقدار مسببة، … منها الصغير، ومنها الفادح الجلل\nوالله يقدر أن يفني بريته، … من غير سقم، ولكن جنده العلل\nوفي الليالي مضاء موجب، أبدا، … كلول طرفك عما حازت الكلل\nسقيا الغمائم بعض الإنس تفسده، … كالطرس يهلك إما مسه البلل\nوددت أني مثل السيف، ليس له … حس، إذا فل، أو رثت له خلل\nظلت غرائز منا باعثات أسى، … إذا الضنى حل، أو لم يؤهل الطلل\nفي الناس من فقره عز لجارته، … وجاره وغناه كله ذلل\nضل امرؤ قال: خلي أستعين به؛ … وأي خل نأى، عن وده، خلل\nوما فتئت، وأيامي تجدد لي، … حتى مللت، ولم يظهر بها ملل\nإن الأكف، إذا كانت على سرق … مجبولة، فجدير ما بها الشلل\nوالحائمون كثير ثم بعدهم … قوم نهال، وقوم كظهم علل"},{"id":"diwan-maarri:1021","bookId":"diwan-maarri","type":"poem","seq":1021,"chapter":"قصائد","title":"الشعر كالناس، تلقى الأرض جائشة","page":"","text":"الشعر كالناس، تلقى الأرض جائشة … بالجمع يزجى، وخير منهم رجل\nوالأمر يدرك عن قدر، فكم خطئت … نبل المكيث، وصاب الأخرق العجل\nوأمن دنياك من جهل تولده؛ … وصاحب العقل فيها خائف وجل\nوالدهر شاعر آفات يفوه بها … للناس، يفكر، تارات، ويرتجل"},{"id":"diwan-maarri:1022","bookId":"diwan-maarri","type":"poem","seq":1022,"chapter":"قصائد","title":"الشر طبع، ودنيا المرء قائدة","page":"","text":"الشر طبع، ودنيا المرء قائدة … إلى دناياه، والأهواء أهوال\nوالمال يحويه جدوى من يجود به، … إن المكارم، للمجدين، أموال\nوالقول إن يبق يحسب للفتى أثرا، … فلا تشيننك، بعد الموت، أقوال\nحال وحول على أن يذهبا خلقا، … فما تدوم، على الأحوال، أحوال\nوالمجد كالرزق: هذا نال منه غنى، … وذاك منه، على ما فات، إعوال\nلا يجمع الفضل بل يعطى العلا رجب … للحرب يجبى، ويعطى الفطر شوال"},{"id":"diwan-maarri:1023","bookId":"diwan-maarri","type":"poem","seq":1023,"chapter":"قصائد","title":"في الوحدة الراحة العظمى، فآخ بها","page":"","text":"في الوحدة الراحة العظمى، فآخ بها … قلبا، وفي الكون بين الناس أثقال\nإن الطبائع لما ألفت جلبت … شرا، تولد فيه القيل والقال\nحتى إذا مالك الأشياء فرقها، … زال العناء، ولم يتعبك تنقال\nونابت الوجه زين في الندي له، … كالأرض حسنها في العين إبقال"},{"id":"diwan-maarri:1024","bookId":"diwan-maarri","type":"poem","seq":1024,"chapter":"قصائد","title":"دنياك مثل سراب، إن ظننت بها","page":"","text":"دنياك مثل سراب، إن ظننت بها … ماء، فخدع، وإن عضبا فتهويل\nوالجسم للروح دار طالما لقيت … هدما، وحق، لرب الدار، تحويل\nتسول النفس آمالا وتسألها، … فالخير سؤل، وحسن الظن تسويل\nمولت، والمال مثل الفيء منتقل، … فليغد منك، على عافيك، تمويل\nأخذت ميثاق أيام غررت بها، … وما، على ذلك الميثاق، تعويل\nفي قبضة الله أعمار مقسمة، … لها إذا شاء، تقصير وتطويل"},{"id":"diwan-maarri:1025","bookId":"diwan-maarri","type":"poem","seq":1025,"chapter":"قصائد","title":"دين وكفر، وأنباء تقص، وفر","page":"","text":"دين وكفر، وأنباء تقص، وفر … قان ينص، وتوراة، وإنجيل\nفي كل جيل أباطيل يدان بها، … فهل تفرد يوما بالهدى جيل؟\nومن أتاه سجل السعد، عن قدر … عال، فليس له بالخلد تسجيل\nوما تزال، لأهل الفضل، منقصة، … وللأصاغر تعظيم وتبجيل\nهل سرت الخيل أن زانت سوابقها، … بين المواكب، غرات وتحجيل؟\nأم التفاخر فينا ليس يعرفه … إلا الأنيس، وبعض القول تهجيل\nفلتلبس الوحش نعمى، لا حذاء لها … يقي التراب، ولا للهام ترجيل\nما مبغضي، لعمري، محضري أجلي … بالكيد، إن كان لي، في الغيب، تأجيل\nلا الحرب أفنت ولا سلم العدو حمت، … بل، للمقادير، تأخير وتعجيل\nومدحك المرء بالأخلاق يعدمها، … للحر ذي اللب تبكيت وتخجيل\nفاصرف لعافيك سجل العرف تملأه، … ولو أتاك، من الخضراء، سجيل"},{"id":"diwan-maarri:1026","bookId":"diwan-maarri","type":"poem","seq":1026,"chapter":"قصائد","title":"لأوصين بما أوصت به أمم،","page":"","text":"لأوصين بما أوصت به أمم، … في الدهر، والقول مثل الشرب معلول\nلا تأمنن أخا داء ولا ضمن، … قد يحدث السيف كلما، وهو مفلول\nولا يغرنك، ممن قلبه أحن، … صمت، فإن حسام الغمر مسلول\nوإن دللت على شر لتأتيه، … فأنت منه، على ما ساء، مدلول\nمفعول خيرك، في الأفعال، مفتقد، … كما تعذر، في الأسماء، فعلول\nولا يصدنك، عن مجد ولا شرف … تبغيه، أنك طلق الوجه بهلول\nولا تجلن ما الأحلام تحظره، … فقد علمت بأن الرمس محلول\nوقد يطل دماء، غير هينة، … دم من الذارع الزنجي مطلول\nذاك الأسير، كفانا غله عنتا، … فليته، آخر الأيام، مغلول"},{"id":"diwan-maarri:1027","bookId":"diwan-maarri","type":"poem","seq":1027,"chapter":"قصائد","title":"قلتم: لنا خالق حكيم،","page":"","text":"قلتم: لنا خالق حكيم، … قلنا: صدقتم كذا نقول\nزعمتموه بلا مكان … ولا زمان، ألا فقولوا:\nهذا كلام له خبيء، … معناه ليست لنا عقول"},{"id":"diwan-maarri:1028","bookId":"diwan-maarri","type":"poem","seq":1028,"chapter":"قصائد","title":"ما أطيب العيش عند قوم،","page":"","text":"ما أطيب العيش عند قوم، … لو أنه كان لا يزول\nوالدهر عود، بلا فناء، … أو جذع ما له بزول\nما أمنت هذه الثريا … أن يترامى بها النزول\nعنوان القصيدة : تعالى الله فهو بنا خبير، … تعالى الله فهو بنا خبير،\nقد اضطرت إلى الكذب العقول … نقول على المجاز، وقد علمنا"},{"id":"diwan-maarri:1029","bookId":"diwan-maarri","type":"poem","seq":1029,"chapter":"قصائد","title":"سمعتك مخبرا، فنظرت فيما","page":"","text":"سمعتك مخبرا، فنظرت فيما … تقول، فكان أمرا يستحيل\nمتى أسألك، في يومي، دليلا، … أجدك به، على غده، تحيل\nنعم لاح الهلال، فصار بدرا، … وعاد لنقصه، فهو النحيل\nكذاك الدهر: إقبال ونحس، … وإبرام يعاقبه سحيل\nوركب وارد ليقيم عصرا؛ … وآخر قد أجد به الرحيل\nفلا تنكر، إذا دنت الأقاصي، … ولا تعجب، إذا مره الكحيل"},{"id":"diwan-maarri:1030","bookId":"diwan-maarri","type":"poem","seq":1030,"chapter":"قصائد","title":"نزلت عن الكميت إلى كميت؛","page":"","text":"نزلت عن الكميت إلى كميت؛ … ألا بئس الخليفة والبديل\nظلمت بها حجاك، بغير ذنب، … فخف إن العقول لها سديل"},{"id":"diwan-maarri:1031","bookId":"diwan-maarri","type":"poem","seq":1031,"chapter":"قصائد","title":"تولى سيبويه، وجاش سيب","page":"","text":"تولى سيبويه، وجاش سيب … من الأيام، فاختل الخليل\nويونس أوحشت منه المغاني، … وغير مصابه النبأ الجليل\nأتت علل المنون، فما بكاهم، … من اللفظ، الصحيح ولا العليل\nولو أن الكلام يحس شيئا … لكان له، وراءهم، أليل\nودلتهم، إلى حفر، أياد، … لنا بورودها وضح الدليل"},{"id":"diwan-maarri:1032","bookId":"diwan-maarri","type":"poem","seq":1032,"chapter":"قصائد","title":"إله قادر، وعبيد سوء،","page":"","text":"إله قادر، وعبيد سوء، … وجبر في المذاهب واعتزال\nوبالكذب انسرى وضح وليل، … ولم تزل الخطوب ولا تزال\nولولا حاجة، في الذئب، تدعو، … لصيد الوحش، ما اقتنص الغزال\nوما لذؤالة المسكين صبر، … فيصرفه عن الحمل الهزال\nويسعى، في المعاش، الخلق حتى … من الشبثان نسج واغتزال\nولو أمنت شمالك، وهي أخت، … يمينك، ظن خون واختزال"},{"id":"diwan-maarri:1033","bookId":"diwan-maarri","type":"poem","seq":1033,"chapter":"قصائد","title":"إن كان من فعل الكبائر مجبرا،","page":"","text":"إن كان من فعل الكبائر مجبرا، … فعقابه ظلم على ما يفعل\nوالله، إذ خلق المعادن، عالم … أن الحداد البيض منها تجعل\nسفك الدماء بها رجال أعصموا … بالخيل تلجم بالحديد، وتنعل\nلا تمس في نار الضمير فراشة، … فضغائن الصدر الحريق المشعل"},{"id":"diwan-maarri:1034","bookId":"diwan-maarri","type":"poem","seq":1034,"chapter":"قصائد","title":"أجمل فعالك، إن وليت، ولا تجر","page":"","text":"أجمل فعالك، إن وليت، ولا تجر … سبل الهدى، فلكل وال عازل\nللعالم العلوي، فيما خبروا، … شيم بها قدر الكواكب نازل\nأترى الهلال، وليس فيه مظنة، … يصبو إلى جوزائه ويغازل\nويناله نصب يطيل عناءه، … فله، كساري المدلجين، منازل\nويقيم في الدار المنيفة ليلة، … وإذا ترحل لم يعقه الآزل\nوالبدر أنضته الغياهب والسرى، … فليرض إن ينض الفنيق البازل\nعل السماك، إذا استقل برمحه، … بطل يمارس قرنه وينازل\nأيقنت، من قبل النهى، أن السهى … ساه، يضاحك جاره ويهازل\nوالشمس غازلة تمد خيوطها، … فلذاك نسوان الأنام غوازل\nأما النجوم، فإنهن ركائب … تحت الزمان، فهل لهن هوازل؟\nيا حبذا العيش الأنيق، ولم ترم … هدم السرور، من الخطوب، زلازل\nأيام سنبلة البروج غضيضة، … والليث شبل، والنسور جوازل\nوهممت أن تحظى، ولكن طالما … خزلتك، عن نيل المراد، خوازل"},{"id":"diwan-maarri:1035","bookId":"diwan-maarri","type":"poem","seq":1035,"chapter":"قصائد","title":"أنسل أو اعقم، فالتوحد راحة؛","page":"","text":"أنسل أو اعقم، فالتوحد راحة؛ … سيان نجلك، والخبيت الناسل\nوالشر أغلب، عصبة جمعت لنا … أقذاء دنيانا، وفذ غاسل\nعسلت قنا، وخوامع، وثعالب … أعقت جنا، وأطاب نحل عاسل\nوالنفع لم يكمل به، لكن له … ضير، وكم أردى الغريق سلاسل\nأنت الجبان، إذا المنية أعرضت، … وعلى ثنيتك الشجاع الباسل\nنهج العلا ينضي الركاب، وكلنا … كسلان، دون المجد، أو متكاسل\nوالنفس في جسم تعلل بالمنى، … ومنى يلاحظ يومها ويراسل\nلم يمنع ابن الملك، من آفاته، … عوذ تناط بكشحه، ومراسل\nسقيا لطيب العصر، لو أن الفتى، … بالمرغبات إلى بقاء، واسل\nفالروض مجنون، وما حمل الثرى … غلا، ولكن للوميض سلاسل\nأجأ أجيء، إلى الحتوف، قطينه، … فمضى وواسل بالمنون مواسل"},{"id":"diwan-maarri:1036","bookId":"diwan-maarri","type":"poem","seq":1036,"chapter":"قصائد","title":"يتحارب الطبع الذي مزجت به","page":"","text":"يتحارب الطبع الذي مزجت به … مهج الأنام، وعقلهم، فيفله\nويظل ينظر، ما سناه بنافع، … كالشمس يسترها الغمام وظله\nحتى إذا حضر الحمام، تبينوا … أن الذي فعلوه جهل كله\nوالعقل في معنى العقال ولفظه … فالخير يعقل، والسفاه يحله\nوتغرب الشرير يوجب حتفه، … مثل الوجار، إذا تسحب صله\nولزومه الأوطان أبقى للردى، … كالسيد يستر، في الضراء، أزله\nوالنفس آلفة الحياة، فدمعها … يجري، لذكر فراقها، منهله\nما خلة بأغر منها، والفتى … يبكي، إذا ركب الصريمة خله\nلا تحجز الأقدار، وهي كثيرة، … كالغيث وابله يصوب وطله\nومن الجنود، على الكمي، جواده، … وحسامه، وسنانه، ومتله\nميز، إذا انكل الغمام، وميضه، … فالبرق يخبر أين يسقط كله\nولقد علمت، فما أسفت لفائت، … أن البقية من مداي أقله\nوالبر يلتمس الحلال، ولم أجد … هذا الورى، إلا فقيدا حله\nيمسي، وقد مل البقاء، ويغتدي، … وله رجاء فيه ليس يمله\nفاحفظ أخاك، وإن تبين أنه … بالي الوداد، ضعيفه مختله\nفالغمد يذعر، في اللقاء، كهامه؛ … والسيف لم يبد الخبيئة سله\nوالبرد يكفيك العيون دريسه … والعضو ينفع، في الخطوب، أشله\nوالعمر لا يدري الحكيم: أكثره … خير له متغبرا، أم قله\nلا تهزأن بالشيخ، كم من ليلة … جازت به كالبدر، يحسن دله\nأيام يهتك، في البطالة، ستره، … كالطرف مزق، في التمرح، جله\nشر الزمان زمان أشيب دالف، … وصباه أنفس وقته وأجله\nما لي! أيفهم سامعي نصيحتي، … فأبيت أنهل مصغيا، وأعله؟\nيجري بفارسه الطمر مؤجلا، … وإذا انقضى أجل، فليس يقله\nوالفقر بكر ترتقيه شذاته؛ … واليسر عود ما تسور عله\nأجتاب شهرا أولا؛ فأبيده، … ويجيء ثان، بعده، فأهله\nيمسي، على حد المهند، أخمصي، … فترى اليسير من، من الأمور، يزله\nوالناس جائر مسلك مسترشد، … وأخ، على غير الطريق، يدله"},{"id":"diwan-maarri:1037","bookId":"diwan-maarri","type":"poem","seq":1037,"chapter":"قصائد","title":"نفس الفتى وليت له جسدا؛","page":"","text":"نفس الفتى وليت له جسدا؛ … إن الولاية بعدها عزل\nلا تخزل الأوقات مهجته، … قد تفضح السرقات والخزل\nمقر يداف ليستصح به، … ودم يراق ليذهب الأزل\nكالدن ضاق بما تضمنه، … حتى يكون لراحه بزل\nوسنا يضيء، وبعده غسق، … فانظر أجد ذاك أم هزل\nواللب يحمل، من هواجسه، … ما ليس ناهضة به البزل\nقض الزمان بعفة وتقى … فلكل مطعم آكل نزل\nولتغد هونات المناكب أمثا … ل العناكب، شأنها الغزل\nلا خير في جزل العطاء، أتى … رجلا بأن كلامه جزل\nيرجو، فيمدح غير مرتقب … ربا، وكل مقاله إزل\nخير لعمري، من جمائله ال … كوم الجلاد، جمائل جزل\nشهرت، سيوف القول، طائفة … كذب، وأفضل منهم العزل"},{"id":"diwan-maarri:1038","bookId":"diwan-maarri","type":"poem","seq":1038,"chapter":"قصائد","title":"كم تنصح الدنيا ولا نقبل،","page":"","text":"كم تنصح الدنيا ولا نقبل، … وفائز من جده مقبل\nإن أذاها مثل أفعالنا، … ماض، وفي الحال، ومستقبل\nأجبلت الأبحر في عصرنا … هذا، كما أبحرت الأجبل\nفاترك لأهل الملك لذاتهم، … فحسبنا الكمأة والأحبل\nونشرب الماء براحاتنا، … إن لم يكن، ما بيننا، جنبل\nتسوق الناس بفرقانهم، … وانتبلوا جهلا، فلم ينبلوا\nوليس ما ينقل عن عاصم … كما روى عن شيخه قنبل\nلا تأمن الأغفار، في النيق، أن … تصبح موصولا بها الأحبل\nيغنيك قطر بل منك الصدى، … في العيش، أن تزداد قطربل\nوالفذ يكفيك، إذا فاتك الر … قيب، والنافس، والمسبل\nلو نطق الدهر هجا أهله، … كأنه الرومي، أو دعبل\nوهو، لعمري، شاعر مغرز … بالفعل، لكن لفظه مجبل\nإن كف، ما بينهم، حازم، … فلبه المطلق لا يكبل\nوفاعلاتن ومفاعيلها … تكف، في الوزن، ولا تخبل\nلا تغبط الأقوام، يوما، على … ما أكلوا خضما، وما سربلوا\nيذبل غصن العيش حقا، ولو … أضحى، ومن أوراقه، يذبل\nفليت حواء عقيم غدت، … لا تلد الناس ولا تحبل\nوليت شيثا، وأبانا الذي … جاء بنا، أهبله المهبل\nوليتنا تترك أجسادنا، … كما يزول السمر المحبل\nتفكروا بالله، واستيقظوا، … فإنها داهية ضئبل\nفي سنبل يخلق من حبة، … ثمت منها يخلق السنبل\nأراد من يجهل تقويمنا، … ونحن أخياف كما نحبل\nيكره، عول الشيخ، أبناؤه؛ … وهل تعول الأسد الأشبل؟\nننزل من دار لنا رحبة، … تطل بالآفات، أو توبل\nوكل من حل بها يكره ال … رحلة عنها، وهي تستوبل\nإن أديما لي أنا وقته، … فأين مني الشجر المعبل؟"},{"id":"diwan-maarri:1039","bookId":"diwan-maarri","type":"poem","seq":1039,"chapter":"قصائد","title":"كل، على مكروهه، مبسل،","page":"","text":"كل، على مكروهه، مبسل، … وحازم الأقوام لا ينسل\nفسل أبو عالمنا آدم، … ونحن من والدنا أفسل\nلو تعلم النحل بمشتارها، … لم ترها في جبل تعسل\nوالخير محبوب، ولكنه … يعجز عنه الحي، أو يكسل\nوالأرض للطوفان مشتاقة، … لعلها من درن تغسل\nقد كثر الشر على ظهرها، … واتهم المرسل والمرسل\nوأمقرت أفعال سكانها، … فهم ذئاب في الفضا عسل\nومن يكن يوم الوغى باسلا، … فالموت، في حملته، أبسل\nوجرعة الذيفان مشروبة، … وغيرها المستعذب السلسل\nفأت جميلا، لم يقع بأسنا … بأنه، يوما، به يوسل"},{"id":"diwan-maarri:1040","bookId":"diwan-maarri","type":"poem","seq":1040,"chapter":"قصائد","title":"من يعرف الدنيا يهن، عنده،","page":"","text":"من يعرف الدنيا يهن، عنده، … إمراعها، الدهر، وإمحالها\nلذاتها تعجب أملاكها، … لو لم تغير بهم حالها\nدار، حللناها، على رغمنا، … وإنما ينظر ترحالها\nوالخود، كالنخلة، مجنية، … وزوجها البائس فحالها"},{"id":"diwan-maarri:1041","bookId":"diwan-maarri","type":"poem","seq":1041,"chapter":"قصائد","title":"إن عجوزا حبست برهة،","page":"","text":"إن عجوزا حبست برهة، … ثم غدا من حكمها القتل\nخاتل إبليس بها رهطه، … فتم في القوم بها الختل\nكم قارىء هش إلى نارها، … فأطفأت نور الذي يتلو"},{"id":"diwan-maarri:1042","bookId":"diwan-maarri","type":"poem","seq":1042,"chapter":"قصائد","title":"هذا زمان، ليس في أهله،","page":"","text":"هذا زمان، ليس في أهله، … إلا لأن تهجره، أهل\nجميعنا يخبط في حندس، … قد استوى الناشىء والكهل\nحان رحيل النفس عن عالم، … ما هو إلا الغدر والجهل\nقد فني الوقت فما حيلتي، … إذا انقضى الإمهال والمهل؟\nإن ختم الله بغفرانه، … فكل ما لاقيته سهل"},{"id":"diwan-maarri:1043","bookId":"diwan-maarri","type":"poem","seq":1043,"chapter":"قصائد","title":"بالقضاء البليغ كنا، فعشنا،","page":"","text":"بالقضاء البليغ كنا، فعشنا، … ثم زلنا، وكل خلق يزول\nنحن، في هذه البسيطة، أضيا … ف، لنا في ذرا المليك نزول\nوالمليكان ذاهبان مولى، … مستجد، وراحل معزول\nبلي الحبل، والغزالة فوق الأ … رض، لم يبل خيطها المغزول\nوأنا العود، قلبه أضمر الشو … ق، ولكن ظهره مجزول\nومن الرشد، للفصيل انفصال … بالردى، قبل أن يحين بزول\nبات ينعى الأبدان بدر بدين … وهلال، في أفقه، مهزول\nكم أبادا من عالم، وأعادا … سابحا، وهو في الثرى مأزول\nسلب الدن مبزلا حلف راح، … بفتاة نجيعه مبزول\nطللاه دار وجسم، فشخ … ص المرء خاو، وربعه منزول"},{"id":"diwan-maarri:1044","bookId":"diwan-maarri","type":"poem","seq":1044,"chapter":"قصائد","title":"وفر هذا الفتى مديد، بسيط،","page":"","text":"وفر هذا الفتى مديد، بسيط، … وافر، كامل، خفيف، طويل\nستة فيه من نعوت القوافي، … ما لها، غير شحه، تأويل\nسولت لي نفسي أمورا، وهي … هات، لقد خاب ذلك التسويل\nواتهامي بالمال، كلف أن يطل … ب مني ما يقتضي التمويل\nويقول الغواة: خولك الله؛ … كذبتم، لغيري التخويل\nعيشة ضاهت الهواذير مافي … ها مفيد، وكلها تطويل\nإن حباك القدير كالنيل تبرا، … فليغضه العطاء والتنويل\nلا تعول على اختزان، فما لل … بدر الصفر، إثر ميت، عويل\nوإذا هولت علي المنايا، … راقني، من وعيدها، التهويل\nحوليني عن ظاهر الأرض، فالقل … ب يسلي، همومه، التحويل\nليس فعل الدنيا بفعل عروس، … بل هي الغول، شأنها التغويل\nلو ملكت الرحيل جولت في ال … آفاق، حتى يملني التجويل"},{"id":"diwan-maarri:1045","bookId":"diwan-maarri","type":"poem","seq":1045,"chapter":"قصائد","title":"إتق الواحد المهي","page":"","text":"إتق الواحد المهي … من، فالله أول\nإن قوما، لما يكو … ن حراما، تأولوا\nرغبوا الناس في المحا … ل، وراعوا وهولوا\nورأى الله أنه … كذب ما تقولوا\nضربوا، في البلاد، عص … را، فطافوا وجولوا\nخولوا نعمة، فلم … يشكروا ما تخولوا\nواستطالت على الورى … عصب ما تطولوا\nطلبوا الناقد القلي … ل، فمانوا وسولوا\nنظروا في نجومهم، … وعلى النجم عولوا\nظلموا البائس الفقي … ر، وأعطوا ونولوا\nواستمالوا قلوب قو … م إلى أن تمولوا\nفانظروا الآن فيهم، … أي غول تغولوا\nلو أقاموا القليل فا … زوا، ولكن تحولوا"},{"id":"diwan-maarri:1046","bookId":"diwan-maarri","type":"poem","seq":1046,"chapter":"قصائد","title":"غدا كل طفل، على عمره،","page":"","text":"غدا كل طفل، على عمره، … طفيلا، يخب به قرزل\nيود ثباتا على ظهره، … وتدعو الخطوب: ألا تنزل!\nرعى الله قوما مضى دهرهم، … وما فيهم أحد يهزل\nتضاهي العناكب نسوانهم، … فتنسج للنفع، أو تغزل\nوما عزفت مزهرا في الحيا … ة، ولا الدن يفتح، أو يبزل\nجهلن الغناء، وصوتا يقا … ل: غناه دحمان أو زلزل\nونفس الفتى وليت جسمه، … إذا جاء ميقاتها تعزل\nوإن السماكين لا يخلدان، … ويهلك ذو الرمح والأعزل\nأعيرت غيرك داء عراه، … وخالقك الواهب المجزل\nوقد عاش ما شاء هذا الغراب، … فما قالت الطير: يا أقزل"},{"id":"diwan-maarri:1047","bookId":"diwan-maarri","type":"poem","seq":1047,"chapter":"قصائد","title":"أدنياك تخطبها أيما،","page":"","text":"أدنياك تخطبها أيما، … ويعضلها دونك العاضل\nقد انتضل الناس في أمرها، … فهل يوجد الرجل الناضل\nوخلك أفضل من غيره، … وما في الورى كلهم فاضل"},{"id":"diwan-maarri:1048","bookId":"diwan-maarri","type":"poem","seq":1048,"chapter":"قصائد","title":"تخالفنا الدنيا على السخط والرضى،","page":"","text":"تخالفنا الدنيا على السخط والرضى، … فإن أوشك الإنسان قالت له: مهلا!\nهي الماء، لو أني، بعلمي، وردته، … لقلت لنفسي: كان مورده جهلا\nفما رئمت طفلا، ولا أكرمت فتى، … ولا رحمت شيخا، ولا وقرت كهلا\nقطعنا إلى السهل الحزونة، نبتغي … يسارا، فلم نلف اليسير، ولا السهلا\nفلا تأمل الأيام للخير مرة، … فليست لخير، أن يظن بها، أهلا"},{"id":"diwan-maarri:1049","bookId":"diwan-maarri","type":"poem","seq":1049,"chapter":"قصائد","title":"دع الراح، في راح الغواة، مدارة،","page":"","text":"دع الراح، في راح الغواة، مدارة، … يظنون فيها حنوة وقرنفلا\nكأن شذاها العسجدي، بطبعه، … تضوع هنديا، وأودع فلفلا\nتريع لها أجناد إبليس، رغبة، … وتنفر، جراها، الملائك جفلا\nيضن بها لما تطعم شربها، … فليس بساخ أن يمج، ويتفلا\nغفلت، ومن غزوي قفلت بخيبة … ولم يعدني ريب الحوادث مغفلا\nولم أقض فرضا في منى وبلادها؛ … وكم عاجز قد زارها متنفلا\nووسعت دنياكم على من سعى لها، … فما أنا آت، للمعاشر، محفلا\nسوى أن خطا في البسيطة، ضيقا، … يكون على شخصي، يد الدهر، مقفلا\nوأصمت صمتا لا تكلم بعده، … ولا قول داع: يا فلان ويا فلا\nفما درهمي إن مر بي متلبثا، … ولا طفل لي حتى ترى الشمس مطفلا\nويرزقني الله، الذي قام حكمه، … بأرزاقنا في أرضه، متكفلا"},{"id":"diwan-maarri:1050","bookId":"diwan-maarri","type":"poem","seq":1050,"chapter":"قصائد","title":"من عير الخبل إنسانا، فقد خبلا؛","page":"","text":"من عير الخبل إنسانا، فقد خبلا؛ … هل تحمل الأم إلا الثكل والهبلا؟\nيعوم، في اللج، ركب، يمتطي سفنا، … ويجنب الخيل سار، يركب الإبلا\nوإنما هو حظ لا تجاوزه، … والسعد غيم، إذا طل الفتى، وبلا\nتبغي الثراء، فتعطاه وتحرمه؛ … وكل قلب على حب الغنى جبلا\nلو أن عشقك، للدنيا، له شبح … أبديته، لملأت السهل والجبلا\nأتقبل النصح مني أم تضيعه؛ … ورب مثلك ألغاه، فما قبلا\nمن اهتدى بسوى المعقول أورده، … من بات يهديه، ماء طالما تبلا\nحبالة لا يرجى الظبي مخلصه … منها، وأنى، إذا ليث الشرى حبلا؟\nلا تربلن، وكن رئبال مأسدة؛ … إن الرشاد ينافي البادن الربلا\nخير لعمري، وأهدى من إمامهم، … عكاز أعمى هدته، إذ غدا، السبلا\nقد أعبلت شجرات غير عاذبة، … وسوف يبكر جان يطلب العبلا\nتكهل بعده سن يشاكله؛ … ما أيبس الغصن إلا بعدما ذبلا\nإن المسن، وقد لاقى أذى وشذى، … يود لو رد غض العيش مقتبلا\nيوصي كبير أعاديه أصاغرهم … بقصده، فليعد النبل والنبلا\nتعلل الناس حتى بالمنى، وسما … ذو الغور يهدي، إلى النجدية، القبلا\nأرى الطريقين: من ميت ومن ولد، … لا يخلوان، كلا نهجيهما سبلا\nفلا تبن لمجرى السيل أخبية، … فالحزم ينزلك الأخياف والقبلا\nبلى لجسم وبلوى حلف مصطحب، … إن قلت: لا، عند أمر عن، قال: بلى"},{"id":"diwan-maarri:1051","bookId":"diwan-maarri","type":"poem","seq":1051,"chapter":"قصائد","title":"سقيا لشوهاء ما همت بفاحشة،","page":"","text":"سقيا لشوهاء ما همت بفاحشة، … غدت على الغزل، ليست تعرف الغزلا\nوتجهل العود، إلا عود مغزلها، … ولا تراح، إذا ما عاتق بزلا\nكل البرية شاك، لو سما زحل … إلى السماك رآه يشتكي العزلا\nإن الغراب، ولم يوجد أخو قدم … أصح منه، تعاني رجله قزلا\nفجنب الزهو في الدنيا، فلو زهيت … غر الغمام لذم القطر، إذ نزلا\nلو تاه بيت قريض، وهو منتسب … في كامل الشعر، وافى الوقص أو خزلا\nفاعجب لعود الغواني لم يخف هرما، … ولا يراه زمان، في السرى، هزلا\nفي هيئة البكر، ما حالت سجيته، … فقيل: أسدس، في حول، وما بزلا\nتلاوم الناس، وافتنت ظنونهم، … وأرجأ الناشىء الباغي، أو اعتزلا\nوقيل لا بعث يرجى للثواب، وما … سمعت، في ذاك، دعوى مبطل هزلا\nوكيف للجسم أن يدعى إلى رغد، … من بعد ما رم، في الغبراء، أو أزلا؟\nوهل يقوم لحمل العبء، من جدث، … ظهر، وأيسر ما لاقاه أن جزلا؟\nما أحسب الكوكب المريخ أو زحلا، … إلا أميرين، إن طال المدى عزلا"},{"id":"diwan-maarri:1052","bookId":"diwan-maarri","type":"poem","seq":1052,"chapter":"قصائد","title":"الرمح أبلغ من قس تخاطبه","page":"","text":"الرمح أبلغ من قس تخاطبه … خرساء، يوجد فيها المسمع الخطلا\nوقدرة الله نجت راجلا ورعا، … يوم الهياج، وأردت فارسا بطلا\nإن ماطلتك الليالي بالذي وعدت، … فالجود يشعر تنغيصا، إذا مطلا\nوالخير يعدي، كغادي مزنة هطلت … أرضا، فلما رآها رائح هطلا\nيذكي التقارب مابين الورى حسدا، … حتى إذا ما تناءى شكلهم بطلا\nوهي المقادير لا يغبط، بحليته، … جيد الحمامة، جيد غيره عطلا"},{"id":"diwan-maarri:1053","bookId":"diwan-maarri","type":"poem","seq":1053,"chapter":"قصائد","title":"ما لي رأيت صنوف الباطل اشتبهت،","page":"","text":"ما لي رأيت صنوف الباطل اشتبهت، … فلم تزل بقران المشتري زحلا؟\nعبدان، لله، سياران، ما سئما … طول المسير، إذا مل الفتى الرحلا\nوما استفزهما الإمهال، فادعيا، … بالجهل، ما قاله المغرور، وانتحلا\nإن ينظرا أعينا رمدا، فما رمدا، … ولا بغير سواد الحندس اكتحلا"},{"id":"diwan-maarri:1054","bookId":"diwan-maarri","type":"poem","seq":1054,"chapter":"قصائد","title":"يتلون أسفارهم، والحق يخبرني","page":"","text":"يتلون أسفارهم، والحق يخبرني … بأن آخرها مين، وأولها\nصدقت يا عقل، فليبعد أخو سفه، … صاغ الأحاديث إفكا، أو تأولها\nوليس حبر ببدع في صحابته، … إن سام نفعا بأخبار تقولها\nوإنما رام نسوانا، تزوجها، … بما افتراه، وأموالا تمولها\nطال العناء بكون الشخص في أمم، … تعد فرية غاويها معولها\nوسوف يرقد، في الغبراء، مضطرب، … قد سار آفاق دنياه، وجولها\nلأهجرنك لا عن بغضة سلفت، … بل شيمة حمها قدر وسولها\nوصاحب الشرع كان القدس قبلته، … صلى إليها زمانا ثم حولها\nلا يخدعنك داع قام، في ملإ، … بخطبة، زان معناها وطولها\nفما العظات، وإن راعت، سوى حيل … من ذي مقال، على ناس، تحولها\nوالدهر ينسي كمي الحرب صارمه، … ودرعه، وفتاة الحي مجولها\nويسترد من النفس، التي شرفت، … ما كان في سالف الأيام خولها\nوجرول صار تربا، بعد منطقه، … ولم يشابه، من الصحراء، جرولها\nقض الزمان بإجمال وتمشية … للأمر، إن وراء الروح مغولها\nوالورد، يكفيك، منه شربة حملت … في الركب، إن منعتك الأرض جدولها"},{"id":"diwan-maarri:1055","bookId":"diwan-maarri","type":"poem","seq":1055,"chapter":"قصائد","title":"دع آدما، لا شفاه الله من هبل،","page":"","text":"دع آدما، لا شفاه الله من هبل، … يبكي على نجله المقتول هابيلا\nففي عقاب الذي أبداه، من خطإ، … ظلنا نمارس من سقم عقابيلا\nونحن من حدثان نمتري عجبا؛ … ومعشر يقفون الغي تسبيلا\nهم الغرابيب من إثم، وإن أمنوا … على سرارك لم تعدم غرابيلا\nدهر يكر، ويوم ما يمر بنا … إلا يزيد به المعقول تخبيلا\nمن أنكر النكر سودان شرامحة، … تكون أبناؤها بيضا تنابيلا\nتنسك الأسد الضرغام، وابتكرت … جآذر العين آسادا رآبيلا\nإن القيان وشرب الراح مفسدة، … من قبل لمك وقينان وقابيلا\nأما سرابيل دنياكم فضافية، … وما كسيتم من التقوى سرابيلا\nفقابل الترب سمطي لؤلؤ بفم، … يروم للمومس الغيداء تقبيلا\nوما وجدت منايا القوم مغفلة … شبلا بغاب، ولا غفرا بإشبيلا\nأرى التطول، في الأقوام، طال بكم … إلى النجوم، وإن كنتم حنابيلا"},{"id":"diwan-maarri:1056","bookId":"diwan-maarri","type":"poem","seq":1056,"chapter":"قصائد","title":"بهاء ليل، وإن جنت حنادسه،","page":"","text":"بهاء ليل، وإن جنت حنادسه، … فدع نهارك، ود من بهاليلا\nوما شمالي لخل بل أجنبه … إلى الجنوب، وإن سقت الشماليلا\nإذا طما لي، أو لم يطم، بحر غنى، … فقد وجدت بني الدنيا طماليلا\nهل تجعلون على أيد أساورها، … أو تعقدون على هام أكاليلا\nمهلا تعالى لتحظى من تجاربنا؛ … إن الحياة علمناها تعاليلا"},{"id":"diwan-maarri:1057","bookId":"diwan-maarri","type":"poem","seq":1057,"chapter":"قصائد","title":"أما البليغ، فإني لا أجادله،","page":"","text":"أما البليغ، فإني لا أجادله، … ولا العيي بغى للحق إبطالا\nفنحن في ليل غي، ليس منكشفا، … لم يفتقد عارضا، بالجهل، هطالا\nوالنفس كالسبب المدود تجمعه، … فيستكف، وإن أرسلته طالا\nكذات شنف، أرادت بعده خدما … ونظم در وكانت قبل معطالا\nوقد شربت نميرا، فاجتزأت به، … فلم حملت، من الصهباء، أرطالا؟\nلا خيل مثل قوافي الشعر جائلة، … أبقى على الدهر أعناقا وآطالا\nإن ينقل الحتف، عن عاداته، بطلا، … فما تزال معانيهن أبطالا"},{"id":"diwan-maarri:1058","bookId":"diwan-maarri","type":"poem","seq":1058,"chapter":"قصائد","title":"جسم الفتى مثل قام، فعل،","page":"","text":"جسم الفتى مثل قام، فعل، … مذ كان ما فارق اعتلالا\nوالخل، في لفظه، دليل … بأن، في وده، اختلالا\nمللت من حندس وصبح، … ولم أبن فيهما ملالا"},{"id":"diwan-maarri:1059","bookId":"diwan-maarri","type":"poem","seq":1059,"chapter":"قصائد","title":"أزل هموم الفؤاد واصبر،","page":"","text":"أزل هموم الفؤاد واصبر، … فإنما قصرك الإزاله\nوليس فيمن تراه خير، … فعده، واطلب اعتزاله\nوالغزل والردن للغواني، … شيئان عدا من الجزاله\nوالشمس غزالة، ولكن … خففت الزاي في الغزاله"},{"id":"diwan-maarri:1060","bookId":"diwan-maarri","type":"poem","seq":1060,"chapter":"قصائد","title":"أيسمع خالقي مني دعاء،","page":"","text":"أيسمع خالقي مني دعاء، … فأصبح، في كياني، مستقيلا\nكأن العالمين صلوا هجيرا، … فما يلفي به أحد مقيلا\nلقد جربت حتى لم أصدق … حديثا، عن قريب مدى نقيلا\nإذا صلوا فصل، وعف وابذل … زكاتك، واجتنب قالا وقيلا\nولا ترهف مدى لعبيط نحض، … ولا تشهر على قرن صقيلا\nإذا جالستهم، فأقل شيء … تجر بذاك أن تدعى ثقيلا"},{"id":"diwan-maarri:1061","bookId":"diwan-maarri","type":"poem","seq":1061,"chapter":"قصائد","title":"ليذمم والدا ولد، ويعتب","page":"","text":"ليذمم والدا ولد، ويعتب … عليه، فبئس عمري ماسعى له\nأتدري، والحياة لها صروف، … بما يلقاه جروك يا ثعاله؟\nفمن ضار يمزق منه شلوا، … ويعطي فضل أكرعه جعاله\nومن صقر يقول له: رويدا؛ … ومن شرك يصيح به: تعاله\nوما في الأرض من أحد غني، … ولكن كلنا فقراء عاله\nأرى نار الصبا لبست خمودا، … وأذكى الشيب في الرأس اشتعاله"},{"id":"diwan-maarri:1062","bookId":"diwan-maarri","type":"poem","seq":1062,"chapter":"قصائد","title":"متى ما شئت موعظة، فعرج","page":"","text":"متى ما شئت موعظة، فعرج … بيثرب سائلا عن آل قيله\nوقف بالحيرة البيضاء، فانظر … منازل منذر، وبني بقيله"},{"id":"diwan-maarri:1063","bookId":"diwan-maarri","type":"poem","seq":1063,"chapter":"قصائد","title":"يسود الناس زيد، بعد عمرو،","page":"","text":"يسود الناس زيد، بعد عمرو، … كذاك تقلب الدولات دوله\nورب شهادة وردت بزور، … أقام لنصها القاضي عدوله\nومن شر البرية رب ملك، … يريد رعية أن يسجدوا له"},{"id":"diwan-maarri:1064","bookId":"diwan-maarri","type":"poem","seq":1064,"chapter":"قصائد","title":"إن هللت أفواهكم، فقلوبكم","page":"","text":"إن هللت أفواهكم، فقلوبكم … ونفوسكم، دون الحقوق، مهلله\nآليت، ما توراتكم بمنيرة، … إن ألفيت فيها الكميت محلله\nلا تأمنوا برق الغمام، فإنما … تلك السيوف، من القضاء، مسلله\nقال افتكار، في الحوادث، صادق … جعل الصعاب من الحذار مذلله\nهفت الحنيفة، والنصارى ما اهتدت، … ويهود حارت، والمجوس مضلله\nاثنان أهل الأرض، ذو عقل بلا … دين، وآخر دين لا عقل له"},{"id":"diwan-maarri:1065","bookId":"diwan-maarri","type":"poem","seq":1065,"chapter":"قصائد","title":"الدهر، لا تبقى عليه نعامة،","page":"","text":"الدهر، لا تبقى عليه نعامة، … سهلا تحل، وتتقي أجرالها\nوورى لها برق، فهاج زفيفها، … أدحيها تبعي بذاك رالها\nتلفي بها ريب الزمان موكلا، … إن لم يزرها بالنهار سرى لها"},{"id":"diwan-maarri:1066","bookId":"diwan-maarri","type":"poem","seq":1066,"chapter":"قصائد","title":"تدري الحمامة، حين تهتف بالضحى،","page":"","text":"تدري الحمامة، حين تهتف بالضحى، … أن الأجادل لا تطيل جدالها\nوهدى لها قدر، أتيح بسدفة، … صقرا، ففجع بالهديل هدالها\nومهى الصوان، أدالها متختل، … ورأى المليك عدوها، فأدالها\nوخدى، لأرض، بالفقير نجيه، … فأصاب ثروتها، وحاز خدالها"},{"id":"diwan-maarri:1067","bookId":"diwan-maarri","type":"poem","seq":1067,"chapter":"قصائد","title":"طلب الخسائس، وارتقى في منبر،","page":"","text":"طلب الخسائس، وارتقى في منبر، … يصف الحساب لأمة ليهولها\nويكون غير مصدق بقيامة، … أمسى يمثل، في النفوس، ذهولها\nووجدت ليل الغي، ألبس مردها … وشيوخها وشبابها وكهولها\nلو قام أموات العواصم، وحدها، … ملأوا البلاد حزونها وسهولها\nفخذ الذي قال اللبيب، وعش به، … ودع الغواة كذوبها وجهولها"},{"id":"diwan-maarri:1068","bookId":"diwan-maarri","type":"poem","seq":1068,"chapter":"قصائد","title":"افهم عن الأيام، فهي نواطق،","page":"","text":"افهم عن الأيام، فهي نواطق، … ما زال يضرب صرفها الأمثالا\nلم يمض، في دنياك، أمر معجب، … إلا أرتك لما مضى تمثالا"},{"id":"diwan-maarri:1069","bookId":"diwan-maarri","type":"poem","seq":1069,"chapter":"قصائد","title":"حديث جاء عن هابي","page":"","text":"حديث جاء عن هابي … ل، في الدهر، وقابيلا\nوطير عكفت، يوما، … على الجيش، أبابيلا\nمتى تزحل عن دنيا، … تزيد الأهل تخبيلا؟\nسواهم نخل النصح، … ولاقوك غرابيلا\nلبسنا من مدى الأيا … م، للغي، سرابيلا\nوقضيت زمان الشر … خ تقيدا، وتكبيلا\nوزار الطيف، في النوم، … فلم تسأله تقبيلا\nففرق مالك الجم، … وخل الأرض تسبيلا\nولا تستزر بالقوم، … إذا كانوا تنابيلا\nفما كنت من الرهط … يعدون مقابيلا\nولا يبقى، على الساعا … ت، أغفار بإشبيلا"},{"id":"diwan-maarri:1070","bookId":"diwan-maarri","type":"poem","seq":1070,"chapter":"قصائد","title":"أيا شيعة إسماعي","page":"","text":"أيا شيعة إسماعي … ل! إن الصبر قد عيلا\nكذاك الدهر، والأيا … م يفعلن الأفاعيلا\nأرى الأمصار لا تمل … ك، للحافر، تنعيلا\nوقد غير، معناها، … أذى يأتي أراعيلا\nكما جزىء بيت الشع … ر، تقطيعا وتفعيلا"},{"id":"diwan-maarri:1071","bookId":"diwan-maarri","type":"poem","seq":1071,"chapter":"قصائد","title":"كيف لي، يا عيش، لو","page":"","text":"كيف لي، يا عيش، لو … أصبح مولاك مقيلا؟\nقد حملنا، من رزايا … دهرنا، عبئا ثقيلا\nومللنا منه مغدى، … ومبيتا، ومقيلا\nوأطلنا، في بني أي … امنا، قالا وقيلا\nصدىء العقل به، من … بعد ما كان صقيلا"},{"id":"diwan-maarri:1072","bookId":"diwan-maarri","type":"poem","seq":1072,"chapter":"قصائد","title":"أصبحت منحوسا، كأني ابن مس","page":"","text":"أصبحت منحوسا، كأني ابن مس … عود، وما أطغى بأن أهزلا\nلي أمل، فرقانه محكم، … أقرؤه غضا، كما أنزلا\nشيخا أراني، كطفيل غدا … يركض، في غارته، قرزلا\nلا يكذب الناس على ربهم، … ما حرك العرش، ولا زلزلا\nفليت من يفري أحاديثه، … مات فصيلا، قبل أن يبزلا\nيا جدثي! حسبك، من رتبة، … أنك من أجداثهم معزلا\nأملني الدهر بأحداثه، … فاشتقت، في بطن الثرى، منزلا\nإن نشأت بنتك في نعمة، … فألزمنها البيت والمغزلا\nذلك خير من شوار لها، … ومن عطايا والد أجزلا"},{"id":"diwan-maarri:1073","bookId":"diwan-maarri","type":"poem","seq":1073,"chapter":"قصائد","title":"قد بدل العالم عاداتهم،","page":"","text":"قد بدل العالم عاداتهم، … بل قدر، من فوقهم، بدلا\nتوقعوا من دهرهم عدله، … والدهر لا يحسن أن يعدلا\nهل يأمن الضائن سيد الغضا، … أو الحمام المغتدي أجدلا؟\nأخاف كون الرند ضالا، ولا … آمن كون الضالة المندلا\nوالشر فينا غالب، طالب، … يلحق بالدوية المجدلا\nفي كل دهر جنف كامن، … والنحس في المولد، والسعد لا\nيا معدن العسجد! أصبحت ما … تخرج إلا الترب والجندلا\nوالعجب داء قاتل أهله، … يمانع الأستار أن تسدلا\nعير على سفواء يزهى؛ من ال … قائم لما ركب الدلدلا؟"},{"id":"diwan-maarri:1074","bookId":"diwan-maarri","type":"poem","seq":1074,"chapter":"قصائد","title":"العدل صعب، وكلما عدل ال","page":"","text":"العدل صعب، وكلما عدل ال … إنسان عن عدله، امترى ثقله\nوالظلم يشقى به الظلوم، وير … عاه، كرعي الظباء مبتقله\nوالمجد كالقلة المنيفة، وال … مرء لقال، من الزمان، قله\nإن يهلك التابع التبيع، فقد … يمقله، في الغنى، إذا مقله\nأو يعتقله، فالرمح أحوج ما … كان إليه الفتى، إذا اعتقله\nوالسيف لا يفرج المضايق، أو … يوقعه، في المضيق، من صقله\nوالحي لا بد راكب سفرا، … وتارك، من ورائه، ثقله\nلا يسلم القادر المخدم، في ال … نيق، ولا أم غفرة الوقله\nتصغي إلى ناقل الحديث، وهل … تصدق، فيما تحدث، النقله؟\nوالمال لا يجذب الجمال إلى ال … إنسان، إلا إذا نضا عقله"},{"id":"diwan-maarri:1075","bookId":"diwan-maarri","type":"poem","seq":1075,"chapter":"قصائد","title":"جسمي أودى مر السنين به،","page":"","text":"جسمي أودى مر السنين به، … فلتطلب النفس منزلا بدله\nما كرهت مأثما، ولا فعلت … خيرا، وعادت مسيئة جدله\nوالناس لا يصلحون ما طلعت … شمس، وما أرسل الدجى سدله\nما عدم الجائرون، عندهم، … تأليا أنهم من العدله\nوالعلوي البصري كان، بهم، … أعرف منهم، واللب يشهد له"},{"id":"diwan-maarri:1076","bookId":"diwan-maarri","type":"poem","seq":1076,"chapter":"قصائد","title":"قد أشرعت سنبس ذوابلها،","page":"","text":"قد أشرعت سنبس ذوابلها، … وأرهفت بحتر معابلها\nلفتنة، لا تزال باعثة … رامحها، في الوغى، ونابلها\nحسان، في الملك، لا يحس لها، … تزجي، إلى موتها، قنابلها\nخل ودنياك، أهل عزتها، … فكم شكت مهجة بلابلها\nوجاوزتني سحائب سكب، … تحرمني طلها ووابلها\nعندي، فاعلم، نصيحة عجب، … وما إخال السفيه قابلها\nأسكت، فإن السكوت منقبة، … تأمن به إنسها وخابلها\nترضى بحكم القضاء في سخط، … وهل تحب الظباء حابلها\nجبلة، بالفساد، واشجة، … إن لامها المرء لام جابلها\nفاجزأ، وإن كنت في ذميم صدى، … فما تذم الوحوش آبلها\nأين لبيد، وأين أسرته، … تزخر، عند الضحى، مسابلها\nيحل أجسامها المدام، إذا … ما فارقت قنصها، وبابلها"},{"id":"diwan-maarri:1077","bookId":"diwan-maarri","type":"poem","seq":1077,"chapter":"قصائد","title":"عش بخيلا، كأهل عصرك هذا،","page":"","text":"عش بخيلا، كأهل عصرك هذا، … وتباله، فإن دهرك أبله\nقوم سوء، فالشبل منهم يغول اللي … ث فرسا، والليث يأكل شبله\nإن ترد أن تخص حرا، من النا … س، بخير، فخص نفسك قبله\nبعد الشرب، قربوا أم ليلى … لتعير اللسان، في اللفظ، خبله\nأوردوك الأذى، لتغرق فيه، … وأروك الخنى، لتعرف سبله\nوجدوا مشمشا ثقيلا، يريدو … ن به: من ينم ينبه بقبله\nوأراني مرمى لصرف الليالي، … يحتذيني، فلست أعدم نبله\nهل ترى ناعبا، كعنترة العب … سي، يبكي على منازل عبله\nأو خفاف يرثي رجال سليم، … أو سحيم يحدو مع الركب إبله\nلا تهبه، ولا سواه من الطي … ر، فما يتقي أخو اللب تبله"},{"id":"diwan-maarri:1078","bookId":"diwan-maarri","type":"poem","seq":1078,"chapter":"قصائد","title":"لا تكوني روادة هزاله،","page":"","text":"لا تكوني روادة هزاله، … واحذري من نوائب جزاله\nإغزلي في الحياة، فالشمس قدما … غزلت خيطها، فقيل غزاله"},{"id":"diwan-maarri:1079","bookId":"diwan-maarri","type":"poem","seq":1079,"chapter":"قصائد","title":"كبرت، فأصبحت، للراشدين،","page":"","text":"كبرت، فأصبحت، للراشدين، … كبرت يعد لهدي دليلا\nكبرت، فما زال هذا الزمان، … كبرت، يجذ قليلا قليلا\nوسيف المنية أمضى السيوف، … وما سمعت منه أذن صليلا"},{"id":"diwan-maarri:1080","bookId":"diwan-maarri","type":"poem","seq":1080,"chapter":"قصائد","title":"إذا عدت، في مرض، مكثرا،","page":"","text":"إذا عدت، في مرض، مكثرا، … فخفف وخف أن تمل العليلا\nوإن كان ذا فاقة مقترا، … فأسعف، وإن كان نيلا قليلا"},{"id":"diwan-maarri:1081","bookId":"diwan-maarri","type":"poem","seq":1081,"chapter":"قصائد","title":"سلاسل برق، تقل البلاد","page":"","text":"سلاسل برق، تقل البلاد … من المحل، جادت بني سلسله\nسقت وطنا، وتخطت سواه، … موقرة، بالحيا، مرسله\nأتغسل جسمي مما به، … وقلبي أحوج أن تغسله؟\nولا أشرب، الدهر، بسل الشراب … ونفسي، بأعمالها، مبسله"},{"id":"diwan-maarri:1082","bookId":"diwan-maarri","type":"poem","seq":1082,"chapter":"قصائد","title":"إذا قيل: إن الفتى ناسك،","page":"","text":"إذا قيل: إن الفتى ناسك، … ورام الجمال، فلا نسك له\nيصلي، وهمته أن يقا … ل: سابق خيل رضا فسكله\nوأفضل منه امرؤ خامل، … يقوت، بمكسبه، حسكله"},{"id":"diwan-maarri:1083","bookId":"diwan-maarri","type":"poem","seq":1083,"chapter":"قصائد","title":"وجدتك في رقدة، فانتبه،","page":"","text":"وجدتك في رقدة، فانتبه، … أحذرك من هذه الخاتله\nأتاها بنوها، على غرة، … وما علموا أنها قاتله"},{"id":"diwan-maarri:1084","bookId":"diwan-maarri","type":"poem","seq":1084,"chapter":"قصائد","title":"إذا ما ابن ستين ضم الكعاب","page":"","text":"إذا ما ابن ستين ضم الكعاب … إليه، فقد حلت البهله\nهو الشيخ، لم يرضه أهله، … ولم يرض، في فعله، أهله\nفلا يتزوج أخو الأربعي … ن، إلا مجربة كهله\nرأى الشيب، في عارضه، المسن، … فنعم القرين له الشهله\nوجدنا الفتى صعبت عيشة … عليه، وإن ظنها سهله\nأرى الشر يأتي سبيل الحياة، … ولم تلف، بينهما، مهله"},{"id":"diwan-maarri:1085","bookId":"diwan-maarri","type":"poem","seq":1085,"chapter":"قصائد","title":"بني الأرض! ما تحت التراب موفق","page":"","text":"بني الأرض! ما تحت التراب موفق … لرشد، ولا فوق التراب سوى فسل\nأكان أبوكم آدم، في الذي أتى، … نجيبا، فترجون النجابة للنسل؟\nأسكن الثرى، لا يبعثون رسالة … إلينا، ولستم سامعي كلم الرسل\nولا تسل نفسي عنكم باختيارها، … ولكن طول الدهر ينهل أو يسلي\nتفرعت الأشياء، والأصل واحد، … ومن حلب الغيث الذي در من رسل\nوما بردت أعضاء ميت مكرم، … وإن عز، حتى أغلي الماء للغسل\nوكم بر، مثل الببر، نجل أبا له، … وكان له كالضب يغدر بالحسل"},{"id":"diwan-maarri:1086","bookId":"diwan-maarri","type":"poem","seq":1086,"chapter":"قصائد","title":"يخونك من أدى إليك أمانة،","page":"","text":"يخونك من أدى إليك أمانة، … فلم ترعه يوما بقول ولا فعل\nفأحسن إلى من شئت في الأرض أو أسىء، … فإنك تجزى حذوك النعل بالنعل\nيرومون بالسعي المراتب والعلا، … وربك يهوي طالب المجد أو يعلي"},{"id":"diwan-maarri:1087","bookId":"diwan-maarri","type":"poem","seq":1087,"chapter":"قصائد","title":"لبكر، لعمري، بكر الدهر بالردى،","page":"","text":"لبكر، لعمري، بكر الدهر بالردى، … وقد عجلت أحداثه لبني عجل\nوتغلب، من أحياء تغلب، سادة، … وقد غلبتهم قبل مختلف الرجل"},{"id":"diwan-maarri:1088","bookId":"diwan-maarri","type":"poem","seq":1088,"chapter":"قصائد","title":"إذا كنت في نخل، جناه ميسر","page":"","text":"إذا كنت في نخل، جناه ميسر … لكفك، فاهتف بالضعيف إلى النخل\nفإن لم يعد، فابعث له سهم طارق … لتؤجر، أو تدعى البريء من البخل\nأبى الله أخذي در ضأن وماعز، … وإدخالي الأمر المضر على السخل"},{"id":"diwan-maarri:1089","bookId":"diwan-maarri","type":"poem","seq":1089,"chapter":"قصائد","title":"لقد صدئت أفهام قوم، فهل لها","page":"","text":"لقد صدئت أفهام قوم، فهل لها … صقال، ويحتاج الحسام إلى الصقل؟\nوكم غرت الدنيا بنيها، وساءني، … مع الناس، مين في الأحاديث والنقل\nسأتبع من يدعو إلى الخير، جاهدا، … وأرحل عنها، ما إمامي سوى عقلي\nإذا جهزتني غائبا غير آيب، … تركت لها ما حملتني من الثقل\nمغيرة الحالات، ناقضة القوى، … موثقة الأغلال، محكمة العقل\nتواصت بها الأرواح، في القيظ، بعدما … تناصت بها الأرماح في زمن البقل\nومن كان، في الأشياء، يحكم بالحجى، … تساوى لديه من يحب ومن يقلي"},{"id":"diwan-maarri:1090","bookId":"diwan-maarri","type":"poem","seq":1090,"chapter":"قصائد","title":"إذا كنت تهدي لي، وأجزيك مثله،","page":"","text":"إذا كنت تهدي لي، وأجزيك مثله، … فإن الهدايا، بيننا، تعب الرسل\nفلا أنا مغبون، ولا أنت، في الذي … بعثنا كلانا، غير ملتمس الرسل\nفدونك شغلا، ليس هذا، لعله … يعود بنفع، لا كشغلك بالنسل\nأبوك جنى شرا عليك، وإنما … هو الضب، إذا يسدي العقوق إلى الحسل\nيقول كلاما فوك يوجد بعده، … كذي نجس يحتاج منه إلى الغسل"},{"id":"diwan-maarri:1091","bookId":"diwan-maarri","type":"poem","seq":1091,"chapter":"قصائد","title":"أخلت عمود الدين في الأرض ثابتا،","page":"","text":"أخلت عمود الدين في الأرض ثابتا، … وفي كل يوم يضمحل على مهل؟\nسهيل، وإن كان اليماني، منكر … لأمر، بضبن الشام، ما هو بالسهل\nبرئت إلى الخلاق من أهل مذهب، … يرون، من الحق، الإباحة للأهل\nفهلا خشيب كي يقنأ، تحته، … مشيب من الشيخ المسن، أو الكهل\nوأين حسام الهند، عنك، وجهله؛ … جهادك أولى من جهاد أبي جهل"},{"id":"diwan-maarri:1092","bookId":"diwan-maarri","type":"poem","seq":1092,"chapter":"قصائد","title":"إذا كنت ذا ثنتين، فاعدل، أو اتحد","page":"","text":"إذا كنت ذا ثنتين، فاعدل، أو اتحد … بنفسك، فالتوحيد أولى من العدل\nشفاه المها تفني يسارا، تفيئه … عليك المهاري من مشافرها الهدل"},{"id":"diwan-maarri:1093","bookId":"diwan-maarri","type":"poem","seq":1093,"chapter":"قصائد","title":"متى نشأت ريح لقدرك، فابعثي،","page":"","text":"متى نشأت ريح لقدرك، فابعثي، … لجارتك الدنيا، قليلا، ولا تملي\nفإن يسير الطعم يقضي مذمة، … ولا سيما للطفل، أو ربة الحمل\nوإن حل، أبدى، فاقة منك، فاضمني … قراه، ولو جمعته من قرى النمل\nوأعلم أن الأول الفرد قادر … على أن يمير المؤمنين من الرمل\nعفا الله عني، رب ريح تهب لي، … فتذري ترابي من جنوب ومن شمل\nوشغل فم، يستغفر الله ذنبه، … أحق به من ذكر زينب أو جمل\nوإهمالك النفس اللجوج، ملاوة، … تقاضت دموعا من جفونك بالهمل"},{"id":"diwan-maarri:1094","bookId":"diwan-maarri","type":"poem","seq":1094,"chapter":"قصائد","title":"علمت بأن الناس لا خير عندهم،","page":"","text":"علمت بأن الناس لا خير عندهم، … فجانبتهم من جائدين وبخال\nإذا قلت: جدي، قلت: هبني دفنته … كجدي، وخالي هامد في ثرى خال\nتحل بتقوى، أو تحل بعفة، … فذلك خير من سوار وخلخال"},{"id":"diwan-maarri:1095","bookId":"diwan-maarri","type":"poem","seq":1095,"chapter":"قصائد","title":"إذا طرق المسكين دارك فاحبه","page":"","text":"إذا طرق المسكين دارك فاحبه … قليلا، ولو مقدار حبة خردل\nولا تحتقر شيئا تساعفه به، … فكم من حصاة أيدت ظهر مجدل\nوما كبد العصفور، وهي ضئيلة، … بعاجزة عن ضبطها نفس أجدل\nلطال علي الوقت، والنفس عمرها … كأقصر ظل، في الزمان الشمردل\nمدى حيوان، في هواء ولجة، … وأرض وترب، مستكن وجندل\nفبين، إذا حاولت إفهام سامع، … فإن بيانا من قضاء معدل\nتقول: حميد قال، والمرء ما درى … حميد بن ثور أم حميد بن بحدل\nإذا ما دعي القوم ضاهى صريحهم، … فلا تنكرن، واعدده آخر عبدل\nأليس، كباقي أحرف الوزن، لامه، … وما فصلت من لام سهل وأهدل"},{"id":"diwan-maarri:1096","bookId":"diwan-maarri","type":"poem","seq":1096,"chapter":"قصائد","title":"منى صل حرب نالها بالمناصل،","page":"","text":"منى صل حرب نالها بالمناصل، … فواصل، وقاطع بالرقاق الفواصل\nسقينك من ماء المفاصل مرويا، … وزايلن، في الهيجاء، بين المفاصل\nمننت على أبنائك النزر، آسفا، … فأنت عليهم كالألد المفاصل\nولم تسع فيهم ليلة سعي متعب، … إلى أن يبين الصبح شيبة ناصل\nألم تر زغبا أدلجت أمهاتها، … فألقت لها ما حصلت في الحواصل؟\nغدت شجرات، في السماء، سوامقا، … عناصرها، في الضعف، مثل العناصل"},{"id":"diwan-maarri:1097","bookId":"diwan-maarri","type":"poem","seq":1097,"chapter":"قصائد","title":"دعاكم، إلى خير الأمور، محمد،","page":"","text":"دعاكم، إلى خير الأمور، محمد، … وليس العوالي، في القنا، كالسوافل\nحداكم على تعظيم من خلق الضحى … وشهب الدجى من طالعات وآفل\nوألزمكم ما ليس يعجز حمله … أخا الضعف من فرض له ونوافل\nوحث على تطهير جسم وملبس، … وعاقب في قذف النساء الفواضل\nوحرم خمرا، خلت ألباب شربها، … من الطيش، ألباب النعام الجوافل\nيجرون ثوب الملك جر أوانس، … لدى البدو، أذيال الغواني الروافل\nفصلى عليه الله، ما ذر شارق، … وما فت، مسكا، ذكره في المحافل"},{"id":"diwan-maarri:1098","bookId":"diwan-maarri","type":"poem","seq":1098,"chapter":"قصائد","title":"اتق الله، واحذر أن يغرك ناسك،","page":"","text":"اتق الله، واحذر أن يغرك ناسك، … بما هو فيه من تغير حاله\nفما أنفس الأقوام إلا توابع، … لقائل زور، مفرط في محاله\nفهذا الذي في صومه وصلاته، … كذاك الذي في حله وارتحاله\nفكذب زعيما قال: إني دين، … فما دينه إلا ضعيف انتحاله\nيماحل في الدنيا الخؤون، وإنما … يؤمل نزرا فانيا بمحاله\nومن يكتحل بالسهد في طلب العلا … يجز أن يرى منهاجها باكتحاله"},{"id":"diwan-maarri:1099","bookId":"diwan-maarri","type":"poem","seq":1099,"chapter":"قصائد","title":"إذا ما عددت السن عدت بترحة،","page":"","text":"إذا ما عددت السن عدت بترحة، … وأملت ربي أن يحل عقالي\nأسر لدنياي، التي قد طويتها، … وآسي لجرمي خاطر ومقال\nفيا أم دفر! كنت لي مي وامق، … فصار تعاد بيننا وتقالي\nجعلت ثقيل الترب فوقي، وطالما … وطئت بأوزار، عليك، ثقال\nوقد صدئت نفسي بجسمي ولبسه، … فهل تصطفيها ميتتي بصقال؟"},{"id":"diwan-maarri:1100","bookId":"diwan-maarri","type":"poem","seq":1100,"chapter":"قصائد","title":"عمى العين يتلوه عمى الدين والهدى","page":"","text":"عمى العين يتلوه عمى الدين والهدى … فليلتي القصوى ثلاث ليالي\nوما أزمت نفسي البنان على التي، … إذا أزمت، عضت بشوك سيال\nولا قصرت لي أم ليلى بشربها … حنادس أوقات، علي طيال\nإذا ما اجتمعنا هاجت الحزن ألفة … محدثة، عن جمعنا، بزيال\nلحا الله غارات السنين، فإنها … مبدلة ظلمانها بريال\nوما سرني رب الخيال بشخصه، … فيطلب مني النوم طيف خيال\nوهون أرزاء الحوادث أنني … وحيد، أعانيها بغير عيال\nفدعني وأهوالا أمارس ضنكها؛ … وإياك عني لا تقف بحيالي"},{"id":"diwan-maarri:1101","bookId":"diwan-maarri","type":"poem","seq":1101,"chapter":"قصائد","title":"بفي الحصى، هل تملأ الخلد التي","page":"","text":"بفي الحصى، هل تملأ الخلد التي … بفيها، لرائي العين، سمط لآلي؟\nإذا ما رأيت الآل مني قائما، … تقاك هجير، في العيان، بآل\nفلا تغبطني أن رزقت نضارة، … من الدهر، وانظر مرجعي ومآلي\nوآلي، أعني الأقرباء، جنوده، … على ما سقاني من أذى ووأى لي"},{"id":"diwan-maarri:1102","bookId":"diwan-maarri","type":"poem","seq":1102,"chapter":"قصائد","title":"أوالي هذا المصر، في زي واحد،","page":"","text":"أوالي هذا المصر، في زي واحد، … أواخر، من أيامنا، وأوال\nإذا ما حبال الناس عادت بواليا، … فإن حبال الشمس غير بوال\nتوالي بعض القوم ليس بنافع، … وتمضي هواد للردى وتوال\nجوالي أحداث الزمان، سفاهة، … وأنفسنا عما يحل جوال\nتظل حوالي قرح وبوازل، … حوالي، قد أعييتها بحوال\nخوى لي نجم في قديم وحادث، … وتذكر أوقات مضين خوال\nدواليك، يا ريب الخطوب، فهذه … ثقال غروب، ما لهن دوال\nإذا ما الإماء الثاكلات رأيتها … سوالي للأحياء، فهي سوال\nوإن طوال الدهر صير أينقي … رذايا، وجربى ما لهن طوال\nعوى لي ذئب، فانتبهت لزجره؛ … رويدك إن النيرات عوال\nمتى ما تبت خوص المطايا مواليا … بنا، في ابتغاء العز، فهي موال\nوما الناس إلا كالقنيص، إزاءه … كوالىء من أخطاره، وكوال\nغوى ليل مثر، فاستقل بفتنة، … وقد رخصت، للسائمين، غوال\nوكيف احتيالي في الصديق، وقد نوى … لي الشر، محتاج أصاب نوالي؟"},{"id":"diwan-maarri:1103","bookId":"diwan-maarri","type":"poem","seq":1103,"chapter":"قصائد","title":"تضيق الليالي عن محلة ماجد،","page":"","text":"تضيق الليالي عن محلة ماجد، … فما ضمنت إلا ذميم فعال\nوأيامنا مثل الأيوم، وإنما … سعى لي، من ساعاتهن، سعال\nفلا تسأل المرء الغني عطاءه، … ورج الغنى من ربك المتعالي\nومهلا بني الورهاء، ما كان فيكم … رشيد، ولا أنتم بأهل معالي\nعسى جد خيل، قربتكم من العلا، … يجود لها من عسجد بنعال\nهبوا واجعلوا للجود فيكم بقية، … سوى جود همام على ابن جعال\nإذا اليوم ولى أعجز القوم رده، … ولو تبعوا آثاره برعال\nيمدون، للطعن، الثعالب في الوغى … وآسادهم عند اللقاء ثعال\nوإن أخا نسك، دعا لك بالذي … ملكت، بضد، من غناك، دعا لي"},{"id":"diwan-maarri:1104","bookId":"diwan-maarri","type":"poem","seq":1104,"chapter":"قصائد","title":"إذا صقلت دنياك مرآة عقلها،","page":"","text":"إذا صقلت دنياك مرآة عقلها، … أرتك جزيل الأمر غير جزيل\nفبعدا، لحاك الله، ياشر منزل، … ثواه، من الإنسان، شر نزيل\nوقد زال عنه ساكن، بعد ساكن؛ … فهل هو ماض مرة بمزيل؟\nعجبت لثوب، من ظلام، ممزق، … وخيط صباح، من ذكاء، غزيل\nوما تترك الأيام، وهي كثيرة، … ولاية وال وانصراف عزيل\nيضللن، حتى الركب، يبعث بزله … لأزهر، من صفو المدام، بزيل\nوما يفرق الترب، الذي هو آكل … لنا، بين جسمي بادن وهزيل"},{"id":"diwan-maarri:1105","bookId":"diwan-maarri","type":"poem","seq":1105,"chapter":"قصائد","title":"بك على الناس بالمزموم والرمل،","page":"","text":"بك على الناس بالمزموم والرمل، … فإن أعمال دنياهم كلا عمل\nوالحكم، من عالم عال، تنزله؛ … فما لسكان هذي الأرض كالهمل؟\nعاشوا بها، واستجاشوا، ثم ما حصلوا … إلا على الموت، في التفصيل والجمل\nلا أحمل الهم، لي يوم يغيبني، … ولو حللت مع الجوزاء والحمل\nويب الحوادث! كم أخرجن من ملك … عن الديار؛ وكم قصرن من أمل\nيسعى الفتى لابتغاء الرزق، مجتهدا، … بالسيف والرمح فوق الطرف والجمل\nولو أقام لوافاه الذي سمحت … به المقادير، من نقص ومن كمل\nجمعا لمحبوب قربى، أو بغيض عدا، … كأنه عن ذراه غير محتمل\nإذا ملكت، فأسجح، غير مهتضم؛ … وإن حكمت على قوم، فلا تمل"},{"id":"diwan-maarri:1106","bookId":"diwan-maarri","type":"poem","seq":1106,"chapter":"قصائد","title":"جالس عدوك تعرف من تكاتمه،","page":"","text":"جالس عدوك تعرف من تكاتمه، … يبدو القلى في حديث القوم والمقل\nوالشر، في حيوان الأرض، مفترق، … والإنس، كالوحش من ضار ومبتقل\nيجري القضاء، فيهدي العيس، كارهة، … إلى الضراغم في الأقياد والعقل\nفخالف الناس ترشد، كلما نطقوا … فاصمت حميدا، وإن هم أنصتوا، فقل\nواطلب رضاك من الخلين: ذي شطب … ومطلق الحد، في الأبطال، معتقل\nأما ترى الشهب، في أفلاكها، انتقلت … بقدرة من مليك غير منتقل؟"},{"id":"diwan-maarri:1107","bookId":"diwan-maarri","type":"poem","seq":1107,"chapter":"قصائد","title":"ما أوصل السيف، قطاعا، لحامله؛","page":"","text":"ما أوصل السيف، قطاعا، لحامله؛ … وأبلغ الذابل الموصوف بالخطل\nقد وافياك بتاج الملك، عن عرض؛ … وأثرياك بحلي الكاعب العطل\nوأحرزاك بمقدار إلى أمد؛ … وأنجزا لك وعد الكذب المطل\nوالسيف، إن قال أبدى نبأة عجبا، … في وزن حرفين لم يكثر ولم يطل\nسلمان، تفهم عنه فارسيته، … فدع سليمان، والمعنى: ردى البطل"},{"id":"diwan-maarri:1108","bookId":"diwan-maarri","type":"poem","seq":1108,"chapter":"قصائد","title":"أعجل بتسبيح رب لا كفاء له،","page":"","text":"أعجل بتسبيح رب لا كفاء له، … أو رتلنه، ولا تجنح إلى رتل\nولا تكن عاديا كالذئب، شيمته … ختل، فلا خير مصروف إلى الختل\nما أنت؟ والطعنة النجلاء يحفزها، … مثل القليب، أصم الذادة القتل\nغارت، وفارت، وألقى من يمارسها، … فيها، العمائم أبدالا من الفتل"},{"id":"diwan-maarri:1109","bookId":"diwan-maarri","type":"poem","seq":1109,"chapter":"قصائد","title":"يا خاطري! لا توجه وجه سيئة،","page":"","text":"يا خاطري! لا توجه وجه سيئة، … فأفكر، الآن، أقصى الفكر وارتجل\nويا بناني! لا تبسط لعارفة؛ … ويا لساني، بغير الصدق، لا تجل\nأوجال نفسي، في الأولى، مضاعفة، … ولا أزال، من الأخرى، على وجل\nوالشر في الخلق طبع لا يزايله، … فقس على خزر، في العين، أو نجل\nلو وفق المرء لم يبهش إلى امرأة؛ … أو الغريرة لم تزفف إلى رجل\nأو عمر الشيخ عمر النسر من شهب، … لا من ذوات جناح، لم يقل: بجل\nقد يسأم الحي، والأسرار ما خلصت … في حبها الموت، من سبط ومن رجل\nأولى البرية أن يحظى بعاقبة، … من لم يرح، من قبيح، بادي الخجل\nوالصمت أحجى، وأحرار الكلام لها … فضل، وفيه نظير النسوة الهجل\nإن اللطيفين: من دهر وأمكنة، … لا يفتآن بلا حس ولا زجل\nإن كان نقلي، عن الدنيا، يكون إلى … خير وأرحب، فانقلني على عجل\nوإن علمت مآلي، عند آخرتي، … شرا وأضيق، فانسأ، رب، في الأجل"},{"id":"diwan-maarri:1110","bookId":"diwan-maarri","type":"poem","seq":1110,"chapter":"قصائد","title":"قد طال، في العيش، تقييدي وإرسالي،","page":"","text":"قد طال، في العيش، تقييدي وإرسالي، … من اتقى الله، فهو السالم السالي\nيا صاحب الضأن! سلم حق معدمها … ولا تقل: ضل إنساني بإبسالي\nوارقب إلهك في عسر وفي يسر؛ … واترك جدالك في بعث وإرسال\nكم غال طاهيك من عفراء مرضعة، … وذات لونين صارت قوت مكسال\nوقد ضننت بشاة، وهي فاردة، … على أزل فقيد القوت، عسال\nبخلت أن يتغذى طفله دمها، … وأنت شارب لذ الطعم، سلسال\nواسأل به الحي، من عدنان أو سبإ، … تجده ليس، إذا أقوى، بوسال"},{"id":"diwan-maarri:1111","bookId":"diwan-maarri","type":"poem","seq":1111,"chapter":"قصائد","title":"نعشى عن الأمر، حتى يعلو ابن ردى","page":"","text":"نعشى عن الأمر، حتى يعلو ابن ردى … نعشا، تبارك رب العالم العالي!\nلا يدرك الخلد أوعال مخلدة، … فاسأل بصحة هذا أم أوعال\nظننت أني وحدي مخطىء، فإذا … أفعال كل بني الدنيا كأفعالي\nما بال مكة فيها مع معشر سدن، … من يطرق البيت يؤثرهم بأجعال\nفلا تكلف جوادا سير نائية، … فيها الحزونة، إلا بعد إنعال"},{"id":"diwan-maarri:1112","bookId":"diwan-maarri","type":"poem","seq":1112,"chapter":"قصائد","title":"يكسى الوليد جديد العمر يلبسه،","page":"","text":"يكسى الوليد جديد العمر يلبسه، … وكل يوم يرث الملبس الغالي\nيظل في المهد، لا يسطيع جلسته؛ … وسيره، للمنايا، رهن إبغال\nيضيق صدر الفتى ما لم يواف له، … شغلا، فيحتال للدنيا بأشغال"},{"id":"diwan-maarri:1113","bookId":"diwan-maarri","type":"poem","seq":1113,"chapter":"قصائد","title":"صاح الزمان، فعاد الجمع مفترقا،","page":"","text":"صاح الزمان، فعاد الجمع مفترقا، … كالضأن لما أحست صوت رئبال\nإن الفوارس ما انفكت عقائلها … مطلولة، بين آساد وأشبال\nتسربل الوشي راج أن يجمله، … والحمد في كل عصر خير سربال\nوكيف يعدل موصول بمنقطع، … يبلى النسيج، وهذا ليس بالبالي\nالناس يسعون في أشياء معجزة، … وسعيهم ليس من نجح على بال\nهل ميز يوما هواء في لطافته … بمنخل، أو صفا ماء بغربال؟\nوالنبل يبلغ ما أعيا القنا، مثلا … أجريه للنبل يلفى عند تنبال\nقد أحبلت سمرات الجزع سامعة … أمر القضاء، وما همت بإحبال\nما زلت آمل حظا أن يساعدني، … حتى أتيح لحفري طول إجبال\nإذا أناف على الخمسين بالغها، … فليضمر اليأس من سعد وإقبال\nوالعمر إصعاد إنسان ومهبطه، … كالأرض أودية منها وأجيال"},{"id":"diwan-maarri:1114","bookId":"diwan-maarri","type":"poem","seq":1114,"chapter":"قصائد","title":"لم يسقكم ربكم عن حسن فعلكم؛","page":"","text":"لم يسقكم ربكم عن حسن فعلكم؛ … ولا حماكم غماما سوء أعمال\nوإنما هي أقدار مرتبة، … ما علقت بإساءات وإجمال\nدليل ذلك أن الحر أعوزه … قوت، وأن سواه فاز بالمال\nكم جد بالرزق ثاو في منازله، … وحد سار بأفراس وأجمال\nفأملوا الله وأرجوا منه عاقبة، … فليس دنياكم أهلا لآمال\nدنتم بأن سيجازيكم إلهكم، … فما لأفعالكم أفعال إهمال؟"},{"id":"diwan-maarri:1115","bookId":"diwan-maarri","type":"poem","seq":1115,"chapter":"قصائد","title":"يا نفس! جسمك سربال له خطر،","page":"","text":"يا نفس! جسمك سربال له خطر، … وما يبدل في حال بسربال\nقد أخلقته الليالي، فاتركيه لقى، … فما يزينك لبس المخلق البالي\nفإن خرجت إلى بؤسى فوا حرجي؛ … وإن نقلت إلى نعمى فطوبى لي"},{"id":"diwan-maarri:1116","bookId":"diwan-maarri","type":"poem","seq":1116,"chapter":"قصائد","title":"مضى الزمان، ونفس الحي مولعة","page":"","text":"مضى الزمان، ونفس الحي مولعة … بالشر، من قبل هابيل وقابيل\nلو غربل الناس، كيما يعدموا سقطا، … لما تحصل شيء في الغرابيل\nأو قيل للنار: خصي من جنى، أكلت … أجسادهم، وأبت أكل السرابيل\nهل ينظرون سوى الطوفان يهلكهم، … كما يقال، أو الطير الأبابيل؟\nفلا أجدك رديئا في ذوي أمم، … وكن نبيلا مع القوم التنابيل\nسبحان من ألهم الأجناس كلهم … أمرا، يقود إلى خبل وتخبيل\nلحظ العيون، وأهواء النفوس، وإه … واء الشفاه إلى لثم وتقبيل"},{"id":"diwan-maarri:1117","bookId":"diwan-maarri","type":"poem","seq":1117,"chapter":"قصائد","title":"يا أذن سوف يظل السمع مفتقدا،","page":"","text":"يا أذن سوف يظل السمع مفتقدا، … وتستريحين من قال ومن قيل\nويصبح الجسم، بعد الروح، منتبذا … صفرا، كنبذك مكسور البواقيل\nوفي المعاشر من لو حاز من ذهب … طودا، لضن بإعطاء المثاقيل\nفاجعل يمينك بالإحسان مطلقة؛ … وخفف الوطء، لا تهمم بتثقيل\nإن شاء ربك رقاك العلا درجا، … فما مراقيك بالعيس المراقيل\nيقول ملك: عسى قيل يدوم لنا؛ … وإنما الملك لهو، كالعساقيل"},{"id":"diwan-maarri:1118","bookId":"diwan-maarri","type":"poem","seq":1118,"chapter":"قصائد","title":"أيتها النفس لا تهالي!","page":"","text":"أيتها النفس لا تهالي! … شرخي قد مر واكتهالي\nلم يبق إلا شفا يسير، … قرب من موردي نهالي\nوابتهل الدهر في أذاتي، … وكان في الباطل ابتهالي\nوأم دفر فتاة سوء، … تخبؤني في ثرى مهال\nمرسلة غارة بخيل، … قد غنيت عن هب وهال\nوجدت حبي لها قديما، … وقد تبينت مقتها لي"},{"id":"diwan-maarri:1119","bookId":"diwan-maarri","type":"poem","seq":1119,"chapter":"قصائد","title":"أذهني! طال عهدك بالصقال؛","page":"","text":"أذهني! طال عهدك بالصقال؛ … وماج الناس في قيل وقال\nستطلقني المنية عن قريب، … فإني في إسار واعتقال\nكأن ذوي تجاربنا سوام، … تأنق في مراد وابتقال\nإذا انتقلت عن الأوصال نفسي، … فما للجسم علم بانتقال\nأسير، فلا أعود، وما رجوعي! … وقد كان الرحيل رحيل قال\nأمور يلتبسن على البرايا، … كأن العقل منها في عقال"},{"id":"diwan-maarri:1120","bookId":"diwan-maarri","type":"poem","seq":1120,"chapter":"قصائد","title":"وبالي فيك، يا دنيا، وبالي؛","page":"","text":"وبالي فيك، يا دنيا، وبالي؛ … وأفنيت الخليل ولم تبالي\nأغرت لنا حبالات المنايا، … بما غزلت ذكاء من الحبال\nوأربعة أنسن بكل حي، … رمتهن الحوادث بالنبال\nحشاشة عائش، ونجيع نحض، … وهيكل ميت، وعروق بالي\nكجذوة موقد، وسراج ليل، … وماء حبية، وشفا ذبال\nإذا كان الحمام بكل أرض، … فبعدا للوهود وللجبال!\nوإن إقبال قوم زال عنهم، … فما يغنى المعاشر من قبال"},{"id":"diwan-maarri:1121","bookId":"diwan-maarri","type":"poem","seq":1121,"chapter":"قصائد","title":"تعالى الله، وهو أجل قدرا","page":"","text":"تعالى الله، وهو أجل قدرا … من الإخبار عنه بالتعالي\nسعى لي والدي بغير لب؛ … وسيان العرائس والسعالي\nوكون الروح في الأجسام ألقى … نفارا، في الخدود، من النعال\nأتيت وعدت، بالتسليم، كرها، … لأقدار أتينك من معال\nولولا أن شيب المرء نار، … لما وصف المفارق باشتعال"},{"id":"diwan-maarri:1122","bookId":"diwan-maarri","type":"poem","seq":1122,"chapter":"قصائد","title":"أنفت، وقد أنفت على عقود","page":"","text":"أنفت، وقد أنفت على عقود … سوارا، كي يقول الناس حال\nوكيف أشيد في يومي بناء، … وأعلم أن في غدي ارتحالي؟\nمحالك زلة، والدهر خب، … يسير بأهله قلق المحال\nأقمنا في الرحال، ونحن سفر، … كأنا قاعدون على الرحال\nأراك الجهل أنك في نعيم؛ … وأنت، إذا افتكرت، بسوء حال\nإذا ما كان إثمدنا ترابا، … فأي الناس يرغب في اكتحال؟\nوما سمحت لنا الدنيا بشيء، … سوى تعليل نفس المحال\nوأعوزت الفضيلة كل حي، … فما هو غير دعوى وانتحال"},{"id":"diwan-maarri:1123","bookId":"diwan-maarri","type":"poem","seq":1123,"chapter":"قصائد","title":"يلام الممسك الإعطاء، حتى","page":"","text":"يلام الممسك الإعطاء، حتى … جفون ما تساعد بانهمال\nأسيئي في فعال، أو كلام، … فقد جربت صبري واحتمالي\nإذا الحيوان فض العقل منه، … فما فضل الأنيس على النمال؟\nأرى زمنا تقادم غير فان؛ … فسبحان المهيمن ذي الكمال\nقد اكتحلت عيون للثريا، … بما يربي على كثب الرمال\nغدونا سائرين على وفاز، … صحاة، مثل شراب ثمال\nعلى الفرسين، لا فرسي رهان، … أو الجملين، ليسا كالجمال\nفلا يعجب، بصورته، جميل … فإن القبح يطوى، كالجمال\nوما غضبي، إذا جرت القضايا … بتفضيل اليمين على الشمال؟\nكذاك الدهر إظلام وصبح، … وريح من جنوب أو شمال\nبلا مال، عن الدنيا، رحيلي، … وصعلوكا خرجت بغير مال"},{"id":"diwan-maarri:1124","bookId":"diwan-maarri","type":"poem","seq":1124,"chapter":"قصائد","title":"أبى طول البقاء وحب سلمى","page":"","text":"أبى طول البقاء وحب سلمى … هلال، حين يطلع لا يبالي\nيمر على الجبال، وهن صم، … فيعطي الوهن راسية الجبال\nفهل قين، يباشر نسج درع … لما يرمي الزمان من النبال\nأغار حبال قوم، فاستمرت؛ … وكر، فجد في نقض الحبال\nعجبت له، فتبا لي وتبا … لغيري، إن جمعنا للتبال\nوكم سرح الخليط لهم سواما، … فما نفع القبائل من قبال\nأصالح! هل أصالح، أو أعادي، … وبالي موقن بعظام بالي؟"},{"id":"diwan-maarri:1125","bookId":"diwan-maarri","type":"poem","seq":1125,"chapter":"قصائد","title":"أمالي الزمان، على بنيه،","page":"","text":"أمالي الزمان، على بنيه، … حوادث أصبحت شر الأمالي\nأصاب الرملة الحدثان يوما، … فخص، وما يزال أخا اشتمال\nوهل عصمت جبال أو بحار، … فتنجو ساكنات بالرمال؟\nوما لمجاور الأيام عقل، … يكشف ليله، فيقول: مالي\nفلا تبني خيامك في محل، … فإن القاطنين على احتمال\nوأجنحة النسور، إذا أتتها … مناياها، كأجنحة النمال\nإذا كان الجمال إلى انتساخ، … فحزنا جر موهوب الجمال\nوما طير اليمين بمبهجاتي، … فأخشى الهم من طير الشمال\nمضى روض، وجاء ولم يخبر، … فنسأله عن الشرب الثمال\nفيا دار الخسار! ألا خلاص، … فأذهب في الجنوب أو الشمال\nوظلم أن أحاول فيك ربحا، … ولم أخرج إليك برأس مال\nوهل دون السلامة بعد أرض … فيطوى بالأيانق والجمال؟\nنموت لأننا حلفاء نقص، … ويبقى من تفرد بالكمال"},{"id":"diwan-maarri:1126","bookId":"diwan-maarri","type":"poem","seq":1126,"chapter":"قصائد","title":"تحمل ثقل نفسك، واحفظنها،","page":"","text":"تحمل ثقل نفسك، واحفظنها، … فقد حط المهيمن عنك ثقلي\nألم تر عالما يمضي، ويأتي … سواه، كأنه مرعي بقل؟\nهي الأفهام، قد صدئت وكلت، … ولم يظفر لها أحد بصقل\nأتعقل ساعة، فتروم عقلا … لعنسك، أم خلقت بغير عقل؟\nوكيف أجيد، في دار، بناء … ورب الدار يؤذنني بنقل؟"},{"id":"diwan-maarri:1127","bookId":"diwan-maarri","type":"poem","seq":1127,"chapter":"قصائد","title":"جهلتك بل عرفتك، ما خشوعي","page":"","text":"جهلتك بل عرفتك، ما خشوعي … لغيرك، بين عرفاني وجهلي\nسألتك أن تمن علي شيخا، … وفيك حملت رعب فتى وكهل\nولم تعجل، بمهلكي، المنايا، … ولكن طال إمهالي ومهلي\nأعذني، محسنا، من شر نفسي، … وأتبع ذاك لي بشرور أهلي\nفهبني كنت في مدحي رزينا، … يروم فواصل الحسن بن سهل"},{"id":"diwan-maarri:1128","bookId":"diwan-maarri","type":"poem","seq":1128,"chapter":"قصائد","title":"غدت هذي الحوافل راتعات،","page":"","text":"غدت هذي الحوافل راتعات، … وما جادت لنا بقليل رسل\nلقد درنت بي الدنيا، زمانا، … وسوف يجيد عنها الموت غسلي\nوكم شاهدت من عجب وخطب؛ … ومر الدهر بالإنسان يسلي\nتغير دولة، وظهور أخرى، … ونسخ شرائع، وقيام رسل\nوضب ما رأى، في العيش، خيرا، … وما ينفك من تربيت حسل\nلو ان بني أفضل أهل عصري … لما آثرت أن أحظى بنسل\nفكيف، وقد علمت بأن مثلي … خسيس لا يجيء بغير فسل!"},{"id":"diwan-maarri:1129","bookId":"diwan-maarri","type":"poem","seq":1129,"chapter":"قصائد","title":"أرى السرقات في كفر ومصر،","page":"","text":"أرى السرقات في كفر ومصر، … أتتك بحلي أسوار وحجل\nوليسا من نضار، بل حديد، … وقد حكما بقطع يد ورجل\nجررت الذيل في سفه المخازي، … فليتك نافر ذيال إجل\nيشب الحرب مشتاق إليها، … يحث على الهياج وعنه تجلي\nوما تثني المقادر عن مراد، … بما جمعت من خيل ورجل"},{"id":"diwan-maarri:1130","bookId":"diwan-maarri","type":"poem","seq":1130,"chapter":"قصائد","title":"هي الدنيا، إذا طلبت أهانت،","page":"","text":"هي الدنيا، إذا طلبت أهانت، … وعالت، والفريضة ذات عول\nفما أنا ساعيا فيها لغيري؛ … ولا أحمدت أقواما سعوا لي"},{"id":"diwan-maarri:1131","bookId":"diwan-maarri","type":"poem","seq":1131,"chapter":"قصائد","title":"يمر الحول، بعد الحول، عني،","page":"","text":"يمر الحول، بعد الحول، عني، … وتلك مصارع الأقوام حولي\nكأني بالألى حفروا لجاري، … وقد أخذوا المحافر وانتحوا لي"},{"id":"diwan-maarri:1132","bookId":"diwan-maarri","type":"poem","seq":1132,"chapter":"قصائد","title":"رأيت المرء يهوي في هبوط،","page":"","text":"رأيت المرء يهوي في هبوط، … إذا هو فوق أيدي القوم عولي\nوما أدري بما سيكون مني، … ولكن في البسيطة أوسعوا لي"},{"id":"diwan-maarri:1133","bookId":"diwan-maarri","type":"poem","seq":1133,"chapter":"قصائد","title":"رأى الأقوام دنياهم عروسا،","page":"","text":"رأى الأقوام دنياهم عروسا، … وما لقيتهم إلا بغول\nمتى أنا راحل عنها لشأني، … فإني قد قضيت بها شغولي"},{"id":"diwan-maarri:1134","bookId":"diwan-maarri","type":"poem","seq":1134,"chapter":"قصائد","title":"عرفتك جيدا، يا أم دفر،","page":"","text":"عرفتك جيدا، يا أم دفر، … وما إن زلت ظالمة فزولي\nدعيت أبا العلاء، وذاك مين، … ولكن الصحيح أبو النزول\nأغي الطفل من بعد التناهي، … وضعف السقب في حال البزول؟"},{"id":"diwan-maarri:1135","bookId":"diwan-maarri","type":"poem","seq":1135,"chapter":"قصائد","title":"إذا ما جد كلب، وهو أعمى،","page":"","text":"إذا ما جد كلب، وهو أعمى، … تصيد ربة الطرف الكحيل\nمتى تقف الركاب علي جهلا، … فأنت كواقف الربع المحيل\nتعود علي كرات الليالي، … وما أبرمته مثل السحيل\nتحفوا بالكلام، وأكرموني … على ما كان من جسد نحيل\nدعوا هذا المقال، وجهزوني، … فإني قد عزمت على الرحيل"},{"id":"diwan-maarri:1136","bookId":"diwan-maarri","type":"poem","seq":1136,"chapter":"قصائد","title":"لم لا أؤمل رحمة من قادر،","page":"","text":"لم لا أؤمل رحمة من قادر، … والسول يطلب في السحاب الأسول\nوالدهر أكوان، تمر سريعة، … ويكون آخرها نظير الأول\nويؤلف الوقت المدير قصارها، … حتى يعد من الزمان الأطول\nوالعقل يزجر، والطباع مع النهى، … كالفيل يضرب رأسه بالمغول\nدنياك أم قد أجاب مليكها، … فيها من الأبناء، دعوة جرول\nوتجول فوق الساكنين، كأنها … ورهاء هاجرة، غدت في مجول\nوالفقر أروح، في الحياة، من الغنى؛ … والموت يجعل خائلا كمخول\nإن اللقاح، وإن أتاك بثروة، … فأقل منه أذى حيال الحول\nوالمرء يعقد، بالبعيد، رجاءه، … كالرسل رجي في النياق الشول\nكم أحرز، المال، المقيم، بجده، … وسعى الحريص، فعاد غير ممول\nورأيت شر الجار يشمل جاره، … كرحى الفم انتزعت بذنب المقول"},{"id":"diwan-maarri:1137","bookId":"diwan-maarri","type":"poem","seq":1137,"chapter":"قصائد","title":"شعر، كساه الدهر صبغة حاذق،","page":"","text":"شعر، كساه الدهر صبغة حاذق، … لونا، أقام بحاله لم ينصل\nشبحي، وإن نلت الثريا، للثرى … طعم، وعنصر خيرنا كالعنصل\nوالناس كلهم بغى ما فاته، … وغدا يحاول مطلبا لم يحصل\nمتنصل من غير ذنب فيهم، … وأخو ذنوب ليس بالمتنصل\nلو خيروا بين الحياة وغيرها، … ما كانت الدنيا اختيار محصل\nوأرى الفتى بلغ المكارم والعلا … بالحظ، لا بسنانه والمنصل\nجسم يذم النفس، وهي تذمه، … في مجمل، من أمرها، ومفصل\nيتقاطعون، وفي القطيعة راحة، … من بؤس عيش، بالأذاة، موصل\nتلقى النفوس حتوفها من مظلم، … أو مصبح، أو مظهر، أو مؤصل\nفكأن روحك لم يحل بشخصه، … والراح ما دبت له في مفصل"},{"id":"diwan-maarri:1138","bookId":"diwan-maarri","type":"poem","seq":1138,"chapter":"قصائد","title":"آليت، أرغب في قميص مموه،","page":"","text":"آليت، أرغب في قميص مموه، … فأكون شارب حنظل من حنضل\nنجى المعاشر، من براثن صالح، … رب يفرج كل أمر معضل\nما كان لي فيها جناح بعوضة، … والله ألبسهم جناح تفضل"},{"id":"diwan-maarri:1139","bookId":"diwan-maarri","type":"poem","seq":1139,"chapter":"قصائد","title":"هي غربتان: فغربة من عاقل،","page":"","text":"هي غربتان: فغربة من عاقل، … ثم اغتراب من محكم عقله\nوالطبع يثبت كالهضاب، ومن يرم … نقلا له يعجز ويعي بنقله\nوالحق يثقل كل غاو ظالم، … وأخو الديانة ما يحس بثقله"},{"id":"diwan-maarri:1140","bookId":"diwan-maarri","type":"poem","seq":1140,"chapter":"قصائد","title":"للخير منزلتان عند معاشر،","page":"","text":"للخير منزلتان عند معاشر، … وله على رأي ثلاث منازل\nوالله يغفر، في الحساب، لنسوة، … جاهدن، إذ فقد الحيا، بمغازل\nفكسبن منها ما يقوم بأنفس، … والصبر يبدن في الزمان الهازل\nأتصدقت بالخيط، ثم هوت إلى ال … حمراء، فاعتصمت بخيط الغازل\nوأنالت المسكين أكلة جائع، … فغدت كرضوى في المقام الآزل\nإن البعوضة، من تقى، موزونة … بالفيل، عند مليكها، والبازل\nوتصون حبة خردل قدم الفتى … عن زلة، واليوم حلف زلازل\nخف دعوة المظلوم، فهي سريعة … طلعت، فجاءت بالعذاب النازل\nعزل الأمير عن البلاد، وما له … إلا دعاء ضعيفها من عازل"},{"id":"diwan-maarri:1141","bookId":"diwan-maarri","type":"poem","seq":1141,"chapter":"قصائد","title":"عز الذي بالموت رد غنينا","page":"","text":"عز الذي بالموت رد غنينا … كفقيرنا، ومقيمنا كالراحل\nما أسرع التغيير، إن مره الفلا … بسرابه، فالليل إثمد كاحل\nأعيى الخلاص من السقام، وصورة ال … قمر المنير إلى هلال ناحل\nأعجبت للطفل الوليد بمهده، … لم يخط، كيف سرى بغير رواحل\nقد عاش يوميه وعمر ثالثا، … ثم استراح من المدى المتماحل\nكم سار من سنة أبوه، فيا له، … قطع المسافة في ثلاث مراحل\nرفعت له لجج البحار، فعامها، … ونجا وأصبح سالما بالساحل"},{"id":"diwan-maarri:1142","bookId":"diwan-maarri","type":"poem","seq":1142,"chapter":"قصائد","title":"لا يغبطن ماش فوارس شزب،","page":"","text":"لا يغبطن ماش فوارس شزب، … ما فارس إلا كآخر راجل\nويداي في دنياي، وهي حبيبة، … كيدي أبي لهب غدا في الآجل\nوإذا افتكرت، فما يهيج تفكري، … فيما أكابد، غير لوم الناجل\nوأرحت أولادي، فهم في نعمة ال … عدم، التي فضلت نعيم العاجل\nولو أنهم ظهروا لعانوا شدة، … ترميهم في متلفات هواجل\nأسوىء بحال الظبي، وهو مربب … في الإنس، يمرح في حلى وجلاجل\nأطلب لنفسك، يا أغن، محلة … في حيث لا تدميك زجلة زاجل\nلولا نوافر، في القديم، تناسلت، … ما أنضج الظبيات غلي مراجل\nوسوالف القمر السواكن بالفلا، … غذين أيدي أيد بمناجل\nلا تأسفن حواجل الغربان، وال … فتيان كلهم بقيد حاجل\nوسجل موت، راح يكتبه الردى … لمساجل، منا، وغير مساجل"},{"id":"diwan-maarri:1143","bookId":"diwan-maarri","type":"poem","seq":1143,"chapter":"قصائد","title":"غلت الشرور، ولو عقلنا صيرت","page":"","text":"غلت الشرور، ولو عقلنا صيرت … دية القتيل كرامة للقاتل\nهذي حبال الشمس، وهي ضعيفة، … دامت، وكم أبلت حبالة خاتل"},{"id":"diwan-maarri:1144","bookId":"diwan-maarri","type":"poem","seq":1144,"chapter":"قصائد","title":"أسررت، إذ مر السنيح، تفاؤلا،","page":"","text":"أسررت، إذ مر السنيح، تفاؤلا، … والفال من رأي، لعمرك، فائل\nأرأيت فعل الدهر في أمم مضت، … قبلا، ومرج قبائل بقبائل؟\nأسرج كميتك، في الكتائب، جائلا، … ودع الكميت أخا الحباب الجائل\nخسر الذي باع الخلود، وعيشه، … بنعيم أيام، تعد، قلائل\nوتخير المغرور طول بقائه، … سفها، وما طول البقاء بطائل\nوتفاوت الأجسام، ثم جميعها … متقاربات في نهى وخصائل\nحر يضيق، عن الوليدة، طوله، … وسواه لم يقنع بتسع حلائل\nجمد النضار له، فما هو سائل، … من جود راحته، براحة سائل\nما المرء نائل رتبة من سؤدد، … حتى يصير ماله في النائل\nلو عدت من أسد النجوم بجبهة، … أو بت في ذنب لشبوة شائل\nأو كنت رأس الغول، وهو موقر، … في الشهب، لم آمن تهجم غائل\nكان الشباب ظلام جنح، فانجلى، … والشيب يذهب في النهار الزائل\nوالغر يرسل قوله بمواعد … ولد، فتنتج عن يمين حائل\nوأقل أهل الأرض حظا، في العلا، … من يكتفي منها بخطبة قائل\nوالحي شاهد رزء خطب هائل، … من كون ميت تحت أنمل هائل\nقد خلت أنك محسن فيما مضى، … والخال يكذب فيه ظن الخائل\nلا تفرحن بدولة أوتيتها، … إن المدال عليه مثل الدائل\nومتى حظيت بنعمة من منعم، … فتوق واحذر صولة من صائل\nوعقائل الألباب غير أوامر … بأذاة أيتام، وهتك عقائل\nوإذالة الإنسان، ليس بمانع … منها تحرزه بدرع ذائل\nوحبائل الدنيا تزيد على الحصى؛ … وأقل أنفاسي أدق حبائلي"},{"id":"diwan-maarri:1145","bookId":"diwan-maarri","type":"poem","seq":1145,"chapter":"قصائد","title":"حكم تدل على حكيم قادر،","page":"","text":"حكم تدل على حكيم قادر، … متفرد، في عزه، بكمال\nوالمال خدن النفس، غير مدافع؛ … والفقر موت جاء بالإهمال\nأوما ترى حكم النجوم مصورا … بيت الحياة، يليه بيت المال؟\nومن الجهات الست ربي حائطي، … لا عن يميني، مرة، وشمالي\nأرواحنا ألفين كالأرواح، في … خير وشر، من صبا وشمال\nوالمرء كان ، ومثل كان، وجدته، … حاليه في الإلغاء والإعمال\nثمل الأنام من الضلالة، وانتشوا … بالخمر، فاعجب من ثمال ثمال\nقوم تغنوا مرملين من الهدى، … فتضاعف الإرمال بالأرمال\nوهم البهام، قصيرة أعمارهم، … ويؤملون أطاول الآمال\nلم تلق إلا جاهلا متعاقلا، … متجملا منهم بغير جمال\nمثل البهائم أبهمت عن رشدها، … إلا احتمال ثقائل الأحمال\nدنياك أرزاق تذكر، بعدها، … أخرى، تنال بصالح الأعمال"},{"id":"diwan-maarri:1146","bookId":"diwan-maarri","type":"poem","seq":1146,"chapter":"قصائد","title":"يا صاح! ما أهوى وما أقلي؛","page":"","text":"يا صاح! ما أهوى وما أقلي؛ … ثقلي علي، فلا تزد ثقلي\nإن العقول تقول مولية: … ليس الأنام كنابت البقل\nصدئت خواطرنا، فما صقلت، … والمكث أحوجها إلى الصقل\nدنياك دار، كل ساكنها … متوقع سببا من النقل\nوالنسل أفضل ما فعلت بها، … وإذا سعيت له فعن عقل"},{"id":"diwan-maarri:1147","bookId":"diwan-maarri","type":"poem","seq":1147,"chapter":"قصائد","title":"عشت من أيسر حل،","page":"","text":"عشت من أيسر حل، … وتشبهت بظل\nلست بالخل أصا … فيك، وما أنت بخل\nربما يعتمد المر … ء على العضو الأشل\nأيها الدنيا! لحاك الله … من ربة دل\nما تسلى خلدي عن … ك، وإن ظن التسلي\nإنما أبقيت مني، … للأخلاء، أقلي\nأمس أوديت ببعضي، … وغدا يذهب كلي\nلك أوقاتي، فخلي … ني، إذا قمت أصلي\nودعيني، ساعة في … ك، لمولاي الأجل\nوالصبا ملك، وقد يب … كى على الملك المولي"},{"id":"diwan-maarri:1148","bookId":"diwan-maarri","type":"poem","seq":1148,"chapter":"قصائد","title":"دنياك والحمام في رتبة،","page":"","text":"دنياك والحمام في رتبة، … من خارج غم، ومن داخل\nما طهرت، بل دنست، وارتمت … بالسيد الوهاب والباخل\nلو نخل العيش لما حصلت … شيئا، سوى الموت، يد الناخل"},{"id":"diwan-maarri:1149","bookId":"diwan-maarri","type":"poem","seq":1149,"chapter":"قصائد","title":"كن وشيكا في حاجة، أو مكيثا،","page":"","text":"كن وشيكا في حاجة، أو مكيثا، … ليس مر الأيام فينا بمهل\nحبذا العيش، والزمان غرير، … والفتى ما استجد حلة كهل\nوخمولي يذود عني الرزايا؛ … نام عني الأذى، فلم ينتبه لي\nقبل أن ينطق الزمان بتصغي … ر كبار، من فرط عي وجهل\nإذ ثريا النجوم تسمى بثروى، … وسهيل السماء يدعى بسهل\nولجين لجن، كبيرة لفظ، … ولجيم، كذاك أخلاق سهل"},{"id":"diwan-maarri:1150","bookId":"diwan-maarri","type":"poem","seq":1150,"chapter":"قصائد","title":"سل سبيل الحياة عن سلسبيل،","page":"","text":"سل سبيل الحياة عن سلسبيل، … لا تخبر عن غير ورد وبيل\nوالمنايا لقين، بالجندل الف … ظ، ثنايا لقين بالتقبيل\nهل ترى سيد القرابة أضحى … مفرد الشخص، ما له من قبيل\nقوضته، وطالما قوضته، … مخبلات أعقبن بالتخبيل\nلم تحد نبل دهرنا برماح، … أو سيوف، عن ساقط أو نبيل\nوبني الأشعث استباحت رزايا … ها، وألقت كلا على رتبيل\nيا طبيب المصر! اجتهدت، وما الج … لاب جلاب راحة لنبيل\nوإذا وقرت جبال الردى جل … ت، فلم تندفع بجل جبيل\nأيها الجامع الكنوز! أذر … أم زبال من نملة في زبيل؟\nصدقات من المليك، على الحت … ف، جسوم عرفن بالتسبيل\nلا تؤبل أخاك، يوما، إذا ما … ت، فما كان موضع التأبيل\nوارتقب، من مؤذن القوم، فتكا، … فالنصارى يشكون فعل الأبيل\nولحبر اليهود، في درسه التو … راة فن، والهم في التدبيل\nربلته أسفارها، وحمته، … طول اسفاره، من التربيل\nحسن القول، يبتغي نضرة العي … ش بغش الإذواء، والتذبيل\nفاقدروا، من بنات ضأن، عبورا … سره أن تكون كالزندبيل\nواصنعوا من حلاوة ذات طيب، … لا برطلي بغداد، بل أردبيل\nواحذروا أن تواكلوه، فما يأ … من ديانكم يد الجردبيل\nإن تحلوا شاما، فخمر جبال، … أو عراقا، فالشرب من نهر بيل\nوهي رومية لزنجية الأع … ناب، فيها طعم من الزنجبيل\nذات خرس، تردد النطق أخ … رس، يشكو على اللسان الخبيل\nقد أراكم تلطفا، وهو في الغل … ظة من جرهم، وآل عبيل\nموعد بالإجرام يوعد أم الن … سل فيه، بالثكل والتهبيل\nفليحده على قرى حربته: … كفر توتا منها وكفر تبيل\nيطلق الخمس في الحرام، وأما الل … فظ منه، فدائم التكبيل\nكذب لا يزال يطعم خبزا، … نص عن آدم وعن قابيل\nيمتريه جذلان مهتبل الغر … ة، يبدي حزنا على هابيل\nلا تعري الليث المنون، ولا الشب … ل، ولا المغفرات في إشبيل\nأنا بئس الإنسان، والناس مثلي، … فاعتبيني إن شئت، أو فاعتبي لي"},{"id":"diwan-maarri:1151","bookId":"diwan-maarri","type":"poem","seq":1151,"chapter":"قصائد","title":"الفتى قد رأى اليقين، ولكن","page":"","text":"الفتى قد رأى اليقين، ولكن … يؤثر العيش، فهو كالمختول\nخير فيما أراه لامرأة الجن … دي، من زوجها المقتول\nإذ أغارت حبل القناعة، تبغي الر … زق من عند خيطها المفتول\nخلصت من بناتها وبنيها، … فهي، بين النساء، مثل البتول"},{"id":"diwan-maarri:1152","bookId":"diwan-maarri","type":"poem","seq":1152,"chapter":"قصائد","title":"لقد علم الله، رب الكمال،","page":"","text":"لقد علم الله، رب الكمال، … بقلة علمي وديني ومالي\nوأن التجمل قد ضاق بي، … فكيف أنافس أهل الجمال؟\nأريد الإناخة في منزل، … وقد حديت لسواه جمالي\nلقد خاب من يبتغي نصرتي، … وعاجزة عن يميني شمالي\nفمن مخبري: أغريق البحا … ر ألقى الردى، أم دفين الوصال؟\nهويت انفرادي، كيما يخف، … عمن أعاشر، ثقل احتمالي\nفماذا أقول، وبين الأنا … م خلف على جهلهم، أو تمالي؟\nأما لي، فيما أرى، راحة، … مدى الدهر، من هذيان الأمال؟"},{"id":"diwan-maarri:1153","bookId":"diwan-maarri","type":"poem","seq":1153,"chapter":"قصائد","title":"عجبت، وكم عجب في الزمان،","page":"","text":"عجبت، وكم عجب في الزمان، … لرأي بني دهرك الفائل\nفمقتا لما أورثوا من غنى، … وما وهبوه من النائل\nفلا تحملن لهم منة، … ولو بت في صورة العائل\nيغول الفتى أرضه بالوجيف، … ولا بد من حادث غائل\nويطلب قوتا، ورزق الملي … ك يسأل بالطالب السائل\nألم ترني، وجميع الأنا … م، في دولة الكذب الذائل؟\nمضى قيل مصر إلى ربه، … وخلى السياسة للخائل\nوقالوا: يعود، فقلنا: يجوز … بقدرة خالقنا الآئل\nإذا هب زيد إلى طيىء، … وقام كليب إلى وائل\nأخو الحرب يعدو على سابح، … ليسبح في الزاخر السائل\nسيقصر من طول تلك القناة، … ويرفع من درعه الذائل\nوتصغي، إلى المين، أسماعنا، … ونصبو إلى زخرف القائل\nوكيف اعتدالي، وهذا النهار … يروح بميزانه المائل؟\nوإن ثبيرا له خفة، … تبين على كفة الشائل\nتصول علينا بنات الزمان؛ … فهلا يصال على الصائل!\nوقد عز رمل على حاسب، … كما عز بحر على كائل\nيهال التراب على من ثوى؛ … فآه من النبإ الهائل\nوكم قيد الدهر من دالف، … وقد كان كالسابق الجائل\nجميع الذي نحن فيه النفاق، … ونلحق بالذاهب الزائل\nولو لم يكن حولك العاذلون، … بكيت على المنزل الحائل\nويغنيك، عن طرح فال، تعو … د باليمن، طعنك في الفائل\nنسر، إذا نثرة أرعفت، … ونفرح بالأسد البائل"},{"id":"diwan-maarri:1154","bookId":"diwan-maarri","type":"poem","seq":1154,"chapter":"قصائد","title":"أتاني بإسناده مخبر،","page":"","text":"أتاني بإسناده مخبر، … وقد بان لي كذب الناقل\nأذو العصمة العاقل الآدمي، … إلا كذي العصمة العاقل؟\nولا فضل فينا، ولكنها … حظوظ من الفلك الصاقل\nفهذا كسحبان لما احتبى، … وذلك في سملي باقل"},{"id":"diwan-maarri:1155","bookId":"diwan-maarri","type":"poem","seq":1155,"chapter":"قصائد","title":"إذا عشت مفتكرا في الأنام،","page":"","text":"إذا عشت مفتكرا في الأنام، … غدوت على المدرج السابل\nفتلك الثريا، وهذا الثرى، … شبيهان في قبضة الجابل\nحبوت بنصحك مستكبرا، … وما هو للنصح بالقابل\nوسخط الظباء بما نالها، … تولد منه رضى الحابل\nهو الموت، من ينج من رامح، … فلا بد من أسهم النابل\nلنا أسوة في رجال مضوا؛ … وهل أنا إلا أخو الآبل؟\nمتى لمتماني على زلة، … رجعت على أمي الهابل\nوهاروت، كيف عصى ربه … بتعليمه السحر في بابل؟\nإذا العام جاد بأدنى اليسا … ر، أملت أسناه في القابل\nفإن القليل يؤم الكثي … ر، كالطل بشر بالوابل"},{"id":"diwan-maarri:1156","bookId":"diwan-maarri","type":"poem","seq":1156,"chapter":"قصائد","title":"قرنت الجياد بأجمالها،","page":"","text":"قرنت الجياد بأجمالها، … لتسعف نفسا بآمالها\nولا بد من سيرها مرة، … بعد التفات إلى مالها\nوأفضل ما اكتسبت أمة، … وإن شقيت، حسن أعمالها\nولا خير في أن تمد الحياة، … ونقصانها مثل إكمالها\nفويها، وواها لسيل المنو … ن، كم جر عيرا بأحمالها\nأمور توافي جنود الردى، … بتفصيلها، بعد إجمالها\nوقد أعمل الناس أفكارهم، … فلم يغنهم طول إعمالها\nفهل يرمل الدهر أم الأنام … فتفقد نسلا بإرمالها؟"},{"id":"diwan-maarri:1157","bookId":"diwan-maarri","type":"poem","seq":1157,"chapter":"قصائد","title":"استعدت الخمر من أفعال شاربها","page":"","text":"استعدت الخمر من أفعال شاربها … إلى المليك، فقالت: شج ثم قتل\nوجارح الدن، ما كانت جراحته … قصاص عمد، ولكن للمدام ختل\nيود أن دجاه فار خابية؛ … وأن كل غمام بالعقار هتل\nماذا تريدين منه قد ظفرت به، … ألم تريه صريعا في التراب يتل؟"},{"id":"diwan-maarri:1158","bookId":"diwan-maarri","type":"poem","seq":1158,"chapter":"قصائد","title":"غض الجفون، إذا جلس","page":"","text":"غض الجفون، إذا جلس … ت على الصعيد، ولا تأمل\nوالبيت أولى بالكري … م من الطريق، وإن تجمل\nوالذكر يتركه الفتى … للقاطنين، إذا تحمل\nوالمرء تعجبه الحيا … ة، وعيشه سم يثمل\nمن ذا الذي سمح الزما … ن له بإدراك المؤمل؟\nفيه توافى المرملو … ن، وقل أصحاب المرمل\nحيل تمن على الأنا … م، فأدمع العقلاء همل\nكم غر، صاحبة الجما … ل، منجم بحساب جمل"},{"id":"diwan-maarri:1159","bookId":"diwan-maarri","type":"poem","seq":1159,"chapter":"قصائد","title":"الله إن أعطاك يجزل،","page":"","text":"الله إن أعطاك يجزل، … وكأن هذا الدهر يهزل\nكسرى بنى إيوانه، … والعنكبوت تظل تغزل\nهل يشعرن الميت إن … ظهر الثرى، بالحي، زلزل؟\nأرجوا، أو اعتزلوا، فإن … ي عن مقامكم بمعزل\nقد طال سيري في الحيا … ة، ولي ببطن الأرض منزل"},{"id":"diwan-maarri:1160","bookId":"diwan-maarri","type":"poem","seq":1160,"chapter":"قصائد","title":"أشهد أني رجل ناقص،","page":"","text":"أشهد أني رجل ناقص، … لا أدعي الفضل، ولا أنتحل\nجئت، كما شاء الذي صاغني، … ومن يصفني بجميل يحل\nتزوج الشيخ، فألفيته، … كأنه مثقل إبل وحل\nوعرسه في تعب دائم، … لا تخضب الكف ولا تكتحل\nملت، وإن أحسن أيامه، … تقول في النفس: متى يرتحل؟\nلو مات لاستبدلت منه فتى، … إني أراه محرما لا يحل\nويثبت الله وسلطانه، … وكل أمر، غيره، يضمحل"},{"id":"diwan-maarri:1161","bookId":"diwan-maarri","type":"poem","seq":1161,"chapter":"قصائد","title":"قد بكرت لا يعوقها سبل،","page":"","text":"قد بكرت لا يعوقها سبل، … كمهرة الروض، من بنات سبل\nإلى طبيب على الطريق، لكي … تأخذ من عنده دواء حبل\nكم قذفت عرس بائس بحصى، … كل حصاة منها نظير جبل"},{"id":"diwan-maarri:1162","bookId":"diwan-maarri","type":"poem","seq":1162,"chapter":"قصائد","title":"سبح الله طالع مستنير،","page":"","text":"سبح الله طالع مستنير، … وهلال مثل القلامة ناحل\nوبدت، من بنات نعش، غوان، … لم يصبها من إثمد الليل كاحل\nكالسوام الأنام، هل فاز من سا … فر منهم إلى بطيء المراحل؟\nيمني وفارسي وشامي، … وغاد، من أهل غربة، راحل\nساحليون، لم أرد ساحل البح … ر، ولكن نسبا لأقمر ساحل\nخف ملك على السرير، فهل يو … جد في العالمين قرم حلاحل؟"},{"id":"diwan-maarri:1163","bookId":"diwan-maarri","type":"poem","seq":1163,"chapter":"قصائد","title":"عجبا للقطا، من الكدر والجو","page":"","text":"عجبا للقطا، من الكدر والجو … ن، غدت في عنائها المتواصل\nلقطت حبة، وجاءت بها الأف … راخ، ثم استقت لها في الحواصل\nمن بلاد بعيدة، لسراب ال … هجر، فيها، لوامع كالمناصل\nفأغاثت، بوردها، مودعات … في هجول، تقل فيها الصلاصل\nهائفات، قد مزق الحر عنها … الأهب، أو هم أن يميز المفاصل\nراعها أجدل من الطير، أو با … ز، فمود، قبل الوصول، وواصل\nصاليات، وما لها من صلاة، … صائمات لغير نسك تواصل\nثم باد المصيد، من بعد، والصا … ئد، لا شيء غير ذلك حاصل\nفاتق الله وافعل الخير، فالمو … ت حسام يفري البرية قاصل\nلا تغير هذا البياض، فإن تأ … ب فلا تجزعن إن قيل: ناصل\nإن أعمارنا كآي أبينت، … والمنايا لهن مثل الفواصل"},{"id":"diwan-maarri:1164","bookId":"diwan-maarri","type":"poem","seq":1164,"chapter":"قصائد","title":"فر من هذه البرية في الأر","page":"","text":"فر من هذه البرية في الأر … ض، فما غير شرها لك حاصل\nفشعاري: قاطع؛ وكان شعارا … لتنوخ، في سالف الدهر، واصل\nواطلب الرزق بالمرور من الشج … راء، لا من أسنة ومناصل\nوتشبه بالطير تغدو خماصا، … وتعد اليسار ملء الحواصل"},{"id":"diwan-maarri:1165","bookId":"diwan-maarri","type":"poem","seq":1165,"chapter":"قصائد","title":"رام دنياه ناسك،","page":"","text":"رام دنياه ناسك، … فادعى النسك وانتحل\nأصبح المفتري على الله، … قد ذل واضمحل\nبينما يعمر المنا … زل، قالوا: قد ارتحل\nعز رب النجوم تس … ري، ولا تسأم الرحل\nأينام السماك أم … هو، بالغمض، ما اكتحل\nجهل المشتري، وإن … كان في الخير ذا محل\nأي ذنب أصابه، … فسما فوقه زحل؟"},{"id":"diwan-maarri:1166","bookId":"diwan-maarri","type":"poem","seq":1166,"chapter":"قصائد","title":"أرى حبلا، حادثا في النسا","page":"","text":"أرى حبلا، حادثا في النسا … ء، حبل أذاة بهن اتصل\nأتى ولد بسجل العناء، … فيا ليت وارده ما وصل\nوإن أنظرته خطوب الزما … ن، عض بناب شديد العصل\nوريع، من الغير الطارقا … ت، بالرمح صر وبالسيف صل\nوقال له،: صل، داعي الهدى، … وقال له ملحد: لا تصل\nوشب وشاب وأفنى الشباب؛ … وسقيا له من خضاب نصل\nومن بعد ذاك يجيء الحما … م، فانظر على أي شيء حصل\nفيا راحة النفس عند المما … ت، إن كان هذا الحساب انفصل"},{"id":"diwan-maarri:1167","bookId":"diwan-maarri","type":"poem","seq":1167,"chapter":"قصائد","title":"أتتك بحبل فتاة غدت","page":"","text":"أتتك بحبل فتاة غدت … مسائلة عن دواء الحبل\nوقد حسبت من بنات السهول، … فجاءت بإحدى بنات الجبل"},{"id":"diwan-maarri:1168","bookId":"diwan-maarri","type":"poem","seq":1168,"chapter":"قصائد","title":"أمل حبيب أدل،","page":"","text":"أمل حبيب أدل، … وستر الضلال انسدل؟\nعلى م تناظرتم، … فقد طال هذا الجدل\nتعليكم في الأمو … ر، ما هو إلا تدل\nوكلكم ظالم، … فهل من تقي عدل؟\nوتهلك ذات الكرا، … وتهلك ذات الخدل\nتقادم شخص مضى، … فأحدث منه البدل\nوما صح إلا امرؤ، … تصرف ثم انجدل\nعلا كاذب صادقا؛ … فليت المزاج اعتدل\nإذا هدر الفحل قي … ل: صوت حمام هدل\nتحير مسترشد، … فوفق لما استدل"},{"id":"diwan-maarri:1169","bookId":"diwan-maarri","type":"poem","seq":1169,"chapter":"قصائد","title":"سيسأل ناس: ما قريش ومكة،","page":"","text":"سيسأل ناس: ما قريش ومكة، … كما قال ناس: ما جديس وما طسم؟\nأرى الوقت يفني أنفسا بفنائه، … ويمحو، فما يبقى الحديث ولا الرسم\nلقد جد أهل الملعبين، فأثلوا … بناء، ولم يثبت لرافعه وسم\nوفي العالم الغاوي بخيل ممول، … وسمح فقير، شد ما اختلف القسم\nوكون الفتى في رهطه نيل عزة، … على أن داء الدهر ليس له حسم\nويرزأ جسم المرء، حتى إذا أوى … إلى العنصر التربي لم يرزإ الجسم"},{"id":"diwan-maarri:1170","bookId":"diwan-maarri","type":"poem","seq":1170,"chapter":"قصائد","title":"إذا ما تقضى الأربعون فلا ترد","page":"","text":"إذا ما تقضى الأربعون فلا ترد … سوى امرأة، في الأربعين، لها قسم\nفإن الذي وفى الثلاثين وارتقى … عليهن عشرا، للفناء به وسم\nزمان الغواني، عصر جسمك، زائد، … وهن عناء بعد أن يقف الجسم\nسألت بني الأيام عن ذاهب الصبا، … كأنك قلت الآن ما فعلت طسم\nتريد من الدنيا خلافا لما مضى، … وأعياك تدبير به سبق الرسم\nهو الداء لا ينفك يشكى ويشتكى، … ولو شاء رب الناس أدركه الحسم\nمضى الشخص ثم الذكر، فانقرضا معا، … وما مات كل الموت من عاش منه اسم"},{"id":"diwan-maarri:1171","bookId":"diwan-maarri","type":"poem","seq":1171,"chapter":"قصائد","title":"مكان ودهر أحرزا كل مدرك،","page":"","text":"مكان ودهر أحرزا كل مدرك، … وما لهما لون يحس، ولا حجم\nوليس لنا علم بسر إلهنا … فهل علمته الشمس، أو شعر النجم؟\nونحن غواة يرجم الظن بعضنا، … ليعرف ما نور الكواكب والرجم\nوتطردنا ساعاتنا، وكأننا … وسائق خيل، ما تكفكفها اللجم\nقضى الله في وقت مضى أن عامكم … يقل حياه، أو يزيد به السجم\nفقولكم: رب اسقنا، غير ممطر، … ولكن بهذا دانت العرب والعجم\nعلى كل شيء تهجمون بجهلكم، … وأعياكم يوما، على رشد، هجم"},{"id":"diwan-maarri:1172","bookId":"diwan-maarri","type":"poem","seq":1172,"chapter":"قصائد","title":"كبار أناس مثل جلة سائم،","page":"","text":"كبار أناس مثل جلة سائم، … يربون أطفالا كما ارتضع البهم\nتوهم بعض الناس أمرا، فأصلوا … يقين أمور، بات يتبعها الوهم\nجهلنا ولكن للخلائق صانع، … أقر به فسل من القوم، أو شهم\nويعلم كل أن للخير موضعا … وفضلا، على إثباته أجمع الدهم\nوأين أناس كالسحائب إن يروا … يروقوا، وإن يستمطروا للغنى يهموا؟\nفإن شئت أن تحظى بمالك، فاحبه … ذوي الحاج، أو أنفقه تبسم لك الجهم\nفما هو إلا السهم، لا كف عاديا، … ولا نال صيدا، في كنانته، السهم"},{"id":"diwan-maarri:1173","bookId":"diwan-maarri","type":"poem","seq":1173,"chapter":"قصائد","title":"إذا حرق الهندي، بالنار، نفسه،","page":"","text":"إذا حرق الهندي، بالنار، نفسه، … فلم يبق نحض للتراب ولا عظم\nفهل هو خاش من نكير ومنكر، … وضغطة قبر لا يقوم لها نظم؟"},{"id":"diwan-maarri:1174","bookId":"diwan-maarri","type":"poem","seq":1174,"chapter":"قصائد","title":"خلافك بعض الناس يرجى به المنى،","page":"","text":"خلافك بعض الناس يرجى به المنى، … وفي الدهر أقوام خلافهم حزم\nفأفطر، إذا صاموا، وصم عند فطرهم … على خبرة، إن الدواء هو الأزم\nولو لم يسر وقت الفتى، وهو موشك، … لما صح في هجر الحياة له عزم\nألا ذللوا هذي النفوس، فإنها، … ركائب سوء، ليس يضبطها الحزم\nولم يأت، في الدنيا القديمة، منصف، … ولا هو آت، بل تظالمنا جزم"},{"id":"diwan-maarri:1175","bookId":"diwan-maarri","type":"poem","seq":1175,"chapter":"قصائد","title":"نصحتك لا تنكح، فإن خفت مأثما،","page":"","text":"نصحتك لا تنكح، فإن خفت مأثما، … فأعرس، ولا تنسل، فذلك أحزم\nأظنك، من ضعف بلبك، غاديا، … يحلك، من عقد الزواج، المعزم\nإلى الله نصت رغبة أولية … نصارى تنادي، أو مجوس تزمزم\nهو الحظ، عير البيد، ساف بأنفه … خزامى، وأنف العود بالذل يخزم\nوما بيض أنثى يهزم القيض فرخه، … كبيض ذكور بالحديد يهزم\nتباركت، أنهار البلاد سوائح … بعذب، وخصت بالملوحة زمزم\nتعاليت رب الناس عن كل ريبة، … كأنا، بإتيان المآثم، نلزم\nوترفع أجساد، وتنصب مرة، … وتخفض، في هذا التراب، وتجزم\nغرائز أعطاها ربيعة جده … وشنشنة أغرى بها النجل أخزم\nوحادثة، أما الثريا بعبئها … وأينقها، والمرزمان، فرزم\nحياة، لو أني باختياري وردتها، … لما فتئت مني الأنامل تؤزم"},{"id":"diwan-maarri:1176","bookId":"diwan-maarri","type":"poem","seq":1176,"chapter":"قصائد","title":"أراك حسبت النجم ليس بواعظ","page":"","text":"أراك حسبت النجم ليس بواعظ … لبيبا، وخلت البدر لا يتكلم\nبلى، قد أتانا أن ما كان زائل، … ولكننا في عالم ليس يعلم\nوإن أخا دنياك أعمى يرى السهى، … عليل معافى، ظالم يتظلم\nفهل تألم الشمس الحوادث مثلنا، … أم اتسقت كالهضب لا يتألم؟\nوهل فيكم من باخل يظهر الندى … رياء به، أو جاهل يتحلم؟\nوما سالم الحي القضاء، وإنما … إلى الحتف يرقى، والسلامة سلم\nفيا مطلقا للنفع، يفصد كفه، … أبالكلم يستشفي الأسير المكلم؟\nلعمري لقد أعيا المقاييس أمرنا، … فحندسنا، عند الظهيرة، مظلم\nفمن محرم، لا يحرم العلق الظبا، … ومن محرم، أظفاره لا تقلم\nضعفنا عن الأشياء، إلا عن الأذى، … وقد يسم الوجه الكهام المثلم\nوإن ظليم القفر يرضيه زقه، … ويفهم عن أخدانه، وهو أصلم"},{"id":"diwan-maarri:1177","bookId":"diwan-maarri","type":"poem","seq":1177,"chapter":"قصائد","title":"توهمت خيرا في الزمان وأهله،","page":"","text":"توهمت خيرا في الزمان وأهله، … وكان خيالا، لا يصح، التوهم\nفما النور نوار، ولا الفجر جدول، … ولا الشمس دينار، ولا البدر درهم\nرأيتك لم تحمد من الترك معشرا، … لهم عارض بالترك يهمي ويرهم\nولا الكاسك المرجين في كل مظلم، … رجا كاسك الحمراء، والخيل تدهم\nوقد يأمر الله الكهام، إذا نبا، … فيفري، وقد ينهى الحسام، فيكهم\nوإنك لا باك عليك مهند، … ولا مظهر حزنا جواد مطهم\nيساوي مليك الحي صعلوك قومه، … وتسحا له الأرض الزرود، فتلهم\nوما يشعر المدفون، يسري حديثه، … فينجد في أقصى البلاد، ويتهم\nجرت عند شقراء الكميت بكفه، … إلى فيه، حتى صار في الرجل أدهم\nأتذكر، يا طرف، الوغى وركومها، … وقد صرت من نبل، كأنك شيهم\nإذا أشرعت فيك الأسنة ردها، … لصونك، تجفاف عن الطعن مبهم\nلشهباء يخفي القرن فيها كلامه، … ويفهم، إلا أنه ليس يفهم\nإذا ما تدانوا، فالضراب صفاحهم؛ … وإن يتناءوا، فالرسائل أسهم\nلهم حيل، في حربهم، ما اهتدت لها … جديس، ولا ساست بها الملك جرهم"},{"id":"diwan-maarri:1178","bookId":"diwan-maarri","type":"poem","seq":1178,"chapter":"قصائد","title":"مريدي بقائي، طالما لقي الفتى","page":"","text":"مريدي بقائي، طالما لقي الفتى … عناء بطول العيش، والله يعلم\nإذا كان بسط العمر ليس بكاسب … سوى شقوة، فالموت خير وأسلم\nأفاد غوي غيه عن شيوخه، … فهم درجات للضلال وسلم\nوأهلكه جهلان: باد مركب … قديما، وتال، بعده، يتعلم\nتفكرت واستثبت أن سكوته، … هدى وتقى، فليغد لا يتكلم\nأرى النبت أولى أن يحس بحطمه، … إذا زعموا أن الصخور تألم\nوأشهد أن الدهر كالحلم زائل؛ … وأن أديم البدر يبلى ويحلم\nوجدت يد الوهاب تطوى، وعينه … تكف، وأظفار الليوث تقلم"},{"id":"diwan-maarri:1179","bookId":"diwan-maarri","type":"poem","seq":1179,"chapter":"قصائد","title":"سأرحل عن وشك، ولست بعالم","page":"","text":"سأرحل عن وشك، ولست بعالم … على أي أمر، لا أبا لك، أقدم\nوهون إعدامي علي تحققي … بأني، وإن طال التمكث، أعدم\nفإن لم تكن إلا الحياة وبينها، … فلست، على أيامها، أتندم\nودنياك يهواها، على الهرم، الفتى، … ويخدمها، فيما ينوب، المخدم\nأرى الشخص يطوى والممالك تحتوى، … ومن صح يذوى، والمجادل تهدم\nمنعت الهوى مني، وسمتني الهوى، … وقد يبلغ الحاج الفنيق المسدم\nإذا رؤساء الناس أموا تنازعوا … كؤوس الأذى، هل في الزجاجة عندم\nولم يرضهم شرب المدامة أذهبت … حجى النفس، إلا أن يمازجها الدم\nفنحن كأيم الضال أولى مراسه، … بما كان يغوي الآخر، المتقدم\nوحواء أعطت بنتها البؤس، وابنها … لآدم، يغذى بالشقاء ويؤدم"},{"id":"diwan-maarri:1180","bookId":"diwan-maarri","type":"poem","seq":1180,"chapter":"قصائد","title":"أيا ديك! عدت من أياديك، صيحة","page":"","text":"أيا ديك! عدت من أياديك، صيحة … بعثت بها ميت الكرى، وهو نائم\nهتفت، فقال الناس: أوس بن معير، … أو ابن رباح، بالمحلة قائم\nلعل بلالا هب من طول رقدة، … وقد بليت، في الأرض، تلك الرمائم\nونعم أذين المعشر ابن حمامة، … إذا سجعت، للذاكرين، الحمائم\nوفيك، إذا ما ضيع النكس، غيرة … تصان بها المستصحبات الكرائم\nوجود بموجود النوال على التي … حميت، وإن لم تستهل الغمائم\nيزان لديك الطعن في حومة الوغى، … إذا زينت، للعاجزين، الهزائم\nفلو كنت بالدر الثمين معوضا … من البر، ما لامت عليه اللوائم\nوتلقى، لديك، المنقضات نواصعا، … يقال: غريبات البحار التوائم\nرآها كبارا من براها، كأنها … تريك نعام، أودعته الصرائم\nوتؤثر، بالقوت، الحليلة، شيمة … كريمية، ما استعملتها الألائم\nكأنك فحل الشول، حولك أينق … عليها برى، من طاعة، وخزائم\nفتلمح، تارات، وتغضي، كأنها … ضرائر، سفتها، لديك، الخصائم\nفحمر وسود حالكات، كأنها … سوام بني السيد، ازدهته القوائم\nعليك ثياب خاطها الله قادرا، … بها رئمتك العاطفات الروائم\nوتاجك معقود، كأنك هرمز، … يباهي به أملاكه، ويوائم\nوعينك سقط، ما خبا عند قرة، … كلمعة برق، ما لها، الدهر، شائم\nوما افتقرت يوما إلى موقد لها … إذا قربت، للموقدين، الهشائم\nورثت هدى التذكار من قبل جرهم … أوان ترقت، في السماء، النعائم\nوما زلت، للدين القديم، دعامة، … إذا قلقت، من حامليه، الدعائم\nولو كنت لي، ما أرهفت لك مدية، … ولا رام إفطارا، بأكلك، صائم\nولم يغل ماء كي تمزق حلة، … حبتك، بأسناها، العصور القدائم\nولا عمت في الخمر، التي حال طعمها … كأنك في غمر، من السيل، عائم\nولاقيت عندي الخير، تحسب عيلا … ينافيك قول سيىء، وشتائم\nفإن كتب الله الجرائم، ساخطا، … على الخلق، لم تكتب عليك الجرائم\nفهل تردن حوض الحياة، مبادرا، … إذا حلئت عنه النفوس الحوائم\nوترتع ما بين النبيئين، ناعما … بعيشة خلد، لم تنلها السمائم\nوأقوال سكان البلاد ثلاثة، … توالى عليها عاند وملائم\nفقول جزاء ما، وقول تهاون، … وآخر يجزى إنسه لا البهائم\nيضارعنا من بعدنا في أمورنا، … ونمضي على العلات، والفعل دائم\nوكل يوصي النفس، عند خلوه، … بزهد، ولكن لا تصح العزائم\nوأين فراري من زماني وأهله، … وقد غص، شرا، نجده والتهائم؟\nوفي كل شهر تصرع الدهر جنة، … فتعقد فيه بالهلال التمائم\nله عوذ في كل شرق ومغرب، … رعاها اليماني الدار والمتشائم\nأبى القلب إلا أم دفر، كما أبى … سوى أم عمرو، موجع القلب هائم\nهي المنتهى والمشتهى، ومع السهى … أماني منها، دونهن العظائم\nولم تلقنا، إلا وفينا تحاسد … عليها، وإلا في الصدور سخائم\nنزت في الحشا ثم استقلت، فغادرت … جماجم تنزو، فوقهن، الغمائم\nوأيامنا عيس، وليس أزمة … عليها، وخيل أغفلتها الشكائم\nوقد نسيت حسن العهود، ومالها … بنان يد، فيه تشد الرتائم\nفإن سكرت، فالراح فيها كثيرة، … ذوارعها والمخرزات الحتائم\nقسيمات ألوان، سميحات شيمة، … لها ضائع ما طيبته القسائم\nوما خلق البيض الحسان حميدة، … إذا اشتهرت أخلاقهن الذمائم\nوتمضي بنا الساعات، مضمرة لنا … قبيحا، على أن الوجوه وسائم\nنممن بما يخفيه حي وميت، … ومن شر أفعال الرجال النمائم\nيعيش الفتى، في عدمه، عيش راغب، … ويثري مسن، للمعيشة، سائم\nوأنوار أعوام مضين شواهد … بما ضمنته، بعدهن، الكمائم"},{"id":"diwan-maarri:1181","bookId":"diwan-maarri","type":"poem","seq":1181,"chapter":"قصائد","title":"إذا ما تبينا الأمور تكشفت","page":"","text":"إذا ما تبينا الأمور تكشفت … لنا، وأمير القوم للقوم خادم\nأقل بني الدنيا، هموما وحسرة، … فقيد غنى، للمال والرشد عادم\nوما هي إلا منزل غير طائل، … فمرتحل عنه، وآخر قادم\nتبكي على الميت الجديد لأنه … حديث، وينسى ميتك المتقادم\nولو أنني وافيتها بتخير، … لأدمى البنان العشر بالأزم نادم\nسيسليك أن القابض الرزق باسط؛ … وأن الذي شاد البنية هادم"},{"id":"diwan-maarri:1182","bookId":"diwan-maarri","type":"poem","seq":1182,"chapter":"قصائد","title":"إذا قيل غال الدهر شيئا، فإنما","page":"","text":"إذا قيل غال الدهر شيئا، فإنما … يراد إله الدهر، والدهر خادم\nومولد هذي الشمس أعياك حده، … وخبر لب أنه متقادم\nوأيسر كون تحته كل عالم، … ولا تدرك الأكوان جرد صلادم\nإذا هي مرت لم تعد، ووراءها … نظائر، والأوقات ماض وقادم\nفما آب منها، بعدما غاب، غائب، … ولا يعدم الحين المجدد عادم\nكأنك أودعت التماثيل أنفسا، … وأنت على التفريط، في ذاك، نادم\nوما آدم في مذهب العقل واحدا، … ولكنه عند القياس أوادم\nتخالفت الأغراض: ناس وذاكر، … وسال ومشتاق، وبان وهادم"},{"id":"diwan-maarri:1183","bookId":"diwan-maarri","type":"poem","seq":1183,"chapter":"قصائد","title":"تكلم بالقول الذي ليس فوقه","page":"","text":"تكلم بالقول الذي ليس فوقه … سوى كسب ذنب، وهو بالرغم صائم\nلو أنك في أهل التنسك والتقى، … لما كثرت فيما لديك الخصائم"},{"id":"diwan-maarri:1184","bookId":"diwan-maarri","type":"poem","seq":1184,"chapter":"قصائد","title":"إذا شئت، يوما، وصلة بقرينة،","page":"","text":"إذا شئت، يوما، وصلة بقرينة، … فخير نساء العالمين عقيمها\nلنا طرق، في كل شرق ومغرب، … إلى الموت، أعيا راكبا مستقيمها\nهي الدار، يأتيها من الناس قادم، … يحث على أن يستقل مقيمها"},{"id":"diwan-maarri:1185","bookId":"diwan-maarri","type":"poem","seq":1185,"chapter":"قصائد","title":"نسوم، على وجه البسيطة، مرة،","page":"","text":"نسوم، على وجه البسيطة، مرة، … فأي مراد، في الحياة، نسوم؟\nيفرق، بين الشخص والروح، حادث، … ألا إن أيام الفراق حسوم\nإلى العالم العلوي تزمع، رحلة، … نفوس، وتبقى في التراب جسوم\nوما ظعنت، إلا وللدهر صولة، … تبين على أوطانها، ووسوم\nستوحش أطلال: ديار ومعشر؛ … وتدرس، من هذي وتلك، رسوم"},{"id":"diwan-maarri:1186","bookId":"diwan-maarri","type":"poem","seq":1186,"chapter":"قصائد","title":"مضى الناس أفواجا، ونحن وراءهم،","page":"","text":"مضى الناس أفواجا، ونحن وراءهم، … وكانوا وكنا، في الضلال، نعوم\nفيا أذني! هل في الذي تسمعينه، … من القول، إلا فرية وزعوم؟\nوكم يتجنى، المين، أحمر ناطق، … تماز به، عند المذاق، طعوم\nوراحلتي نفس خؤون، كأنها، … من الضعف، شاة، في السوام، رغوم\nلجون، إذا بان الهدى لا تؤمه؛ … وإن لاح نهج الغي، فهي سعوم"},{"id":"diwan-maarri:1187","bookId":"diwan-maarri","type":"poem","seq":1187,"chapter":"قصائد","title":"كأن نفوس الناس، والله شاهد،","page":"","text":"كأن نفوس الناس، والله شاهد، … نفوس فراش، ما لهن حلوم\nوقالوا: فقيه، والفقيه مموه، … وحلف جدال، والكلام كلوم\nأتوك بأصناف المحال، وإنما … لهم غرض في أن يقال علوم\nوجدت الفتى يرمي سواه بدائه، … ويشكو إليك الظلم، وهو ظلوم\nفإن كان شيطان له يستفزه، … فأيهما، عند القياس، تلوم؟\nتجرأ، ولا تجعل، لحتفك، علة، … بإكثار طعم، إن ذلك لوم"},{"id":"diwan-maarri:1188","bookId":"diwan-maarri","type":"poem","seq":1188,"chapter":"قصائد","title":"رأيتك، في لج من البحر، سابحا،","page":"","text":"رأيتك، في لج من البحر، سابحا، … تلوم بني الدنيا، وأنت مليم\nيقول الحجى: هل لي إذا مت راحة، … فإن عذابي، في الحياة، أليم\nوأجسامنا مثل الديار لأنفس … جوائر، منها جاهل وحليم\nفإما انهدام قبل رحلة ظاعن؛ … وإما رحيل، والمحل سليم"},{"id":"diwan-maarri:1189","bookId":"diwan-maarri","type":"poem","seq":1189,"chapter":"قصائد","title":"الموت نوم طويل، لا هبوب له،","page":"","text":"الموت نوم طويل، لا هبوب له، … والنوم موت قصير، بعثه أمم\nوفي الخمول حمام، والفتى قبل، … وفي النباهة عيش، والفتى رمم\nتخالف الشكل: عصم في جماجمها … أرواقها، ونعام ما لها لمم\nوحية تسمع الأصوات، ظالمة … من وصفها، وظليم شأنه الصمم\nلا يخدعنك، أخرانا كأولنا، … في نحو ما نحن فيه، كانت الأمم\nمقلدين بذم لا يضيعه … منهم عريب، ولكن ضاعت الذمم\nأجيد قلبك لما جادهم مطر، … أم فاض همك، لما غاضت الهمم؟\nلا تشمخ الأنف الشم، التي رزقت … ما لا يدوم، فما يبقى لها الشمم\nلولا بدائع دلت أن خالقنا … أدرى وأحكم، قلنا: خلقنا لمم"},{"id":"diwan-maarri:1190","bookId":"diwan-maarri","type":"poem","seq":1190,"chapter":"قصائد","title":"لا تسدين قبيحا، إن هممت به،","page":"","text":"لا تسدين قبيحا، إن هممت به، … وافعل جميلا، فإن الخير يغتنم\nإن فارقتني حياتي خلتني صنما، … ولا يراع لكسر الهامة الصنم\nفاجعل عظامي قرى غبراء مظلمة، … أو قوت حمراء نار، ضوءها سنم\nسوى على الجسم خضر، حوتها جشع … بعد الممات، وخضر زرقها تنم\nقطع البنان الذي شبهته عنما، … إن مات، كالقطع في قضب هي العنم\nوالغانيات، وفي آذانها درر، … كالضأن ترعى، وفي آذانها زنم"},{"id":"diwan-maarri:1191","bookId":"diwan-maarri","type":"poem","seq":1191,"chapter":"قصائد","title":"يكفيك، أدما، سليط ما أريق له","page":"","text":"يكفيك، أدما، سليط ما أريق له … دم، ولا مس روحا، إذ جرى ألم\nله فضائل منها فقد كلفته، … وأنه بسناه تنجلي الظلم\nقالوا: تقسم مقتول على حنق؛ … فقلت: سيان كلم الميت والكلم\nإن ودعوه، فما يدري بما صنعوا؛ … أو قطعوه، فما ينتابه ألم\nورب أزهر يلقى هامه هدرا، … كما يقط، لأدنى علة، قلم"},{"id":"diwan-maarri:1192","bookId":"diwan-maarri","type":"poem","seq":1192,"chapter":"قصائد","title":"إن اليهودي خلى جهله امرأة،","page":"","text":"إن اليهودي خلى جهله امرأة، … كانت عقيما، وخير النسوة العقم\nماذا أراد، لحاه الله، من ولد، … يلقى، من الدهر، ما يردي وما يقم؟\nأما تحاول، إن طالت تجاربها، … برءا من السقم، هذي الأنفس السقم\nمثل البهائم، غرتها سلامتها؛ … والله يمهل حينا ثم ينتقم"},{"id":"diwan-maarri:1193","bookId":"diwan-maarri","type":"poem","seq":1193,"chapter":"قصائد","title":"الجل مود، ولا جلمود يتركه","page":"","text":"الجل مود، ولا جلمود يتركه … ريب الزمان، فأنى يخلد القزم؟\nشدت عليهم مناياهم توسطهم، … كالخيل شدت على أوساطها الحزم\nلا تسألوا الناس، واغدوا آكلي مقر؛ … إن النفوس، على إمساكها، عزم\nلعل أرباب أيد، للندى، بسطت، … يوم الحساب، على أيديهم أزم\nلا ورد لي ، والمطايا في خزائمها، … وكل صاحب سن، حبله خزم\nما لي أرى حزماء الناس في شرق، … كأنما الحزم، في أحشائهم، حزم؟\nيا نسوة الحي! إن كنتن أظبية، … فكلكن يصيد الخادر الرزم\nكثير أنا في حرفي، أهبت له … في التاء، يلزم حرفا ليس يلتزم\nوالمرء يرفع أفعالا، فتخفضه، … حتى إذا مات أضحى، وهو منجزم"},{"id":"diwan-maarri:1194","bookId":"diwan-maarri","type":"poem","seq":1194,"chapter":"قصائد","title":"هل ألهمت يثرب، يوما مثربها","page":"","text":"هل ألهمت يثرب، يوما مثربها … أن ليس يخلد، من آطامها، أطم؟\nكانت تضم رجالا، تحت أعينهم … معاطس، لم تذلل عزها الخطم\nأيد، إذا بسطوها للعلا وصلوا؛ … وأوجه لا تغادي مثلها اللطم\nوأرضع المجد أطفالا، وأملهم … دهر، فماتوا أولي شيب، وما فطموا\nضراغم كالقطاميات، ليس لها، … إلى أكيل، سوى أعدائها، قطم\nوالناس مثل سوام، لا حلوم لهم، … يسوقه للمنايا سائق حطم"},{"id":"diwan-maarri:1195","bookId":"diwan-maarri","type":"poem","seq":1195,"chapter":"قصائد","title":"المرء كالنار تبدو عند مسقطها","page":"","text":"المرء كالنار تبدو عند مسقطها … صغيرة، ثم تخبو حين تحتدم\nوالناس بالناس من حضر وبادية، … بعض لبعض، وإن لم يشعروا، خدم\nوكل عضو لأمر ما يمارسه، … لا مشي للكف بل تمشي بك القدم\nوعالم ظل فيه القول مختلفا، … ومحدث هو من رب له القدم\nفاذخر لنفسك خيرا كي تسر به، … فإن فعلت، وإلا عادك الندم"},{"id":"diwan-maarri:1196","bookId":"diwan-maarri","type":"poem","seq":1196,"chapter":"قصائد","title":"لو يتركون وهذا اللب ما قبلوا","page":"","text":"لو يتركون وهذا اللب ما قبلوا … مينا يقال، ولكن شالت الجذم\nأتوهم بأحاديث، وقيل لهم: … قولوا صدقنا، وإلا أروي الخذم\nوأرهبتهم جفون، ملؤها نوب؛ … وأرغبتهم جفان، للندى، رذم"},{"id":"diwan-maarri:1197","bookId":"diwan-maarri","type":"poem","seq":1197,"chapter":"قصائد","title":"الناس، إن لم تنبههم قيامتهم،","page":"","text":"الناس، إن لم تنبههم قيامتهم، … أو نبهوا، فتراب ما لهم قيم\nيؤمل القوم، عندي، شيمة حسنت، … وشيمة الدهر أن لا تحسن الشيم\nما زال يبخل، حتى ما يصوب حيا، … فهل تعلم بخل العالم الديم؟"},{"id":"diwan-maarri:1198","bookId":"diwan-maarri","type":"poem","seq":1198,"chapter":"قصائد","title":"يقال: أن سوف يأتي، بعدنا، عصر","page":"","text":"يقال: أن سوف يأتي، بعدنا، عصر … يرضى، فتضبط أسد الغابة الخطم\nهيهات هيهات، هذا منطق كذب، … في كل صقر زمان كائن قطم\nما دام، في الفلك، المريخ، أو زحل، … فلا يزال عباب الشر يلتطم\nوإن تغيرت الأفلاك، وانعكست … بالسعد، فالوهد يبنى فوقه الأطم\nهب الفتى نال أقصى ما يؤمله، … أليس راعي المنايا، خلفه، حطم؟"},{"id":"diwan-maarri:1199","bookId":"diwan-maarri","type":"poem","seq":1199,"chapter":"قصائد","title":"هل تمسك، الماء لي، مزادي،","page":"","text":"هل تمسك، الماء لي، مزادي، … من بعد ما فري الأديم؟\nتمادت الكأس بالندامى، … وحق أن يندم النديم\nما في بني آدم غني، … بل كلهم مقتر عديم\nيغنى الذي ما له فناء، … وذلك الواحد القديم"},{"id":"diwan-maarri:1200","bookId":"diwan-maarri","type":"poem","seq":1200,"chapter":"قصائد","title":"مصائب هذه الدنيا كثير،","page":"","text":"مصائب هذه الدنيا كثير، … وأيسرها على الفطن الحمام\nمصاب، لا تنزه عنه نفس، … ولا يقضى، بمدفعه، الذمام"},{"id":"diwan-maarri:1201","bookId":"diwan-maarri","type":"poem","seq":1201,"chapter":"قصائد","title":"وجدت الشر ينفع كل حين،","page":"","text":"وجدت الشر ينفع كل حين، … ومن نفع به حمل الحسام\nوليس الخير في وسع الليالي، … فكيف نسومها ما لا يسام؟\nوفي الحيوان شرك بين أرض … وجو، سوف يدركه انقسام\nفراق الروح هذا الجسم، فيه، … على نوعيهما، نعم جسام\nوما نأت القرابة من رجال، … أبوهم يافث، وأبوك سام"},{"id":"diwan-maarri:1202","bookId":"diwan-maarri","type":"poem","seq":1202,"chapter":"قصائد","title":"إذا لؤم الفتى لم يخش مما","page":"","text":"إذا لؤم الفتى لم يخش مما … يقال، وإن ترادفه الملام\nوما كانت كلام السيف، يوما، … لتبلغ مثل ما بلغ الكلام\nتحارب أنفس وتسر، حتى … يظن الصلح فيها والسلام\nوبين جوانح الأقوام نار، … يوري، عن تلهبها، السلام\nوبعد الخير ناقضه، وأعيا … نهار ليس يعقبه ظلام\nأنوء مع الخطوب إلى أمور، … لشخصي، دون موقعها، اصطلام\nويجري سابحي، وله عيوب؛ … ويقطع صارم، وبه انثلام\nويصبح، في الحجى، التشريق رزءا، … وأنى يبهج الركن استلام؟\nوبعض حواصل الأسماء دلت، … على تعريفه، ألف ولام"},{"id":"diwan-maarri:1203","bookId":"diwan-maarri","type":"poem","seq":1203,"chapter":"قصائد","title":"فوارس خيلكم تعطى مناها،","page":"","text":"فوارس خيلكم تعطى مناها، … إذا دمى نواجذها الشكيم\nوفي بيض السيوف بياض عيش، … بذلك، فاعلموا، نطق الحكيم"},{"id":"diwan-maarri:1204","bookId":"diwan-maarri","type":"poem","seq":1204,"chapter":"قصائد","title":"لو كان لي أمر يطاوع لم يشن","page":"","text":"لو كان لي أمر يطاوع لم يشن … ظهر الطريق، يد الحياة، منجم\nأعمى بخيل، أو بصير فاجر، … نوء الضلال به مرب مثجم\nيغدو بزخرفة يحاول مكسبا، … فيدير أسطرلابه ويرجم\nوقفت به الورهاء، وهي كأنها، … عن الوقوف، على عرين تهجم\nسألته عن زوج لها متغيب، … فاهتاج يكتب بالرقان ويعجم\nويقول: ما اسمك واسم أمك؟ إنني … بالظن، عما في الغيوب، مترجم\nيولي بأن الجن تطرق بيته، … وله يدين فصيحها والأعجم\nوالمرء يكدح في البلاد، وعرسه … في المصر تأكل من طعام يوجم\nأفما يكر على معيشته الفتى، … إلا بما نبذت إليه الأنجم؟\nرجم التنائف بالركاب أعز من … كسب يحق لربه لو يرجم\nآه لأسرار الفؤاد غواليا، … في الصدر أستر دونها، وأجمجم\nعجبا لكاذب معشر لا ينثني، … غب العقوبة، وهو أخرس أضجم\nكيف التخلص، والبسيطة لجة، … والجو غيم، بالنوائب، يسجم؟\nفسد الزمان، فلا رشاد ناجم … بين الأنام، ولا ضلال منجم\nأسرج وألجم للفرار، فكلهم، … فيما يسوءك، مسرج أو ملجم\nوالخير أزهر، ما إليه مسارع، … والشر أكدر، ليس عنه محجم\nضحكوا إليك، وقد أتيت بباطل، … ومتى صدقت، فهم غضاب رجم\nيحميك منهم أن تمر عليهم، … فإذا حلوت، عدت عليك العجم"},{"id":"diwan-maarri:1205","bookId":"diwan-maarri","type":"poem","seq":1205,"chapter":"قصائد","title":"العالم العالي، برأي معاشر،","page":"","text":"العالم العالي، برأي معاشر، … كالعالم الهاوي، يحس ويعلم\nزعمت رجال: أن سياراته … تسق العقول، وأنها تتكلم\nفهل الكواكب مثلنا في دينها، … لا يتفقن، فهائد أو مسلم؟\nولعل مكة في السماء كمكة، … وبها نضاد ويذبل ويلملم\nوالنور، في حكم الخواطر، محدث، … والأولي هو الزمان المظلم\nوالخير، بين الناس، رسم داثر، … والشر نهج، والبرية معلم\nطبع خلقت عليه ليس بزائل، … طول الحياة، وآخر متعلم\nإن جارت الأمراء جاء مؤمر … أعتى وأجور، يستضيم ويكلم\nكحمائم ظلمت، فنادى أجدل: … إن كنت ظالمة، فإني أظلم\nأرأيت أظفار الضراغم عودت … فرة، وأظفار الأنيس تقلم؟\nوكذاك حكم الدهر في سكانه، … عير له أذن، وهيق أصلم\nإن شئت أن تكفى الحمام فلا تعش … هذي الحياة إلى المنية سلم\nماذا أفدت بأن دهرك خافض، … وغناك منبسط، وعرسك غيلم؟\nأحسن بدنيا القوم، لو كان الفتى … لا يقتضى، وأديمه لا يحلم\nوكأنما الأخرى تيقظ نائم؛ … وكأنما الأولى منام يحلم\nيتشبه الطاغي بطاغ مثله، … وأخو السعادة بينهم من يسلم\nفي الناس ذو حلم يسفه نفسه … كيما يهاب، وجاهل يتحلم\nوكلاهما تعب، يحارب شيمة … غلبت، فآض، بحربها، يتألم\nفالزم ذراك، وإن تشعث جدره، … فالعس قد يرويك، وهو مثلم"},{"id":"diwan-maarri:1206","bookId":"diwan-maarri","type":"poem","seq":1206,"chapter":"قصائد","title":"دهر يمر كما ترى، فأهلة","page":"","text":"دهر يمر كما ترى، فأهلة … تنمي لتكمل، أو بدور تسقم\nوتحب أن يثنى عليك بأنك ال … بر التقي، وأنت صل أرقم\nوشهادة لك أن خلقك يجتنى … ليصاب شهدا، وهو صاب علقم\nتجني، فتنقم ما كرهت، وكل ما … تجنيه تحسب أنه لا ينقم"},{"id":"diwan-maarri:1207","bookId":"diwan-maarri","type":"poem","seq":1207,"chapter":"قصائد","title":"كل تسير به الحياة، وما له","page":"","text":"كل تسير به الحياة، وما له … علم على أي المنازل يقدم\nومن العجائب أننا بجهالة … نبني، وكل بناء قوم يهدم\nوالمرء يسخط، ثم يرضى بالذي … يقضى، ويوجده الزمان ويعدم\nويلذ أطعمة البقاء، وخيرها، … كالسم، يخلط بالحمام ويؤدم\nوالدهر يقدم عن ترادف أعصر، … فيغيب أعصر في الخطوب ويقدم\nذكر القريض ربيعة بن مكدم، … ولينسين ربيعة ومكدم\nونروم دنيانا، وما كلف بها … إلا الفنيق يظل، وهو مسدم\nهويت، وقد خدمت، ولم تر خدمة، … وتعرضت لك، إذ أهينت، تخدم\nوأضيع أوقاتي بغير ندامة، … ويفوتني الشيء اليسير فأندم\nمنع الفتى هينا، فجر عظائما، … وحمى نمير الماء، فانبعث الدم\nوجديد عيشتنا الشباب، فإن مضى، … فقميصنا خلق اللباس مردم\nوالجسم ظرف نوائب، وكأنه … ظرف يؤخر، تارة، ويقدم"},{"id":"diwan-maarri:1208","bookId":"diwan-maarri","type":"poem","seq":1208,"chapter":"قصائد","title":"دنياك أشبهت المدامة: ظاهر","page":"","text":"دنياك أشبهت المدامة: ظاهر … حسن، وباطن أمرها ما تعلم\nوالدهر يصمت غير أن خطوبة … ترجمن، حتى خلته يتكلم\nأنفق لترزق، فالثراء الظفر إن … يترك يشن، ويعود حين يقلم"},{"id":"diwan-maarri:1209","bookId":"diwan-maarri","type":"poem","seq":1209,"chapter":"قصائد","title":"آناء ليلك والنهار، كلاهما،","page":"","text":"آناء ليلك والنهار، كلاهما، … مثل الإناء، من الحوادث، مفعم\nوإذا الفتى كره الغواني واتقى … مرضا يعود وضره ما يطعم\nفقد انطوت عنه الحياة، وكاذب … من قال عنه: يبيت، وهو منعم\nركب الزمان إلى الحمام برغمه، … ورأى المنية ليس فيها مرغم"},{"id":"diwan-maarri:1210","bookId":"diwan-maarri","type":"poem","seq":1210,"chapter":"قصائد","title":"وعظ الزمان، فما فهمت عظاته،","page":"","text":"وعظ الزمان، فما فهمت عظاته، … وكأنه، في صمته، يتكلم\nلو حاورتك الضأن قال حصيفها: … الذئب يظلم، وابن آدم أظلم\nأطردت عنا فارسا ذا رجلة، … ساقته حاجته وليل مظلم\nويزيده عذرا، لدينا، أنه … سدران، ليس بعالم ما تعلم\nتهوى سلامتنا وترعى سرحنا … وحراب ضار من حرابك أسلم\nأظفارك استعلت إلى أظفاره … بأسا، وتلك وقت وهذي تقلم\nلو كان غصنا، في المنابت، ناضرا، … لألم يذبل يذبل ويلملم\nصبرا على دنياك ينقض حينها، … فكأنها حلم بنوم يحلم\nولربما قضت الأناة مآربا … من نازح، ولكل عال سلم\nوالناس شتى من حلوم: مظهرا … جهلا يعر، وجاهل يتحلم\nفارقت فاستعلت همومك والمدى … يأسو، بطول مروره، ما يكلم\nوإذا يد قطعت، فإن عشيرها، … لو حرقت بالنار، لا يتألم"},{"id":"diwan-maarri:1211","bookId":"diwan-maarri","type":"poem","seq":1211,"chapter":"قصائد","title":"لفعالك المذموم ريح حوابس،","page":"","text":"لفعالك المذموم ريح حوابس، … ولفعلك المحمود ريا تفغم\nوالطبع أحكمه المليك، فلن ترى … حجرا يقول، ولا هزبرا يبغم\nوإذا غدوت على القضاء مغالبا، … فأذاك تستمري، وأنفك ترغم\nأيكون رفع للشرور، فينتهي … غاو، ويقنع، بالنبات، الضيغم؟\nوالموت أصدق حادث وأصحه، … وكأنه كذب يسر فينغم"},{"id":"diwan-maarri:1212","bookId":"diwan-maarri","type":"poem","seq":1212,"chapter":"قصائد","title":"العقل يخبر أنني في لجة","page":"","text":"العقل يخبر أنني في لجة … من باطل، وكذاك هذا العالم\nمثل الحجارة، في العظات، قلوبنا، … أو كالحديد، فليتنا لا نألم"},{"id":"diwan-maarri:1213","bookId":"diwan-maarri","type":"poem","seq":1213,"chapter":"قصائد","title":"لم تلق في الأيام إلا صاحبا","page":"","text":"لم تلق في الأيام إلا صاحبا … تأذى به، طول الحياة، وتألم\nويعد كونك، في الزمان، بلية، … فاصبر لها، فكذاك هذا العالم"},{"id":"diwan-maarri:1214","bookId":"diwan-maarri","type":"poem","seq":1214,"chapter":"قصائد","title":"الشهب، عظمها المليك ونصها","page":"","text":"الشهب، عظمها المليك ونصها … للعالمين، فواجب إعظامها\nوأرى الحياة، وإن لهجت بحبها، … كالسلك، طوقك الأذاة نظامها"},{"id":"diwan-maarri:1215","bookId":"diwan-maarri","type":"poem","seq":1215,"chapter":"قصائد","title":"عميانكم قرأت على أجداثكم،","page":"","text":"عميانكم قرأت على أجداثكم، … وأتوا لكم بالبر من آتاكم\nأحياؤكم بخلت عليهم بالندى، … فبغوه بالفرقان من موتاكم\nكم توعظون فلا تلين قلوبكم، … فتبارك الخلاق ما أعتاكم\nلا تأذنون إلى النهاة، مصيفكم، … وتجانبون البر في مشتاكم\nإن الضلالة كالغريزة فيكم، … يأوي إليها كهلكم وفتاكم"},{"id":"diwan-maarri:1216","bookId":"diwan-maarri","type":"poem","seq":1216,"chapter":"قصائد","title":"أسرار نفسك في البلاد، كأنها","page":"","text":"أسرار نفسك في البلاد، كأنها … أسرار وجهك ما عليه لثام\nوظهور تلك أباحه لك ربها؛ … وظهور هذي هتكة وأثام"},{"id":"diwan-maarri:1217","bookId":"diwan-maarri","type":"poem","seq":1217,"chapter":"قصائد","title":"دمع، على ما يفوت، منسكب؛","page":"","text":"دمع، على ما يفوت، منسكب؛ … ما الكأس من همتي ولا الجام\nنحن ذئاب ضراؤنا مدد، … لا أسد، والثياب آجام\nوالناس شتى، جرى بهم قدر، … إذا طغى لم يعقه إلجام\nوعالمي في سفاهة وخنا … عالمه، بالظنون، رجام\nقد كتب الله للردى صحفا، … وبان نقط لها وإعجام\nفيا سحاب المنون! سلت بنا، … هل لك، أخرى الزمان، إنجام؟\nتواصلت منك، بيننا، ديم، … وزيد فيها سح وإثجام\nكم أسود من أمامه حجب، … عليه ضيف الأذاة هجام\nوأحجم القرن عن فوارسه، … وما لريب المنون إحجام\nتلك بلاد النبات ما سقيت، … والغيم فوق الرمال سجام"},{"id":"diwan-maarri:1218","bookId":"diwan-maarri","type":"poem","seq":1218,"chapter":"قصائد","title":"توق النساء على عفة،","page":"","text":"توق النساء على عفة، … ليجزيك الواحد القيم\nفأبكارهن ابتكار البلا، … وأيمهن هي الأيم"},{"id":"diwan-maarri:1219","bookId":"diwan-maarri","type":"poem","seq":1219,"chapter":"قصائد","title":"أعاذل! إن ظلمتنا الملوك،","page":"","text":"أعاذل! إن ظلمتنا الملوك، … فنحن، على ضعفنا، أظلم\nتوسط بنا سائرات الرفاق، … لعل ركائبنا تسلم\nألم تر للشعر، وهو الكلا … م، يبقى على الدهر لا يكلم\nآخر أوتاده موبق … بقطع، وأولها يثلم\nفلا تسرعن، فإن السري … ع يوقف حقا، كما تعلم\nفإن قلت: ثانيه لا وقف في … ه؛ قلنا: وثالثه أصلم\nفلا تغبطن ذوي نعمة، … فخلفهم وقعة صيلم\nتسامت قريش إلى ما علم … ت، واستأثر الترك والديلم\nوهل ينكر العقل أن يستب … د، بالملك، غانية غيلم؟\nوما ظفر الملك في جيشه، … سوى ظفر بالردى يقلم"},{"id":"diwan-maarri:1220","bookId":"diwan-maarri","type":"poem","seq":1220,"chapter":"قصائد","title":"أنا الجائر الظالم،","page":"","text":"أنا الجائر الظالم، … ومولاي بي عالم\nفيا لك من يقظة، … كأني بها حالم"},{"id":"diwan-maarri:1221","bookId":"diwan-maarri","type":"poem","seq":1221,"chapter":"قصائد","title":"توار بجنح الظلا","page":"","text":"توار بجنح الظلا … م، قد ظلم العالم\nأولاك قرون الصلا … ل، إن يؤذنوا آلموا\nهلال، إذا حاربوا، … ونقد، إذا سالموا"},{"id":"diwan-maarri:1222","bookId":"diwan-maarri","type":"poem","seq":1222,"chapter":"قصائد","title":"تصدق على الأعمى بأخذ يمينه،","page":"","text":"تصدق على الأعمى بأخذ يمينه، … لتهديه، وامنن بإفهامك الصما\nوإنشادك العود، الذي ضل، نعيه … عليك، فما بال امرىء حيثما أما؟\nوأعط أباك النصف حيا وميتا، … وفضل عليه من كرامتها الأما\nأقلك خفا، إذ أقلتك مثقلا، … وأرضعت الحولين، واحتملت تما\nوألقتك عن جهد، وألقاك لذة، … وضمت وشمت مثلما ضم أو شما\nوأحمد سماني كبيري، وقلما … فعلت سوى ما أستحق به الذما\nتلم الليالي شأن قوم، وإن عفوا … زمانا، فإن الأرض تأكلهم لما\nيموتون بالحمى، وغرقى، وفي الوغى، … وشتى منايا، صادفت قدرا حما\nوسهل على نفسي، التي رمت حزنها، … مبيت سهيل للركائب مؤتما\nوما أنا بالمحزون للدار أوحشت؛ … ولا آسف إثر المطي إذا زما\nفإن شئتم، فارموا سهوبا رحيبة؛ … وإن شئتم، فاعلوا مناكبها الشما\nوزاك تردى بالطيالس وادعى، … كذمر تردى بالصوارم واعتما\nولم يكف هذا الدهر ما حمل الفتى … من الثقل، حتى رده يحمل الهما\nولو كان عقل النفس، في الجسم، كاملا، … لما أضمرت، فيما يلم بها، غما\nولي أمل قد شبت، وهو مصاحبي، … وساودني قبل السواد، وما هما\nمتى يولك المرء الغريب نصيحة، … فلا تقصه، واحب الرفيق، وإن ذما\nولا تك ممن قرب العبد شارخا، … وضيعه إذا صار، من كبر، هما\nفنعم الدفين الليل، إن بات كاتما … هواك، وبعدا للصباح، إذا نما\nنهيتك عن سهم الأذى ريش بالخنى، … ونصله غيظ، فأرهف أو سما\nفأرسلته يستنهض الماء سائحا، … وقد غاض، أو يستنضب البحر إذ طما\nيغادر ظمأ في الحشا غير نافع، … ولو غاض عذبا، في جوانحه، اليما\nوقد يشبه الإنسان جاء لرشده … بعيدا، ويعدو شبهه الخال والعما\nولست أرى في مولد حكم قائف، … وكم من نواة أنبتت سحقا عما\nرميت بنزر من معائب، صادقا، … جزاك بها أربابها كذبا جما\nضمنت فؤادي للمعاشر كلهم، … وأمسكت لما عظموا الغار، أو خما"},{"id":"diwan-maarri:1223","bookId":"diwan-maarri","type":"poem","seq":1223,"chapter":"قصائد","title":"غرائز لما ألفت جمعت ردى،","page":"","text":"غرائز لما ألفت جمعت ردى، … وهل يجد الخلم الذي يحفظ الخلما؟\nفليت الفتى كالترب، لا يألم الأذى، … وكالماء في الهيجاء، لا يأنف الكلما\nولولا حياة في يدي خلت أنملي … كأقلام بار، غير منكرة قلما\nوما سفت الريح الرغام جهالة، … ولا ركدت قدس وأترابها حلما\nرأيت سجايا الناس فيها تظالم، … ولا ريب في عدل الذي خلق الظلما\nإذا علمي الأشياء جر مضرة … إلي، فإن الجهل أن أطلب العلما\nوما رضيت رضوى من الدهر حكمه، … وإن كان سلمى غير مرزوقة سلما\nعفا الله عن صافي الحجى متنبه، … يرى خفضه بؤسى ويقظته حلما\nفما روضه مرعى، ولا يسره غنى، … ولا صبحه أضحى، ولا ليله ألمى"},{"id":"diwan-maarri:1224","bookId":"diwan-maarri","type":"poem","seq":1224,"chapter":"قصائد","title":"إذا سخطت روح الفتى، فليقل لها:","page":"","text":"إذا سخطت روح الفتى، فليقل لها: … لعمرك ما وفقت أن تسكني الجسما\nفإن هي قالت: ما علمت، فربها، … من الموت، يعطيها لأدوائها حسما"},{"id":"diwan-maarri:1225","bookId":"diwan-maarri","type":"poem","seq":1225,"chapter":"قصائد","title":"إذا مر أعمى، فارحموه وأيقنوا،","page":"","text":"إذا مر أعمى، فارحموه وأيقنوا، … وإن لم تكفوا، أن كلكم أعمى\nوما زال نعم الرأي لي أن منزلي، … كأني فيه مضمر كن في نعما\nغدوت ابن وقتي، ما تقضى نسيته، … وما هو آت لا أحس له طعما\nوقال أناس: ما لأمر حقيقة؛ … فهل أثبتوا أن لا شقاء ولا نعمى؟\nوشكك في الإيجاب والنفي معشر … حيارى، جرت خيل الضلال بهم سعما\nفنحن وهم في مزعم وتشاجر، … ويعلم رب الناس أكذبنا زعما"},{"id":"diwan-maarri:1226","bookId":"diwan-maarri","type":"poem","seq":1226,"chapter":"قصائد","title":"إذا ألف الشيء استهان به الفتى،","page":"","text":"إذا ألف الشيء استهان به الفتى، … فلم يره بؤسى، يعد، ولا نعمى\nكإنفاقه من عمره ومساغه … من الريق عذبا لا يحس له طعما\nوما ارتاب في لقيا الردى، وكأنه … حديث أتى من كاذب يبطل الزعما"},{"id":"diwan-maarri:1227","bookId":"diwan-maarri","type":"poem","seq":1227,"chapter":"قصائد","title":"يحاول طينا أرمنيا، لعله","page":"","text":"يحاول طينا أرمنيا، لعله … يدافع عن حوبائه قدرا حما\nله أجل، إن حان لم تثنه الرقى؛ … وإن لم يحن لم يخش من شربه السما"},{"id":"diwan-maarri:1228","bookId":"diwan-maarri","type":"poem","seq":1228,"chapter":"قصائد","title":"هياما يصير الجسم في هامد الثرى،","page":"","text":"هياما يصير الجسم في هامد الثرى، … فما بالكم بالآل يخدع هياما؟\nأروام أمر لا يصح جهلتم، … كأنكم لستم عن الأرض رياما\nوكم شيم، في غمد من الترب، صارم … وكان لبرق الغيث والغمد شياما\nوهتكت الأقدار، بعد صيانة، … أيامى نساء ما تخوفن أياما\nوعام أناس في بحار من الردى، … وأمسوا إلى نزر من الرسل عياما\nبنيتم على الأمر القبيح خيامكم، … وألفيتم عن صالح الفعل خياما\nفيا ما أضل الناس عن سبل الهدى، … وللدهر لم يترك إياما ولا ياما"},{"id":"diwan-maarri:1229","bookId":"diwan-maarri","type":"poem","seq":1229,"chapter":"قصائد","title":"أراك زنيما، إن تعرضت ليلة","page":"","text":"أراك زنيما، إن تعرضت ليلة … لأدم رماح، أو لغزلان أزنما\nغنائم قوم سوف ينهبها الردى، … فلا تدن منها، واجعل النسك مغنما\nيزنمن، بالدر الثمين، مسامعا، … ويزجرن، للبين، السوام المزنما\nولما تناءت بلدة عنمية، … من الغور، أبدين البنان المعنما\nيرين، على ما ليس يمكن قدرة، … ويعملن، في كيد الفوارس، هنما\nلدى سمرات الحي غادرن سامرا، … وخيمن، للنوم، الرفيع المنمنما\nجنان ورضوان الذي هو مالك … لها عنك ينفي مالكا وجهنما\nحلمن، وجن الحلي من فرط لهجة، … فوسوس، من تحت الثياب، وهينما\nوقد صمتت أحجالها عن ترنم، … وأعيى غريقا، كظ، أن يترنما\nفلا تبك جملا، إن رأيت جمالها … تسنمن، من رمل الغضا، ما تسنما"},{"id":"diwan-maarri:1230","bookId":"diwan-maarri","type":"poem","seq":1230,"chapter":"قصائد","title":"أعكرم! إن غنيت ألفيت نادبا،","page":"","text":"أعكرم! إن غنيت ألفيت نادبا، … فلا تتغني، في الأصائل، عكرما\nبنظم شجا، في الجاهلية، أهلها، … وراق، مع البعث، الحنيف المخضرما\nوقد هاج، في الإسلام، كل مولد، … وأطرب ذا نسك وآخر مجرما\nلك النصح مني، لا أغاديك خاتلا … بمكر، ولكني أغاديك مكرما\nإذا ما حذرت الصقر يوما فحاذري … أخا الإنس أياما، وإن كان محرما\nيصوغ لك الغاوي، قلادة هالك … من الدم، تخبي وجدك المتضرما\nوكم سحقت كفاه مثلك في ضحا … شبيبتها، إذ لم تر الدهر مهرما\nوراع، بقهر، من جناحك آمنا، … فظل، على الريش، النهوض محرما\nوقد يبرم الحين القضاء بناشىء، … يراوح خيطا، شده بك، مبرما\nكما قيد السلطان حلف جناية … ليقتص منه، أو ليغرم مغرما\nفزوري وبار القفر من كل وابر، … وإلا فرومي خلف ذلك مخرما\nبحيث توافين الصحابي معوزا … من الناس، والماء السحابي خضرما\nوحلي بقاف، إن أطقت بلوغه، … فأفني لديه عمرك المتصرما"},{"id":"diwan-maarri:1231","bookId":"diwan-maarri","type":"poem","seq":1231,"chapter":"قصائد","title":"لقد بكرت في خفها وإزارها،","page":"","text":"لقد بكرت في خفها وإزارها، … لتسأل بالأمر الضرير المنجما\nوما عنده علم، فيخبرها به؛ … ولا هو من أهل الحجا فيرجما\nيقول غدا، أو بعده، وقع ديمة، … يكون غياثا أن تجود وتسجما\nويوهم جهال المحلة أنه … يظل، لأسرار الغيوب، مترجما\nولو سألوه بالذي فوق صدره … لجاء بمين، أو أرم وجمجما\nكأن سحابا عمهم بضلالة، … فليس إلى يوم القيامة منجما\nإذا قال أهل اللب حان انسفاره، … تداركه غيم سواه، فأنجما\nفإن كنت قد وفقت فانج بوحدة، … وخل البرايا من فصيح وأعجما\nولا تك فيما يكره القوم ساعيا، … ولا مسرجا في نصر غيرك، ملجما"},{"id":"diwan-maarri:1232","bookId":"diwan-maarri","type":"poem","seq":1232,"chapter":"قصائد","title":"لو كان يدري أويس ما جنت يده","page":"","text":"لو كان يدري أويس ما جنت يده … لاختار، دون مغار الثلة، العدما\nفإن من أقبح الأشياء يفعله … شاكي المجاعة، يوما، أن يريق دما\nيا أوس! هيهات كم قابلت هاجرة، … أذكت عليك وقود الحر، فاحتدما\nوكم طرقت عتودا بين أعنزة، … يوما، ففريت من أحشائه الأدما\nمطردا بت لم تبن الخيام ضحى، … ولا تراع، إذا ما بيتك انهدما\nوما كسوت، إذا قر أتى، جسدا؛ … ولا حذوت، حذارا للوجى، قدما\nجمعت في كل ري سلة وردى … نفس، فهلا سرقت القرص والحدما\nقد يقصر النفس، إعظاما لبارئه، … على القفار، منيب طالما ائتدما\nولا تصوم لوجه الله محتسبا، … أم غير صومك أمسى الهم والسدما\nأتضمر التوب من ضأن تروعها، … أم كان ذلك داء فيكم قدما؟\nولو ظفرت، على حال، بحالية، … جزأتها ونبذت السور والخدما\nوهل ندمت على طفل فجعت به … أما، ومثلك لا يستشعر الندما\nولا يوارى، إذا حلت منيته، … ولا إذا مات في غار له ردما\nوكم ثوى لك جد ما درى فطن، … منكم على أي أمر، إذ مضى، قدما"},{"id":"diwan-maarri:1233","bookId":"diwan-maarri","type":"poem","seq":1233,"chapter":"قصائد","title":"يدعو الغراب أناس حاتما سفها","page":"","text":"يدعو الغراب أناس حاتما سفها … لأنه بفراق عندهم حتما\nهذا التكذب ، ما للجون معرفة، … ولا يبالي أنال المدح أم شتما\nالسيد البر من لا يستجيز أذى … ولا يبوح بسر، عنده، كتما\nالغامر، الطارق المحتاج نائله، … أو ابن مرية من أماته يتما\nلا يرفع الصوت بالقول الهراء ضحى … ولا يدب إلى جاراته عتما\nوالعمر كالذابل الخطي، قد بسطت … له كعوب، ولكن بالردى ختما"},{"id":"diwan-maarri:1234","bookId":"diwan-maarri","type":"poem","seq":1234,"chapter":"قصائد","title":"جاران: شاك ومسرور بحالته،","page":"","text":"جاران: شاك ومسرور بحالته، … كالغيث يبكي، وفيه بارق بسما\nمال الدفين أتى الوراث، فاقتسموا، … ولم يراعوه في ثلث له قسما\nلا أطعموا منه مسكينا، ولا بذلوا … عرفا، ولا كفروا، في حنثه، قسما\nأوصى فلم يقبلوا منه، وعاهدهم، … فقابلوا بخلاف كل ما رسما\nوالعيش داء، وموت المرء عافية، … إن داؤه، بتواري شخصه، حسما\nأنفاسه كخطاه، والبقاء له … مسافة، فهو يفنى كلما انتسما\nمنازل الأنفس الأجساد، يظعنها … وفد الحمام، فكم من منزل طسما"},{"id":"diwan-maarri:1235","bookId":"diwan-maarri","type":"poem","seq":1235,"chapter":"قصائد","title":"لم يكفها نور خديها ونور نقا","page":"","text":"لم يكفها نور خديها ونور نقا … في ثغرها، فأصارت عشرها عنما\nكانت أضر لأهل النسك من صنم، … فليبعد الله تلك الخود والصنما\nلم يغنم القيل، عدت في الإماء له، … بل مظهر الزهد في أمثالها غنما"},{"id":"diwan-maarri:1236","bookId":"diwan-maarri","type":"poem","seq":1236,"chapter":"قصائد","title":"الجسم والروح من قبل اجتماعهما،","page":"","text":"الجسم والروح من قبل اجتماعهما، … كانا وديعين لا هما ولا سقما\nتفرد الشيء خير من تألفه … بغيره، وتجر الألفة النقما"},{"id":"diwan-maarri:1237","bookId":"diwan-maarri","type":"poem","seq":1237,"chapter":"قصائد","title":"نفضت عني ترابا، وهو لي نسب،","page":"","text":"نفضت عني ترابا، وهو لي نسب، … وذاك يحسب من قطع الفتى الرحما\nيا هون ما أوعد الله العباد به، … إن صار جسمي في تحريقه فحما\nوإنما هو تخليد بلا أمد، … تمضي الدهور وصالي النار ما رحما"},{"id":"diwan-maarri:1238","bookId":"diwan-maarri","type":"poem","seq":1238,"chapter":"قصائد","title":"إسمع مقالة ذي لب وتجربة،","page":"","text":"إسمع مقالة ذي لب وتجربة، … يفدك، في اليوم ما في دهره علما\nإذا أصاب الفتى خطب يضر به، … فلا يظن جهول أنه ظلما\nقد طال عمري طول الظفر، فاتصلت … به الأذاة، وكان الحظ لو قلما"},{"id":"diwan-maarri:1239","bookId":"diwan-maarri","type":"poem","seq":1239,"chapter":"قصائد","title":"أما حياتي، فما لي عندها فرج،","page":"","text":"أما حياتي، فما لي عندها فرج، … فليت شعري عن موتي إذا قدما\nصحبت عيشا أعانيه ويغلبني، … مثل الوليد يقود المصعب السدما\nوقد مللت زمانا، شره لهب، … إذا دنا لخبو عاد فاحتدما\nمن باعني بحياتي ميتة سرحا، … بايعته، وأهان الله من ندما\nإذا أظلت من الأهواء مهلكة، … فلا تهابن رداها، وامضين قدما\nوالنفس تسمو، فإن تسغب، فبغيتها … قوت، متى أعطيته حاولت أدما\nفي طبعها حبها الدنيا، وقد علمت … أن المنية فينا حادث قدما\nوالخير أجمع في غبراء تأدم بي … هذا التراب، ويفري الجسم والأدما\nفالآن شارفت جيش الحتف، واقتربت … دار أكاد إليها أرفع القدما\nحم القضاء، فما يرثي لباكية، … ولو أفاضت، على إثر الدموع، دما\nمن يغن يخدمه أقوام على طمع، … ولا يرون لمن أخطا الغنى خدما\nوالله صور أشباحا لها خبر، … والشخص بعد وجود يقتضي عدما\nوشاد إيوان كسرى معشر طلبوا … ثباته، وتمادى الوقت، فانهدما"},{"id":"diwan-maarri:1240","bookId":"diwan-maarri","type":"poem","seq":1240,"chapter":"قصائد","title":"إن شئت أن تحفظي من أنت صاحبة","page":"","text":"إن شئت أن تحفظي من أنت صاحبة … له، فلا تدخلي، في المصر، حماما\nوإن بدوت، فلا يؤنسك مرشقة … ضحى، تناجين سوارا وزماما\nفكم عصيتن من ناه وناهية؛ … وكم فضحتن أخوالا وأعماما\nما صانكن سوى الأزواج من أحد؛ … وأول الدهر أعييتن هماما\nوما بكيت رميما، وهي نائية، … وإن علمت حبال الوصل أرماما\nإذا تولت على هجر ومقلية، … فلا تعرض لها، في النوم، إلماما"},{"id":"diwan-maarri:1241","bookId":"diwan-maarri","type":"poem","seq":1241,"chapter":"قصائد","title":"دموعي لا تجيب على الرزايا،","page":"","text":"دموعي لا تجيب على الرزايا، … ولولا ذاك ما فتئت سجوما\nرضا بقضاء ربك، فهو حتم، … ولا تظهر، لحادثة، وجوما\nولم زحلا، أو المريخ فيها، … ولا تلم الذي خلق النجوما\nولست أقول: إن الشهب، يوما، … لبعث محمد جعلت رجوما\nفأمسك غرب فيك، ولا تعود، … على القول، الجراءة والهجوما"},{"id":"diwan-maarri:1242","bookId":"diwan-maarri","type":"poem","seq":1242,"chapter":"قصائد","title":"وجدت الموت للحيوان داء،","page":"","text":"وجدت الموت للحيوان داء، … وكيف أعالج الداء القديما!\nوما دنياك إلا دار سوء، … ولست على إساءتها مقيما\nأرى ولد الفتى عبئا عليه، … لقد سعد الذي أمسى عقيما\nأما شاهدت كل أبي وليد، … يؤم طريق حتف مستقيما؟\nفإما أن يربيه عدوا؛ … وإما أن يخلفه يتيما"},{"id":"diwan-maarri:1243","bookId":"diwan-maarri","type":"poem","seq":1243,"chapter":"قصائد","title":"أجسما فيه هذي الروح، هلا","page":"","text":"أجسما فيه هذي الروح، هلا … غبطت، لفقدها الألم، السلاما\nأجدك لن ترى الإنسان إلا … قليل الرشد، محتملا ملاما\nوتحمله الغريزة، وهو شيخ، … على ما كان يفعله غلاما\nوأيسر من ركوب الظلم، جهلا، … ركوبك، في مآربك، الظلاما\nوقد يبغي السلامة مستجير، … فيترك، من مخافته، السلاما\nوكم حلم الأديم من ابن دهر … حديث السن، ما بلغ احتلاما"},{"id":"diwan-maarri:1244","bookId":"diwan-maarri","type":"poem","seq":1244,"chapter":"قصائد","title":"قال المنجم والطبيب كلاهما:","page":"","text":"قال المنجم والطبيب كلاهما: … لا تحشر الأجساد؛ قلت: إليكما\nإن صح قولكما، فلست بخاسر، … أو صح قولي، فالخسار عليكما\nطهرت ثوبي للصلاة، وقبله … طهر، فأين الطهر من جسديكما؟\nوذكرت ربي، في الضمائر، مؤنسا … خلدي بذاك، فأوحشا خلديكما\nوبكرت في البردين أبغي رحمة … منه، ولا ترعان في برديكما\nإن لم تعد بيدي منافع بالذي … آتي، فهل من عائد بيديكما؟\nبرد التقي، وإن تهلل نسجه، … خير بعلم الله من برديكما"},{"id":"diwan-maarri:1245","bookId":"diwan-maarri","type":"poem","seq":1245,"chapter":"قصائد","title":"قد يرفع الأقوام، إن سئلوا:","page":"","text":"قد يرفع الأقوام، إن سئلوا: … هل تخفضون، وقولهم ربما\nيسقون، في القيظ، الحميم، وفي … حين الصنابر، باردا شبما\nالناصبين، لماء شربهم، … قاماتهم، والناصبين بما"},{"id":"diwan-maarri:1246","bookId":"diwan-maarri","type":"poem","seq":1246,"chapter":"قصائد","title":"قال زمان الناس في صفوه،","page":"","text":"قال زمان الناس في صفوه، … وربه سلاك، أو هيما\nكم غادة لي، أيما غادة، … غادرتها من بعلها أيما\nكانت نظير الشمس، في خدرها، … وغيبت عنه، فقد غيما\nلا تحمل المرأة علما بأن الحس … ن، في مرآتها، ديما\nإن خيمت، أو ظعنت للسرى، … فهو، على أسرارها، خيما\nترائب نعمها قيم، … فصير الترب لها قيما"},{"id":"diwan-maarri:1247","bookId":"diwan-maarri","type":"poem","seq":1247,"chapter":"قصائد","title":"ألمم بدار النسك إلمامه،","page":"","text":"ألمم بدار النسك إلمامه، … فالنفس بالباطل همامه\nوإن رأيت الخود مختالة، … يصلح أن تجعل شمامه\nتطرح في الموم الفتى، واسمها … أسماء، أو زينب، أو مامه\nفعد عنها، وتعوض بها … سوداء، للأينق، زمامه\nغمازة، في الجنح، ضحاكة … لأسفيات الحي رمامه\nقد حدثت سرك طلابه … عين، بما في الصدر، نمامه\nوشر ما أعطيه مكثر … يد، لما تملك ضمامه"},{"id":"diwan-maarri:1248","bookId":"diwan-maarri","type":"poem","seq":1248,"chapter":"قصائد","title":"أجم رحيلي ما أجمت مواردي،","page":"","text":"أجم رحيلي ما أجمت مواردي، … وكان دخولي في ذوي العدد الجم\nأشمس نهاري! كم خلت لك حجة؛ … فهل لك من خال، فيعرف، أو عم؟\nلعمري! لقدما صاغك الله قادرا … بغير أب عند القياس ولا أم\nرحمتك يا مخلوقة الإنس إنما … حياتك موت، والمطاعم كالسم\nفإن تحرمي عقلا سعدت لغبطة؛ … وإن ترزقيه، فهو مبتعث الهم\nولن يجمع الناس، الذين رأيتهم، … على الحمد، لكن يجمعون على الذم"},{"id":"diwan-maarri:1249","bookId":"diwan-maarri","type":"poem","seq":1249,"chapter":"قصائد","title":"لعمري! لقد أغنتك صورة واحد","page":"","text":"لعمري! لقد أغنتك صورة واحد … من الإنس، في الأقوام، عن كنية واسم\nولكن بيان زيد فيك، وإنما … جرينا من الأمر القديم على رسم\nوما كان فينا من سجية مخطىء، … فقد وجدت في حي عاد وفي طسم\nإذا ما تفرقنا خلصنا من الأذى، … ولم يحوج الراعي المسيم إلى الوسم\nتحمل عن الأرض المريضة غاديا، … ولا ترض للداء العياء سوى الحسم\nوما فتئت روح الفتى في نوائب … تمارسها، حتى استقلت عن الجسم\nصبرنا لحكم الله، والنفس حرة، … وقد علمت فضل التفاوت في القسم"},{"id":"diwan-maarri:1250","bookId":"diwan-maarri","type":"poem","seq":1250,"chapter":"قصائد","title":"رويدك! لو كشفت ما أنا مضمر","page":"","text":"رويدك! لو كشفت ما أنا مضمر … من الأمر، ما سميتني أبدا باسمي\nأطهر جسمي، شاتيا ومقيظا، … وقلبي أولى بالطهارة من جسمي"},{"id":"diwan-maarri:1251","bookId":"diwan-maarri","type":"poem","seq":1251,"chapter":"قصائد","title":"تمنيت أني من هضاب يلملم،","page":"","text":"تمنيت أني من هضاب يلملم، … إذا ما أتاني الرزء لم أتلملم\nفمي أخذت منه الليالي، وإنني … لأشرب منه في إناء مثلم\nوأودى بظلم الثغر صبح وحندس، … متى ينظرا في نير العين يظلم\nفذاهبنا كالترب ليس بناطق، … وغابرنا مثل الأسير المكلم\nيحبب دنيانا إلينا قطينها، … فمن ينأ عنهم يسل عنها ويسلم\nمتى تنفرد لا تغبط المال مثريا، … وتستغن، لا تجهل، ولا تتحلم\nومن شأن هذا الخلق غش وظنة، … ومن يتقرب منهم يتظلم\nفإن يسأل الباقي الثرى عن معاشر … ألمت به، يخبر ولا يتكلم\nوكان حلول الروح، في الجسم، نكبة … على خير معيا، أو على شر معلم\nفهل كف وقت لم يكن لعطارد … شبا ظفر، في الأربعاء، مقلم؟\nهي الدار يثويها الفتى ثم يغتدي، … ويتركها للوارث المتسلم"},{"id":"diwan-maarri:1252","bookId":"diwan-maarri","type":"poem","seq":1252,"chapter":"قصائد","title":"أشد عقابا من صلاة أضعتها،","page":"","text":"أشد عقابا من صلاة أضعتها، … وصوم ليوم واجب، ظلم درهم\nإذا لم يكن يوما لديني تعلق … بغيري، رجيت السعادة، فافهم\nوعشت صنوف العيش، كهلا وشارخا؛ … فيا لحياة كاليماني المسهم\nوأعجب للهراز سمي ضيغما؛ … وللعير يدعى بالجواد المطهم\nوما جدل الأقوام إلا تعلة، … مصورة من باطل متوهم"},{"id":"diwan-maarri:1253","bookId":"diwan-maarri","type":"poem","seq":1253,"chapter":"قصائد","title":"إذا لم يكن للميت أهل، فقلما","page":"","text":"إذا لم يكن للميت أهل، فقلما … يزور أناس قبره للتذمم\nوإن مست الأرزاء نفسك لم يكن … لها ناصر، إلا بحسن التغمم\nوهل رد حيا مالك بن نويرة … نكير علي، أو بكاء متمم؟\nزممت المطايا للوجيف، ولم تكن … تنال المعالي بالمطي المزمم\nولكن بأطراف القنا وكعوبه، … وضرب الهوادي بالحديد المسمم\nوجذب رداء، يدرج النمل فوقه، … لتعميم رأس الهبرزي المعمم\nرويدك! لم تبلغ، من الدهر، لذة، … إذا لم تعش عيش الغبي المذمم\nوتسمع فيه ما يصم ذوي النهى، … فلا روح إلا بالحمام المصمم\nوحظك فيه نبذة الفيل، إن دنا … إليها نأت عن أنفه بالتشمم\nوأخلقني مر الزمان وكده، … فصار أديمي كالسقاء المرمم\nفعد، جسدي، للعنصر الطهر تسترح … إذا صرت تقضي الفرض عند التيمم"},{"id":"diwan-maarri:1254","bookId":"diwan-maarri","type":"poem","seq":1254,"chapter":"قصائد","title":"أرى جزء شهد بين أجزاء علقم،","page":"","text":"أرى جزء شهد بين أجزاء علقم، … ولبا ينادي باللبيب: لتعقم\nوأسقام دين، إن يرج شفاءها … صحيح، يطل منه العناء ويسقم\nوصبحا وإظلاما، كأن مداهما … من السر، في لونيهما، برد أرقم\nوحكما لهذا الدهر، صاح بقائم … من العالم: اجلس، أو دعا جالسا: قم\nكأن سرور النفس من خطإ الفتى، … متى ما يكن ينكر عليه وينقم"},{"id":"diwan-maarri:1255","bookId":"diwan-maarri","type":"poem","seq":1255,"chapter":"قصائد","title":"مناطق غلمان، وأحجال أنس،","page":"","text":"مناطق غلمان، وأحجال أنس، … تغر، وأعمال الفتى بالخواتم\nوكم زلة مدت أياد لدفعها، … وقد علقت من أهلها بالعراتم\nفإن عديا فر من خوف نكبة، … وآضت سبيا أخته بنت حاتم\nوما زالت الحمر الرواهن للقرى، … تكشف غمات الوجوه القواتم\nفقارب وباعد واحب واعل ولا تقل، … وقولن، وجاهر بالمراد، وكاتم\nلكل زمان أسرة، ليس أنجم، … بدت مغربا، مثل النجوم العواتم\nأنعمان! ما سر ابن حنتمة الذي … سررت به، من شرب ما في الحناتم\nوأحسن من مدح امرىء الصدق كاذبا … بما ليس فيه، رميه بالمشاتم\nتشابه أهل الأرض: عبد وسيد، … وما قيل في أعراسهم والمآتم\nهم أسفوا للخطب موجب فرحة، … وهشوا لأمر، وهو إحدى السلاتم\nوقد هتم النعمى هميم بن غالب، … لما سار من أقواله في الأهاتم\nوأجمل من سوق المئين سكوته … عن الفخر، والأفواه رهن الرواتم"},{"id":"diwan-maarri:1256","bookId":"diwan-maarri","type":"poem","seq":1256,"chapter":"قصائد","title":"وأي امرىء في الناس ألفي قاضيا،","page":"","text":"وأي امرىء في الناس ألفي قاضيا، … فلم يمض أحكاما لحكم سدوم\nأبت فاقدات الحس حمل رزية، … وهل راب صخرا نحته بقدوم؟"},{"id":"diwan-maarri:1257","bookId":"diwan-maarri","type":"poem","seq":1257,"chapter":"قصائد","title":"أخفت حلوم الناس أم كان من مضى،","page":"","text":"أخفت حلوم الناس أم كان من مضى، … من القوم، جهالا خفاف حلوم؟\nفلا تأسفن الشاة إن أدني ابنها … لشفرة عات، للرجال، ظلوم\nفلو حملوا الخضراء أصبح بينهم … لآض ذبيحا، أو نجا بكلوم\nأناس متى تهرب إلى القبر منهم، … فأنت، بعلم الله، غير ملوم"},{"id":"diwan-maarri:1258","bookId":"diwan-maarri","type":"poem","seq":1258,"chapter":"قصائد","title":"متى ما تشاهد نعمة، كنعامة","page":"","text":"متى ما تشاهد نعمة، كنعامة … مطردة، ترتع بألف ظليم\nونخشى عذابا في الممات، وإننا … لأهل عذاب، في الحياة، أليم\nوما كذبتني لامتي، إن لامتي، … إذا ادرع الأقوام، ثوب مليم\nفيا ليت يومي يوم أشعث عامل، … وليلي، من الإشفاق، ليل سليم\nوما كنت في الرزء الجليل بصابر؛ … ولا عند خطب، هزني، بحليم\nوأشعر أن العقل يصحب تارة، … وينفر أخرى، وهو غير عليم\nوقال أناس: ليس عيسى مقربا؛ … فقيل: ولا موساكم بكليم"},{"id":"diwan-maarri:1259","bookId":"diwan-maarri","type":"poem","seq":1259,"chapter":"قصائد","title":"نصحتك لا تقدم على فعل سوءة؛","page":"","text":"نصحتك لا تقدم على فعل سوءة؛ … وخف من إله، للزمان، قديم\nبنو آدم! لم أدر ما غرض الذي … نماهم، وهل فيهم صحيح أديم؟\nولست ترى إلا عليما كجاهل، … على علمه، أو مثريا كعديم\nوما عندهم من خيرة لمعاشر؛ … وكم من مدام برحت بمديم\nفلا تشربنها ما حييت، وإن تمل … إلى الغي، فاشربها بغير نديم"},{"id":"diwan-maarri:1260","bookId":"diwan-maarri","type":"poem","seq":1260,"chapter":"قصائد","title":"إذا لم تكن دنياك دار إقامة،","page":"","text":"إذا لم تكن دنياك دار إقامة، … فما لك تبنيها بناء مقيم؟\nأرى النسل ذنبا للفتى لا يقاله، … فلا تنكحن، الدهر، غير عقيم\nفحال وحيد لم يخلف مناسبا، … تشابه حالي عامر وتميم\nوأعجب من جهل الذين تكاثروا … بمجد لهم، من حادث وقديم\nوأحلف، ما الدنيا بدار كرامة، … ولا عمرت، من أهلها، بكريم\nسأرحل عنها، لا أؤمل أوبة، … ذميما تولى عن جوار ذميم\nوما صح ود الخل فيها، وإنما … تغر بود، في الحياة، سقيم\nفلا تتعلل بالمدام، وإن تجز … إليها الدنايا، فاخش كل نديم\nوجدت بني الدنيا، لدى كل موطن، … يعدون فيها شفوة كنعيم\nيزيدك فقرا، كلما ازددت ثروة، … فتلقى غنيا في ثياب عديم\nفساد وكون حادثان كلاهما … شهيد بأن الخلق صنع حكيم"},{"id":"diwan-maarri:1261","bookId":"diwan-maarri","type":"poem","seq":1261,"chapter":"قصائد","title":"إذا بلغ الإنسان خمسين حجة،","page":"","text":"إذا بلغ الإنسان خمسين حجة، … فلا يمتهن دينا برد سلام\nليشغل بذكر الله عن كل شاغل؛ … فذلك عند اللب خير كلام\nومن شيم الأيام، وهي كثيرة، … فناء كبير واقتبال غلام\nملام لنفسي، حق عندي لمثلها، … وكنت حقيقا عندها بملام\nوإظلام عين، بعده ظلمة الثرى؛ … فقل في ظلام زيد فوق ظلام"},{"id":"diwan-maarri:1262","bookId":"diwan-maarri","type":"poem","seq":1262,"chapter":"قصائد","title":"بدا شيبه مثل النهار، ولم يكن","page":"","text":"بدا شيبه مثل النهار، ولم يكن … يشابه فجرا، أو نجوم ظلام\nيحدثها ما لا تريد استماعه، … ولم يبق، عند الشيخ، غير كلام\nتقول له في النفس، غير مبينة … خذ المهر مني، وانصرف بسلام\nتود لو ان الله أعطاه حتفه، … وكيف لها، من بعده، بغلام؟"},{"id":"diwan-maarri:1263","bookId":"diwan-maarri","type":"poem","seq":1263,"chapter":"قصائد","title":"أرى البحر ملحا لا يجود لوارد","page":"","text":"أرى البحر ملحا لا يجود لوارد … بورد، فعومي في السراب، وعامي\nتميلين عن نهج اليقين، كأنما … سرى بك أعمى، أو عراك تعامي\nسمام أفاع في اهتضام خوادر، … وختل ذئاب في حلوم نعام\nوكم مر عام لم أكن بعض أهله؛ … وكم نبذت، خلفي، أهلة عام\nفبعدا لنفس لا تزال ذليلة … لحب شراب، أو لحب طعام"},{"id":"diwan-maarri:1264","bookId":"diwan-maarri","type":"poem","seq":1264,"chapter":"قصائد","title":"متى أنا للدار المريحة ظاعن،","page":"","text":"متى أنا للدار المريحة ظاعن، … فقد طال، في دار العناء، مقامي\nوقد ذقتها ما بين شهد وعلقم؛ … وجربتها من صحة وسقام"},{"id":"diwan-maarri:1265","bookId":"diwan-maarri","type":"poem","seq":1265,"chapter":"قصائد","title":"نحس الحياة، على الأحياء، مشتمل؛","page":"","text":"نحس الحياة، على الأحياء، مشتمل؛ … وساكنو الأرض من لؤم بلا كرم\nفالبعد للعيش أداني إلى تلف؛ … وللشبيبة قادتني إلى الهرم\nلا يعجبنك إقبال يريك سنا، … إن الخمود، لعمري، غاية الضرم\nوهي السعادة، للحجرين، مائزة: … مغنى ثمود وحجر البيت والحرم\nلا فرق بين بني فهر وغيرهم، … في دولة، وشهور الحل كالحرم\nقد أبرمت هذه الأجزاع، لا سأما … بالزائرين، ولكن طبن عن برم"},{"id":"diwan-maarri:1266","bookId":"diwan-maarri","type":"poem","seq":1266,"chapter":"قصائد","title":"كل البلاد ذميم لا مقام به،","page":"","text":"كل البلاد ذميم لا مقام به، … وإن حللت ديار الوبل والرهم\nإن الحجاز عن الخيرات محتجز، … وما تهامة إلا معدن التهم\nوالشأم شؤم، وليس اليمن في يمن، … ويثرب الآن تثريب على الفهم"},{"id":"diwan-maarri:1267","bookId":"diwan-maarri","type":"poem","seq":1267,"chapter":"قصائد","title":"لا تحدث القطع في كف ولا قدم؛","page":"","text":"لا تحدث القطع في كف ولا قدم؛ … ولا تعرض مدى الدنيا لسفك دم\nوخل من صور الأشباح، مقتدرا، … يحلها، فهو رب الدهر والقدم\nوتصبح الذرة الصغرى له أمة؛ … والشمس والبدر معدودين في الخدم\nوقد أسفت لخير، إذ علمت به، … وما أسفت عليه كيف لم يدم\nوما انتفاعي بندمان أسر به، … إذا الفراق رماني منه بالندم\nوإن حسرة نفس، غير هينة، … مصيرها، بعد إيجاد، إلى عدم\nلو شك بالطعن ميت لم يجد ألما، … فالرمح فيه كإشفى الخرز في الأدم\nسيان إلباسه ما لان من كفن، … وطرحه في لظى للنار محتدم"},{"id":"diwan-maarri:1268","bookId":"diwan-maarri","type":"poem","seq":1268,"chapter":"قصائد","title":"النفس، إن لم تذق موتا، مشارفة،","page":"","text":"النفس، إن لم تذق موتا، مشارفة، … إن لم يحم، بقدر، يومها يحم\nإن تطفإ النار عن جزل، فإن لها … يعفى ويخبأ ما أبقت من الفحم\nوبعض جسمك يرمي بعضه بأذى، … وأكثر الشر يأتي من ذوي الرحم\nويشتهي الناس ما لا يسعفون به، … وشركة الخلق دون الحمل في الوحم"},{"id":"diwan-maarri:1269","bookId":"diwan-maarri","type":"poem","seq":1269,"chapter":"قصائد","title":"ما أقبح المين! قلتم لم يشب أحد،","page":"","text":"ما أقبح المين! قلتم لم يشب أحد، … حتى أتى الشيب إبراهيم عن أمم\nكذبتم، ونجوم الليل شاهدة، … إن المشيب قديما حل في اللمم\nهذا البياض رسول الموت، يبعثه، … في كل عصر، إلى الأجيال والأمم\nوما أسيت على الدنيا، مزايلة، … ولا تأست على البالي من الرمم\nشقت وعقت، ولم أحمد، ولا حمدت … ثم انصرفنا كلانا سيىء الهمم\nورغبتي في بنيها غير كائنة؛ … وكيف يرغب خدن العقل في اللمم\nلا خير فيهم، وإن هم عظموا رجبا، … دون الشهور، فقد شانوه بالصمم\nلم تعط قط أنوفا، جدعت، شمما؛ … فليت كفك لم تجدع أخا الشمم\nلا تحكم العقد في حلف ولا عدة، … فإن طبعك يدعى ناقض الذمم\nوللزمان مغار في نفوسهم؛ … يكفيك أن تضع الهندي بالقمم"},{"id":"diwan-maarri:1270","bookId":"diwan-maarri","type":"poem","seq":1270,"chapter":"قصائد","title":"عرفت من أم دفر شيمة عجبا،","page":"","text":"عرفت من أم دفر شيمة عجبا، … دلت على اللؤم، وهي العنف بالخدم\nومن يهنها تصنه عن مكارهها، … بعض الصيانة، فارفضها بلا ندم\nوما لنفسي خلاص من نوائبها، … ولا لغيري إلا الكون في العدم"},{"id":"diwan-maarri:1271","bookId":"diwan-maarri","type":"poem","seq":1271,"chapter":"قصائد","title":"فضيلة النطق، في الإنسان، تمزجها","page":"","text":"فضيلة النطق، في الإنسان، تمزجها … نقيضة الكذب المعدود في النقم\nأصدق إلى أن تظن الصدق مهلكة، … وعند ذلك فاقعد كاذبا وقم\nفالمين ميتة مضطر ألم بها؛ … والحق كالماء يجفى خيفة السقم"},{"id":"diwan-maarri:1272","bookId":"diwan-maarri","type":"poem","seq":1272,"chapter":"قصائد","title":"لقد أسفت، وماذا رد لي أسفي،","page":"","text":"لقد أسفت، وماذا رد لي أسفي، … لما تفكرت في الأيام والقدم؟\nفي العدم كنا، وحكم الله أوجدنا، … ثم اتفقنا على ثان من العدم\nسيان عام ويوم في ذهابهما، … كأن ما دام، ثم انبت، لم يدم"},{"id":"diwan-maarri:1273","bookId":"diwan-maarri","type":"poem","seq":1273,"chapter":"قصائد","title":"اعدد لكل زمان ما يشاكله؛","page":"","text":"اعدد لكل زمان ما يشاكله؛ … إن البراقع يستثبتن بالشبم\nفإن ضربت بسيف الهند في ومد، … فسيف إفرنجة المخبوء للشبم"},{"id":"diwan-maarri:1274","bookId":"diwan-maarri","type":"poem","seq":1274,"chapter":"قصائد","title":"العيش أدى إلى ضر ومهلكة،","page":"","text":"العيش أدى إلى ضر ومهلكة، … لولا الحياة لكان الجسم كالصنم\nمن يفقد الحس لا يعرف بمخزية؛ … إن الذباب متى يعل الجنى ينم\nهذا الأنام له شأن يراد به، … وأنت غيري، وليس الأري كالهنم\nمعنى خبيء على ما بان منه، كما … تبنى الزوائد من: يا أوس لا تنم\nوحاجة النفس ترضيها بما سخطت، … وكم تجرأ رب الإبل بالغنم\nدع الكعاب التي لم يدن مأكلها، … من لؤلؤ الثغر، إلا قانىء العنم"},{"id":"diwan-maarri:1275","bookId":"diwan-maarri","type":"poem","seq":1275,"chapter":"قصائد","title":"إن طاب خيمك في الدنيا، فلا تخم؛","page":"","text":"إن طاب خيمك في الدنيا، فلا تخم؛ … ولا تضن بمقتول على الرخم\nفالجسم، إن زايلته الروح، صار لقى … كلا على القوم، ما فيه من الضخم"},{"id":"diwan-maarri:1276","bookId":"diwan-maarri","type":"poem","seq":1276,"chapter":"قصائد","title":"أصمت سويداء قلب، من تلهبها،","page":"","text":"أصمت سويداء قلب، من تلهبها، … حمراء، والنار تنضو حلة الفحم\nكأنما الليث ألقى لون مقلته، … ليلا عليها، فقد ملت من السحم\nوالترب نقليه ظلما، وهو والدنا، … وكم لنا فيه من قربى ومن رحم"},{"id":"diwan-maarri:1277","bookId":"diwan-maarri","type":"poem","seq":1277,"chapter":"قصائد","title":"دنياك هذي منام، إن جرى حلم","page":"","text":"دنياك هذي منام، إن جرى حلم … فيها بشر، فأمل غبطة الحلم\nفقد يرى، أنه باك، حليف كرى، … فيستجد سرورا، فاقد الألم\nفاضرب وليدك، وادلله على رشد، … ولا تقل: هو طفل غير محتلم\nورب شق برأس جر منفعة، … وقس على نفع شق الرأس في القلم"},{"id":"diwan-maarri:1278","bookId":"diwan-maarri","type":"poem","seq":1278,"chapter":"قصائد","title":"كم باد في حدثان الدهر من ملإ؛","page":"","text":"كم باد في حدثان الدهر من ملإ؛ … وساد في دول الأيام من قزم\nوالسعد فوق سروج الخيل، يمسكها … لأهلها، وهي لم تشدد إلى الحزم\nوالليث، إن ولج الحرمان منه، فما … ألقى الفريسة من أنيابه الأزم"},{"id":"diwan-maarri:1279","bookId":"diwan-maarri","type":"poem","seq":1279,"chapter":"قصائد","title":"أطرق، كأنك في الدنيا بلا نظر،","page":"","text":"أطرق، كأنك في الدنيا بلا نظر، … واصمت، كأنك مخلوق بغير فم\nوإن هممت بمين، فاتخذ لفما … مضاعفات، لتثني اللفظ باللفم"},{"id":"diwan-maarri:1280","bookId":"diwan-maarri","type":"poem","seq":1280,"chapter":"قصائد","title":"كلم بسيفك قوما، إن دعوتهم،","page":"","text":"كلم بسيفك قوما، إن دعوتهم، … من الكلوم، فما يصغون للكلم\nذو النون، إن كان سيف الهند، أبلغ من … ذي النون في الوعظ، بل من نون والقلم"},{"id":"diwan-maarri:1281","bookId":"diwan-maarri","type":"poem","seq":1281,"chapter":"قصائد","title":"إذا أمنت على مال أخا ثقة،","page":"","text":"إذا أمنت على مال أخا ثقة، … فاحذر أخاك، ولا تأمن على الحرم\nفالطبع في كل جيل طبع ملأمة، … وليس، في الطبع، مجبول على الكرم"},{"id":"diwan-maarri:1282","bookId":"diwan-maarri","type":"poem","seq":1282,"chapter":"قصائد","title":"هل يأمن الفتيان الخطب آونة،","page":"","text":"هل يأمن الفتيان الخطب آونة، … وللمقادير إعلام بإعلام\nأولاهما أن يغادى، في مدى بردى، … هذا النهار، فكونوا أهل أحلام\nهو الجديد، فيطويه الزمان بلى، … ويرجع الدهر إظلاما بإظلام\nدنياك، فيما توالي، غير محسنة، … فلم تزل ذات أولاد وأخلام\nحسب الحياة قذاة أن تعد أذى؛ … وأن تقضى بأوصاب وآلام\nوليس يقذفني فقري إلى نوبي، … ولا يسلمني منهن إسلامي\nوالناس في غمرات أعملوا فكرا، … كالسرب يرتع في رغل وقلام\nوما يعرون، من مكر ولا حيل، … أطراف سمر ولا أطراف أقلام\nأعياك خل، ولولا قدرة سلفت، … لم يمكن الجمع بين الخاء واللام\nفلا تغرنك، في الأيام، خادعة … من الحسان، بوحي أو بكلام\nينأى الغلام، ولو لم يرض والده، … عن احتياج إلى حلي وعلام\nفاردد أمورك، فيما أنت فاعله، … إلى نقي من الأدناس، علام"},{"id":"diwan-maarri:1283","bookId":"diwan-maarri","type":"poem","seq":1283,"chapter":"قصائد","title":"عيش وموت، وأحداث تبدلها","page":"","text":"عيش وموت، وأحداث تبدلها … ينوبنا، ومهود بين أرحام\nأمر، حمى النوم، بعد الفكر، صاحبه، … ومثله لرقاد وارد حام"},{"id":"diwan-maarri:1284","bookId":"diwan-maarri","type":"poem","seq":1284,"chapter":"قصائد","title":"إلهنا الحق! خفف واشف من وصب،","page":"","text":"إلهنا الحق! خفف واشف من وصب، … فإنها دار أثقال وآلام\nيسر علينا رحيلا، لا يلبثنا، … إلى الحفائر من أهل وأخلام\nوجازنا عن خطايانا بمغفرة؛ … فكم حلمت، ولسنا أهل أحلام\nقد أسلم الرجل النصران، مرتغبا … وليس ذلك من حب لإسلام\nوإنما رام عزا في معيشته، … أو خاف ضربة ماضي الحد قلام\nأو شاء تزويج مثل الظبي، معلمة، … للناظرين بأسوار وعلام\nقد حاول الناس رزق الله، فابتكروا … مجاهدين بأرماح وأقلام\nنرجو من الله رحبا إثر ضيقة … من الأمور، ونورا بعد إظلام\nله الممالك قد بانت دلائلها، … للمفكرين، برايات وأعلام\nوالحظ، من غير سعي، من مواهبه، … كأنها ضرب أيسار بأزلام\nويح لجيلي والأجيال، إن بعثوا … إلى حساب قديم اللطف علام\nمحصي الجرائم، فعال العظائم، نص … ار الهضائم، جاز، غير ظلام"},{"id":"diwan-maarri:1285","bookId":"diwan-maarri","type":"poem","seq":1285,"chapter":"قصائد","title":"عققت دنياك، إن حاولت خدمتها؛","page":"","text":"عققت دنياك، إن حاولت خدمتها؛ … إياك والأم، لا تدعى من الآم\nوتحت رجلك منها مفرق ترب، … أنى اتجهت بإعراق وإشآم\nأسمتني أم دفر غير مرعية، … وزاد أهلك إعناتي وإسآمي"},{"id":"diwan-maarri:1286","bookId":"diwan-maarri","type":"poem","seq":1286,"chapter":"قصائد","title":"لا تزدرن صغارا في ملاعبهم،","page":"","text":"لا تزدرن صغارا في ملاعبهم، … فجائز أن يروا سادات أقوام\nوأكرموا الطفل عن نكر يقال له، … فإن يعش يدع كهلا بعد أعوام\nولا تناموا عن الدنيا وغرتها، … فإن أبيتم، فكونوا خير نوام\nلا تظلموا من بنيها واحدا أبدا، … حتى تعدوا ذوي فطر كصوام"},{"id":"diwan-maarri:1287","bookId":"diwan-maarri","type":"poem","seq":1287,"chapter":"قصائد","title":"بعض الأقارب مكروه تجاورهم،","page":"","text":"بعض الأقارب مكروه تجاورهم، … وإن أتوك ذوي قربى وأرحام\nكالعين والحاء تأبى أن تقارنها … في لفظها، فحماها قربها حامي"},{"id":"diwan-maarri:1288","bookId":"diwan-maarri","type":"poem","seq":1288,"chapter":"قصائد","title":"سألتكم: لا تكنوني لتكرمة،","page":"","text":"سألتكم: لا تكنوني لتكرمة، … وصغروني تصغيرا بترخيم\nفالمرء يخلق من أشياء أربعة، … وكلها راجع للأصل والخيم\nوما ألومك في خفضي ومنقصتي، … لكن ألومك في رفعي وتفخيمي"},{"id":"diwan-maarri:1289","bookId":"diwan-maarri","type":"poem","seq":1289,"chapter":"قصائد","title":"ليس اغتنام الصديق شأني؛","page":"","text":"ليس اغتنام الصديق شأني؛ … فلا تكن، شأنك اغتنامي\nفي الأرض حي وغير حي، … فجامد بيننا ونام\nغيب ميت، فما رأته … عين سوى رؤية المنام\nفلا يبال اللبيب منا … في منسم حل، أو سنام\nنأي زنام، أوان يدهى، … حدث بالناي عن زنام\nوالغدر، في الآدمي، طبع، … فاحترزي قبل أن تنامي\nمن ادعى أنه وفي، … فلينتسب في سوى الأنام"},{"id":"diwan-maarri:1290","bookId":"diwan-maarri","type":"poem","seq":1290,"chapter":"قصائد","title":"أدنياي! اذهبي، وسواي أمي،","page":"","text":"أدنياي! اذهبي، وسواي أمي، … فقد ألممت، ليتك لم تلمي\nوكان الدهر ظرفا، لا لحمد … تؤهله العقول، ولا لذم\nوأحسب سانح الإزميم نادى … ببين الحي، في صحراء زم\nإذا بكر جنى فتوق عمرا، … فإن كليهما لأب وأم\nوخف حيوان هذي الأرض، واحذر … مجيء النطح من روق وجم\nوفي كل الطباع طباع نكر، … وليس جميعهن ذوات سم\nوما ذنب الضراغم حين صيغت، … وصير قوتها مما تدمي؟\nفقد جبلت على فرس وضرس، … كما جبل الوقود على التنمي\nضياء لم يبن لعيون كمه؛ … وقول ضاع في آذان صم\nلعمرك، ما أسر بيوم فطر، … ولا أضحى، ولا بغدير خم\nوكم أبدى تشيعه غوي، … لأجل تنسب ببلاد قم\nوما زال الزمان، بلا ارتياب، … يعد الجدع للأنف الأشم\nأحاضنة الغلام! ذممت منه … أذاك، فأرضعي حنشا، وضمي\nفلو وفقت لم تسقي جنينا، … ولم تضعي الوليد؛ ولم تهمي\nلهان، على أقاربك الأداني، … قيامك عن خديج غير تم\nسألت عن الحقائق، وهي سر، … ويخشاك المخبر أن تنمي\nوكيف يبين، للأفهام، معنى، … له من ربه قدر معمي؟\nوعندي، لو أمنتك، علم أمر … من الجهال، غيبه، مكم\nوسمي، إن أراق الماء، جبس، … يراقب جنة أن لا يسمي\nرأيت الحق لؤلؤة توارت … بلج، من ضلال الناس، جم\nأحث الخلق: من ذكر وأنثى، … على حسن التعبد والتأمي\nوقد يلفى الغريب، على نواه، … أعز عليك من خال وعم\nمتى يتبلج المبيض يرعى، … لقوم، تحت أخضر مدلهم\nونحن ميممون مدى بعيدا، … كأنا عائمون غمار يم"},{"id":"diwan-maarri:1291","bookId":"diwan-maarri","type":"poem","seq":1291,"chapter":"قصائد","title":"لقد كرمت عليك فتاة قوم،","page":"","text":"لقد كرمت عليك فتاة قوم، … شربت، بفضلها، فضلات كرم\nوسقت إليك سوء الجرم عمدا، … وأنت معلل بسويق جرم\nأرى هرما يعيد نبات نبع، … وإن كان الصليب كنبت هرم\nلقد خاب الذي حلبت يداه … سفاهة عقله، بأذى وغرم\nسيخفت، كل صوت، زأر ليث، … ونبأة باغم، وهدير قرم\nرماني من له وتري وقوسي، … وكفي والسهام، فكيف أرمي؟"},{"id":"diwan-maarri:1292","bookId":"diwan-maarri","type":"poem","seq":1292,"chapter":"قصائد","title":"أقضي الدهر من فطر وصوم،","page":"","text":"أقضي الدهر من فطر وصوم، … وآخذ بلغة يوما بيوم\nوأعلم أن غايتي المنايا؛ … فصبرا! تلك غاية كل قوم\nوسامتني إهانتها الليالي؛ … ومن لي أن تخليني وسومي؟\nفإن تقف الحوادث دون نفسي، … فما يتركن إشمامي ورومي\nأعوم اللج، والحيتان حولي، … وما أنا محسن، في ذاك، عومي\nوأيام الحياة ظلال عتر؛ … ومن لي أن يكون ظلال دوم؟\nلعل العيش تسهيد ونصب، … وراحتي الحمام، أتى بنوم\nوما كان المهيمن، وهو عدل، … ليقصر حيلتي، ويطيل لومي"},{"id":"diwan-maarri:1293","bookId":"diwan-maarri","type":"poem","seq":1293,"chapter":"قصائد","title":"لقد هجم الزمان على تميم","page":"","text":"لقد هجم الزمان على تميم … بأجمعهم، فمن آل الهجيم؟\nفما حمت السروج ظبى سريج … ولا لجم الجياد بني لجيم"},{"id":"diwan-maarri:1294","bookId":"diwan-maarri","type":"poem","seq":1294,"chapter":"قصائد","title":"أما لأمير هذا المصر عقل","page":"","text":"أما لأمير هذا المصر عقل … يقيم، عن الطريق، ذوي النجوم؟\nفكم قطعوا السبيل على ضعيف، … ولم يعفوا النساء من الهجوم\nهم ناس، ولو رجموا استحقوا … بأنهم شياطين الرجوم\nإذا افتكر اللبيب رأى أمورا، … ترد الضاحكات إلى الوجوم\nإلى الليثين ترسل، باقتدار، … نوائبها، يد القدر الهجوم\nفمن أسد يعد من الضواري؛ … ومن أسد يعد من النجوم"},{"id":"diwan-maarri:1295","bookId":"diwan-maarri","type":"poem","seq":1295,"chapter":"قصائد","title":"يقول الناس: إن الخمر تودي","page":"","text":"يقول الناس: إن الخمر تودي … بما في الصدر من هم قديم\nولولا أنها باللب تودي، … لكنت أخا المدامة والنديم"},{"id":"diwan-maarri:1296","bookId":"diwan-maarri","type":"poem","seq":1296,"chapter":"قصائد","title":"أبالقدر المتاح تدين جن","page":"","text":"أبالقدر المتاح تدين جن … تسمع، غير هائبة الرجوم\nوتعلم أن ما لم ينض صعب، … فما تخشى المنية في الهجوم\nبإذن الله ينفذ كل أمر؛ … فنهنه فيض أدمعك السجوم\nيجوز بحكمه موت الثريا، … وأن تبقى السماء بلا نجوم\nوكم وجم الفتى من بعد ضحك، … وأضحك بعد إفراط الوجوم"},{"id":"diwan-maarri:1297","bookId":"diwan-maarri","type":"poem","seq":1297,"chapter":"قصائد","title":"إذا ما جاءني رجل حذام،","page":"","text":"إذا ما جاءني رجل حذام، … فإن القول ما قالت حذام\nأرى سيف بن ذي يزن، فرته … صروف الدهر بالسيف الهذام\nوأذوت غاضرا، ورمت حبالا … سليل أخي طليحة بانجذام\nوما زيد بن حارثة حبيبا … إلى الحي المصبح من جذام\nألم تر لامرىء القيس بن حجر … بكى، متشبها بفتى حذام؟\nكذاك تناسخ الدنيا، فمن لي … مزادك قبل تقضيب الوذام"},{"id":"diwan-maarri:1298","bookId":"diwan-maarri","type":"poem","seq":1298,"chapter":"قصائد","title":"قطع الطريق بمهمه، ونظيره،","page":"","text":"قطع الطريق بمهمه، ونظيره، … في المصر، فعل منجم ومعزم\nتتوافق الأسماء منا، والكنى … متباينات، فانه جهلا، واحزم\nهيهات! ما الجوزاء، ترزم عندها … وجناء، كالجوزاء ذات المرزم\nوتشابه الأخلاق من متباعدي … نجر، وليس خزيمة من أخزم\nوبعين سلوان، التي في قدسها … طعم يوهم أنها من زمزم\nوالمرء يسخط ما أتاه، وكم فتى … كالشن ينفع أهله بمهزم\nغضب المملك أن خرجا لم يفر، … والعبد أن سقاءه لم يخزم\nوالخير أفضل ما اعتقدت، فلا تكن … هملا، وصل بقبلة، أو زمزم\nووجدت نفس الحر تجعل كفه … صفرا، وتلزمه بما لم يلزم"},{"id":"diwan-maarri:1299","bookId":"diwan-maarri","type":"poem","seq":1299,"chapter":"قصائد","title":"علمي بأني جاهل متمكن","page":"","text":"علمي بأني جاهل متمكن … عندي، وإن ضيعت حق العالم\nوالظلم يمهل بعض من يسعى له، … ومحل نقمته بنفس الظالم\nما بال من طلب الهدى بمفاوز … قفر، وطالب غيره بمعالم؟\nوالمرء في حال التيقظ هاجع، … يرنو إلى الدنيا بمقلة حالم\nوأخو الحجى أبدا يجاهد طبعه، … فتراه، وهو محارب، كمسالم\nسأل الطبيب عن الشكاية مدنف … يرجو سلامته، وليس بسالم"},{"id":"diwan-maarri:1300","bookId":"diwan-maarri","type":"poem","seq":1300,"chapter":"قصائد","title":"أسكت وخل مضلهم وشؤونه،","page":"","text":"أسكت وخل مضلهم وشؤونه، … ليسوقهم بعصاه، أو بحسامه\nنصحوا فما قبلوا وباعوا كثكثا، … من شر معدنه، بقيمة سامه\nفكأنهم غنم ترود، أسامها … من لا يبالي كيف حال مسامه\nدفن السرور، فما يبين لعاقل … رزء، يكون الموت في أقسامه\nكذب امرؤ نسب القبيح إلى الذي … خلق الأنام، وخط في برسامه"},{"id":"diwan-maarri:1301","bookId":"diwan-maarri","type":"poem","seq":1301,"chapter":"قصائد","title":"هذي الحياة مسافة، فاصبر لها،","page":"","text":"هذي الحياة مسافة، فاصبر لها، … كيما تبين، وأنت غير ملوم\nمن لي بناجية سفيهة مدلج، … فالعيس لم تحمد ذوات حلوم\nروح الظلوم إذا هوت، فإذا ارتقت، … فكأنما هي دعوة المظلوم\nأما ركاب الجود، فهي عواطب، … وسرى الأنام على ركاب اللوم\nفي عالم، أخذ الإله عقولهم، … فغدوا جميعهم بلا معلوم"},{"id":"diwan-maarri:1302","bookId":"diwan-maarri","type":"poem","seq":1302,"chapter":"قصائد","title":"شر على المرأة من حمامها،","page":"","text":"شر على المرأة من حمامها، … إرسالك الفاضل من زمامها\nومشيها تضرب في أكمامها، … يفوح ريا الطيب من أمامها\nزائرة المسجد في إلمامها، … تأتم، والخيبة في ائتمامها\nبأحدل، ما عف عن كمامها، … أعاذها الخالق من إمامها\nوريقها الشروب، في صمامها، … سمام أفعى بان من سمامها\nإن نزلت عصماء من شمامها، … فلا سقاها الطل من غمامها\nإذا احتوى الريم على رمامها، … لزومها البيت مع اهتمامها\nحتى يجيها الوفد من حمامها، … وحملها المغزل في إتمامها\nأوفى بما تعقد من ذمامها … -"},{"id":"diwan-maarri:1303","bookId":"diwan-maarri","type":"poem","seq":1303,"chapter":"قصائد","title":"إجتنب الناس وعش واحدا،","page":"","text":"إجتنب الناس وعش واحدا، … لا تظلم القوم، ولا تظلم\nوجدت دنياك، وإن ساعفت، … لا بد من وقعتها الصيلم\nلو بعث المنصور نادى: أيا … مدينة التسليم! لا تسلمي\nقد سكن القفر بنو هاشم، … وانتقل الملك إلى الديلم\nلو كنت أدري أن عقباهم … لذاك، لم أقتل أبا مسلم\nقد خدم الدولة مستنصحا، … فألبسته شية العظلم\nما دام غير الله من دائم، … فاغضب على الأقدار، أو سلم\nطوفت في الآفاق عصرا، فما … أسفرت من حندسك المظلم\nسألت أقواما، فلم تلف من … يهديك من رشد إلى معلم\nفاحلم عن الجاهل مستكبرا، … فالعين إن تلق الكرى تحلم\nإن وفاة النكس، في جبنه، … مثل وفاة الفارس المعلم"},{"id":"diwan-maarri:1304","bookId":"diwan-maarri","type":"poem","seq":1304,"chapter":"قصائد","title":"يضحي الفتى المرؤوس بالسيد ال","page":"","text":"يضحي الفتى المرؤوس بالسيد ال … ماجد، كالمرؤوس بالصارم\nغريزة، في الناس، معروفة، … تنقل للمكروم بالكارم\nوالدهر لا ينكر تسويده … بني كليب لبني دارم\nويخمص الإنسان من نخوة، … ساكنة في أنفه الوارم\nبيت العلى بيت قريض، ولا … بد من الكاسر والخارم\nإن يحرم السائل عندي جدا، … فلست، عند الله، بالحارم\nلو كنت أسطيع له راحة، … راح بها في عامه العارم\nصد زكاة المال من زاد، في ال … حال، عن المسكين والغارم\nوالحق أن تطلب، ما بيننا، … جناية الجرم من الجارم"},{"id":"diwan-maarri:1305","bookId":"diwan-maarri","type":"poem","seq":1305,"chapter":"قصائد","title":"نطقت حيا نيرا، فاعذري","page":"","text":"نطقت حيا نيرا، فاعذري … من نطق النير، أو لومي\nسلي عن الخير، فعهدي به، … مع التقصي، غير معلوم\nأنصف مولانا، وكل امرىء … يظلم، والظلم من اللوم\nقد يقتل الحر، وما دينه، … في طاعة الله، بمكلوم\nلا شيء، في الجو وآفاقه، … أصعد من دعوة مظلوم"},{"id":"diwan-maarri:1306","bookId":"diwan-maarri","type":"poem","seq":1306,"chapter":"قصائد","title":"إن سرور المدام لم يدم،","page":"","text":"إن سرور المدام لم يدم، … بل أعقبت بالهموم والسدم\nوالكأس من كاس في التعثر، وال … ندمان لفظ أتى من الندم\nما زال مستهترا بها لهجا، … حتى انثنى موسرا من العدم\nكيف له أن يكون شاربها … بالأهل، بعد السوام والخدم\nأقبل يهوي بها إلى فمه، … حتى ترقى يفري من الأدم\nيوسع الجلد والعظام لها، … أطبقة مازجت دما بدم\nمقتولة، في الحديث، ضاحكة، … موطوءة، في القديم، بالقدم\nقد ظهر السر، بعد خفيته، … من قائل بالزمان والقدم\nلم تخلد الراح والمزاهر وال … قينات حيي عاد، ولا قدم"},{"id":"diwan-maarri:1307","bookId":"diwan-maarri","type":"poem","seq":1307,"chapter":"قصائد","title":"ما أكرم الله، عز من ملك،","page":"","text":"ما أكرم الله، عز من ملك، … ورزقنا من دلائل الكرم\nكم عال من كافر وكافرة، … من ابتداء الصبا إلى الهرم\nثم استقلا إلى قبورهما، … والقبر، للنازلين، كالحرم\nإذا عظام الفتى به أرمت، … حسبته من ثمود، أو إرم\nقد وطىء الأخمصان، ويحهما، … على جسوم الرجال والحرم\nيا جسد الميت! كم أضيف إلى … تربك من ياسر ومن برم\nوأوقد الناس، فوق أرضهم، … أمثالها من مجمع الضرم\nلو أنصفوا نزهوا سوامهم … عن غليان الكسور في البرم\nقرم هوى مقرم بصارمه، … يدعو به: لا شفيت من قرم\nحرمتني الكون في الرياض، وأن … أنشق ريا العرار والبرم\nأو أرد الماء، بعد خامسة، … في هجمات الحلال والصرم\nقضيت بي حق رفقة وفدت؛ … حسبك من مأثم ومجترم\nرب مهاة نفت بمرودها ال … أعداء من طفلها، فلم يرم\nحم لها نابل، فغادرها … مخضوبة بالنجيع، وهي رمي"},{"id":"diwan-maarri:1308","bookId":"diwan-maarri","type":"poem","seq":1308,"chapter":"قصائد","title":"لو زعمت نفسي الرشاد لها","page":"","text":"لو زعمت نفسي الرشاد لها … حلفا لكذبتها بمزعمها\nدار، إذا سمحت بلذتها، … فإن بؤسا وراء أنعمها\nإن غفر الله لي، فلا أسف … على الذي فات من تنعمها\nأكلتها جمرة، حرارتها … صدت أخا الحرص عن تطعمها"},{"id":"diwan-maarri:1309","bookId":"diwan-maarri","type":"poem","seq":1309,"chapter":"قصائد","title":"رب اكفني حسرة الندامة في ال","page":"","text":"رب اكفني حسرة الندامة في ال … عقبى، فإني محالف الندم\nوالظلم في وقدة، فلو عرضت … شربة ماء لما غلت بدمي\nولم يكن، في غمامنا، وشل، … ولا قليب لنا ولا أدم\nعفوك للروح، وهي قادرة، … وجسمها، كالهباء، للقدم\nلا تفرق العين، حين تبصره، … ما بين كف تبين من قدم\nوالملك فينا هو الفقير، لما … يلزمه من معونة الخدم\nيكفيك عبد، وليس يقنعه … ألف، وكم دمت، وهو لم يدم\nوكيف ترجى السعود في زمن، … يساره راجع إلى العدم؟"},{"id":"diwan-maarri:1310","bookId":"diwan-maarri","type":"poem","seq":1310,"chapter":"قصائد","title":"وددت وفاتي في مهمه،","page":"","text":"وددت وفاتي في مهمه، … به لامع، ليس بالمعلم\nأموت به واحدا مفردا، … وأدفن في الأرض لم تظلم\nوأبعد عن قائل: لا سلمت؛ … وآخر قال: ألا يا سلمي\nأحاذر أن تجعلوا مضجعي … إلى كافر، خان، أو مسلم\nإذا قال: ضايقتني في المحل! … قلت: أساؤا، ولم أعلم"},{"id":"diwan-maarri:1311","bookId":"diwan-maarri","type":"poem","seq":1311,"chapter":"قصائد","title":"سلي الله ربك إحسانه،","page":"","text":"سلي الله ربك إحسانه، … فإنك إن تنظري تألمي\nوليس اعتقادي خلود النجوم، … ولا مذهبي قدم العالم"},{"id":"diwan-maarri:1312","bookId":"diwan-maarri","type":"poem","seq":1312,"chapter":"قصائد","title":"قفي وقفة تعلمي،","page":"","text":"قفي وقفة تعلمي، … وإن سلموا، فاسلمي\nفما قلت من لوعة: … ألمي بنا يا لم\nوكيف صعودي إلى … الثريا بلا سلم؟\nأيخلص هذا الورى … من الحندس المظلم؟\nأيهم لم يكن … ظلوما، ولم يظلم؟\nولا بد للحادثا … ت من وقعة صيلم\nتبيد أعاديهم … مع الترك والديلم\nوتثنيك في راحة، … كأنك لم تؤلم\nولم يبق صرف الردى … على بطل معلم\nيخضب هام العدى … بنحو من العظلم\nوكم بذ من قرح … مدى الجذع الأزلم\nولست من الركب، إذ … يعوجون في المعلم\nإذا طمعوا فاقتنع؛ … وإن جهلوا فاحلم\nولا يدنون الفتى … لعرس، ولا يولم\nفإن ظهرت زلتي، … فقل لرفيقي: لم"},{"id":"diwan-maarri:1313","bookId":"diwan-maarri","type":"poem","seq":1313,"chapter":"قصائد","title":"ما للأنام؟ وجدتهم، من جهلهم","page":"","text":"ما للأنام؟ وجدتهم، من جهلهم … بالدين، أشباه النعام، أو النعم\nفمجادل وصل الجدال، وقد درى … أن الحقيقة فيه ليس كما زعم\nعلم الفتى النظار أن بصائرا … عميت، فكم يخفى اليقين، وكم يعم\nلو قال سيد غضا: بعثت بملة … من عند ربي؛ قال بعضهم: نعم!"},{"id":"diwan-maarri:1314","bookId":"diwan-maarri","type":"poem","seq":1314,"chapter":"قصائد","title":"يا روح! شخصي منزل أوطنته،","page":"","text":"يا روح! شخصي منزل أوطنته، … ورحلت عنه، فهل أسفت، وقد هدم\nعيد المريض، وعاونته خوادم، … ثم انتقلت، فما أعين ولا خدم\nلقد استراح معلل ومساهر … منه، وإن غدت النوائح تلتدم\nحملوه، بعد مجادل وأسرة، … حمل الغريب، فحط في بيت ردم\nما زال في تعب وهم دائم، … فلعله عدم الأذاة بأن عدم\nلو كان ينطق ميت لسألته: … ماذا أحس، وما رأى لما قدم؟\nإن تثو في دار الجنان، فإنما … فارقت من دنياك نارا تحتدم\nمن ذا يلومك في هواك مسيئة؛ … كل الأنام بحبها كلف سدم\nفاعذر خليلك إن جفاك ولا تجد؛ … وإذا الزيارة ساعفتك، فلا تدم\nبئس العشير أنا، الغداة، وصاحبي … مثلي، فإني ما ندمت ولا ندم"},{"id":"diwan-maarri:1315","bookId":"diwan-maarri","type":"poem","seq":1315,"chapter":"قصائد","title":"دنياي، ويحك! ما طرقتك مخ","page":"","text":"دنياي، ويحك! ما طرقتك مخ … تارا، ولكن القضاء حكم\nقضيت أيام الشباب على … مضض، وقد طال البقاء، فكم؟\nيكفيك أن المدح فيك يرى … كذبا وذما، في العقول، حكم\nوبنوك مثلك فيهم جبل … عال، وواد غائر، وأكم"},{"id":"diwan-maarri:1316","bookId":"diwan-maarri","type":"poem","seq":1316,"chapter":"قصائد","title":"الحرص في كل الأفانين يصم؛","page":"","text":"الحرص في كل الأفانين يصم؛ … أما رأيت كل ظهر ينقصم؟\nوعروة من كل حي تنقصم؛ … أما سمعت الحادثات تختصم؟\nأم حبك الأشياء يعمي ويصم؟ … -"},{"id":"diwan-maarri:1317","bookId":"diwan-maarri","type":"poem","seq":1317,"chapter":"قصائد","title":"صاحب الشرطة إن أنصفني،","page":"","text":"صاحب الشرطة إن أنصفني، … فهو خير لي من عدل ظلم\nمن أراد الخير فليعمل له، … فعليه لذوي اللب علم\nحكم الناس، غواة، مثل ما … حكمت، قبل، حصاة وزلم\nلا تهاون بصغير من عدى، … فقديما كسر الرمح القلم\nوترقب، من سليل، صنعه، … فمن البيع قياض وسلم\nيجمع الجنس شريفا ولقى، … كحديد، منه سيف وجلم\nخالد غاو، ونصر صالح، … ومن الأشجار نخل وسلم\nفازجر النفس، إذا ما أسرفت؛ … فمتى لم يقصص الظفر كلم\nرب شيخ ظل يهديه، إلى … سبل الحق، غلام ما احتلم\nوكأن الشر أصل فيهم، … وكذا النور حديث في الظلم\nأعجب الغضب لما هذ، فقد … كل، أو صادف بؤسا، فانثلم\nومع الضير بلوغ للمنى؛ … ومع النفع شكاة وألم"},{"id":"diwan-maarri:1318","bookId":"diwan-maarri","type":"poem","seq":1318,"chapter":"قصائد","title":"رب! متى أرحل عن هذه ال","page":"","text":"رب! متى أرحل عن هذه ال … دنيا، فإني قد أطلت المقام\nلم أدر ما نجمي، ولكنه … في النحس، مذ كان، جرى واستقام\nفلا صديق يترجى يدي؛ … ولا عدو يتخشى انتقام\nوالعيش سقم، للفتى، منصب؛ … والموت يأتي بشفاء السقام\nوالترب مثواي ومثواهم؛ … وما رأينا أحدا منه قام"},{"id":"diwan-maarri:1319","bookId":"diwan-maarri","type":"poem","seq":1319,"chapter":"قصائد","title":"والدنا الدهر به طيشة،","page":"","text":"والدنا الدهر به طيشة، … فليس فيه من بنيه حليم\nما ركب المرء سوى ظالم، … يعدو إلى الفتنة عدو الظليم\nدنياهم نار بلا جنة، … فالقوم منها في عذاب أليم\nمستلمين الركن، مستلئمي … ن السرد، كل منهم مستليم\nرب! متى أرحل عن عالمي؟ … فأنت بالناس خبير عليم\nفالمالك المملوك، والموسر ال … معسر، والسالم مثل السليم\nما نال فرعون بها نعمة؛ … ولا صفا عيش لموسى الكليم"},{"id":"diwan-maarri:1320","bookId":"diwan-maarri","type":"poem","seq":1320,"chapter":"قصائد","title":"روحي كالنار أذابت دمي","page":"","text":"روحي كالنار أذابت دمي … غليا، فلما بردت غاض دم\nلا تقدم، الدهر، على مأثم؛ … واستغفر الواحد رب القدم\nشربت بالعسجد، عن عزة، … ومشربي من خزف أو أدم\nأعوذ بالخالق من معشر، … إذا غلت قدرهم لم تدم\nهذي نجوم شاهدت تبعا، … ومن مضى من حمير، أو قدم\nبروجها كالبرج في الأرض، إن … طال مداه في العصور انهدم\nفاندم على الذنب، إذا جئته، … فمن شروط التائبين الندم\nوالخدم الأحجال في اللفظ وال … مقصد، كالقوم دعوا بالخدم\nماهنة الجسم هي الرجل، وال … خلخال، في المنزل، عند القدم\nوالمال كالتابع، أهون به، … ورب يسر في قوام العدم"},{"id":"diwan-maarri:1321","bookId":"diwan-maarri","type":"poem","seq":1321,"chapter":"قصائد","title":"رب درفس، خلفه ذائب،","page":"","text":"رب درفس، خلفه ذائب، … أروح من رب الدرفس العلم\nليس الفتى من رأسه مبدلا … رأسا، كما يفعل باري القلم\nوهذه الدنيا، على أنها … محبوبة، لم تخلنا من ألم\nيلام ذو اليسر، وأي امرىء، … أدرك منها طرفا، لم يلم؟\nقد يوجد الكهل حليف النهى … كأنه من جهله ما احتلم\nكان تقيا، قبل إمكانه، … حتى إذا مكن منها ظلم\nيحسب أن الصبح باد له، … وهو، نهارا، خابط في الظلم\nومن بديع الجور، ما بيننا، … حربك من ألقى إليك السلم\nإن إناء الخير من عسجد، … لوخر هضب، فوقه، ما انثلم\nإن زجر الله حديدا نبا، … أو أمر الله حريرا كلم\nأروح من عيش، جنى لي أذى، … موت أتاني راحة، واصطلم\nطيف حمام زارني في الكرى؛ … فمرحبا بالطيف لما ألم\nأينكر التقليد مستبصر، … قبل ركن البيت، ثم استلم؟\nوالجذع الأزلم لم يبق ذا … رمح، من الناس، ولا ذا زلم"},{"id":"diwan-maarri:1322","bookId":"diwan-maarri","type":"poem","seq":1322,"chapter":"قصائد","title":"يا أمة، في التراب، هامدة،","page":"","text":"يا أمة، في التراب، هامدة، … تجاوز الله عن سرائركم\nيا ليتكم لم تطوا إماءكم، … ولا دنوتم إلى حرائركم\nإن استرحتم مما نكابده، … فنحن، من بعد، في جرائركم\nقد خطب الخاطبون نسوتكم، … وأسكت الحس من ضرائركم\nذر البلى، فوقكم، رمادته، … ولم تعودوا إلى ذرائركم\nلو شاء ربي أمر، مقتدرا، … ما نقض الموت من مرائركم"},{"id":"diwan-maarri:1323","bookId":"diwan-maarri","type":"poem","seq":1323,"chapter":"قصائد","title":"إن أكلتم فضلا، وأنفقتم فض","page":"","text":"إن أكلتم فضلا، وأنفقتم فض … لا، فلا يدخلن وال عليكم\nلا تولوا أموركم أيدي النا … س، إذا ردت الأمور إليكم"},{"id":"diwan-maarri:1324","bookId":"diwan-maarri","type":"poem","seq":1324,"chapter":"قصائد","title":"قد ندمنا على القبيح، فأمسي","page":"","text":"قد ندمنا على القبيح، فأمسي … نا، على غير قهوة نتنادم\nخالق، لا يشك فيه، قديم، … وزمان، على الأنام، تقادم\nجائز أن يكون آدم، هذا، … قبله آدم على إثر آدم\nخدم الله غيرنا، وأرانا … أهل غي لربنا نتخادم\nلست أنفي عن قدرة الله أشبا … ح ضياء، بغير لحم ولا دم\nوبصير الأقوام مثلي، أعمى، … فهلموا في حندس نتصادم"},{"id":"diwan-maarri:1325","bookId":"diwan-maarri","type":"poem","seq":1325,"chapter":"قصائد","title":"أعوز الشث والسلم،","page":"","text":"أعوز الشث والسلم، … وأديمي به حلم\nفهنيئا لمن مضى، … قبل أن يجري القلم\nلم تصب جسمه الكلو … م، ولا دينه كلم\nإنما صاحب التقى … تاجر، يدفع السلم\nعجب الناس للجنين، … إذا مسه الألم\nعلم الله أنه … إن يطل عمره ظلم\nأصبح الشيخ ماردا، … بعدما حج واستلم\nخط أمر لفاعل، … إن يجىء غيره يلم\nمن فتى يعرف الهلا … ل غلاما قد احتلم\nوسهيلا مع المعا … شر في كفه زلم\nخبط القوم في الضلا … ل، فهل تكشف الظلم؟\nفي بلاد مضلة، … ليس، في أرضها، علم\nدونها يقصر الخيا … ل، إذا طيفه ألم"},{"id":"diwan-maarri:1326","bookId":"diwan-maarri","type":"poem","seq":1326,"chapter":"قصائد","title":"ألا فانعموا واحذروا، في الحياة،","page":"","text":"ألا فانعموا واحذروا، في الحياة، … ملما، يسمى مزيل النعم\nأرى قدرا بث أحداثه، … فخص بهن أناسا، وعم\nوإن القنا حملتها الأكف … لطعن الكماة، وشل النعم\nفلا تأمنوا الشر من صاحب، … وإن كان خالا لكم، وابن عم\nأتوكم بإقبالهم والحسام، … فشد به زاعم ما زعم\nتلوا باطلا، وجلوا صارما، … وقالوا: صدقنا! فقلتم: نعم!\nأفيقوا، فإن أحاديثهم … ضعاف القواعد والمدعم\nزخارف ما ثبتت في العقو … ل، عمى عليكم بهن المعم\nيدول الزمان لغير الكرام، … وتضحي ممالك قوم طعم\nوما تشعر الإبل أن الركاب … أعمت إلى الرمل، أم لم تعم"},{"id":"diwan-maarri:1327","bookId":"diwan-maarri","type":"poem","seq":1327,"chapter":"قصائد","title":"إذا مدحوا آدميا مدح","page":"","text":"إذا مدحوا آدميا مدح … ت مولى الموالي، ورب الأمم\nوذاك الغني عن المادحين، … ولكن لنفسي عقدت الذمم\nله سجد الشامخ المشمخر، … على ما بعرنينه من شمم\nومغفرة الله مرجوة، … إذا حبست أعظمي في الرمم\nمجاور قوم تمشى الفنا … ء ما بين أقدامهم، والقمم\nفيا ليتني هامد، لا أقوم، … إذا نهضوا ينفضون اللمم\nونادى المنادي على غفلة، … فلم يبق في أذن من صمم\nوجاءت صحائف، قد ضمنت … كبائر آثامهم واللمم\nفليت العقوبة تحريقة، … فصاروا رمادا بها، أو حمم\nرأيت بني الدهر في غفلة، … وليست جهالتهم بالأمم\nفنسك أناس لضعف العقول؛ … ونسك أناس لبعد الهمم"},{"id":"diwan-maarri:1328","bookId":"diwan-maarri","type":"poem","seq":1328,"chapter":"قصائد","title":"إذا دارت الكأس في دارهم،","page":"","text":"إذا دارت الكأس في دارهم، … فقد رحل الدين عن دارهم\nفما وفقوا عند إيرادهم؛ … ولا وفقوا عند إصدارهم\nوفي رفع أصواتهم، بالغناء، … دليل على حط أقدارهم\nفإن كنت خدنا لهم، فاحبهم … جفاء، على قرب مزدارهم"},{"id":"diwan-maarri:1329","bookId":"diwan-maarri","type":"poem","seq":1329,"chapter":"قصائد","title":"أدين برب واحد وتجنب","page":"","text":"أدين برب واحد وتجنب … قبيح المساعي، حين يظلم دائن\nلعمري، لقد خادعت نفسي برهة، … وصدقت في أشياء من هو مائن\nوخانتني الدنيا مرارا، وإنما … يجهز بالذم الغواني الخوائن\nأعلل بالآمال قلبا مضللا، … كأني لم أشعر بأني حائن\nيحدثنا عما يكون منجم، … ولم يدر، إلا الله، ما هو كائن\nويذكر من شأن القران شدائدا، … وفي أي دهر لم تبت القرائن\nأرى الحيرة البيضاء حارت قصورها … خلاء، ولم يثبت لكسرى المدائن\nوهجن، لذات الملوك، زوالها، … كما غدرت بالمنذرين الهجائن\nركبنا على الأعمار، والدهر لجة، … فما صبرت، للموج، تلك السفائن\nلقد حمد الأبناء قوم، وطالما … أتتك من الأهل الشرور الدفائن\nكنائن صدق كثرت عدد الفتى، … فهن بحق، للسهام، كنائن\nتجيء الرزايا بالمنايا، كأنما … نفوس البرايا، للحمام، رهائن\nتنطس، في كتب الوثائق، خائف … منيته، والمرء لا بد بائن\nيضن عليها، بالثمين، حليلها، … وتودع، في الأرض، الشخوص الثمائن\nيخاف، إذا حل الثرى، أن يقينها … لآخر من بعض الرجال، القوائن\nيصون الكريم العرض بالمال جاهدا، … وذو اللؤم، للأموال، بالعرض صائن\nمتى ما تجد مسترفد الجود شاتما، … ففي البخل، للوجه الذي ذين، ذائن"},{"id":"diwan-maarri:1330","bookId":"diwan-maarri","type":"poem","seq":1330,"chapter":"قصائد","title":"لعمرك، ما الدنيا بدار إقامة؛","page":"","text":"لعمرك، ما الدنيا بدار إقامة؛ … ولا الحي، في حال السلامة، آمن\nوإن وليدا حلها لمعذب، … جرت لسواه، بالسعود، الأيامن\nونال بنوها ما حبتهم جدودهم، … على أن جد المرء في الجد كامن"},{"id":"diwan-maarri:1331","bookId":"diwan-maarri","type":"poem","seq":1331,"chapter":"قصائد","title":"عجبت لكهل قاعد بين نسوة،","page":"","text":"عجبت لكهل قاعد بين نسوة، … يقات بما ردت عليه الروادن\nيعال على ذم، ويزجر عن قلى، … كما زجرت، بين الجياد، الكوادن\nيكاد الورى لا يعرف الخير بعضه، … على أنه كالترب، فيه معادن\nتحاربنا أيامنا، ولنا رضا … بذلك، لو أن المنايا تهادن\nإذا كان جسمي، للرغام، أكيلة، … فكيف يسر النفس أني بادن؟\nومن شر أخدان الفتى أم زنبق، … وتلك عجوز أهلكت من تخادن\nتخبر عن أسراره قرناءه، … ومن دونها قفل منيع وسادن"},{"id":"diwan-maarri:1332","bookId":"diwan-maarri","type":"poem","seq":1332,"chapter":"قصائد","title":"إذا عدت الأوطان في كل بلدة،","page":"","text":"إذا عدت الأوطان في كل بلدة، … لقوم، سجونا، فالقبور حصون\nوما كان هذا العيش إلا إذالة؛ … فعل ترابا بالحمام يصون\nفكن بعض أشجار تقضت أصولها، … ولم يبق، في الدنيا، لهن غصون"},{"id":"diwan-maarri:1333","bookId":"diwan-maarri","type":"poem","seq":1333,"chapter":"قصائد","title":"وجدت سواد الرأس تقلب لونه،","page":"","text":"وجدت سواد الرأس تقلب لونه، … من الدهر، بيض، يختلفن، وجون\nفلا يغترر، بالملك، صاحب دولة، … فكم من ضياء غيبته دجون\nوإني أرى أنصار إبليس جمة، … ولا مثل ما أوفى له الزرجون\nفإن كانت الأرواح، بعد فراقها، … تنال رخاء، فالجسوم سجون\nوماء الصبا إن طال في الشخص مكثه، … أضر به بعد الصفاء أجون"},{"id":"diwan-maarri:1334","bookId":"diwan-maarri","type":"poem","seq":1334,"chapter":"قصائد","title":"كأن نجوم الليل زرق أسنة،","page":"","text":"كأن نجوم الليل زرق أسنة، … بها كل من فوق التراب طعين\nولولا عيون حاسرات متى رأت … مقيما، بوجه الأرض، قيل معين\nولائح هذا الفجر سيف مجرد، … أعان به صرف الزمان معين\nكأن قد حوتهم لعنة من مليكهم، … ومن لم يطع مولاه فهو لعين\nوأروح من عين، يظل انتسابها … إلى الإنس، وحش بالمهامه عين"},{"id":"diwan-maarri:1335","bookId":"diwan-maarri","type":"poem","seq":1335,"chapter":"قصائد","title":"لقد لجنت بالمال خوصاء ضامر،","page":"","text":"لقد لجنت بالمال خوصاء ضامر، … وكيف لها أن اللجين لجين؟\nونحن بنو هذا التراب، فلا تبت … مسر غرام أن يقال هجين\nحياتي تعذيب، وموتي راحة، … وكل ابن أنثى، في التراب، سجين\nأقبري بوهد أم وجين أحله، … فإن أديم الآدمي وجين"},{"id":"diwan-maarri:1336","bookId":"diwan-maarri","type":"poem","seq":1336,"chapter":"قصائد","title":"توهمت، يا مغرور، أنك دين،","page":"","text":"توهمت، يا مغرور، أنك دين، … علي يمين الله، ما لك دين\nتسير إلى البيت الحرام تنسكا، … ويشكوك جار بائس وخدين"},{"id":"diwan-maarri:1337","bookId":"diwan-maarri","type":"poem","seq":1337,"chapter":"قصائد","title":"أودى السرور بدار، كلها حزن،","page":"","text":"أودى السرور بدار، كلها حزن، … فلا تبال على ما صابت المزن\nقد غلب المين، حتى الصدق مستتر؛ … وغيب الرشد، حتى خفت الرزن\nمن لم يكن خازنا للمال من بخل، … فلا يخاف، على نحض له، خزن\nأكذب القوم بالميزان أن سمعوا … أن القيامة، فيها عادل يزن؟\nوقد وجدنا مقال الناس ذا زنة، … فكيف ينكر أن الفعل يتزن؟"},{"id":"diwan-maarri:1338","bookId":"diwan-maarri","type":"poem","seq":1338,"chapter":"قصائد","title":"إن الإران، أمام الحي، محتمل،","page":"","text":"إن الإران، أمام الحي، محتمل، … فكيف يدرك، أشباحا لنا، أرن؟\nلعل موتا يريح الجسم من نصب، … إن العناء، بهذا العيش، مقترن"},{"id":"diwan-maarri:1339","bookId":"diwan-maarri","type":"poem","seq":1339,"chapter":"قصائد","title":"ما كان في الأرض من خير ولا كرم","page":"","text":"ما كان في الأرض من خير ولا كرم … فضل من قال: إن الأكرمين فنوا\nوإنما نحن في سوداء طامية، … وهل تخلص، من أمثالها، السفن\nوالشيب أولى من الشبان لو عبطوا، … لأنه مكثب، من حتفه، اليفن\nأعفى المنازل قبر يستراح به، … وأفضل اللبس، فيما أعلم، الكفن\nإن الذين، على وجه الثرى، وطئوا … يشابهون أناسا، تحته، دفنوا\nالضاحكين، إذا ما خيض في سفه؛ … وإن أريدوا على أكرومة شفنوا\nوما أصابهم أفن، فغيرهم، … لكن أراهم، على طول المدى، أفنوا\nولا تنجي دروع، أهلها، سبغ؛ … ولا جياد، على أبوابهم، صفن\nإنا لركب ليال غير وانية، … فقوتلت من ركاب، ما لها ثفن"},{"id":"diwan-maarri:1340","bookId":"diwan-maarri","type":"poem","seq":1340,"chapter":"قصائد","title":"ما أقدر الله، أن يدعى بريته","page":"","text":"ما أقدر الله، أن يدعى بريته … من تربهم، فيعودوا كالذي كانوا\nوتودع، الناس في بطن الثرى، نوب: … خفض ورفع وتحريك وإسكان\nإن كان رضوى وقدس غير دائمة، … فهل تدوم لهذا الشخص أركان؟\nما أحسن الأرض لو كانت بغير أذى، … ونحن فيها، لذكر الله، سكان\nقد يمكن البعث إن نادى المليك به، … وليس منا، لدفع الشر، إمكان"},{"id":"diwan-maarri:1341","bookId":"diwan-maarri","type":"poem","seq":1341,"chapter":"قصائد","title":"يخبرونك عن رب العلى كذبا،","page":"","text":"يخبرونك عن رب العلى كذبا، … وما درى بشؤون الله إنسان\nوبالقضاء، لآساد الشرى، لجم، … وللوحوش، بإذن الله، أرسان\nفألسنوني أبين مشكلاتكم، … أم ليس فيكم، لأهل الحق، إلسان؟\nهل تسمعون، فإني فارس، أربي … من الفراسة، إذ للحرب فرسان\nما كان، في هذه الدنيا، أخو رشد … ولا يكون، ولا في الدهر، إحسان\nوإنما يتقضى الملك عن غير، … كما تقضت بنو نصر وغسان\nحستهم حادثات لم تبن أسفا، … كأن تأسف إثر القوم حسان\nبنو أمية، بالشامين، دين لهم، … والهاشميون والتهم خراسان\nولست آمن أن يدعى إمامكم، … من عالة الزنج، أو ربته ميسان\nوالرأي أن تبعث الأنضاء واحدة … إلى دمشق، فبئس الدار بيسان"},{"id":"diwan-maarri:1342","bookId":"diwan-maarri","type":"poem","seq":1342,"chapter":"قصائد","title":"يكفيك حزنا، ذهاب الصالحين معا،","page":"","text":"يكفيك حزنا، ذهاب الصالحين معا، … ونحن بعدهم، في الأرض، قطان\nإن العراق وإن الشام، مذ زمن، … صفران، ما بهما للملك سلطان\nساس الأنام شياطين مسلطة، … في كل مصر، من الوالين، شيطان\nمن ليس يحفل خمص الناس كلهم، … إن بات يشرب خمرا، وهو مبطان\nتشابه النجر: فالرومي منطقه … كمنطق العرب، والطائي مرطان\nأما كلاب، فأغنى من ثعالبهم، … كأن أرماحهم، في الحرب، أشطان\nمتى يقوم إمام يستقيد لنا، … فتعرف العدل أجبال وغيطان؟\nصلوا بحيث أردتم، فالبلاد أذى، … كأنما كلها، للإبل، أعطان"},{"id":"diwan-maarri:1343","bookId":"diwan-maarri","type":"poem","seq":1343,"chapter":"قصائد","title":"لا تعرف الوزن كفي، بل غدت أذني","page":"","text":"لا تعرف الوزن كفي، بل غدت أذني … وزانة، ولبعض القول ميزان\nوالأرض رقعة لعاب، مقسمة، … منها سهول وأجبال وحزان\nتغير الناس والدنيا بأجمعها، … حتى الفرائس، بعد الإبل، خزان\nوالسر ليس بمخزون على أحد، … لكن تكاثر، للأموال، خزان\nإن لم تحول فرازينا بياذقهم، … فالشاة فيل، وذاك الفيل فرزان\nولا مغني، بل مبد له أسفا، … كما يقول: بنو سراك حزان"},{"id":"diwan-maarri:1344","bookId":"diwan-maarri","type":"poem","seq":1344,"chapter":"قصائد","title":"تمنت شيعة الهجري نصرا،","page":"","text":"تمنت شيعة الهجري نصرا، … لعل الدهر يسهل فيه حزن\nوقد أضحت جماعتهم شريدا … فلا يفنى لهم أسف وحزن\nوقالوا: إنها ستعود يوما، … فينبت، ما سقى الآفاق مزن\nوبيت الشعر قطع لا لعيب، … ولكن عن تصحيح ووزن\nإذا أوتيت مالا، فابذلنه، … فما يبقيه توفير وخزن"},{"id":"diwan-maarri:1345","bookId":"diwan-maarri","type":"poem","seq":1345,"chapter":"قصائد","title":"سكونا خلت أقدم من حراك،","page":"","text":"سكونا خلت أقدم من حراك، … فيكف بقولنا حدث السكون؟\nوما في الناس أجهل من غبي، … يدوم له، إلى الدنيا، ركون\nمنازلنا، إذا ما الطير صيدت، … فما تبكي، من الأسف، الوكون\nوما كانت نوى، فنذم بينا؛ … ولكن، بعد أيام، تكون"},{"id":"diwan-maarri:1346","bookId":"diwan-maarri","type":"poem","seq":1346,"chapter":"قصائد","title":"لقد طال الزمان علي حتى","page":"","text":"لقد طال الزمان علي حتى … غدوت ولي، إلى الدنيا، ركون\nفلا أغرر، إذا أجلي خطاني، … سيأتي الموت، أغفل ما أكون\nويلحق بالثرى جسد هباء، … على حركاته ورد السكون"},{"id":"diwan-maarri:1347","bookId":"diwan-maarri","type":"poem","seq":1347,"chapter":"قصائد","title":"أتحملك الحصان، وأنت خال،","page":"","text":"أتحملك الحصان، وأنت خال، … وفي الهيجاء يحملك الحصان؟\nتصون الخيل تحتك من وجاها، … وإن جاء الحمام، فما تصان"},{"id":"diwan-maarri:1348","bookId":"diwan-maarri","type":"poem","seq":1348,"chapter":"قصائد","title":"ما أمس بالشبح الذي، إن مر بي،","page":"","text":"ما أمس بالشبح الذي، إن مر بي، … فرجوعه، من بعد ذلك، ممكن\nوالناس، بين حياتهم ومماتهم، … مثل الحروف محرك ومسكن\nلله طاعة ربنا من خلة، … فيها استوى فصحاؤنا والألكن"},{"id":"diwan-maarri:1349","bookId":"diwan-maarri","type":"poem","seq":1349,"chapter":"قصائد","title":"لباسي البرس، فلا أخضر،","page":"","text":"لباسي البرس، فلا أخضر، … ولا خلوقي، ولا أدكن\nوقوتي الشيء، أبى مثله … فصيح هذا الخلق، والألكن\nوأسأل الخالق، من عزه، … ما لم يكن، إلا له، يمكن\nسيرا إلى الموت، وعفوا، إذا … مت ففي الآخرة الموكن\nوالرفق بالنفس، لدى بينها … عن جسد ظلت به تسكن\nوكنت والناس إلى هذه ال … دنيا، فخانت عهد من يركن"},{"id":"diwan-maarri:1350","bookId":"diwan-maarri","type":"poem","seq":1350,"chapter":"قصائد","title":"هذي القضايا، فمن يطاولها،","page":"","text":"هذي القضايا، فمن يطاولها، … وهي المنايا، فمن يخاشنها؟\nلم يثن، عن فارس وحميرها، … دروعها الموت، أو جواشنها\nولا قصور لها مشيدة، … قد موهت عسجدا رواشنها\nوباد للروم أسرة عجب، … تعرف في ولدها شناشنها\nوكان، في طيىء وإخوتها، … مطاعم، لا يرد راشنها\nوآل قابوس أهل مملكة، … حاملة، وفدها، رعاشنها"},{"id":"diwan-maarri:1351","bookId":"diwan-maarri","type":"poem","seq":1351,"chapter":"قصائد","title":"أين عمرو لما دعا أم عمرو،","page":"","text":"أين عمرو لما دعا أم عمرو، … ولديها، من المدامة، صحن؟\nبئست الأم، للأنام، هي ال … دنيا، وبئس البنون للأم، نحن\nكلنا لا يبرها بمقال، … فاعذروها، إذ ليس بالفعل تحنو\nفسد الأمر كله، فاتركوا الإع … راب، إن الفصاحة، اليوم، لحن"},{"id":"diwan-maarri:1352","bookId":"diwan-maarri","type":"poem","seq":1352,"chapter":"قصائد","title":"كل ذكر من بعده نسيان،","page":"","text":"كل ذكر من بعده نسيان، … وتغيب الآثار والأعيان\nإنما هذه الحياة عناء، … فليخبرك، عن أذاها، العيان\nما يحس التراب ثقلا، إذا دي … س، ولا الماء، يتعب الجريان\nنفس، بعد مثله، يتقضى، … فتمر الدهور والأحيان\nقد ترامت، إلى الفساد، البرايا، … واستوت، في الضلالة، الأديان\nأنت في السهل أعوزتك الخزامى، … أو على النيق ما به الطيان\nطال صبري، فقيل: أكثم شبعا … ن، وإني لمنطو طيان\nأنا أعمى، فكيف أهدى إلى المن … هج، والناس كلهم عميان؟\nوالعصا، للضرير، خير من القا … ئد، فيه الفجور والعصيان\nوادعى الهدي، في الأنام، رجال، … صح لي أن هديهم طغيان\nفلك دائر، أبى فتياه … ونية، أو يفرق الفتيان\nونفوس تروم إرثا، وما الوا … رث إلا المهيمن الديان\nونبات البلاد، فيه الجبائي، … ومنه الوشيج والشريان\nإن تملىء بالهم كاسي دنيا … ي، فكاسي نعيمها عريان\nيبتني راغب، فما تكمل الرغ … بة، حتى يهدم البنيان\nوخيول، من الحوادث، تردى، … والردى شأنهن، لا الرديان\nناعبات، كما غدت ناعيات، … وحمام، كما تغنى القيان\nليس، في هذه المجرة، ماء، … فيرجي وروده الصديان"},{"id":"diwan-maarri:1353","bookId":"diwan-maarri","type":"poem","seq":1353,"chapter":"قصائد","title":"أصاح! إذا ما أتاك القضاء،","page":"","text":"أصاح! إذا ما أتاك القضاء، … لم يقك الدرع والجوشن\nفلا يشكونك جار الفناء، … يقول: تعدى له روشن\nفإن الذين أحبوا الخلو … د، لانوا، من الخوف، واخشوشنوا"},{"id":"diwan-maarri:1354","bookId":"diwan-maarri","type":"poem","seq":1354,"chapter":"قصائد","title":"لبيب إلى الدهر لا يركن،","page":"","text":"لبيب إلى الدهر لا يركن، … وإنقاذي النفس لا يمكن\nفحسبي، من المال، قوتي به؛ … وحسبي، من البلد، المسكن"},{"id":"diwan-maarri:1355","bookId":"diwan-maarri","type":"poem","seq":1355,"chapter":"قصائد","title":"أقمت برغمي، وما طائري","page":"","text":"أقمت برغمي، وما طائري … براض، إذا ألفته الوكون\nولي أمل كأتم القنا، … وحال كأقصر سهم يكون\nفيا ألف اللفظ لا تأملي … حراكا، فما لك إلا السكون"},{"id":"diwan-maarri:1356","bookId":"diwan-maarri","type":"poem","seq":1356,"chapter":"قصائد","title":"إذا أعمل الفكر الفتى جعل الغنى،","page":"","text":"إذا أعمل الفكر الفتى جعل الغنى، … من المال، فقرا، والسرور به حزنا\nيكون وكيلا للبرية باذلا، … وللوارثيه، إن أراد له خزنا\nويصبح منثور البلى كنظيمة، … بناها عبيد، لا يقيم لها وزنا\nوفي الأرض من يستمطر السيف رزقه … إذا كان بعض القوم يستمطر المزنا\nعرفنا به خير الزمان وشره، … أجل، ووطئنا فوقها السهل والحزنا\nويطمع، في ورد السراب، معاشر، … وسوف يروزون الخطوب كما رزنا"},{"id":"diwan-maarri:1357","bookId":"diwan-maarri","type":"poem","seq":1357,"chapter":"قصائد","title":"سترعى، إذا ألفيت، للفظ، خازنا،","page":"","text":"سترعى، إذا ألفيت، للفظ، خازنا، … وتدهى، إذا حسنت، للذهب، الخزنا\nفأنفق، بميزان، مقالك، وابتعث … يديك، بما أوتيت وزنا ولا وزنا\nوكم نسوة ربين، كالنخل، فتية، … فحزن بما أمكن من ولد حزنا"},{"id":"diwan-maarri:1358","bookId":"diwan-maarri","type":"poem","seq":1358,"chapter":"قصائد","title":"لعمري! لقد نام الفتى عن حمامه،","page":"","text":"لعمري! لقد نام الفتى عن حمامه، … إلى أن أتاه حتفه متوسنا\nإذا ما فعلت الخير، فاجعله خالصا … لربك، وازجر عن مديحك ألسنا\nفكونك، في هذي الحياة، مصيبة، … يعزيك عنها أن تبر وتحسنا"},{"id":"diwan-maarri:1359","bookId":"diwan-maarri","type":"poem","seq":1359,"chapter":"قصائد","title":"حرام على النفس الخبيثة بينها","page":"","text":"حرام على النفس الخبيثة بينها … عن الجسم، حتى تجزي السوء محسنا\nفلا تسد للنفس الجميل، وأسده، … لربك، وانفض عن عيون توسنا"},{"id":"diwan-maarri:1360","bookId":"diwan-maarri","type":"poem","seq":1360,"chapter":"قصائد","title":"غنينا عصورا في عوالم جمة،","page":"","text":"غنينا عصورا في عوالم جمة، … فلم نلق إلا عالما متلاعنا\nإذا فاتهم طعن الرماح، فمحفل … ترى فيه مطعونا عليه وطاعنا\nهنيئا لطفل أزمع السير عنهم، … فودع، من قبل التعارف، ظاعنا"},{"id":"diwan-maarri:1361","bookId":"diwan-maarri","type":"poem","seq":1361,"chapter":"قصائد","title":"روح تعدن، قضي اليوم وانتظري","page":"","text":"روح تعدن، قضي اليوم وانتظري … غدا، لعلي فيه أدرك العدنا\nوديدن الجد مملوك، تنافره … كل النفوس، وتهوى اللهو والددنا\nفدى لنفسك نفسي، آوني جدثا … من الخفيات، لا قصرا ولا فدنا\nوابدأ ببدنك، فاهضم منه طائفة، … من قبل سوقك، في أصحابك، البدنا\nفإن جنة عدن لا يجاد بها … إلا لصاحب دين، في أذى عدنا\nليث كفادر فزر، لبسه شعر، … وكالرديني آلى يلبس الردنا\nوالعيش، يلقى بصخر من يمارسه، … ولن يدوم على حال، إذا لدنا\nتحسمت منه أيام منغصة، … من بعد ما ود في ودان، أو ودنا\nوالغي ثوب، إذا لم يستلب رجلا، … بالرغم، لم تحسر التقوى له ردنا\nكالدر يمنع منه الطفل، مقتسرا، … ولم يجانبه من زهد، وقد شدنا\nأما الشرور، فلن تلفى بمقفرة، … إلا قليلا، ولكن تألف المدنا\nإني لعمرك، ما أرجو، لعالمنا، … هدى يثبت، في أفنائنا، الهدنا\nوالحظ أغلب، كم بيت لمكرمة، … سدى، يظل، وبيت للخنى سدنا"},{"id":"diwan-maarri:1362","bookId":"diwan-maarri","type":"poem","seq":1362,"chapter":"قصائد","title":"إن تاب إبليس، يوما، تاب عابدكم","page":"","text":"إن تاب إبليس، يوما، تاب عابدكم … من الضلال، ولن تلقوا فتى فتنا\nوعمنا الغي، حتى خلتنا دمثا … مقابلا، من سفاه، عارضا هتنا\nغنينا، من عفاف النفس، أفقرنا؛ … وقيلنا علج وحش يألف الأتنا"},{"id":"diwan-maarri:1363","bookId":"diwan-maarri","type":"poem","seq":1363,"chapter":"قصائد","title":"ينسى الحوادث أفتانا وأكبرنا،","page":"","text":"ينسى الحوادث أفتانا وأكبرنا، … ولن تصيب فؤادا حاملا حزنا\nلا يفرحن، بهذا المال، جامعه، … ليحزننك صافي التبر إن خزنا\nيعد بيت نضار بيت قافية، … لو زال منه القليل النزر ما اتزنا"},{"id":"diwan-maarri:1364","bookId":"diwan-maarri","type":"poem","seq":1364,"chapter":"قصائد","title":"لنا طباع، وجدنا العقل يأمرها،","page":"","text":"لنا طباع، وجدنا العقل يأمرها، … فلا تريد، من الأخلاق، ما حسنا\nأخوك، إن عز، علج في أوابده؛ … وإن يذل، فعير آهل رسنا\nنحن المياه، أقامت في مواطنها، … وطال وقت، فأمسى كلها أسنا\nإن الليالي قالت، وهي صامتة: … ما أبلغ الدهر، لا من يدعي اللسنا\nسبحان خالق هذي الشهب، دائبة، … سارت وأسرت فلا أينا ولا وسنا\nوالشمس تغمر أهل الأرض مصلحة، … ربت جسوما، وفيها للعيون سنا"},{"id":"diwan-maarri:1365","bookId":"diwan-maarri","type":"poem","seq":1365,"chapter":"قصائد","title":"لو كانت الخمر حلا ما سمحت بها","page":"","text":"لو كانت الخمر حلا ما سمحت بها … لنفسي، الدهر، لا سرا ولا علنا\nفليغفر الله، كم تطغى مآربنا، … وربنا قد أحل الطيبات لنا"},{"id":"diwan-maarri:1366","bookId":"diwan-maarri","type":"poem","seq":1366,"chapter":"قصائد","title":"باهى رجال، وفي جهل يباهونا،","page":"","text":"باهى رجال، وفي جهل يباهونا، … لاهون في النسك، إن ألغاه لاهونا\nناهوك عن حسن فعل آمروك به، … والآمرون بسوء الفعل ناهونا\nخلت النجوم تنادي: أنجموا فرقا، … أو السهى قال: أهل الأرض ساهونا\nطهت لك الشمس ما يغني أخا دعة … عن أن يكون له، في الأرض، طاهونا\nذرية الإنس! لا تزهوا، فإنكم … ذرا تعدون، أو نملا تضاهونا\nتأبى الحوادث نقص الدهر تومنة، … وأهون الخطب أن القوم واهونا"},{"id":"diwan-maarri:1367","bookId":"diwan-maarri","type":"poem","seq":1367,"chapter":"قصائد","title":"أكرم نزيلك واحذر من غوائله،","page":"","text":"أكرم نزيلك واحذر من غوائله، … فليس خلك، عند الشر، مأمونا\nوغالب الحال في الجيران أنهم … نكد، يلومون جارا، أو يلامونا\nتنام أعين قوم عن ذخائرهم، … والطالبون أذاهم ما ينامونا\nأحلل بمن شئت لا يعدمك نائبة؛ … خان اليمانون طرا، والشآمونا\nحي تنوع من نام ومن جمد، … فالنبت والوحش والإنسي نامونا\nهل تشعر الأرض ديست والتراب، إذا … أهيل، مثل أناس يستضامونا؟\nأم ذلك العالم الحساس خالصة، … فيستحقون حمدا، أو يذامونا؟\nبتم تسامون من نيل العلى رتبا، … فهل علمتم يقينا ما تسامونا؟"},{"id":"diwan-maarri:1368","bookId":"diwan-maarri","type":"poem","seq":1368,"chapter":"قصائد","title":"يا قوت! ما أنت ياقوت ولا ذهب،","page":"","text":"يا قوت! ما أنت ياقوت ولا ذهب، … فكيف تعجز أقواما مساكينا؟\nوأحسب الناس، لو أعطوا زكاتهم، … لما رأيت بني الإعدام شاكينا\nفإن تعش تبصر الباكين قد ضحكوا، … والضاحكين، لفرط الجهل، باكينا\nفجانب القوم، إن زكوا نفوسهم، … فليس حلال دنيانا بزاكينا\nيسقونك الغي صرفا، إن أطعتهم، … وقد علمتهم، للمين، حاكينا\nلا يتركن قليل الخير، يفعله … من نال، في الأرض، تأييدا وتمكينا\nفالطبع يكسر بيتا، أو يقومه، … بأهون السعي تحريكا وتسكينا"},{"id":"diwan-maarri:1369","bookId":"diwan-maarri","type":"poem","seq":1369,"chapter":"قصائد","title":"رب الجواد فرى عينا لمأكله،","page":"","text":"رب الجواد فرى عينا لمأكله، … فعد من رهط أقوام فراعينا\nقل للمطاعيم، تعصيهم ضيوفهم: … إن المطاعين، يمسون المطاعينا\nويحمد المرء، في الساعين، مبتكرا، … وليس يحمد يوما في المساعينا\nوما تزال تلاقي، في دجى وضحى، … مبشرين، بلا بشرى، وناعينا\nوما وجدت صروف الدهر ناكبة … عن قانتين، لوجه الله، داعينا\nشر النساء مشاعات غدون سدى، … كالأرض يحملن أولادا مشاعينا\nوالأمر لله، كم أودى فتى ومضى، … عينا، وخلف أطفالا مضاعينا\nوالعيش أوفاه يمضي مثل أقصره، … سبع كسبعين، أو تسع كتسعينا\nولو تراعين مولى الناس كلهم، … ما كنت من نوب الدنيا تراعينا"},{"id":"diwan-maarri:1370","bookId":"diwan-maarri","type":"poem","seq":1370,"chapter":"قصائد","title":"لقد أتوا بحديث لا يثبته","page":"","text":"لقد أتوا بحديث لا يثبته … عقل، فقلنا: عن أي الناس تحكونه؟\nفأخبروا بأسانيد لهم كذب، … لم تخل من كر شيخ لا يزكونه\nعجبت للأم، لما فات واحدها، … بكت، وساعدها ناس يبكونه\nوكل يوم تداعى منهم نفر، … لبالغ السن، أو طفل يذكونه\nوينصبون لوحشي حبائلهم، … أو بالسهام، على عمد، يشكونه\nهم أسارى مناياهم، فما لهم، … إذا أتاهم أسير، لا يفكونه؟\nفلو تكلم دهر كان شاكيهم، … كما تراهم، على الإحسان، يشكونه\nأما ترون ديار القوم خالية، … بعد الجماعات، والأجداث مسكونه"},{"id":"diwan-maarri:1371","bookId":"diwan-maarri","type":"poem","seq":1371,"chapter":"قصائد","title":"العيش ثقل، وقاضي الأرض ممتحن،","page":"","text":"العيش ثقل، وقاضي الأرض ممتحن، … يضحي ونصف خصوم المصر يشكونه\nزكوه دهرا، فلما صار قاضيهم، … واستعمل الحق، عادوا لا يزكونه\nيصوم ناس عن الزاد المباح لهم، … ويغتذون بلحم لا يذكونه"},{"id":"diwan-maarri:1372","bookId":"diwan-maarri","type":"poem","seq":1372,"chapter":"قصائد","title":"إن خرف الدهر، فهو شيخ،","page":"","text":"إن خرف الدهر، فهو شيخ، … يحق بالهتر والزمانه\nأضحى سليما بغير داء، … لم تبد، في شخصه، ضمانه\nإن قالت الشهب: نحن رهط … أقدم منه، فهن مانه\nأعجم قد بين الرزايا، … أو جعل الشر ترجمانه\nفأودعن فاتكا حصاة، … وأودعن ناسكا جمانه\nكلاهما ليس بالمؤدي … إليك، في المودع، الأمانه"},{"id":"diwan-maarri:1373","bookId":"diwan-maarri","type":"poem","seq":1373,"chapter":"قصائد","title":"جمجم هذا الزمان قولا،","page":"","text":"جمجم هذا الزمان قولا، … وكلنا يرتجي بيانه\nوحدثتنا الشيوخ أمرا، … وما ادعى مخبر عيانه\nفكائن فاسد لأمر، … وربه مفسد كيانه\nما بالنا في شقاء عيش، … وإنما نبتغي ليانه\nدنياك دار قد اصطلحنا، … فيها، على قلة الديانه\nكأنها قينة خلوب … ما عرفت، قط، بالصيانه\nمن لم ينلها أراك زهدا، … ومن لعير بصليانه؟\nما خان ذاك الفتى، ولكن … حث سواه على الخيانه"},{"id":"diwan-maarri:1374","bookId":"diwan-maarri","type":"poem","seq":1374,"chapter":"قصائد","title":"لأمواه الشبيبة كيف غضنه،","page":"","text":"لأمواه الشبيبة كيف غضنه، … وروضات الصبا كاليبس إضنه\nوآمال النفوس معللات، … ولكن الحوادث يعترضنه\nفلا الأيام تغرض من أذاة؛ … ولا المهجات، من عيش، غرضنه\nوأسباب المنى أسباب شعر، … كففن بعلم ربك، أو قبضنه\nوما الظبيات مني خائفات، … وردن على الأصائل، أو ربضنه\nفلا تأخذ ودائع ذات ريش، … فما لك أيها الإنسان بضنه\nفراع الله واله عن الغواني، … يرحن ليمتشطن ويرتحضنه\nوطئن السابري وخضن بحر الن … عيم، وهن، في ذهب، يخضنه\nوللسمرات، في الأشجار، عيب … إذا ما قال مخبرهن: حضنه\nنجائب لامرىء القيس بن حجر، … وقصن أخا البطالة، إذ يرضنه\nوخيل اللهو جامحة علينا، … يساقطن الفوارس، إن ركضنه\nفيا غضا من الفتيان، خير … من اللحظات أبصار غضضنه\nففض زكاة مالك غير آب، … فكل جموع مالك ينفضضنه\nوأعجز أهل هذي الأرض غاو، … أبان العجز عن خمس فرضنه\nوصم رمضان مختارا مطيعا، … إذ الأقدام من قيظ رمضنه\nعيون العالمين إلى اغتماض، … وما خلت الكواكب يغتمضنه\nوقد سر المعاشر باقيات … من الأنباء، سرن ليستفضنه\nأرى الأزمان أوعية لذكر، … إذا بسط الأوان له نفضنه\nقد انقرضت ممالك آل كسرى، … سوى سير لهن سينقرضنه\nفطر إن كنت يوما ذا جناح، … فإن قوادم البازي يهضنه\nوكم طير قصصن لغير ذنب، … وألزمن السجون، فما نهضنه\nمتى عرض الحجى لله ضاقت … مذاهبه عليه، وإن عرضنه\nوقد كذب الذي يغدو بعقل … لتصحيح الشروع، إذا مرضنه\nهي الأشباح كالأسماء، يجري ال … قضاء، فيرتفعن وينخفضنه\nوتلك غمائم الدنيا اللواتي … يسفهن الحليم، إذا ومضنه\nغدت حجج الكلام حجا غدير، … وشيكا ينعقدن وينتقضنه\nلعل الظاعنات عن البرايا، … من الأرواح، فزن بما استعضنه\nوللأشياء علات، ولولا … خطوب للجسوم لما رفضنه\nوغارت، لانصرام حيا، مياه، … وكن، على ترادفه، يفضنه"},{"id":"diwan-maarri:1375","bookId":"diwan-maarri","type":"poem","seq":1375,"chapter":"قصائد","title":"تهاون بالظنون وما حدسنه،","page":"","text":"تهاون بالظنون وما حدسنه، … ولا تخش الظباء متى كنسنه\nوأوقات الصبا، في كل عصر، … أراقم، والمنية ما قلسنه\nيجدن بهين ويعدن فيه، … أليس، بعلم ربك، قد ألسنه؟\nيلسن شخوص أهل الأرض، حتى … يسخن، وراء ذلك، ما يلسنه\nوما أنا والظعائن سائرات، … أغرن، مع الغوائر، أو جلسنه\nضربت لجاهل مثل الغواني، … قلبن، وما رأبن، غداة رسنه\nهي النيران، تحسن من بعيد، … وتحرقن الأكف، إذا لمسنه\nأخذن اللب أجمع، ظاعنات، … فعدن وما ربعن وما خمسنه\nإذا مدت روامقها إليها … قوابس، لم يعجن بما قبسنه\nولولا أنهن أذى وكيد، … لما أصبحن في كلل حبسنه\nثغور محارب منعت هجوعا، … ثغورا، في مضاحكها، غرسنه\nتشابهت الخلائق والبرايا، … وإن مازتهم صور ركسنه\nوجرم، في الحقيقة، مثل جمر، … ولكن الحروف به عكسنه\nغنى زيد يكون لفقر عمرو، … وأحكام الحوادث لا يقسنه\nكأنك، إن بقيت على الليالي، … بأعلام الولاة، وقد نكسنه\nوخير الرزق ما وافاك عفوا، … فخل فضول أموال مكسنه\nوليت نفوسنا، والحق آت، … ذهبن كما أتين وما أحسنه\nقدمنا، والقوابل ضاحكات؛ … وسرنا، والمدامع ينبجسنه\nعناصرنا طواهر غير شك؛ … فيا أسفا لأجسام نجسنه!\nويرجو أن يزيل الغل صاد، … إذا سمع الرواعد يرتجسنه\nوقد زعم الزواعم، وافتكرنا؛ … فويح للخواطر ما هجسنه\nومن يتأمل الأيام تسهل … عليه النائبات، وإن بخسنه\nولو صرف الهدى بجميل فعل … إلى مهج نفسن، لما نفسنه\nومن يحمد، لعيشته، ليانا، … يذم الغب أخلاقا شرسنه\nوما الأحراس إلا أمهات، … أكسن الناجيات، وما أكسنه\nتحاسدت العيون على منام، … عرفن كذابه، وأردن حسنه\nفصبرا، إن سمعت لسان سوء … من ابن مودة، وتوق لسنه\nفإن الورد من ملح أجاج، … أجئت لشربه، وعرفت أسنه\nولولا ضعف أرواح أعرنا … سفاها، ما ابتهجن ولا ابتأسنه\nوإن ملوك غسان تقضوا، … ولم يترك لهم، في الملك، غسنه\nوفارس عز منها، كل راع، … أسود للمقادر يفترسنه\nوهد جبالها أقيال فهر، … فتلك ربوعها آيا طمسنه\nيذيبون النضار بكل مشتى، … إذا الأمواه من قر جمسنه\nوقد حرس الممالك حي لخم، … فغالتهم نوائب يحترسنه\nشكا الركب السهاد، فلم يعيجوا … بأشباح، على قلق، ينسنه\nوكم قطعت سواري الشهب، ليلا، … سواهد ما هجعن، ولا نعسنه\nهواك مشابه فرسا جموحا، … وما ألجمته، فعليك رسنه\nولا يعجبك روض، باكرته … غمائمه، وأغصان يمسنه\nولا الأفواه تضحك عن غريض، … فرائد في مدامتها غمسنه\nتنعمت الخوافض في مقام، … فكيف الناعمات، إذا رمسنه؟\nفأين القائلات بلا اقتصاد، … أألغين التكلم أم خرسنه؟\nملأن مواضي الأزمان قولا، … وألزمن السكوت، فما نبسنه\nألم ترني حميت بنات صدري، … فما زوجتهن، وقد عنسنه\nولا أبرزتهن إلى أنيس، … إذا نور الوحوش به أنسنه\nوقال الفارسون: حليف زهد، … وأخطأت الظنون بما فرسنه\nورضت صعاب آمالي، فكانت … خيولا، في مراتعها، شمسنه\nولم أعرض عن اللذات، إلا … لأن خيارها عني خنسنه\nولم أر، في جلاس الناس، خيرا، … فمن لي بالنوافر، إن كنسنه؟\nوقد غابت نجوم الهدي عنا، … فماج الناس في ظلم دمسنه\nوقد تغشى السعادة غير ندب، … فيشرق بالسعود، إذا ودسنه\nوتقسم حظوة، حتى صخور … يزرن، فيستلمن ويلتمسنه\nكذات القدس، أو ركني قريش، … وأسرتهن أحجار لطسنه\nيحج مقام إبراهيم وفد، … وكم أمثال موقفه وطسنه\nتشاءم بالعواطس أهل جهل، … وأهون إن خفتن، وإن عطسنه\nوأعمار الذين مضوا صغارا، … كأثواب بلين وما لبسنه\nوهان، على الفراقد والثريا، … شخوص، في مضاجعها، درسنه\nوما حفلت حضار ولا سهيل … بأبشار يمانية، يدسنه"},{"id":"diwan-maarri:1376","bookId":"diwan-maarri","type":"poem","seq":1376,"chapter":"قصائد","title":"إذا ما شئتم دعة وخفضا،","page":"","text":"إذا ما شئتم دعة وخفضا، … فعيشوا في البرية خاملينا\nولا يعقد لكم أمل بخلق، … وبيتوا للمهيمن آملينا\nورفقا بالأصاغر كي يقولوا: … غدونا بالجميل معاملينا\nفأطفال الأكابر إن يوقوا … يروا، يوما، رجالا كاملينا\nونودوا في إمارتهم، فجفوا … وعادوا للثقائل حاملينا\nولا تبدوا عداوتكم لقوم … أتوكم، في الحياة، مجاملينا\nولا ترضوا بأن تدعوا وشاة، … وتسعوا بالأقارب ناملينا\nوقد جار القضاة، إذا أشاروا … بأيسر نظرة، متحاملينا\nلعل معاشرا، في الأرض، جوزوا … بما كانوا، قديما، عاملينا"},{"id":"diwan-maarri:1377","bookId":"diwan-maarri","type":"poem","seq":1377,"chapter":"قصائد","title":"هون عليك، ولا تبال بحادث","page":"","text":"هون عليك، ولا تبال بحادث … يشجيك، فالأيام سائرة بنا\nأعدى عدو لابن آدم نفسه، … ثم ابنه وافاه يهدم ما بنى\nهاتيك تأمره بكل قبيحة، … ودعاه ذاك لأن يضن ويجبنا\nوالغبن كوني في الحياة مصورا، … فمن الغباوة خيفتي أن أغبنا\nوأقل عبئا من جلوس ممدح، … للوفد يقصد، أن يروح مؤبنا"},{"id":"diwan-maarri:1378","bookId":"diwan-maarri","type":"poem","seq":1378,"chapter":"قصائد","title":"أركان دنيانا غرائز أربع،","page":"","text":"أركان دنيانا غرائز أربع، … جعلت لمن هو فوقنا أركانا\nوالله صير للبلاد وأهلها … ظرفين: وقتا ذاهبا، ومكانا\nوالدهر لا يدري بمن هو كائن … فيه، فكيف يلام فيما كانا؟\nوالمرء ليس بزاهد في غادة، … لكنه يترقب الإمكانا\nوالحي تخلق جسمه حركاته، … فيكل وهو يحاذر الإسكانا\nنبكي ونضحك، والقضاء مسلط، … ما الدهر أضحكنا ولا أبكانا\nنشكو الزمان وما أتى بجناية، … ولو استطاع تكلما لشكانا\nمتوافقين على المظالم، ركبت … فينا، وقارب شرنا أزكانا\nيمضي بنا الفتيان، ما أخذا لنا … نفسا، على حال، ولا تركانا\nوأرى الجدود حبت قريشا ملكها … وذوته، عمدا، عن بني ملكانا"},{"id":"diwan-maarri:1379","bookId":"diwan-maarri","type":"poem","seq":1379,"chapter":"قصائد","title":"لو لم تكن دنياك مذمومة،","page":"","text":"لو لم تكن دنياك مذمومة، … ما أولع الله بها الألسنا\nما أحمد الخيري، فألا به، … ولا أذم الورد والسوسنا\nأجهل مني رجل يبتغي، … عندي، ما لست له محسنا\nحق، وإن كان أخا صورة … في الإنس، أن يلجم، أو يرسنا\nوأن تسمى رجله حافرا، … في واجب التشبيه، أو فرسنا"},{"id":"diwan-maarri:1380","bookId":"diwan-maarri","type":"poem","seq":1380,"chapter":"قصائد","title":"ما وقع التقصير في لفظنا،","page":"","text":"ما وقع التقصير في لفظنا، … لو صدقت أفعالنا الألسنه\nكم حسنت في الأرض من صورة، … ولم تكن في عمل محسنه\nوما عيون الناس، فيما أرى، … منتبهات من طويل السنه\nإن أمامي أسدا فارسا، … لا بازلا يوطئني فرسنه\nإن تتطير، أو تفاءل، فما … تملك ريب الدهر، أن ترسنه\nخيرية في لفظها خيرة، … جاءتك بالسوء من السوسنه\nوالأمل المبسوط قرن إزا … ء الليث، لا يترك أن يلسنه\nلو قيل لم يبق سوى ساعة، … أملت ما تعجز عنه سنه"},{"id":"diwan-maarri:1381","bookId":"diwan-maarri","type":"poem","seq":1381,"chapter":"قصائد","title":"طودان قالا: زل غفرانا،","page":"","text":"طودان قالا: زل غفرانا، … فنسأل الخالق غفرانا\nأبرأنا الواحد من سقمنا، … ورمنا الملك، وأبرانا\nالله أدرانا بأمر، فما … نغسل بالتوبة أدرانا\nأجرأنا الجهل على إثمنا … وهو على الإحسان أجرانا\nوالبغي أشرانا، فألفيتنا، … وكلنا يوجد أشرانا\nإني حي، ران ذنبي على … قلبي، فما أنفك حيرانا\nنجران من قيظ وهم، فمن … يغدو على مسجد نجرانا؟\nإن يفن بدرانا، فنرجو الذي … أغنى، ولا نسأل بدرانا\nإثران من خير وشر لنا، … ويلحق التثريب أثرانا\nعمران مرا لكبير، ولا … يترك للدامر عمرانا\nفرحمة الله على أمة، … عهدتها، في الأرض، جيرانا\nأقرأنا منها السلام الكرى، … وكم أباد الحتف أقرانا\nغيران من حمد ومن عفة، … خير لمن ألفي غيرانا\nنهمل أسرانا بأيدي الردى، … ويدلج الليلة أسرانا\nنيران لاحا في ظلام لنا، … وقد لمحنا فيه نيرانا\nلو عقل الإنسان رام الهدى، … ولم يبت، في النوم، سدرانا\nمران: عيش وحمام، فما … أغناه أن يحمل مرانا"},{"id":"diwan-maarri:1382","bookId":"diwan-maarri","type":"poem","seq":1382,"chapter":"قصائد","title":"صنوف هذي الحياة يجمعها","page":"","text":"صنوف هذي الحياة يجمعها … طول انتباه، ورقدة، وسنه\nدنياك، لو حاورتك ناطقة، … خاطبت منها بليغة لسنه\nليفعل الدهر ما يهم به، … إن ظنوني بخالقي حسنه\nلا تيأس النفس من تفضله، … ولو أقامت، في النار، ألف سنه"},{"id":"diwan-maarri:1383","bookId":"diwan-maarri","type":"poem","seq":1383,"chapter":"قصائد","title":"أشممنا لبنى، فقلنا: لبينى،","page":"","text":"أشممنا لبنى، فقلنا: لبينى، … بعدما أزمعت صدودا وبينا\nعارضتنا بودها، فكرهنا … ه، وآبت لزورة، فأبينا\nقد تركنا لأهلها أم دفر، … وقعدنا عن شغلها فاحتبينا\nوصروف الأيام فرقن ما يج … بي الفتى في حياضه، وجبينا\nنسأل الله أن يخلص منهن، … وكم شقن زاهدا واطبينا\nلم نكن من ذوي الخمور سبأنا … ها، ولا من ذوي الأمور سبينا\nلا تعش مجبرا ولا قدريا، … واجتهد في توسط بين بينا"},{"id":"diwan-maarri:1384","bookId":"diwan-maarri","type":"poem","seq":1384,"chapter":"قصائد","title":"متى أنا، في هذا التراب، مغيب،","page":"","text":"متى أنا، في هذا التراب، مغيب، … فأصبح لا يجنى علي، ولا أجني؟\nأسير عن الدنيا، ولست بعائد … إليها، وهل يرتد قطن إلى دجن؟\nوجدت بها أحرارها، كعبيدها، … قباح السجايا، والصرائح كالهجن\nويوم حصولي في قراري نعمة … علي، كيومي لو خرجت من السجن\nوإن زمانا فجره مثل سيفه، … هلال، دجاه من مخالبه الحجن\nفما سقيت دار، فقلت لها: انعمي؛ … ولا هب إيماض، فقلت له: هجني\nإذا ما وردنا للمنايا شريعة، … فهان علينا ما شربنا من الأجن"},{"id":"diwan-maarri:1385","bookId":"diwan-maarri","type":"poem","seq":1385,"chapter":"قصائد","title":"أفدت، بهجران المطاعم، صحة،","page":"","text":"أفدت، بهجران المطاعم، صحة، … فما بي من داء يخاف، ولا حبن\nوإن ألق شكوي ألقه تحت خفية، … كجزء بسيط أول مس بالخبن\nوأصبحت، في الدنيا، غبينا مرزأ، … فأعقيت نسلي من أذاة ومن غبن\nفلست تراني حافرا مثل ضبها، … ولا لفراخي، مثل طائرها، أبني\nفإن تحكمي بالجور في وفي أبي، … فلن تحكميه في بناتي، ولا في ابني\nوأوقدت لي نار الظلام، فلم أجد … سناك بطرفي، بل سنانك في ضبني\nوما قام لبن الضيف إذ جاء طارقا، … بما هو راج، في الصباح، من اللبن"},{"id":"diwan-maarri:1386","bookId":"diwan-maarri","type":"poem","seq":1386,"chapter":"قصائد","title":"مطيتي الوقت، الذي ما امتطيته","page":"","text":"مطيتي الوقت، الذي ما امتطيته … بودي، ولكن المهيمن أمطاني\nوما أحد معطي، والله حارمي، … ولا حارمي شيئا، إذا هو أعطاني\nهما الفتيان استوليا بتعاقب، … وما لهما لب، فكيف يشطان؟\nإذا مضيا لم يرجعا، وتلاهما … نظيران، بالمستودعات، يلطان\nوكل غني يسلبان من الغنى، … وكل كمي، عن جواد، يحطان\nوكم نزلا في مهمه، وتحملا، … بغير حسيس، عن جبال وغيطان\nوما حملا رحلين، طورا، فيؤنسا، … إذا حفز الوشك الرحال يئطان\nويبتريان العظم والنحض، ذائبا … لينتقياه، والأديم يعطان\nوقد خطرا فحلين، لو زال عنهما … غطاء، لكانا بالوعيد يغطان\nوما برحا، والصمت من شيمتيهما، … يقصان فينا عبرة، أو يخطان\nوقد شهرا سيفين في كل معشر، … يقدان ما هما به، أو يقطان\nلغيرك بالقرطان أولى من ان يرى، … وشنفان في الأذنين منه، وقرطان\nتريد مقاما دائما، ومسرة … بدار هموم، لم تكن دار قطان\nوما زال شرط، يفسد البيع، واحد، … فما باله لما تظاهر شرطان؟\nلقد خدعتني أم دفر، وأصبحت … مؤيدة، من أم ليلى، بسلطان\nإذا أخذت قسطا من العقل هذه، … فتلك لها في ضلة المرء قسطان\nدعاوى أناس توجب الشك فيهم، … وأخطأني غيث الحجى، وتخطاني\nألم تر أعشى هوذة اهتاج، يدعي … معونته، عند المقال، بشيطان؟\nيراد بنا المجد الرفيع بزعمنا، … ونختار لبثا في وبيلة أوطان\nكأنا غروب مكرهات على العلى، … تمد إلى أعلى الركي بأشطان\nوما العيش إلا لجة ذات غمرة، … لها مولد الإنسان والموت شطان\nفأحسن بدنياك المسيئة، إذ بدت، … عليها وشاح من نجوم وسمطان\nوكم واسع الأعطان تجزع نفسه، … ورحب فؤاد آلف ضيق أعطان\nومن لي بجون عند كدر بقفرة، … كأنهما من آل يعقوب سبطان\nيجر بها المرطان من يمنية، … على كل غبراء الأفاحيص مرطان\nتخال بها مسعى من الصل مسقطا … من السوط، والعينان في الجنح سقطان\nإذا ما انجلى خيط الصباح تبينت … حبال رمال، ذات عفر وخيطان"},{"id":"diwan-maarri:1387","bookId":"diwan-maarri","type":"poem","seq":1387,"chapter":"قصائد","title":"أيأتي نبي يجعل الخمر طلقة،","page":"","text":"أيأتي نبي يجعل الخمر طلقة، … فتحمل ثقلا من همومي وأحزاني\nوهيهات، لو حلت لما كنت شاربا … مخففة، في الحلم، كفة ميزاني\nإذا خزنوني في الثرى، فمقالدي … مضيعة، لا يحسن الحفظ خزاني\nكأني نبت مر يوم وليلة … علي، وكانا منفضين، فجزاني\nهما بدويان، الطريق تعرضا، … وبردي، من نسج الشبيبة، بزاني\nقويان عزاني عليه، وأوقعا … بغيري ما بي أوقعاه، فعزاني\nوما ضيقا أرضي، ولكن أراهما … إلى الضنك، من وجه البسيطة، لزاني\nوما أكلا زادي، ولكن أكلته، … وقد نبهاني للسرى واستفزاني\nولم يرضيا إلا بنفسي من القرى، … ولو صنته، عن طارقي، لأحزاني\nوما هاج ذكري بارق نحو بارق؛ … ولا هزني شوق لجارة هزان\nبل الفتيان، اعتاد قلبي أذاهما، … يشيمان أسياف الردى، ويهزان\nعزيزان بالله، الذي ليس مثله، … يذلان في مقداره، ويعزان\nوكم فتكا، والحس قد بان عنهما، … بأهل وهود، أو جبال وحزان\nوما تركا ترك القباب، وغادرا … برمحين، أو جرزين، أسرة جرزان\nسلا غاب ترج والأنيعم كم ثوى، … بذاك وهذا، من أسود وخزان"},{"id":"diwan-maarri:1388","bookId":"diwan-maarri","type":"poem","seq":1388,"chapter":"قصائد","title":"أريد ليان العيش في دار شقوة،","page":"","text":"أريد ليان العيش في دار شقوة، … وتأبى الليالي غير بخل وليان\nويعجبني شيئان: خفض وصحة؛ … ولكن ريب الدهر غير شياني\nوما جبل الريان، عندي، بطائل؛ … ولا أنا من خود الحسان بريان\nوأحياني الله القدير ملاوة، … فهلا بخوف الله أقطع أحياني؟\nوإن بني الديان، أخمل عزهم … قيام عميد من خزيمة ديان\nوما اقتتل الحيان إلا سفاهة، … ولو صح ودي للمحارب حياني\nوتهلك أعيان الرجال، وإنما … مصارع أعيار كمصرع أعيان\nولم يشو حتف أم عفر بوهدة، … ولا أم غفر بين آس وظيان\nأريد عليات المراتب ضلة، … وخرط قتاد الليل دون عليان"},{"id":"diwan-maarri:1389","bookId":"diwan-maarri","type":"poem","seq":1389,"chapter":"قصائد","title":"تمزن، من مزن السحاب، معاشر،","page":"","text":"تمزن، من مزن السحاب، معاشر، … ومن مازن، بيض النمال تمزني\nعززت، ورب الناس أعطاك عزة، … وأصبحت هينا، كل شيء يعزني\nكنبت ضعيف لم يوازره غيره، … فأي نسيم هب، فهو يهزني"},{"id":"diwan-maarri:1390","bookId":"diwan-maarri","type":"poem","seq":1390,"chapter":"قصائد","title":"لهان علينا أن تمر، كأنها","page":"","text":"لهان علينا أن تمر، كأنها … هوازن طير، نسوة من هوازن\nوأم طويل الرمح سمته مازنا، … لدى العقل يحكي نملة، أم مازن\nرضيت بما جاء القضاء مسلما، … وضاع سؤالي في حواز حوازن\nإذا أنت أعطيت الغنى، فادخر به … نثا، وأرحه من خواز خوازن\nوما أنا إن وليت أمرا بعادل؛ … ولا في قريض الشعر بالمتوازن"},{"id":"diwan-maarri:1391","bookId":"diwan-maarri","type":"poem","seq":1391,"chapter":"قصائد","title":"ثعالة! حاذر من أمير وسوقة،","page":"","text":"ثعالة! حاذر من أمير وسوقة، … فمن لفظ صيد جاء لفظ الصيادن\nولا تتخذ من آل حواء صاحبا، … وغيرهم، إن شئت، فاصحب وخادن\nفإن كان في دنياك للشر معدن، … فإنهم في ذاك أزكى المعادن\nولا تقرب الناظور في الأرض، خلته … هدانا، فتلقى فاتكا لم يهادن\nوعاص مشيما قال: بادره غاده، … فلست بحاد كيد أشمط بادن\nفرب مسن رد مثلك، بالضحى، … لقى لرواد في النساء الروادن\nوكم أيموا من ضيغم أم أشبل، … وكم أثكلوا من أم شاد وشادن"},{"id":"diwan-maarri:1392","bookId":"diwan-maarri","type":"poem","seq":1392,"chapter":"قصائد","title":"قرن بحج عمرة وقريننا","page":"","text":"قرن بحج عمرة وقريننا … غراما، فآه من قوار قوارن\nعقائل مرد فوق جرد عوابس، … ذوات أوار، بالفناء أوارن\nمرى لهم المران رسل حياتهم، … فأعجب برسل من موار موارن\nإذا لم يزم النفس لب ولا تقى، … فرب عوار، للأنوف عوارن\nوكم من حسام قد أميط به الأذى، … ومارن سمر فيه رغم لمارن"},{"id":"diwan-maarri:1393","bookId":"diwan-maarri","type":"poem","seq":1393,"chapter":"قصائد","title":"رأيتك مفقود المحاسن، غابرا،","page":"","text":"رأيتك مفقود المحاسن، غابرا، … مع الناس، في دهر فقيد المحاسن\nأترجو المطايا خفض عيش ولذة، … يريح براها من مراس المراسن؟\nفقد سئمت خوض الرمال خفافها، … ونضح صداها بالمياه الأواسن\nفيوم نوى قصرن فيه عن النوى، … ويوم فراس دسنه بالفراسن\nفإن لا يكن وسنان حظي وحظها، … فإن عليه فترة المتواسن\nإذا أنت لم تصبح من الناس مفردا، … أذنت إلى لاص يعيب ولاسن"},{"id":"diwan-maarri:1394","bookId":"diwan-maarri","type":"poem","seq":1394,"chapter":"قصائد","title":"سكنت إلى الدنيا، فلما عرفتها","page":"","text":"سكنت إلى الدنيا، فلما عرفتها … تمنيت أني لست فيها بساكن\nوما فتئت ترمي الفتى، عن قسيها … بكل الرزايا من جميع الأماكن\nوما سمحت للزائرات بأمنها؛ … ولا للمواكي في أقاصي المواكن\nركنا إليها، إذ ركونا أمورها، … فقل في سفاه للرواكي الرواكن\nفأين الشموس اليعربيات قبلنا، … بها كن، فاسأل عن مآل البهاكن\nزكن المنايا أن زكون، فنعمة … من الله دامت للزواكي الزواكن\nجمعنا بقدر، وافترقنا بمثله، … وتلك قبور بدلت من مساكن\nنفتنا قوى لا مضربات لسالم، … بلا بل، ولا مستدركات بلكن"},{"id":"diwan-maarri:1395","bookId":"diwan-maarri","type":"poem","seq":1395,"chapter":"قصائد","title":"قبيح مقال الناس: جئناه مرة،","page":"","text":"قبيح مقال الناس: جئناه مرة، … فكان قليلا خيره لم يعاون\nإذا أنت لم تعط الفقير، فلا يبن … له منك وجه المعرض المتهاون\nولا تأمنن الحادثات، فإنها … ترد ليوث الغاب مثل الضياون"},{"id":"diwan-maarri:1396","bookId":"diwan-maarri","type":"poem","seq":1396,"chapter":"قصائد","title":"منون رجال خبرونا عن البلى،","page":"","text":"منون رجال خبرونا عن البلى، … وعادوا إلينا بعد ريب منون\nبنون كآباء، وكم برح الردى … بضب، على علاته، وبنون\nدفناهم، في الأرض، دفن تيقن، … ولا علم بالأرواح غير ظنون\nوروم الفتى ما قد طوى الله علمه، … يعد جنونا، أو شبيه جنون"},{"id":"diwan-maarri:1397","bookId":"diwan-maarri","type":"poem","seq":1397,"chapter":"قصائد","title":"عجبت لقوم جنبوا ثمن الغنا،","page":"","text":"عجبت لقوم جنبوا ثمن الغنا، … وقد شربوا كاساتهم بديون\nوأفضل عندي، من أكف تداولت … سلافة خمار، أكف قيون\nيقولون: لم نشرب، مقال تكذب، … وقد شهدت في أوجه وعيون"},{"id":"diwan-maarri:1398","bookId":"diwan-maarri","type":"poem","seq":1398,"chapter":"قصائد","title":"حياة وموت وانتظار قيامة،","page":"","text":"حياة وموت وانتظار قيامة، … ثلاث أفادتنا ألوف معان\nفلا تمهرا الدنيا المروءة، إنها … تفارق أهليها فراق لعان\nولا تطلباها من سنان وصارم، … بيوم ضراب، أو بيوم طعان\nوإن شئتما أن تخلصا من أذاتها، … فحطا بها الأثقال واتبعاني\nفما راعني منها تهجم ظالم؛ … ولا خمت عن وهد لها ورعان\nولا حل سري، قط، في أذن سامع، … وشنفاه، أو قرطاه يستمعان\nولم أرقب النسرين في حومة الدجى، … أظنهما في كفتي يقعان\nعجبت من الصبح المنير وضده، … على أهل هذي الأرض يطلعان\nوقد أخرجاني بالكراهة منهما، … كأنهما، للضيق، ما وسعاني\nوكيف أرجي الخير يصدر عنهما، … وقد أكلتني فيهما الضبعان؟\nوما بر من ساواهما في قياسه، … ببري عقوق، بل هما سبعان\nوما مات ميت مرة في سواهما، … كخصمين، في الأرواح، يفترعان\nأشاحا فقالا، ضلة: ليس عندنا … محل، وفي ضيق الثرى وضعاني\nوكيوان والمريخ عبدان سخرا، … ولست أبالي إن هما فرعاني\nولو شاء من صاغ النجوم بلطفه، … لصاغهما كالمشتري ودعان\nأيعكس هذا الخلق مالك أمره، … لعل الحجى والحظ يجتمعان؟"},{"id":"diwan-maarri:1399","bookId":"diwan-maarri","type":"poem","seq":1399,"chapter":"قصائد","title":"أرى الخلق في أمرين: ماض ومقبل؛","page":"","text":"أرى الخلق في أمرين: ماض ومقبل؛ … وظرفين: ظرفي مدة ومكان\nإذا ما سألنا عن مراد إلهنا، … كنى عن بيان، في الإجابة، كاني"},{"id":"diwan-maarri:1400","bookId":"diwan-maarri","type":"poem","seq":1400,"chapter":"قصائد","title":"أرى فتيي دنياك، إن حرج الفتى،","page":"","text":"أرى فتيي دنياك، إن حرج الفتى، … فما إن هما في مأثم حرجان\nوكم من رحيب يلقيان ملاءة … عليه، وضنك ضيق يلجان\nجديدان لما يبليا بتقادم، … ولا بأكف القوم ينتسجان\nإذا حزن الأصحاب لم يحزنا لهم، … فأنى بضد الحزن يبتهجان؟\nملاحيتي قد زينت أنجم الدجى، … ملاحية لم تجنها يد جاني\nتعلق أذن الدهر قرطا، ولم يكن … ليخلج، والقرطان يختلجان\nومن داين الأيام، فهي ملية، … على غيها، باللي والسلجان\nوسيان ملكا معشر، في سناهما، … وعلجان في الشعراء والعلجان\nرجاك، لعمري، أيها الريم، قاطع … رجائي، وبعدا للغوي رجاني\nوآثر عندي من مديحي، تخرصا، … كلام غوي لامني وهجاني\nغدا الحتف لا شجوا يخاف ولا شجا، … وقبلك أشجى أسودي، وشجاني\nوما ينفع الغربيب، والضعف واقع، … إذا كان لون الرأس غير هجان"},{"id":"diwan-maarri:1401","bookId":"diwan-maarri","type":"poem","seq":1401,"chapter":"قصائد","title":"عيشي مؤد إلى الضراء والوهن،","page":"","text":"عيشي مؤد إلى الضراء والوهن، … ومهنتي، لإلهي، أشرف المهن\nتخل من أم دفر، فهي مؤذية، … وهون الأمر في غرائه يهن\nإنا ضيوف زمان، ما قراه لنا … إلا المنايا، ونحن الآن في اللهن\nوقد أنفت لنفس منه نافرة … كل النفار، وشخص فيه مرتهن\nالله عالم غيب لا أحاوله … من ذي نجوم، ولا أبغيه في الكهن"},{"id":"diwan-maarri:1402","bookId":"diwan-maarri","type":"poem","seq":1402,"chapter":"قصائد","title":"لولا الحوادث لم أركن إلى أحد","page":"","text":"لولا الحوادث لم أركن إلى أحد … من الأنام، ولم أخلد إلى وطن\nوكنت في كل تيه صاحبا لقطا … في الورد، قطني من سعد ومن قطن\nحليف وجناء ترمي بالوجين شفا … منها، وتجهل معنى الحوض والعطن\nوغيض السير عينيها، فلو وردت … جميهما الطير، لم تشرب بلا شطن\nوهل ألوم غبيا في غباوته، … وبالقضاء أتته قلة الفطن؟"},{"id":"diwan-maarri:1403","bookId":"diwan-maarri","type":"poem","seq":1403,"chapter":"قصائد","title":"إن لم نكن عائمي لج نمارسه","page":"","text":"إن لم نكن عائمي لج نمارسه … إلى الحمام، فإنا راكبو سفن\nلولا التجمل سرنا في ترحلنا، … كما وردنا، بلا طيب ولا كفن\nإن اللباس وعطرا أنت بائعه، … ليسا لمدفون موتانا، بل الدفن\nجاء الوليد معرى لا خيوط له، … فما الفضيلة بين الطفل واليفن"},{"id":"diwan-maarri:1404","bookId":"diwan-maarri","type":"poem","seq":1404,"chapter":"قصائد","title":"أمسي، وأمسي في شحط، وإن غدي","page":"","text":"أمسي، وأمسي في شحط، وإن غدي … وإن يومي، بلا ريب، لأمسان\nإن الفتيين بالفتيان في لعب، … كل أحس، ومرا لا يحسان\nويوديان بما قالوا وما صنعوا، … حتى إساءة قوم مثل إحسان\nوالله يخلف أزمانا بمشبهها، … كما يبدل إنسانا بإنسان\nتلقي المقادير، في آنافهم، خطما، … يقدنهم، لمناياهم، بأرسان\nأذوين آل زهير، وارتعين بني … نبت، وحسين موتا رهط حسان\nألمطعمي الضيف عن يسر وعن عدم؛ … والشاهدي الحرب من رجل وفرسان\nكاسوا عقولا، وكاست إبلهم كرما؛ … والغدر في الناس لم يعرف بكيسان"},{"id":"diwan-maarri:1405","bookId":"diwan-maarri","type":"poem","seq":1405,"chapter":"قصائد","title":"العيش ماض، فأكرم والديك به،","page":"","text":"العيش ماض، فأكرم والديك به، … والأم أولى بإكرام وإحسان\nوحسبها الحمل والإرضاع تدمنه، … أمران بالفضل نالا كل إنسان\nواخش الملوك وياسرها بطاعتها، … فالملك للأرض مثل الماطر الساني\nإن يظلموا، فلهم نفع يعاش به، … وكم حموك برجل أو بفرسان\nوهل خلت، قبل، من جور ومظلمة، … أرباب فارس، أو أرباب غسان؟\nخيل إذا سومت سامت، وما حبست … إلا بلجم، تعنيها، وأرسان"},{"id":"diwan-maarri:1406","bookId":"diwan-maarri","type":"poem","seq":1406,"chapter":"قصائد","title":"قد آذنتنا بأمر فادح أذن؛","page":"","text":"قد آذنتنا بأمر فادح أذن؛ … وإنما قيل آذان لإيذان\nشمس وبدر أنارا في ضحى ودجى … لآدم، وهما لا ريب هذان\nوالليل والصبح ما انجذت حبالهما، … وكل حبل على عمد يجذان\nويأكلان، ولم يستوبلا مقرا … من الطعام، ولا شهدا يلذان\nإن الجديدين ما ظنا وما علما، … بل طائران على جد أحذان\nطرفان لله ما بذا ولا لحقا، … ولم يزالا، بمقدار، يبذان\nهذا العظات علينا في سكونهما، … كصارمين ذوي غرب يهذان\nوقالت الأرض: مهلا يا بني، ألا … سيان فوقي أجمالي وقذاني\nغذاكم الله مني ثم عوضني … مما لقيت، فبالأجسام غذاني\nوطئتموني بأقدام وأحذية، … فقد أدلت، فتحتي من تحذاني\nكم مر، في الدهر، من قيظ ومن شبم … ولاح، في الأرض، من ورد وحوذان\nيا صاحبي اللذين استشفيا لضنى، … بمن تلوذان، أو ممن تعوذان؟\nبقراط، عمري، وجالينوس ما سلما، … والحق أنهما في الطب فذان"},{"id":"diwan-maarri:1407","bookId":"diwan-maarri","type":"poem","seq":1407,"chapter":"قصائد","title":"أنافق الناس، إني قد بليت بهم،","page":"","text":"أنافق الناس، إني قد بليت بهم، … وكيف لي بخلاص منهم داني؟\nمن عاش غير مداج من يعاشره، … أساء عشرة أصحاب وأخدان\nكم صاحب يتمنى لو نعيت له، … وإن تشكيت راعاني وفداني\nصحبت دهري وسوء الغدر شيمته، … فإن غدرت فإن الدهر أعداني\nوما أبالي وأرداني مبرأة … من العيوب، إذا ما الحتف أرداني\nمتى لحقت بتربي زل عن جدثي، … مدحي وذمي من مثنى ووحدان\nهل تزدهي كعبة الحجاج، إذ فقدت … حسا، بكثرة زوار وسدان\nفي الحول عيدان ما فازا بما رزقا، … فيظهرا البشر، لما قيل عيدان\nكم عبد الفتيان الخلق عن عرض، … بذلة، وهما لله عبدان\nأما الجديدان من ثوبي ومن جسدي، … فيبليان، ولا يبلى الجديدان\nبرد الشباب وبرد الناسج ابتذلا، … وهل يدوم على البردين بردان؟"},{"id":"diwan-maarri:1408","bookId":"diwan-maarri","type":"poem","seq":1408,"chapter":"قصائد","title":"الدهر لونان أعيى ثالث لهما،","page":"","text":"الدهر لونان أعيى ثالث لهما، … وكم أتاك بأشباه وألوان\nلا أشرب الراح، أشري طيب نشوتها … بالعقل أفضل أنصاري وأعواني\nلو كان يعرف دنياه مصاحبها، … أرادها لعدو دون إخوان\nوإن كفتني عذاب الله آخرة، … فما أحاول منها فوز رضوان\nوالرزق يقسم، ما فتكي بمنتقصي … حظا، ولا النسك في المكروه أهواني\nسيحان للروم عذب، ليس مورده … ملحا كزمزم، أو عين لسلوان\nوالإنس مثل نظام الشعر، كم رجل … بالجيش يفدى، وكم بيت بديوان\nوأقصر الوقت كون ثم ينظمه … حكم القديم، فيفنيه بأكوان\nإن جاءني الخطب يجنيه، بلا سبب، … كيوان، فالله أرجو، رب كيوان"},{"id":"diwan-maarri:1409","bookId":"diwan-maarri","type":"poem","seq":1409,"chapter":"قصائد","title":"لا أشرك الجدي في در يعيش به؛","page":"","text":"لا أشرك الجدي في در يعيش به؛ … ولا أروع بنات الوحش والضان\nولا أقول لجار لم يجىء خطأ، … إن كان يوما بحسن الفعل أرضاني\nلو ينطق السيف نادى: ليس لي عمل، … إذا قضى مالك الأفلاك أنضاني\nمتى أراد، فصفحاي اللذان هما … بحر الردى، من حياض الموت حوضاني\nوإن كهمت، فأمر الله أكهمني، … وإن مضيت، فأمر الله أمضاني"},{"id":"diwan-maarri:1410","bookId":"diwan-maarri","type":"poem","seq":1410,"chapter":"قصائد","title":"خير وشر، وليل بعده وضح،","page":"","text":"خير وشر، وليل بعده وضح، … والناس، في الدهر، مثل الدهر قسمان\nواللب حارب تركيبا يجاهده، … فالعقل والطبع، حتى الموت، خصمان\nهل ألحد السيف، أو قلت ديانته؛ … أو كان صاحب توحيد وإيمان؟\nورابني منه ترك الجاحدين سدى … لم يفجعوا برؤوس منذ أزمان"},{"id":"diwan-maarri:1411","bookId":"diwan-maarri","type":"poem","seq":1411,"chapter":"قصائد","title":"الطبع شيء قديم لا يحس به،","page":"","text":"الطبع شيء قديم لا يحس به، … وعادة المرء تدعى طبعه الثاني\nوالإلف أبكى على خل يفارقه، … وكلف القوم تعظيما لأوثان"},{"id":"diwan-maarri:1412","bookId":"diwan-maarri","type":"poem","seq":1412,"chapter":"قصائد","title":"ما رقش الخط في درج ولا صحف","page":"","text":"ما رقش الخط في درج ولا صحف … من آل مقلة، إلا قلت فان\nسيفان من بحري الظلماء ما شهرا … إلا لأفراد ذي بدن وسيفان\nضيفان للدهر: ميلاد ومخترم، … ونحن بينهما أشباه ضيفان\nوما النسور، وإن كانت مملكة، … إلا نظير جراد، طار، خيفان"},{"id":"diwan-maarri:1413","bookId":"diwan-maarri","type":"poem","seq":1413,"chapter":"قصائد","title":"هل تثبتن، لذي شام وذي يمن،","page":"","text":"هل تثبتن، لذي شام وذي يمن، … عطية الدهر من عز وتمكين؟\nخير لصاحب تاج يدعى ملكا، … لو أنه لابس أطمار مسكين\nإن تمس في، كما في الناس كلهم، … أدناس حي، فلا شيب يزكيني\nوما عنيت سوى ترب تغيرني … فيه أفارق تحريكي وتسكيني\nوما أعود إلى الدنيا، وقد زعموا … أن الزمان بمثلي سوف يحكيني\nوكيف أشكو، لجهل، ما أمارسه، … إلى الأنام، وحكم الله يشكيني؟\nوارحمتا لشبيهي في حوادثه، … ينكيه ما كان في الأيام ينكيني\nإن الذي بالمقال الزور يضحكني، … ضد الذي بيقين الحق يبكيني\nوهل أسر، ونفسي غير زاكية، … بأن تخرص أفواه تزكيني؟"},{"id":"diwan-maarri:1414","bookId":"diwan-maarri","type":"poem","seq":1414,"chapter":"قصائد","title":"إذا وقت السعادة زال عني،","page":"","text":"إذا وقت السعادة زال عني، … فكلني، إن أردت، ولا تكني\nنبذت نصيحتي أن رث جسمي، … وكم نقع الغليل خبيء شن\nوقد عدم التيقن في زمان، … حصلنا من حجاه على التظني\nفقلنا للهزبر: أأنت ليث؟ … فشك وقال: علي، أو كأني\nوضعت على قرى الأيام رحلي؛ … فما أنا للمقام بمطمئن\nولا قتبي على العود المزجى؛ … ولا سرجي على الفرس الأدن\nولكن ترقل الساعات تحتي، … برئن من التمكث والتأني\nأحن وما أجن سوى غرام، … بغير الحق من حن وجن\nنصحتك، ناقتي، سلبي ونفسي، … ونحرك في الحنين، فلا تحني\nأضيف الفقر! ضيفنك ادلاج؛ … فهل لك، من ذؤالة، في ضفن؟\nعنى وتصعلك، وكرى وسهد، … فقضينا الحياة بكل فن\nزمان لا ينال بنوه خيرا، … إذا لم يلحظوه من التمني\nعرفت صروفه، فأزمت منها … على سن ابن تجربة، مسن\nوأفقرني إلى من ليس مثلي، … كما افتقر السنان إلى المسن\nأنا ابن الترب، ما نسبي سواه، … قللت عن التسمي والتكني\nإذا ألهمتني الغبراء، يوما، … فقد أمن التجنب والتجني\nوما أهل التحنؤ والتحلي، … إلى أهل التحلؤ والتحني\nويكفيك التقنع، من قريب، … عظائم ليس تبلغ بالتوني:\nصرير الرمح في زدد منيع، … ووقع المشرفي على المجن\nوحمل مهند يسطو بعير … وفور، ليس بالأشر المرن\nولا شلال عانات خماص، … ولكن خيل جيش مرجحن\nيرى عذم الأوابد غير حل؛ … ويعذم هامة البطل الرفن\nوما ينفك محتملا ذبابا، … أبى التغريد في الخصر المغن\nتذوب، حذاره، زرق الأعادي، … ويسخى، بالحياة، حليف ضن\nوينفث في فم الحيات سما، … ويملأ ذلة أنف المصن\nوخرق مفازة كسيت سرابا، … يعري الذئب من وبر مكن\nشكت سحرا من السبرات قرا، … فأوسعها الهجير من القطن\nوتعزف جنها، والليل داج، … إذا خلت الجنادب من تغني\nيخال الغر سرح بني أقيش، … يؤنق، في مراتعها، بسن\nأراك إذا انفردت كفيت شرا، … من الخل المعاشر والمعن\nومن يحمل حقوق الناس يوجد، … لدى الأغراض، كالفرس المعن\nأتعجب من ملوك الأرض أمسوا، … للذات النفوس، عبيد قن؟\nفإن دانيتهم لم تعد ظلما، … ومنا في الأمور بغير من\nنهيتك عن خلاط الناس، فاحذر … أقاربك الأداني، واحذرني\nوإن أنا قلت لا تحمل جرازا، … فهز أخا السفاسق واضربني\nفنصل السيف، وهو اللج يرمي … غريقا، فوق سيف مرفئن\nوضاحيه يزيل غضون وجه، … ويبسط من وداد المكبئن\nفما حملت يداه به خؤونا، … ولا نبراته نبرات ون\nسنا العيش الخمول، فلا تقولوا: … دفين الصيت كالميت المجن\nوتؤثر حالة الزميت نفسي، … وأكره شيمة الرجل المفن\nكفى حزنا رحيل القوم عني، … وليس تخيري وطن المبن\nتبنوا خيمهم، فوقوا هجيرا … وأعوزني مكان للتبني\nيصافح راحة باليأس قلبي، … ولدن الشرخ حول من لدني\nوما أنا والبكاء لغير خطب، … أعين بذاك من لم يستعني\nحسبتك لو توازن بي ثبيرا، … ورضوى في المكارم، لم تزني\nوما أبغي كفاءك عن جميل، … وأما بالقبيح فلا تدني\nولا تك جازيا بالخير شرا، … وإن أنا خنت في سبب، فخني\nجليسي ما هويت لك اقترابا، … وصنتك عن معاشرتي، فصني\nأرى الأقوام خيرهم سوام، … وإن أهن ابن حادثة يهني\nإذا قتل الفتى الشريب منهم، … فلا يهج الغرام كسير دن\nرأيت بني النضير، من آل موسى، … أعارهم الشقاء حطيم ثن\nسعوا، وسعت أوائلهم لأمر، … فما ربحوا سوى دأب معني"},{"id":"diwan-maarri:1415","bookId":"diwan-maarri","type":"poem","seq":1415,"chapter":"قصائد","title":"إذا هاجت، أخا أسف، ديار،","page":"","text":"إذا هاجت، أخا أسف، ديار، … فليت طلول دارك لم تهجني\nإذا خلجت بوارق في هزيع، … دعوت، فقلت: يا موت اختلجني\nأتأسى النفس للجثمان يبلى، … وهل أسي الحيا لفراق دجن؟\nوما ضر الحمامة كسر ضنك، … من الأقفاص، كان أضر سجن\nأعوذ بخالقي من أن يراني … كشاك النبت، لا يجنى ويجني\nكممطور القتادة، يتقينا … بآلات، مقوصة، وحجن\nأزجي العيش معترفا بضعف؛ … أنافي القول في عرب وهجن\nفإن الطير يقنعهن ورد، … على ما كان من صفو وأجن"},{"id":"diwan-maarri:1416","bookId":"diwan-maarri","type":"poem","seq":1416,"chapter":"قصائد","title":"ذممتك، أم دفر، فاسمعيني،","page":"","text":"ذممتك، أم دفر، فاسمعيني، … وجازيني بذلك، أو دعيني\nفما كنت الحبيب إليك يوما، … فأقرب في الثوي لتخدعيني\nلعنتك، جاهدا، وقد اشتبهنا، … كلانا راح في بردي لعين\nعلى خلق العجوز غدا بنوها، … لهم ورد من الغدر المعين\nإذا ما الأربعون مضت كمالا، … فما للمرء من أرب لعين\nوغشيان النساء، إذا تقضت، … لسلطان المنية كالمعين"},{"id":"diwan-maarri:1417","bookId":"diwan-maarri","type":"poem","seq":1417,"chapter":"قصائد","title":"كأن الدهر بحر، نحن فيه،","page":"","text":"كأن الدهر بحر، نحن فيه، … على خطر، كركاب السفين\nبكى جزعا لميته كفور، … فجاء بمنتهى الرأي الأفين\nمصيبة دينه، لو كان يدري، … أجل من المصيبة بالدفين\nقد استخفيت، كالجسد الموارى، … ولكن الطوارق تختفيني\nعفا أثري الزمان، وما أغبت … ضباع، في المحلة، تعتفيني"},{"id":"diwan-maarri:1418","bookId":"diwan-maarri","type":"poem","seq":1418,"chapter":"قصائد","title":"أجارحي الذي أدمى أساني،","page":"","text":"أجارحي الذي أدمى أساني، … وسالب حلتي عني كساني\nفما لي لا أقول، ولي لسان، … وقد نطق الزمان بلا لسان\nعسا عمرو عن الطوق المعري، … فقد جانبت علي، أو عساني\nوبيعت بالفلوس، لكل خزي، … وجوه كالدنانير الحسان\nولو أني أعد بألف بحر، … لمر علي موت، فاحتساني\nظلامي والنهار قد استمرا … علي، كما تتابع فارسان"},{"id":"diwan-maarri:1419","bookId":"diwan-maarri","type":"poem","seq":1419,"chapter":"قصائد","title":"طلبت مكارما، فأجدت لفظا،","page":"","text":"طلبت مكارما، فأجدت لفظا، … كأنا خالدان على الزمان\nسينسى كل ما الأحياء فيه، … ويختلط الشآمي باليماني\nورمت تجملا، فكسيت شينا؛ … ومن لك من شرورك بالأمان؟\nوإن حوادث الأيام نكد، … يصيرن الحقائق كالأماني\nضماني أن سينفد كل شيء، … سوى من ليس يدخل في الضمان\nوما خلت السماك، ولا أخاه، … على خلقيهما لا يهرمان\nوما أدري أعلمهما كعلمي، … بهذا الأمر، أم لا يعلمان؟\nفهل للفرقدين سلاف راح، … على كاساتها يتنادمان؟\nوإن فهما خطاب الدهر مثلي، … فما سعدا بما يمنيه مان\nوأروح منهما حادي ثلاث، … يسوقهن، أو حادي ثمان\nومن لي أن أكون طريد سرب … سما لي خدن سنبس، أو رماني\nألم ترني كميت الناس نفسي، … فأظهرني القضاء، وما كماني؟"},{"id":"diwan-maarri:1420","bookId":"diwan-maarri","type":"poem","seq":1420,"chapter":"قصائد","title":"لو هب سكان التراب من الكرى،","page":"","text":"لو هب سكان التراب من الكرى، … أعيى المحل على المقيم الساكن\nلغدوا، وقد ملأ البسيطة بعضهم، … ورأيت أكثرهم بغير أماكن\nلا تركنن إلى الحياة، فإنها … غدارة بأخي الوفاء الراكن"},{"id":"diwan-maarri:1421","bookId":"diwan-maarri","type":"poem","seq":1421,"chapter":"قصائد","title":"طال الزمان علي، وهو معللي","page":"","text":"طال الزمان علي، وهو معللي … بمثالث، من زوره، ومثاني\nكم حلت الأحياء جدة روضة، … ورعت لها نبتا لعام ثان"},{"id":"diwan-maarri:1422","bookId":"diwan-maarri","type":"poem","seq":1422,"chapter":"قصائد","title":"أف لدنيانا وأحزانها،","page":"","text":"أف لدنيانا وأحزانها، … خففت من كفة ميزانها\nوتلك دار غير مأمونة، … أولع ضاريها بخزانها\nفي بقعة من رقعة يسرت، … للبيذق، الفتك بفرزانها\nأين ملوك غبرت مدة، … بين روابيها وحزانها\nتردي بشن البدر أضيافها، … وتشتري الخيل بأوزانها\nقد ذهبت عن ذهب صامت، … وخلفته عند خزانها"},{"id":"diwan-maarri:1423","bookId":"diwan-maarri","type":"poem","seq":1423,"chapter":"قصائد","title":"هل قبلت، من ناصح، أمة","page":"","text":"هل قبلت، من ناصح، أمة … تغدو إلى الفصح بصلبانها؟\nكنائس يجمعها وصلة، … بين غوانيها وشبانها\nما بالها عذراء، أو ثيبا، … كوردة الجاني بإبانها\nراحت إلى القس بتقريبها، … وبيتها أولى بقربانها\nقد جربت من فعله سيئا، … والطيب جار بجربانها\nوربها تسخط، بل زوجها ال … بائس، في طاعة ربانها\nوزارت الدير، وأثوابها … ضامنة فتنة رهبانها"},{"id":"diwan-maarri:1424","bookId":"diwan-maarri","type":"poem","seq":1424,"chapter":"قصائد","title":"قرنت جيشين، فكم من دم","page":"","text":"قرنت جيشين، فكم من دم … أرقت، لا هديا عن القارن\nفمارني، إن شئت، أو لا، فما … يعرف إلا ذلة مارني\nوار زناد الشر في هذه الدن … يا، فقل يا جدثي وارني\nويا خليلي درني زائد، … فأقصني، في الأرض، أو دارني\nعندك مال، فأعن سائلا، … ولا تبت كالسابق الحارن\nفالرجل للرجلة، والكف لل … كفة، والعرنين للعارن"},{"id":"diwan-maarri:1425","bookId":"diwan-maarri","type":"poem","seq":1425,"chapter":"قصائد","title":"ما هاجني البارق من بارق،","page":"","text":"ما هاجني البارق من بارق، … يوما، ولا هز لهزان\nحربة زان بفؤاد الفتى، … خير له من خربة الزاني\nلا أشرب الراح ولو ضمنت … ذهاب لوعاتي وأحزاني\nمخففا ميزان حلمي بها، … كأنني ما خف ميزاني\nعمر مضى، لا كان من ذاهب … جزيته شرا، وجزاني\nأجامل الناس، ولو أنني … كشفت ما في السر أخزاني\nأسيت من نقصي، ولكن ما … يظهر من غيري عزاني"},{"id":"diwan-maarri:1426","bookId":"diwan-maarri","type":"poem","seq":1426,"chapter":"قصائد","title":"الحمد لله الذي صاغني،","page":"","text":"الحمد لله الذي صاغني، … أطعمني رزقي وأحياني\nشخصي هذا عرضة للردى، … ولم يزل معدن عصيان\nمن كل فن فيه أعجوبة، … كأنه جامع سفيان\nيا آل يعقوب! خذوا حذركم، … في الدهر، من حبر وديان\nيزعم: نار من سماء هوت، … تأكل ذا إفك وطغيان\nلو كنت فيما قلته صادقا، … لم تعد للشر بهميان\nولم تكن ترغب في زيف، … تؤخذ من عرج وعميان\nأما توقى كذبا فاحشا، … أذهلني منك وأعياني؟\nتجعل نميك تبرا، وما … تخلطه حبة عقيان"},{"id":"diwan-maarri:1427","bookId":"diwan-maarri","type":"poem","seq":1427,"chapter":"قصائد","title":"من لي بترك الطعام أجمع، إن ال","page":"","text":"من لي بترك الطعام أجمع، إن ال … أكل ساق الورى إلى الغبن\nلا أفجع الأم بالرضيع، ولا … أشرك هذا الفرير في اللبن\nأقتات من طيب النبات، وهل … يسلم عود الفتى من الأبن؟\nشجع قلبي على الردى رشدي، … والنفس مجبولة على الجبن"},{"id":"diwan-maarri:1428","bookId":"diwan-maarri","type":"poem","seq":1428,"chapter":"قصائد","title":"يا بدوي اتق المدامة، إن ال","page":"","text":"يا بدوي اتق المدامة، إن ال … خمر باتت كثيرة الأبن\nآليت ما سمحت أخا بخل، … يوما، ولا شجعت أخا جبن\nوإنما تلك خفة حدثت … عنها، فجاءت بأثقل الغبن\nأفضل من أحمر السلاف، ومن … كميتها، ناصع من اللبن"},{"id":"diwan-maarri:1429","bookId":"diwan-maarri","type":"poem","seq":1429,"chapter":"قصائد","title":"لا تجلسن حرة موفقة","page":"","text":"لا تجلسن حرة موفقة … مع ابن زوج، لها، ولا ختن\nفذاك خير لها، وأسلم لل … إنسان، إن الفتى مع الفتن\nودم على غيرة الصبا أبدا، … ولا تعد في الشباب ثم تني\nكأنما الحادثات، في الآفاق، … بعض السحائب الهتن\nما ختن القوم باختيارهم، … إذ جلبوا من طراز أو ختن"},{"id":"diwan-maarri:1430","bookId":"diwan-maarri","type":"poem","seq":1430,"chapter":"قصائد","title":"نحن قطنية، وصوفية أن","page":"","text":"نحن قطنية، وصوفية أن … تم، فقطني من التجمل، قطني\nتقطعون البلاد بطنا وظهرا؛ … إنما سعيكم لفرج وبطن\nحاطني خالقي، فعشت، ولولا … خوفه، قلت: ليته لم يحطني\nجسدي خرقة تخاط إلى الأر … ض، فيا خائط العوالم خطني"},{"id":"diwan-maarri:1431","bookId":"diwan-maarri","type":"poem","seq":1431,"chapter":"قصائد","title":"عيشتي سلتي، ورمسي غمدي؛","page":"","text":"عيشتي سلتي، ورمسي غمدي؛ … فاقربوني فيه ولا تقربوني\nزبنتنا، عن درها، أم دفر، … فصفوها بالحيزبون الزبون\nورأيت البقاء فيها، وإن م … د، لوشك الحمام كالعربون\nإن في الشر، فاعلموه، خيارا، … وحبون الرجال فوق الحبون\nليس حال المخبول، فيما يلاقي، … مثل حال المطوي والمخبون\nوهم الناس، والحياة لهم سو … ق، فمن غابن ومن مغبون\nهرم البازل الذي يحمل العب … ء، فأمسى يعزه ابن اللبون\nكم قطعنا من حندس ونهار، … وكأن الزمان في ديدبون\nفرعى الله جيرة ما تناءوا … عن رحيب لبانه، ملبون\nأطربوني، وما ابن سبرة، في السب … رة، إلا منية الأطربون"},{"id":"diwan-maarri:1432","bookId":"diwan-maarri","type":"poem","seq":1432,"chapter":"قصائد","title":"ويبكم! إن رأيتموني، يوما،","page":"","text":"ويبكم! إن رأيتموني، يوما، … حبة، في الثرى فلا تلقطوني\nأنا كالحرف ليس ينقط، والل … ه حسيب الجهال، إن نقطوني\nبت كالواو بين ياء وكسر، … لا يلام الرجال إن يسقطوني"},{"id":"diwan-maarri:1433","bookId":"diwan-maarri","type":"poem","seq":1433,"chapter":"قصائد","title":"جير ان الفتى لفي النصب الأع","page":"","text":"جير ان الفتى لفي النصب الأع … ظم، بين الأهلين والجيران\nوحران الجواد كالحتف للها … رب، قدام ثائر حران\nأنا أدراني الرشاد بأن الإ … نس مخلوقة من الأدران\nإن يكن أبرأ القضاء الضنى، فه … وبراني من بعد ما أبراني\nلاكرى نائم بجفني، ولا أع … ملت، في الدهر، فتنة بكران\nقد أراني القياس أن ليوث ال … غاب، فيما ينوب، مثل الإران\nخوفونا من القران، ولا بد … لنفس، مع الردى، من قران\nكم جبال من الجيوش ترادى، … والذي أوضعت له الحجران\nمر آن من الزمان على الشخ … ص، فقد خلت أن دهرا مراني\nوعراني خطب أراد العراني … ن بذل، وكلها في عران\nزعم الناس أن قوما من الأب … رار عولوا، بالجو، بالطيران\nومشوا فوق صفحة الماء، هذا الإف … ك، هيهات ما جرى العصران\nما مشى فوق لجة الماء لا السع … دان، فيما مضى، ولا العمران\nأقراني ذاك المضيف ما أك … ره، والله غالب الأقران\nلم أبت غافلا، فأشراني الحر … ص إلى أن أعود كالأشران"},{"id":"diwan-maarri:1434","bookId":"diwan-maarri","type":"poem","seq":1434,"chapter":"قصائد","title":"أواني هم، فألقى أواني،","page":"","text":"أواني هم، فألقى أواني، … وقد مر في الشرخ والعنفوان\nوضعت بواني في ذلة، … وألقيت، للحادثات، البواني\nثواني ضيف، فلم أقره … أوائل من عزمتي، أو ثواني\nفيا هند! وان، عن المكرما … ت، من لا يساور بالهندواني\nزواني خوف المقام الذمي … م، عن أن أكون خليل الزواني\nرواني صبري، فأضحت إلي … عيون، على غفلات، رواني\nعواني قضاء، دوين المراد، … وما بكر شأنك مثل العوان\nوهل جعل الشائمات الوميض … تواني، غير اتصال التواني؟\nفما، لركابك، هذي، الوقوف … عدا حادييها، الذي يرجوان\nحواني للورد أعناقها، … وما علمت أي وقت حواني\nولم يلق، في دهره، أجربي … هواني، فلينأ عني هواني\nوعندي سر بذي الحديث، … كنت عنه في العالمين الغواني\nإذا رملة لم تجىء بالنبات، … فقد جهلت إن سقتها السواني\nجريت مع الدهر جري المطيع، … بين اللياحي والأرجواني\nكأني في العيش لدن الغصو … ن، من شاء قومني أو لواني\nولا لون للماء، فيما يقال، … ولكن تلونه بالأواني\nوفي كل شر، دعته الخطوب، … شواسع منفعة، أو دواني\nوأجزاء ترياقهم لا تتم، … إلا بجزء من الأفعوان\nفلا تمدحاني يمين الثناء، … فأحسن من ذاك أن تهجواني\nوإني، من فكرتي والقضا … ء، ما بين بحرين لا يسجوان\nوإن النهار، وإن الظلام، … على كل ذي غفلة يدجوان\nوكيف النجاء، وللفرقدين … فضل، وآليت لا ينجوان\nفلم تطلبا شيمتي ناشئين، … وعما لطفت له تجفوان\nفإن تقفوا أثري تحمدا؛ … وإن تعرفا النهج لا تقفوان\nوقد أمر الحلم أن تصفحا، … ونادى بلطف: ألا تعفوان؟\nفلن تقذيا باغتفار الذنوب، … ولكن بغفرانها تصفوان\nولولا القذى طرتما في الهواء، … وفي اللج ألفيتما تطفوان\nفكونا مع الناس كالبارقين، … تعمان بالنور، أو تخفوان\nفلم تخلقا ملكي قدرة، … إذا ما هفا الإنس لا تهفوان\nألم ترنا عصري دهرنا، … يؤودان بالثقل، أو يأدوان؟\nوما فتىء الفتيان، الحياة، … يروحان بالشر، أو يغدوان\nعدوان، ما شعرا بالحمام، … فكيف تظنهما يعدوان؟\nألا تسمع، الآن، صوتيهما، … بكل امرىء فيهما يحدوان؟\nوما كشف البحث سريهما؛ … وما خلت أنهما يبدوان\nوكم سروا عالما أولا، … وما سروا، فمتى يسروان؟\nوبينهما أهلك، الغابرين، … ما يقريان، وما يقروان\nإذا ما خلا شبحي منهما، … فما يقفران، ولا يخلوان\nقلينا البقاء، ولم يبرحا … بنا، في مراحله، يقلوان\nوكم أجليا عن رجال مضوا؛ … وأخبار ما كان لا يجلوان\nكما خلقا غبرا في العصو … ر، لا يرخصان ولا يغلوان\nتمر وتحلوا لنا الحادثات، … وما يمقران ولا يحلوان\nإذا تلوا عظة، فالأنا … م لا يأذنون لما يتلوان\nمغذان بالناس، لا يلغبان، … وسيفان لله لا ينبوان\nولو خلقا مثل خلق الجياد، … رأيتهما، في المدى، يكبوان\nلعلكما، إن تهب الصبا، … إلى بلد نازح تصبوان\nفلا ريب أن الذي تحبيا … ن، أفضل منه الذي تحبوان\nفعيشا أبيين للمخزيا … ت، مثل السماكين لا تأبوان\nإذا شبت الشعريان الوقود، … ففي الحكم أنهما تخبوان\nوكونا كريمين بين الأني … س، لا تنملان، ولا تأثوان\nإذا الخل أعرض لم تلفيا، … لسوء أحاديثه، تنثوان\nوإن لم تهيلا، إلى معدم، … طعاما، فيكفيه ما تحثوان\nوجهل مراد كما في المقيظ، … عهدا من الورد والأقحوان\nوما الحاديان سوى الجندبي … ن، في حر هاجرة ينزوان\nوما أمن البازيان القصاص، … وأن يؤخذا بالذي يبزوان\nفإن تهملا كل ما تخزنان، … فلم يأت بالخزي ما تخزوان\nولا توجدا أبدا كاهنين، … تروعان قوما بما تخزوان\nونصا، إلى الله، مغزاكما، … فذلك أفضل ما تغزوان\nولا تعزوا الخير إلا إليه، … فيجني الشفاء بما تعزوان\nوإن عريت كاسيات الغصو … ن، فلتكس بالدفء من تكسوان\nوضنا بعمركما أن يضيع، … ولا تفنيا وقته تلهوان\nبذكر إلهكما، فأبها، … لعلكما بالتقى تبهوان\nفيا رب طاهي صلال يبيت، … متخذا طعمه، يطهوان\nوسيرا، وساعين، في المكرمات … ت، لا تدلجان ولا تقطوان\nمطا بكما قدر، لا يزال … جديداه، في غفلة، يمطوان\nفويح لخاطئتي مارد، … تنصان في ما له تخطوان"},{"id":"diwan-maarri:1435","bookId":"diwan-maarri","type":"poem","seq":1435,"chapter":"قصائد","title":"يا شائم البارق! لا تشجك ال","page":"","text":"يا شائم البارق! لا تشجك ال … أظعان، فوضن إلى أرض ببن\nأبن للأوطان في عازب ال … روض، فما وجدك لما أببن؟\nيشببن بالعود، ويخلفن في ال … موعود، لا كان صلاء شببن\nصببن، في الوادي، إلى قرية … غناء، لكن بالهوى ما صببن\nيسببن بالفعل، فأما إذا … قيل، فما يعلمن يوما سببن\nيحملها العيس، ومن حولها الشر … ب، قربن ضحا، أو خببن\nمهى نقاء لا مهى في نقا، … رببن في ظل قنا، أو رببن\nعقارب قاتلة من منى، … على لساني وضميري دببن\nآه من العيش وإفراطه، … ورب أيد في بقاء تببن\nتذكرني، راحة أهل البلى، … أرواح ليل بخزامى هببن\nلا تأمن الدهر، وتحويله المل … ك إلى آل إماء ضببن\nإن اللبيبات، إذا ملن للدن … يا وألغين التقى، ما لببن\nوفي مزيج الراح، أو في صريح ال … رسل، والعام جديب عببن"},{"id":"diwan-maarri:1436","bookId":"diwan-maarri","type":"poem","seq":1436,"chapter":"قصائد","title":"ضمكم جنس وأزرى بكم","page":"","text":"ضمكم جنس وأزرى بكم … قنس، وأنتم في دجى تخبطون\nحفرتم صخرا، وأنبطتم … ماء، فهلا العلم تستنبطون\nبعضكم يقتل بعضا، كأن … جوزيتم عن غنم تعبطون\nرابطتم الثغر بأفراسكم، … وفوقكم في العقل ما تربطون\nلم ترزقوا خيرا، ولم تعدموا … شرا، فما بالكم تغبطون؟\nظن، ارتقاء بكم، جاهل، … وكلكم، في صبب، تهبطون\nضبطتم المال، ولكن ما … يجمح بالإنسان لا تضبطون\nلم تقتنوا مجدا، وأصبحتم … قن فروج لكم، أو بطون"},{"id":"diwan-maarri:1437","bookId":"diwan-maarri","type":"poem","seq":1437,"chapter":"قصائد","title":"كم آية يؤنسها معشر","page":"","text":"كم آية يؤنسها معشر … فلا يبالون، ولا يتقون\nفي هوة حطوا، ومن رأيهم … أنهم، في رفعة، يرتقون\nوهم أسارى في يدي عيشهم، … لعلهم عند الردى يعتقون\nما أغدر الدهر وأبناءه، … لأنهم، من بحره، يستقون\nكم ظلم الأقوام أمثالهم، … ثمت بادوا، فمتى يلتقون؟"},{"id":"diwan-maarri:1438","bookId":"diwan-maarri","type":"poem","seq":1438,"chapter":"قصائد","title":"كل واشرب الناس على خبرة،","page":"","text":"كل واشرب الناس على خبرة، … فهم يمرون، ولا يعذبون\nولا تصدقهم، إذا حدثوا، … فإنني أعهدهم يكذبون\nوإن أروك الود، عن حاجة، … ففي حبال لهم يجذبون"},{"id":"diwan-maarri:1439","bookId":"diwan-maarri","type":"poem","seq":1439,"chapter":"قصائد","title":"قد غدت النحل إلى نورها؛","page":"","text":"قد غدت النحل إلى نورها؛ … ويحك يا نحل لمن تكسبين؟\nيجيء مشتار بآلاته، … فيلسب الأري ولا تلسبين\nأتحسبين العمر علما به، … لا بل تعيشين ولا تحسبين\nهل لك بالآباء من خبرة، … كم والد في زمن تنسبين\nأتحسبين الدهر ذا غفلة، … هيهات! ما الأمر كما تحسبين!"},{"id":"diwan-maarri:1440","bookId":"diwan-maarri","type":"poem","seq":1440,"chapter":"قصائد","title":"سنك خير لك من درة","page":"","text":"سنك خير لك من درة … زهراء، تعشي أعين الناظرين\nعجبت للضارب في غمرة، … لم يطع الناهين والآمرين\nيكسر باللؤلؤ، من جهله، … خشبا عتت عن أنمل الكاسرين\nمن كان، من أسراه، مال له، … فلست، للمال، من الآسرين\nأعد أسنى الربح فعل التقى، … فلا أكن، رب، من الخاسرين"},{"id":"diwan-maarri:1441","bookId":"diwan-maarri","type":"poem","seq":1441,"chapter":"قصائد","title":"مضى زماني، وتقضى المدى،","page":"","text":"مضى زماني، وتقضى المدى، … فليتني وفقت في ذا الزمين\nأرزمت الناب، وعارضتها، … فليعجب السامع للمرزمين\nأمطرنا الله بإحسانه، … لا أنسب الغيث إلى المرزمين\nليت دموعي بمنى سيلت، … ليشرب الحجاج من زمزمين"},{"id":"diwan-maarri:1442","bookId":"diwan-maarri","type":"poem","seq":1442,"chapter":"قصائد","title":"إن شئتما أن تنسكا، فاسكنا،","page":"","text":"إن شئتما أن تنسكا، فاسكنا، … وأنفقا المال الذي تمسكان\nواعتقدا، في حال تقواكما، … أنكما بالله لا تشركان\nإن تتبعا في مذهب جاهلا، … فالحق، من خلقكما، تتركان\nوتطلبان الأمر يعييكما؛ … وتفنيان العمر لا تدركان\nلم يفد سابور ولا تبعا، … ما وجدا من ذهب، يملكان\nونير الليل وشمس الضحا … داما، ولكنهما يهلكان\nسبحان من سخر نجم الدجى … والبدر، في قدرته، يسلكان\nهذا الفتى أوقح من صخرة، … يبهت من ناظره حيث كان\nويدعي الإخلاص في دينه، … وهو، عن الإلحاد، في القول، كان\nيزعم أن العشر ما نصفها … خمس، وأن الجسم لا في مكان"},{"id":"diwan-maarri:1443","bookId":"diwan-maarri","type":"poem","seq":1443,"chapter":"قصائد","title":"كم صرف المولود، عن والد،","page":"","text":"كم صرف المولود، عن والد، … خيرا، وكم أم له لم يمن\nالربع للزوجة، إن لم يكن … نسل، وإن كان غدت بالثمن\nوالزوج يزوي النصف أبناؤه … عنه، وفي الدهر خطوب كمن\nقال أناس: باطل زعمهم؛ … فراقبوا الله ولا تزعمن\nفكر يزدان، على غرة، … فصيغ من تفكيره أهرمن"},{"id":"diwan-maarri:1444","bookId":"diwan-maarri","type":"poem","seq":1444,"chapter":"قصائد","title":"لقد فقد الخير بين الأنا","page":"","text":"لقد فقد الخير بين الأنا … م والشر في كل وجه يعن\nأعن بجميل، إذا ما حضرت، … وعد بالسكوت إذا لم تعن\nوإن جاءك الموت، فافرح به، … لتخلص من عالم قد لعن\nهم ضربوا حيدرا ساجدا، … وحسبك من عمر، إذ طعن"},{"id":"diwan-maarri:1445","bookId":"diwan-maarri","type":"poem","seq":1445,"chapter":"قصائد","title":"ليبك مسن شاب ثم أجله","page":"","text":"ليبك مسن شاب ثم أجله … معاشر، لما قيل أشيب، أجله\nإذا سألوا عن مذهبي، فهو بين، … وهل أنا إلا مثل غيري أبله؟\nخلقت من الدنيا، وعشت كأهلها، … أجد، كما جدوا، وألهو، كما لهوا\nوأشهد أني بالقضاء حللتها، … وأرحل عنها خائفا أتأله\nوما النفس بالفعل الجميل مدلة؛ … ولكن عقلي من حذار مدله"},{"id":"diwan-maarri:1446","bookId":"diwan-maarri","type":"poem","seq":1446,"chapter":"قصائد","title":"لعمري! لخير الذخر، في كل شدة،","page":"","text":"لعمري! لخير الذخر، في كل شدة، … إلهك ترجو فضله وألاه\nفلا تشبه الوحشي خلف طفله … لخنساء، ترعى، بالمغيب، طلاه\nوإن نلت في دنياك، للجسم، نعمة … من العيش، فاذكر دفنه وبلاه\nإذا اختصمت في سيء الفعل وابنها … فلا هي من أهل الحقوق، ولا هو\nمتى يصرم الخل المسيء، فلا ترع، … فأفضل من وصل اللئيم قلاه\nوكم غيب الإلف الشقيق أليفه، … فريع له، الأيام، ثم سلاه\nوما كان حادي العيس في غربة النوى … علي، كحادي النجم حين قلاه\nومن يحلف الأيمان بالله، ولا ونى … عن الود، يحنث، أو يضره ألاه\nومن ترك العلج المعرد، راتعا … بأفيح، يقرو في الخلاء خلاه\nوقد كلأ المسكين، في الورد، بائس، … ومن كبد القوس الكتوم كلاه\nفطلق عرسا كارها، وفلا الردى، … لها تولبا، لم يمتنع بفلاه\nفلا تقر هم النفس، عجزا عن القرى، … وأدلج، إذا ما الركب مال طلاه\nطوى عنك، سرا، صاحب، قبل شيبه، … فلما انجلى عنه الشباب جلاه\nولا ملك إلا للذي عز وجهه، … ودامت، على مر الزمان، علاه\nوقد يدرك المجد الفتى وهو مقتر، … كثير الرزايا، مخلق سملاه\nغدا جملاه يرقلان بكوره، … وهل غير عصري دهره جملاه؟\nوما فتلاه عن سجاياه، بعدما … أجاد كتابا محكما، فتلاه\nفإن مات، أو غاداه قتل، فما هما … أماتاه، في حكمي، ولا قتلاه\nيد حملت هذا الأنام عليهما، … ولولا يمين الله ما احتملاه\nوعاءان للأشياء، ما شذ عنهما … قليل، ولا ضاقا بما شملاه\nوجاء بمين مدع، جاء زاعما … بأنهما عن حاجة ختلاه\nعجبت لرامي النبل يقصد آبلا، … بجهل، وقد راحت له إبلاه\nبدا عارضا خير وشر لشائم، … وما استويا في الخطب، إذ وبلاه\nزجرتهما زجر ابن سبع سباعه، … ولو فهما زجري لما قبلاه\nتهاوى جبال من كنانة غالب، … وأبطحها لم ينتقل جبلاه\nإذا النسل أسواه الأب، اهتاج أنه … يموت، ويبقى ماله وحلاه\nفكم ولد، للوالدين، مضيع، … يجازيهما بخلا بما نجلاه\nطوى عنهما القوت الزهيد، نفاسة، … وجراه سارا الحزن، وارتحلاه\nيرى فرقدي وحشية بدليهما، … وما فرقدا مسراهما بدلاه\nولامهما عن فرط حبهما له، … وفي بغضه إياهما عذلاه\nأساء، فلم يعد لهما بشراكه، … وكانا، بأنوار الدجى، عدلاه\nيعيرهما طرفا، من الغيظ، شافنا، … كأنهما، فيما مضى، تبلاه\nينام، إذا ما أدنفا، وإذا سرى … له الشكوبات، الغمض ما اكتحلاه\nإن ادعيا، في وده، الجهد صدقا، … وما اتهما فيه، فينتحلاه\nيغشهما في الأمر هان، وطالما … أفاءا عليه النصح، وانتخلاه\nيسرهما أن يهجر الريم، دهره، … وأنهما من قبله نزلاه\nولو بمشار العين يوحى إليهما، … لوشك اعتزال العيش، لاعتزلاه\nيودان، إكراما، لو انتعل السها … وإن حذيا السلاء وانتعلاه\nيذم لفرط الغي ما فعلا به؛ … وأحسن وأجمل بالذي فعلاه\nيعدانه كالصارم العضب في العدى … بظنهما، والذابل اعتقلاه\nويؤثر بالسر الكنين سواهما، … فينقله عنه وما نقلاه"},{"id":"diwan-maarri:1447","bookId":"diwan-maarri","type":"poem","seq":1447,"chapter":"قصائد","title":"أعوذ بالله من قوم، إذا سمعوا","page":"","text":"أعوذ بالله من قوم، إذا سمعوا … خيرا أسروه، أو شرا أذاعوه\nما حم كان ولم تدفعه مشفقة، … ويفعل الأمر، في الدنيا، مطاعوه\nإن النجاشي نال الملك، عن قدر، … برغم ناس، لبعض التجر باعوه\nوخالد بن سنان ليس ينقصه، … من قدره، الكون في حي أضاعوه\nما لي رأيت دعاة الغي ناطقة، … والرشد يصمت، خوف القتل، داعوه\nلا يفرحن بمولود ذوو شرف، … فإنما بشراء الطفل ناعوه\nكذلك الدهر غنى من يصاحبه، … ولم يعد، بسوى الخسران، ساعوه\nوالله حق، وإن ماجت ظنونكم، … وإن أوجب شيء أن تراعوه"},{"id":"diwan-maarri:1448","bookId":"diwan-maarri","type":"poem","seq":1448,"chapter":"قصائد","title":"قد ينصف القوم، في الأشياء، سيدهم،","page":"","text":"قد ينصف القوم، في الأشياء، سيدهم، … ولو أطاقوا له ريبا لرابوه\nلم يقدروا أن يلاقوه بسيئة … من الكلام، فلما غاب عابوه\nتحدثوا بمخازيه، مكتمة، … وقابلوه بإجلال، وهابوه\nوكم أرادوا له كيدا بيوم ردى، … من الزمان، ولكن ما أصابوه\nأكدى، فلاموه لما قل نائله، … ولو حبا الوفر زاروه ونابوه\nصبرا قليلا، فإن الموت آخذه، … وما يخلف لا صقر ولا بوه\nلبى الغني بنو حواء، من طمع، … ولو دعاهم فقير ما أجابوه"},{"id":"diwan-maarri:1449","bookId":"diwan-maarri","type":"poem","seq":1449,"chapter":"قصائد","title":"أخوك معذب يا أم دفر،","page":"","text":"أخوك معذب يا أم دفر، … أظلته الخطوب وأرهقته\nوما زالت معاناة الرزايا … على الإنسان، حتى أزهقته\nكأن حوادث الأيام آم، … تريق بجهلها ما أدهقته\nتروقك من مشاربها بمر، … وكل شرابها ما روقته\nونفسي والحمامة لم تطوق، … ميسرة لأمر طوقته\nأرى الدنيا، وما وصفت ببر، … متى أغنت فقيرا أوهقته\nإذا خشيت لشر عجلته؛ … وإن رجيت لخير عوقته\nحياة، كالحبالة، ذات مكر؛ … ونفس المرء صيد أعلقته\nوأنظر سهمها قد أرسلته … إلي بنكبة، أو فوقته\nفلا يخدع، بحيلتها، أريب، … وإن هي سورته ونطقته\nتعلقها ابن أمك في صباه، … فهام بفارك ما علقته\nأجدت في مناه وعود مين، … إلى أن أخلفته، وأخلقته\nيطلق عرسه، إن مل منها، … ويأسف إثر عرس طلقته\nأكلته، النهار، وأنصبته، … وأشكته، الظلام، وأرقته\nسقته زمانه مقرا وصابا، … وكأس الموت آخر ما سقته\nوما عافته، لكن عيفته؛ … وما نتقت علاه، بل انتقته\nنبكي للمغيب في ثراه، … وذلك مسترق أعتقته\nعجوز خيانة حضنت وليدا، … فلدته الكريه وشرقته\nأذاقته شهيا من جناها، … وصدت فاه عما ذوقته\nتشوقه إليه بسوء طبع، … ليشقيه عذاب شوقته\nأضرت بالصفا وتخونته، … ومرت بالصفاء فرنقته\nعددنا من كتائبها المنايا، … وكم فتكت بجمع فرقته\nقضت دين ابن آمنة، وجازت … بإيوان ابن هرمز فارتقته\nطوت عنه النسيم، وقد حبته، … وحيته بنور فتقته\nكسته شبابه ونضته عنه، … وكرت للمشيب، فمزقته\nوعاثت في قواه فحلمته، … وقدما أيدته فنزقته\nتميت مسافرا، ظلما، بهجل، … وفي بحر المهالك غرقته\nفإما في أريز أخصرته، … وإما في هجير حرقته\nوما حقنت، دم الإنسان فيها، … رموس في الرغام تفوقته\nوقد رفعت غمائم للرزايا، … على وجه التراب، فطبقته\nتؤمل مخلصا من ضيق أمر، … وليس يفك عان أوثقته\nهي افتتحت له، في الأرض، بيتا، … فبوته النزيل، وأطبقته\nونحن المزمعون وشيك سير، … لنسلك في طريق طرقته\nهوت أم لنا غدرت وخانت، … ولم تشف السليل ولا رقته\nإذا التفت ابنها عنها بزهد، … ثنته بزخرفي نمقته\nولو قدر العبيد على إباق، … لبادر عبد سوء أوبقته\nأقات الشيء بعد الشيء فيها، … ليمسكني، فليتي لم أقته\nعذلت حشاشة حرصت عليها، … فجاءتني بعذر لفقته\nوتسأل عن بقاء أعطيته، … غدا، في أي شيء أنفقته\nولست بفاتح للرزق بابا، … إذا أيدي الحوادث أغلقته\nتمنى دولة رجل غبي، … ولو حاز الممالك ما وقته\nوإن الملك طود أثبتته … صروف الدهر، ثمت أقلقته\nومن يظفر بأمر يبتغيه، … فأقضية المهيمن وفقته\nلنا مهج يمازجها خداع، … تود قسيها لو نفقته\nووالدة بنت جسدا بنحض، … وفاءت فيئة، فتعرقته\nتوطأت الفطيم، على اعتماد، … فما أبقت عليه، ولا اتقته\nولم تك رائما ساءت رضيعا، … وحنت بعدها فتملقته\nحياتك هجعة: سهد ونوم، … ورؤيا هاجع ما أنقته\nفمن حلم يسرك أبطلته؛ … ومن حلم يضرك حققته\nوكم أدى، أمانته إليها، … أمين خونته، وسرقته\nوقائم أمة زكته عصرا، … فلما أن تمكن، فسقته\nوإن أدنت لنا أملا، فقلنا: … أتانا، أبعدته وأسحقته\nووقتي كالسفينة سيرته، … ومن سوء الجرائم أوسقته\nحثت، يبس الرغام على رضيع، … يد، بأبيه آدم ألحقته\nوكم صالت، على بر تقي، … أكف، بالمواهب أرفقته\nوأنفاسي موكلة بروح … أراحتها، وعمر أمحقته"},{"id":"diwan-maarri:1450","bookId":"diwan-maarri","type":"poem","seq":1450,"chapter":"قصائد","title":"قد اختل الأنام بغير شك،","page":"","text":"قد اختل الأنام بغير شك، … فجدوا في الزمان وألعبوه\nوظنوا أن بوه الطير صقر، … بجهلهم، وأن الصقر بوه\nوودوا العيش في زمن خؤون، … وقد عرفوا أذاه وجربوه\nوينشأ ناشىء الفتيان، منا … على ما كان عوده أبوه\nوما دان الفتى بحجا، ولكن … يعلمه التدين أقربوه\nوطفل الفارسي له ولاة، … بأفعال التمجس دربوه\nوضم الناس كلهم هواء، … يذلل، بالحوادث، مصعبوه\nلعل الموت خير للبرايا، … وإن خافوا الردى وتهيبوه\nأطاعوا ذا الخداع وصدقوه، … وكم نصح النصيح، فكذبوه\nوجاءتنا شرائع كل قوم، … على آثار شيء رتبوه\nوغير بعضهم أقوال بعض، … وأبطلت النهى ما أوجبوه\nفلا تفرح، إذا رجبت فيهم، … فقد رفعوا الدني، ورجبوه\nوبدل ظاهر الإسلام رهط، … أرادوا الطعن فيه وشذبوه\nوما نطقوا به تشبيب أمر، … كما بدأ المديح مشببوه\nويذكر أن، في الأيام، يوما، … يقوم من التراب مغيبوه\nوما يحدث، فإنا أهل عصر، … قليل، في المعاشر، منجبوه\nصحبنا دهرنا دهرا، وقدما … رأى الفضلاء أن لا يصحبوه\nوغيظ به بنوه وغيظ منهم، … فعذب ساكنيه وعذبوه\nومن عاداته في كل جيل … غذاه، أن يقل مهذبوه\nأساء بغيه أدبا عليهم، … فهل من حيلة، فيؤدبوه؟\nوما يخشى الوعيد، فيوعدوه؛ … ولا يرعى العتاب، فيعتبوه\nوهل ترجى الكرامة من أوان، … وقد غلب الرجال مغلبوه؟\nوهل، من وقتهم، أبغى وأطغى، … على أي المذاهب قلبوه؟\nأجلوا مكثرا، وتنصفوه؛ … وعابوا من أقل، وأنبوه\nولم يرضوا ، لما سكنوه، شيدا، … إلى أن فضضوه وأذهبوه\nفإن يأكلهم أسفا وحقدا، … فقد أكل الغزال مرببوه\nوتلك الوحش، ما جادوا عليها … بعشب، غب ند عشبوه\nيسور الكلب مجتهدا إليها، … ويحظى، بالقنيص، مكلبوه\nرجوا أن لا يخيب لهم دعاء، … وكم سأل الفقير، فخيبوه\nوما شأن اللبيب بغير سلم، … وإن شهد الوغى متلببوه\nألظوا بالقبيح، فتابعوه، … ولو أمروا به لتجنبوه\nنهاهم عن طلاب المال زهد، … ونادى الحرص: ويبكم اطلبوه\nفألقاها إلى أسماع غثر، … إذا عرفوا الطريق تنكبوه\nسعوا بين اقتراب واغتراب، … يموت بغصة متغربوه\nغدوا قوتا لمثلهم، تساوى … خبيثوه، لديه، وأطيبوه\nمضت أمم على شرخ الليالي، … إذا عمدوا لعقد أربوه\nوكم تركوا لنا أثرا منيفا، … يعود بآية متأوبوه\nلقد عمروا، وأقسمت الرزايا؛ … لبئس الرهط رهط خربوه\nفإما عاث فيه حاسدوه؛ … وإما غاله متكسبوه\nوللأرمين خطب مستفيض، … يعوم بلجه متعجبوه\nولو قدروا على إيوان كسرى، … لساموه الردى، وتعقبوه\nوقد منوا برزق الله جهلا، … كأنهم لباغ سببوه\nإذا أصحاب دين أحكموه، … أذالوا ما سواه وعيبوه\nوقد شهد النصارى: أن عيسى … توخته اليهود، ليصلبوه\nوقد أبهوا، وقد جعلوه ربا، … لئلا ينقصوه ويجدبوه\nتمج قلوبهم ما أودعته؛ … لسوء في الغرائز، أشربوه\nأضاعوا السر لما استحفظوه؛ … وقد صانوا الأديم وسربوه\nلهم نسب الرغام، وذاك طهر، … ولم يطهر به متنسبوه\nونبىء، في بني يعقوب، موسى … بشرع ما تخلص متعبوه\nوقد نضت النواظر، كل عام، … وأتراب السعادة متربوه\nعلى حجر لهم تهوي جبال، … ولم يستعف ذنبا مذنبوه\nودون الأبيض المشتار زغب … لواسب، عقنهم أن يلسبوه\nوقد ركب الذين مضوا سبيلا … إلى عليائهم، لم يركبوه\nوحبل العيش منتكث ضعيف، … ونعم الرأي أن لا تجذبوه\nوما فعلوه، ولكن باكروه … بأسباب الحمام، فقضبوه\nفمن سيف، ومن رمح وسهم، … ونصل أرهفوه وذربوه\nوما دفعت عن الملك المنايا … مقانبه، ولا متكتبوه\nحسبتم يا بني حواء شيئا، … فجاءكم الذي لم تحسبوه\nوجيران الغريب مبغضوه … إلى جلاسهم، ومحببوه\nفإن يولوا قبيحا يذكروه؛ … وإن يحبوا يشيعوا ما حبوه\nتقول الهند: آدم كان قنا … لنا، فسرى إليه مخببوه\nأولئك يحرقون الميت نسكا، … ويشعره لبانا ملهبوه\nولو دفنوه في الغبراء، جاءت … بما يسعى له متألبوه\nأديل الشر منكم، فاحذروه، … ومات الخير منكم، فاندبوه"},{"id":"diwan-maarri:1451","bookId":"diwan-maarri","type":"poem","seq":1451,"chapter":"قصائد","title":"تهجد معشر، ليلا، ونمنا،","page":"","text":"تهجد معشر، ليلا، ونمنا، … وفاز بحندس متهجدوه\nإلهك أوجد الأشياء جمعا، … فلا يفخر بشيء موجدوه\nوربك أنجد الأقوام، حتى … بنى أعلى القصور منجدوه\nفمجده، فلم يخسر أناس … أنابوا للمليك ومجدوه"},{"id":"diwan-maarri:1452","bookId":"diwan-maarri","type":"poem","seq":1452,"chapter":"قصائد","title":"ظلمتم غيركم فأديل منكم،","page":"","text":"ظلمتم غيركم فأديل منكم، … وأخيار الأنام مظلموه\nتهاونتم بمطران النصارى، … وأشياع ابن مريم عظموه\nوقال لكم نبيكم: إذا ما … كريم القوم جاء، فأكرموه\nفلا يرجع خطيبكم بحقد، … متى لاقاهم، فتهضموه"},{"id":"diwan-maarri:1453","bookId":"diwan-maarri","type":"poem","seq":1453,"chapter":"قصائد","title":"تحمل عن أبيك الثقل، يوما،","page":"","text":"تحمل عن أبيك الثقل، يوما، … فإن الشيخ قد ضعفت قواه\nأتى بك عن قضاء لم ترده، … وآثر أن تفوز بما حواه\nصديقك في الجهار عدو سر، … فلا تأسف إذا شحطت نواه\nركنت إلى الفقير، بغير علم، … وكم زور لسائله رواه\nوما في نشر هذا الخلق نعمى، … فهل يلحى الزمان إذا طواه؟\nفصيل أخيك يشكو طول ظمء، … بما لاقى فصيلك من غواه\nوكيف يؤمل الإنسان رشدا، … وما ينفك متبعا هواه\nيظن بنفسه شرفا وقدرا، … كأن الله لم يخلق سواه\nألا تثني جمالك نحو مرعى، … فهذا الرمل لم ينبت لواه\nولست بمدرك أمرا قريبا، … إذا ما خالقي عني زواه"},{"id":"diwan-maarri:1454","bookId":"diwan-maarri","type":"poem","seq":1454,"chapter":"قصائد","title":"الراهب المسجون، فرط عبادة،","page":"","text":"الراهب المسجون، فرط عبادة، … من حب دنياه الكذوب موله\nأعرفتم أصحابكم بحقيقة، … أم كلكم عنهم غبي أبله؟\nذكر التأله، فادعوه تخرصا؛ … ما هذه أفعال من يتأله"},{"id":"diwan-maarri:1455","bookId":"diwan-maarri","type":"poem","seq":1455,"chapter":"قصائد","title":"لم يبق في العالمين من ذهب،","page":"","text":"لم يبق في العالمين من ذهب، … وإنما جل من ترى شبه\nدعهم، فكم قطعت رقابهم … جدعا، ولم يشعروا، ولا أبهوا\nقد مزجوا بالنفاق، فامتزجوا، … والتبسوا في العيان، واشتبهوا\nوما لأقوالهم، إذا كشفت، … حقائق، بل جميعها شبه\nقد ذهبت عادهم وجرهمها، … وهم على ما عهدت ما انتبهوا"},{"id":"diwan-maarri:1456","bookId":"diwan-maarri","type":"poem","seq":1456,"chapter":"قصائد","title":"أسهب الناس في المقال، وما يظ","page":"","text":"أسهب الناس في المقال، وما يظ … فر، إلا بزلة، مسهبوه\nعجبا للمسيح بين أناس، … وإلى الله والد نسبوه\nأسلمته إلى اليهود النصارى، … وأقروا بأنهم صلبوه\nيشفق الحازم اللبيب على الطف … ل، إذا ما لداته ضربوه\nوإذا كان ما يقولون في عي … سى صحيحا، فأين كان أبوه؟\nكيف خلى وليده للأعادي، … أم يظنون أنهم غلبوه؟\nوإذا ما سألت أصحاب دين، … غيروا، بالقياس، ما رتبوه\nلا يدينون بالعقول، ولكن … بأباطيل زخرف كذبوه"},{"id":"diwan-maarri:1457","bookId":"diwan-maarri","type":"poem","seq":1457,"chapter":"قصائد","title":"إذا كنت قد أوتيت لبا وحكمة،","page":"","text":"إذا كنت قد أوتيت لبا وحكمة، … فشمر عن الدنيا، فأنت منافيها\nوكونن لها، في كل أمر، مخالفا، … فما لك خير في بنيها ولا فيها\nوهيهات ما تنفك ولهان، مغرما … بورهاء، لا تعطي الصفاء مصافيها\nفإن تك هذي الدار منزل ظاعن، … فدار مقامي، عن قليل، أوافيها\nأرجي أمورا لم يقدر بلوغها، … وأخشى خطوبا والمهيمن كافيها\nوإن صريع الخيل غير مروع، … إذا الطير همت بالقتيل عوافيها\nبغبراء لم تحفل بطل ووابل؛ … ونكباء تسفي، بالعشي، سوافيها\nأرى مرضا بالنفس ليس بزائل؛ … فهل ربها مما تكابد شافيها؟\nوفي كل قلب غدرة مستكنة، … فلا تخدعن من خلة بتوافيها"},{"id":"diwan-maarri:1458","bookId":"diwan-maarri","type":"poem","seq":1458,"chapter":"قصائد","title":"تنازع في الدنيا سواك، وما له","page":"","text":"تنازع في الدنيا سواك، وما له … ولا لك شيء، بالحقيقة، فيها\nولكنها ملك لرب مقدر، … يعير جنوب الأرض مرتدفيها\nولم تحظ في ذاك النزاع بطائل … من الأمر، إلا أن تعد سفيها\nأيا نفس! لا تعظم عليك خطوبها، … فمتفقوها مثل مختلفيها\nوصفت لقوم رحمة أزلية، … ولم تدركي، بالقول، أن تصفيها\nتداعوا إلى النزر القليل، فجالدوا … عليه، وخلوها لمغترفيها\nوما أم صل، أو حليلة ضيغم، … بأظلم من دنياك، فاعترفيها\nتلاقي الوفود القادميها بفرحة، … وتبكي على آثار منصرفيها\nولم يتوازن، في القياس، نعيمها … وسيئة أودت بمقترفيها\nوأرزاقها تغشى أناسا بفترة، … وتقصر، حينا، دون مكترفيها\nوما هي إلا شاكة ليس عندها … وجدك، إرطاب لمخترفيها\nفنالت، على الخضراء، شرب كميتها، … وغالت، على الغبراء، معتسفيها\nكما نبذت، للوحش والطير، رازم، … فألفت شرورا بين مختطفيها\nتناءت عن الإنصاف، من ضيم لم يجد … سبيلا إلى غايات منتصفيها\nفأطبق فما، عنها، وكفا ومقلة، … وقل لغوي القوم: فاك لفيها\nكأن التي في الكأس، يطفو حبابها، … سمام حباب بين مرتشفيها\nتتابع أجزاء الزمان لطائفا، … وتلحق تفريقا بمؤتلفيها"},{"id":"diwan-maarri:1459","bookId":"diwan-maarri","type":"poem","seq":1459,"chapter":"قصائد","title":"كأن أكوان أعمار، نعيش بها،","page":"","text":"كأن أكوان أعمار، نعيش بها، … خيل يبدل ماضيها بتاليها\nففذها يحمل الأشياء قاطبة، … كلحمة العين، ثم الوضع واليها\nتحط عنه لآت بعده أبدا، … فلا تبيد ولا تثني خواليها\nهون عليك، فما الدنيا بدائمة، … وليس عاطلها إلا كحاليها\nوالعقل يزعم أياما، تشاهدها … بيضا، حوادث في داجي لياليها\nنفسي بها، ونفوس القوم ملهجة، … ونحن نخبر أنا لا نباليها\nأمرتني بسلو عن خوادعها، … فانظر هل أنت، مع السالين، ساليها\nولا ترى الدهر إلا من يهيم بها، … طبعا، ولكنه باللفظ قاليها\nوالجسم لا شك أرضي، وقد وصلت … به لطائف عالاها معاليها\nفقيل جاءته من أرض على كثب، … وقيل خرت إليه من معاليها\nوالله يقدر أن تدعى بحكمته، … أواخر من براياه، أواليها"},{"id":"diwan-maarri:1460","bookId":"diwan-maarri","type":"poem","seq":1460,"chapter":"قصائد","title":"ناديت أقضية الله التي سلفت:","page":"","text":"ناديت أقضية الله التي سلفت: … إن المعالي بذتها معاليها\nوضعت نفسي، فعاليها على قتب … من الغنى، يعرف الجدوى فعاليها\nنوائب الدهر تستقري غرائزها، … حتى ترى، كحواليها، خواليها\nأما نبال المنايا، فهي مصمية … فما نبال مقال لا أباليها\nلا تمنع الغادة الحسناء نعمتها، … وأن تقوم حواليها حواليها\nوما تفيد الغواني من لآليها … نفعا، إذا جاء كيد من لياليها\nولم تجدني طغاة الناس في طمع، … حتى تعيش أواليها أواليها\nجماعة القوم جدت في تناظرها، … كعانة الوحش، جدت في تغاليها\nحق على أنفس منهم تكالؤها، … فقد يخاف عليها من تكاليها\nبطن البسيطة أعفى من ظواهرها، … فوسعا لي أهرب من سعاليها\nوما تزال دواليها نوائبها، … فمن شداد خطوب، أو دواليها\nوقد أطلت وصاليها على سخط … منى، وسيان غرقاها وصاليها\nوما استراح، لعمري، من سوائلها، … إذا طغى ماؤها، إلا سواليها"},{"id":"diwan-maarri:1461","bookId":"diwan-maarri","type":"poem","seq":1461,"chapter":"قصائد","title":"حاشيت غيري، ونفسي ما أحاشيها،","page":"","text":"حاشيت غيري، ونفسي ما أحاشيها، … خشيتها، وحليف اللب خاشيها\nواستجهلتني رجال، لم تزل جهلا، … إن الأوابي هاجتها عواشيها\nأما العراق، فعمت أرضه فتن، … مثل القيامة، غشتها غواشيها\nوالشام أصلح، إلا أن هامته … فضت، وأسرى على النيران عاشيها\nوالقوم يردون من لاقوا بأردية، … أعلامها الدم، لم تكفف حواشيها\nذوات قر يظنوا دارجات قرى … مضت عليها، ولم تقفل مواشيها\nأنستك، هندا، سيوف الهند، ماحية … ما قال عاذلها، أو قال واشيها\nوللزمان على أبنائه، أبدا، … حكومة، لا يرد الحكم راشيها"},{"id":"diwan-maarri:1462","bookId":"diwan-maarri","type":"poem","seq":1462,"chapter":"قصائد","title":"حسبي، من الجهل، علمي أن آخرتي","page":"","text":"حسبي، من الجهل، علمي أن آخرتي … هي المآل، وأني لا أراعيها\nوأن دنياي دار لا قرار بها، … وما أزال معنى في مساعيها\nكذلك النفس، ما زالت معللة … بباطل العيش، حتى قام ناعيها\nيا أمة من سفاه لا حلوم لها، … ما أنت إلا كضأن غاب راعيها\nتدعى لخير، فلا تصغى له أذنا، … فما ينادي لغير الشر داعيها"},{"id":"diwan-maarri:1463","bookId":"diwan-maarri","type":"poem","seq":1463,"chapter":"قصائد","title":"عجبت للظبي، بانت عنه صاحبة،","page":"","text":"عجبت للظبي، بانت عنه صاحبة، … لاقت جنود منايا، لا تناخيها\nفارتاع يوما ويوما ثم ثالثة، … ومال، بعد، إلى أخرى يواخيها\nما شد صرف زمان عقدة لأذى، … إلا ومر لياليه يراخيها"},{"id":"diwan-maarri:1464","bookId":"diwan-maarri","type":"poem","seq":1464,"chapter":"قصائد","title":"إني لمن آل حواء، الذين هم","page":"","text":"إني لمن آل حواء، الذين هم … ثقل على الأرض، غانيها وعافيها\nجاروا على حيوان البر، ثم عدوا … على البحار، فغال الصيد ما فيها\nلم يقنع الحي منها ما تقنصه، … حتى أجاز أناس أكل طافيها\nكم درة قصدوها في مواطنها، … لعل كفا، بمقدار، توافيها\nفاستخدموا اللجة الخضراء، تحملهم … سفائن، بين أمواج تنافيها\nوالطير جمعاء: ضعفاها وجارحها، … حتى العقاب، التي حدت أشافيها\nينافقون، وما جر النفاق لهم … خيرا، فعثرتهم معي تلافيها\nإن الظواهر لم تشبه بواطنها … مثل القوادم خانتها خوافيها\nدنياك توجد أيام السرور بها، … مثل القصيدة، لم تذكر قوافيها\nوما وفت لخليل في معاشرة، … ولا طمعنا لخل في توافيها\nأم لنا، ما فتئنا عائبين لها، … فاشتط لاح لحاها في تجافيها\nومن يطيق ورود الآجنات بها، … وقد تشرق، تارات، بصافيها؟\nوالنفس هشت إلى آس يطببها، … ولم تهش إلى رب يعافيها\nحلت بدار، فظنت أنها وطن … لها، ومالك تلك الدار نافيها\nآمالنا في الثريا، من تطاولها، … وحلمنا في رياح الطيش هافيها\nتقل أجسامنا الغبراء ثم إلى … بلى تصير، فتسفيها سوافيها\nفيا بني آدم الأغمار، ويبكم! … نفوسكم لم تمكن من تصافيها\nسرتم على الماء في الحاجات آونة، … أما قنعتم بسير في فيافيها؟\nتخاذل الناس، فارتاحت عداتهم، … إن المعاشر يرديها تقافيها\nوالنفس لم يلف عنها، مغنيا، بدن، … إن المراجل نصتها أثافيها\nيعرى الكريم، فيعرى بعد مذهبة … صفراء، لا يهجر الصحراء ضافيها\nرحل على ناقة عفراء من عمر، … فقد سريت لغايات توافيها\nوما علافيها إلا يجد لها … ذما على في، أو ذما على فيها\nهذي الحياة، إذا ما الدهر خرقها، … فما بنان أخي صنع برافيها\nوالموت داء البرايا، لا يفارقها؛ … ولا يؤمل أن الله شافيها\nوليس فارسها إلا كراجلها، … وقد يرى محتذيها مثل حافيها"},{"id":"diwan-maarri:1465","bookId":"diwan-maarri","type":"poem","seq":1465,"chapter":"قصائد","title":"كم حاول الرجل الدنيا بقوته","page":"","text":"كم حاول الرجل الدنيا بقوته … وماله، فخطته، أو تخطاها\nوقد يروم ضعيف نيل آخرة، … فلا يشك لبيب أن سيعطاها\nوالموت يعدو على الآساد، مخدرة، … والعين بين خزاماها وأرطاها\nوذات قرطين في حلي تعدهما، … قد صار أجرا لذات الغسل قرطاها"},{"id":"diwan-maarri:1466","bookId":"diwan-maarri","type":"poem","seq":1466,"chapter":"قصائد","title":"لو أن كل نفوس الناس رائية","page":"","text":"لو أن كل نفوس الناس رائية … كرأي نفسي، تناءت عن خزاياها\nوعطلوا هذه الدنيا، فما ولدوا، … ولا اقتنوا، واستراحوا من رزاياها"},{"id":"diwan-maarri:1467","bookId":"diwan-maarri","type":"poem","seq":1467,"chapter":"قصائد","title":"يا أمة ما لها عقول،","page":"","text":"يا أمة ما لها عقول، … وفقد ألبابها دهاها\nتسلت النفس عن كل شيء، … إلا نهاها وما نهاها\nفحدثوني، بغير مين، … عن الثريا وعن سهاها\nأتعلم الأرض، وهي أم، … خف زمان فما ازدهاها\nبأي جرم، وأي حكم، … سلط ليث على مهاها\nوعذرت حاجة، بعسر، … على عليل قد اشتهاها\nوظالم عنده كنوز، … من أم دفر ومن لهاها\nكان، إذا ما دجا ظلام، … صاح بأجماله وهاها"},{"id":"diwan-maarri:1468","bookId":"diwan-maarri","type":"poem","seq":1468,"chapter":"قصائد","title":"دنيا الفتى هذه عدو،","page":"","text":"دنيا الفتى هذه عدو، … تفريه، عمدا، بمنصليها\nغناه فيها، عن الغواني، … أجمل من فقره إليها\nوصبره، في الشباب، عنها، … أيسر من صبره عليها"},{"id":"diwan-maarri:1469","bookId":"diwan-maarri","type":"poem","seq":1469,"chapter":"قصائد","title":"إذا ابتكرت إلى العراف، فاعرف","page":"","text":"إذا ابتكرت إلى العراف، فاعرف … مكان عصا تصك بها قراها\nوساورها، إذا أبدت سوارا، … وبارئها متى كشفت براها\nوحذرها المنجم، فهو ذئب، … تشوقه الضوائن أن يراها\nفإن هي لم تجبه إلى قبيح، … تحلبها المنافع، وامتراها\nيقول لها زخارف معربات، … فراها الأولون، أو افتراها\nوقد يجفو الكرى منها جفونا، … إذا ما حل في ساق كراها"},{"id":"diwan-maarri:1470","bookId":"diwan-maarri","type":"poem","seq":1470,"chapter":"قصائد","title":"قران المشتري زحلا يرجى","page":"","text":"قران المشتري زحلا يرجى … لإيقاظ النواظر، من كراها\nوهيهات البرية في ضلال، … وقد فطن اللبيب لما اعتراها\nوكم رأت الفراقد والثريا … قبائل، ثم أضحت في ثراها\nتقضى الناس جيلا بعد جيل، … وخلفت النجوم كما تراها\nقراء الوحش، وهي مسومات، … بربات المعاطف من قراها\nوما ظلم العشير ولا قراه، … ظليم المقفرات، ولا قراها\nإذا رجع الحصيف إلى حجاه، … تهاون بالمذاهب وازدراها\nفخذ منها بما أداه لب، … ولا يغمسك جهل في صراها\nوهت أديانهم من كل وجه … فهل عقل يشد به عراها؟\nأتعلم جارسات في جبال، … أراها قبلها سلف، أراها\nبما فيه المعاشر من فساد، … توارى في الجوانح، أو وراها\nقضاء من إلهك مستمر، … غدت منه المعاطس في براها\nيحط إلى الفوادر، كل حين، … منيعات الفوادر من ذراها\nوما تبقى الأراقم في حماها؛ … ولا الأسد الضراغم في شراها\nتقدم صاحب التوراة موسى، … وأوقع، في الخسار، من اقتراها\nوقال رجاله: وحي أتاه؛ … وقال الظالمون: بل افتراها\nأعبري تهوك في حديث، … فباع المشكلات، كما اشتراها\nوغايات بسطن إلى أمور، … جراها الآجرون، كما جراها\nأرى أم القرى خصت بهجر، … وسارت نمل مكة عن قراها\nوكم سرت الرفاق إلى صلاح، … فمارست الشدائد في سراها\nيوافون البنية، كل عام، … ليلقوا المخزيات على قراها\nضيوف، ما قراها الله عفوا، … ولكن من نوائبها قراها\nوما سيري إلى أحجار بيت، … كؤوس الخمر تشرب في ذراها\nولم تزل الأباطح، منذ كانت، … يدنس، من فواجرها، براها\nوبين يدي جميع الناس خطب، … له نسيت مولعة غراها\nمهالك، إن أجزت الخرق منها، … فأنت سليكها، أو شنفراها\nبدت كرة، كأن الوقت لاه … بها، عز المهيمن إذ كراها\nتبارك من أدار بنات نعش، … ومن برأ النعائم في حراها\nتمارى القوم في الدعوى، وهبوا … إلى الدنيا، فكلهم مراها\nوكم جمع النفائس رب مال، … فلما جد مرتحلا ذراها\nتظل عيون هذا الدهر خزرا، … تعد الماشيات وخوزراها\nكتائب، منسراها الليل يتلى … بصبح، كيف يؤمن من سراها\nوأدواء ثوى بقراط، ميتا، … وجالينوس فاد وما دراها\nوما انفك الزمان بغير جرم، … طوائفه تطيع من ادراها\nأهذي الدار ملك لابن أرض، … بها رام المقام أم اكتراها؟\nعلى كره تيممها، فألقى … بها رحلا، وعن سخط شراها\nوما برح الوجيف على المطايا، … وتلك نفوسنا حتى براها\nإذا ما حرة هريت وسيفت، … فمن ساف الإماء ومن هراها؟\nونحن كأننا همل بجدب، … عراة لا نمكن من عراها\nشبابك مثل جنح الليل، فانظر … أعاد إلى الشبيبة من سراها\nوما نال الهجين من المعالي، … إذا خطب الكريمة، واستراها\nأنرهب هذه الغبراء نارا، … تطبق مثل ما تهوي سراها؟\nفإن الله غير ملوم فعل، … إذا أورى الوقود على وراها"},{"id":"diwan-maarri:1471","bookId":"diwan-maarri","type":"poem","seq":1471,"chapter":"قصائد","title":"أتت خنساء مكة، كالثريا،","page":"","text":"أتت خنساء مكة، كالثريا، … وخلت في المواطن فرقديها\nولو صلت بمنزلها وصامت، … لألفت ما تحاوله لديها\nولكن جاءت الجمرات ترمي، … وأبصار الغواة إلى يديها\nوليس محمد، فيما أتته، … ولا الله القدير بمحمديها\nإذا ما رامت الصلوات خود، … يظن هناك أفضل ملحديها"},{"id":"diwan-maarri:1472","bookId":"diwan-maarri","type":"poem","seq":1472,"chapter":"قصائد","title":"كيف يصفو المقيم في أم دفر،","page":"","text":"كيف يصفو المقيم في أم دفر، … وهو من كل وجهة يصطفيها؟\nمن ديار قد جاءها القادم الآ … تي، فلم يعتبر بمنصرفيها\nواختلاف، من الشؤون، على … أن السجايا تضم مختلفيها\nوبزاة الأنيس تختطف الل … ذات، لو سلمت لمختطفيها\nعربي يسعى إلى الجارة الدن … يا، فيدعى لما جناه سفيها\nوترى الكاسكي يختار عرسا، … من سوى القرية التي هو فيها"},{"id":"diwan-maarri:1473","bookId":"diwan-maarri","type":"poem","seq":1473,"chapter":"قصائد","title":"تفقهت في الدنيا، فلم تلف طائلا،","page":"","text":"تفقهت في الدنيا، فلم تلف طائلا، … ولا خير في كسب أتاك من الفقه\nوإن تشرب الصهباء تعقبك شهوة، … ولكن من الموت الشراب الذي يقهي"},{"id":"diwan-maarri:1474","bookId":"diwan-maarri","type":"poem","seq":1474,"chapter":"قصائد","title":"وجدت سجايا الفضل، في الناس، غربة،","page":"","text":"وجدت سجايا الفضل، في الناس، غربة، … وأعدم هذا الدهر مغتربيه\nوإن الفتى، فيما أرى، بزمانه … لأشبه منه شيمة بأبيه\nووالدنا هذا التراب، ولم يزل … أبر يدا من كل منتسبيه\nيؤدي إلى من فوقه رزق ربه، … أمينا، ويعطي الصون محتجبيه\nولا شيء مثل الخير يزمع تركه، … ويصبح مبذولا لمكتسبيه\nويقسم حظ النفس، شرقا ومغربا، … على قدر من خامل ونبيه\nتشابهت الأشياء طبعا وصورة، … وربك لم يسمع له بشبيه"},{"id":"diwan-maarri:1475","bookId":"diwan-maarri","type":"poem","seq":1475,"chapter":"قصائد","title":"متى ما تخالط عالم الإنس لا يزل،","page":"","text":"متى ما تخالط عالم الإنس لا يزل، … بسمعك، وقر من مقال سفيه\nإذا ما الفتى لم يرم شخصك، عامدا، … بكفيه عن ضغن، رماك بفيه\nوقد علم الله اعتقادي، وإنني … أعوذ به من شر ما أنا فيه"},{"id":"diwan-maarri:1476","bookId":"diwan-maarri","type":"poem","seq":1476,"chapter":"قصائد","title":"فتاة بغت أمرا من الدهر معجزا،","page":"","text":"فتاة بغت أمرا من الدهر معجزا، … وما رأيها لو مكنت بسفيه؟\nلتفدي عمرا، جمة شركاؤه، … بخمسين عمرا لا تشارك فيه"},{"id":"diwan-maarri:1477","bookId":"diwan-maarri","type":"poem","seq":1477,"chapter":"قصائد","title":"لو كان جسمك متروكا بهيئته،","page":"","text":"لو كان جسمك متروكا بهيئته، … بعد التلاف، طمعنا في تلافيه\nكالدن عطل من راح تكون به، … ولم يحطم، فعادت مرة فيه\nلكنه صار أجزاء مقسمة، … ثم استمر هباء في سوافيه"},{"id":"diwan-maarri:1478","bookId":"diwan-maarri","type":"poem","seq":1478,"chapter":"قصائد","title":"الغدر فينا طباع، لا ترى أحدا،","page":"","text":"الغدر فينا طباع، لا ترى أحدا، … وفاؤه لك خير من توافيه\nأين الذي هو صاف لا يقال له: … لو أنه كان، أو لولا كذا فيه؟\nوتلك أوصاف من ليست جبلته … جبلة الإنس، بل كل ينافيه\nولو علمناه سرنا طالبين له، … لعلنا بشفا عمرو نوافيه\nوالدهر يفقد يوما ما به كدر، … ويعوز الخل باديه كخافيه\nوقلما تسعف الدنيا بلا تعب، … والدر يعدم فوق الماء طافيه\nومن أطال خلاجا في مودته، … فهجره لك خير من تلافيه\nورب أسلاف قوم شأنهم خلف، … والشعر يؤتي كثيرا من قوافيه\nنعى الطبيب إلى مضنى، حشاشته، … مهلا، طبيب، فإن الله شافيه\nعجبت للمالك القنطار من ذهب، … يبغي الزيادة، والقيراط كافيه\nوكثرة المال ساقت للفتى أشرا، … كالذيل عثر، عند المشي، ضافيه\nلقد عرفتك عصرا موقدا لهبا، … من الشبيبة، لم تنضب أنافيه\nوالشيخ يحزن من، في الشرخ، يعهده … كأنه الربع هاج الشوق عافيه\nومسكن الروح في الجثمان أسقمه، … وبينها عنه، من سقم، يعافيه\nوما يحس، إذا ما عاد متصلا … بالترب، تسفيه في الهابي سوافيه\nفما يبالي أديم، وهي جانبه؛ … ولا يراع، إذا حدت أشافيه\nوحبذا الأرض قفرا، لا يحل بها … ضد تعاديه، أو خلم تصافيه\nوما حمدت كبيرا في تحدبه؛ … ولا عذلت صغيرا في تجافيه\nجنى أب وضع ابنا للردى غرضا، … إن عق، فهو على جرم يكافيه"},{"id":"diwan-maarri:1479","bookId":"diwan-maarri","type":"poem","seq":1479,"chapter":"قصائد","title":"أكرم بياضك عن خطر يسوده،","page":"","text":"أكرم بياضك عن خطر يسوده، … وازجر يمينك عن شيب تنقيه\nلقيته بجلاء عن منازله، … وليس يحسن هذا من تلقيه\nألا تفكرت، قبل النسل، في زمن … به حللت، فتدري أين تلقيه؟\nترجو له من نعيم الدهر ممتنعا، … وما علمت بأن العيش يشقيه\nشكا الأذى فسهرت الليل، وابتكرت … به الفتاة إلى شمطاء ترقيه\nوأمه تسأل العراف، قاضية … عنه النذور، لعل الله يبقيه\nوأنت أرشد منها حين تحمله … إلى الطبيب، يداويه ويسقيه\nولو رقى الطفل عيسى، أو أعيد له … بقراط، ما كان من موت يوقيه\nوالحي في العمر مثل الغر، يرقأ في … سور العدى، وإلى حتف ترقيه\nدنست عرضك، حتى ما ترى دنسا، … لكن قميصك، للأبصار، تنقيه"},{"id":"diwan-maarri:1480","bookId":"diwan-maarri","type":"poem","seq":1480,"chapter":"قصائد","title":"لا تحلفن على صدق ولا كذب،","page":"","text":"لا تحلفن على صدق ولا كذب، … فإن أبيت فعد الحلف بالله\nفقد أشرت إلى معنى له نبأ، … وافى العقول بإعجاز وإيلاه\nيخاف كل رشيد من عقوبته، … وإن تلفع ثوب الغافل اللاهي"},{"id":"diwan-maarri:1481","bookId":"diwan-maarri","type":"poem","seq":1481,"chapter":"قصائد","title":"وجدت غنائم الإسلام نهبا،","page":"","text":"وجدت غنائم الإسلام نهبا، … لأصحاب المعازف والملاهي\nوكيف يصح إجماع البرايا، … وهم لا يجمعون على الإله؟\nتنازعني إلى الشهوات نفسي، … فلا أنا منجح أبدا ولا هي"},{"id":"diwan-maarri:1482","bookId":"diwan-maarri","type":"poem","seq":1482,"chapter":"قصائد","title":"العقل إن يضعف يكن مع","page":"","text":"العقل إن يضعف يكن مع … هذه الدنيا، كعاشق مومس تغويه\nأو يقو، فهي له كحرة عاقل … حسناء يهواها ولا تهويه"},{"id":"diwan-maarri:1483","bookId":"diwan-maarri","type":"poem","seq":1483,"chapter":"قصائد","title":"عنسي في الدنيا سوى الراهي،","page":"","text":"عنسي في الدنيا سوى الراهي، … طلقتها تطليق إكراه\nوالجد أبراها لمن راضها، … فانهض إلى عنسك إبراه\nوإنما نحن أسارى بها، … وسوف تودي بالأسارى هي"},{"id":"diwan-maarri:1484","bookId":"diwan-maarri","type":"poem","seq":1484,"chapter":"قصائد","title":"بخيفة الله تعبدتنا،","page":"","text":"بخيفة الله تعبدتنا، … وأنت عين الظالم اللاهي\nتأمرنا بالزهد في هذه ال … دنيا، ما همك إلا هي"},{"id":"diwan-maarri:1485","bookId":"diwan-maarri","type":"poem","seq":1485,"chapter":"قصائد","title":"لن تريه، إن كنت لما تريه،","page":"","text":"لن تريه، إن كنت لما تريه، … ثابتا خاتماه في خنصريه\nلم يجد عند أكبريه سموا، … فاعتزى فضله إلى أصغريه\nظل يستخبر النجوم عن الغي … ب، فجاء اليقين من خبريه\nقد مضت عنه الأربعون بلا … حمد، وذاك الأجل من عمريه\nليس من خلة الزمان على … شيء، ولو بات، ثالثا، قمريه\nقد رآه ما بين موت وقتل؛ … هل يجوز النجاء من قدريه؟"},{"id":"diwan-maarri:1486","bookId":"diwan-maarri","type":"poem","seq":1486,"chapter":"قصائد","title":"لا تهاد القضاة كي تظلم الخ","page":"","text":"لا تهاد القضاة كي تظلم الخ … صم، ولا تذكرن ما تهديه\nإن من أقبح المعايب، عارا، … أن يمن الفتى بما يسديه"},{"id":"diwan-maarri:1487","bookId":"diwan-maarri","type":"poem","seq":1487,"chapter":"قصائد","title":"نضحي ونمسي كبني آدم","page":"","text":"نضحي ونمسي كبني آدم … وما على الغبراء إلا سفيه\nفنسأل العالم إنقاذنا … من عالم السوء، الذي نحن فيه"},{"id":"diwan-maarri:1488","bookId":"diwan-maarri","type":"poem","seq":1488,"chapter":"قصائد","title":"لنا خفض المحلة والدنايا،","page":"","text":"لنا خفض المحلة والدنايا، … ولله المكارم والعلو\nإذا كان الهوى، في النفس طبعا، … فليس، بغير ميتتها، سلو\nوإن أهلت ديار من أناس، … فسوف يمسها منهم خلو"},{"id":"diwan-maarri:1489","bookId":"diwan-maarri","type":"poem","seq":1489,"chapter":"قصائد","title":"الخلق من أربع مجمعة:","page":"","text":"الخلق من أربع مجمعة: … نار وماء وتربة وهوا\nإن السهى والسماك ما غفلا … عن ذكر مولاهما، ولا سهوا\nوالنيران المواصلان سنا، … إن نله في أرضنا، فما لهوا\nوالشمس والغيث طاهيان له، … يطعم أهل البلاد ما طهوا"},{"id":"diwan-maarri:1490","bookId":"diwan-maarri","type":"poem","seq":1490,"chapter":"قصائد","title":"العقل يوضح، للنس","page":"","text":"العقل يوضح، للنس … ك، منهجا، فاحذ حذوه\nوليس يظلم قلب، … وفيه للب جذوه\nوفات ركض المنايا … ركض القضيب، وبذوه"},{"id":"diwan-maarri:1491","bookId":"diwan-maarri","type":"poem","seq":1491,"chapter":"قصائد","title":"كأنك بعد خمسين استقلت،","page":"","text":"كأنك بعد خمسين استقلت، … لمولدك، البناء دنا ليهوي\nوإنك، إن تزوج بنت عشر، … لأخيب صفقة من شيخ مهو\nفأزمع من بني الدنيا نفارا، … فإنهم لفي لعب ولهو\nوما أنا يائس من أمر ربي، … على ما كان من عمد وسهو\nوكم من آكل رزقا هنيئا، … وباشر غيره عنتا بطهو"},{"id":"diwan-maarri:1492","bookId":"diwan-maarri","type":"poem","seq":1492,"chapter":"قصائد","title":"لعمرك! ما زوج الفتاة بحازم،","page":"","text":"لعمرك! ما زوج الفتاة بحازم، … إذا ما الندامى، في محلته، غنوا\nأتى بيته بالراح والشرب، لاهيا، … فإما رنوا نحو الظعينة، أو زنوا\nرآهم على ما يكره الناس ربهم، … وعذت به فيما تمنوا وما منوا\nوددت، بعلم الله، أن صحابتي … على كل حال أفردوني، فما ثنوا\nإذا كان سكان البلاد كما هم، … فلا تحفلن إن صغروا اسمك، أو كنوا\nينافس، في الدنيا الخسيسة، جاهل؛ … رويدك يذهب عنك عارض هذا النو\nيسير، على الأرض الرحيبة، أهلها، … ويترك ما شادوا، هناك، وما بنوا"},{"id":"diwan-maarri:1493","bookId":"diwan-maarri","type":"poem","seq":1493,"chapter":"قصائد","title":"تسوقوا بالغنا لربهم،","page":"","text":"تسوقوا بالغنا لربهم، … وأظهروا خيفة له ودعوا\nسعوا لدنياهم بآخرة، … فبئس ما حاولوا غداة سعوا\nوخلفوا العقل من ورائهم، … واستودعوا كل سوءة، فرعوا\nولم يعوا ما يقول واعظهم، … لكن قول المخرصين وعوا\nمثل تيوس المعيز، نازية، … ولم يضاهوا الفحول حين قعوا"},{"id":"diwan-maarri:1494","bookId":"diwan-maarri","type":"poem","seq":1494,"chapter":"قصائد","title":"تدين، مغربي بانتحال،","page":"","text":"تدين، مغربي بانتحال، … وعارض بالتنحل مشرقي\nفصمتا، إن أردتم، أو مقالا، … فما في هذه الدنيا تقي\nنقاء لباسنا فيها كثير، … وليس لأهلها عرض نقي\nوإن رقي الفتى رتب المعالي، … فمثل هبوطه ذاك الرقي\nويحسب بعضنا أن قد أتاه … نعيم، وهو لو يدري شقي\nوأعوزنا بياض العيش فيها، … ولم يعوز بياض مفرقي"},{"id":"diwan-maarri:1495","bookId":"diwan-maarri","type":"poem","seq":1495,"chapter":"قصائد","title":"أرادوا الشر، وانتظروا إماما،","page":"","text":"أرادوا الشر، وانتظروا إماما، … يقوم بطي ما نشر النبي\nفإن يك ما يؤمله رجال، … فقد يبدي لك العجب الخبي\nإذا أهل الديانة لم يصلوا، … فكل هدى لمذهبهم أبي\nوجدت الشرع تخلقه الليالي … كما خلق الرداء الشرعبي\nهي العادات، يجري الشيخ منها … على شيم يعودها الصبي\nوما عندي بما لم يأت علم، … وقد ألوى بأنمله الربي\nمضى ملك ليخلف، بعد، ملك، … حبي زال ثم نمى حبي\nوقد يحمي الأرانب، من أسود … ضراغمة، جراء ثعلبي\nوأشوى الحق رام مشرقي، … ولم يرزقه آخر مغربي\nفذا عمر يقول، وذا علي، … كلا الرجلين في الدعوى غبي\nوخير للفؤاد من التغاضي، … على التثريب، نصل يثربي\nفإن يلحق بك البكري غدرا، … فلم يتعر منه التغلبي\nأذيت من الذين تعد أهلا، … وجنبك الأذاة الأجنبي\nوسكن الأرض كلهم ذميم، … صريحهم المهذب والسبي\nفإن سموا بأرقم، أو بليث، … فذئبي أتاك وعقربي"},{"id":"diwan-maarri:1496","bookId":"diwan-maarri","type":"poem","seq":1496,"chapter":"قصائد","title":"صفري من بعده رجبي،","page":"","text":"صفري من بعده رجبي، … فانظرن أين جاد ذاك الحبي\nزعمت، أن نارها ما خبت، فا … رس، والدهر فيه معنى خبي\nنام عنا ربينا، وهلاك ال … ركب يخشى، إن نام عنه الربي\nعلم الكائنات، في كل وجه، … أول عنده السماك صبي\nخالق النيران، ما يتغابى العب … د، لكنه ضعيف غبي\nأيها الغر، إن خصصت بعقل، … فاسألنه، فكل عقل نبي\nحلبوا درة الكؤوس، وألغوا … ما رواه الكرخي والحلبي\nوشرابي ماء قراح، وحسبي، … لا يهنأ شرابك العنبي\nوكفاني، مما يعب، لجين … ي، إذا عب صرفك الذهبي\nفتنتك السبيتان، فبيضا … ء وحمراء، من كروم سبي\nجلبت هذه بسمر، وهاتي … ك بصفر، لها أب لهبي\nقدر غالب، وأمر قديم، … يتضاهى ذليله والأبي\nواختلاف من عنصر ذي اتفاق، … وتساوى الزنجي والعربي\nغركم بالخلاف أصفر قيس، … برهة، ثم أصفر ثعلبي"},{"id":"diwan-maarri:1497","bookId":"diwan-maarri","type":"poem","seq":1497,"chapter":"قصائد","title":"لعمري! لقد بعنا الفناء نفوسنا،","page":"","text":"لعمري! لقد بعنا الفناء نفوسنا، … بلا عوض عند البياع ولا ثنيا\nولو بين دنيانا الدنية خيرت، … وبين سواها، ما أرادت سوى الدنيا"},{"id":"diwan-maarri:1498","bookId":"diwan-maarri","type":"poem","seq":1498,"chapter":"قصائد","title":"ساء بريا، من البرايا،","page":"","text":"ساء بريا، من البرايا، … من لبس الدين سابريا\nإن كسرتني يد المنايا، … فما الأطباء جابريا\nأمرت بالغدر أم دفر، … ولم أطع فيك آمريا\nعبرت، في عيشة، مضيقا، … فليوسع الحفر قابريا\nمفازة ما الضباب فيها، … ولا عقيل بخافريا\nما أحوجتني إلى ورود، … لما سقتني الخمار ريا\nقد خبر الله من ضميري، … ما لم يكن عند خابريا\nولم يطل سامري حديثي، … بل عشت في الدهر سامريا\nلو علم العاذلون سري، … لأصبح القوم عاذريا\nيا أمتي اتقوا شرورا … مني، وبيتوا محاذريا\nقامرة كلنا الليالي، … فما أبالي بقامريا\nوارتني الأرض، فاهجروني، … لا يرهب العتب هاجريا\nهل كره القرب من عظامي، … أعظم قوم مجاوريا\nما بهشوا بالسلام نحوي، … ولا أراهم محاوريا\nغنيت عن زائر ملم، … فليشغل الخير زائريا\nأزيل الملك آل كسرى، … وصار بالشام عامريا؟"},{"id":"diwan-maarri:1499","bookId":"diwan-maarri","type":"poem","seq":1499,"chapter":"قصائد","title":"قد خف جرمي، وصار جرمي","page":"","text":"قد خف جرمي، وصار جرمي … أثقل من هضبة عليا\nنفسي أولى بما عناها، … من هؤلاء وهؤليا\nلولا تقضي الشباب عني، … عصيت في الغي عاذليا\nفهل تراني أكون برا، … لو رد عصر الصبا إليا؟\nإياك والخود أن تخلى، … ملبسة جيدها حليا\nكأنها ظبية خذول، … مرضعة، بالضحى، طليا\nيا هند كوني مع الهوافي؛ … وجانبي الخفض يا عليا"},{"id":"diwan-maarri:1500","bookId":"diwan-maarri","type":"poem","seq":1500,"chapter":"قصائد","title":"لقد أمنتني الأدماء، أضحت","page":"","text":"لقد أمنتني الأدماء، أضحت … تراعي في مراتعها طليا\nبعدت من الأصادق والأعادي، … فما أنا من ألاك ولا أليا\nدعا لي، بالحياة، أخو وداد، … رويدك، إنما تدعو عليا\nوما كان البقاء لي اختيارا، … لو ان الأمر مردود إليا"},{"id":"diwan-maarri:1501","bookId":"diwan-maarri","type":"poem","seq":1501,"chapter":"قصائد","title":"تروم شفاء ما الأقوام فيه،","page":"","text":"تروم شفاء ما الأقوام فيه، … رويدك إن داء القوم أعيا\nفحاذر عقربا غشيتك لسبا، … وأم أراقم وافتك سعيا\nوألقت هذه الأيام علما … إليك، فلم تصادف منك وعيا\nودينك ما علي الحكم فيه، … فأبغي للذي أخفيت بغيا\nإذا الإنسان كف الشر عني، … فسقيا، في الحياة، له ورعيا\nويدرس، إن أراد، كتاب موسى، … ويضمر، إن أحب ولاء شعيا"},{"id":"diwan-maarri:1502","bookId":"diwan-maarri","type":"poem","seq":1502,"chapter":"قصائد","title":"وفرت العارضين، ولم يعارض","page":"","text":"وفرت العارضين، ولم يعارض … مشيبي، إذ تناثر، ملقطايا\nوإن البيض مثل السود عندي، … فكيف يخص تلك مسلطايا؟\nمطاي عليه للأيام عبء، … كأني، للأذاة، من المطايا\nمحلي، إن جلاني عنك خطب، … فمن خطإي تراح ومن خطايا\nوما شعر برأسك في عداد، … بأكثر من ذنوبك والخطايا\nعطايا الناس ممسكة، فحاول … ثواب مليكنا الجزل العطايا\nكفيتك أن تراب، الدهر، مني، … ولم تكفف بزاتك عن قطايا"},{"id":"diwan-maarri:1503","bookId":"diwan-maarri","type":"poem","seq":1503,"chapter":"قصائد","title":"كل امرء يضحي مريا،","page":"","text":"كل امرء يضحي مريا، … والدهر لا يبقي سريا\nفترو من هذي الحيا … ة، لكي تموت النفس ريا\nما للثريا قيمة، … عند الذي خلق الثريا\nصار الأمير أبا مري، … ثم أورثها مريا\nوالحي، للنكبات، يس … تقري، ويرجع للقريا\nما عريت مما يخا … ف عمايتان، ولا عريا"},{"id":"diwan-maarri:1504","bookId":"diwan-maarri","type":"poem","seq":1504,"chapter":"قصائد","title":"أصبحت ألحى خلتيا،","page":"","text":"أصبحت ألحى خلتيا، … هاتيك أبغضها وتيا\nودعيت شيخا، بعدما … سميت، في زمن، فتيا\nوكفيت صحبي إلتيا، … بعد اللتيا واللتيا\nسقيا لأيام الشباب، … وما حسرت مطيتيا\nأيام آمل أن أمس … الفرقدين براحتيا\nوأفيض إحساني على … جاري، ثم، وجارتيا\nفالآن تعجز همتي … عما ينال بخطوتيا\nأوصى ابنتيه لبيد ال … ماضي، ولا أوصي ابنتيا\nلست المفاخر، في الرجا … ل، بعمتي وخالتيا\nلكن أقر بأنني … ضرع، أمارس دارتيا\nوالله يرحمني، إذا … أودعت أضيق ساحتيا\nلا تجعلن حالي، إذا … غيبت أيأس حالتيا"},{"id":"diwan-maarri:1505","bookId":"diwan-maarri","type":"poem","seq":1505,"chapter":"قصائد","title":"ما بالها ناوية شقة","page":"","text":"ما بالها ناوية شقة … تودي بشخص الناقة الناويه؟\nلم تأو للعيس، ولا بد من … قبر إليه أوت الآويه\nوتقدم الأرض نفوس أتت … مخلوقة من أنفس تاويه\nوالدهر كالحيوت والحوت في … إهلاكه، ما حوت الحاويه\nإن تعمر الدنيا، فلا بد من … يوم ردى يتركها خاويه\nفاهرب من الإنس إلى الوحش كي … تسكن في الدوية الداويه\nإن يسمعوا شرا توافوا له … حفظا، ومثل الشاعر الراويه\nما أنفع السيف لمن شامه … أخضر، ما روضته ذاويه\nذبابه إن يشد يحدث له … جد يوازي لعب الغاويه\nيقتسر الدنيا لأخلافه، … محتلبا أخلافها الصاويه\nألوى نبات الأرض، وهو الذي … لم يلو بل ألوت به اللاويه\nهاوية نفسك ما ساءها، … فلتخش أن تلقى إلى الهاويه\nمن اتقى الله، فأسد الشرى، … لديه، مثل الأكلب العاويه"},{"id":"diwan-maarri:1506","bookId":"diwan-maarri","type":"poem","seq":1506,"chapter":"قصائد","title":"نحن شئنا، فلم يكن ما أردنا؛","page":"","text":"نحن شئنا، فلم يكن ما أردنا؛ … وتمت لله فينا المشيه\nوثريا النجوم تلقى حماما، … كالثريا، في رهطها، القرشيه\nقد طربنا إلى المهارى تبارى … بالأصاحيب، غدوة وعشيه\nملأتها البياض سحم من الدجن … وبهمى غضيضة حبشيه"},{"id":"diwan-maarri:1507","bookId":"diwan-maarri","type":"poem","seq":1507,"chapter":"قصائد","title":"إرمنا يا ظلام في كل فج،","page":"","text":"إرمنا يا ظلام في كل فج، … فالمنى لم تزل تجر المنايا\nوحنى بائس، على القرب، جيدا … لوداع، والعيس مثل الحنايا\nودنا يا عذول أنا سلمنا … من هوانا، ولم ندان الدنايا\nإن جهلا سلمي لآل سليمى، … وثنائي على عذاب الثنايا"},{"id":"diwan-maarri:1508","bookId":"diwan-maarri","type":"poem","seq":1508,"chapter":"قصائد","title":"ليس يبقى الضرب الطويل على الدهر،","page":"","text":"ليس يبقى الضرب الطويل على الدهر، … ولا ذو العبالة الدرحايه\nيا أبا القاسم، الوزير، ترحلت … وخلفتني ثفال رحايه\nوتركت الكتب الثمينة للنا … س، وما رحت عنهم بسحايه\nليتني كنت، قبل أن تشرب المو … ت أصيلا، شربته بضحايه\nإن نحتك المنون قبلي، فإني … منتحاها، وإنها منتحايه\nأم دفر تقول، بعدك، للذا … ئق: لا طعم لي، فأين فحايه؟\nإن يخط الذنب اليسير حفيظا … ك، فكم من فضيلة محايه"},{"id":"diwan-maarri:1509","bookId":"diwan-maarri","type":"poem","seq":1509,"chapter":"قصائد","title":"مجوسية وحنيفية،","page":"","text":"مجوسية وحنيفية، … ونصرانة ويهوديه\nنفوس تخالف أديانها، … وليست من الموت بمفديه\nتراقب مهديا أن يقوم، … فتلفى إلى الحق مهديه\nفيا سعد! كم خرجت ظبية … ترود بخضراء سعديه\nفتضحي من المرد مردية؛ … وتمسي من الردى مرديه\nلقد كان أبدى إليها الزما … ن، ثم هي الآن مبديه\nويا هند! ما عصمت أهلها … قواضب، في الضرب، هنديه\nولا ورد غاب ، له حلة … من الدم، في الغيل، ورديه\nتشبه بعض ببعض، فما … تزال الشمائل فرديه\nقد امتزج العالم الآدمي، … فغورية مع نجديه\nوأم النميري تركية؛ … وأم العقيلي صغديه\nوزوج الكلابية الكاسكي؛ … وعرس الكلابي كرديه"},{"id":"diwan-maarri:1510","bookId":"diwan-maarri","type":"poem","seq":1510,"chapter":"قصائد","title":"ألم تر أنني حي كميت،","page":"","text":"ألم تر أنني حي كميت، … أداري الوقت، أو ميت كحي\nأحاذر عالمي وأخاف مني، … وألحى الناس، بله بني لحي\nوهم لي مثل ما كانت قديما، … لقيس ابن الخطيم، بنو دحي"},{"id":"diwan-maarri:1511","bookId":"diwan-maarri","type":"poem","seq":1511,"chapter":"قصائد","title":"أليس أبوكم آدم إن عزيتم","page":"","text":"أليس أبوكم آدم إن عزيتم … يكون سليلا للتراب إذا عزي؟\nيود الفتى لو عاش، آخر دهره، … سليما مؤتى، لا أميت ولا رزي\nأنام، لعمري، ليس فيه موفق … لرشد ولا يحظى بخير إذا جزي\nوباز يغادي الطير مهتضما لها، … فهل يرتجي النصف الضعيف إذا بزي\nوجدت سفيه القوم من سوء رأيه، … إذا قيل: خف من قادر فوقنا، هزي\nوردنا إلى الدنيا بإذن مليكنا، … لمغزى، ولسنا عالمين بما غزي\nذوو النسك خير الناس في كل موطن، … وزيهم، بين المعاشر، خير زي\nوهل ينفع الوشي السحيب مضللا، … وإن ذكرت، في القوم، شيمته خزي\nومن عجب دعواك علما وحكمة، … وعلمك شيء قيل بالظن، أو حزي\nوجئت بنمي إلى متعصب، … فناداك دينار بكفك هبرزي"},{"id":"diwan-maarri:1512","bookId":"diwan-maarri","type":"poem","seq":1512,"chapter":"قصائد","title":"تولي يا خبيثة، لا هلمي،","page":"","text":"تولي يا خبيثة، لا هلمي، … أقول، إذا نأيت، ولا تعالي\nوإما كنت يا نوبي ولاء، … فإني لا أحاذر أن توالي\nتعالى القوم في طلب المعالي … فيا قمرا بذي كلإ تعالي\nولو أوتيت، في الأيام، لبا … تقارضت الوداد ولم تقالي"},{"id":"diwan-maarri:1513","bookId":"diwan-maarri","type":"poem","seq":1513,"chapter":"قصائد","title":"الدهر لا تأمنه لقوة،","page":"","text":"الدهر لا تأمنه لقوة، … تزق أفراخا لها بالسلي\nتضحي الثعالي خائفات لها، … وتذعر الخشف وأم الطلي\nإن يرحل الناس ولم أرتحل، … فعن قضاء لم يفوض إلي\nخلفت من بعد رجال مضوا، … وذاك شر لي، وشر علي"}]};